    public sealed class KeystoneArcEvent
    {
        public string Id;
        public string Symbol;
        public string SetupClass;       // BH, FVG, or DT
        // LONG and SHORT are historical setup directions, not an order instruction.
        public string Direction = "LONG";
        public string StrengthTag;      // BASE, WICK, AGGR
        public DateTime ReferenceTime;
        public DateTime TriggerTime;
        public DateTime EntryTime;
        public double Entry;
        public double Stop;
        public double Target;
        // Prop scenarios use whole micros; a personal CFD/spot index model may use fractional
        // lots. The value is a historical sizing input only and never reaches a broker.
        public double Quantity;
        public double StopDistance;
        public string RiskModel;
        public DateTime ExitTime;
        public double ExitPrice = double.NaN;
        public string Outcome;          // WIN, LOSS, SESSION EXIT, OPEN
        public double GrossPnl;
        // Asian cycle only: combined MNQ + MGC cycle P/L (realized + open legs at the 1M close)
        // at the minute this leg closed, and the lowest combined value the night had reached by then.
        public int AsianLegNumber;
        public double AsianCyclePnlAtExit = double.NaN;
        public double AsianCycleWorstAtExit = double.NaN;
        // Optional evaluation-stage result for the same historical path.  The standard Outcome
        // remains the funded/base parameter result; allocation selects this resolved result only
        // while the assigned virtual slot is still in its evaluation stage.
        public string EvaluationOutcome;
        public DateTime EvaluationExitTime;
        public double EvaluationExitPrice = double.NaN;
        public double EvaluationGrossPnl;
        public double EvaluationTarget = double.NaN;
        public double EvaluationStop = double.NaN;
        // Auditable path statistics from the exact 1-minute series when it is validated.
        // If the run falls back to setup bars, they remain conservative bar-range statistics.
        public double PeakAfterEntry = double.NaN;
        public double TroughAfterEntry = double.NaN;
        public int TargetTouched;
        public int StopTouched;
        public int SessionOrder;
        public double FvgLower = double.NaN;
        public double FvgUpper = double.NaN;
        public DateTime FvgFormedTime = DateTime.MinValue;
        // FVG retest strategy audit: which visit of the box produced the entry, the aggression
        // before the box (red candles in a row / drop in price), and the box size.
        public int FvgVisit;
        public int FvgRedRun;
        public double FvgDrop;
        public double FvgGap;
        // Setup quality (walk-forward: learned only from setups that finished before this entry).
        // Tier A / B / C; "N" = not enough earlier setups yet. Features are known at entry time.
        public double QualityScore = double.NaN;
        public string QualityTier = string.Empty;
        public double FeatureAtr, FeatureDipPercent, FeatureGreenBody;
        // GOLDEN SETUP chart labels: the start (time + price), the push-down low and the pattern's first candle.
        public DateTime GoldenStartTime = DateTime.MinValue, GoldenLowTime = DateTime.MinValue, GoldenPatternTime = DateTime.MinValue;
        public double GoldenStartPrice = double.NaN, GoldenLowPrice = double.NaN;
        // GOLDEN study: per stop level (KeystoneGoldenStudy stop levels + the pattern stop last), the best
        // run up (points above the entry) before that stop was hit, and whether it was hit before the data ended.
        public double[] GoldenRunBeforeStop;
        public bool[] GoldenStopHit;
        public string GoldenSkipReason = string.Empty;
        // MOVE STUDY (GOLDEN): from the entry to the session close, no target / stop — how far price went for us (MFE),
        // against us (MAE), against us before the best point, where it closed, and for each move level the worst point
        // against us before that level was first reached (NaN = never reached).
        public double MoveMfe = double.NaN, MoveMae = double.NaN, MoveMaeBeforeMfe = double.NaN, MoveClose = double.NaN; public int MoveMfeMinutes;
        public double[] MoveHeat;
        public string AssignedVirtualAccount;
        public string SkipReason;
        public string ConfigurationKey;
        // Internal ACCEPTED state means detector-qualified and eligible for a virtual pool.
        // Every detector-qualified event begins eligible for the virtual pool. The review screen
        // is optional and can exclude a specific row; it is not a second approval requirement.
        public string ReviewState = "ACCEPTED"; // ACCEPTED (eligible), REJECTED, FLAGGED
        public string ReviewNote = string.Empty;
        // Field-by-field copy (values and strings only) for running the same ledger through several pools.
        public KeystoneArcEvent CopyForPool() { var c = (KeystoneArcEvent)MemberwiseClone(); c.AssignedVirtualAccount = null; c.SkipReason = null; return c; }
    }

    // One bullish FVG box and what happened to it (FVG retest strategy). Chart + audit data.
    public sealed class KeystoneArcFvgZone
    {
        public string Symbol;
        public double Lower, Upper;               // candle 1 high → candle 3 low
        public DateTime FormedTime;               // candle 3 time
        public DateTime EndTime = DateTime.MaxValue; // when the box stopped being tradable
        public string EndReason = "OPEN";         // CLOSED BELOW, RUN AWAY, USED, AGE, SESSION END, OPEN
        public int Visits, Entries;
        public int RedRun; public double Drop; public bool Aggressive;
        public double FormationLow;               // lowest low of the 3 candles that made the gap
        public int Stacked = 1;                   // boxes merged into this zone (FVGs formed in a row)
        public List<double[]> Parts = new List<double[]>();   // the individual boxes [lower, upper]
        public List<string> Log = new List<string>();          // why an entry did / did not happen, candle by candle
        public void Note(DateTime t, string text) { if (Log.Count < 60) Log.Add(t.ToString("HH:mm") + "  " + text); }
        public double Height { get { return Upper - Lower; } }
    }

    // One row is an auditable scenario, never a trading instruction.  It keeps setup discovery
    // separate from virtual-account allocation and the optional illustrative lifecycle.
    public sealed class KeystoneArcComparisonRow
    {
        public string Symbol;
        public int SetupMinutes;
        public int PoolSize;
        public string StartMode;
        public string DataMethod;
        public int Setups;
        public int Wins;
        public int Losses;
        public int SessionExits;
        public double AllOutcomeGross;
        public int Assigned;
        public int Skipped;
        public double AssignedGross;
        public int EvaluationPassed;
        public int Funded;
        public int Payouts;
        public double PayoutCash;
        public double EvaluationCost;
        public string Note;

        public override string ToString()
        {
            int resolved = Wins + Losses;
            string winRate = resolved == 0 ? "n/a" : (Wins * 100.0 / resolved).ToString("0.0", CultureInfo.InvariantCulture) + "%";
            if (string.Equals(StartMode, "LIVE ACCOUNT", StringComparison.OrdinalIgnoreCase))
                return Symbol.PadRight(4) + " | " + SetupMinutes.ToString(CultureInfo.InvariantCulture).PadLeft(3) + "M | setups " + Setups.ToString(CultureInfo.InvariantCulture).PadLeft(3) +
                    " | W/L " + Wins.ToString(CultureInfo.InvariantCulture).PadLeft(3) + "/" + Losses.ToString(CultureInfo.InvariantCulture).PadLeft(3) +
                    " | " + winRate.PadLeft(6) + " | final " + AssignedGross.ToString("C0", CultureInfo.InvariantCulture).PadLeft(10) + " | ONE LIVE ACCOUNT";
            return Symbol.PadRight(4) + " | " + SetupMinutes.ToString(CultureInfo.InvariantCulture).PadLeft(3) + "M | setups " + Setups.ToString(CultureInfo.InvariantCulture).PadLeft(3) +
                " | W/L " + Wins.ToString(CultureInfo.InvariantCulture).PadLeft(3) + "/" + Losses.ToString(CultureInfo.InvariantCulture).PadLeft(3) +
                " | " + winRate.PadLeft(6) + " | gross " + AllOutcomeGross.ToString("C0", CultureInfo.InvariantCulture).PadLeft(10) +
                " | pool " + PoolSize.ToString(CultureInfo.InvariantCulture).PadLeft(2) + " | " + StartMode;
        }
    }

