    // ---- MOVE STUDY (build 10-03e) -----------------------------------------------------------------
    // No fixed target or stop: every detected entry is followed to the session close and measured — how far price went
    // for us, against us, against us before the best point, where it closed. Compared by entry set × instrument × year,
    // against a no-setup baseline (buy at the start time every day). The target / stop in points (and dollars) are then
    // chosen FROM those movements, per year and overall; the best sets are explained by their features (why).
    // ---- ROTATION TESTER (build 10-03f) -------------------------------------------------------------
    // The live rotation tool replayed on history: MNQ and MGC opened together (BUY BUY / SELL SELL / random / a fast
    // confirmation), one combined target and stop per rotation, a 3-tier profit lock, a pause, then the next account takes
    // the next rotation. Each account has a daily target, a daily stop and a two-loss lock, and is a prop evaluation
    // (target, trailing EOD drawdown that stops at +100, consistency). Real 1-minute bars, both instruments on the same
    // minute; inside a minute the worst combined price (both at their adverse extremes) counts before the best.
    public sealed class KeystoneRotationConfig
    {
        public int StartHhmm = 930, EndHhmm = 1555, MnqQty = 20, MgcQty = 20, PauseMinutes = 1, Accounts = 20, MaxLossesPerDay = 2, Seed = 7;
        public string Direction = "BUY";           // BUY • SELL • RANDOM • FOLLOW5 (both instruments' last 5 min agree → that way) • FADE5 (against it)
        public double RotationTarget = 1000, RotationStop = 500, DailyTarget = 2000, DailyStop = 2000;
        public string LockTiers = "500:150,700:350,900:750";   // peak trigger : locked profit
        public double CommissionPerSide = 0.62; public int SlippageTicks = 1;
        public KeystonePropRules Rules = new KeystonePropRules();
        public KeystoneRotationConfig Copy() { var c = (KeystoneRotationConfig)MemberwiseClone(); c.Rules = Rules.Copy(); return c; }
        public List<Tuple<double, double>> Tiers()
        {
            var list = new List<Tuple<double, double>>();
            foreach (var part in (LockTiers ?? "").Split(new[] { ',', ';', ' ' }, StringSplitOptions.RemoveEmptyEntries))
            {
                var kv = part.Split(':'); double a, b;
                if (kv.Length == 2 && double.TryParse(kv[0], NumberStyles.Any, CultureInfo.InvariantCulture, out a) && double.TryParse(kv[1], NumberStyles.Any, CultureInfo.InvariantCulture, out b) && a > 0 && b < a) list.Add(Tuple.Create(a, b));
            }
            return list.OrderBy(t => t.Item1).ToList();
        }
        public string Describe()
        {
            Func<double, string> m = v => "$" + v.ToString("N0", CultureInfo.InvariantCulture);
            return KeystoneRotation.DirectionName(Direction) + " • " + MnqQty + " MNQ + " + MgcQty + " MGC • rotation +" + m(RotationTarget) + " / −" + m(RotationStop) + (Tiers().Count > 0 ? " • locks " + LockTiers : "") + " • pause " + PauseMinutes + " min • " + KeystoneBracket.Hm(StartHhmm) + "–" + KeystoneBracket.Hm(EndHhmm) + " • " + Accounts + " accounts • day +" + m(DailyTarget) + " / −" + m(DailyStop) + (MaxLossesPerDay > 0 ? " / " + MaxLossesPerDay + " losses" : "");
        }
    }

    public sealed class KeystoneRotationTrade { public DateTime Entry, Exit; public int Account, Dir; public double Pnl, Peak; public string Reason = string.Empty; }

    public sealed class KeystoneRotationDay { public DateTime Day; public int Rotations, Wins, Losses, Passed, Blown, Bought; public double Net, Costs; }

    public sealed class KeystoneRotationResult
    {
        public KeystoneRotationConfig Config; public List<KeystoneRotationDay> Days = new List<KeystoneRotationDay>(); public List<KeystoneRotationTrade> Trades = new List<KeystoneRotationTrade>();
        public int Bought, Passed, Blown; public double Spent, Net, Costs; public List<int> DaysToPass = new List<int>();
        public string Label = string.Empty;
        public int RotCount, WinCount; public double PnlSum;   // kept when the trade list is dropped (optimizer)
        public int Rotations { get { return RotCount; } }
        public double WinPct { get { return RotCount == 0 ? 0 : 100.0 * WinCount / RotCount; } }
        public double PerRotation { get { return RotCount == 0 ? 0 : PnlSum / RotCount; } }
        public double CostPerPass { get { return Passed == 0 ? double.PositiveInfinity : Spent / Passed; } }
        public double PassRate { get { return Bought == 0 ? 0 : 100.0 * Passed / Bought; } }
        public Dictionary<int, double[]> ByYear = new Dictionary<int, double[]>();   // year → { bought, passed, spent, net, rotations }
    }

    public static class KeystoneRotation
    {
        public static readonly string[] Directions = { "BUY", "SELL", "RANDOM", "FOLLOW5", "FADE5" };
        public static string DirectionName(string d) { switch (d) { case "BUY": return "BUY BUY"; case "SELL": return "SELL SELL"; case "RANDOM": return "RANDOM BUY BUY / SELL SELL"; case "FOLLOW5": return "CONFIRM: BOTH UP 5 MIN → BUY, BOTH DOWN → SELL"; case "FADE5": return "CONFIRM: BOTH UP 5 MIN → SELL, BOTH DOWN → BUY"; } return d; }

        sealed class Acct { public double Bal, Hwm, Best, DayPnl; public int DayLosses, Days, Id; public bool Locked, Dead, Passed, TradedToday; public DateTime Started; }

        static double Threshold(Acct a, KeystonePropRules r) { return r.Drawdown == "STATIC" ? -r.MaxDrawdown : Math.Min(a.Hwm - r.MaxDrawdown, r.LockAt); }

        public static KeystoneRotationResult Run(List<KeystoneHelixMinute> minutes, KeystoneRotationConfig c)
        {
            var res = new KeystoneRotationResult { Config = c }; var r = c.Rules; var rng = new Random(c.Seed); var tiers = c.Tiers();
            double km = 2.0 * c.MnqQty, kg = 10.0 * c.MgcQty;
            double cost = 2 * c.CommissionPerSide * (c.MnqQty + c.MgcQty), slip = c.SlippageTicks * (0.25 * km + 0.1 * kg);
            int sm = c.StartHhmm / 100 * 60 + c.StartHhmm % 100, em = c.EndHhmm / 100 * 60 + c.EndHhmm % 100;
            var accts = new List<Acct>(); int nextId = 1;
            Func<DateTime, Acct> buy = day => { var a = new Acct { Id = nextId++, Started = day }; res.Bought++; res.Spent += r.EvalCost; return a; };
            int turn = 0;
            foreach (var g in minutes.Where(x => x.HasMnq && x.HasMgc).GroupBy(x => x.Time.Date).OrderBy(x => x.Key))
            {
                var day = new KeystoneRotationDay { Day = g.Key }; int boughtBefore = res.Bought;
                // replace dead or passed accounts, keep the pool at its size
                for (int i = accts.Count - 1; i >= 0; i--) if (accts[i].Dead || accts[i].Passed) accts.RemoveAt(i);
                while (accts.Count < Math.Max(1, c.Accounts)) accts.Add(buy(g.Key));
                foreach (var a in accts) { a.DayPnl = 0; a.DayLosses = 0; a.Locked = false; a.TradedToday = false; }
                var bars = g.Where(x => { int m = x.Time.Hour * 60 + x.Time.Minute; return m > sm && m <= em; }).OrderBy(x => x.Time).ToList();
                var all = g.OrderBy(x => x.Time).ToList(); var at = new Dictionary<DateTime, int>(); for (int q = 0; q < all.Count; q++) at[all[q].Time] = q;
                int i0 = 0; DateTime nextAllowed = DateTime.MinValue;
                while (i0 < bars.Count)
                {
                    var b0 = bars[i0];
                    if (b0.Time < nextAllowed) { i0++; continue; }
                    // next account in turn that can still trade today
                    Acct acct = null; for (int k = 0; k < accts.Count; k++) { var a = accts[(turn + k) % accts.Count]; if (!a.Locked && !a.Dead && !a.Passed) { acct = a; turn = (turn + k + 1) % accts.Count; break; } }
                    if (acct == null) break;
                    // direction
                    int dir = 1;
                    if (c.Direction == "SELL") dir = -1; else if (c.Direction == "RANDOM") dir = rng.NextDouble() < 0.5 ? 1 : -1;
                    else if (c.Direction == "FOLLOW5" || c.Direction == "FADE5")
                    {
                        int j; if (!at.TryGetValue(b0.Time, out j) || j < 5) { i0++; continue; }
                        double dm = all[j - 1].MnqC - all[j - 5].MnqO, dg = all[j - 1].MgcC - all[j - 5].MgcO;
                        if (Math.Sign(dm) == 0 || Math.Sign(dm) != Math.Sign(dg)) { i0++; continue; }   // no agreement → wait a minute
                        dir = Math.Sign(dm) * (c.Direction == "FADE5" ? -1 : 1);
                    }
                    double eM = b0.MnqO, eG = b0.MgcO;
                    Func<double, double, double> val = (pm, pg) => dir * ((pm - eM) * km + (pg - eG) * kg);
                    // the daily target is net of costs: what is left of it plus this rotation's commission
                    double target = Math.Min(c.RotationTarget, c.DailyTarget > 0 ? c.DailyTarget - acct.DayPnl + cost : double.MaxValue);
                    if (target <= 2 * cost) { acct.Locked = true; continue; }   // nothing worth a rotation left today
                    double stop = Math.Min(c.RotationStop, c.DailyStop > 0 ? c.DailyStop + acct.DayPnl : double.MaxValue);
                    double room = acct.Bal - Threshold(acct, r) - cost; stop = Math.Min(stop, Math.Max(1, room));
                    double peak = 0, floor = -stop, pnl = 0; string reason = null; int i = i0; DateTime exitT = b0.Time;
                    for (; i < bars.Count; i++)
                    {
                        var b = bars[i];
                        double worst = dir > 0 ? val(b.MnqL, b.MgcL) : val(b.MnqH, b.MgcH), best = dir > 0 ? val(b.MnqH, b.MgcH) : val(b.MnqL, b.MgcL), close = val(b.MnqC, b.MgcC);
                        if (worst <= floor + 1e-9) { pnl = floor - slip; reason = floor > -stop + 1e-9 ? "LOCK" : "STOP"; exitT = b.Time; break; }
                        peak = Math.Max(peak, best);
                        foreach (var t in tiers) if (peak >= t.Item1 - 1e-9) floor = Math.Max(floor, t.Item2);
                        if (best >= target - 1e-9) { pnl = target; reason = "TARGET"; exitT = b.Time; break; }
                        if (close <= floor + 1e-9) { pnl = floor - slip; reason = "LOCK"; exitT = b.Time; break; }
                        if (i == bars.Count - 1) { pnl = close - slip; reason = "SESSION END"; exitT = b.Time; break; }
                    }
                    if (reason == null) break;
                    pnl -= cost; res.Costs += cost + (reason == "TARGET" ? 0 : slip); day.Costs += cost;
                    res.Trades.Add(new KeystoneRotationTrade { Entry = b0.Time, Exit = exitT, Account = acct.Id, Dir = dir, Pnl = pnl, Peak = peak, Reason = reason });
                    day.Rotations++; if (pnl > 0) day.Wins++; else { day.Losses++; acct.DayLosses++; }
                    acct.DayPnl += pnl; acct.Bal += pnl; acct.TradedToday = true; day.Net += pnl;
                    if (acct.Bal <= Threshold(acct, r) + 1e-6) { acct.Dead = true; res.Blown++; day.Blown++; }
                    if ((c.DailyTarget > 0 && acct.DayPnl >= c.DailyTarget - 2 * cost - 1e-6) || (c.DailyStop > 0 && acct.DayPnl <= -c.DailyStop + 1e-6) || (c.MaxLossesPerDay > 0 && acct.DayLosses >= c.MaxLossesPerDay)) acct.Locked = true;
                    nextAllowed = exitT.AddMinutes(Math.Max(1, c.PauseMinutes));
                    i0 = i + 1;
                }
                // end of day: trailing floor, pass check
                foreach (var a in accts.Where(x => x.TradedToday && !x.Dead))
                {
                    a.Days++; a.Best = Math.Max(a.Best, a.DayPnl); a.Hwm = Math.Max(a.Hwm, a.Bal);
                    bool consistent = r.Consistency <= 0 || a.Best <= r.Consistency / 100.0 * a.Bal + 1e-9;
                    if (a.Bal >= r.Target && a.Days >= Math.Max(1, r.MinDays) && consistent) { a.Passed = true; res.Passed++; day.Passed++; res.DaysToPass.Add(a.Days); }
                }
                day.Bought = res.Bought - boughtBefore; res.Days.Add(day);
                double[] y; if (!res.ByYear.TryGetValue(g.Key.Year, out y)) { y = new double[5]; res.ByYear[g.Key.Year] = y; }
                y[0] += day.Bought; y[1] += day.Passed; y[2] += day.Bought * r.EvalCost; y[3] += day.Net; y[4] += day.Rotations;
            }
            res.Net = res.Trades.Sum(t => t.Pnl); res.RotCount = res.Trades.Count; res.WinCount = res.Trades.Count(t => t.Pnl > 0); res.PnlSum = res.Net;
            res.Label = c.Describe();
            return res;
        }

        // Search: direction × window × contracts × target / stop × pause, ranked by the cost of one passed evaluation (all CPU cores).
        public static List<KeystoneRotationResult> Optimize(List<KeystoneHelixMinute> minutes, KeystoneRotationConfig basis, Action<string> progress) { return Optimize(minutes, basis, progress, null); }
        public static List<KeystoneRotationResult> Optimize(List<KeystoneHelixMinute> minutes, KeystoneRotationConfig basis, Action<string> progress, Func<bool> cancelled)
        {
            var configs = new List<KeystoneRotationConfig>();
            var windows = new[] { Tuple.Create(930, 1100), Tuple.Create(930, 1555), Tuple.Create(1000, 1200), Tuple.Create(1300, 1555), Tuple.Create(800, 930) };
            foreach (string d in Directions)
                foreach (var win in windows)
                    foreach (int q in new[] { 5, 10, 20 })
                        foreach (double tp in new[] { 500.0, 1000, 1500 })
                            foreach (double sl in new[] { 250.0, 500, 1000 })
                                foreach (int pause in new[] { 1, 5, 15 })
                                {
                                    var c = basis.Copy(); c.Direction = d; c.StartHhmm = win.Item1; c.EndHhmm = win.Item2; c.MnqQty = q; c.MgcQty = q; c.RotationTarget = tp; c.RotationStop = sl; c.PauseMinutes = pause;
                                    configs.Add(c);
                                }
            var results = new KeystoneRotationResult[configs.Count]; int done = 0;
            System.Threading.Tasks.Parallel.For(0, configs.Count, i =>
            {
                if (cancelled != null && cancelled()) return;
                var rr = Run(minutes, configs[i]); rr.Trades = new List<KeystoneRotationTrade>(); results[i] = rr;   // summary only (memory)
                int d = System.Threading.Interlocked.Increment(ref done); if (progress != null && d % 50 == 0) progress(d + " / " + configs.Count);
            });
            return results.Where(x => x != null).OrderBy(x => x.Passed >= 5 ? 0 : 1).ThenBy(x => x.CostPerPass).ThenByDescending(x => x.Passed).ToList();
        }

        // When do MNQ and MGC move together? Per 30-minute slot: % of 5-minute windows where both moved the same way,
        // and the average combined $ move (both legs, the chosen contracts) — the fuel a combined target needs.
        public static List<string[]> Together(List<KeystoneHelixMinute> minutes, int mnqQty, int mgcQty)
        {
            var rows = new List<string[]>(); var slots = new Dictionary<int, List<Tuple<bool, double>>>();
            foreach (var g in minutes.Where(x => x.HasMnq && x.HasMgc).GroupBy(x => x.Time.Date))
            {
                var list = g.OrderBy(x => x.Time).ToList();
                for (int i = 4; i < list.Count; i += 5)
                {
                    if ((list[i].Time - list[i - 4].Time).TotalMinutes > 4.5) continue;
                    double dm = list[i].MnqC - list[i - 4].MnqO, dg = list[i].MgcC - list[i - 4].MgcO;
                    int slot = (list[i - 4].Time.Hour * 60 + list[i - 4].Time.Minute - 1) / 30 * 30;
                    List<Tuple<bool, double>> s; if (!slots.TryGetValue(slot, out s)) { s = new List<Tuple<bool, double>>(); slots[slot] = s; }
                    s.Add(Tuple.Create(Math.Sign(dm) != 0 && Math.Sign(dm) == Math.Sign(dg), Math.Abs(dm * 2 * mnqQty) + Math.Abs(dg * 10 * mgcQty)));
                }
            }
            foreach (var kv in slots.OrderBy(k => k.Key))
            {
                if (kv.Value.Count < 20) continue;
                int h = kv.Key / 60, m = kv.Key % 60;
                rows.Add(new[] { h.ToString("00") + ":" + m.ToString("00") + "–" + ((kv.Key + 30) / 60 % 24).ToString("00") + ":" + ((kv.Key + 30) % 60).ToString("00"), kv.Value.Count.ToString(), (100.0 * kv.Value.Count(t => t.Item1) / kv.Value.Count).ToString("0") + "%", "$" + kv.Value.Average(t => t.Item2).ToString("N0", CultureInfo.InvariantCulture), "$" + kv.Value.Where(t => t.Item1).Select(t => t.Item2).DefaultIfEmpty(0).Average().ToString("N0", CultureInfo.InvariantCulture) });
            }
            return rows;
        }

        public static string Verdict(KeystoneRotationResult x)
        {
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            if (x.Passed == 0) return "NO EVALUATION PASSED • " + x.Bought + " bought (" + m(x.Spent) + ") • " + x.Rotations + " rotations, " + x.WinPct.ToString("0") + "% won, " + m(x.PerRotation) + " per rotation after costs.";
            return "1 PASSED EVALUATION COSTS " + m(x.CostPerPass) + " • " + x.Passed + " passed of " + x.Bought + " bought (" + x.PassRate.ToString("0") + "%) in " + (x.DaysToPass.Count == 0 ? 0 : x.DaysToPass.Average()).ToString("0.0") + " trading days on average • " + x.Rotations + " rotations, " + x.WinPct.ToString("0") + "% won, " + m(x.PerRotation) + " per rotation after costs (costs " + m(x.Costs) + ").";
        }
    }

    // ---- FIRST 5M FVG ENTRY STUDY (build 10-03h) -----------------------------------------------------
    // Per instrument and day: the FIRST bullish 5-minute FVG formed after the start time (all 3 candles after the start;
    // gap = candle 3 low above candle 1 high, at least MinGap points). Each entry variation is its own set:
    //   TOUCH (limit at the gap top) • 25% DIP • 50% DIP (limits inside the gap) • GREEN CLOSE + BREAK (a candle touches the gap
    //   without closing below it, a green 5M candle closes — after a red touch the next one must be green — the next 5M candle
    //   breaks that green high = entry at that high) • PRIOR FVG TOUCH / 50%: an FVG formed earlier (18:00 the evening before →
    //   the start) still untouched at the start, that the opening candles (first N minutes) dip into.
    // Fills on 1-minute bars (a limit fills at the level, or at the open when the minute opens through it). No BH. Every
    // entry is then measured to the close by the MOVE STUDY (the fill minute's favourable move is not counted — conservative).
    public sealed class KeystoneFvgStudyConfig
    {
        public int MnqStart = 930, MgcStart = 800, Close = 1555, PriorMinutes = 30;
        public double MnqMinGap = 5, MgcMinGap = 1, MnqAggr = 30, MgcAggr = 3;
        public bool OpenCandleGap = true;   // candle 1 may be the last candle before the start when candle 2 (the opening move) is after it
    }

    public static class KeystoneFvgEntryStudy
    {
        public const string Touch = "FIRST 5M FVG • TOUCH THE GAP TOP", Dip25 = "FIRST 5M FVG • 25% DIP INTO THE GAP", Dip50 = "FIRST 5M FVG • 50% DIP (GAP MIDDLE)", Break = "FIRST 5M FVG • GREEN CLOSE + BREAK OF ITS HIGH", PriorTouch = "PRIOR UNTOUCHED FVG • OPENING CANDLES TOUCH IT", Prior50 = "PRIOR UNTOUCHED FVG • OPENING CANDLES DIP TO 50%", FirstBh = "FIRST 5M BH • RED → GREEN → BREAK OF THE GREEN HIGH";
        public static readonly string[] Sets = { Touch, Dip25, Dip50, Break, PriorTouch, Prior50, FirstBh };

        sealed class Gap { public double Low, High; public DateTime Formed; public int Index; public double Height { get { return High - Low; } } }

        // 5-minute candles from close-stamped 1-minute bars (a 5M candle ends on a multiple of 5 minutes).
        public static List<KeystoneArcBar> FiveMinute(List<KeystoneArcBar> one)
        {
            var output = new List<KeystoneArcBar>(); KeystoneArcBar cur = null; DateTime curEnd = DateTime.MinValue;
            foreach (var b in one)
            {
                int m = b.Time.Minute % 5; DateTime end = m == 0 ? b.Time : b.Time.AddMinutes(5 - m);
                if (cur == null || end != curEnd) { if (cur != null) output.Add(cur); cur = new KeystoneArcBar { Symbol = b.Symbol, Time = end, Open = b.Open, High = b.High, Low = b.Low, Close = b.Close }; curEnd = end; }
                else { cur.High = Math.Max(cur.High, b.High); cur.Low = Math.Min(cur.Low, b.Low); cur.Close = b.Close; }
            }
            if (cur != null) output.Add(cur);
            return output;
        }

        static int FirstAfter(List<KeystoneArcBar> raw, DateTime t) { int lo = 0, hi = raw.Count; while (lo < hi) { int mid = (lo + hi) / 2; if (raw[mid].Time > t) hi = mid; else lo = mid + 1; } return lo; }

        // First 1-minute bar after `after` (up to `until`) that trades down to `level`: fill at the level or at the open if it opened below.
        static bool LimitFill(List<KeystoneArcBar> raw, DateTime after, DateTime until, double level, out int idx, out double fill)
        {
            idx = -1; fill = double.NaN;
            for (int i = FirstAfter(raw, after); i < raw.Count && raw[i].Time <= until; i++)
                if (raw[i].Low <= level + 1e-9) { idx = i; fill = Math.Min(level, raw[i].Open); return true; }
            return false;
        }

        public static Dictionary<string, List<KeystoneArcEvent>> Run(List<KeystoneArcBar> oneMinute, KeystoneFvgStudyConfig c)
        {
            var sets = Sets.ToDictionary(s => s, s => new List<KeystoneArcEvent>());
            if (oneMinute == null) return sets;
            foreach (var sg in oneMinute.GroupBy(b => (b.Symbol ?? "").ToUpperInvariant()))
            {
                string sym = sg.Key; if (sym != "MNQ" && sym != "MGC") continue;
                var raw = sg.OrderBy(b => b.Time).ToList(); var five = FiveMinute(raw);
                int startHhmm = sym == "MGC" ? c.MgcStart : c.MnqStart; double minGap = sym == "MGC" ? c.MgcMinGap : c.MnqMinGap, aggrPts = sym == "MGC" ? c.MgcAggr : c.MnqAggr;
                foreach (var day in raw.Select(b => b.Time.Date).Distinct().OrderBy(d => d))
                {
                    if (day.DayOfWeek == DayOfWeek.Saturday || day.DayOfWeek == DayOfWeek.Sunday) continue;
                    DateTime start = day.AddHours(startHhmm / 100).AddMinutes(startHhmm % 100), close = day.AddHours(c.Close / 100).AddMinutes(c.Close % 100), evening = day.AddDays(-1).AddHours(18);
                    if (close <= start) continue;
                    int s0 = five.FindIndex(b => b.Time > start); if (s0 < 0 || five[s0].Time > close) continue;
                    double startOpen = five[s0].Open;
                    // ---- the first FVG after the start (all three candles after it)
                    Gap first = null;
                    for (int i = Math.Max(2, c.OpenCandleGap ? s0 + 1 : s0 + 2); i < five.Count && five[i].Time <= close; i++)
                        if (five[i].Low > five[i - 2].High && five[i].Low - five[i - 2].High >= minGap - 1e-9) { first = new Gap { Low = five[i - 2].High, High = five[i].Low, Formed = five[i].Time, Index = i }; break; }
                    if (first != null)
                    {
                        double low = double.MaxValue; for (int q = s0; q <= first.Index - 2; q++) low = Math.Min(low, five[q].Low);
                        double drop = low == double.MaxValue ? 0 : Math.Max(0, startOpen - low);
                        Action<string, int, double, DateTime> add = (set, idx, fill, trig) =>
                        {
                            var e = new KeystoneArcEvent { Symbol = sym, Direction = "LONG", SetupClass = "FVG", TriggerTime = trig, EntryTime = raw[idx].Time, Entry = fill, FvgLower = first.Low, FvgUpper = first.High, FvgGap = first.Height, FvgDrop = drop, FvgFormedTime = first.Formed, StrengthTag = drop >= aggrPts ? "AGGR" : "BASE", ReviewNote = set };
                            KeystoneMoveStudy.Walk(e, raw, idx, 1, close, sym, true); if (e.MoveHeat != null) sets[set].Add(e);
                        };
                        int fi; double fp;
                        if (LimitFill(raw, first.Formed, close, first.High, out fi, out fp)) add(Touch, fi, fp, first.Formed);
                        if (LimitFill(raw, first.Formed, close, first.High - 0.25 * first.Height, out fi, out fp)) add(Dip25, fi, fp, first.Formed);
                        if (LimitFill(raw, first.Formed, close, first.High - 0.5 * first.Height, out fi, out fp)) add(Dip50, fi, fp, first.Formed);
                        // green close + break of its high (one attempt, like the lab's FVG rule)
                        for (int k = first.Index + 1; k < five.Count && five[k].Time <= close; k++)
                        {
                            var b = five[k]; if (b.Close < first.Low) break;
                            if (b.Low > first.High) continue;                          // not back in the gap yet
                            int refIdx = b.Close > b.Open ? k : (k + 1 < five.Count && five[k + 1].Close > five[k + 1].Open && five[k + 1].Close >= first.Low ? k + 1 : -1);
                            if (refIdx < 0 || refIdx + 1 >= five.Count || five[refIdx + 1].Time > close) break;
                            var refBar = five[refIdx]; var trig = five[refIdx + 1];
                            if (trig.High >= refBar.High)
                            {
                                for (int i = FirstAfter(raw, refBar.Time); i < raw.Count && raw[i].Time <= trig.Time; i++)
                                    if (raw[i].High >= refBar.High) { add(Break, i, Math.Max(refBar.High, raw[i].Open), trig.Time); break; }
                            }
                            break;
                        }
                    }
                    // ---- for comparison: the first 5M BH after the start (red candle → green reference → the next candle breaks the green high)
                    for (int i = s0 + 2; i < five.Count && five[i].Time <= close; i++)
                    {
                        var red = five[i - 2]; var grn = five[i - 1]; var trg = five[i];
                        if (!(red.Close < red.Open && grn.Close > grn.Open && trg.High >= grn.High)) continue;
                        double lowB = double.MaxValue; for (int q = s0; q <= i - 2; q++) lowB = Math.Min(lowB, five[q].Low);
                        double dropB = lowB == double.MaxValue ? 0 : Math.Max(0, startOpen - lowB);
                        for (int m = FirstAfter(raw, grn.Time); m < raw.Count && raw[m].Time <= trg.Time; m++)
                            if (raw[m].High >= grn.High)
                            {
                                var e = new KeystoneArcEvent { Symbol = sym, Direction = "LONG", SetupClass = "BH", TriggerTime = trg.Time, EntryTime = raw[m].Time, Entry = Math.Max(grn.High, raw[m].Open), FvgDrop = dropB, StrengthTag = dropB >= aggrPts ? "AGGR" : "BASE", ReviewNote = FirstBh };
                                KeystoneMoveStudy.Walk(e, raw, m, 1, close, sym, true); if (e.MoveHeat != null) sets[FirstBh].Add(e);
                                break;
                            }
                        break;
                    }
                    // ---- prior untouched FVG: formed 18:00 the evening before → the start, not traded into before the start
                    var prior = new List<Gap>();
                    for (int i = 2; i < five.Count && five[i].Time <= start; i++)
                    {
                        if (five[i - 2].Time - TimeSpan.FromMinutes(5) < evening) continue;
                        if (five[i].Low > five[i - 2].High && five[i].Low - five[i - 2].High >= minGap - 1e-9) prior.Add(new Gap { Low = five[i - 2].High, High = five[i].Low, Formed = five[i].Time, Index = i });
                    }
                    if (prior.Count > 0)
                    {
                        DateTime startRaw = start;
                        prior = prior.Where(g => { for (int q = g.Index + 1; q < five.Count && five[q].Time <= startRaw; q++) if (five[q].Low <= g.High) return false; return true; }).ToList();
                        // the opening candles: the first touch of any untouched prior gap within PriorMinutes after the start
                        DateTime until = start.AddMinutes(Math.Max(5, c.PriorMinutes));
                        for (int i = FirstAfter(raw, start); i < raw.Count && raw[i].Time <= until && prior.Count > 0; i++)
                        {
                            var hit = prior.Where(g => raw[i].Low <= g.High + 1e-9).OrderByDescending(g => g.High).FirstOrDefault();
                            if (hit == null) continue;
                            double drop = Math.Max(0, startOpen - raw[i].Low);
                            Action<string, int, double> addPrior = (set, idx, fill) =>
                            {
                                var e = new KeystoneArcEvent { Symbol = sym, Direction = "LONG", SetupClass = "PRIOR FVG", TriggerTime = raw[idx].Time, EntryTime = raw[idx].Time, Entry = fill, FvgLower = hit.Low, FvgUpper = hit.High, FvgGap = hit.Height, FvgDrop = drop, FvgFormedTime = hit.Formed, StrengthTag = drop >= aggrPts ? "AGGR" : "BASE", ReviewNote = set };
                                KeystoneMoveStudy.Walk(e, raw, idx, 1, close, sym, true); if (e.MoveHeat != null) sets[set].Add(e);
                            };
                            addPrior(PriorTouch, i, Math.Min(hit.High, raw[i].Open));
                            int fi; double fp; if (LimitFill(raw, raw[i].Time.AddMinutes(-1), until, hit.High - 0.5 * hit.Height, out fi, out fp)) addPrior(Prior50, fi, fp);
                            break;
                        }
                    }
                }
            }
            return sets;
        }
    }

    // ---- REPLAY TRADER engine: a session replayed tick by tick from the loaded 1-minute bars ------------------------------
    // Inside each minute the price walks open → the nearer-in-time extreme → the other extreme → close (a down-closing
    // minute visits its high first, an up-closing minute its low first) in small steps. That path is SIMULATED: 1-minute
    // bars do not record the order of the ticks inside the minute. Buy / sell at the current price, optional stop / target in
    // points (checked on every step), flat at the end of the session; costs = commission both sides + 1 tick per contract.
    public sealed class KeystoneReplayOrder { public int Id, Dir, Qty; public string Type = "LIMIT"; public double Price; public string Label { get { return (Dir > 0 ? "BUY " : "SELL ") + Type + " " + Qty; } } }

    // A strategy signal shown on the replay chart (only once the replay clock has reached its entry time).
    public sealed class KeystoneReplaySignal
    {
        public DateTime Time, Exit; public int Dir; public double Entry, Stop = double.NaN, Target = double.NaN; public string Tag = string.Empty, Tier = string.Empty; public bool Taken, WaitExit, Inverted;   // WaitExit: formed during a trade → placed when it closes (if still valid) • Inverted: FVG RETRACE INVERSION — a single order like a LIMIT one, sent as a STOP (the opposite side at the same price)
        // tested opening-range rules: Order = "STOP" → a stop order at Entry from Time until CancelAt (one of a pair, Group = OCO);
        // the stop / target are distances from the fill (StopDist / TargetDist, 0 = none); Exit = flat by this time
        public string Order = "MARKET"; public double StopDist, TargetDist, FundStopDist, FundTargetDist; public DateTime CancelAt = DateTime.MaxValue; public int Group; public string Why = string.Empty;
        // OPENING FVG: the zone drawn on the chart from ZoneFrom, and how it grew (time, low, high, the limit's price) — the order moves with it
        public double ZoneLo = double.NaN, ZoneHi = double.NaN; public DateTime ZoneFrom; public List<Tuple<DateTime, double, double, double>> Stages; public List<Tuple<DateTime, DateTime, double, double>> Fvgs;
        public Tuple<DateTime, double, double, double> StageAt(DateTime t) { if (Stages == null) return null; Tuple<DateTime, double, double, double> o = null; foreach (var x in Stages) if (x.Item1 <= t) o = x; return o; }
    }

    // The opening-range rules that survived the 6-year walk-forward research (docs/research, research/*.cs):
    // settings chosen on 2020–2023, judged on 2024–2026. One trade a day, flat by 15:55, conservative fills.
    public sealed class KeystoneOrbRule
    {
        public string Name = "", Short = ""; public int OpenHhmm = 930, Minutes = 10, EntryWindow = 150, ExitHhmm = 1555;
        public string Mode = "CANDLE";       // CANDLE = market order in the direction of the opening candle • BREAK = stop orders at the range high / low (first one wins)
        public double StopAtr = 0.25;        // stop = this × the 14-day average 09:30–16:00 range (0 = the opening range itself)
        public double TargetR = 4;           // target = this × the stop (0 = none, hold to the exit time)
        public bool SkipNews = true;         // no trade on FOMC and payrolls days
        public int Side = 0;                 // 1 = buys only, −1 = sells only, 0 = both
        public string Evidence = "";
        // Mode "FVG" (OPENING FVG • MNQ): the first 5-minute FVG after the open (stacked FVGs in a row = one zone), a limit order at FvgPct
        // of the zone, stop −StopUsd / target +TargetUsd for Contracts MNQ (→ points), cancelled / flat at ExitHhmm
        public double FvgPct = 50, StopUsd = 2000, TargetUsd = 1000; public int Contracts = 10, FvgMinutes = 5; public string Symbols = "MNQ";   // OPENING FVG: MNQ • MGC • BOTH
        public int FvgFrom = 0;
        // OPENING FVG FILTERS + the funded bracket (0 / ANY = off): FVGs in a row before the order goes in • the zone set by HHMM • the overnight
        // move (18:00 → 09:30) WITH / AGAINST the side • where 09:30 opens in the overnight range, side-relative (LOW = near the side's start,
        // HIGH = near its end) • FUNDED accounts trade their own stop / target $
        public int MinStack = 1, ZoneByHhmm = 0; public string Overnight = "ANY", OpenPos = "ANY";
        public double FundStopUsd = 0, FundTargetUsd = 0;
        public int WaitExit = 1;
        public double MinGapPts = 0;
        public int Invert = 0;     // FVG RETRACE INVERSION: 1 = the same FVGs and prices, the opposite side (a bullish FVG SELLS at its level with a stop order, a bearish one BUYS); same stop / target $
        public int VwapSide = 0;   // FVG RETRACE: 1 = only buys when the FVG's third candle closes above the session VWAP (from OpenHhmm), sells below   // FVG RETRACE: the gap must be at least this many points (1-minute FVGs: 1 point keeps out the 1-tick noise)   // FVG RETRACE: a setup that forms during a trade waits for its exit (1) or is skipped (0)
        public int WindowEndHhmm = 1500;   // FVG RETRACE: new setups from OpenHhmm to this time (each order valid EntryWindow minutes)
        public string JoinMode = "ALL";   // OPENING FVG zone grows with: ALL = every FVG the same way until the order fills (an opposite FVG ends it) • ROW = only FVGs in a row   // OPENING FVG: 0 = the 09:30 candle is the FVG's FIRST candle • 1 = the 09:30 candle may be its MIDDLE (gap) candle (candle 1 = 09:25)
        public KeystoneOrbRule Copy() { return (KeystoneOrbRule)MemberwiseClone(); }
        public string Describe()
        {
            if (Mode == "FVGR") return Name + " • every " + FvgMinutes + "-minute FVG" + (MinGapPts > 0 ? " (≥ " + MinGapPts.ToString("0.##", CultureInfo.InvariantCulture) + " pt)" : "") + " from " + (OpenHhmm / 100).ToString("00") + ":" + (OpenHhmm % 100).ToString("00") + " to " + (WindowEndHhmm / 100).ToString("00") + ":" + (WindowEndHhmm % 100).ToString("00") + (VwapSide == 1 ? " on the VWAP side (bullish above, bearish below)" : "")
                + " • order at " + FvgPct.ToString("0.#", CultureInfo.InvariantCulture) + "% of the gap, valid " + EntryWindow + " min • " + (Invert == 1 ? "INVERTED: a bullish FVG SELLS, a bearish one BUYS (stop order at the same price)" : "a bullish FVG BUYS, a bearish one SELLS (limit)")
                + " • stop −$" + StopUsd.ToString("N0", CultureInfo.InvariantCulture) + " • target +$" + TargetUsd.ToString("N0", CultureInfo.InvariantCulture) + " for " + Contracts + " • " + (Symbols == "BOTH" ? "MNQ + MGC" : Symbols) + " • flat " + (ExitHhmm / 100).ToString("00") + ":" + (ExitHhmm % 100).ToString("00");
            if (Mode == "FVG") return Name + " • " + (Symbols == "BOTH" ? "MNQ + MGC" : Symbols) + ": the first " + FvgMinutes + "-minute FVG after " + (OpenHhmm / 100).ToString("00") + ":" + (OpenHhmm % 100).ToString("00") + " (FVGs in a row = one zone) • limit order at " + FvgPct.ToString("0.#", CultureInfo.InvariantCulture) + "% of the zone (BUY a bullish one, SELL a bearish one) • stop −$" + StopUsd.ToString("N0", CultureInfo.InvariantCulture) + " • target +$" + TargetUsd.ToString("N0", CultureInfo.InvariantCulture) + " for " + Contracts + " contracts • no fill by " + (ExitHhmm / 100).ToString("00") + ":" + (ExitHhmm % 100).ToString("00") + " = no trade, flat then";
            return Name + " • opening range " + (OpenHhmm / 100).ToString("00") + ":" + (OpenHhmm % 100).ToString("00") + " + " + Minutes + " min • " + (Mode == "CANDLE" ? "market order in the direction of that candle" : "stop orders at its high and low (first one wins, until " + EntryWindow + " min later)")
                + " • stop " + (StopAtr > 0 ? StopAtr.ToString("0.##", CultureInfo.InvariantCulture) + " × 14-day range" : "the other side of the range") + " • target " + (TargetR > 0 ? TargetR.ToString("0.#", CultureInfo.InvariantCulture) + "R" : "none") + " • flat " + (ExitHhmm / 100).ToString("00") + ":" + (ExitHhmm % 100).ToString("00") + (SkipNews ? " • no trade on FOMC / payrolls days" : "");
        }
    }

    // KEYSTONE REPORT (.kreport.json, format "keystone-report-1"): a study made outside the studio (docs/research) —
    // summary, tables and every labelled day with its markers / trades. The REPORTS window imports it and draws a day on the chart.
    public sealed class KeystoneReport
    {
        public string Title = "", Subtitle = "", Instrument = "MNQ", Method = "", Generated = "", FilePath = "";
        public List<string[]> Summary = new List<string[]>();
        public List<Section> Sections = new List<Section>();
        public List<Day> Days = new List<Day>();
        public sealed class Section { public string Title = "", Note = ""; public List<string> Columns = new List<string>(); public List<List<string>> Rows = new List<List<string>>(); }
        public sealed class Marker { public TimeSpan Time; public double Price = double.NaN; public string Text = "", Kind = "info"; }
        public sealed class Trade { public int Dir; public TimeSpan EntryTime, ExitTime; public double Entry = double.NaN, Stop = double.NaN, Target = double.NaN, Exit = double.NaN, Pnl = double.NaN; public string Why = ""; }
        public sealed class Day { public DateTime Date; public string Label = "", Color = "", Note = ""; public Dictionary<string, string> Fields = new Dictionary<string, string>(); public List<Marker> Markers = new List<Marker>(); public List<Trade> Trades = new List<Trade>(); }

        public static KeystoneReport Load(string path) { var r = Parse(File.ReadAllText(path)); r.FilePath = path; return r; }

        public static KeystoneReport Parse(string json)
        {
            int i = 0; var root = Value(json, ref i) as Dictionary<string, object>;
            if (root == null) throw new FormatException("not a report (no JSON object)");
            if (Str(root, "format") != "keystone-report-1") throw new FormatException("not a Keystone report (format must be keystone-report-1)");
            var r = new KeystoneReport { Title = Str(root, "title"), Subtitle = Str(root, "subtitle"), Instrument = Str(root, "instrument") == "" ? "MNQ" : Str(root, "instrument").ToUpperInvariant(), Method = Str(root, "method"), Generated = Str(root, "generated") };
            foreach (var o in List(root, "summary").OfType<Dictionary<string, object>>()) r.Summary.Add(new[] { Str(o, "label"), Str(o, "value"), Str(o, "note") });
            foreach (var o in List(root, "sections").OfType<Dictionary<string, object>>())
            {
                var s = new Section { Title = Str(o, "title"), Note = Str(o, "note") };
                s.Columns.AddRange(List(o, "columns").Select(x => Convert.ToString(x, CultureInfo.InvariantCulture)));
                foreach (var row in List(o, "rows").OfType<List<object>>()) s.Rows.Add(row.Select(x => Convert.ToString(x, CultureInfo.InvariantCulture)).ToList());
                r.Sections.Add(s);
            }
            foreach (var o in List(root, "days").OfType<Dictionary<string, object>>())
            {
                DateTime dt; if (!DateTime.TryParseExact(Str(o, "date"), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out dt)) continue;
                var d = new Day { Date = dt, Label = Str(o, "label"), Color = Str(o, "color"), Note = Str(o, "note") };
                object f; if (o.TryGetValue("fields", out f) && f is Dictionary<string, object>) foreach (var kv in (Dictionary<string, object>)f) d.Fields[kv.Key] = Convert.ToString(kv.Value, CultureInfo.InvariantCulture);
                foreach (var m in List(o, "markers").OfType<Dictionary<string, object>>()) d.Markers.Add(new Marker { Time = Hm(Str(m, "time")), Price = Num(m, "price"), Text = Str(m, "text"), Kind = Str(m, "kind") == "" ? "info" : Str(m, "kind") });
                foreach (var t in List(o, "trades").OfType<Dictionary<string, object>>()) d.Trades.Add(new Trade { Dir = (int)Math.Sign(Num(t, "dir")), EntryTime = Hm(Str(t, "entryTime")), ExitTime = Hm(Str(t, "exitTime")), Entry = Num(t, "entry"), Stop = Num(t, "stop"), Target = Num(t, "target"), Exit = Num(t, "exit"), Pnl = Num(t, "pnl"), Why = Str(t, "why") });
                r.Days.Add(d);
            }
            r.Days = r.Days.OrderBy(d => d.Date).ToList();
            return r;
        }

        static TimeSpan Hm(string s) { TimeSpan t; return TimeSpan.TryParseExact(s ?? "", new[] { @"hh\:mm", @"h\:mm", @"hh\:mm\:ss" }, CultureInfo.InvariantCulture, out t) ? t : TimeSpan.Zero; }
        static string Str(Dictionary<string, object> o, string k) { object v; return o.TryGetValue(k, out v) && v != null ? Convert.ToString(v, CultureInfo.InvariantCulture) : ""; }
        static double Num(Dictionary<string, object> o, string k) { object v; return o.TryGetValue(k, out v) && v is double ? (double)v : double.NaN; }
        static List<object> List(Dictionary<string, object> o, string k) { object v; return o.TryGetValue(k, out v) && v is List<object> ? (List<object>)v : new List<object>(); }

        // a small JSON reader (objects, arrays, strings, numbers, true / false / null) — no extra assembly needed
        static object Value(string s, ref int i)
        {
            Ws(s, ref i); if (i >= s.Length) throw new FormatException("unexpected end of the file");
            char c = s[i];
            if (c == '{')
            {
                var o = new Dictionary<string, object>(); i++; Ws(s, ref i);
                if (s[i] == '}') { i++; return o; }
                while (true) { Ws(s, ref i); string k = (string)Value(s, ref i); Ws(s, ref i); if (s[i] != ':') throw new FormatException("':' expected at " + i); i++; o[k] = Value(s, ref i); Ws(s, ref i); if (s[i] == ',') { i++; continue; } if (s[i] == '}') { i++; return o; } throw new FormatException("',' or '}' expected at " + i); }
            }
            if (c == '[')
            {
                var l = new List<object>(); i++; Ws(s, ref i);
                if (s[i] == ']') { i++; return l; }
                while (true) { l.Add(Value(s, ref i)); Ws(s, ref i); if (s[i] == ',') { i++; continue; } if (s[i] == ']') { i++; return l; } throw new FormatException("',' or ']' expected at " + i); }
            }
            if (c == '"')
            {
                var b = new StringBuilder(); i++;
                while (s[i] != '"')
                {
                    if (s[i] == '\\') { i++; char e = s[i]; if (e == 'n') b.Append('\n'); else if (e == 't') b.Append('\t'); else if (e == 'u') { b.Append((char)Convert.ToInt32(s.Substring(i + 1, 4), 16)); i += 4; } else b.Append(e); i++; }
                    else b.Append(s[i++]);
                }
                i++; return b.ToString();
            }
            if (string.CompareOrdinal(s, i, "true", 0, 4) == 0) { i += 4; return true; }
            if (string.CompareOrdinal(s, i, "false", 0, 5) == 0) { i += 5; return false; }
            if (string.CompareOrdinal(s, i, "null", 0, 4) == 0) { i += 4; return null; }
            int a = i; while (i < s.Length && "+-0123456789.eE".IndexOf(s[i]) >= 0) i++;
            if (a == i) throw new FormatException("unexpected '" + c + "' at " + i);
            return double.Parse(s.Substring(a, i - a), NumberStyles.Float, CultureInfo.InvariantCulture);
        }
        static void Ws(string s, ref int i) { while (i < s.Length && char.IsWhiteSpace(s[i])) i++; }
    }

    public static class KeystoneOpeningRange
    {
        public static List<KeystoneOrbRule> Presets()
        {
            return new List<KeystoneOrbRule>
            {
                new KeystoneOrbRule { Name = "OPENING DRIVE • 10M CANDLE", Short = "DRIVE", Minutes = 10, Mode = "CANDLE", StopAtr = 0.25, TargetR = 4, SkipNews = true,
                    Evidence = "MNQ 2020–23: 720 trades, $13.8 a trade per micro • 2024–26 (unseen): 677 trades, $17.9 a trade, every year 2021–2026 positive • 35% winners, wins ≈ 3× losses" },
                new KeystoneOrbRule { Name = "OPENING RANGE BREAK • 15M", Short = "ORB15", Minutes = 15, Mode = "BREAK", StopAtr = 0.25, TargetR = 4, EntryWindow = 150, SkipNews = true,
