        static DateTime At(DateTime session, int hhmm) { return session.Date.AddHours(hhmm / 100).AddMinutes(hhmm % 100); }
        static DateTime Session(DateTime barTime) { var t = barTime.AddMinutes(-1); return t.Hour >= 18 ? t.Date.AddDays(1) : t.Date; }
        public static bool NewsDay(DateTime day)
        {
            string k = day.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
            return KeystoneNews.FomcDates.Contains(k) || KeystoneNews.NfpDate(day.Year, day.Month) == day.Date;
        }

        // average 09:30–16:00 range of the 14 full sessions before `day` (prior = earlier bars, any order)
        public static double RthAtr(List<KeystoneArcBar> prior, DateTime day)
        {
            if (prior == null || prior.Count == 0) return double.NaN;
            var ranges = new List<double>();
            foreach (var g in prior.GroupBy(b => Session(b.Time)).Where(g => g.Key < day.Date && g.Key.DayOfWeek != DayOfWeek.Saturday && g.Key.DayOfWeek != DayOfWeek.Sunday).OrderByDescending(g => g.Key))
            {
                var list = g.ToList(); if (list.Count < 800) continue;
                DateTime a = At(g.Key, 930), b = At(g.Key, 1600);
                var rth = list.Where(x => x.Time > a && x.Time <= b).ToList();
                if (rth.Count < 300 || !rth.Any(x => x.Time == a.AddMinutes(1)) || !rth.Any(x => x.Time >= b.AddMinutes(-2))) continue;
                ranges.Add(rth.Max(x => x.High) - rth.Min(x => x.Low)); if (ranges.Count == 14) break;
            }
            return ranges.Count == 14 ? ranges.Average() : double.NaN;
        }

        // the day's signal(s) for a rule; session = the day's 1-minute bars (Time = bar close, New York)
        public static List<KeystoneReplaySignal> Signals(KeystoneOrbRule rule, List<KeystoneArcBar> session, List<KeystoneArcBar> prior, string symbol)
        {
            var output = new List<KeystoneReplaySignal>(); if (session == null || session.Count < 60) return output;
            DateTime day = Session(session[0].Time); if (rule.SkipNews && NewsDay(day)) return output;
            if (rule.Mode == "FVGR")
            {
                string sy0 = (symbol ?? "").ToUpperInvariant(); bool mgc0 = KeystoneMoveStudy.IsMgc(sy0);
                if (!(rule.Symbols == "BOTH" ? (sy0 == "MNQ" || mgc0) : rule.Symbols == "MGC" ? mgc0 : sy0 == "MNQ")) return output;
                output.AddRange(KeystoneFvgRetrace.Signals(session, rule, symbol)); return output;
            }
            if (rule.Mode == "FVG")
            {
                string sy = (symbol ?? "").ToUpperInvariant(); bool mgc = KeystoneMoveStudy.IsMgc(sy);   // MNQ / MGC / BOTH (MNQ by default)
                if (!(rule.Symbols == "BOTH" ? (sy == "MNQ" || mgc) : rule.Symbols == "MGC" ? mgc : sy == "MNQ")) return output;
                var x = KeystoneOpenFvg.Run(session, rule, symbol); if (x == null || x.Dir == 0 || x.Stages.Count == 0) return output;
                var st0 = x.Stages[0];   // the order goes in when the FIRST FVG is set (at its level); it moves when another one joins
                double fpv = KeystoneMoveStudy.PointValue(symbol) * Math.Max(1, rule.Contracts);
                output.Add(new KeystoneReplaySignal { FundStopDist = rule.FundStopUsd > 0 ? rule.FundStopUsd / fpv : 0, FundTargetDist = rule.FundTargetUsd > 0 ? rule.FundTargetUsd / fpv : 0, Time = st0.Item1, ZoneLo = st0.Item2, ZoneHi = st0.Item3, ZoneFrom = x.ZoneStart, Stages = x.Stages, Fvgs = x.Fvgs, Exit = At(day, rule.ExitHhmm).AddMinutes(1), Dir = x.Dir, Entry = st0.Item4, Stop = st0.Item4 - x.Dir * x.StopPts, Target = st0.Item4 + x.Dir * x.TargetPts, StopDist = x.StopPts, TargetDist = x.TargetPts,
                    Order = "LIMIT", CancelAt = At(day, rule.ExitHhmm), Tag = "OPEN FVG " + rule.FvgPct.ToString("0.#", CultureInfo.InvariantCulture) + "%" + (x.Stack > 1 ? " ×" + x.Stack : ""), Tier = "T",
                    Why = (x.Dir > 0 ? "bullish" : "bearish") + " " + rule.FvgMinutes + "-min FVG" + (x.Stack > 1 ? "s ×" + x.Stack + " in a row" : "") + " " + x.ZoneLo.ToString("0.00", CultureInfo.InvariantCulture) + " – " + x.ZoneHi.ToString("0.00", CultureInfo.InvariantCulture) + " • " + (x.Dir > 0 ? "BUY" : "SELL") + " limit at " + rule.FvgPct.ToString("0.#", CultureInfo.InvariantCulture) + "% = " + x.Entry.ToString("0.00", CultureInfo.InvariantCulture) + " • stop −$" + rule.StopUsd.ToString("N0", CultureInfo.InvariantCulture) + " (" + x.StopPts.ToString("0.##", CultureInfo.InvariantCulture) + " pts) • target +$" + rule.TargetUsd.ToString("N0", CultureInfo.InvariantCulture) + " (" + x.TargetPts.ToString("0.##", CultureInfo.InvariantCulture) + " pts)" });
                return output;
            }
            double tick = KeystoneMoveStudy.IsMgc(symbol) ? 0.1 : 0.25;
            DateTime o = At(day, rule.OpenHhmm), orEnd = o.AddMinutes(rule.Minutes), exit = At(day, rule.ExitHhmm).AddMinutes(1);
            var range = session.Where(b => b.Time > o && b.Time <= orEnd).ToList(); if (range.Count == 0 || range[0].Time != o.AddMinutes(1)) return output;
            double hi = range.Max(b => b.High), lo = range.Min(b => b.Low), w = hi - lo; if (w < 4 * tick) return output;
            double atr = RthAtr(prior, day); if (rule.StopAtr > 0 && double.IsNaN(atr)) return output;
            double stopD = rule.StopAtr > 0 ? rule.StopAtr * atr : w, tgtD = rule.TargetR > 0 ? rule.TargetR * stopD : 0;
            string tag = rule.Short + " " + rule.Minutes + "M";
            if (rule.Mode == "CANDLE")
            {
                double op = range[0].Open, cl = range[range.Count - 1].Close; int dir = Math.Sign(cl - op); if (dir == 0 || (rule.Side != 0 && dir != rule.Side)) return output;
                output.Add(new KeystoneReplaySignal { Time = orEnd, Exit = exit, Dir = dir, Entry = cl, Stop = cl - dir * stopD, Target = tgtD > 0 ? cl + dir * tgtD : double.NaN, StopDist = stopD, TargetDist = tgtD, Tag = tag, Tier = "T",
                    Why = "first " + rule.Minutes + " min closed " + (dir > 0 ? "UP" : "DOWN") + " (" + op.ToString("0.##", CultureInfo.InvariantCulture) + " → " + cl.ToString("0.##", CultureInfo.InvariantCulture) + ") • stop " + stopD.ToString("0.#", CultureInfo.InvariantCulture) + " pts" });
                return output;
            }
            DateTime cancel = orEnd.AddMinutes(rule.EntryWindow); int grp = day.DayOfYear;
            foreach (int dir in new[] { 1, -1 })
            {
                if (rule.Side != 0 && dir != rule.Side) continue; double lvl = dir > 0 ? hi : lo;
                // the bar that trades through the level (for the chart arrow); the AUTO trader works the stop order itself
                var hit = session.FirstOrDefault(b => b.Time > orEnd && b.Time <= cancel && (dir > 0 ? b.High >= hi + tick : b.Low <= lo - tick));
                output.Add(new KeystoneReplaySignal { Time = orEnd, Exit = exit, Dir = dir, Entry = lvl + dir * tick, Stop = lvl + dir * tick - dir * stopD, Target = tgtD > 0 ? lvl + dir * tick + dir * tgtD : double.NaN, StopDist = stopD, TargetDist = tgtD,
                    Order = "STOP", CancelAt = cancel, Group = grp, Tag = tag + (dir > 0 ? " HIGH" : " LOW"), Tier = "T",
                    Why = "range " + lo.ToString("0.##", CultureInfo.InvariantCulture) + " – " + hi.ToString("0.##", CultureInfo.InvariantCulture) + " • " + (dir > 0 ? "buy stop above the high" : "sell stop below the low") + " until " + cancel.ToString("HH:mm") + (hit == null ? " (not reached)" : "") });
            }
            return output;
        }
    }

    // ---- OPENING FVG • MNQ: one day on 1-minute bars (Time = bar close, New York). 5-minute candles from the open; the first FVG (bullish:
    // candle 3's low above candle 1's high • bearish: candle 3's high below candle 1's low) sets the direction; every next candle that forms
    // another FVG the same way joins the zone (lowest → highest edge). A limit order waits at Pct of the zone (bullish: that far down from its
    // top • bearish: that far up from its bottom) and moves with the zone until it fills; then stop / target in points for the $ and contracts.
    // Fills: the limit at its price (or the open when the minute opens through it); the fill minute checks the stop only; after that the stop
    // first, then the target (both at their prices); flat at the exit time on that minute's close. No fill by the exit time = no trade.
    public sealed class KeystoneOpenFvgDay
    {
        public DateTime Day, SetupTime, ZoneStart, FillTime = DateTime.MinValue, ExitTime = DateTime.MinValue; public int Dir, Stack; public bool Filled;
        // the zone as it grew: (time it was set, low, high, the order's price) — the first FVG, then each one that joined it
        public List<Tuple<DateTime, double, double, double>> Stages = new List<Tuple<DateTime, double, double, double>>();
        public List<Tuple<DateTime, DateTime, double, double>> Fvgs = new List<Tuple<DateTime, DateTime, double, double>>();   // every FVG of the zone: (formed at, its first candle, low, high)
        public double ZoneLo, ZoneHi, Entry, StopPts, TargetPts, Exit, Points, Pnl; public string Reason = string.Empty;
    }
    // ---- FVG RETRACE (FREQUENT): every 5-minute FVG between OpenHhmm and WindowEndHhmm (candles counted from OpenHhmm) → a LIMIT order
    // at FvgPct of the gap (bullish: that far down from its top • bearish: up from its bottom, on the tick), valid EntryWindow minutes;
    // stop / target in $ for the contracts; flat at ExitHhmm. The chart holds one position at a time: a newer FVG replaces a waiting order.
    public static class KeystoneFvgRetrace
    {
        public static List<KeystoneReplaySignal> Signals(List<KeystoneArcBar> session, KeystoneOrbRule r, string symbol)
        {
            var o = new List<KeystoneReplaySignal>(); if (session == null || session.Count == 0) return o;
            var last = session[session.Count - 1].Time.AddMinutes(-1); DateTime day = last.Hour >= 18 ? last.Date.AddDays(1) : last.Date;
            Func<int, DateTime> at = hm => { var t = day.AddHours(hm / 100).AddMinutes(hm % 100); return hm >= 1800 ? t.AddDays(-1) : t; };
            DateTime ws = at(r.OpenHhmm), we = at(r.WindowEndHhmm), flat = at(r.ExitHhmm); int m = Math.Max(1, r.FvgMinutes);
            double pv = KeystoneMoveStudy.PointValue(symbol), tk = KeystoneMoveStudy.TickSize(symbol); int q = Math.Max(1, r.Contracts);
            double stp = r.StopUsd / (pv * q), tgt = r.TargetUsd / (pv * q);
            var c = new Dictionary<int, double[]>();   // candle index → o, h, l, c
            DateTime cs = ws.AddMinutes(-m * Math.Max(0, Math.Min(1, r.FvgFrom)));   // FvgFrom 1: the candle before the open counts, so the open candle can be an FVG's MIDDLE
            foreach (var b in session)
            {
                var ot = b.Time.AddMinutes(-1); if (ot < cs || b.Time > we) continue;
                int k = (int)Math.Floor((ot - cs).TotalMinutes / m); double[] x;
                if (!c.TryGetValue(k, out x)) c[k] = new[] { b.Open, b.High, b.Low, b.Close }; else { x[1] = Math.Max(x[1], b.High); x[2] = Math.Min(x[2], b.Low); x[3] = b.Close; }
            }
            // the session VWAP from the open (typical price × volume), known at the close of each minute
            var vwT = new List<DateTime>(); var vwV = new List<double>();
            if (r.VwapSide == 1) { double sPv = 0, sVol = 0; foreach (var b in session) { var bt = b.Time.AddMinutes(-1); if (bt < ws || b.Time > we) continue; double vol = Math.Max(1, b.Volume); sPv += (b.High + b.Low + b.Close) / 3 * vol; sVol += vol; vwT.Add(b.Time); vwV.Add(sPv / sVol); } }
            Func<DateTime, double> vwapAt = t => { double v0 = double.NaN; for (int i = 0; i < vwT.Count && vwT[i] <= t; i++) v0 = vwV[i]; return v0; };
            foreach (var k3 in c.Keys.OrderBy(k => k))
            {
                double[] c1, c3 = c[k3]; if (!c.TryGetValue(k3 - 2, out c1)) continue;
                int d = c3[2] > c1[1] ? 1 : c3[1] < c1[2] ? -1 : 0; if (d == 0 || (r.Side != 0 && d != r.Side)) continue;
                if (r.VwapSide == 1) { double vw = vwapAt(cs.AddMinutes((k3 + 1) * m)); if (double.IsNaN(vw) || (d > 0 ? c3[3] < vw : c3[3] > vw)) continue; }
                double lo = d > 0 ? c1[1] : c3[1], hi = d > 0 ? c3[2] : c1[2]; if (hi - lo < r.MinGapPts - 1e-9) continue; double v = d > 0 ? hi - r.FvgPct / 100.0 * (hi - lo) : lo + r.FvgPct / 100.0 * (hi - lo);
                double lv = d > 0 ? Math.Floor(v / tk + 0.5 - 1e-9) * tk : Math.Ceiling(v / tk - 0.5 + 1e-9) * tk;
                DateTime formed = cs.AddMinutes((k3 + 1) * m), cancel = formed.AddMinutes(Math.Max(1, r.EntryWindow)); if (cancel > we) cancel = we; if (formed >= we) continue;
                var stage = new List<Tuple<DateTime, double, double, double>> { Tuple.Create(formed, lo, hi, lv) };
                bool inv = r.Invert == 1; int td = inv ? -d : d;   // INVERSION: the same FVG and price, the trade the other way (a stop order)
                o.Add(new KeystoneReplaySignal { FundStopDist = r.FundStopUsd > 0 ? r.FundStopUsd / (pv * q) : 0, FundTargetDist = r.FundTargetUsd > 0 ? r.FundTargetUsd / (pv * q) : 0, Time = formed, Exit = flat.AddMinutes(1), Dir = td, Entry = lv, Stop = lv - td * stp, Target = lv + td * tgt, StopDist = stp, TargetDist = tgt, Order = "LIMIT", Inverted = inv, CancelAt = cancel, Tier = "T", WaitExit = r.WaitExit == 1,
                    ZoneLo = lo, ZoneHi = hi, ZoneFrom = cs.AddMinutes((k3 - 2) * m), Stages = stage, Fvgs = new List<Tuple<DateTime, DateTime, double, double>> { Tuple.Create(formed, cs.AddMinutes((k3 - 2) * m), lo, hi) },
                    Tag = (inv ? "FVG INV " : "FVG R ") + r.FvgPct.ToString("0.#", CultureInfo.InvariantCulture) + "%",
                    Why = (d > 0 ? "bullish" : "bearish") + " " + m + "-min FVG " + lo.ToString("0.00", CultureInfo.InvariantCulture) + " – " + hi.ToString("0.00", CultureInfo.InvariantCulture) + " • " + (td > 0 ? "BUY" : "SELL") + (inv ? " stop (INVERTED) at " : " limit at ") + r.FvgPct.ToString("0.#", CultureInfo.InvariantCulture) + "% = " + lv.ToString("0.00", CultureInfo.InvariantCulture) + " until " + cancel.ToString("HH:mm") + " • stop −$" + r.StopUsd.ToString("N0", CultureInfo.InvariantCulture) + " • target +$" + r.TargetUsd.ToString("N0", CultureInfo.InvariantCulture) });
            }
            return o;
        }
    }
    public static class KeystoneOpenFvg
    {
        public static KeystoneOpenFvgDay Run(List<KeystoneArcBar> session, KeystoneOrbRule r, string symbol)
        {
            if (session == null || session.Count == 0) return null;
            var last = session[session.Count - 1].Time.AddMinutes(-1); DateTime day = last.Hour >= 18 ? last.Date.AddDays(1) : last.Date;
            DateTime open = day.AddHours(r.OpenHhmm / 100).AddMinutes(r.OpenHhmm % 100), exit = day.AddHours(r.ExitHhmm / 100).AddMinutes(r.ExitHhmm % 100);
            if (r.OpenHhmm >= 1800) open = open.AddDays(-1); if (r.ExitHhmm >= 1800) exit = exit.AddDays(-1);   // a session open from 18:00 (Asia 20:00) is the evening before
            double pv = KeystoneMoveStudy.PointValue(symbol), cost = KeystoneMoveStudy.Cost(symbol); int q = Math.Max(1, r.Contracts); int m = Math.Max(1, r.FvgMinutes);
            var res = new KeystoneOpenFvgDay { Day = day, StopPts = r.StopUsd / (pv * q), TargetPts = r.TargetUsd / (pv * q) };
            DateTime cOpen = open.AddMinutes(-m * Math.Max(0, Math.Min(1, r.FvgFrom)));   // the first 5-minute candle counted
            var candles = new List<double[]>();   // o, h, l, c
            double co = double.NaN, ch = double.MinValue, cl = double.MaxValue, cc = double.NaN; int lastFvg = -10;
            double tk = KeystoneMoveStudy.TickSize(symbol);
            // the order's price on the tick (a tie goes the safer way: a buy lower, a sell higher)
            Func<double> level = () => { double v = res.Dir > 0 ? res.ZoneHi - r.FvgPct / 100.0 * (res.ZoneHi - res.ZoneLo) : res.ZoneLo + r.FvgPct / 100.0 * (res.ZoneHi - res.ZoneLo); return res.Dir > 0 ? Math.Floor(v / tk + 0.5 - 1e-9) * tk : Math.Ceiling(v / tk - 0.5 + 1e-9) * tk; };
            // what was known at 09:30: the overnight move and where the open sits in the overnight range
            double onOpen = session[0].Open, onHi = double.MinValue, onLo = double.MaxValue, o930 = double.NaN;
            foreach (var b0 in session) { if (b0.Time <= open) { onHi = Math.Max(onHi, b0.High); onLo = Math.Min(onLo, b0.Low); } else { o930 = b0.Open; break; } }
            int minStack = Math.Max(1, r.MinStack); bool armed = false, rowOnly = r.JoinMode == "ROW", frozen = false;
            foreach (var b in session)
            {
                if (b.Time <= cOpen) continue; DateTime ot = b.Time.AddMinutes(-1);
                if (res.Filled)
                {
                    double stop = res.Entry - res.Dir * res.StopPts, tgt = res.Entry + res.Dir * res.TargetPts;
                    if (res.Dir > 0 ? b.Low <= stop : b.High >= stop) { res.Exit = stop; res.Reason = "STOP"; res.ExitTime = b.Time; break; }
                    if (res.Dir > 0 ? b.High >= tgt : b.Low <= tgt) { res.Exit = tgt; res.Reason = "TARGET"; res.ExitTime = b.Time; break; }
                    if (b.Time >= exit) { res.Exit = b.Close; res.Reason = "TIME EXIT"; res.ExitTime = b.Time; break; }
                    continue;
                }
                if (b.Time > exit) break;
                // a working limit order at the zone's level (once the zone has enough FVGs in a row)
                if (armed)
                {
                    double lv = res.Entry;
                    bool touch = res.Dir > 0 ? b.Low <= lv : b.High >= lv;
                    if (touch)
                    {
                        double fill = res.Dir > 0 ? Math.Min(lv, b.Open) : Math.Max(lv, b.Open); res.Entry = fill; res.Filled = true; res.FillTime = b.Time;
                        double stop = fill - res.Dir * res.StopPts;
                        if (res.Dir > 0 ? b.Low <= stop : b.High >= stop) { res.Exit = stop; res.Reason = "STOP"; res.ExitTime = b.Time; break; }
                        continue;
                    }
                }
                // the 5-minute candle this minute belongs to
                int k = (int)Math.Floor((ot - cOpen).TotalMinutes / m);
                if (k != candles.Count) { if (!double.IsNaN(co)) { candles.Add(new[] { co, ch, cl, cc }); } co = double.NaN; ch = double.MinValue; cl = double.MaxValue; while (candles.Count < k) candles.Add(null); }
                if (double.IsNaN(co)) co = b.Open; ch = Math.Max(ch, b.High); cl = Math.Min(cl, b.Low); cc = b.Close;
                bool closes = (int)Math.Floor((b.Time - cOpen).TotalMinutes) % m == 0;
                if (!closes) continue;
                candles.Add(new[] { co, ch, cl, cc }); co = double.NaN; ch = double.MinValue; cl = double.MaxValue;
                int n = candles.Count; if (n < 3 || candles[n - 1] == null || candles[n - 2] == null || candles[n - 3] == null) continue;
                var c1 = candles[n - 3]; var c3 = candles[n - 1]; int fd = c3[2] > c1[1] ? 1 : c3[1] < c1[2] ? -1 : 0;
                if (res.Dir != 0 && !armed && (rowOnly ? (fd != res.Dir || lastFvg != n - 2) : fd == -res.Dir)) { res.Reason = "FILTER: ONLY " + res.Stack + " FVG IN A ROW (wanted " + minStack + ")"; res.Dir = 0; return res; }
                if (fd == 0) continue;
                double lo = fd > 0 ? c1[1] : c3[1], hi = fd > 0 ? c3[2] : c1[2];
                if (res.Dir == 0)
                {
                    if (r.Side != 0 && fd != r.Side) { res.Reason = "FIRST FVG AGAINST THE SIDE"; return res; }
                    if (r.Overnight == "WITH" || r.Overnight == "AGAINST") { int om = Math.Sign(o930 - onOpen); if (om == 0 || (r.Overnight == "WITH") != (om == fd)) { res.Reason = "FILTER: OVERNIGHT NOT " + r.Overnight + " THE SIDE"; return res; } }
                    if ((r.OpenPos == "LOW" || r.OpenPos == "MID" || r.OpenPos == "HIGH") && onHi > onLo && !double.IsNaN(o930))
                    {
                        double pos = (o930 - onLo) / (onHi - onLo); if (fd < 0) pos = 1 - pos; string pz = pos <= 1 / 3.0 ? "LOW" : pos < 2 / 3.0 ? "MID" : "HIGH";
                        if (pz != r.OpenPos) { res.Reason = "FILTER: 09:30 OPEN " + pz + " IN THE OVERNIGHT RANGE (wanted " + r.OpenPos + ")"; return res; }
                    }
                    res.Dir = fd; res.ZoneLo = lo; res.ZoneHi = hi; res.Stack = 1; lastFvg = n - 1; res.SetupTime = b.Time; res.ZoneStart = cOpen.AddMinutes((n - 3) * m); res.Entry = level(); res.Fvgs.Add(Tuple.Create(b.Time, res.ZoneStart, lo, hi));
                }
                else if (fd == res.Dir && (rowOnly ? lastFvg == n - 2 : !frozen)) { res.ZoneLo = Math.Min(res.ZoneLo, lo); res.ZoneHi = Math.Max(res.ZoneHi, hi); res.Stack++; lastFvg = n - 1; res.SetupTime = b.Time; res.Entry = level(); res.Fvgs.Add(Tuple.Create(b.Time, cOpen.AddMinutes((n - 3) * m), lo, hi)); }
                else if (!rowOnly && fd == -res.Dir && armed) { frozen = true; continue; }   // an opposite FVG: the zone stops growing
                else if (!armed) { res.Reason = "FILTER: ONLY " + res.Stack + " FVG IN A ROW (wanted " + minStack + ")"; res.Dir = 0; return res; }
                else continue;
                if (res.Stack < minStack) continue;
                if (!armed && r.ZoneByHhmm > 0 && b.Time > day.AddHours(r.ZoneByHhmm / 100).AddMinutes(r.ZoneByHhmm % 100)) { res.Reason = "FILTER: ZONE SET AFTER " + (r.ZoneByHhmm / 100).ToString("00") + ":" + (r.ZoneByHhmm % 100).ToString("00"); res.Dir = 0; return res; }
                armed = true; res.Stages.Add(Tuple.Create(b.Time, res.ZoneLo, res.ZoneHi, res.Entry));
            }
            if (!armed && res.Dir != 0) { res.Reason = "FILTER: ONLY " + res.Stack + " FVG" + (res.Stack == 1 ? "" : "S") + " IN THE ZONE (wanted " + minStack + ")"; res.Dir = 0; }
            if (res.Filled)
            {
                if (res.ExitTime == DateTime.MinValue) { var lb = session[session.Count - 1]; res.Exit = lb.Close; res.Reason = "SESSION END"; res.ExitTime = lb.Time; }
                res.Points = (res.Exit - res.Entry) * res.Dir; res.Pnl = res.Points * pv * q - cost * q;
            }
            return res;
        }
    }

    // 🤖 AI CONFLUENCE: the studio's strategies run in the background on the session; a setup becomes an AI signal only when others agree —
    // another strategy's setup the same way within 15 minutes, the price on the right side of the session VWAP, the last 5 minutes moving
    // that way. Score = how many agree (the setup itself counts 1); minScore+ = a strong setup (stop from the setup, target at least 1.5R).
    public static class KeystoneConfluence
    {
        public static readonly int[] Kinds = { 1, 3, 5, 8, 9, 10 };
        public static string Short(int kind) { switch (kind) { case 1: return "FVG 50%"; case 3: return "FVG CLOSE"; case 5: return "BH"; case 8: return "OPENING DRIVE"; case 9: return "ORB 15"; case 10: return "ORB 30"; default: return "SETUP " + kind; } }
        public static double Vwap(IList<KeystoneArcBar> bars, int upto)
        {
            double pv = 0, v = 0; for (int i = 0; i <= upto && i < bars.Count; i++) { double w = Math.Max(1, bars[i].Volume); pv += w * (bars[i].High + bars[i].Low + bars[i].Close) / 3; v += w; }
            return v > 0 ? pv / v : double.NaN;
        }
        public static List<KeystoneReplaySignal> Find(List<KeystoneArcBar> session, string symbol, List<KeystoneArcBar> prior, int minScore = 3, Func<int, List<KeystoneReplaySignal>> source = null)
        {
            var res = new List<KeystoneReplaySignal>(); if (session == null || session.Count < 10) return res;
            var all = new List<Tuple<int, KeystoneReplaySignal>>();
            foreach (var k in Kinds) { List<KeystoneReplaySignal> sg; try { sg = source != null ? source(k) : KeystoneReplaySignals.Build(k, session, symbol, null, 0, prior); } catch { sg = null; } if (sg != null) foreach (var x in sg) if (x.Dir != 0 && !double.IsNaN(x.Entry)) all.Add(Tuple.Create(k, x)); }
            foreach (var c in all)
            {
                var s = c.Item2; int idx = -1; for (int i = 0; i < session.Count && session[i].Time <= s.Time; i++) idx = i; if (idx < 5) continue;
                var why = new List<string> { Short(c.Item1) };
                foreach (var k in all.Where(o => o.Item1 != c.Item1 && o.Item2.Dir == s.Dir && Math.Abs((o.Item2.Time - s.Time).TotalMinutes) <= 15).Select(o => o.Item1).Distinct()) why.Add(Short(k));
                double close = session[idx].Close, vw = Vwap(session, idx);
                if (!double.IsNaN(vw) && (s.Dir > 0 ? close > vw : close < vw)) why.Add("VWAP");
                if (Math.Sign(close - session[idx - 5].Close) == s.Dir) why.Add("5-MIN MOVE");
                int score = why.Count; if (score < minScore) continue;
                double risk = !double.IsNaN(s.Stop) ? Math.Abs(s.Entry - s.Stop) : 0;
                if (risk <= 0) { double hi = session.Skip(Math.Max(0, idx - 14)).Take(15).Max(b => b.High), lo = session.Skip(Math.Max(0, idx - 14)).Take(15).Min(b => b.Low); risk = Math.Max(KeystoneMoveStudy.IsMgc(symbol) ? 0.5 : 4, (hi - lo) / 2); }
                double reward = !double.IsNaN(s.Target) ? Math.Abs(s.Target - s.Entry) : 0; if (reward < 1.5 * risk) reward = 1.5 * risk;
                res.Add(new KeystoneReplaySignal { Time = s.Time, Exit = s.Exit, Dir = s.Dir, Entry = s.Entry, Stop = s.Entry - s.Dir * risk, Target = s.Entry + s.Dir * reward, Tier = score >= 4 ? "A" : "B", Tag = "🤖 AI " + score + ": " + string.Join(" + ", why) });
            }
            // one signal per side and 10 minutes (the best score, then the earliest)
            return res.OrderByDescending(x => x.Tag.Length).GroupBy(x => x.Dir + "|" + x.Time.Ticks / TimeSpan.FromMinutes(10).Ticks).Select(g => g.OrderByDescending(x => int.Parse(x.Tag.Substring(6, 1))).ThenBy(x => x.Time).First()).OrderBy(x => x.Time).ToList();
        }
    }

    public static class KeystoneReplaySignals
    {
        public static readonly string[] Names = { "MANUAL (NO SIGNALS)", "1M FVG • 50% LIMIT (BUY + SELL)", "5M FVG • 50% LIMIT (BUY + SELL)", "1M FVG • CANDLE CLOSE (BUY + SELL)", "FVG RETEST + BREAK (BUY + SELL)", "BH • BREAK OF HIGH / LOW", "GOLDEN • FIRST BH / FVG AFTER THE OPEN", "ASIAN 75 REVERSAL LEGS", "★ OPENING DRIVE • 10M CANDLE (TESTED)", "★ OPENING RANGE BREAK • 15M (TESTED • PROP PICK)", "★ OPENING RANGE BREAK • 30M 1R (TESTED)", "★ OPENING FVG • MNQ 5M 50% (−$2K / +$1K)", "★ FVG RETRACE • MNQ 5M 10% (FREQUENT • PROP ROI)", "★ FVG RETRACE • MNQ 1M 10% + VWAP (FAST ROTATION)", "FVG RETRACE • TPT 50K ROTATION (NOT RECOMMENDED)" };
        public static List<KeystoneOrbRule> Rules = KeystoneOpeningRange.Presets();   // kinds 8, 9, 10 (editable in the studio)
        public const int AsianKind = 7;   // ASIAN 75 REVERSAL LEGS: from 18:00; each leg runs to its stop (the next leg reverses) or the cycle's end, no price target

        // The day's signals for the chosen strategy on one instrument's session bars (detectors of the lab, both directions).
        // tpPts: the target for the FVG signals (0 = 30 MNQ / 3 MGC); their stop is beyond the FVG's first candle.
        public static List<KeystoneReplaySignal> Build(int kind, List<KeystoneArcBar> sessionBars, string symbol, KeystoneArcRunConfig basis, double tpPts)
        {
            return Build(kind, sessionBars, symbol, basis, tpPts, null);
        }

        // prior = earlier sessions: the setup grades (A / B / C) are learned from the setups before the replayed day.
        public static List<KeystoneReplaySignal> Build(int kind, List<KeystoneArcBar> sessionBars, string symbol, KeystoneArcRunConfig basis, double tpPts, List<KeystoneArcBar> prior)
        {
            var output = new List<KeystoneReplaySignal>(); if (kind <= 0 || sessionBars == null || sessionBars.Count < 10) return output;
            if (kind >= 8 && kind - 8 < Rules.Count) return KeystoneOpeningRange.Signals(Rules[kind - 8], sessionBars, prior, symbol);
            bool mgc = KeystoneMoveStudy.IsMgc(symbol); double tp = tpPts > 0 ? tpPts : (mgc ? 3 : 30), gap = mgc ? 0.3 : 3;
            if (kind <= 3)
            {
                int tf = kind == 2 ? 5 : 1; string fill = kind == 3 ? "CLOSE" : "50";
                foreach (var t in KeystoneIdeas.FvgTrades(sessionBars, symbol, tf, fill, 1800, 1700, -1, gap, tp, -1))
                    output.Add(new KeystoneReplaySignal { Time = t.EntryTime.AddMinutes(-1), Exit = t.ExitTime, Dir = t.Dir, Entry = t.Entry, Stop = t.Stop, Target = t.Target, Tag = tf + "M FVG" + (fill == "50" ? " 50%" : "") });
                return output;
            }
            var cfg = basis == null ? new KeystoneArcRunConfig() : basis.ShallowCopy();
            cfg.Scope = symbol; cfg.TradeSide = "BOTH"; cfg.SessionMode = "FULL_GLOBEX"; cfg.OutcomeModelEnabled = 1;
            DateTime dayStart = sessionBars[0].Time.AddMinutes(-1), dayEnd = sessionBars[sessionBars.Count - 1].Time;
            var all = prior != null && prior.Count > 0 && kind != 7 ? prior.Where(b => b.Time < sessionBars[0].Time).Concat(sessionBars).ToList() : sessionBars;
            cfg.Start = all[0].Time.AddMinutes(-1); cfg.End = dayEnd;
            if (kind == 4) { cfg.StrategyCode = "FVG"; cfg.EnableFvg = 1; cfg.SetupMinutes = 5; }
            else if (kind == 5) { cfg.StrategyCode = "BH"; cfg.EnableBh = 1; cfg.EnableFvg = 0; cfg.SetupMinutes = 5; }
            else if (kind == 6) { cfg.StrategyCode = "GLD"; cfg.SetupMinutes = 5; cfg.GoldenTakeAll = 1; cfg.GoldenMaxTradesPerDay = 5; }
            else { cfg.StrategyCode = "ASIAN75"; cfg.SetupMinutes = 1; }
            var setup = cfg.SetupMinutes <= 1 ? all : KeystoneArcEngine.ToSetupBars(all, symbol, cfg.SetupMinutes);
            List<KeystoneArcEvent> ev;
            try { ev = KeystoneArcEngine.DetectAndResolve(all, setup, cfg); } catch { ev = new List<KeystoneArcEvent>(); }
            foreach (var e in ev.Where(x => x.EntryTime != DateTime.MinValue && x.EntryTime > dayStart && x.EntryTime <= dayEnd && !double.IsNaN(x.Entry) && string.Equals(x.Symbol, symbol, StringComparison.OrdinalIgnoreCase)))
                output.Add(new KeystoneReplaySignal { Time = e.EntryTime.AddMinutes(-1), Exit = e.ExitTime, Dir = e.Direction == "SHORT" ? -1 : 1, Entry = e.Entry, Stop = e.Stop, Target = e.Target, Tag = e.SetupClass ?? cfg.StrategyCode, Tier = e.QualityTier ?? string.Empty });
            return output.OrderBy(x => x.Time).ToList();
        }
    }

    // 🎯 REVERSAL FVG SCANNER (BUILD 2026-11-11i) — SIGNALS / ALERTS ONLY: it never places, changes or cancels an order (no link, no broker here).
    // The rule, on CLOSED 1-minute bars only (the signal at bar i reads bars[0..i], never later — tests/ReversalFvgTests.cs scrambles the bars after it):
    //   an aggressive move of ≥ D points (default 100; 60 / 150): the HIGH of the 40 minutes before a new LOW down to that low, the low within the last
    //   15 minutes (mirror for sells) → the FIRST opposite 3-candle FVG after that low (bullish: candle-3 low − candle-1 high ≥ 2 pts) → the zone
    //   [candle-1 high, candle-3 low]; proposal: entry = the gap's near edge (candle-3 low), stop = the low − 2 pts (risk 4 … 150 pts), targets 1R / 2R / 3R.
    //   ★ = the high-volume variant: the middle candle's volume ≥ 2 × the average of the 30 bars before (bars i−30 … i−3, as the research).
    //   Ported from the research program (aggfvg); the research's "one trade at a time" filter needs later fills, so the scanner shows every setup.
    //   MGC: the point thresholds × 0.1 (untested — the research is MNQ). Honest: Research below.
    public sealed class KeystoneRevFvgSignal
    {
        public string Symbol = "MNQ", Source = "LIVE"; public DateTime Time, ExtTime; public int Dir; public bool Star;
        public double D, Move, Ext, Opp, GapLo, GapHi, Entry, Stop, Risk, VolRatio;
        public bool Returned; public DateTime ReturnedAt = DateTime.MinValue; public bool Alerted;
        public readonly string[] Outcome = { "PENDING", "PENDING", "PENDING" }; public readonly double[] OutR = { double.NaN, double.NaN, double.NaN };
        public double Target(int r) { return Entry + Dir * r * Risk; }
        public string Key { get { return Symbol + "|" + Time.ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture) + "|" + (Dir > 0 ? "BUY" : "SELL") + "|" + D.ToString("0", CultureInfo.InvariantCulture); } }
        public string Same() { return Key + "|" + Entry.ToString("0.00", CultureInfo.InvariantCulture) + "|" + Stop.ToString("0.00", CultureInfo.InvariantCulture) + "|" + Star + "|" + GapLo.ToString("0.00", CultureInfo.InvariantCulture) + "|" + GapHi.ToString("0.00", CultureInfo.InvariantCulture); }
    }
    public static class KeystoneRevFvg
    {
        public const double DefaultMove = 100, GapPts = 2, StopPad = 2, MinRisk = 4, MaxRisk = 150, StarVol = 2, Cost = 1;
        public const int HighBars = 40, LowBars = 15, VolBars = 30, FillMinutes = 30;
        public static readonly double[] Moves = { 60, 100, 150 };
        public const string Research = "6 years MNQ: every setup −0.06 R/trade (slightly losing); ★ high-volume +0.18 R at 3R (≈60/yr; 2020–23 +0.41, 2024–26 +0.07): weak, possibly luck — practice / small size";
        public const string LogHeader = "logged,source,symbol,signal_time,side,move_d,move_pts,star,vol_x,gap_low,gap_high,entry,stop,risk_pts,target_1r,target_2r,target_3r,came_back,came_back_at,outcome_1r,r_1r,outcome_2r,r_2r,outcome_3r,r_3r";
        public static double Scale(string symbol) { return KeystoneMoveStudy.IsMgc(symbol) ? 0.1 : 1; }
        static DateTime Sess(DateTime openT) { return openT.AddHours(6).Date; }   // the session from 18:00 (bar OPEN times, as the research)
        static DateTime OpenT(KeystoneArcBar b) { return b.Time.AddMinutes(-1); }

        // the signal formed by the CLOSE of bar i (null = none) — reads bars[0..i] only
        public static KeystoneRevFvgSignal At(IList<KeystoneArcBar> bars, int i, int dir, double D, string symbol)
        {
            if (bars == null || i < 45 || i >= bars.Count || dir == 0) return null; double sc = Scale(symbol), gapMin = GapPts * sc;
            var c3 = bars[i]; var c1 = bars[i - 2]; if ((OpenT(c3) - OpenT(c1)).TotalMinutes != 2) return null;
            bool gap = dir > 0 ? c3.Low - c1.High >= gapMin : c1.Low - c3.High >= gapMin; if (!gap) return null;
            var s3 = Sess(OpenT(c3)); int ext = -1; double ev = dir > 0 ? double.MaxValue : double.MinValue;
            for (int k = i - LowBars; k <= i - 1; k++) { if (Sess(OpenT(bars[k])) != s3) continue; if (dir > 0 ? bars[k].Low < ev : bars[k].High > ev) { ev = dir > 0 ? bars[k].Low : bars[k].High; ext = k; } }
            if (ext < 0) return null; double op = dir > 0 ? double.MinValue : double.MaxValue;
            for (int k = Math.Max(0, ext - HighBars); k < ext; k++) { if (Sess(OpenT(bars[k])) != s3) continue; op = dir > 0 ? Math.Max(op, bars[k].High) : Math.Min(op, bars[k].Low); }
            if (op == double.MinValue || op == double.MaxValue || Math.Abs(op - ev) < D * sc) return null;
            for (int k = ext + 2; k < i; k++) if (dir > 0 ? bars[k].Low - bars[k - 2].High >= gapMin : bars[k - 2].Low - bars[k].High >= gapMin) return null;   // the FIRST gap after the extreme
            var c2 = bars[i - 1]; double avgV = 0; int nv = 0; for (int k = i - VolBars; k < i - 2; k++) { avgV += bars[k].Volume; nv++; } avgV /= Math.Max(1, nv);
            double entry = dir > 0 ? c3.Low : c3.High, stop = dir > 0 ? ev - StopPad * sc : ev + StopPad * sc, risk = Math.Abs(entry - stop);
            if (risk < MinRisk * sc || risk > MaxRisk * sc) return null;
            return new KeystoneRevFvgSignal { Symbol = (symbol ?? "MNQ").ToUpperInvariant(), Time = c3.Time, ExtTime = bars[ext].Time, Dir = dir, D = D, Move = Math.Abs(op - ev), Ext = ev, Opp = op,
                GapLo = dir > 0 ? c1.High : c3.High, GapHi = dir > 0 ? c3.Low : c1.Low, Entry = entry, Stop = stop, Risk = risk, VolRatio = avgV > 0 ? c2.Volume / avgV : 0, Star = avgV > 0 && c2.Volume >= StarVol * avgV };
        }
        // every signal on these (closed) bars, oldest first
        public static List<KeystoneRevFvgSignal> Scan(IList<KeystoneArcBar> bars, double D, bool buys, bool sells, string symbol)
        {
            var o = new List<KeystoneRevFvgSignal>(); if (bars == null) return o;
            for (int i = 45; i < bars.Count; i++) { if (buys) { var s = At(bars, i, 1, D, symbol); if (s != null) o.Add(s); } if (sells) { var s = At(bars, i, -1, D, symbol); if (s != null) o.Add(s); } }
            return o;
        }
        // forward evidence from the bars AFTER the signal (closed ones): did price come back into the zone, and each target's outcome — the research's
        // own rules: a LIMIT at the entry filled when price trades a tick through it within 30 minutes (the target reached first = NO FILL), then
        // PESSIMISTIC (stop + target in one minute = a loss), the session's end = the close; R after 1 point of costs
        public static void Track(KeystoneRevFvgSignal s, IList<KeystoneArcBar> bars, double tick)
        {
            if (s == null || bars == null) return; int i0 = -1; for (int k = 0; k < bars.Count; k++) if (bars[k].Time == s.Time) { i0 = k; break; } if (i0 < 0) return;
            var ss = Sess(OpenT(bars[i0])); int dir = s.Dir; tick = tick > 0 ? tick : 0.25;
            if (!s.Returned) for (int k = i0 + 1; k < bars.Count; k++) { if (Sess(OpenT(bars[k])) != ss) break; if (dir > 0 ? bars[k].Low <= s.Entry : bars[k].High >= s.Entry) { s.Returned = true; s.ReturnedAt = bars[k].Time; break; } }
            for (int ri = 0; ri < 3; ri++)
            {
                if (s.Outcome[ri] != "PENDING") continue; double R = ri + 1, tp = s.Target(ri + 1); int fill = -1; bool closed = false;
                for (int k = i0 + 1; k < Math.Min(bars.Count, i0 + 1 + FillMinutes); k++)
                {
                    var x = bars[k]; if (Sess(OpenT(x)) != ss) { closed = true; break; }
                    bool thr = dir > 0 ? x.Low <= s.Entry - tick : x.High >= s.Entry + tick, gone = dir > 0 ? x.High >= tp : x.Low <= tp;
                    if (thr) { fill = k; break; } if (gone) { closed = true; break; }
                }
                if (fill < 0) { if (closed || bars.Count >= i0 + 1 + FillMinutes) s.Outcome[ri] = "NO FILL"; continue; }
                for (int k = fill; k < bars.Count; k++)
                {
                    var x = bars[k]; double pts = double.NaN; string w = "";
                    if (Sess(OpenT(x)) != ss) { pts = dir * (bars[k - 1].Close - s.Entry); w = "SESSION END"; }
                    else
                    {
                        bool hs = dir > 0 ? x.Low <= s.Stop : x.High >= s.Stop, ht = dir > 0 ? x.High >= tp : x.Low <= tp;
                        if (k == fill) { if (hs) { pts = -s.Risk; w = "LOSS"; } }
                        else if (hs) { pts = -s.Risk; w = "LOSS"; } else if (ht) { pts = R * s.Risk; w = "WIN"; }
                    }
                    if (w != "") { s.Outcome[ri] = w; s.OutR[ri] = (pts - Cost * Scale(s.Symbol)) / s.Risk; break; }
                }
            }
        }
        // the order panel's fields for this proposal (price, stop / target in POINTS from the entry) — values only: nothing is sent from here
        public static Tuple<double, double, double> Proposal(KeystoneRevFvgSignal s, int r) { return s == null ? null : Tuple.Create(s.Entry, s.Risk, Math.Max(1, Math.Min(3, r)) * s.Risk); }
        public static string Line(KeystoneRevFvgSignal s, DateTime logged)
        {
            var ic = CultureInfo.InvariantCulture; Func<double, string> f = v => double.IsNaN(v) ? "" : v.ToString("0.##", ic);
            return string.Join(",", logged.ToString("yyyy-MM-dd HH:mm:ss", ic), s.Source, s.Symbol, s.Time.ToString("yyyy-MM-dd HH:mm", ic), s.Dir > 0 ? "BUY" : "SELL", f(s.D), f(s.Move), s.Star ? "★" : "", f(s.VolRatio), f(s.GapLo), f(s.GapHi), f(s.Entry), f(s.Stop), f(s.Risk),
                f(s.Target(1)), f(s.Target(2)), f(s.Target(3)), s.Returned ? "YES" : "NO", s.Returned ? s.ReturnedAt.ToString("yyyy-MM-dd HH:mm", ic) : "", s.Outcome[0], f(s.OutR[0]), s.Outcome[1], f(s.OutR[1]), s.Outcome[2], f(s.OutR[2]));
        }
        public static string Words(KeystoneRevFvgSignal s, int qty)
        {
            double pv = KeystoneMoveStudy.PointValue(s.Symbol) * Math.Max(1, qty); Func<double, string> px = v => v.ToString("0.00", CultureInfo.InvariantCulture); Func<double, string> usd = v => "$" + Math.Round(Math.Abs(v)).ToString("N0", CultureInfo.InvariantCulture);
            return (s.Dir > 0 ? "BUY" : "SELL") + (s.Star ? " ★" : "") + " · entry " + px(s.Entry) + " · stop " + px(s.Stop) + " (−" + usd(s.Risk * pv) + ") · 1R " + px(s.Target(1)) + " (+" + usd(s.Risk * pv) + ") · 2R " + px(s.Target(2)) + " (+" + usd(2 * s.Risk * pv) + ") · 3R " + px(s.Target(3)) + " (+" + usd(3 * s.Risk * pv) + ") × " + Math.Max(1, qty);
        }
    }

    public sealed class KeystoneReplayFill { public DateTime EntryTime, ExitTime; public string Symbol = string.Empty, Side = string.Empty, Reason = string.Empty; public int Qty; public double Entry, Exit, Points, Net, Gross, Fee; }

    // ⏱ item 36: REAL TICKS in the Backtest Studio replay — one trade print (time, price, size); the tick cache (Studio\TickCache\<SYM>\<day>.bin) loads a day once
    public struct KeystoneTick { public DateTime Time; public double Price; public long Volume; }
    public static class KeystoneTickCache
    {
        public static string FileOf(string folder, string symbol, DateTime day) { return Path.Combine(folder ?? "", "TickCache", (symbol ?? "MNQ").ToUpperInvariant(), day.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture) + ".bin"); }
        // compact: "KTK1", the count, the source, then per tick: time ticks (long), price (double), volume (int)
        public static void Save(string folder, string symbol, DateTime day, IList<KeystoneTick> ticks, string source)
        {
            if (ticks == null || ticks.Count == 0) return; var f = FileOf(folder, symbol, day); Directory.CreateDirectory(Path.GetDirectoryName(f));
            using (var bw = new BinaryWriter(File.Create(f))) { bw.Write("KTK1"); bw.Write(ticks.Count); bw.Write(source ?? "TICKS"); foreach (var t in ticks) { bw.Write(t.Time.Ticks); bw.Write(t.Price); bw.Write((int)Math.Min(int.MaxValue, t.Volume)); } }
        }
        public static List<KeystoneTick> Load(string folder, string symbol, DateTime day, out string source)
        {
            source = ""; var f = FileOf(folder, symbol, day); if (!File.Exists(f)) return null;
            try { using (var br = new BinaryReader(File.OpenRead(f))) { if (br.ReadString() != "KTK1") return null; int n = br.ReadInt32(); source = br.ReadString(); var o = new List<KeystoneTick>(n); for (int i = 0; i < n; i++) o.Add(new KeystoneTick { Time = new DateTime(br.ReadInt64()), Price = br.ReadDouble(), Volume = br.ReadInt32() }); return o; } }
            catch { return null; }
        }
        // 📦 BUILD 11f — EXPORT TICKS for research: the cached real ticks of a date range → one compact CSV.gz (time to the ms, price, size, side — empty: not in the cache)
        public static int ExportCsvGz(string folder, IList<string> symbols, DateTime from, DateTime to, string outFile)
        {
            int n = 0; Directory.CreateDirectory(Path.GetDirectoryName(outFile));
            using (var fs = File.Create(outFile)) using (var gz = new System.IO.Compression.GZipStream(fs, System.IO.Compression.CompressionMode.Compress)) using (var sw = new StreamWriter(gz, new UTF8Encoding(false)))
            {
                sw.Write("symbol,time_ny,price,size,side\n");
                foreach (var sym in symbols ?? new List<string>())
                    for (var d = from.Date; d <= to.Date; d = d.AddDays(1))
                    {
                        string src; var tl = Load(folder, sym, d, out src); if (tl == null) continue;
                        foreach (var t in tl) { sw.Write(sym); sw.Write(','); sw.Write(t.Time.ToString("yyyy-MM-dd HH:mm:ss.fff", CultureInfo.InvariantCulture)); sw.Write(','); sw.Write(t.Price.ToString("0.00###", CultureInfo.InvariantCulture)); sw.Write(','); sw.Write(t.Volume.ToString(CultureInfo.InvariantCulture)); sw.Write(",\n"); n++; }
                    }
            }
            return n;
        }
        // 1-second bars → ticks (the fallback): each second gives its open, its high / low in the order the close suggests, its close — at that second
        public static List<KeystoneTick> FromSeconds(IList<KeystoneArcBar> secs)
        {
            var o = new List<KeystoneTick>(); if (secs == null) return o;
            foreach (var b in secs)
            {
                var t0 = b.Time.AddSeconds(-1); long v = Math.Max(1, b.Volume / 4); bool upFirst = b.Close < b.Open;
                o.Add(new KeystoneTick { Time = t0, Price = b.Open, Volume = v }); o.Add(new KeystoneTick { Time = t0.AddMilliseconds(250), Price = upFirst ? b.High : b.Low, Volume = v });
                o.Add(new KeystoneTick { Time = t0.AddMilliseconds(500), Price = upFirst ? b.Low : b.High, Volume = v }); o.Add(new KeystoneTick { Time = b.Time.AddMilliseconds(-1), Price = b.Close, Volume = v });
            }
            return o;
        }
    }
    // 📜 BUILD 11f — the Backtest Studio's TRADES LOG (the user's 1-minute scalps): every closed trade with its seconds, size (+ adds), prices, $ after costs, points,
