    public static class KeystonePracticeTrades
    {
        static readonly CultureInfo IC = CultureInfo.InvariantCulture;
        public const string Header = "date,entry_ny,exit_ny,symbol,side,size,adds,entry,exit,net_usd,points,mfe_usd,mae_usd,seconds,how,attempt,preset,note";
        static string C(string x) { return (x ?? "").Replace(",", " ").Replace("\n", " ").Replace("\r", " "); }
        public static string Line(KeystonePracticeTrade t)
        {
            return string.Join(",", t.Entry.ToString("yyyy-MM-dd", IC), t.Entry.ToString("HH:mm:ss", IC), t.Exit.ToString("HH:mm:ss", IC), C(t.Symbol), t.Side, t.Qty, t.Adds, t.EntryPx.ToString("0.00", IC), t.ExitPx.ToString("0.00", IC), t.Net.ToString("0.00", IC), t.Points.ToString("0.00", IC),
                t.Mfe.ToString("0.00", IC), t.Mae.ToString("0.00", IC), t.Seconds.ToString("0", IC), C(t.How), t.Attempt, C(t.Preset), C(t.Note));
        }
        public static KeystonePracticeTrade Parse(string line)
        {
            var a = (line ?? "").Split(','); if (a.Length < 18 || a[0] == "date") return null;
            try
            {
                var d = DateTime.ParseExact(a[0], "yyyy-MM-dd", IC); Func<int, double> D = k => double.Parse(a[k], NumberStyles.Float, IC);
                var t = new KeystonePracticeTrade { Entry = d + TimeSpan.Parse(a[1], IC), Exit = d + TimeSpan.Parse(a[2], IC), Symbol = a[3], Side = a[4], Qty = int.Parse(a[5], IC), Adds = int.Parse(a[6], IC), EntryPx = D(7), ExitPx = D(8), Net = D(9), Points = D(10), Mfe = D(11), Mae = D(12), How = a[14], Attempt = int.Parse(a[15], IC), Preset = a[16], Note = a[17] };
                if (t.Exit < t.Entry) t.Exit = t.Exit.AddDays(1); return t;
            }
            catch { return null; }
        }
        public static List<KeystonePracticeTrade> Load(string csv) { return (csv ?? "").Split('\n').Select(l => Parse(l.TrimEnd('\r'))).Where(t => t != null).ToList(); }
        static string Sg(double v) { return (v >= 0 ? "+" : "−") + "$" + Math.Abs(v).ToString("N2", IC); }
        // the longest win / loss runs (a $0 trade breaks both)
        public static int[] Streaks(IList<KeystonePracticeTrade> rows) { int w = 0, l = 0, bw = 0, bl = 0; foreach (var t in rows ?? new List<KeystonePracticeTrade>()) { if (t.Net > 0) { w++; l = 0; } else if (t.Net < 0) { l++; w = 0; } else { w = l = 0; } bw = Math.Max(bw, w); bl = Math.Max(bl, l); } return new[] { bw, bl }; }
        public static List<string[]> Totals(IList<KeystonePracticeTrade> rows)
        {
            rows = rows ?? new List<KeystonePracticeTrade>(); var t = new List<string[]> { new[] { "STAT", "VALUE" } }; int n = rows.Count, wn = rows.Count(x => x.Net > 0), ln = rows.Count(x => x.Net < 0); var st = Streaks(rows);
            t.Add(new[] { "trades", n.ToString(IC) }); t.Add(new[] { "win %", n == 0 ? "–" : (100.0 * wn / n).ToString("0.0", IC) + " % (" + wn + " / " + n + ")" });
            t.Add(new[] { "avg win / avg loss", (wn == 0 ? "–" : Sg(rows.Where(x => x.Net > 0).Average(x => x.Net))) + " / " + (ln == 0 ? "–" : Sg(rows.Where(x => x.Net < 0).Average(x => x.Net))) });
            t.Add(new[] { "expectancy per trade", n == 0 ? "–" : Sg(rows.Average(x => x.Net)) }); t.Add(new[] { "best / worst streak", st[0] + " wins / " + st[1] + " losses" });
            t.Add(new[] { "total", Sg(rows.Sum(x => x.Net)) }); t.Add(new[] { "avg duration", n == 0 ? "–" : rows.Average(x => x.Seconds).ToString("0", IC) + " s" });
            foreach (var g in rows.GroupBy(x => x.Entry.Date).OrderBy(g => g.Key)) t.Add(new[] { "P/L " + g.Key.ToString("ddd yyyy-MM-dd", IC), Sg(g.Sum(x => x.Net)) + " (" + g.Count() + " trade" + (g.Count() == 1 ? "" : "s") + ")" });
            return t;
        }
        public static List<KeystonePracticeTrade> Filter(IList<KeystonePracticeTrade> rows, string what, DateTime today, int attempt)
        {
            var l = (rows ?? new List<KeystonePracticeTrade>()).ToList(); return what == "TODAY" ? l.Where(x => x.Entry.Date == today.Date).ToList() : what == "ATTEMPT" ? l.Where(x => x.Attempt == attempt).ToList() : l;
        }
    }
    // 🧪 BUILD 11f — the PROBE ENTRY (practice only, the same simulated trader): 1 micro, wait N seconds, then ADD the rest when the open P/L ≥ +X ticks; else CLOSE (a)
    // or HOLD for a 1-minute candle closing the trade's way within M minutes (b), then add — or close when none came. Pure decisions (the studio does the orders).
    public static class KeystoneProbe
    {
        // after the wait: "ADD" / "CLOSE" / "WAIT" (mode b) — openTicks = the probe's open P/L in ticks
        public static string AfterWait(double openTicks, double needTicks, string mode) { return openTicks >= needTicks - 1e-9 ? "ADD" : mode == "WAIT" ? "WAIT" : "CLOSE"; }
        // mode b: a closed 1-minute candle → "ADD" (closes the trade's way), "CLOSE" (the minutes are over) or "" (keep waiting)
        public static string OnCandle(int dir, double open, double close, DateTime now, DateTime until) { if (dir > 0 ? close > open : close < open) return "ADD"; return now >= until ? "CLOSE" : ""; }
    }
    public sealed class KeystoneReplayTrader
    {
        /* ⏱ item 36 (BUILD 2026-11-11c): REAL TICKS — with a day's ticks every step is one real print at its real time (the clock moves by real time ×
           speed, so 1× = a minute in 60 seconds, moving like the market did); the forming candle = the saved minute's open + the high / low / close / volume
           of the ticks seen so far (clamped to the saved minute: the minute bar wins, mismatches are counted in TickNote); fills, the bracket and the
           practice floor only at tick prices in time order. Without ticks: the 1-second bars, else the old estimated path (TickSource "ESTIMATED") */
        List<KeystoneTick>[] barTicks; public string TickSource = "ESTIMATED", TickNote = ""; public int TickMismatch; long formingVol;
        public bool HasTicks { get { return barTicks != null; } }
        public void CopyTicks(KeystoneReplayTrader o) { if (o == null || o.barTicks == null || !ReferenceEquals(o.Bars, Bars)) return; barTicks = o.barTicks; TickSource = o.TickSource; TickNote = o.TickNote; TickMismatch = o.TickMismatch; }
        public void SetTicks(IList<KeystoneTick> ticks, string source)
        {
            if (ticks == null || ticks.Count == 0 || Bars.Count == 0) return; var bt = new List<KeystoneTick>[Bars.Count]; int bi = 0, mis = 0, used = 0;
            foreach (var t in ticks.OrderBy(x => x.Time))
            {
                while (bi < Bars.Count && t.Time >= Bars[bi].Time) bi++; if (bi >= Bars.Count) break; if (t.Time < Bars[bi].Time.AddMinutes(-1)) continue;
                if (bt[bi] == null) bt[bi] = new List<KeystoneTick>(); var b = Bars[bi]; double p = t.Price; if (p > b.High + 1e-9 || p < b.Low - 1e-9) { mis++; p = Math.Max(b.Low, Math.Min(b.High, p)); }
                bt[bi].Add(new KeystoneTick { Time = t.Time, Price = p, Volume = t.Volume }); used++;
            }
            for (int i = 0; i < bt.Length; i++) if (bt[i] != null && bt[i].Count > 0 && Math.Abs(bt[i][bt[i].Count - 1].Price - Bars[i].Close) > 1e-9) mis++;
            if (used == 0) return; barTicks = bt; TickSource = source ?? "TICKS"; TickMismatch = mis;
            TickNote = (TickSource == "SECONDS" ? "⏱ 1-second bars" : "⏱ real ticks") + " · " + used.ToString("N0", CultureInfo.InvariantCulture) + " prints" + (mis > 0 ? " · " + mis + " tick(s) outside / off the saved minute: the minute bar wins" : "");
        }
        List<KeystoneTick> TicksAt(int i) { return barTicks != null && i >= 0 && i < barTicks.Length ? barTicks[i] : null; }
        // the time of the next step (a tick's own time, or the estimated path's step)
        public DateTime NextTime()
        {
            if (Finished) return DateTime.MaxValue; var b = Bars[BarIndex]; var tl = TicksAt(BarIndex);
            if (tl != null && tl.Count > 0) return Step < tl.Count ? tl[Step].Time : b.Time;
            return b.Time.AddMinutes(-1).AddSeconds(60.0 * (Step + 1) / StepsPerBar);
        }
        public readonly List<KeystoneArcBar> Bars; public readonly string Symbol; public readonly int StepsPerBar;
        public int BarIndex, Step; public double Price; public DateTime Time;
        public int Position; public double AvgPrice, StopPts, TargetPts, Realized; public DateTime PositionTime;
        public List<KeystoneReplayFill> Fills = new List<KeystoneReplayFill>();
        public List<KeystoneReplayOrder> Orders = new List<KeystoneReplayOrder>(); int nextOrderId = 1;
        public double Tick { get { return tick; } }
        readonly double pv, cost, tick;
        public bool Live { get; private set; }   // LIVE: bars arrive from NinjaTrader's real-time feed (the last one is forming); no replay clock
        // LINKED to a real account (KeystoneAccountLink): the account is the truth — no simulated fills, no simulated stop / target /
        // order execution; your actions only change the intent, which the link sends to the account
        public bool Slave;
        public void Adopt(int qty, double avg, DateTime now) { if (Position == 0 && qty != 0) PositionTime = Time; Position = qty; AvgPrice = qty == 0 ? 0 : avg; }   // the REAL fill: a new entry's stop / target are measured from it (live: an add keeps the real stop's PRICE through Pull)
        // contracts added / taken off on the same side: the stop and the target stay at the SAME PRICE (user's request) — their distances follow
        // the new average, so the $ on the line is the exact profit / loss of every contract now open
        void KeepLevels(double oldAvg, int oldPos)
        {
            if (oldPos == 0 || Position == 0 || Math.Sign(oldPos) != Math.Sign(Position) || Math.Abs(oldAvg - AvgPrice) < 1e-12) return; int d = Math.Sign(Position);
            if (StopPts != 0) { double sp = oldAvg - d * StopPts; double ns = d * (AvgPrice - sp); StopPts = Math.Abs(ns) < 1e-9 ? -1e-6 : ns; }   // exactly at the new average = a break-even stop (−0.000001 locks $0), never "no stop"
            if (TargetPts > 0) { double tp = oldAvg + d * TargetPts; double nt = d * (tp - AvgPrice); if (nt > 1e-9) TargetPts = nt; }
        }   // the chart's clock (the bars' time zone)
        public void AddRealFill(KeystoneReplayFill f) { if (f == null) return; Fills.Add(f); Realized += f.Net; }

        // LIVE: the session so far (last bar = the forming one); prices then come in through LiveUpdate
        public static KeystoneReplayTrader LiveStart(List<KeystoneArcBar> sessionSoFar, string symbol, DateTime now)
        {
            var t = new KeystoneReplayTrader(new List<KeystoneArcBar>(sessionSoFar ?? new List<KeystoneArcBar>()), symbol, 4) { Live = true };
            t.BarIndex = Math.Max(0, t.Bars.Count - 1); t.Step = 1;
            if (t.Bars.Count > 0) t.Price = t.Bars[t.Bars.Count - 1].Close; t.Time = now;
            return t;
        }

        // LIVE: a new or updated 1-minute bar (bar.Time = its close time) and the current time; works orders and the bracket at the new price
        public void LiveUpdate(KeystoneArcBar bar, DateTime now)
        {
            if (!Live || bar == null) return;
            if (Bars.Count == 0 || bar.Time > Bars[Bars.Count - 1].Time) Bars.Add(new KeystoneArcBar { Symbol = bar.Symbol, Time = bar.Time, Open = bar.Open, High = bar.High, Low = bar.Low, Close = bar.Close, Volume = bar.Volume });
            else if (bar.Time == Bars[Bars.Count - 1].Time) { var l = Bars[Bars.Count - 1]; l.Open = bar.Open; l.High = bar.High; l.Low = bar.Low; l.Close = bar.Close; l.Volume = bar.Volume; }
            else return;   // an older bar: ignore
            BarIndex = Bars.Count - 1; Step = 1; Price = bar.Close; Time = now;
            if (!Slave) { CheckOrders(); CheckBracket(); }
        }

        public KeystoneReplayTrader(List<KeystoneArcBar> sessionBars, string symbol, int stepsPerBar)
        {
            Bars = sessionBars ?? new List<KeystoneArcBar>(); Symbol = (symbol ?? "MNQ").ToUpperInvariant(); StepsPerBar = Math.Max(4, stepsPerBar);
            pv = KeystoneMoveStudy.PointValue(Symbol); cost = KeystoneMoveStudy.Cost(Symbol); tick = KeystoneMoveStudy.TickSize(Symbol);
            BarIndex = 0; Step = 0; if (Bars.Count > 0) { Price = Bars[0].Open; Time = Bars[0].Time.AddMinutes(-1); }
        }

        public bool Finished { get { return BarIndex >= Bars.Count; } }
        public double Unrealized { get { return Position == 0 ? 0 : (Price - AvgPrice) * Position * pv; } }
        public double DayNet { get { return Realized + Unrealized; } }

        // The simulated price at step k (0 … StepsPerBar) of a 1-minute bar.
        public static double PathPrice(KeystoneArcBar b, int k, int steps, double tick)
        {
            bool highFirst = b.Close < b.Open || (b.Close == b.Open && b.High - b.Open < b.Open - b.Low);
            double a = highFirst ? b.High : b.Low, c = highFirst ? b.Low : b.High;
            double l0 = Math.Abs(a - b.Open), l1 = Math.Abs(c - a), l2 = Math.Abs(b.Close - c), total = l0 + l1 + l2, range = b.High - b.Low;
            if (total <= 0 || steps < 3) return b.Close;
            // the steps where the walk stands exactly on the first extreme (k1) and the second (k2)
            int k1 = Math.Max(1, Math.Min(steps - 2, (int)Math.Round(steps * l0 / total))), k2 = Math.Max(k1 + 1, Math.Min(steps - 1, (int)Math.Round(steps * (l0 + l1) / total)));
            if (k <= 0) return b.Open; if (k >= steps) return b.Close; if (k == k1) return a; if (k == k2) return c;
            double from, to; int ka, kb; int leg;
            if (k < k1) { from = b.Open; to = a; ka = 0; kb = k1; leg = 0; } else if (k < k2) { from = a; to = c; ka = k1; kb = k2; leg = 1; } else { from = c; to = b.Close; ka = k2; kb = steps; leg = 2; }
            double t = (k - ka) / (double)Math.Max(1, kb - ka), p = from + (to - from) * t;
            // realistic wiggle: smooth swings that vanish at the leg's ends + one-tick jitter (seeded by the minute, so a replay
            // is the same every time); kept inside the minute's real high / low, so the open, high, low and close stay exact
            unchecked
            {
                long seed = b.Time.Ticks / 600000000L * 31 + leg * 7 + 1; Func<long, double> rnd = n => { long x = (seed * 6364136223846793005L + n * 1442695040888963407L) >> 11; return (x & 0xFFFFF) / (double)0xFFFFF; };
                double f1 = 2 + 3 * rnd(1), f2 = 5 + 4 * rnd(2), ph1 = 6.283 * rnd(3), ph2 = 6.283 * rnd(4), amp = 0.22 * range;
                p += amp * Math.Sin(Math.PI * t) * (0.65 * Math.Sin(6.283 * f1 * t + ph1) + 0.35 * Math.Sin(6.283 * f2 * t + ph2));
                p += (rnd(100 + k) - 0.5) * 2 * tick;
            }
            double lo = Math.Min(from, to) - 0.2 * range, hi = Math.Max(from, to) + 0.2 * range;
            p = Math.Max(Math.Max(lo, b.Low), Math.Min(Math.Min(hi, b.High), p));
            return Math.Round(p / tick) * tick;
        }

        // The candles so far in the chosen timeframe, the last one still forming (its close = the current price).
        // one candle per trading session (18:00 New York → 17:00)
        public static List<KeystoneArcBar> DailyCandles(List<KeystoneArcBar> bars)
        {
            var outD = new List<KeystoneArcBar>(); if (bars == null || bars.Count == 0) return outD;
            foreach (var g in bars.GroupBy(b => KeystoneStudioStore.SessionOf(b.Time)).OrderBy(g => g.Key))
            {
                var l = g.OrderBy(b => b.Time).ToList();
                outD.Add(new KeystoneArcBar { Symbol = l[0].Symbol, Time = l[l.Count - 1].Time, Open = l[0].Open, High = l.Max(b => b.High), Low = l.Min(b => b.Low), Close = l[l.Count - 1].Close, Volume = l.Sum(b => b.Volume) });
            }
            return outD;
        }
        public List<KeystoneArcBar> Candles(int minutes)
        {
            var done = Live ? Bars.ToList() : Bars.Take(BarIndex).ToList();
            var tlF = !Live && !Finished ? TicksAt(BarIndex) : null;
            if (tlF != null && tlF.Count > 0) { if (Step > 0) { var b = Bars[BarIndex]; var part = new KeystoneArcBar { Symbol = b.Symbol, Time = b.Time, Open = b.Open, High = b.Open, Low = b.Open, Close = Price, Volume = formingVol }; for (int k = 0; k < Step && k < tlF.Count; k++) { part.High = Math.Max(part.High, tlF[k].Price); part.Low = Math.Min(part.Low, tlF[k].Price); } done.Add(part); } }
            else if (!Live && !Finished && Step > 0) { var b = Bars[BarIndex]; var part = new KeystoneArcBar { Symbol = b.Symbol, Time = b.Time, Open = b.Open, High = b.Open, Low = b.Open, Close = Price };
                for (int k = 0; k <= Step; k++) { double p = PathPrice(b, k, StepsPerBar, tick); part.High = Math.Max(part.High, p); part.Low = Math.Min(part.Low, p); } done.Add(part); }
            if (minutes >= 1440) return DailyCandles(done);
            return KeystoneEngLab.Candles(done, Math.Max(1, minutes));
        }

        // Working orders: a LIMIT buys at or below its price (sells at or above); a STOP buys once price reaches it from below
        // (sells from above). Filled at the order price on the step that reaches it.
        public KeystoneReplayOrder Place(string type, int dir, int qty, double price)
        {
            var o = new KeystoneReplayOrder { Id = nextOrderId++, Type = type == "STOP" ? "STOP" : "LIMIT", Dir = dir > 0 ? 1 : -1, Qty = Math.Max(1, qty), Price = Math.Round(price / tick) * tick };
            Orders.Add(o); return o;
        }
        public void CancelOrders() { Orders.Clear(); }
        void CheckOrders()
        {
            foreach (var o in Orders.ToList())
            {
                bool hit = o.Type == "LIMIT" ? (o.Dir > 0 ? Price <= o.Price + 1e-9 : Price >= o.Price - 1e-9) : (o.Dir > 0 ? Price >= o.Price - 1e-9 : Price <= o.Price + 1e-9);
                if (!hit) continue;
                Orders.Remove(o); double keep = Price; Price = o.Price; Trade(o.Dir * o.Qty); Price = keep;
            }
        }

        // One step forward; returns false at the end of the session (an open position is closed at the last price).
        public bool Advance()
        {
            if (Live) return true;   // LIVE: prices come from LiveUpdate
            if (Finished) return false;
            var b = Bars[BarIndex]; var tl = TicksAt(BarIndex);
            if (tl != null && tl.Count > 0)
            {   /* ⏱ a real print */
                if (Step < tl.Count) { var tk = tl[Step]; Step++; Price = tk.Price; Time = tk.Time; formingVol += tk.Volume; CheckOrders(); CheckBracket(); }
                if (Step >= tl.Count) { Step = 0; BarIndex++; Time = b.Time; Price = b.Close; formingVol = 0; }
                if (Finished) { Orders.Clear(); if (Position != 0) CloseAll("SESSION END"); }
                return !Finished;
            }
            Step++;
            Price = PathPrice(b, Step, StepsPerBar, tick); Time = b.Time.AddMinutes(-1).AddSeconds(60.0 * Step / StepsPerBar);
            CheckOrders(); CheckBracket();
            if (Step >= StepsPerBar) { Step = 0; BarIndex++; Time = b.Time; }
            if (Finished) { Orders.Clear(); if (Position != 0) CloseAll("SESSION END"); }
            return !Finished;
        }

        // Advance until the replay clock reaches t (several instruments stay on one clock); false at the end of the session.
        public bool AdvanceTo(DateTime t, int maxSteps)
        {
            int n = 0; while (!Finished && (HasTicks ? NextTime() <= t : Time < t) && n < maxSteps) { Advance(); n++; }
            return !Finished;
        }

        public void JumpTo(DateTime t) { while (!Finished && Bars[BarIndex].Time <= t) { Step = 0; Price = Bars[BarIndex].Close; Time = Bars[BarIndex].Time; BarIndex++; if (Position != 0) CheckBracketBar(Bars[BarIndex - 1]); } }

        void CheckBracketBar(KeystoneArcBar b)
        {
            var tl = TicksAt(Bars.IndexOf(b)); if (tl != null && tl.Count > 0) { foreach (var tk in tl) { if (Position == 0) break; Price = tk.Price; Time = tk.Time; CheckBracket(); } Price = b.Close; return; }
            for (int k = 1; k <= StepsPerBar && Position != 0; k++) { Price = PathPrice(b, k, StepsPerBar, tick); CheckBracket(); }
            Price = b.Close;
        }

        void CheckBracket()
        {
            if (Position == 0) return; int dir = Math.Sign(Position);
            if (StopPts != 0 && dir * (Price - AvgPrice) <= -StopPts + 1e-9) { Price = AvgPrice - dir * StopPts; CloseAll(StopPts < 0 ? "PROFIT STOP" : "STOP"); return; }   // StopPts < 0 = a stop past the entry (locks profit)
            if (TargetPts > 0 && dir * (Price - AvgPrice) >= TargetPts - 1e-9) { Price = AvgPrice + dir * TargetPts; CloseAll("TARGET"); }
        }

        public void Buy(int qty) { Trade(Math.Max(1, qty)); }
        public void Sell(int qty) { Trade(-Math.Max(1, qty)); }

        void Trade(int signedQty)
        {
            if (Finished && Bars.Count > 0) return;
            if (Position != 0 && Math.Sign(Position) != Math.Sign(signedQty))
            {
                int closing = Math.Min(Math.Abs(Position), Math.Abs(signedQty));
                Record(closing, "MANUAL"); Position += Math.Sign(signedQty) * closing; signedQty -= Math.Sign(signedQty) * closing;
                if (Position == 0) { AvgPrice = 0; if (signedQty != 0 && StopPts < 0) StopPts = 0; }   // REVERSED: a profit stop belonged to the old trade — on the new side it would be a stop beyond the price (rejected → flatten)
            }
            if (signedQty == 0) return;
            if (Position == 0) { PositionTime = Time; AvgPrice = Price; Position = signedQty; }
            else { int p0 = Position; double a0 = AvgPrice; AvgPrice = (AvgPrice * Math.Abs(Position) + Price * Math.Abs(signedQty)) / (Math.Abs(Position) + Math.Abs(signedQty)); Position += signedQty; KeepLevels(a0, p0); }
        }

        public void CloseAll(string reason) { if (Position != 0) { Record(Math.Abs(Position), reason); Position = 0; AvgPrice = 0; } }

        void Record(int qty, string reason)
        {
            if (Slave) return;   // linked: the real fills make the trades
            int dir = Math.Sign(Position); double pts = dir * (Price - AvgPrice), net = pts * pv * qty - cost * qty;
            Realized += net;
            Fills.Add(new KeystoneReplayFill { Symbol = Symbol, Side = dir > 0 ? "BUY" : "SELL", Qty = qty, Entry = AvgPrice, Exit = Price, EntryTime = PositionTime, ExitTime = Time, Points = pts, Net = net, Reason = reason });
        }

        // The journal: one CSV line per finished trade (appended), so every replayed day is kept.
        public static string JournalLine(DateTime session, KeystoneReplayFill f)
        {
            return string.Join(",", session.ToString("yyyy-MM-dd"), f.Symbol, f.Side, f.Qty, f.EntryTime.ToString("yyyy-MM-dd HH:mm:ss"), f.Entry.ToString(CultureInfo.InvariantCulture), f.ExitTime.ToString("yyyy-MM-dd HH:mm:ss"), f.Exit.ToString(CultureInfo.InvariantCulture), f.Points.ToString("0.##", CultureInfo.InvariantCulture), f.Net.ToString("0.00", CultureInfo.InvariantCulture), f.Reason);
        }
        public const string JournalHeader = "session,symbol,side,qty,entry_time,entry,exit_time,exit,points,net,reason";
    }

    // ---- 📒 MY TRADES POOL: every trade closed in the studio (REGULAR backtesting, ✋ I TRADE or ⚡ AUTO, and the PROP SIM),
    // one line each in StudioTrades.csv with how it was taken and the strategy; older trades come from ReplayJournal.csv (no tag).
    // Days, instruments, sides, hours, weekdays, hold times, exits, strategies — and a prompt for the AI to find my patterns.
    public sealed class KeystoneManualTrade
    {
        public DateTime Session, EntryTime, ExitTime; public string Symbol = "", Side = "", Reason = "", Mode = "", How = "", Strategy = ""; public int Qty; public double Entry, Exit, Points, Net;
        public double HoldMinutes { get { return Math.Max(0, (ExitTime - EntryTime).TotalMinutes); } }
        public string Key { get { return Session.ToString("yyyy-MM-dd") + "|" + Symbol + "|" + EntryTime.ToString("yyyy-MM-dd HH:mm:ss") + "|" + ExitTime.ToString("yyyy-MM-dd HH:mm:ss") + "|" + Net.ToString("0.00", CultureInfo.InvariantCulture); } }
    }
    public sealed class KeystoneManualRow
    {
        public string Name = ""; public int Trades, Won, Days; public double Net, Best = double.NaN, Worst = double.NaN, GrossWin, GrossLoss, Hold;
        public double WinPct { get { return Trades == 0 ? 0 : 100.0 * Won / Trades; } }
        public double Pf { get { return GrossLoss <= 0 ? (GrossWin > 0 ? 99 : 0) : GrossWin / GrossLoss; } }
        public double AvgWin { get { return Won == 0 ? 0 : GrossWin / Won; } }
        public double AvgLoss { get { return Trades - Won == 0 ? 0 : GrossLoss / (Trades - Won); } }
    }
    public static class KeystoneManualPool
    {
        public const string Header = "session,symbol,side,qty,entry_time,entry,exit_time,exit,points,net,reason,mode,how,strategy";
        static string Clean(string s) { return (s ?? "").Replace(",", " ").Replace("\r", " ").Replace("\n", " ").Trim(); }
        public static string Line(DateTime session, KeystoneReplayFill f, string mode, string how, string strategy)
        {
            return KeystoneReplayTrader.JournalLine(session, f) + "," + Clean(mode) + "," + Clean(how) + "," + Clean(strategy);
        }
        // a StudioTrades.csv line (14 columns) or a ReplayJournal.csv line (11 columns)
        public static KeystoneManualTrade Parse(string line)
        {
            if (string.IsNullOrWhiteSpace(line) || line.StartsWith("session,")) return null; var a = line.Split(','); if (a.Length < 11) return null;
            try
            {
                var ic = CultureInfo.InvariantCulture; var t = new KeystoneManualTrade();
                t.Session = DateTime.ParseExact(a[0], "yyyy-MM-dd", ic); t.Symbol = a[1]; t.Side = a[2]; t.Qty = int.Parse(a[3], ic);
                t.EntryTime = DateTime.ParseExact(a[4], "yyyy-MM-dd HH:mm:ss", ic); t.Entry = double.Parse(a[5], ic); t.ExitTime = DateTime.ParseExact(a[6], "yyyy-MM-dd HH:mm:ss", ic); t.Exit = double.Parse(a[7], ic);
                t.Points = double.Parse(a[8], ic); t.Net = double.Parse(a[9], ic); t.Reason = a[10];
                if (a.Length >= 14) { t.Mode = a[11]; t.How = a[12]; t.Strategy = a[13]; }
                return t;
            }
            catch { return null; }
        }
        // tagged trades first; a journal trade that is not in the tagged file (older history) is added as "BEFORE TAGS"
        public static List<KeystoneManualTrade> Load(string tradesFile, string journalFile)
        {
            var o = new List<KeystoneManualTrade>(); var keys = new HashSet<string>();
            try { if (File.Exists(tradesFile)) foreach (var l in File.ReadAllLines(tradesFile)) { var t = Parse(l); if (t != null && t.Mode != "") { o.Add(t); keys.Add(t.Key); } } } catch { }
            try { if (journalFile != null && File.Exists(journalFile)) foreach (var l in File.ReadAllLines(journalFile)) { var t = Parse(l); if (t == null || keys.Contains(t.Key)) continue; t.Mode = "?"; t.How = "BEFORE TAGS"; t.Strategy = "?"; o.Add(t); } } catch { }
            return o.OrderBy(t => t.ExitTime).ToList();
        }
        public static KeystoneManualRow Sum(string name, IEnumerable<KeystoneManualTrade> ts)
        {
            var r = new KeystoneManualRow { Name = name }; var days = new HashSet<DateTime>();
            foreach (var t in ts)
            {
                r.Trades++; r.Net += t.Net; r.Hold += t.HoldMinutes; days.Add(t.Session);
                if (t.Net > 0) { r.Won++; r.GrossWin += t.Net; } else r.GrossLoss -= t.Net;
                if (double.IsNaN(r.Best) || t.Net > r.Best) r.Best = t.Net; if (double.IsNaN(r.Worst) || t.Net < r.Worst) r.Worst = t.Net;
            }
            r.Days = days.Count; if (r.Trades > 0) r.Hold /= r.Trades; return r;
        }
        public static string HoldBucket(double m) { return m < 1 ? "a under 1 min" : m < 5 ? "b 1–5 min" : m < 15 ? "c 5–15 min" : m < 60 ? "d 15–60 min" : "e over 1 hour"; }
        public static string HourOf(KeystoneManualTrade t) { return t.EntryTime.Hour.ToString("00") + ":00"; }
        // the breakdowns shown in the pool: (title, key)
        public static readonly string[] Views = { "INSTRUMENT", "SIDE", "HOW", "STRATEGY", "ENTRY HOUR (NY)", "WEEKDAY", "HOLD TIME", "EXIT", "MONTH", "MODE" };
        public static string KeyOf(string view, KeystoneManualTrade t)
        {
            switch (view)
            {
                case "INSTRUMENT": return t.Symbol; case "SIDE": return t.Side; case "HOW": return t.How == "" ? "?" : t.How; case "STRATEGY": return t.Strategy == "" ? "?" : t.Strategy;
                case "ENTRY HOUR (NY)": return HourOf(t); case "WEEKDAY": return ((int)t.Session.DayOfWeek) + " " + t.Session.DayOfWeek.ToString().ToUpperInvariant();
                case "HOLD TIME": return HoldBucket(t.HoldMinutes); case "EXIT": return t.Reason == "" ? "?" : t.Reason; case "MONTH": return t.Session.ToString("yyyy-MM"); case "MODE": return t.Mode == "" ? "?" : t.Mode;
            }
            return "";
        }
        // sorted for display; the sort prefix ("1 MONDAY", "a under 1 min") is cut off in the name
        public static List<KeystoneManualRow> By(IList<KeystoneManualTrade> ts, string view)
        {
            bool prefixed = view == "WEEKDAY" || view == "HOLD TIME";
            return ts.GroupBy(t => KeyOf(view, t)).OrderBy(g => g.Key, StringComparer.Ordinal).Select(g => Sum(prefixed ? g.Key.Substring(2) : g.Key, g)).ToList();
        }
        // every day: per day the totals and the instruments
        public static List<Tuple<DateTime, KeystoneManualRow, string>> Days(IList<KeystoneManualTrade> ts)
        {
            return ts.GroupBy(t => t.Session).OrderByDescending(g => g.Key).Select(g => Tuple.Create(g.Key, Sum(g.Key.ToString("yyyy-MM-dd ddd", CultureInfo.InvariantCulture), g),
                string.Join(" • ", g.GroupBy(t => t.Symbol).OrderBy(x => x.Key).Select(x => x.Key + " " + x.Count() + " " + (x.Sum(t => t.Net) >= 0 ? "+" : "−") + "$" + Math.Abs(x.Sum(t => t.Net)).ToString("N0", CultureInfo.InvariantCulture))))).ToList();
        }
        public static int[] Streaks(IList<KeystoneManualTrade> ts)   // longest winning / losing run of trades, green / red days in a row
        {
            int w = 0, l = 0, bw = 0, bl = 0; foreach (var t in ts) { if (t.Net > 0) { w++; l = 0; } else { l++; w = 0; } bw = Math.Max(bw, w); bl = Math.Max(bl, l); }
            int gd = 0, rd = 0, bg = 0, br = 0; foreach (var d in ts.GroupBy(t => t.Session).OrderBy(g => g.Key)) { double n = d.Sum(t => t.Net); if (n > 0) { gd++; rd = 0; } else { rd++; gd = 0; } bg = Math.Max(bg, gd); br = Math.Max(br, rd); }
            return new[] { bw, bl, bg, br };
        }
        public static double MaxDrawdown(IList<KeystoneManualTrade> ts) { double eq = 0, pk = 0, dd = 0; foreach (var t in ts) { eq += t.Net; pk = Math.Max(pk, eq); dd = Math.Max(dd, pk - eq); } return dd; }

        public const string AiSystem = "You are a trading coach reading a futures trader's own trade journal (MNQ / MGC micro futures, replayed days and practice). Find what separates their winning trades from the losing ones: instruments, sides, hours, weekdays, hold times, exits, strategies, manual vs automatic. Use only the numbers given; say how many trades back each point (under 20 trades = a hint, not a finding). Plain English, short: 1) the 3 strongest patterns, 2) what to stop doing, 3) what to do more, 4) one concrete rule to test next.";
        public static string AiPrompt(IList<KeystoneManualTrade> ts)
        {
            var sb = new StringBuilder(); var all = Sum("ALL", ts); var ic = CultureInfo.InvariantCulture;
            Func<KeystoneManualRow, string> line = r => r.Name + ": " + r.Trades + " trades, " + r.WinPct.ToString("0", ic) + "% won, net $" + r.Net.ToString("0", ic) + ", avg win $" + r.AvgWin.ToString("0", ic) + ", avg loss $" + r.AvgLoss.ToString("0", ic) + ", PF " + r.Pf.ToString("0.00", ic) + ", avg hold " + r.Hold.ToString("0.0", ic) + " min";
            sb.AppendLine("MY TRADES • " + (ts.Count == 0 ? "none" : ts[0].Session.ToString("yyyy-MM-dd") + " → " + ts[ts.Count - 1].Session.ToString("yyyy-MM-dd")) + " • " + all.Days + " days");
            sb.AppendLine(line(all)); var st = Streaks(ts); sb.AppendLine("longest runs: " + st[0] + " wins, " + st[1] + " losses in a row • " + st[2] + " green days, " + st[3] + " red days in a row • max drawdown $" + MaxDrawdown(ts).ToString("0", ic));
            foreach (var v in Views.Where(v => v != "MONTH")) { sb.AppendLine(); sb.AppendLine("BY " + v); foreach (var r in By(ts, v)) sb.AppendLine("  " + line(r)); }
            sb.AppendLine(); sb.AppendLine("THE LAST 60 TRADES (session, symbol, side, qty, entry time, hold min, points, net, exit, how, strategy)");
            foreach (var t in ts.Skip(Math.Max(0, ts.Count - 60))) sb.AppendLine("  " + string.Join(", ", t.Session.ToString("yyyy-MM-dd"), t.Symbol, t.Side, t.Qty, t.EntryTime.ToString("HH:mm"), t.HoldMinutes.ToString("0.0", ic), t.Points.ToString("0.##", ic), t.Net.ToString("0", ic), t.Reason, t.How, t.Strategy));
            return sb.ToString();
        }
    }

    // ---- ACCOUNT LINK: the studio's live chart IS the real NinjaTrader account --------------------------------------------
    // The real account is the truth. Every tick the studio shows its position, average price, stop / target and working
    // orders — wherever they were placed (the studio, NinjaTrader's Chart Trader / DOM / ATM). What you do in the studio (BUY /
    // SELL / CLOSE, drag a stop / target / order, BE, ✕, AUTO) is turned into real orders — only while ARMED; unarmed the studio
    // only WATCHES (and refuses to trade). Every fill is turned into a trade (journal). Safety while armed: max contracts, day
    // loss limit and day profit cap (flatten + disarm), runaway guard, a rejected order disarms, minimum hold time.
    public sealed class KeystoneBrokerOrder
    {
        public string Id = string.Empty, Kind = "MARKET", Oco = string.Empty, Name = string.Empty;   // Kind: MARKET, LIMIT, STOP
        public int Side, Qty, Filled; public double Price; public bool Done, Rejected, CancelSent, Ours; public object Native;
    }
    public sealed class KeystoneExec { public string Id = string.Empty, Name = string.Empty; public DateTime Time; public int SignedQty; public double Price, Commission; }

    public interface IKeystoneBroker
    {
        bool Connected { get; }
        int Qty { get; }                                  // signed real position in this instrument
        double AvgPrice { get; }
        double DayPnl { get; }                            // the account's realized + open P/L today
        double Tick { get; }
        List<KeystoneBrokerOrder> Working();              // every working order on this instrument (the studio's and NinjaTrader's)
        List<KeystoneExec> Executions();                  // this instrument's executions (any order)
        KeystoneBrokerOrder Submit(string kind, int signedQty, double price, string oco, bool automated);   // null = refused
        void ChangePrice(KeystoneBrokerOrder o, double price);
        void Cancel(KeystoneBrokerOrder o);
        void Flatten();
    }

    // Executions → finished trades (average price, partial closes and reversals included).
    public sealed class KeystoneTradeBuilder
    {
        public int Pos; public double Avg, PosComm; public DateTime Since; readonly HashSet<string> seen = new HashSet<string>(); bool realFees;
        readonly string symbol; readonly double pv, cost;
        public KeystoneTradeBuilder(string sym) { symbol = (sym ?? "MNQ").ToUpperInvariant(); pv = KeystoneMoveStudy.PointValue(symbol); cost = KeystoneMoveStudy.Cost(symbol); }
        // executions already there when the link starts: they set the position, they are not new trades
        public void Prime(IEnumerable<KeystoneExec> list) { foreach (var e in (list ?? new List<KeystoneExec>()).OrderBy(x => x.Time)) { if (e == null || !seen.Add(e.Id)) continue; Apply(e, null); } }
        public List<KeystoneReplayFill> Add(IEnumerable<KeystoneExec> list)
        {
            var output = new List<KeystoneReplayFill>();
            foreach (var e in (list ?? new List<KeystoneExec>()).OrderBy(x => x.Time)) { if (e == null || e.SignedQty == 0 || !seen.Add(e.Id)) continue; Apply(e, output); }
            return output;
        }
        public void Anchor(int qty, double avg, DateTime now) { if (qty == Pos && (qty == 0 || Math.Abs(avg - Avg) < 1e-9)) return; if (Pos == 0 && qty != 0) Since = now; Pos = qty; Avg = qty == 0 ? 0 : avg; }
        void Apply(KeystoneExec e, List<KeystoneReplayFill> output)
        {
            int q = e.SignedQty; int all = Math.Abs(q); if (e.Commission > 0) realFees = true;
            if (Pos != 0 && Math.Sign(q) != Math.Sign(Pos))
            {
                int closing = Math.Min(Math.Abs(Pos), Math.Abs(q)); int dir = Math.Sign(Pos); double pts = dir * (e.Price - Avg);
                // fees: the commissions NinjaTrader reported (the entry's share + this exit's share); an estimate only when none were reported
                double entryShare = PosComm * closing / Math.Abs(Pos), fee = realFees ? entryShare + e.Commission * closing / all : cost * closing; PosComm -= entryShare;
                if (output != null) output.Add(new KeystoneReplayFill { Symbol = symbol, Side = dir > 0 ? "BUY" : "SELL", Qty = closing, Entry = Avg, Exit = e.Price, EntryTime = Since, ExitTime = e.Time, Points = pts, Net = pts * pv * closing - fee, Gross = pts * pv * closing, Fee = fee, Reason = "REAL • " + (e.Name.StartsWith("KEYSTONE") ? "STUDIO" : "NINJATRADER") });
                Pos += Math.Sign(q) * closing; q -= Math.Sign(q) * closing; if (Pos == 0) { Avg = 0; PosComm = 0; }
            }
            if (q == 0) return;
            PosComm += e.Commission * Math.Abs(q) / all;
            if (Pos == 0) { Pos = q; Avg = e.Price; Since = e.Time; }
            else { Avg = (Avg * Math.Abs(Pos) + e.Price * Math.Abs(q)) / (Math.Abs(Pos) + Math.Abs(q)); Pos += q; }
        }
    }

    // 🔒 NINJATRADER LOCKOUT (BUILD 2026-11-11i, user's catch: TAKEPROFIT893 locked in NinjaTrader's Accounts tab ▸ Lockout, "Locked until 5:00 PM",
    // still shown ARMED here). The lock is read from the Account object by REFLECTION (the member is not in every NinjaTrader version and its name is
    // not documented): every property / field whose name contains "Lock" — a DateTime / DateTime? ahead = locked until then, a bool true = locked —
    // on the account and one level down on related objects (names with Lock / Risk / Setting / Option). The members seen are written once to
    // Studio\KeyStone.log. A locked account: every ENTRY is refused (closes / cancels still go), the links are disarmed, LOCK FOR TODAY mirrors it,
    // the 🤖 AUTOPILOT gives it no ticket. Re-read every 5 s; the end of the lock is shown, nothing is re-armed by itself.
    public sealed class KeystoneNtLock
    {
        public bool Locked; public DateTime Until = DateTime.MinValue; public string Source = "", Members = "";
        public bool ActiveAt(DateTime nowLocal) { return Locked && (Until == DateTime.MinValue || nowLocal < Until); }
        public string UntilText { get { return Until == DateTime.MinValue ? "" : Until.ToString("h:mm tt", CultureInfo.InvariantCulture); } }
        public string Label { get { return "🔒 LOCKED by NinjaTrader" + (UntilText != "" ? " until " + UntilText : ""); } }
    }
    public static class KeystoneNtLockout
    {
        public static Func<DateTime> Clock = () => DateTime.Now;   // NinjaTrader's lock time is the PC's local time
        static readonly Dictionary<string, KeystoneNtLock> states = new Dictionary<string, KeystoneNtLock>(StringComparer.OrdinalIgnoreCase);
        static readonly Dictionary<string, bool> was = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase);
        static readonly string[] notALock = { "unlock", "allow", "can", "flatten", "show", "auto", "sync", "object", "padlock" };
        static bool LockName(string n) { if (string.IsNullOrEmpty(n) || n.IndexOf("lock", StringComparison.OrdinalIgnoreCase) < 0) return false; string l = n.ToLowerInvariant(); return !notALock.Any(x => l.Contains(x)); }
        static bool Related(string n) { string l = (n ?? "").ToLowerInvariant(); return l.Contains("lock") || l.Contains("risk") || l.Contains("setting") || l.Contains("option"); }
        // the members (name, type, value) whose name contains "Lock" — on the object and on its related objects
        static void Walk(object o, string path, int depth, List<Tuple<string, Type, object>> found, HashSet<object> seen)
        {
            if (o == null || depth > 2 || !seen.Add(o)) return;
            var flags = System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance;
            var items = new List<Tuple<string, Type, Func<object>>>();
            try { foreach (var p in o.GetType().GetProperties(flags)) { var pp = p; if (pp.GetIndexParameters().Length > 0 || !pp.CanRead) continue; items.Add(Tuple.Create(pp.Name, pp.PropertyType, (Func<object>)(() => pp.GetValue(o, null)))); } } catch { }
            try { foreach (var f in o.GetType().GetFields(flags)) { var ff = f; if (ff.Name.Contains("k__BackingField")) continue; items.Add(Tuple.Create(ff.Name, ff.FieldType, (Func<object>)(() => ff.GetValue(o)))); } } catch { }
            foreach (var it in items)
            {
                var t = Nullable.GetUnderlyingType(it.Item2) ?? it.Item2; bool simple = t.IsPrimitive || t.IsEnum || t == typeof(DateTime) || t == typeof(TimeSpan) || t == typeof(string) || t == typeof(decimal);
                if (simple) { if (!LockName(it.Item1)) continue; object v = null; try { v = it.Item3(); } catch { continue; } found.Add(Tuple.Create(path + it.Item1, t, v)); continue; }
                if (!Related(it.Item1) || typeof(System.Collections.IEnumerable).IsAssignableFrom(t) || typeof(Delegate).IsAssignableFrom(t)) continue;
                object child = null; try { child = it.Item3(); } catch { continue; } if (child == null || child.GetType().IsPrimitive) continue;
                Walk(child, path + it.Item1 + ".", depth + 1, found, seen);
            }
        }
        public static List<Tuple<string, Type, object>> Find(object acct)
        {
            var found = new List<Tuple<string, Type, object>>(); try { Walk(acct, "", 0, found, new HashSet<object>(new RefEq())); } catch { } return found;
        }
        sealed class RefEq : IEqualityComparer<object> { public new bool Equals(object a, object b) { return ReferenceEquals(a, b); } public int GetHashCode(object o) { return System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(o); } }
        // locked: a "lock" time ahead (≤ 1 year: a MaxValue / unset time is no lock) or a "locked" switch on
        public static KeystoneNtLock Read(object acct, DateTime nowLocal)
        {
            var st = new KeystoneNtLock(); if (acct == null) return st; var found = Find(acct);
            st.Members = string.Join(" • ", found.Select(x => x.Item1 + " (" + x.Item2.Name + ") = " + (x.Item3 == null ? "null" : x.Item3 is DateTime ? ((DateTime)x.Item3).ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture) : Convert.ToString(x.Item3, CultureInfo.InvariantCulture))));
            foreach (var x in found)
            {
                if (x.Item3 is DateTime)
                {
                    var d = (DateTime)x.Item3; if (d.Kind == DateTimeKind.Utc) d = d.ToLocalTime();
                    if (d > nowLocal && d < nowLocal.AddYears(1) && (!st.Locked || st.Until == DateTime.MinValue || d > st.Until)) { st.Locked = true; st.Until = d; st.Source = x.Item1; }
                }
            }
            if (!st.Locked) foreach (var x in found) if (x.Item3 is bool && (bool)x.Item3) { st.Locked = true; st.Source = x.Item1; break; }
            return st;
        }
        // the poll's result for an account (Set) • what the rest of KeyStone asks (IsLocked / Get / Label)
        public static void Set(string account, KeystoneNtLock st) { if (string.IsNullOrEmpty(account)) return; lock (states) { if (st == null) states.Remove(account); else states[account] = st; } }
        public static KeystoneNtLock Get(string account) { KeystoneNtLock st; lock (states) { if (account == null || !states.TryGetValue(account, out st)) return null; } return st; }
        public static bool IsLocked(string account) { var st = Get(account); return st != null && st.ActiveAt(Clock()); }
        public static string Label(string account) { var st = Get(account); return st != null && st.ActiveAt(Clock()) ? st.Label : ""; }
        public static void Clear() { lock (states) { states.Clear(); was.Clear(); } }
        // the change since the last call for this account: +1 = it just got locked, −1 = the lock just ended, 0 = no change
        public static int Change(string account)
        {
            bool now = IsLocked(account), before; lock (states) { was.TryGetValue(account ?? "", out before); was[account ?? ""] = now; }
            return now == before ? 0 : now ? 1 : -1;
        }
        // an order of `signedQty` on a position of `real`: an ENTRY (opens or adds, or reverses) — refused while locked; a reduce / close is not
        public static bool IsEntry(int real, int signedQty) { if (signedQty == 0) return false; if (real == 0 || Math.Sign(signedQty) == Math.Sign(real)) return true; return Math.Abs(signedQty) > Math.Abs(real); }
    }
    // a broker that knows its NinjaTrader account (the link reads that account's lockout)
    public interface IKeystoneNamedBroker { string AccountName { get; } }

    public sealed class KeystoneAccountLink
    {
        public readonly IKeystoneBroker Broker; public readonly KeystoneTradeBuilder Trades;
        public bool Armed { get; private set; }
        public int MaxContracts = 2, MinHoldSeconds; public double DayLossLimit = 500, DayProfitCap; public bool Automated, AutoStop; public double DefaultStopPts;
        public bool Locked, LockFlatten;
        // 🔒 the NinjaTrader lockout of this link's account (BUILD 11i): AccountName set here, or the broker's own (NinjaBroker) — entries refused, closes / cancels go
        public string AccountName = "";
        public string LockKey { get { if (!string.IsNullOrEmpty(AccountName)) return AccountName; var nb = Broker as IKeystoneNamedBroker; return nb != null ? nb.AccountName : ""; } }
        public bool ExternalLocked { get { string k = LockKey; return !string.IsNullOrEmpty(k) && KeystoneNtLockout.IsLocked(k); } }
        public string ExternalLockLabel { get { string k = LockKey; return string.IsNullOrEmpty(k) ? "" : KeystoneNtLockout.Label(k); } }
        public bool AutoOco = true;   // one cancels the other for EVERY order on the account (also NinjaTrader's): a closed position cancels its stop / target, a filled entry cancels the other entries
        HashSet<KeystoneBrokerOrder> protSeen = new HashSet<KeystoneBrokerOrder>(), entrySeen = new HashSet<KeystoneBrokerOrder>(), addSeen = new HashSet<KeystoneBrokerOrder>();   // LOCKED FOR TODAY: the studio places nothing; LockFlatten = a position opened anyway (e.g. in NinjaTrader) is closed
        public bool Connected { get; private set; }
        DateTime lockFlatAt = DateTime.MinValue;
        public string State = "WATCHING", Warning = ""; public bool Pulled; public readonly List<string> Log = new List<string>();
        public readonly List<KeystoneReplayFill> NewFills = new List<KeystoneReplayFill>();   // real trades not yet saved by the UI
        public Action<string> Disarmed;
        // the state both sides agreed on last (studio == real); a difference on the studio side = something you did in the studio
        int sQty; double sStop, sTgt; readonly Dictionary<int, KeystoneBrokerOrder> map = new Dictionary<int, KeystoneBrokerOrder>(); readonly Dictionary<int, double> sPrice = new Dictionary<int, double>();
        int? pendingQty; bool bracketWanted; DateTime waitUntil = DateTime.MinValue; readonly List<DateTime> sends = new List<DateTime>(), protSends = new List<DateTime>(); int ocoSeq; DateTime realSince = DateTime.MinValue; int lastReal;
        readonly HashSet<string> protective = new HashSet<string>(); readonly List<KeystoneBrokerOrder> ours = new List<KeystoneBrokerOrder>(); DateTime bracketWait = DateTime.MinValue;

        public KeystoneAccountLink(IKeystoneBroker broker, string symbol) { Broker = broker; Trades = new KeystoneTradeBuilder(symbol); try { Trades.Prime(broker.Executions()); } catch { } }

        public string Arm(DateTime now)
        {
            if (Broker == null || !Broker.Connected) return "THE ACCOUNT IS NOT CONNECTED IN NINJATRADER";
            if (ExternalLocked) return ExternalLockLabel.ToUpperInvariant() + " — NO ENTRIES UNTIL NINJATRADER UNLOCKS IT";
            if (MaxContracts < 1) return "MAX CONTRACTS MUST BE 1 OR MORE";
            if (Math.Abs(Broker.Qty) > MaxContracts) return "THE ACCOUNT HOLDS " + Math.Abs(Broker.Qty) + " — MORE THAN MAX QTY " + MaxContracts;
            Armed = true; sends.Clear(); protSends.Clear();
            // 🛑 user's catch (the window re-opened and CLOSED the trades): a day limit ALREADY past when arming only blocks new entries — it never
            // closes a position by itself; only a limit crossed WHILE armed closes (as before)
            double pnlA = Broker.DayPnl; lossPastAtArm = DayLossLimit > 0 && pnlA <= -Math.Abs(DayLossLimit); capPastAtArm = DayProfitCap > 0 && pnlA >= DayProfitCap;
            Note(now, "ARMED • max " + MaxContracts + " • day loss $" + DayLossLimit.ToString("0", CultureInfo.InvariantCulture) + (DayProfitCap > 0 ? " • day cap $" + DayProfitCap.ToString("0", CultureInfo.InvariantCulture) : "") + (MinHoldSeconds > 0 ? " • min hold " + MinHoldSeconds + "s" : ""));
            return null;
        }
        bool lossPastAtArm, capPastAtArm, synced;   // the day limits were already past when arming (re-opening the window): never close by themselves
        public void Disarm(string why, DateTime now, bool flatten)
        {
            if (!Armed) return; Armed = false; pendingQty = null; bracketWanted = false;
            if (flatten) { try { Broker.Flatten(); } catch { } }
            Note(now, "DISARMED • " + why + (flatten ? " • FLATTENED" : "")); State = "WATCHING • " + why;
            if (Disarmed != null) Disarmed(why);
        }
        void Note(DateTime now, string s) { Log.Add(now.ToString("HH:mm:ss", CultureInfo.InvariantCulture) + " " + s); if (Log.Count > 300) Log.RemoveAt(0); }
        double Tk { get { return Broker.Tick > 0 ? Broker.Tick : 0.25; } }
        double Round(double p) { return Math.Round(p / Tk) * Tk; }
        static string Px(double p) { return p.ToString("0.00", CultureInfo.InvariantCulture); }
        // RUNAWAY GUARD: 8 entry orders in a minute = stop. A trade's own STOP / TARGET orders are counted apart (30 a minute) — they used to
        // count as entries, so 3 bracketed trades in a minute (entry + stop + target each) tripped it
        bool Guard(DateTime now, bool protective)
        {
            var l = protective ? protSends : sends; int max = protective ? 30 : 8; l.RemoveAll(x => (now - x).TotalSeconds > 60);
            if (l.Count >= max) { Disarm("RUNAWAY GUARD: " + max + (protective ? " STOP / TARGET ORDERS" : " ORDERS") + " IN A MINUTE", now, true); return false; }
            l.Add(now); return true;
        }
        KeystoneBrokerOrder Send(string kind, int signedQty, double price, string oco, DateTime now, string what)
        {
            bool protective = what.StartsWith("STOP ") || what.StartsWith("TARGET ") || what.StartsWith("AUTO STOP");
            if (!Guard(now, protective)) return null;
            var o = Broker.Submit(kind, signedQty, price, oco, Automated);
            if (o == null) { Disarm("NINJATRADER REFUSED THE ORDER (" + what + ")", now, false); return null; }
            o.Ours = true; ours.Add(o); if (ours.Count > 200) ours.RemoveAt(0); Note(now, what); return o;
        }

        // protective orders: the working orders on the other side of the position (stop orders = stop, limit orders = target)
        void Classify(int real, List<KeystoneBrokerOrder> work, out KeystoneBrokerOrder stop, out KeystoneBrokerOrder tgt, out List<KeystoneBrokerOrder> entries)
        {
            stop = null; tgt = null; entries = new List<KeystoneBrokerOrder>(); int dir = Math.Sign(real);
            var studioWorking = new HashSet<KeystoneBrokerOrder>(map.Values);   // the studio's own working orders (e.g. TAKE PROFIT steps) are never the bracket
            foreach (var o in work)
            {
                if (studioWorking.Contains(o)) { entries.Add(o); continue; }
                if (real != 0 && o.Side == -dir && o.Kind == "STOP") { if (stop == null || Math.Abs(o.Price - Broker.AvgPrice) < Math.Abs(stop.Price - Broker.AvgPrice)) stop = o; }
                else if (real != 0 && o.Side == -dir && o.Kind == "LIMIT") { if (tgt == null || Math.Abs(o.Price - Broker.AvgPrice) < Math.Abs(tgt.Price - Broker.AvgPrice)) tgt = o; }
                else entries.Add(o);
            }
        }

        public void Tick(KeystoneReplayTrader t, DateTime now)
        {
            Pulled = false; Warning = "";
            if (t == null) return;
            Connected = Broker.Connected;
            bool ext = ExternalLocked; bool dayLocked = Locked && !ext;   /* 🔒 a NinjaTrader lockout: its own path below (closes / cancels go, entries never) */
            if (ext && Armed) Disarm(ExternalLockLabel + " — entries refused; ARM again yourself once it ends", now, false);   /* never re-armed by itself */
            // 1. real fills → trades (the studio's trade list + the journal)
            try { foreach (var f in Trades.Add(Broker.Executions())) { t.AddRealFill(f); NewFills.Add(f); } } catch { }
            int real = Broker.Qty; double avg = Broker.AvgPrice; Trades.Anchor(real, avg, now); int prevReal = lastReal;
            if (real != 0 && lastReal == 0) realSince = now; lastReal = real;
            var work = Broker.Working().Where(o => !o.Done && !o.CancelSent).ToList();
            if (AutoOco && Connected)
            {
                // one cancels the other: the trade closed → its leftover stop / target goes; an entry filled → the other entries go
                var stale = new List<KeystoneBrokerOrder>();
                if (real == 0 && prevReal != 0) stale.AddRange(protSeen.Where(work.Contains));
                if (real != 0 && prevReal == 0) stale.AddRange(entrySeen.Where(work.Contains));
                // already in a trade: an ADD order (the position's side) filled → the other add orders go too (a limit + a stop to add = only one of them)
                if (real != 0 && prevReal != 0 && Math.Sign(real) == Math.Sign(prevReal) && Math.Abs(real) > Math.Abs(prevReal)) stale.AddRange(addSeen.Where(o => work.Contains(o) && o.Filled == 0));
                foreach (var o in stale) { Broker.Cancel(o); Note(now, "ONE-CANCELS-OTHER • cancelled " + (o.Side > 0 ? "BUY " : "SELL ") + o.Kind + " @ " + Px(o.Price)); }
                if (stale.Count > 0) work = work.Where(o => !stale.Contains(o)).ToList();
            }
            if (real != 0) { protSeen = new HashSet<KeystoneBrokerOrder>(work.Where(o => o.Side == -Math.Sign(real) && o.Kind != "MARKET")); addSeen = new HashSet<KeystoneBrokerOrder>(work.Where(o => o.Side == Math.Sign(real) && o.Kind != "MARKET")); entrySeen.Clear(); }
            else { entrySeen = new HashSet<KeystoneBrokerOrder>(work.Where(o => o.Kind != "MARKET")); protSeen.Clear(); addSeen.Clear(); }
            KeystoneBrokerOrder rStop, rTgt; List<KeystoneBrokerOrder> rEntries; Classify(real, work, out rStop, out rTgt, out rEntries);
            // 🔁 user's bug (TP / SL "gone" after switching the chart account and back): a FRESH link first READS the account's real position, stop,
            // target and orders from NinjaTrader — the chart may still hold the other account's bracket, which must never be sent to this one
            bool firstLook = !synced && Connected; if (firstLook) synced = true;
            if (firstLook && (real != 0 || work.Count > 0)) { if (real != 0) { t.StopPts = 0; t.TargetPts = 0; } Pull(t, real, avg, rStop, rTgt, rEntries, now); Note(now, "LINKED • read from NinjaTrader: " + (real != 0 ? (real > 0 ? "LONG " : "SHORT ") + Math.Abs(real) + (rStop != null ? " • stop @ " + Px(rStop.Price) : "") + (rTgt != null ? " • target @ " + Px(rTgt.Price) : "") : "flat")); }   /* then the safety checks below run as usual (the agreement is now the real state: nothing is pushed) */
            if (real == 0) foreach (var o in work.Where(o => protective.Contains(o.Id)).ToList()) { Broker.Cancel(o); protective.Remove(o.Id); }   // a leftover leg of our bracket
            // the position got smaller (a TAKE PROFIT step or a partial exit filled): a stop / target still sized for more would open a reverse
            // position when it fills — cancel the pair and rebuild it for what is left
            // …and the position got BIGGER (contracts added here or in NinjaTrader): a stop / target sized for fewer would close only part of it and
            // leave the rest unprotected (user's bug) — the same rebuild, for every contract, at the SAME prices
            bool bracketOver = real != 0 && ((rStop != null && rStop.Qty - rStop.Filled > Math.Abs(real)) || (rTgt != null && rTgt.Qty - rTgt.Filled > Math.Abs(real)));
            bool bracketOff = real != 0 && ((rStop != null && rStop.Qty - rStop.Filled != Math.Abs(real)) || (rTgt != null && rTgt.Qty - rTgt.Filled != Math.Abs(real)));
            if (Armed && Connected && !dayLocked && !ext && (bracketOver || (bracketOff && now >= bracketWait)))   // too big: at once (it would reverse); too small: once the last bracket settled
            {
                if (rStop != null) Broker.Cancel(rStop); if (rTgt != null && !rTgt.CancelSent) Broker.Cancel(rTgt);
                Note(now, "POSITION NOW " + Math.Abs(real) + " • stop / target resized for every contract"); bracketWanted = true; bracketWait = now.AddSeconds(2);
                // too big: gone at once; too small (contracts ADDED): this tick still reads the old stop / target's PRICES against the new average
                // (Pull), so the rebuild next tick puts them back at exactly the same prices, sized for every contract
                if (bracketOver) { rStop = null; rTgt = null; }
            }
            else if (!Armed && bracketOff) Warning = "THE STOP / TARGET AT THE BROKER COVER " + (rStop != null ? rStop.Qty - rStop.Filled : rTgt.Qty - rTgt.Filled) + " OF " + Math.Abs(real) + " CONTRACTS — ARM to resize them";
            if (map.Values.Any(b => b.Ours && b.Done && b.Filled > 0) && real != 0) bracketWanted = true;   // a studio entry order filled: its stop / target follow
            if (!Connected || dayLocked) pendingQty = null;
            // 2. limits
            double pnl = Broker.DayPnl;
            if (Armed && Connected && DayLossLimit > 0 && pnl <= -Math.Abs(DayLossLimit)) { Disarm("DAY LOSS LIMIT $" + DayLossLimit.ToString("0", CultureInfo.InvariantCulture) + " REACHED" + (lossPastAtArm ? " (already when armed — your position was NOT closed; no new entries)" : ""), now, !lossPastAtArm); return; }
            if (Armed && Connected && DayProfitCap > 0 && pnl >= DayProfitCap) { Disarm("DAY PROFIT CAP $" + DayProfitCap.ToString("0", CultureInfo.InvariantCulture) + " REACHED (consistency rule) — done for today" + (capPastAtArm ? " (already when armed — your position was NOT closed)" : ""), now, !capPastAtArm); return; }
            if (Armed && ours.Any(o => o.Rejected)) { Disarm("AN ORDER WAS REJECTED BY THE BROKER", now, true); return; }
            if (!Armed && DayProfitCap > 0 && pnl >= DayProfitCap) Warning = "DAY CAP REACHED — stop trading today (consistency)";
            if (!Armed && DayLossLimit > 0 && pnl <= -Math.Abs(DayLossLimit)) Warning = "DAY LOSS LIMIT REACHED — stop trading today";

            // 3. a size change waiting for its bracket to be cancelled first (reduce / reverse), or for the minimum hold
            if (pendingQty.HasValue && Armed && Connected && !dayLocked && !ext)
            {
                int want = pendingQty.Value; bool exiting = real != 0 && (want == 0 || Math.Sign(want) != Math.Sign(real) || Math.Abs(want) < Math.Abs(real));
                if (exiting && MinHoldSeconds > 0 && (now - realSince).TotalSeconds < MinHoldSeconds) { State = "ARMED • HOLDING " + Math.Ceiling(MinHoldSeconds - (now - realSince).TotalSeconds) + "s (min hold; the stop protects)"; return; }
                if (want == real) pendingQty = null;
                else if (want == 0) { if (!Guard(now, true)) return;   /* closing to flat is not a runaway entry */ Broker.Flatten(); Note(now, "FLATTEN"); waitUntil = now.AddSeconds(4); bracketWanted = false; pendingQty = null; State = "ARMED • FLATTENING"; return; }
                else if (exiting && (rStop != null || rTgt != null)) { if (rStop != null) Broker.Cancel(rStop); if (rTgt != null && !rTgt.CancelSent) Broker.Cancel(rTgt); State = "ARMED • CANCELLING THE BRACKET FIRST"; return; }
                else { Send("MARKET", want - real, 0, "", now, (want - real > 0 ? "BUY " : "SELL ") + Math.Abs(want - real) + " MARKET → " + want); waitUntil = now.AddSeconds(4); pendingQty = null; bracketWanted = t.StopPts != 0 || t.TargetPts > 0; State = "ARMED • ORDER SENT"; return; }
            }
            // waiting for the broker: until the real position matches what was sent (max 4 s), the studio keeps your intent
            if (Connected && !dayLocked && !ext && now < waitUntil && real != sQty) { State = Armed ? "ARMED • WAITING FOR THE FILL" : State; return; }

            // 4. what changed in the studio since the last agreement?
            bool qtyCh = t.Position != sQty, stopCh = Math.Abs(t.StopPts - sStop) > Tk / 2, tgtCh = Math.Abs(t.TargetPts - sTgt) > Tk / 2;
            var studioIds = new HashSet<int>(t.Orders.Select(o => o.Id));
            var newOrders = t.Orders.Where(o => !map.ContainsKey(o.Id)).ToList();
            var goneOrders = map.Keys.Where(id => !studioIds.Contains(id)).ToList();
            var moved = t.Orders.Where(o => map.ContainsKey(o.Id) && sPrice.ContainsKey(o.Id) && Math.Abs(sPrice[o.Id] - o.Price) > Tk / 2).ToList();
            bool studioActed = qtyCh || stopCh || tgtCh || newOrders.Count > 0 || goneOrders.Count > 0 || moved.Count > 0;
            if (!Connected) { pendingQty = null; State = "CONNECTION LOST • stops / targets stay at the broker"; Warning = "CONNECTION LOST — orders blocked until it is back"; Pull(t, real, avg, rStop, rTgt, rEntries, now); return; }
            if (ext) { ExternalTick(t, real, avg, rStop, rTgt, rEntries, studioActed, qtyCh, stopCh, tgtCh, newOrders, goneOrders, moved, now); return; }
            if (dayLocked)
            {
                pendingQty = null; State = "LOCKED FOR TODAY";
                if (real != 0 && LockFlatten && (now - lockFlatAt).TotalSeconds > 5) { lockFlatAt = now; Broker.Flatten(); Note(now, "LOCKED → FLATTEN"); Warning = "LOCKED FOR TODAY — the position was closed"; }
                else if (studioActed) Warning = "LOCKED FOR TODAY — no trading on this account until 18:00 NY";
                Pull(t, real, avg, rStop, rTgt, rEntries, now); return;
            }
            if (studioActed && !Armed) { Warning = "NOT ARMED — the studio only watches; press ARM to trade from here"; Pull(t, real, avg, rStop, rTgt, rEntries, now); return; }
            if (studioActed)
            {
                // working orders
                foreach (var o in newOrders) { var b = Send(o.Type == "STOP" ? "STOP" : "LIMIT", o.Dir * Math.Min(o.Qty, MaxContracts), o.Price, "", now, (o.Dir > 0 ? "BUY " : "SELL ") + o.Type + " " + Math.Min(o.Qty, MaxContracts) + " @ " + Px(o.Price)); if (b == null) return; map[o.Id] = b; sPrice[o.Id] = o.Price; }
                foreach (var id in goneOrders) { var b = map[id]; if (!b.Done && !b.CancelSent) { Broker.Cancel(b); Note(now, "CANCEL " + b.Kind + " @ " + Px(b.Price)); } map.Remove(id); sPrice.Remove(id); }
                foreach (var o in moved) { Broker.ChangePrice(map[o.Id], Round(o.Price)); sPrice[o.Id] = o.Price; Note(now, "ORDER MOVED → " + Px(o.Price)); }
                // position
                if (qtyCh)
                {
                    int want = Math.Sign(t.Position) * Math.Min(Math.Abs(t.Position), MaxContracts); pendingQty = want; sQty = want; sStop = t.StopPts; sTgt = t.TargetPts;
                    if (want != t.Position) { t.Adopt(want, t.AvgPrice, now); Warning = "CAPPED AT MAX QTY " + MaxContracts; }
                    State = "ARMED • SENDING"; return;   // sent on the next tick (after the bracket is out of the way when needed)
                }
                // stop / target of the open position
                if (real != 0 && (stopCh || tgtCh)) SetBracket(t.StopPts, t.TargetPts, real, avg, rStop, rTgt, now);
                sStop = t.StopPts; sTgt = t.TargetPts; State = "ARMED • SENT"; return;
            }
            // 5. the bracket the studio asked for, once its entry filled
            if (Armed && bracketWanted && real != 0 && rStop == null && rTgt == null && (t.StopPts != 0 || t.TargetPts > 0)) { bracketWanted = false; SetBracket(t.StopPts, t.TargetPts, real, avg, null, null, now); return; }
            if (real != 0 && ((rStop != null && !rStop.Done && !rStop.CancelSent) || (rTgt != null && !rTgt.Done && !rTgt.CancelSent))) bracketWanted = false;   // a LIVE bracket is there (one being cancelled for a resize does not count)
            // 6. no stop on a real position (e.g. opened in NinjaTrader)
            if (real != 0 && rStop == null)
            {
                if (Armed && AutoStop && !bracketWanted && DefaultStopPts > 0 && now >= bracketWait) { int dir = Math.Sign(real); var s = Send("STOP", -dir * Math.Abs(real), Round(avg - dir * DefaultStopPts), "", now, "AUTO STOP " + Px(Round(avg - dir * DefaultStopPts))); if (s != null) protective.Add(s.Id); return; }
                Warning = "NO STOP ON THE REAL POSITION";
            }
            Pull(t, real, avg, rStop, rTgt, rEntries, now);
            State = (Armed ? "ARMED" : "WATCHING") + (real == 0 ? " • FLAT" : " • " + (real > 0 ? "LONG " : "SHORT ") + Math.Abs(real) + " @ " + Px(avg)) + (rEntries.Count > 0 ? " • " + rEntries.Count + " working" : "");
        }

        // 🔒 LOCKED BY NINJATRADER (BUILD 11i): nothing new is opened — a new working order / a bigger or reversed position is refused here
        // (the studio takes the real account back); a full CLOSE, CANCELS and moving the existing stop / target still go (armed or not:
        // NinjaTrader's lock keeps exits open too). The link is never re-armed by itself when the lock ends.
        void ExternalTick(KeystoneReplayTrader t, int real, double avg, KeystoneBrokerOrder rStop, KeystoneBrokerOrder rTgt, List<KeystoneBrokerOrder> rEntries, bool studioActed, bool qtyCh, bool stopCh, bool tgtCh, List<KeystoneReplayOrder> newOrders, List<int> goneOrders, List<KeystoneReplayOrder> moved, DateTime now)
        {
            pendingQty = null; bracketWanted = false; string lab = ExternalLockLabel; if (lab == "") lab = "🔒 LOCKED by NinjaTrader";
            State = lab + " • entries refused" + (real != 0 ? " • " + (real > 0 ? "LONG " : "SHORT ") + Math.Abs(real) + " @ " + Px(avg) : " • FLAT");
            if (studioActed)
            {
                bool refused = false;
                foreach (var id in goneOrders) { var b = map[id]; if (!b.Done && !b.CancelSent) { Broker.Cancel(b); Note(now, "CANCEL " + b.Kind + " @ " + Px(b.Price) + " (locked by NinjaTrader)"); } map.Remove(id); sPrice.Remove(id); }
                foreach (var o in moved) { Broker.ChangePrice(map[o.Id], Round(o.Price)); sPrice[o.Id] = o.Price; Note(now, "ORDER MOVED → " + Px(o.Price)); }
                foreach (var o in newOrders) { t.Orders.RemoveAll(x => x.Id == o.Id); refused = true; Note(now, "REFUSED " + (o.Dir > 0 ? "BUY " : "SELL ") + o.Type + " " + o.Qty + " @ " + Px(o.Price) + " — " + lab); }
                if (qtyCh)
                {
                    if (t.Position == 0 && real != 0)
                    {
                        if (Guard(now, true)) { Broker.Flatten(); Note(now, "FLATTEN (locked by NinjaTrader: closing is allowed)"); waitUntil = now.AddSeconds(4); }
                        sQty = 0; State = lab + " • CLOSING"; return;
                    }
                    refused = true; Note(now, "REFUSED " + (t.Position > real ? "BUY " : "SELL ") + Math.Abs(t.Position - real) + " → " + t.Position + " — " + lab + " (only a full close goes)");
                }
                else if (real != 0 && (stopCh || tgtCh) && (rStop != null || rTgt != null) && (t.StopPts != 0) == (rStop != null) && (t.TargetPts > 0) == (rTgt != null))
                    SetBracket(t.StopPts, t.TargetPts, real, avg, rStop, rTgt, now);   // only MOVING the existing stop / target (no new leg)
                if (refused) Warning = lab + " — ENTRIES REFUSED (closing / cancelling is allowed)";
            }
            if (real == 0 && sQty == 0 && now < waitUntil) return;
            Pull(t, real, avg, rStop, rTgt, rEntries, now);
        }

        // places / moves / removes the real stop and target for the studio's distances (from the REAL average price)
        void SetBracket(double stopPts, double tgtPts, int real, double avg, KeystoneBrokerOrder rStop, KeystoneBrokerOrder rTgt, DateTime now)
        {
            int dir = Math.Sign(real), q = Math.Abs(real);
            bool holdTarget = MinHoldSeconds > 0 && (now - realSince).TotalSeconds < MinHoldSeconds;
            double sp = stopPts != 0 ? Round(avg - dir * stopPts) : double.NaN, tp = tgtPts > 0 && !holdTarget ? Round(avg + dir * tgtPts) : double.NaN;
            // a leg added or removed: rebuild the pair (cancelling one leg of a one-cancels-other pair cancels both)
            bool structure = (rStop == null) != double.IsNaN(sp) || (rTgt == null) != double.IsNaN(tp);
            if (structure && (rStop != null || rTgt != null))
            {
                if (rStop != null) Broker.Cancel(rStop); if (rTgt != null && !rTgt.CancelSent) Broker.Cancel(rTgt);
                Note(now, "BRACKET CHANGED • rebuilding"); bracketWanted = !double.IsNaN(sp) || !double.IsNaN(tp); bracketWait = now.AddSeconds(4); return;
            }
            if (structure)
            {
                string oco = !double.IsNaN(sp) && !double.IsNaN(tp) ? "KA" + now.ToString("HHmmss", CultureInfo.InvariantCulture) + "-" + (++ocoSeq) : "";
                if (!double.IsNaN(sp)) { var s = Send("STOP", -dir * q, sp, oco, now, "STOP " + Px(sp)); if (s != null) protective.Add(s.Id); }
                if (!double.IsNaN(tp)) { var g = Send("LIMIT", -dir * q, tp, oco, now, "TARGET " + Px(tp)); if (g != null) protective.Add(g.Id); }
                bracketWait = now.AddSeconds(4); return;
            }
            if (rStop != null && Math.Abs(rStop.Price - sp) > Tk / 2) { Broker.ChangePrice(rStop, sp); Note(now, "STOP MOVED → " + Px(sp)); }
            if (rTgt != null && Math.Abs(rTgt.Price - tp) > Tk / 2) { Broker.ChangePrice(rTgt, tp); Note(now, "TARGET MOVED → " + Px(tp)); }
        }

        // the studio takes the real account's state (position, stop / target distances, working orders)
        void Pull(KeystoneReplayTrader t, int real, double avg, KeystoneBrokerOrder rStop, KeystoneBrokerOrder rTgt, List<KeystoneBrokerOrder> rEntries, DateTime now)
        {
            int dir = Math.Sign(real);
            double sp = real != 0 && rStop != null ? Math.Round(dir * (avg - rStop.Price) / Tk) * Tk : 0, tp = real != 0 && rTgt != null ? Math.Round(dir * (rTgt.Price - avg) / Tk) * Tk : 0;
            if (real != 0 && rStop != null && sp == 0) sp = -1e-6;   // the real stop sits exactly at the average (break-even): still a stop, never "no stop"
            if (t.Position != real || (real != 0 && Math.Abs(t.AvgPrice - avg) > Tk / 4)) { t.Adopt(real, avg, now); Pulled = true; }
            // flat: the studio's SL / TP stay as the distances for the next entry; a studio entry waiting for its bracket keeps them too
            bool keepIntent = real == 0 || (bracketWanted && rStop == null && rTgt == null);
            if (!keepIntent && (Math.Abs(t.StopPts - sp) > Tk / 4 || Math.Abs(t.TargetPts - tp) > Tk / 4)) { t.StopPts = sp; t.TargetPts = tp; Pulled = true; }
            // working entry orders: the studio shows exactly the real ones
            var byReal = map.ToDictionary(kv => kv.Value, kv => kv.Key);
            foreach (var b in rEntries)
            {
                int id; KeystoneReplayOrder so;
                if (byReal.TryGetValue(b, out id) && (so = t.Orders.FirstOrDefault(o => o.Id == id)) != null) { if (Math.Abs(so.Price - b.Price) > Tk / 4 || so.Qty != b.Qty - b.Filled) { so.Price = b.Price; so.Qty = Math.Max(1, b.Qty - b.Filled); Pulled = true; } sPrice[id] = so.Price; continue; }
                so = t.Place(b.Kind == "STOP" ? "STOP" : "LIMIT", b.Side, Math.Max(1, b.Qty - b.Filled), b.Price); map[so.Id] = b; sPrice[so.Id] = so.Price; Pulled = true;
            }
            var live = new HashSet<KeystoneBrokerOrder>(rEntries);
            foreach (var kv in map.Where(kv => !live.Contains(kv.Value)).ToList()) { t.Orders.RemoveAll(o => o.Id == kv.Key); map.Remove(kv.Key); sPrice.Remove(kv.Key); Pulled = true; }
            sQty = real; sStop = t.StopPts; sTgt = t.TargetPts;
        }
    }

    // EXCEL: a workbook in the Excel XML format (opens in Excel; one sheet per table, numbers stay numbers)
    public static class KeystoneExcel
    {
        static string X(string v) { return System.Security.SecurityElement.Escape(v ?? "") ?? ""; }
        public static string Build(IEnumerable<Tuple<string, List<string[]>>> sheets)
        {
            var sb = new StringBuilder();
            sb.Append("<?xml version=\"1.0\"?>\n<?mso-application progid=\"Excel.Sheet\"?>\n<Workbook xmlns=\"urn:schemas-microsoft-com:office:spreadsheet\" xmlns:ss=\"urn:schemas-microsoft-com:office:spreadsheet\">\n");
            sb.Append("<Styles><Style ss:ID=\"h\"><Font ss:Bold=\"1\"/><Interior ss:Color=\"#DDE6F0\" ss:Pattern=\"Solid\"/></Style></Styles>\n");
            foreach (var sh in sheets)
            {
                string name = new string((sh.Item1 ?? "Sheet").Where(c => c != '/' && c != '\\' && c != '?' && c != '*' && c != '[' && c != ']' && c != ':').Take(31).ToArray());
                sb.Append("<Worksheet ss:Name=\"" + X(name) + "\"><Table>\n"); bool first = true;
                foreach (var row in sh.Item2)
                {
                    sb.Append("<Row>");
                    foreach (var cell in row)
                    {
                        double d; bool num = !first && double.TryParse(cell, NumberStyles.Float, CultureInfo.InvariantCulture, out d) && !string.IsNullOrWhiteSpace(cell);
                        sb.Append("<Cell" + (first ? " ss:StyleID=\"h\"" : "") + "><Data ss:Type=\"" + (num ? "Number" : "String") + "\">" + X(cell) + "</Data></Cell>");
                    }
                    sb.Append("</Row>\n"); first = false;
                }
                sb.Append("</Table></Worksheet>\n");
            }
            sb.Append("</Workbook>\n"); return sb.ToString();
        }
        // a CSV line → cells (quotes kept simple: commas inside quotes stay in the cell)
        public static string[] SplitCsv(string line)
        {
            var o = new List<string>(); var cur = new StringBuilder(); bool q = false;
            foreach (char c in line ?? "") { if (c == '"') q = !q; else if (c == ',' && !q) { o.Add(cur.ToString()); cur.Clear(); } else cur.Append(c); }
            o.Add(cur.ToString()); return o.ToArray();
        }
    }

    // ---- FIRMS FROM NINJATRADER: the prop firm of an account from its name and its connection's name (what NinjaTrader reports),
    // with a short code and a colour used everywhere (pool, copier, rotation, header). Unknown names keep a stable colour of their own.
    public static class KeystoneFirmNames
    {
        // (code, name, colour, name / connection keys — upper case, matched at the start of the account name or anywhere in the connection)
        public static readonly string[][] Known =
        {
            new[] { "LUCID", "Lucid Trading", "#4FC3F7", "LUCID,LT" },
            new[] { "TPT", "Take Profit Trader", "#FFB74D", "TAKEPROFIT,TPT" },
            new[] { "MFFU", "MyFundedFutures", "#BA68C8", "MFFU,MYFUNDED" },
            new[] { "APEX", "Apex Trader Funding", "#E57373", "APEX,PA-APEX" },
            new[] { "TOPSTEP", "Topstep", "#81C784", "TOPSTEP,TOPX,S1" },
            new[] { "TRADEIFY", "Tradeify", "#F06292", "TRADEIFY,TDFY" },
            new[] { "BULENOX", "Bulenox", "#FFD54F", "BULENOX,BX" },
            new[] { "ALPHA", "Alpha Futures", "#4DB6AC", "ALPHA,AFF" },
            new[] { "ELITE", "Elite Trader Funding", "#9575CD", "ELITE,ETF" },
            new[] { "FUNDEDNEXT", "FundedNext Futures", "#AED581", "FUNDEDNEXT,FNF" },
            new[] { "TICKTICK", "TickTickTrader", "#90A4AE", "TICKTICK,TTT" },
            new[] { "SIM", "NinjaTrader Sim", "#9E9E9E", "SIM,DEMO,PLAYBACK" },
        };
        static readonly string[] Palette = { "#26C6DA", "#FF8A65", "#9CCC65", "#7986CB", "#F48FB1", "#FFF176", "#A1887F", "#80CBC4" };
        // the colour you picked for a firm (LIVE TRADING ▸ ACCOUNTS), by firm code — wins over the built-in one everywhere
        public static readonly Dictionary<string, string> Colors = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        public static readonly string[] Choices = { "#FFB74D", "#4FC3F7", "#BA68C8", "#E57373", "#81C784", "#F06292", "#FFD54F", "#4DB6AC", "#9575CD", "#AED581", "#FF8A65", "#90A4AE" };
        public static string SerializeColors() { return string.Join("\n", Colors.OrderBy(kv => kv.Key).Select(kv => kv.Key + "|" + kv.Value)); }
        public static void ParseColors(string text)
        {
            Colors.Clear();
            foreach (var l in (text ?? "").Split('\n')) { var a = l.Trim().Split('|'); if (a.Length == 2 && a[0] != "" && a[1].StartsWith("#") && (a[1].Length == 7 || a[1].Length == 9)) Colors[a[0]] = a[1]; }
        }
        // short names per firm in the order given: TPT 1, TPT 2 … (account → name)
        public static Dictionary<string, string> AutoNicks(IEnumerable<Tuple<string, string>> accountFirm)
        {
            var res = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase); var n = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            foreach (var af in accountFirm) { string code = string.IsNullOrWhiteSpace(af.Item2) ? "ACC" : af.Item2.Trim().ToUpperInvariant(); int k; n.TryGetValue(code, out k); n[code] = ++k; res[af.Item1] = code + " " + k; }
            return res;
        }
        // code • name • colour (hex). An override (the firm you set on the account) wins.
        public static string[] Detect(string account, string connection, string overrideFirm = null)
        {
            var r = DetectRaw(account, connection, overrideFirm); string c; if (Colors.TryGetValue(r[0], out c)) r[2] = c; return r;
        }
        static string[] DetectRaw(string account, string connection, string overrideFirm)
        {
            if (!string.IsNullOrWhiteSpace(overrideFirm))
            {
                string o = overrideFirm.Trim().ToUpperInvariant(); var k = Known.FirstOrDefault(x => x[0] == o || x[1].ToUpperInvariant() == o);
                return k != null ? new[] { k[0], k[1], k[2] } : new[] { o, overrideFirm.Trim(), Palette[Hash(o) % Palette.Length] };
            }
            string a = (account ?? "").Trim().ToUpperInvariant(), c = (connection ?? "").Trim().ToUpperInvariant();
            if (KeystoneSimAccounts.IsSim(a)) { var ks = Known.First(x => x[0] == "SIM"); return new[] { ks[0], ks[1], ks[2] }; }   /* 🎮 BUILD 11i: a NinjaTrader simulation account (Sim101 …) is SIM by its NAME, whatever its connection is called (e.g. TPT_TEST_PRO) */
            foreach (var k in Known)
                foreach (var key in k[3].Split(','))
                {
                    if (key.Length <= 3 ? (a.StartsWith(key) && (a.Length == key.Length || !char.IsLetter(a[key.Length]))) : a.StartsWith(key) || a.Contains(key)) return new[] { k[0], k[1], k[2] };
                    if (key.Length > 3 && c.Contains(key)) return new[] { k[0], k[1], k[2] };
                }
            string guess = new string(a.TakeWhile(char.IsLetter).ToArray()); if (guess.Length < 2) guess = c.Length > 0 ? new string(c.TakeWhile(char.IsLetter).ToArray()) : "ACCOUNT";
            if (guess.Length == 0) guess = "ACCOUNT";
            return new[] { guess, guess, Palette[Hash(guess) % Palette.Length] };
        }
        static int Hash(string s) { int h = 17; foreach (char ch in s ?? "") h = unchecked(h * 31 + ch); return Math.Abs(h % 100000); }
    }

    // ---- LIVE RANDOM ROTATION (MNQ + MGC on ONE account at a time): the rotation of the Backtest Studio's prop simulation on real
    // accounts. Each pool account has two links (MNQ and MGC: its own limits, arm, lock) and two mirror traders. ENTER (BUY BOTH /
    // SELL BOTH / BUY MNQ • SELL MGC / SELL MNQ • BUY MGC, or AUTO's side) opens both legs on the account in turn — each leg with a hard
    // stop AT THE BROKER (the whole combined stop in that leg's points: safe if the platform or the connection drops). The combined
    // P/L (both legs, real fills) is watched: + TARGET (after the minimum hold on funded accounts) or − STOP (trailing: the stop follows
    // the best combined P/L, its stop $ below) closes both legs. Then the PAUSE, then the next account (the pool's order, drag & drop).
    // Each account: at most MaxTradesPerDay a day, done for the day at its DAY TARGET / DAY STOP (its NinjaTrader P/L today). AUTO enters
    // by itself after the pause; MANUAL waits for a button (the chosen account first, else the next in turn). Every finished trade
    // is kept (Finished) for the journal and the learning log (the sides, both instruments' last-5-minute moves, the result).
    public sealed class KeystoneDuoSeat
    {
        public string Account = "", Firm = "", Color = "#9E9E9E"; public KeystoneAccountLink LinkM, LinkG; public KeystoneReplayTrader MirM, MirG;
        public bool Paused, DoneToday, Funded; public string Status = "", DoneWhy = ""; public int TradesToday; public DateTime Day = DateTime.MinValue;
        // GROUP ROTATION: the other accounts of a copy group trade the same sides with this seat (its P/L decides target / stop) — Label = the group
        public readonly List<KeystoneDuoSeat> Mates = new List<KeystoneDuoSeat>(); public string Label = "";
    }
    public sealed class KeystoneDuoTrade
    {
        public DateTime Entry, Exit; public string Account = "", Firm = "", Reason = ""; public int DirM, DirG, QtyM, QtyG; public double Pnl, Peak, Worst, MoveM5, MoveG5;
        public string Sides { get { return KeystoneSimRotation.SidesName(DirM, DirG); } }
        public const string Header = "entry,exit,account,firm,mnq,mgc,qty_mnq,qty_mgc,pnl,peak,worst,reason,mnq_last5,mgc_last5";
        public string Line() { var ic = CultureInfo.InvariantCulture; return string.Join(",", Entry.ToString("yyyy-MM-dd HH:mm:ss", ic), Exit.ToString("yyyy-MM-dd HH:mm:ss", ic), Account.Replace(",", " "), Firm.Replace(",", " "), DirM, DirG, QtyM, QtyG, Pnl.ToString("0.00", ic), Peak.ToString("0.00", ic), Worst.ToString("0.00", ic), (Reason ?? "").Replace(",", ";"), MoveM5.ToString("0.00", ic), MoveG5.ToString("0.00", ic)); }
    }
    public sealed class KeystoneDuoRotation
    {
        public readonly List<KeystoneDuoSeat> Pool = new List<KeystoneDuoSeat>();
        public int QtyM = 2, QtyG = 2, MaxTradesPerDay = 1, PauseSeconds = 25, HoldSeconds = 11; public double Target = 1500, Stop = 500, DayTarget, DayStop;
        public double PvM = 2, PvG = 10; public bool Auto, Trail = true, HoldOnFunded = true, InHours = true; public string Direction = "RANDOM";
        public Func<DateTime, DateTime> DayOf = t => t.Date;
        public KeystoneDuoSeat Current { get; private set; }
        public KeystoneDuoSeat Selected;   // a click on an account: the next ENTER goes there (if it may trade)
        public DateTime EntryTime, PauseUntil = DateTime.MinValue; public int DirM, DirG; public double Peak, Worst, Floor, Open; public string Status = "READY", LastReason = "";
        public readonly List<KeystoneDuoTrade> Finished = new List<KeystoneDuoTrade>();   // new finished trades (the UI saves and clears them)
        readonly KeystoneSimRotation sides; int turn = -1; bool filled, closing; double dayPnlAtEntry, moveM5, moveG5; DateTime closeSentAt;
        public KeystoneDuoRotation(int seed) { sides = new KeystoneSimRotation(seed); }

        static int Real(KeystoneAccountLink l) { try { return l == null ? 0 : l.Broker.Qty; } catch { return 0; } }
        static bool BrokerOn(KeystoneAccountLink l) { try { return l.Broker.Connected; } catch { return false; } }
        static double DayPnlOf(KeystoneDuoSeat s) { try { return s.LinkM != null ? s.LinkM.Broker.DayPnl : s.LinkG.Broker.DayPnl; } catch { return 0; } }
        public bool Flat(KeystoneDuoSeat s) { return Real(s.LinkM) == 0 && Real(s.LinkG) == 0; }
        public bool Eligible(KeystoneDuoSeat s)
        {
            if (s == null || s.Paused || s.DoneToday || s.TradesToday >= Math.Max(1, MaxTradesPerDay)) return false;
            foreach (var l in new[] { s.LinkM, s.LinkG }) if (l != null && (!BrokerOn(l) || !l.Armed || l.Locked)) return false;
            return (s.LinkM != null || s.LinkG != null) && Flat(s);
        }
        public KeystoneDuoSeat Next() { int n = Pool.Count; for (int j = 1; j <= n; j++) { var s = Pool[((turn + j) % n + n) % n]; if (Eligible(s)) return s; } return null; }
        public void Move(int from, int to) { if (from < 0 || from >= Pool.Count || to < 0 || to >= Pool.Count || from == to) return; var s = Pool[from]; Pool.RemoveAt(from); Pool.Insert(to, s); }
        // one combined leg's open $ (the real position at the broker, the live price)
        static double LegOpen(KeystoneAccountLink l, double px, double pv) { try { int q = l == null ? 0 : l.Broker.Qty; return q == 0 || double.IsNaN(px) ? 0 : (px - l.Broker.AvgPrice) * q * pv; } catch { return 0; } }

        // ENTER both legs on the chosen / next account → "" or why not
        public string Enter(int dM, int dG, DateTime now, double pxM, double pxG, double move5M = 0, double move5G = 0)
        {
            if (Current != null) return "a rotation trade is open";
            if (dM == 0 && dG == 0) return "no side";
            var s = Selected != null && Eligible(Selected) ? Selected : Next(); if (s == null) return "no account may trade now (armed, flat, under its day limits, not done today)";
            Current = s; turn = Pool.IndexOf(s); Selected = null; filled = false; closing = false; DirM = dM; DirG = dG; EntryTime = now; Peak = 0; Worst = 0; Open = 0; Floor = -Math.Abs(Stop);
            dayPnlAtEntry = DayPnlOf(s); moveM5 = move5M; moveG5 = move5G; LastReason = "";
            if (s.LinkM != null && dM != 0 && QtyM > 0) { s.MirM.Price = pxM; s.MirM.Time = now; s.MirM.StopPts = HardStopPts(PvM, QtyM); s.MirM.TargetPts = 0; s.MirM.Adopt(dM * QtyM, pxM, now); }
            if (s.LinkG != null && dG != 0 && QtyG > 0) { s.MirG.Price = pxG; s.MirG.Time = now; s.MirG.StopPts = HardStopPts(PvG, QtyG); s.MirG.TargetPts = 0; s.MirG.Adopt(dG * QtyG, pxG, now); }
            foreach (var m in s.Mates.Where(x => !x.Paused && Flat(x) && (x.LinkM == null || (x.LinkM.Armed && !x.LinkM.Locked)) && (x.LinkG == null || (x.LinkG.Armed && !x.LinkG.Locked))))
            {
                if (m.LinkM != null && dM != 0 && QtyM > 0) { m.MirM.Price = pxM; m.MirM.Time = now; m.MirM.StopPts = HardStopPts(PvM, QtyM); m.MirM.TargetPts = 0; m.MirM.Adopt(dM * QtyM, pxM, now); }
                if (m.LinkG != null && dG != 0 && QtyG > 0) { m.MirG.Price = pxG; m.MirG.Time = now; m.MirG.StopPts = HardStopPts(PvG, QtyG); m.MirG.TargetPts = 0; m.MirG.Adopt(dG * QtyG, pxG, now); }
            }
            Status = "→ " + (s.Label != "" ? s.Label : s.Account) + " • " + KeystoneSimRotation.SidesName(dM, dG); return "";
        }
        // the safety stop at the broker on each leg: the whole combined stop in that leg's points (rounded to the tick)
        double HardStopPts(double pv, int q) { double pts = Math.Abs(Stop) / Math.Max(1e-9, pv * Math.Max(1, q)); return Math.Max(0.25, pts); }
        public void CloseAll(string why, DateTime now)
        {
            if (Current == null) return; closing = true; closeSentAt = now; LastReason = why;
            foreach (var m in new[] { Current.MirM, Current.MirG }) if (m != null) { m.Orders.Clear(); if (m.Position != 0) m.Adopt(0, 0, now); }
            CloseMates(Current, now);
        }
        static void CloseMates(KeystoneDuoSeat c, DateTime now) { foreach (var mt in c.Mates) foreach (var m in new[] { mt.MirM, mt.MirG }) if (m != null) { m.Orders.Clear(); if (m.Position != 0) m.Adopt(0, 0, now); m.StopPts = 0; } }
        IEnumerable<KeystoneDuoSeat> Everyone() { foreach (var s in Pool) { yield return s; foreach (var m in s.Mates) yield return m; } }
        // AUTO: the side to take (the preset: RANDOM, BUY, SELL, BS, SB, RANDOMHEDGE, RANDOM4, CYCLE4, FOLLOW5, FADE5 …)
        public Tuple<int, int> PickSides(double move5M, double move5G) { return sides.PickDirs(Direction, move5M, move5G); }

        public void Tick(double pxM, double pxG, DateTime now, double move5M = 0, double move5G = 0)
        {
            var day = DayOf(now);
            foreach (var s in Everyone())
            {
                if (s.Day != day) { s.Day = day; s.TradesToday = 0; s.DoneToday = false; s.DoneWhy = ""; }
                if (s.MirM != null) { s.MirM.Price = pxM; s.MirM.Time = now; } if (s.MirG != null) { s.MirG.Price = pxG; s.MirG.Time = now; }
                foreach (var l in new[] { s.LinkM, s.LinkG }) if (l != null) l.MinHoldSeconds = HoldOnFunded && s.Funded ? Math.Max(0, HoldSeconds) : 0;
            }
            if (Current != null)
            {
                var c = Current; int rM = Real(c.LinkM), rG = Real(c.LinkG); bool anyReal = rM != 0 || rG != 0;
                if (anyReal) filled = true;
                Open = LegOpen(c.LinkM, pxM, PvM) + LegOpen(c.LinkG, pxG, PvG);
                if (filled && anyReal && !closing)
                {
                    Peak = Math.Max(Peak, Open); Worst = Math.Min(Worst, Open);
                    if (Trail) Floor = Math.Max(Floor, Peak - Math.Abs(Stop));
                    bool holdOk = !(HoldOnFunded && c.Funded) || (now - EntryTime).TotalSeconds >= HoldSeconds;
                    if (Open <= Floor + 1e-9) CloseAll(Floor > -Math.Abs(Stop) + 1e-9 ? "TRAIL STOP" : "STOP", now);
                    else if (Open >= Target - 1e-9 && holdOk) CloseAll("TARGET", now);
                }
                // never filled (refused / no fill in 15 s) → release, the account keeps its turn
                if (!filled && !closing && (now - EntryTime).TotalSeconds > 15) { CloseAll("NOT FILLED", now); }
                // both legs flat after a fill (our close, the broker's hard stop, or closed in NinjaTrader) → the trade is over
                if ((filled || closing) && !anyReal && (closing || filled))
                {
                    bool done = (c.LinkM == null || Real(c.LinkM) == 0) && (c.LinkG == null || Real(c.LinkG) == 0);
                    if (done && (!closing || (now - closeSentAt).TotalSeconds >= 0))
                    {
                        if (filled)
                        {
                            double pnl = DayPnlOf(c) - dayPnlAtEntry;
                            Finished.Add(new KeystoneDuoTrade { Entry = EntryTime, Exit = now, Account = c.Account, Firm = c.Firm, DirM = DirM, DirG = DirG, QtyM = QtyM, QtyG = QtyG, Pnl = pnl, Peak = Peak, Worst = Worst, Reason = LastReason == "" ? "CLOSED AT THE BROKER / IN NINJATRADER" : LastReason, MoveM5 = moveM5, MoveG5 = moveG5 });
                            c.TradesToday++; double dp = DayPnlOf(c);
                            if (DayTarget > 0 && dp >= DayTarget - 1e-9) { c.DoneToday = true; c.DoneWhy = "DAY TARGET"; }
                            else if (DayStop > 0 && dp <= -Math.Abs(DayStop) + 1e-9) { c.DoneToday = true; c.DoneWhy = "DAY STOP"; }
                            else if (c.TradesToday >= Math.Max(1, MaxTradesPerDay)) { c.DoneToday = true; c.DoneWhy = c.TradesToday + " TRADE" + (c.TradesToday == 1 ? "" : "S") + " TODAY"; }
                            PauseUntil = now.AddSeconds(Math.Max(0, PauseSeconds)); Status = "DONE • " + c.Account + " " + (pnl >= 0 ? "+" : "−") + "$" + Math.Abs(pnl).ToString("N0", CultureInfo.InvariantCulture) + " • " + (LastReason == "" ? "closed" : LastReason);
                        }
                        else { turn = Pool.IndexOf(c) - 1; Status = "NOT FILLED • " + c.Account + " keeps its turn"; PauseUntil = now.AddSeconds(5); }
                        foreach (var m in new[] { c.MirM, c.MirG }) if (m != null) { m.Orders.Clear(); m.StopPts = 0; m.TargetPts = 0; }
                        CloseMates(c, now);   // its broker stop closed the seat → the group's other accounts close with it
                        Current = null; filled = false; closing = false;
                    }
                }
            }
            // AUTO: after the pause (and only inside the trading hours) the next account enters by itself
            if (Current == null && Auto && InHours && now >= PauseUntil)
            {
                var sd = PickSides(move5M, move5G);
                if (sd.Item1 != 0 || sd.Item2 != 0) { string why = Enter(sd.Item1, sd.Item2, now, pxM, pxG, move5M, move5G); if (why != "") Status = "AUTO WAITING • " + why; }
                else Status = "AUTO WAITING • no side yet (" + Direction + ")";
            }
            else if (Current == null && Auto && now < PauseUntil) Status = "PAUSE • next in " + Math.Ceiling((PauseUntil - now).TotalSeconds) + " s";
            // every account's links: the intent (mirror) → real orders (only while armed)
            foreach (var s in Pool) foreach (var m in s.Mates)
            {
                if (m.LinkM != null && m.MirM != null) m.LinkM.Tick(m.MirM, now);
                if (m.LinkG != null && m.MirG != null) m.LinkG.Tick(m.MirG, now);
                m.Status = s == Current ? (Flat(m) ? "with " + (s.Label != "" ? s.Label : s.Account) : "IN THE TRADE (group)") : Flat(m) ? "ready (group)" : "HOLDS A POSITION";
            }
            foreach (var s in Pool)
            {
                if (s.LinkM != null && s.MirM != null) s.LinkM.Tick(s.MirM, now);
                if (s.LinkG != null && s.MirG != null) s.LinkG.Tick(s.MirG, now);
                bool armed = (s.LinkM == null || s.LinkM.Armed) && (s.LinkG == null || s.LinkG.Armed), conn = (s.LinkM == null || BrokerOn(s.LinkM)) && (s.LinkG == null || BrokerOn(s.LinkG));
                s.Status = s == Current ? (closing ? "CLOSING" : filled ? "IN THE TRADE " + (Open >= 0 ? "+" : "−") + "$" + Math.Abs(Open).ToString("N0", CultureInfo.InvariantCulture) : "ORDER SENT")
                    : !conn ? "NOT CONNECTED" : !armed ? "NOT ARMED" : s.Paused ? "PAUSED" : (s.LinkM != null && s.LinkM.Locked) || (s.LinkG != null && s.LinkG.Locked) ? "LOCKED" : s.DoneToday ? "DONE TODAY • " + s.DoneWhy : !Flat(s) ? "HOLDS A POSITION" : s == Selected ? "NEXT (CHOSEN)" : "READY";
            }
        }
    }

    // ---- ROTATION: the chart's strategy (a simulated "leader", not linked to any account) trades a POOL of real accounts, one
    // account per trade, in turn. Each pool account has its own link (its own limits, arm, lock) and a mirror trader. When the
    // leader places its entry (a working limit / stop) or opens a position, the account in turn receives it: the working order is
    // placed on that account, a fill on the leader that the account did not get becomes a market order, the leader's stop / target
    // distances follow, and the account closes when the leader is flat. Only ONE account holds the trade, so nothing is ever on both
    // sides. ONE PER DAY: an account that traded today waits until tomorrow. MANUAL (firms that forbid automation): nothing is sent
    // until you press ENTER; after the trade, NEXT ACCOUNT picks the next one. HOLD: the funded accounts' minimum hold (seconds)
    // before a target / exit (the stop is always at the broker at once).
    public sealed class KeystoneRotator
    {
        public readonly List<KeystoneCopyFollower> Pool = new List<KeystoneCopyFollower>();
        public bool Manual, OnePerDay = true, HoldOn = true; public int HoldSeconds = 11;
        public Func<string, bool> IsFunded = a => false;
        public Func<DateTime, DateTime> DayOf = t => t.Date;   // the trading day (live: New York, a new day at 18:00)
        public KeystoneCopyFollower Current { get; private set; }
        public KeystoneCopyFollower Selected;   // MANUAL: the account the next ENTER goes to
        public bool Go, AwaitNext; public string Status = "WAITING FOR A SETUP";
        int turn = -1, turnBefore = -1; bool filled, done; readonly Dictionary<string, DateTime> tradedOn = new Dictionary<string, DateTime>(StringComparer.OrdinalIgnoreCase);
        readonly Dictionary<int, int> om = new Dictionary<int, int>();   // leader order id → mirror order id

        static int Real(KeystoneCopyFollower f) { try { return f.Link.Broker.Qty; } catch { return 0; } }
        public bool TradedToday(KeystoneCopyFollower f, DateTime day) { DateTime d; return tradedOn.TryGetValue(f.Account, out d) && d == day.Date; }
        public bool Eligible(KeystoneCopyFollower f, DateTime day)
        {
            return f != null && !f.Paused && f.Link != null && f.Mirror != null && f.Link.Connected && f.Link.Armed && !f.Link.Locked && Real(f) == 0 && !(OnePerDay && TradedToday(f, day));
        }
        // the next account in turn that may trade now (after `from`), or null
        public KeystoneCopyFollower Peek(DateTime day, int from)
        {
            int n = Pool.Count; for (int j = 1; j <= n; j++) { var f = Pool[((from + j) % n + n) % n]; if (Eligible(f, day)) return f; }
            return null;
        }
        // MANUAL: NEXT ACCOUNT
        public void Advance(DateTime day) { if (Current != null) return; int from = Selected != null ? Pool.IndexOf(Selected) : turn; Selected = Peek(day, from); AwaitNext = false; }

        public void Tick(KeystoneReplayTrader leader, DateTime now)
        {
            if (leader == null) return; var day = DayOf(now);
            bool busy = leader.Position != 0 || leader.Orders.Count > 0;
            foreach (var f in Pool) if (f.Link != null) f.Link.MinHoldSeconds = HoldOn && IsFunded(f.Account) ? Math.Max(0, HoldSeconds) : 0;
            // 1. a new setup on the leader → the account in turn
            if (Current == null && busy)
            {
                KeystoneCopyFollower pick = null;
                if (Manual) { if (Selected != null && !Eligible(Selected, day)) Selected = null; if (Selected == null && !AwaitNext) Selected = Peek(day, turn); if (Go && Selected != null) pick = Selected; }
                else pick = Peek(day, turn);
                if (pick != null) { Current = pick; turnBefore = turn; turn = Pool.IndexOf(pick); filled = false; done = false; om.Clear(); Go = false; Selected = null; }
                Status = Current != null ? "→ " + Current.Account : Manual ? (AwaitNext ? "SETUP • press NEXT ACCOUNT, then ENTER" : Selected != null ? "SETUP • press ENTER for " + Selected.Account : "SETUP • no account free") : "SETUP SKIPPED • no account free (armed, flat, not traded today)";
            }
            else if (!busy && Current == null) { Status = Manual && AwaitNext ? "DONE • press NEXT ACCOUNT" : "WAITING FOR A SETUP" + (Manual && Selected != null ? " • next: " + Selected.Account : ""); if (Manual && Selected == null && !AwaitNext) Selected = Peek(day, turn); }
            // 2. the current account mirrors the leader
            foreach (var f in Pool)
            {
                var m = f.Mirror; if (m == null || f.Link == null) continue; m.Price = leader.Price; m.Time = leader.Time;
                if (f == Current)
                {
                    int real = Real(f); if (real != 0) { if (!filled) tradedOn[f.Account] = day; filled = true; }
                    if (filled && real == 0 && leader.Position != 0) done = true;   // its own stop / target closed it: it sits the rest out
                    if (!done && busy)
                    {
                        // working entry orders
                        var ids = new HashSet<int>(leader.Orders.Select(o => o.Id));
                        foreach (var lo in leader.Orders)
                        {
                            int mid; KeystoneReplayOrder mo;
                            if (om.TryGetValue(lo.Id, out mid) && (mo = m.Orders.FirstOrDefault(o => o.Id == mid)) != null) { mo.Price = lo.Price; mo.Qty = Math.Max(1, Math.Min(lo.Qty, f.MaxQty)); }
                            else if (real == 0 && !filled) { mo = m.Place(lo.Type, lo.Dir, Math.Min(lo.Qty, f.MaxQty), lo.Price); om[lo.Id] = mo.Id; }
                        }
                        foreach (var kv in om.Where(kv => !ids.Contains(kv.Key)).ToList()) { m.Orders.RemoveAll(o => o.Id == kv.Value); om.Remove(kv.Key); }
                        // the position (a leader fill the account did not get → market) and its stop / target distances
                        int want = leader.Position == 0 ? 0 : KeystoneCopier.Desired(leader.Position, 1, f.MaxQty);
                        if (want != 0 && m.Position != want) m.Adopt(want, leader.AvgPrice, now);
                        if (want != 0) { m.StopPts = leader.StopPts; m.TargetPts = KeystoneCopier.TargetFor(leader.TargetPts, f, Math.Abs(want), leader.Symbol, leader.Tick); }
                    }
                    else if (!busy || done)
                    {
                        if (m.Orders.Count > 0) { m.Orders.Clear(); om.Clear(); }
                        if (!busy && m.Position != 0) m.Adopt(0, 0, now);
                    }
                }
                f.Link.Tick(m, now);
                f.Status = f.Link.Locked ? "LOCKED" : f.Paused ? "PAUSED" : !f.Link.Connected ? "NOT CONNECTED" : !f.Link.Armed ? "NOT ARMED" : f == Current ? (done ? "SAT OUT (its stop / target hit)" : Real(f) != 0 ? "IN THE TRADE • " + f.Link.State : "ORDER WORKING • " + f.Link.State) : TradedToday(f, day) ? "TRADED TODAY" : f == Selected ? "NEXT (MANUAL)" : "READY";
            }
            // 3. the trade is over: the leader is idle and the account flat with nothing working → release (no fill: it keeps its turn)
            if (Current != null && !busy && Real(Current) == 0 && Current.Mirror.Orders.Count == 0)
            {
                bool wasFilled = filled; if (!filled) turn = turnBefore;
                Current = null; om.Clear(); if (Manual && wasFilled) AwaitNext = true; Status = wasFilled ? "TRADE DONE" : "ORDER EXPIRED • the account keeps its turn";
            }
        }
    }

    // ---- 🤖 LIVE AUTOPILOT (BUILD 2026-11-11g) ------------------------------------------------------------------------------------
    // The labs' plans on the user's REAL prop accounts — through the SAME safe path as ● LIVE TRADING ▸ 🔄 ROTATE: every order is the
    // intent of a mirror trader that the account's own armed KeystoneAccountLink turns into real orders (its limits: max contracts, day
    // loss, day profit cap, runaway guard 8 entries a minute, stops / targets / closes counted apart, a reject disarms). No new order path.
    // Each account handed over by 🧪 EVAL LAB ▸ ● LIVE ✓ CONFIRM (autopilot-feed.txt next to RotationPool.txt) carries its GROUP's plan:
    //   eval default  = ⚡ ALL AT ONCE 2:00 AM NY • MNQ 20 • TP +$1,500 after costs (a LIMIT at the broker) • a STOP at the account's floor
    //                   (balance − floor room, costs and 2 ticks of safety off) so the trade rides the room with the stop at the broker
    //   funded default = 🛟 SAFE PAYOUT • MNQ 1 (TPT PRO: MNQ 2) • TP +$800 / SL −$300 at the account's own time (the plan's times, spread)
    // Side = one coin per firm per time slot (KeystoneLabFlow.SideOf, the labs' hash coin), and an account never takes the other side of a
    // position its firm already holds. One trade per account per day; positions are closed at 16:54 NY.
    // GUIDED (every firm; always for TPT): at the entry minute a ticket flashes with the exact size / TP / stop; ONE press places the bracket
    // through the armed link; SKIP lets it go; no press within 2 minutes = MISSED (no late entry).
    // AUTO (Lucid / Tradeify only, where KeystoneFirmPolicies allows automation for the stage): the same bracket at the entry minute by itself,
    // only while Running — START needs every link ARMED and, when any seat is AUTO, the word START typed. DISARM / ⛔ CLOSE ALL / LOCK FOR
    // TODAY / closing the window stop it (Stop: the links are disarmed, positions stay with their broker brackets). Pure: no UI here.
    public sealed class KeystoneAutoPlan
    {
        public string Name = "", Group = "", Side = "FIRM"; public int Qty = 20; public double TpUsd = 1500, StopUsd; public int[] Times = { 200 }; public bool Tiny;
        public static KeystoneAutoPlan EvalDefault() { return new KeystoneAutoPlan { Name = "★ ALL AT ONCE 2:00 AM NY (the default)", Qty = 20, TpUsd = 1500, StopUsd = 0, Times = new[] { 200 } }; }
        public static KeystoneAutoPlan FundedDefault(bool tpt) { return new KeystoneAutoPlan { Name = "🛟 SAFE PAYOUT" + (tpt ? " (TPT PRO: MNQ 2, beat the trailing drawdown first)" : ""), Qty = tpt ? 2 : 1, TpUsd = 800, StopUsd = 300, Times = new[] { 200, 830, 930, 1000, 1100 } }; }
        // the group's plan as the labs save it (pools.txt: plan / mnq / tp / stop / times / side) — anything missing = the default
        public static KeystoneAutoPlan FromMap(IDictionary<string, string> m, bool funded, bool tpt, string group)
        {
            var p = funded ? FundedDefault(tpt) : EvalDefault(); p.Group = group ?? ""; if (m == null || m.Count == 0) return p;
            Func<string, string> g = k => { string v; return m.TryGetValue(k, out v) ? (v ?? "").Trim() : ""; };
            int q; double d; var ic = CultureInfo.InvariantCulture;
            if (int.TryParse(g("mnq"), NumberStyles.Integer, ic, out q) && q > 0) p.Qty = Math.Min(50, q);
            if (double.TryParse(g("tp"), NumberStyles.Float, ic, out d) && d > 0) p.TpUsd = d;
            if (double.TryParse(g("stop"), NumberStyles.Float, ic, out d) && d >= 0) p.StopUsd = d;
            var t = KeystoneLabFlow.ParseTimes(g("times")); if (t != null) p.Times = t;
            string sd = g("side").ToUpperInvariant(); if (sd == "LONG" || sd == "BUY") p.Side = "BUY"; else if (sd == "SHORT" || sd == "SELL") p.Side = "SELL"; else if (sd == "EACH" || sd == "ALL") p.Side = sd; else p.Side = "FIRM";
            if (g("plan") != "") p.Name = g("plan");
            // TPT PRO funded on the untouched 🛟 SAFE PAYOUT default: MNQ 2 (the user's plan), the same bracket
            if (funded && tpt && g("plan").StartsWith("🛟 SAFE PAYOUT") && g("mnq") == "1") { p.Qty = 2; p.Name = "🛟 SAFE PAYOUT (TPT PRO: MNQ 2, beat the trailing drawdown first)"; }
            return p;
        }
        public string Words() { return "MNQ " + Qty + " · TP +" + KeystoneAutopilot.Usd(TpUsd) + " · " + (StopUsd <= 0 ? "stop at the floor" : "SL −" + KeystoneAutopilot.Usd(StopUsd)) + " · at " + string.Join(" / ", Times.Select(h => (h / 100) + ":" + (h % 100).ToString("00"))) + " NY"; }
    }
    // one account handed over by the labs (autopilot-feed.txt: account|firm|stage|owner|group|nick|start|dd|target|mindays|daystraded|balance|plan k=v;…)
    public sealed class KeystoneAutoFeed
    {
        public string Account = "", Firm = "", Stage = "EVAL", Owner = "ME", Group = "", Nick = ""; public double Start, Dd, Target, Balance; public int MinDays, DaysTraded; public Dictionary<string, string> Plan = new Dictionary<string, string>();
        public string Line()
        {
            var ic = CultureInfo.InvariantCulture; Func<string, string> c = s => (s ?? "").Replace("|", " ").Replace("\n", " ").Replace("\r", " ");
            return string.Join("|", c(Account), c(Firm), c(Stage), c(Owner), c(Group), c(Nick), Start.ToString("0.##", ic), Dd.ToString("0.##", ic), Target.ToString("0.##", ic), MinDays.ToString(ic), DaysTraded.ToString(ic), Balance.ToString("0.##", ic),
                string.Join(";", Plan.Select(kv => c(kv.Key).Replace(";", " ").Replace("=", " ") + "=" + c(kv.Value).Replace(";", " ").Replace("=", " "))));
        }
        public static List<KeystoneAutoFeed> Parse(string text)
        {
            var res = new List<KeystoneAutoFeed>(); var ic = CultureInfo.InvariantCulture; var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var l in (text ?? "").Split('\n'))
            {
                var a = l.TrimEnd('\r').Split('|'); if (a.Length < 13 || a[0].Trim() == "" || a[0].StartsWith("#") || !seen.Add(a[0].Trim())) continue;
                var f = new KeystoneAutoFeed { Account = a[0].Trim(), Firm = a[1].Trim().ToUpperInvariant(), Stage = a[2].Trim() == "FUNDED" ? "FUNDED" : "EVAL", Owner = a[3].Trim() == "" ? "ME" : a[3].Trim(), Group = a[4].Trim(), Nick = a[5].Trim() };
                double d; int n;
                if (double.TryParse(a[6], NumberStyles.Float, ic, out d)) f.Start = d; if (double.TryParse(a[7], NumberStyles.Float, ic, out d)) f.Dd = d; if (double.TryParse(a[8], NumberStyles.Float, ic, out d)) f.Target = d;
                if (int.TryParse(a[9], NumberStyles.Integer, ic, out n)) f.MinDays = n; if (int.TryParse(a[10], NumberStyles.Integer, ic, out n)) f.DaysTraded = n; if (double.TryParse(a[11], NumberStyles.Float, ic, out d)) f.Balance = d;
                foreach (var kv in a[12].Split(';')) { var p = kv.Split('='); if (p.Length == 2 && p[0].Trim() != "") f.Plan[p[0].Trim()] = p[1].Trim(); }
                res.Add(f);
            }
            return res;
        }
        public static string Text(IEnumerable<KeystoneAutoFeed> feeds) { return "# 🤖 LIVE AUTOPILOT feed (written by 🧪 EVAL LAB ▸ ● LIVE ✓ CONFIRM) — account|firm|stage|owner|group|nick|start|dd|target|mindays|daystraded|balance|plan\n" + string.Join("\n", (feeds ?? Enumerable.Empty<KeystoneAutoFeed>()).Select(f => f.Line())); }
    }
