    public sealed class KeystoneAutopilot
    {
        public readonly List<KeystoneAutoSeat> Seats = new List<KeystoneAutoSeat>();
        public bool Running { get; private set; }
        public string Status = "NOT STARTED", StopWhy = "";
        public readonly List<KeystoneAutoRow> Journal = new List<KeystoneAutoRow>(), NewRows = new List<KeystoneAutoRow>();   // NewRows: written by the UI, then cleared
        public Func<DateTime, DateTime> DayOf = t => t.Hour >= 18 ? t.Date.AddDays(1) : t.Date;   // the NY trading day (a new day at 18:00)
        public TimeSpan FlattenAt = new TimeSpan(16, 54, 0); public int LateMinutes = 2, FillWaitSeconds = 30, Seed; public string Symbol = "MNQ";
        public const string StartWord = "START";
        public static string Usd(double v) { return "$" + Math.Round(Math.Abs(v)).ToString("N0", CultureInfo.InvariantCulture); }
        // AUTO only for Lucid / Tradeify AND where the firm's rules (KeystoneFirmPolicies + the 🏢 FIRMS & RULES book) allow automation for the stage — TPT never
        public static bool AutoFirm(string firm) { string f = (firm ?? "").Trim().ToUpperInvariant(); return f == "LUCID" || f == "TRADEIFY"; }
        public static bool AutoAllowedFor(string firm, string stage)
        {
            string f = (firm ?? "").Trim().ToUpperInvariant(); if (f == "TPT" || !AutoFirm(f)) return false; bool funded = stage == "FUNDED";
            if (!KeystoneFirmPolicies.AutoAllowed(f, funded)) return false;
            KeystonePayoutRules bk = null; try { bk = KeystonePayoutRules.BookOf(f); } catch { } if (bk != null && !(funded ? bk.AutoFunded : bk.AutoEval)) return false;
            return true;
        }
        // why AUTO cannot be used on this account ("" = it can)
        public static string AutoWhyNot(string firm, string stage)
        {
            string f = (firm ?? "").Trim().ToUpperInvariant();
            if (f == "TPT") return "TPT: always GUIDED (no automation — firm rule)";
            if (!AutoFirm(f)) return KeystonePipeline.Nice(f) + ": AUTO is offered for Lucid / Tradeify only — GUIDED";
            if (!AutoAllowedFor(f, stage)) return KeystonePipeline.Nice(f) + " " + (stage == "FUNDED" ? "funded" : "eval") + ": automation is OFF in its rules (👥 ACCOUNTS ▸ RULES / 🏢 FIRMS & RULES) — GUIDED";
            return "";
        }
        // the account's floor: start − drawdown, trailing the best end-of-day balance (funded: locks at start + $100, TPT at the start)
        public static double FloorOf(double start, double dd, bool funded, string firm, IList<KeystoneLiveDay> days, DateTime today)
        {
            double fl = start - dd; if (dd <= 0) return 0;
            double peak = start; foreach (var d in days ?? new List<KeystoneLiveDay>()) if (d.Date.Date < today.Date && d.EndBal > peak) peak = d.EndBal;
            double trail = peak - dd; if (funded) trail = Math.Min(trail, (firm ?? "").ToUpperInvariant() == "TPT" ? start : start + 100);
            return Math.Max(fl, trail);
        }
        // 💰 a funded account's payout reminder ("" = not yet) — a reminder only: requests are made on the firm's site
        public static string PayoutNote(KeystoneAutoSeat s)
        {
            if (s == null || !s.Funded) return ""; var r = KeystonePayoutRules.BookOf(s.Firm) ?? KeystonePayoutRules.For(s.Firm, KeystonePayoutRules.Presets()); if (r == null || r.Parked) return "";
            double p = s.Balance - s.Start; if (p <= 0) return "";
            if (r.Tpt) return p >= r.Dd + r.Cap - 1e-9 ? "💰 payout ready: request " + Usd(r.Cap) : "";
            int q = (s.Days ?? new List<KeystoneLiveDay>()).Count(x => x.Trades > 0 && x.Pnl >= r.QualMin - 1e-9); double due = r.Due(p, false);
            return q >= r.QualDays && due > 0 ? "💰 payout ready: request " + Usd(due) : "";
        }
        public static DateTime EntryAt(DateTime day, int hhmm) { var t = new TimeSpan(hhmm / 100, hhmm % 100, 0); return hhmm >= 1800 ? day.Date.AddDays(-1) + t : day.Date + t; }
        public static double Cost { get { return KeystoneMoveStudy.Cost("MNQ"); } }
        public static double Pv { get { return KeystoneMoveStudy.PointValue("MNQ"); } }
        // TP points so that closing `qty` there makes at least `usd` after the round-trip costs (rounded UP to the tick)
        public static double TpPoints(double usd, int qty, double tick) { if (qty <= 0 || tick <= 0) return 0; double pts = (usd + Cost * qty) / (Pv * qty); return Math.Ceiling(pts / tick - 1e-9) * tick; }
        // stop points so that the loss incl. costs stays within `usd` (rounded DOWN to the tick), minus `safetyTicks`
        public static double StopPoints(double usd, int qty, double tick, int safetyTicks) { if (qty <= 0 || tick <= 0 || usd <= 0) return 0; double pts = (usd - Cost * qty) / (Pv * qty); return Math.Floor(pts / tick + 1e-9) * tick - safetyTicks * tick; }

        static int Real(KeystoneAutoSeat s) { try { return s.Link.Broker.Qty; } catch { return 0; } }
        static bool Conn(KeystoneAutoSeat s) { try { return s.Link.Broker.Connected; } catch { return false; } }
        static double Tick0(KeystoneAutoSeat s) { try { return s.Link.Broker.Tick > 0 ? s.Link.Broker.Tick : 0.25; } catch { return 0.25; } }
        void Log(DateTime now, KeystoneAutoSeat s, string ev, string detail, KeystoneAutoTicket t = null)
        {
            var r = new KeystoneAutoRow { Time = now, Event = ev, Detail = detail ?? "" };
            if (s != null) { r.Account = s.Account; r.Firm = s.Firm; r.Stage = s.Stage; r.Plan = s.Plan != null ? s.Plan.Name : ""; r.Mode = t != null ? (t.Auto ? "AUTO" : "GUIDED") : s.Auto ? "AUTO" : "GUIDED"; try { r.Link = s.Link != null ? s.Link.State : ""; } catch { } }
            if (t != null) { r.Side = t.Side; r.Qty = t.Qty; r.Ref = t.RefPrice; r.TpUsd = t.TpUsd; r.SlUsd = t.StopUsd; r.Tp = t.ModelTp; r.Sl = t.ModelStop; }
            Journal.Add(r); NewRows.Add(r); if (Journal.Count > 2000) Journal.RemoveAt(0);
        }

        // ▶ START AUTOPILOT: every seat's link must be ARMED (seats that are not stay out and never send); any AUTO seat needs START typed
        public bool AnyAuto { get { return Seats.Any(s => s.Auto && !s.Out); } }
        public string Start(string typed, DateTime now)
        {
            if (Running) return "already running";
            if (Seats.Count == 0) return "no account in the autopilot (✓ CONFIRM accounts in 🧪 EVAL LAB ▸ ● LIVE first)";
            bool anyAuto = Seats.Any(s => s.Auto && s.Link != null && s.Link.Armed && !s.Blown);
            if (anyAuto && (typed ?? "").Trim() != StartWord) return "AUTO needs the word START typed — nothing started";
            int armed = 0; var mates = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            foreach (var s in Seats)
            {
                s.Out = false; s.OutWhy = ""; s.OverOwner = false; if (s.Blown) { s.Out = true; s.OutWhy = "💀 BLOWN"; continue; }
                if (s.Link != null && s.Link.ExternalLocked) { s.Out = true; s.NtLocked = true; s.OutWhy = s.Link.ExternalLockLabel; s.State = s.OutWhy + " • never sends"; Log(now, s, "LOCKED", "locked by NinjaTrader • " + s.OutWhy + " • no ticket"); continue; }
                if (s.Link == null || s.Mirror == null || !s.Link.Armed) { s.Out = true; s.OutWhy = "NOT ARMED"; s.State = "NOT ARMED • never sends"; continue; }
                if (s.Link.Locked) { s.Out = true; s.OutWhy = "LOCKED FOR TODAY"; s.State = "LOCKED FOR TODAY • never sends today"; continue; }
                string key = s.Owner + "|" + s.Firm.ToUpperInvariant() + "|" + (s.Funded ? "FUNDED" : "EVAL"); int n; mates.TryGetValue(key, out n); mates[key] = ++n;
                int lim = KeystoneOwners.LimitOf(s.Firm, s.Funded ? "FUNDED" : "EVAL");
                if (n > lim) { s.OverOwner = true; s.Out = true; s.OutWhy = "👥 over " + s.Owner + "'s limit of " + lim + " " + KeystonePipeline.Nice(s.Firm) + " " + (s.Funded ? "funded" : "eval") + " accounts"; s.State = s.OutWhy; continue; }
                s.Link.Automated = s.Auto; armed++;
            }
            if (armed == 0) return "no armed account — ARM the accounts first";
            // the entry time of each account: the group's times spread over its accounts of a firm (the eval default has one: all at 2:00)
            foreach (var g in Seats.GroupBy(s => s.Group + "|" + s.Firm.ToUpperInvariant() + "|" + s.Stage))
            {
                int i = 0; foreach (var s in g) { var ts = s.Plan != null && s.Plan.Times != null && s.Plan.Times.Length > 0 ? s.Plan.Times : new[] { 200 }; s.SlotTime = ts[i % ts.Length]; i++; }
            }
            Running = true; StopWhy = ""; Status = "● RUNNING • " + armed + " account" + (armed == 1 ? "" : "s") + (AnyAuto ? " • AUTO + GUIDED" : " • GUIDED");
            Log(now, null, "START", Status + (AnyAuto ? " (START typed)" : ""));
            return "";
        }
        // DISARM / ⛔ CLOSE ALL / LOCK FOR TODAY / the window closed: nothing more is sent — the links are disarmed, positions stay with their broker brackets
        public void Stop(string why, DateTime now)
        {
            if (!Running) return; Running = false; StopWhy = why ?? "stopped"; Status = "■ STOPPED • " + StopWhy + " • positions stay at the broker with their stop / target";
            foreach (var s in Seats) { if (s.Ticket != null && s.Placed == null) s.Ticket = null; if (s.Link != null) s.Link.Disarm("AUTOPILOT STOPPED: " + StopWhy, now, false); }
            Log(now, null, "STOP", Status);
        }
        public KeystoneAutoSeat Find(string account) { return Seats.FirstOrDefault(s => string.Equals(s.Account, account, StringComparison.OrdinalIgnoreCase)); }
        // the GUIDED tickets flashing now
        public List<KeystoneAutoSeat> Flashing() { return Seats.Where(s => s.Ticket != null && s.Placed == null && s.State.StartsWith("▶")).ToList(); }

        // why this seat may not enter now ("" = it may)
        string Blocked(KeystoneAutoSeat s)
        {
            if (!Running) return "autopilot not running";
            if (s.Link != null && s.Link.ExternalLocked) return "locked by NinjaTrader • " + s.Link.ExternalLockLabel;   // 🔒 BUILD 11i
            if (s.Out) return s.OutWhy; if (s.Blown) return "💀 blown"; if (s.Link == null || !s.Link.Armed) return "NOT ARMED"; if (s.Link.Locked) return "LOCKED FOR TODAY";
            if (!Conn(s)) return "NOT CONNECTED"; if (Real(s) != 0) return "holds a position";
            double pnl = 0; try { pnl = s.Link.Broker.DayPnl; } catch { }
            if (s.Link.DayLossLimit > 0 && pnl <= -Math.Abs(s.Link.DayLossLimit) + 1e-9) return "DAY LOSS LIMIT " + Usd(s.Link.DayLossLimit) + " reached";
            if (s.Link.DayProfitCap > 0 && pnl >= s.Link.DayProfitCap - 1e-9) return "DAY PROFIT CAP reached";
            return "";
        }
        // the firm's side now: a position the firm already holds wins (never both sides inside a firm), else the coin of the firm / slot
        public int SideFor(KeystoneAutoSeat s, DateTime day)
        {
            foreach (var o in Seats) { if (o == s || !string.Equals(o.Firm, s.Firm, StringComparison.OrdinalIgnoreCase)) continue; int q = Real(o); if (q != 0) return Math.Sign(q); if (o.Placed != null && o.Mirror != null && o.Mirror.Position != 0) return Math.Sign(o.Mirror.Position); }
            string r = s.Plan != null ? s.Plan.Side : "FIRM"; int idx = Seats.IndexOf(s) + 1;
            return KeystoneLabFlow.PlanSide(r == "FIRM" || r == "EACH" || r == "ALL" || r == "BUY" || r == "SELL" ? r : "FIRM", day, (s.Firm ?? "").ToUpperInvariant(), idx, s.SlotTime, Seed);
        }
        // the ticket: size (never over the link's MAX), TP after costs, the stop (the plan's, never past the floor or the day loss room)
        public KeystoneAutoTicket MakeTicket(KeystoneAutoSeat s, DateTime now, DateTime day, double price, out string why)
        {
            why = ""; var p = s.Plan ?? (s.Funded ? KeystoneAutoPlan.FundedDefault(s.Firm == "TPT") : KeystoneAutoPlan.EvalDefault());
            bool tiny = !s.Funded && s.Start > 0 && s.Balance - s.Start >= s.Target - 0.5 && s.Target > 0 && s.DaysTraded < s.MinDays;
            int planQ = tiny ? 1 : p.Qty; double tpUsd = tiny ? 50 : p.TpUsd, slUsd = tiny ? 50 : p.StopUsd;
            int q = Math.Max(1, Math.Min(planQ, Math.Max(1, s.Link.MaxContracts))); double tick = Tick0(s);
            double floor = FloorOf(s.Start, s.Dd, s.Funded, s.Firm, s.Days, day), room = s.Balance - floor;
            double roomPts = s.Dd > 0 ? StopPoints(room, q, tick, 2) : double.MaxValue;   // to the floor, costs + 2 ticks of safety off
            double pnl = 0; try { pnl = s.Link.Broker.DayPnl; } catch { }
            double dayRoomPts = s.Link.DayLossLimit > 0 ? StopPoints(Math.Abs(s.Link.DayLossLimit) + pnl, q, tick, 1) : double.MaxValue;
            double stopPts = slUsd > 0 ? StopPoints(slUsd, q, tick, 0) : roomPts; stopPts = Math.Min(stopPts, Math.Min(roomPts, dayRoomPts));
            if (double.IsNaN(stopPts) || stopPts == double.MaxValue) { why = "no floor known for this account (its drawdown) — no stop can be set"; return null; }
            if (stopPts < 4 * tick) { why = "no room above the floor / day loss limit for a stop (" + stopPts.ToString("0.00", CultureInfo.InvariantCulture) + " pts)"; return null; }
            var t = new KeystoneAutoTicket { At = EntryAt(day, s.SlotTime), Qty = q, Slot = s.SlotTime, TpPts = TpPoints(tpUsd, q, tick), StopPts = stopPts, TpUsd = tpUsd, RefPrice = price, Tiny = tiny };
            t.StopUsd = Math.Round(stopPts * Pv * q + Cost * q); t.Deadline = t.At.AddMinutes(LateMinutes); t.Side = SideFor(s, day); t.Auto = !tiny && s.Auto;
            if (t.Side == 0) { why = "no side"; return null; }
            t.Reason = KeystonePipeline.Nice(s.Firm) + " · " + (s.Funded ? "funded" : "eval") + " · " + (tiny ? "✅ target made, day " + (s.DaysTraded + 1) + "/" + s.MinDays + ": the tiny trade (MNQ 1, TP +$50)" : p.Name) + " · side coin " + KeystonePipeline.Nice(s.Firm) + " @ " + (s.SlotTime / 100) + ":" + (s.SlotTime % 100).ToString("00") + " = " + (t.Side > 0 ? "BUY" : "SELL") + (planQ > q ? " · ⚠ capped at the link's MAX " + q + " (plan MNQ " + planQ + ")" : "");
            return t;
        }
        // the ticket → the mirror's intent; the account's armed link sends the market entry, then the STOP + TARGET at its fill (one cancels the other)
        void Place(KeystoneAutoSeat s, DateTime now, double price)
        {
            var t = s.Ticket; if (t == null) return; var m = s.Mirror; m.Price = price > 0 ? price : m.Price; m.Time = now; m.Orders.Clear();
            m.StopPts = t.StopPts; m.TargetPts = t.TpPts; m.Adopt(t.Side * t.Qty, price > 0 ? price : t.RefPrice, now);
            s.Placed = t; s.SentAt = now; s.DoneToday = true; s.BracketSeen = false; s.NoFillLogged = false; s.FillPrice = 0; s.State = "ORDER SENT • " + t.Words();
            Log(now, s, "ORDER", "market entry through the armed link; the STOP + TARGET follow at the fill" + (t.Auto ? "" : " (pressed)"), t);
        }
        // GUIDED: ONE press = the full bracket through the armed link
        public string Press(string account, DateTime now, double price)
        {
            var s = Find(account); if (s == null) return "unknown account"; var t = s.Ticket;
            if (t == null || s.Placed != null) return "no ticket for " + s.Display + " now";
            if (now > t.Deadline) return "missed (more than " + LateMinutes + " minutes after " + t.At.ToString("HH:mm", CultureInfo.InvariantCulture) + ") — no late entry";
            string b = Blocked(s); if (b != "") { Log(now, s, "BLOCKED", b, t); return b; }
            Place(s, now, price); return "";
        }
        public string Skip(string account, DateTime now)
        {
            var s = Find(account); if (s == null || s.Ticket == null || s.Placed != null) return "no ticket";
            Log(now, s, "SKIP", "you let it go", s.Ticket); s.Ticket = null; s.DoneToday = true; s.State = "SKIPPED today"; return "";
        }

        public void Tick(DateTime now, double price)
        {
            var day = DayOf(now); bool weekend = day.DayOfWeek == DayOfWeek.Saturday || day.DayOfWeek == DayOfWeek.Sunday;
            bool flatTime = now.TimeOfDay >= FlattenAt && now.Hour < 18;
            foreach (var s in Seats)
            {
                if (s.Day != day) { s.Day = day; s.DoneToday = false; if (s.Link == null || Real(s) == 0) { s.Ticket = null; s.Placed = null; } s.Flattened = false; if (!s.Out && !s.Blown && !s.TargetDone) s.State = "WAITING"; }
                if (s.Mirror != null) { if (price > 0) s.Mirror.Price = price; s.Mirror.Time = now; }
                s.Payout = PayoutNote(s);
            }
            if (Running)
            {
                // DISARM / a reject / the runaway guard on a seat's link: that account is out; LOCK FOR TODAY stops the whole autopilot
                var locked = Seats.FirstOrDefault(s => !s.Out && s.Link != null && s.Link.Locked && !s.Link.ExternalLocked);   /* a NinjaTrader lockout takes only that account out (below) */
                if (locked != null) Stop("LOCK FOR TODAY on " + locked.Display, now);
            }
            foreach (var s in Seats)
            {
                if (!Running || s.Link == null || s.Mirror == null) continue;
                // 🔒 LOCKED BY NINJATRADER (BUILD 11i): no ticket (journalled once); a position still closes at 16:54 (closing is allowed); the end is
                // journalled but the account is never re-armed by itself (its link was disarmed — ARM + START again)
                if (s.Link.ExternalLocked)
                {
                    string lab = s.Link.ExternalLockLabel;
                    if (!s.NtLocked) { s.NtLocked = true; Log(now, s, "LOCKED", "locked by NinjaTrader • " + lab + " • no ticket", s.Placed ?? s.Ticket); if (s.Placed == null) s.Ticket = null; }
                    if (!s.Out) { s.Out = true; s.OutWhy = lab; }
                    if (flatTime && Real(s) != 0 && !s.Flattened) { s.Flattened = true; s.Mirror.Orders.Clear(); s.Mirror.Adopt(0, 0, now); Log(now, s, "FLATTEN", "16:54 NY: closing the position (locked by NinjaTrader: closing is allowed)", s.Placed); }
                    s.State = lab + " • the autopilot gives it no ticket"; continue;
                }
                if (s.NtLocked) { s.NtLocked = false; Log(now, s, "UNLOCKED", "the NinjaTrader lock ended • NOT re-armed: ARM + ▶ START again to use it"); }
                if (!s.Out && !s.Link.Armed) { s.Out = true; s.OutWhy = "DISARMED • " + s.Link.State; s.State = s.OutWhy + " • the autopilot sends nothing more here"; Log(now, s, "DISARMED", s.Link.State, s.Placed ?? s.Ticket); s.Ticket = s.Placed != null ? s.Ticket : null; }
                if (s.Out) continue;
                // 💀 blown: out of the autopilot for good
                double floor = FloorOf(s.Start, s.Dd, s.Funded, s.Firm, s.Days, day);
                if (!s.Blown && s.Dd > 0 && s.Balance > 0 && s.Balance <= floor + 0.5 && Real(s) == 0) { s.Blown = true; s.Out = true; s.OutWhy = "💀 BLOWN"; s.State = "💀 BLOWN (balance " + Usd(s.Balance) + " ≤ floor " + Usd(floor) + ") • removed from the autopilot"; Log(now, s, "BLOWN", s.State); continue; }
                // ✅ eval target reached (and the days): stop trading it
                if (!s.Funded && s.Target > 0 && s.Start > 0 && s.Balance - s.Start >= s.Target - 0.5 && s.DaysTraded >= s.MinDays && s.Placed == null && Real(s) == 0)
                { if (!s.TargetDone) { s.TargetDone = true; Log(now, s, "TARGET", "✅ target reached: wait for the firm"); } s.State = "✅ target reached: wait for the firm"; continue; }
                // 16:54 NY: close every open position (through the link), once
                if (flatTime && Real(s) != 0 && !s.Flattened) { s.Flattened = true; s.Mirror.Orders.Clear(); s.Mirror.Adopt(0, 0, now); s.State = "16:54 FLATTEN • closing"; Log(now, s, "FLATTEN", "16:54 NY: closing the position", s.Placed); continue; }
                if (s.DoneToday || weekend) { if (weekend && s.Placed == null) s.State = "weekend • no session"; continue; }
                var at = EntryAt(day, s.SlotTime); var dl = at.AddMinutes(LateMinutes);
                if (s.Ticket == null)
                {
                    if (now < at) { s.State = "WAITING • " + at.ToString("HH:mm", CultureInfo.InvariantCulture) + " NY (" + (s.Auto ? "AUTO" : "GUIDED") + ")"; continue; }
                    if (now > dl || flatTime) { s.DoneToday = true; s.State = "MISSED " + at.ToString("HH:mm", CultureInfo.InvariantCulture) + " • no late entry"; Log(now, s, "MISSED", "the entry minute " + at.ToString("HH:mm", CultureInfo.InvariantCulture) + " passed (more than " + LateMinutes + " min) — no late entry"); continue; }
                    string b = Blocked(s); if (b != "") { s.DoneToday = true; s.State = "NO ENTRY TODAY • " + b; Log(now, s, "BLOCKED", b); continue; }
                    string why; var t = MakeTicket(s, now, day, price, out why); if (t == null) { s.DoneToday = true; s.State = "NO ENTRY TODAY • " + why; Log(now, s, "BLOCKED", why); continue; }
                    s.Ticket = t; Log(now, s, "TICKET", t.Reason, t);
                    if (t.Auto) Place(s, now, price);
                    else s.State = "▶ PRESS " + (t.Side > 0 ? "BUY" : "SELL") + " • " + t.Words() + " • until " + t.Deadline.ToString("HH:mm", CultureInfo.InvariantCulture);
                }
                else if (s.Placed == null && now > s.Ticket.Deadline)
                { Log(now, s, "MISSED", "not pressed within " + LateMinutes + " minutes — no late entry", s.Ticket); s.Ticket = null; s.DoneToday = true; s.State = "MISSED today (not pressed)"; }
            }
            // every link: the intent → real orders (only while armed), then what came back
            foreach (var s in Seats)
            {
                if (s.Link == null || s.Mirror == null) continue;
                if (Running || s.Placed != null) s.Link.Tick(s.Mirror, now);
                var t = s.Placed; if (t == null) continue; int real = Real(s);
                if (s.FillPrice == 0 && real != 0)
                {
                    double avg = 0; try { avg = s.Link.Broker.AvgPrice; } catch { } s.FillPrice = avg; int d = Math.Sign(real);
                    Log(now, s, "FILL", "model entry ≈ " + t.RefPrice.ToString("0.00", CultureInfo.InvariantCulture) + " (TP " + t.ModelTp.ToString("0.00", CultureInfo.InvariantCulture) + ") · filled at " + avg.ToString("0.00", CultureInfo.InvariantCulture) + " (TP " + (avg + d * t.TpPts).ToString("0.00", CultureInfo.InvariantCulture) + ", SL " + (avg - d * t.StopPts).ToString("0.00", CultureInfo.InvariantCulture) + ")", t);
                    var last = Journal[Journal.Count - 1]; last.Fill = avg; last.Tp = avg + d * t.TpPts; last.Sl = avg - d * t.StopPts;
                    s.State = "IN THE TRADE • " + (d > 0 ? "LONG " : "SHORT ") + Math.Abs(real) + " @ " + avg.ToString("0.00", CultureInfo.InvariantCulture);
                }
                if (s.FillPrice != 0 && real != 0 && !s.BracketSeen)
                {
                    var w = new List<KeystoneBrokerOrder>(); try { w = s.Link.Broker.Working(); } catch { }
                    var st = w.FirstOrDefault(o => !o.Done && o.Kind == "STOP" && o.Side == -Math.Sign(real)); var tg = w.FirstOrDefault(o => !o.Done && o.Kind == "LIMIT" && o.Side == -Math.Sign(real));
                    if (st != null && tg != null) { s.BracketSeen = true; Log(now, s, "BRACKET", "at the broker: STOP " + st.Price.ToString("0.00", CultureInfo.InvariantCulture) + " · TARGET " + tg.Price.ToString("0.00", CultureInfo.InvariantCulture) + " (one cancels the other)", t); }
                }
                if (s.FillPrice != 0 && real == 0)
                {
                    var f = s.Link.NewFills.LastOrDefault(); double net = f != null ? f.Net : 0, ex = f != null ? f.Exit : 0;
                    Log(now, s, "EXIT", "model expected TP at " + t.ModelTp.ToString("0.00", CultureInfo.InvariantCulture) + " · filled at " + s.FillPrice.ToString("0.00", CultureInfo.InvariantCulture) + " · out at " + ex.ToString("0.00", CultureInfo.InvariantCulture) + " · " + (net >= 0 ? "+" : "−") + Usd(net), t);
                    var last = Journal[Journal.Count - 1]; last.Fill = s.FillPrice; last.Exit = ex; last.Net = net;
                    s.Placed = null; s.Ticket = null; s.DaysTraded++; s.State = "DONE TODAY • " + (net >= 0 ? "+" : "−") + Usd(net);
                    s.Mirror.StopPts = 0; s.Mirror.TargetPts = 0;
                }
                else if (s.FillPrice == 0 && real == 0 && !s.NoFillLogged && (now - s.SentAt).TotalSeconds > FillWaitSeconds)
                {   // never re-sent: the entry stays the day's one; a late fill still gets its STOP + TARGET (the mirror keeps them), a reject disarms the link
                    s.NoFillLogged = true; Log(now, s, "NO FILL", "no fill " + FillWaitSeconds + " s after the order — nothing re-sent; a late fill still gets its bracket", t);
                    if (!s.Out) s.State = "ORDER SENT • no fill yet (nothing re-sent)";
                }
            }
            if (Running) Status = "● RUNNING • " + Seats.Count(s => !s.Out) + " in · " + Seats.Count(s => s.Placed != null) + " in a trade · " + Flashing().Count + " to press" + (AnyAuto ? " • AUTO + GUIDED" : " • GUIDED");
        }
    }

    // ---- COPIER: the chart's account (the leader) copied to follower accounts ------------------------------------------------
    // Each follower has its own account link (its own limits, arm, lock) and a mirror trader whose "intent" is the leader's REAL
    // position × the follower's multiplier (capped at its max) with the leader's stop / target distances. Followers enter at
    // market when the leader's position appears, follow its stop / target moves, and close when the leader is flat. If a
    // follower's own stop / target closes it while the leader is still in, it sits that trade out (never re-enters it).
    public sealed class KeystoneCopyFollower
    {
        public string Account = ""; public double Multiplier = 1; public int MaxQty = 2; public bool Paused;
        public KeystoneAccountLink Link; public KeystoneReplayTrader Mirror; public string Status = "";
        public string DoneTrade = "", Copying = ""; public int LastReal;
        public double TargetRoom, TargetCapPts; public int Extra; public bool AutoOwn;   /* AutoOwn: 🎯 AUTO TAKE PROFIT on → this account's OWN target (its room), not the leader's */   // Extra: ± contracts on THIS account in the current trade (+1 / −1 on its card), reset when the trade ends   // 🎯 TargetRoom: $ this account may still make today (its consistency room, set while flat; 0 = no cap) → TargetCapPts: its own take profit (pts) for its size
    }
    // COPY GROUPS (LIVE TRADING ▸ ⇉ COPIER): named groups of your prop accounts — one LEADER (the chart trades it) + its FOLLOWERS.
    // An account belongs to ONE group at most; Place refuses a second one with the reason.
    public sealed class KeystoneCopyGroup
    {
        public string Name = "", Color = "#4FC3F7", Leader = ""; public bool Custom; public List<KeystoneCopyFollower> Followers = new List<KeystoneCopyFollower>();
        public bool Confirmed, Separate;   // Separate: ✋ the chart may trade ONE account of the group alone (set in the COPIER)   // ✓ CONFIRM GROUP pressed (its accounts + the one on the chart); any change of the accounts or the chart account clears it — the switch needs it
        public IEnumerable<string> Members { get { if (Leader != "") yield return Leader; foreach (var f in Followers) yield return f.Account; } }
    }
    // a copy group traded from the ⇉ COPIER tab while the chart trades another group: one virtual leader per instrument — BUY / SELL /
    // CLOSE set its position (with a stop / target in points; the price comes from the chart's live feed) and every account of the group
    // copies it exactly like a follower (real orders only through each account's armed link)
    public sealed class KeystoneGroupDesk
    {
        public string Group = "", Last = "";
        public readonly Dictionary<string, KeystoneReplayTrader> Leaders = new Dictionary<string, KeystoneReplayTrader>(StringComparer.OrdinalIgnoreCase);
        public readonly List<Tuple<string, KeystoneCopyFollower>> Members = new List<Tuple<string, KeystoneCopyFollower>>();   // (instrument, account)
        public KeystoneReplayTrader Leader(string sym, DateTime now)
        {
            KeystoneReplayTrader l; if (!Leaders.TryGetValue(sym, out l)) { l = KeystoneReplayTrader.LiveStart(new List<KeystoneArcBar>(), sym, now); l.Slave = true; Leaders[sym] = l; }
            return l;
        }
        public void Enter(string sym, int dir, int qty, double price, double stopPts, double targetPts, DateTime now)
        {
            if (dir == 0 || qty <= 0 || price <= 0) return; var l = Leader(sym, now); l.Price = price; l.Time = now;
            // in a trade: the same side ADDS (average price weighted), the other side REDUCES (and reverses past flat) — like the chart
            int cur = l.Position, nw = cur + dir * qty; double avg;
            if (nw == 0) avg = 0; else if (cur == 0 || Math.Sign(nw) != Math.Sign(cur)) avg = price; else if (Math.Abs(nw) > Math.Abs(cur)) avg = (cur * l.AvgPrice + dir * qty * price) / nw; else avg = l.AvgPrice;
            if (cur != 0 && nw != 0 && Math.Sign(nw) != Math.Sign(cur)) l.Adopt(0, 0, now);   // reversed: a new trade
            l.Adopt(nw, avg, now); l.StopPts = Math.Max(0, stopPts); l.TargetPts = Math.Max(0, targetPts);
            Last = (dir > 0 ? "BUY " : "SELL ") + qty + " " + sym + " @ " + price.ToString("0.##", CultureInfo.InvariantCulture);
        }
        public void Close(string sym, DateTime now) { KeystoneReplayTrader l; if (Leaders.TryGetValue(sym, out l) && l.Position != 0) { l.Adopt(0, 0, now); Last = "CLOSED " + sym; } }
        public void CloseAll(DateTime now) { foreach (var s in Leaders.Keys.ToList()) Close(s, now); }
        public int Position(string sym) { KeystoneReplayTrader l; return Leaders.TryGetValue(sym, out l) ? l.Position : 0; }
        // 🔁 switched ON while its accounts are still IN A TRADE: the group's position = its main account's real one, every account keeps
        // exactly its own size (Extra), a flat account sits this trade out, one on the other side is paused — NOTHING is sent
        public List<string> TakeOver(string mainAccount, Dictionary<string, double> priceNow, DateTime now)
        {
            var adopted = new List<string>();
            Func<KeystoneCopyFollower, int> realQ = f => { try { return f.Link.Broker.Qty; } catch { return 0; } };
            Func<KeystoneCopyFollower, double> realAvg = f => { try { return f.Link.Broker.AvgPrice; } catch { return 0; } };
            foreach (var sym in Members.Select(m => m.Item1).Distinct(StringComparer.OrdinalIgnoreCase).ToList())
            {
                var ms = Members.Where(m => string.Equals(m.Item1, sym, StringComparison.OrdinalIgnoreCase)).ToList();
                var main = ms.FirstOrDefault(m => string.Equals(m.Item2.Account, mainAccount, StringComparison.OrdinalIgnoreCase) && realQ(m.Item2) != 0) ?? ms.FirstOrDefault(m => realQ(m.Item2) != 0); if (main == null) continue;
                int lq = realQ(main.Item2); double la = realAvg(main.Item2); if (la <= 0 || Position(sym) != 0) continue;
                var l = Leader(sym, now); double px; if (priceNow != null && priceNow.TryGetValue(sym, out px) && px > 0) l.Price = px;
                l.Adopt(lq, la, now); string tid = KeystoneCopier.TradeId(l);
                foreach (var m in ms)
                {
                    var f = m.Item2; int rq = realQ(f);
                    if (rq == 0) { f.DoneTrade = tid; continue; }
                    f.Mirror.Adopt(rq, realAvg(f) > 0 ? realAvg(f) : la, now);
                    if (Math.Sign(rq) != Math.Sign(lq)) { f.Paused = true; continue; }
                    f.Copying = tid; f.Extra = Math.Abs(rq) - Math.Abs(KeystoneCopier.Desired(lq, f.Multiplier, f.MaxQty));
                }
                adopted.Add(sym + " " + (lq > 0 ? "LONG " : "SHORT ") + Math.Abs(lq) + " @ " + la.ToString("0.00", CultureInfo.InvariantCulture));
            }
            return adopted;
        }
        // the instrument's price now: the leader's stop / target are watched here, then every account follows
        public void Tick(string sym, double price, DateTime now)
        {
            KeystoneReplayTrader l; if (!Leaders.TryGetValue(sym, out l)) return; if (price > 0) l.Price = price; l.Time = now;
            if (l.Position != 0 && price > 0)
            {
                double move = (price - l.AvgPrice) * Math.Sign(l.Position);
                if (l.StopPts > 0 && move <= -l.StopPts) { l.Adopt(0, 0, now); Last = sym + " STOP hit"; }
                else if (l.TargetPts > 0 && move >= l.TargetPts) { l.Adopt(0, 0, now); Last = sym + " TARGET hit"; }
            }
            foreach (var m in Members.Where(x => string.Equals(x.Item1, sym, StringComparison.OrdinalIgnoreCase))) KeystoneCopier.Tick(l, m.Item2, now);
        }
    }
    public static class KeystoneCopyGroups
    {
        public static readonly string[] Colors = { "#4FC3F7", "#FFB74D", "#81C784", "#BA68C8", "#F06292", "#4DB6AC", "#FFD54F", "#9575CD" };
        public static KeystoneCopyGroup GroupOf(List<KeystoneCopyGroup> gs, string acc) { return gs.FirstOrDefault(g => g.Members.Contains(acc ?? "", StringComparer.OrdinalIgnoreCase)); }
        // put an account in a group (as the leader or a follower); null = done, else why not
        public static string Place(List<KeystoneCopyGroup> gs, string group, string acc, bool asLeader, int defMax = 2)
        {
            var g = gs.FirstOrDefault(x => string.Equals(x.Name, group, StringComparison.OrdinalIgnoreCase)); if (g == null) return "no group " + group;
            var other = GroupOf(gs, acc); if (other != null && other != g) return acc + " is already in " + other.Name + " — an account can be in one group only (take it out there first)";
            var old = g.Followers.FirstOrDefault(f => string.Equals(f.Account, acc, StringComparison.OrdinalIgnoreCase));
            if (asLeader)
            {
                if (string.Equals(g.Leader, acc, StringComparison.OrdinalIgnoreCase)) return null;
                g.Confirmed = false; if (old != null) g.Followers.Remove(old);
                if (g.Leader != "") g.Followers.Insert(0, new KeystoneCopyFollower { Account = g.Leader, Multiplier = 1, MaxQty = old != null ? old.MaxQty : defMax });   // the old leader becomes a follower
                g.Leader = acc; return null;
            }
            if (string.Equals(g.Leader, acc, StringComparison.OrdinalIgnoreCase)) { g.Leader = ""; if (g.Followers.Count > 0) { g.Leader = g.Followers[0].Account; g.Followers.RemoveAt(0); } }
            if (old == null && !string.Equals(g.Leader, acc, StringComparison.OrdinalIgnoreCase)) { g.Followers.Add(new KeystoneCopyFollower { Account = acc, Multiplier = 1, MaxQty = Math.Max(1, defMax) }); g.Confirmed = false; }
            return null;
        }
        public static void Remove(List<KeystoneCopyGroup> gs, string acc)
        {
            foreach (var g in gs) { if (g.Members.Contains(acc ?? "", StringComparer.OrdinalIgnoreCase)) g.Confirmed = false; g.Followers.RemoveAll(f => string.Equals(f.Account, acc, StringComparison.OrdinalIgnoreCase)); if (string.Equals(g.Leader, acc, StringComparison.OrdinalIgnoreCase)) g.Leader = ""; }
        }
        public static string NewName(List<KeystoneCopyGroup> gs) { for (int i = 1; ; i++) { string n = "GROUP " + i; if (!gs.Any(g => string.Equals(g.Name, n, StringComparison.OrdinalIgnoreCase))) return n; } }
        public static string Serialize(List<KeystoneCopyGroup> gs)
        {
            var ic = CultureInfo.InvariantCulture;
            return string.Join("\n", gs.Select(g => "GROUP|" + g.Name.Replace("|", "/") + "|" + g.Color + "|" + g.Leader + "|" + string.Join(";", g.Followers.Select(f => f.Account + ":" + f.Multiplier.ToString("0.##", ic) + ":" + f.MaxQty + ":" + (f.Paused ? 1 : 0))) + "|" + (g.Custom ? 1 : 0) + "|" + (g.Confirmed ? 1 : 0) + "|" + (g.Separate ? 1 : 0)));
        }
        public static List<KeystoneCopyGroup> Parse(string text)
        {
            var res = new List<KeystoneCopyGroup>(); var ic = CultureInfo.InvariantCulture;
            foreach (var l in (text ?? "").Split('\n'))
            {
                var a = l.Trim().Split('|'); if (a.Length < 5 || a[0] != "GROUP" || a[1] == "") continue;
                var g = new KeystoneCopyGroup { Name = a[1], Color = a[2].StartsWith("#") ? a[2] : "#4FC3F7", Leader = a[3], Custom = a.Length >= 6 && a[5] == "1", Confirmed = a.Length >= 7 && a[6] == "1", Separate = a.Length >= 8 && a[7] == "1" };
                foreach (var fs in a[4].Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries))
                {
                    var b = fs.Split(':'); double m; int mx; if (b.Length < 4 || b[0] == "" || GroupOf(res, b[0]) != null || g.Members.Contains(b[0])) continue;
                    g.Followers.Add(new KeystoneCopyFollower { Account = b[0], Multiplier = double.TryParse(b[1], NumberStyles.Float, ic, out m) && m > 0 ? m : 1, MaxQty = int.TryParse(b[2], out mx) && mx > 0 ? mx : 2, Paused = b[3] == "1" });
                }
                if (g.Leader != "" && GroupOf(res, g.Leader) != null) g.Leader = "";
                res.Add(g);
            }
            return res;
        }
    }
    public static class KeystoneCopier
    {
        // 🎯 each account its own take profit: the leader's target, capped at what THIS account may still make today for its size (costs in)
        public static double TargetFor(double leaderTp, KeystoneCopyFollower f, int qty, string symbol, double tick)
        {
            double cap = f != null && f.TargetRoom > 0 ? KeystoneConsistency.AutoTargetPts(f.TargetRoom, qty, KeystoneMoveStudy.PointValue(symbol), KeystoneMoveStudy.Cost(symbol), tick) : 0;
            if (f != null) f.TargetCapPts = cap;
            if (cap > 0 && f.AutoOwn) return cap;   // 🎯 AUTO: every account its own target, wherever the leader's is
            return cap > 0 ? (leaderTp > 0 ? Math.Min(leaderTp, cap) : cap) : leaderTp;
        }
        // the account's own ± contracts on top of the group's size, on the same side (never past its MAX; down to flat at most)
        public static int WithExtra(int want, int extra, int max) { if (want == 0 || extra == 0) return want; int q = Math.Max(0, Math.Min(Math.Max(1, max), Math.Abs(want) + extra)); return Math.Sign(want) * q; }
        public static string TradeId(KeystoneReplayTrader leader) { return leader == null || leader.Position == 0 ? "" : leader.PositionTime.Ticks + "|" + Math.Sign(leader.Position); }
        public static int Desired(int leaderQty, double mult, int max)
        {
            if (leaderQty == 0 || mult <= 0) return 0; int q = (int)Math.Round(Math.Abs(leaderQty) * mult, MidpointRounding.AwayFromZero);
            return Math.Sign(leaderQty) * Math.Max(1, Math.Min(Math.Max(1, max), q));
        }
        // sets the follower's intent from the leader, then lets its link do the rest (only places orders while the link is armed)
        public static void Tick(KeystoneReplayTrader leader, KeystoneCopyFollower f, DateTime now)
        {
            if (leader == null || f == null || f.Link == null || f.Mirror == null) return;
            var m = f.Mirror; m.Price = leader.Price; m.Time = leader.Time;
            string id = TradeId(leader); int real = 0; try { real = f.Link.Broker.Qty; } catch { }
            if (id == "") f.DoneTrade = "";
            if (f.Copying != "" && f.Copying == id && real == 0 && f.LastReal != 0 && leader.Position != 0) f.DoneTrade = id;   // its own stop / target closed it: sit out
            f.LastReal = real;
            if (!f.Paused && !f.Link.Locked)
            {
                if (id == "") f.Extra = 0;
                int want = id == "" || f.DoneTrade == id ? 0 : WithExtra(Desired(leader.Position, f.Multiplier, f.MaxQty), f.Extra, f.MaxQty);
                if (want != 0) f.Copying = id;
                if (m.Position != want) m.Adopt(want, leader.AvgPrice, now);
                if (want != 0) { m.StopPts = leader.StopPts; m.TargetPts = TargetFor(leader.TargetPts, f, Math.Abs(want), leader.Symbol, leader.Tick); }
            }
            f.Link.Tick(m, now);
            int target = !f.Paused && id != "" && f.DoneTrade != id ? WithExtra(Desired(leader.Position, f.Multiplier, f.MaxQty), f.Extra, f.MaxQty) : 0;
            f.Status = f.Link.Locked ? "LOCKED" : f.Paused ? "PAUSED" : !f.Link.Connected ? "NOT CONNECTED" : !f.Link.Armed ? "NOT ARMED (watching)" : f.DoneTrade != "" && f.DoneTrade == id ? "SAT OUT (its stop / target hit)" : f.Link.Broker.Qty == target ? (target == 0 ? "IN SYNC • flat" : "IN SYNC • " + (target > 0 ? "LONG " : "SHORT ") + Math.Abs(target)) : "SYNCING → " + target;
        }
        // saved: one line per leader account: leader|follower:mult:max:paused;...
        public static string Serialize(string leader, IEnumerable<KeystoneCopyFollower> fs) { return (leader ?? "").Replace("|", "/") + "|" + string.Join(";", fs.Select(f => f.Account.Replace(";", "/").Replace(":", "/") + ":" + f.Multiplier.ToString(CultureInfo.InvariantCulture) + ":" + f.MaxQty + ":" + (f.Paused ? "1" : "0"))); }
        public static Tuple<string, List<KeystoneCopyFollower>> Parse(string line)
        {
            var a = (line ?? "").Split('|'); if (a.Length < 2) return null; var list = new List<KeystoneCopyFollower>();
            foreach (var p in a[1].Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries))
            {
                var b = p.Split(':'); if (b.Length < 4) continue; double mu; int mx; double.TryParse(b[1], NumberStyles.Float, CultureInfo.InvariantCulture, out mu); int.TryParse(b[2], out mx);
                list.Add(new KeystoneCopyFollower { Account = b[0], Multiplier = mu > 0 ? mu : 1, MaxQty = mx > 0 ? mx : 1, Paused = b[3] == "1" });
            }
            return Tuple.Create(a[0], list);
        }
    }

    // ---- THE POOL: your own record of every account you trade — kept for good (also after you stop trading it) ---------------
    public sealed class KeystonePoolAccount
    {
        public string Account = "", Nick = "", Firm = "", Status = "EVAL", Notes = ""; public DateTime Started = DateTime.MinValue; public double Cost;
        public List<Tuple<DateTime, double>> Payouts = new List<Tuple<DateTime, double>>();
        public List<Tuple<DateTime, double, string>> Expenses = new List<Tuple<DateTime, double, string>>();   // dated costs after the purchase (monthly renewal, activation, reset, data fee …)
        public double PaidOut { get { return Payouts.Sum(p => p.Item2); } }
        public double Spent { get { return Cost + Expenses.Sum(e => e.Item2); } }
        public bool Archived { get { return Status == "BLOWN" || Status == "CLOSED"; } }
        public bool Funded { get { return Status == "FUNDED" || Status == "PAYOUT"; } }
        // seen live (NinjaTrader's balance with open P/L): highest / lowest, the deepest drop from a high, the day it was funded and
        // its highest equity since then (the funded INTRADAY trailing drawdown follows it)
        public double PeakBal, LowBal, MaxDd, FundedPeak; public DateTime FundedOn = DateTime.MinValue;
        // FUNDED drawdown (user's request: a funded account trails until +dd profit locks the floor at the start, or it blows):
        // INTRADAY = the floor follows the best equity (open P/L included) in real time; EOD = it moves only at the day's close
        public string FundedDd = "INTRADAY"; public bool AutoChecked;   // AutoChecked: the name test (TPT "PRO" = funded) ran once for this account
        // a Take Profit Trader PRO account (TAKEPROFITPRO…, PRO…) is the funded stage
        public static bool LooksFunded(string account, string firmCode)
        {   // careful: every TPT name has "PRO" inside TAKE-PRO-FIT — the funded ones are TAKEPROFITPRO…, PRO…, …-PRO…
            var u = (account ?? "").ToUpperInvariant(); if (!string.Equals(firmCode, "TPT", StringComparison.OrdinalIgnoreCase)) return false;
            return u.Contains("TAKEPROFITPRO") || u.StartsWith("PRO") || u.Contains("-PRO") || u.Contains("_PRO") || u.Contains(" PRO");
        }
        // the funded floor now: INTRADAY from the best equity since funded, EOD from the account watch's closes; both stop at the start
        public double FundedFloor(double balNow, double dd, double start, double eodFloor) { if (dd <= 0) return 0; if (FundedDd == "EOD" && !double.IsNaN(eodFloor) && eodFloor > 0) return Math.Min(eodFloor, start); return IntradayFloor(Math.Max(FundedPeak, balNow), dd, start); }
        public void Observe(double equity)
        {
            if (equity <= 0) return;
            if (PeakBal <= 0 || equity > PeakBal) PeakBal = equity; if (LowBal <= 0 || equity < LowBal) LowBal = equity; MaxDd = Math.Max(MaxDd, PeakBal - equity);
            if (Funded && equity > FundedPeak) FundedPeak = equity;
        }
        public void MarkFunded(DateTime day, double equity) { if (FundedOn == DateTime.MinValue) FundedOn = day.Date; if (equity > FundedPeak) FundedPeak = equity; }
        // funded INTRADAY trailing: the floor is dd below the highest equity since funded and stops trailing at the start balance
        public static double IntradayFloor(double peak, double dd, double start) { return peak <= 0 || dd <= 0 ? 0 : Math.Min(peak - dd, start); }
    }
    // ---- 📊 PROP TRACKER: one self-contained web page (saved on your PC, re-read by the browser every 10 s) with what you bought,
    // spent, earned and paid out — per account, per firm, per day and per month — from the POOL (purchases, dated expenses, payouts,
    // status), the real trades NinjaTrader reported (gross, commissions, net) and each account's daily balances.
    public sealed class KeystoneTrackerTrade { public string Account = ""; public DateTime Day; public double Gross, Fees, Net; public int Count = 1; }   // Count: trades in this row (a day row from NinjaTrader = that day's trades)
    // the copy groups for the tracker page (name, colour, ⭐ chart account, members, on / traded from the chart)
    public sealed class KeystoneTrackerGroup { public string Name = "", Color = "#58a6ff", Leader = ""; public List<string> Members = new List<string>(); public bool On, Chart; }
    // 📒 DAILY BOOK: every account's day as NinjaTrader reports it (gross realized, realized after commissions, trades), saved once per session
    // day — all accounts count (copier followers and groups traded from the COPIER too), not only the trades placed from the chart
    // 📊 ORDER FLOW — built from REAL trades (NinjaTrader ticks): each trade's aggressor (bought at the ask / sold at the bid; the tick
    // rule only when there is no quote), every candle's FOOTPRINT (volume at each price, buyers vs sellers), DELTA, CUMULATIVE DELTA, the
    // VOLUME PROFILE (POC, value area, high / low volume nodes), IMBALANCES (stacked), and three signals — STACKED imbalances, ABSORPTION,
    // DELTA DIVERGENCE — each with its HIT RATE measured on the loaded history (+target ticks before −stop ticks), never looking ahead.
    public struct KeystoneOfTick { public DateTime Time; public double Price; public long Size; public int Side; public bool Quoted; }   // Side +1 = buyer aggressor, −1 = seller; Quoted = classified by bid / ask
    public sealed class KeystoneOfRow { public long Buy, Sell; public long Total { get { return Buy + Sell; } } }
    public sealed class KeystoneOfImbalance { public double Price; public int Side; public double Ratio; }
    public sealed class KeystoneOfStack { public double Lo, Hi; public int Side, Count; }
    public sealed class KeystoneFootprint
    {
        public DateTime Start, End; public double Open = double.NaN, High = double.NaN, Low = double.NaN, Close = double.NaN; public long Buy, Sell, MaxDelta, MinDelta, Cvd; public int Trades;
        public SortedDictionary<double, KeystoneOfRow> Rows = new SortedDictionary<double, KeystoneOfRow>(); public double Poc = double.NaN;
        public List<KeystoneOfImbalance> Imb = new List<KeystoneOfImbalance>(); public List<KeystoneOfStack> Stacks = new List<KeystoneOfStack>();
        public long Delta { get { return Buy - Sell; } }
        public long Volume { get { return Buy + Sell; } }
        public bool Empty { get { return Trades == 0; } }
    }
    public sealed class KeystoneProfile { public SortedDictionary<double, KeystoneOfRow> Rows = new SortedDictionary<double, KeystoneOfRow>(); public double Poc = double.NaN, Vah = double.NaN, Val = double.NaN; public long Volume, Buy, Sell; public List<double> Hvn = new List<double>(), Lvn = new List<double>(); }
    public sealed class KeystoneOfSignal { public DateTime Time; public int Bar, Dir, Outcome, N, Wins; public string Kind = "", Why = ""; public double Price, Prob = double.NaN; }
    public sealed class KeystoneOfSettings
    {
        public int TicksPerRow = 1; public double ValueAreaPct = 70, ImbRatio = 3, AbsorbFrac = 0.35; public long ImbMinVol = 5; public int StackMin = 3;
        public int TargetTicks = 40, StopTicks = 40, HorizonBars = 30, DivLookback = 10, LowLookback = 5;
        public bool Stacked = true, Absorb = true, Diverge = true;
        // CONFIRMED setups: a stop run against the signal (the recent swing low / high taken and given back) within SweepRecent candles up to it
        // (NeedSweep), then a CLOSED candle within ConfirmBars that closes beyond the signal candle's extreme with the delta on its side
        public int ConfirmBars = 3, SweepLook = 10, SweepRecent = 5; public bool NeedSweep = true, Trend = true;
    }
    public static class KeystoneOrderFlow
    {
        // the aggressor of one trade: at / above the ask = a buyer lifted the offer; at / below the bid = a seller hit the bid; inside the
        // spread = the nearer side; no quote = the tick rule (up from the last trade = buy, down = sell, same price = same as before)
        public static int Classify(double price, double bid, double ask, double prevPrice, int prevSide)
        {
            if (bid > 0 && ask > 0 && ask >= bid) { if (price >= ask) return 1; if (price <= bid) return -1; double mid = (bid + ask) / 2; if (price > mid) return 1; if (price < mid) return -1; }
            if (prevPrice > 0) { if (price > prevPrice + 1e-9) return 1; if (price < prevPrice - 1e-9) return -1; }
            return prevSide != 0 ? prevSide : 1;
        }
        public static double RowStep(double tick, KeystoneOfSettings s) { return Math.Max(1e-9, tick) * Math.Max(1, s.TicksPerRow); }
        public static double Row(double price, double step) { return Math.Round(Math.Floor(price / step + 1e-7) * step, 6); }
        // the footprint of every window (start, end] (the candles), ticks sorted by time; cumulative delta carried across the windows
        public static List<KeystoneFootprint> Footprints(List<KeystoneOfTick> ticks, List<Tuple<DateTime, DateTime>> windows, double tick, KeystoneOfSettings s)
        {
            return Footprints(ticks, windows, tick, s, 0, 0, ticks == null ? 0 : ticks.Count);
        }
        // the first trade after time t (ticks sorted by time, only the first n looked at)
        public static int FirstAfter(List<KeystoneOfTick> ticks, DateTime t, int n)
        {
            int lo = 0, hi = Math.Min(n, ticks.Count);
            while (lo < hi) { int m = lo + (hi - lo) / 2; if (ticks[m].Time <= t) lo = m + 1; else hi = m; }
            return lo;
        }
        // LIVE FLOW: what everybody traded in the last `seconds` up to `now` → { bought at the ask, sold at the bid, trades }
        public static long[] Flow(List<KeystoneOfTick> ticks, int endN, DateTime now, double seconds)
        {
            var res = new long[3]; endN = Math.Min(endN, ticks.Count);
            for (int i = FirstAfter(ticks, now.AddSeconds(-seconds), endN); i < endN; i++)
            {
                var t = ticks[i]; if (t.Time > now) break;
                if (t.Side > 0) res[0] += t.Size; else res[1] += t.Size; res[2]++;
            }
            return res;
        }
        // the delta (bought − sold) of the last `count` slices of `bucketSec` seconds up to `now`, oldest first — the flow moving up / down
        public static long[] DeltaSlices(List<KeystoneOfTick> ticks, int endN, DateTime now, double bucketSec, int count)
        {
            var res = new long[count]; endN = Math.Min(endN, ticks.Count); DateTime from = now.AddSeconds(-bucketSec * count);
            for (int i = FirstAfter(ticks, from, endN); i < endN; i++)
            {
                var t = ticks[i]; if (t.Time > now) break;
                int b = (int)Math.Floor((t.Time - from).TotalSeconds / bucketSec); if (b >= count) b = count - 1; if (b < 0) continue;
                res[b] += t.Side > 0 ? t.Size : -t.Size;
            }
            return res;
        }
        // WHO IS IN CONTROL over the last `seconds`: the share bought at the ask AND where the price went (a 57 % buy share driving the price up IS
        // buyers in control; 60 % bought while the price falls = buyers absorbed). → side (+1 buyers, −1 sellers, 0 even), strength 0…1, the words.
        public static Tuple<int, double, string> Control(List<KeystoneOfTick> ticks, int endN, DateTime now, double seconds, double tick)
        {
            endN = Math.Min(endN, ticks.Count); int st = FirstAfter(ticks, now.AddSeconds(-seconds), endN); long b = 0, sl = 0; double first = 0, last = 0;
            for (int i = st; i < endN; i++) { var t = ticks[i]; if (t.Time > now) break; if (first == 0) first = t.Price; last = t.Price; if (t.Side > 0) b += t.Size; else sl += t.Size; }
            if (b + sl == 0) return Tuple.Create(0, 0.0, "quiet — nobody is trading");
            double ds = (double)(b - sl) / (b + sl), mv = (last - first) / Math.Max(1e-9, tick);
            double str = Math.Min(1, Math.Abs(ds) * 2.5 + Math.Abs(mv) / 24);
            string pct = (100.0 * b / (b + sl)).ToString("0", CultureInfo.InvariantCulture) + "% bought, price " + (mv >= 0 ? "+" : "") + mv.ToString("0", CultureInfo.InvariantCulture) + " ticks";
            if (ds >= 0.06 && mv >= 2 || mv >= 8 && ds >= -0.02) return Tuple.Create(1, str, "BUYERS IN CONTROL • " + pct);
            if (ds <= -0.06 && mv <= -2 || mv <= -8 && ds <= 0.02) return Tuple.Create(-1, str, "SELLERS IN CONTROL • " + pct);
            if (ds >= 0.12 && mv <= -2) return Tuple.Create(-1, str * 0.7, "BUYERS ABSORBED — they hit the asks but the price falls • " + pct);
            if (ds <= -0.12 && mv >= 2) return Tuple.Create(1, str * 0.7, "SELLERS ABSORBED — they hit the bids but the price rises • " + pct);
            return Tuple.Create(0, str * 0.5, "EVEN FIGHT • " + pct);
        }
        // the EDGE of a kind of setup on one side, from the setups that were FINISHED before `uptoBar` (no look-ahead): with a target of tgtTicks and a
        // stop of stpTicks within `hor` candles → wins, losses, expectancy (ticks per trade) and the median run in its favour before the stop (ticks)
        public static double[] Edge(List<KeystoneOfSignal> sigs, List<KeystoneFootprint> fps, double tick, int tgtTicks, int stpTicks, int hor, int dir, int uptoBar)
        {
            int w = 0, l = 0; var runs = new List<double>();
            foreach (var g in sigs)
            {
                if (g.Dir != dir || g.Bar >= uptoBar) continue;
                double tgt = g.Price + dir * tgtTicks * tick, stp = g.Price - dir * stpTicks * tick, best = 0; int res = 0, k = g.Bar + 1;
                for (; k < fps.Count && k <= g.Bar + hor && k < uptoBar; k++)
                {
                    var f = fps[k]; if (f.Empty) continue;
                    bool hs = dir > 0 ? f.Low <= stp : f.High >= stp, ht = dir > 0 ? f.High >= tgt : f.Low <= tgt;
                    if (!hs) best = Math.Max(best, dir > 0 ? f.High - g.Price : g.Price - f.Low);
                    if (hs) { res = -1; break; } if (ht) { res = 1; break; }
                }
                if (res == 0 && k <= g.Bar + hor) continue;   // not finished before uptoBar
                if (res > 0) w++; else if (res < 0) l++;
                runs.Add(best / tick);
            }
            runs.Sort(); double med = runs.Count == 0 ? double.NaN : runs[runs.Count / 2];
            double exp = w + l == 0 ? double.NaN : (w * (double)tgtTicks - l * (double)stpTicks) / (w + l);
            return new[] { w, l, exp, med };
        }
        // the footprints of windows[fromWin…] only (the closed candles before it are kept by the caller): cumulative delta goes on from
        // startCvd, only the first tickEnd trades count (the live feed may be adding more meanwhile)
        public static List<KeystoneFootprint> Footprints(List<KeystoneOfTick> ticks, List<Tuple<DateTime, DateTime>> windows, double tick, KeystoneOfSettings s, int fromWin, long startCvd, int tickEnd)
        {
            var res = new List<KeystoneFootprint>(); double step = RowStep(tick, s); long cvd = startCvd;
            ticks = ticks ?? new List<KeystoneOfTick>(); int n = Math.Min(tickEnd, ticks.Count);
            int j = fromWin < windows.Count ? FirstAfter(ticks, windows[fromWin].Item1, n) : n;
            for (int wi = fromWin; wi < windows.Count; wi++)
            {
                var wn = windows[wi]; var f = new KeystoneFootprint { Start = wn.Item1, End = wn.Item2 };
                while (j < n && ticks[j].Time <= wn.Item1) j++;
                long run = 0;
                while (j < n && ticks[j].Time <= wn.Item2)
                {
                    var t = ticks[j++]; if (t.Size <= 0 || t.Price <= 0) continue;
                    if (f.Trades == 0) { f.Open = f.High = f.Low = t.Price; }
                    f.High = Math.Max(f.High, t.Price); f.Low = Math.Min(f.Low, t.Price); f.Close = t.Price; f.Trades++;
                    double r = Row(t.Price, step); KeystoneOfRow row; if (!f.Rows.TryGetValue(r, out row)) f.Rows[r] = row = new KeystoneOfRow();
                    if (t.Side > 0) { row.Buy += t.Size; f.Buy += t.Size; run += t.Size; } else { row.Sell += t.Size; f.Sell += t.Size; run -= t.Size; }
                    f.MaxDelta = Math.Max(f.MaxDelta, run); f.MinDelta = Math.Min(f.MinDelta, run);
                }
                cvd += f.Delta; f.Cvd = cvd;
                if (f.Rows.Count > 0) f.Poc = f.Rows.OrderByDescending(kv => kv.Value.Total).ThenBy(kv => kv.Key).First().Key;
                Imbalances(f, step, s); res.Add(f);
            }
            return res;
        }
        // DIAGONAL imbalance: buyers at a price vs sellers one row lower (≥ ratio × and ≥ min volume) = buying imbalance; sellers at a price
        // vs buyers one row higher = selling imbalance. 3+ in a row = a STACK (a zone the aggressive side defended)
        public static void Imbalances(KeystoneFootprint f, double step, KeystoneOfSettings s)
        {
            f.Imb.Clear(); f.Stacks.Clear();
            foreach (var kv in f.Rows)
            {
                KeystoneOfRow below, above; f.Rows.TryGetValue(Math.Round(kv.Key - step, 6), out below); f.Rows.TryGetValue(Math.Round(kv.Key + step, 6), out above);
                long sb = below != null ? below.Sell : 0, ba = above != null ? above.Buy : 0;
                if (kv.Value.Buy >= s.ImbMinVol && kv.Value.Buy >= s.ImbRatio * Math.Max(1, sb)) f.Imb.Add(new KeystoneOfImbalance { Price = kv.Key, Side = 1, Ratio = kv.Value.Buy / (double)Math.Max(1, sb) });
                if (kv.Value.Sell >= s.ImbMinVol && kv.Value.Sell >= s.ImbRatio * Math.Max(1, ba)) f.Imb.Add(new KeystoneOfImbalance { Price = kv.Key, Side = -1, Ratio = kv.Value.Sell / (double)Math.Max(1, ba) });
            }
            foreach (int side in new[] { 1, -1 })
            {
                var ps = f.Imb.Where(x => x.Side == side).Select(x => x.Price).OrderBy(x => x).ToList(); int i = 0;
                while (i < ps.Count)
                {
                    int k = i; while (k + 1 < ps.Count && Math.Abs(ps[k + 1] - ps[k] - step) < step * 0.01) k++;
                    if (k - i + 1 >= s.StackMin) f.Stacks.Add(new KeystoneOfStack { Lo = ps[i], Hi = ps[k] + step, Side = side, Count = k - i + 1 });
                    i = k + 1;
                }
            }
        }
        // the VOLUME PROFILE of a set of candles: POC = the most traded price, VALUE AREA = the prices around it holding ValueAreaPct % of the
        // volume (grown one row at a time toward the bigger side), HVN / LVN = local peaks / valleys of the (3-row smoothed) profile
        public static KeystoneProfile Profile(IEnumerable<KeystoneFootprint> fps, double tick, KeystoneOfSettings s)
        {
            var p = new KeystoneProfile(); double step = RowStep(tick, s);
            foreach (var f in fps) foreach (var kv in f.Rows) { KeystoneOfRow r; if (!p.Rows.TryGetValue(kv.Key, out r)) p.Rows[kv.Key] = r = new KeystoneOfRow(); r.Buy += kv.Value.Buy; r.Sell += kv.Value.Sell; }
            if (p.Rows.Count == 0) return p;
            var keys = p.Rows.Keys.ToList(); var vol = keys.Select(k => p.Rows[k].Total).ToList(); p.Volume = vol.Sum(); p.Buy = p.Rows.Values.Sum(r => r.Buy); p.Sell = p.Rows.Values.Sum(r => r.Sell);
            int poc = 0; for (int i = 1; i < vol.Count; i++) if (vol[i] > vol[poc]) poc = i; p.Poc = keys[poc];
            long target = (long)Math.Ceiling(p.Volume * s.ValueAreaPct / 100.0), acc = vol[poc]; int lo = poc, hi = poc;
            while (acc < target && (lo > 0 || hi < vol.Count - 1))
            {
                long up = hi < vol.Count - 1 ? vol[hi + 1] : -1, dn = lo > 0 ? vol[lo - 1] : -1;
                if (up >= dn) { hi++; acc += vol[hi]; } else { lo--; acc += vol[lo]; }
            }
            p.Val = keys[lo]; p.Vah = keys[hi] + step;
            var sm = new double[vol.Count]; for (int i = 0; i < vol.Count; i++) { double a = 0; int n = 0; for (int k = Math.Max(0, i - 1); k <= Math.Min(vol.Count - 1, i + 1); k++) { a += vol[k]; n++; } sm[i] = a / n; }
            double avg = sm.Average();
            for (int i = 2; i < sm.Length - 2; i++)
            {
                if (sm[i] >= sm[i - 1] && sm[i] >= sm[i + 1] && sm[i] > sm[i - 2] && sm[i] > sm[i + 2] && sm[i] > avg * 1.3) p.Hvn.Add(keys[i]);
                if (sm[i] <= sm[i - 1] && sm[i] <= sm[i + 1] && sm[i] < sm[i - 2] && sm[i] < sm[i + 2] && sm[i] < avg * 0.6) p.Lvn.Add(keys[i]);
            }
            return p;
        }
        // the SIGNALS (at a candle's close):
        //  STACKED  — a stack of buying (selling) imbalances in the candle, delta with it, close in its upper (lower) half → with the buyers (sellers)
        //  ABSORB   — a new low (high) of the last LowLookback candles where ≥ AbsorbFrac of the candle's volume was SOLD (BOUGHT) in its two lowest
        //             (highest) rows, yet it closes in the upper (lower) half: the aggressive side was absorbed → the other way
        //  DIVERGE  — a new high (low) of the last DivLookback candles while the cumulative delta is NOT at a new high (low) and the candle's delta
        //             is against the move → a reversal
        public static List<KeystoneOfSignal> Signals(List<KeystoneFootprint> fps, double tick, KeystoneOfSettings s)
        {
            var res = new List<KeystoneOfSignal>(); double step = RowStep(tick, s);
            for (int i = 0; i < fps.Count; i++)
            {
                var f = fps[i]; if (f.Empty || f.High <= f.Low) continue; double mid = (f.High + f.Low) / 2; bool upHalf = f.Close >= mid, dnHalf = f.Close <= mid;
                if (s.Stacked)
                {
                    var bs = f.Stacks.Where(x => x.Side > 0).OrderByDescending(x => x.Count).FirstOrDefault(); var ss = f.Stacks.Where(x => x.Side < 0).OrderByDescending(x => x.Count).FirstOrDefault();
                    if (bs != null && f.Delta > 0 && upHalf && (ss == null || bs.Count > ss.Count)) res.Add(new KeystoneOfSignal { Time = f.End, Bar = i, Dir = 1, Kind = "STACKED", Price = f.Close, Why = bs.Count + " buying imbalances stacked " + bs.Lo.ToString("0.##", CultureInfo.InvariantCulture) + "–" + bs.Hi.ToString("0.##", CultureInfo.InvariantCulture) + " • delta +" + f.Delta });
                    else if (ss != null && f.Delta < 0 && dnHalf && (bs == null || ss.Count > bs.Count)) res.Add(new KeystoneOfSignal { Time = f.End, Bar = i, Dir = -1, Kind = "STACKED", Price = f.Close, Why = ss.Count + " selling imbalances stacked " + ss.Lo.ToString("0.##", CultureInfo.InvariantCulture) + "–" + ss.Hi.ToString("0.##", CultureInfo.InvariantCulture) + " • delta " + f.Delta });
                }
                if (s.Absorb && i >= s.LowLookback && f.Volume > 0)
                {
                    var prev = fps.GetRange(i - s.LowLookback, s.LowLookback).Where(x => !x.Empty).ToList();
                    if (prev.Count > 0)
                    {
                        var rows = f.Rows.ToList();
                        long soldLow = rows.Take(2).Sum(r => r.Value.Sell), boughtHigh = rows.Skip(Math.Max(0, rows.Count - 2)).Sum(r => r.Value.Buy);
                        if (f.Low < prev.Min(x => x.Low) && soldLow >= s.AbsorbFrac * f.Volume && upHalf) res.Add(new KeystoneOfSignal { Time = f.End, Bar = i, Dir = 1, Kind = "ABSORB", Price = f.Close, Why = "new low, " + (100.0 * soldLow / f.Volume).ToString("0", CultureInfo.InvariantCulture) + "% of the volume sold at the bottom, closed in the upper half — sellers absorbed" });
                        else if (f.High > prev.Max(x => x.High) && boughtHigh >= s.AbsorbFrac * f.Volume && dnHalf) res.Add(new KeystoneOfSignal { Time = f.End, Bar = i, Dir = -1, Kind = "ABSORB", Price = f.Close, Why = "new high, " + (100.0 * boughtHigh / f.Volume).ToString("0", CultureInfo.InvariantCulture) + "% of the volume bought at the top, closed in the lower half — buyers absorbed" });
                    }
                }
                if (s.Diverge && i >= s.DivLookback)
                {
                    var prev = fps.GetRange(i - s.DivLookback, s.DivLookback).Where(x => !x.Empty).ToList();
                    if (prev.Count > 0)
                    {
                        if (f.High > prev.Max(x => x.High) && f.Cvd < prev.Max(x => x.Cvd) && f.Delta < 0) res.Add(new KeystoneOfSignal { Time = f.End, Bar = i, Dir = -1, Kind = "DIVERGE", Price = f.Close, Why = "new high but the cumulative delta is lower (" + f.Cvd + " vs " + prev.Max(x => x.Cvd) + ") and this candle's delta is " + f.Delta });
                        else if (f.Low < prev.Min(x => x.Low) && f.Cvd > prev.Min(x => x.Cvd) && f.Delta > 0) res.Add(new KeystoneOfSignal { Time = f.End, Bar = i, Dir = 1, Kind = "DIVERGE", Price = f.Close, Why = "new low but the cumulative delta is higher (" + f.Cvd + " vs " + prev.Min(x => x.Cvd) + ") and this candle's delta is +" + f.Delta });
                    }
                }
            }
            return res;
        }
        // CONFIRMED: an aggressive burst alone is not a setup. A raw signal becomes CONFIRMED only after
        //  1. the MANIPULATION — within SweepRecent candles up to it, price ran the stops beyond the recent swing (the lowest low / highest high of
        //     the SweepLook candles before) and closed back inside (needed when NeedSweep), and
        //  2. the CONFIRMATION — a CLOSED candle within ConfirmBars after it closes beyond the signal candle's high (buy) / low (sell) with the delta
        //     on its side; a close beyond the other extreme first cancels it. The confirmed setup is placed on the confirming candle (never earlier).
        public static List<KeystoneOfSignal> Confirm(List<KeystoneOfSignal> raw, List<KeystoneFootprint> fps, double tick, KeystoneOfSettings s, bool lastIsForming)
        {
            var res = new List<KeystoneOfSignal>(); var used = new HashSet<int>(); int jMax = fps.Count - 1 - (lastIsForming ? 1 : 0);
            foreach (var g in raw.OrderBy(x => x.Bar))
            {
                int i = g.Bar; if (i < 0 || i >= fps.Count || fps[i].Empty) continue; var fi = fps[i];
                string sweep = null;
                for (int k = Math.Max(1, i - s.SweepRecent); k <= i && sweep == null; k++)
                {
                    var fk = fps[k]; if (fk.Empty) continue; double ext = g.Dir > 0 ? double.MaxValue : double.MinValue; int n = 0;
                    for (int q = Math.Max(0, k - s.SweepLook); q < k; q++) { var fq = fps[q]; if (fq.Empty) continue; n++; ext = g.Dir > 0 ? Math.Min(ext, fq.Low) : Math.Max(ext, fq.High); }
                    if (n < 3) continue;
                    bool took = g.Dir > 0 ? fk.Low < ext - 1e-9 : fk.High > ext + 1e-9; if (!took) continue;
                    bool back = false; for (int q = k; q <= i; q++) if (!fps[q].Empty && (g.Dir > 0 ? fps[q].Close > ext : fps[q].Close < ext)) { back = true; break; }
                    if (back) sweep = (g.Dir > 0 ? "stops under the low " : "stops over the high ") + ext.ToString("0.##", CultureInfo.InvariantCulture) + " run and given back";
                }
                // TREND setups (user's request: a strong trend day has almost no stop runs): with the trend of the last 20 candles (the close beyond their
                // average and beyond the close 20 candles ago) and a pullback into the signal (its low under / high over the 3 candles before it)
                string trend = null;
                if (sweep == null && s.Trend && i >= 20 && !fps[i - 20].Empty)
                {
                    double avg = 0; int na = 0; for (int q = i - 20; q < i; q++) if (!fps[q].Empty) { avg += fps[q].Close; na++; }
                    double pb = g.Dir > 0 ? double.MaxValue : double.MinValue; for (int q = Math.Max(0, i - 3); q < i; q++) if (!fps[q].Empty) pb = g.Dir > 0 ? Math.Min(pb, fps[q].Low) : Math.Max(pb, fps[q].High);
                    if (na >= 10) { avg /= na; bool withTrend = g.Dir > 0 ? fi.Close > avg && fi.Close > fps[i - 20].Close : fi.Close < avg && fi.Close < fps[i - 20].Close; bool pulled = g.Dir > 0 ? fi.Low <= pb : fi.High >= pb;
                        if (withTrend && pulled) trend = "with the trend (20 candles) on a pullback"; }
                }
                if (s.NeedSweep && sweep == null && trend == null) continue;
                for (int j = i + 1; j <= Math.Min(jMax, i + s.ConfirmBars); j++)
                {
                    var fj = fps[j]; if (fj.Empty) continue;
                    if (g.Dir > 0 ? fj.Close < fi.Low : fj.Close > fi.High) break;   // the other side won first: cancelled
                    if ((g.Dir > 0 ? fj.Close > fi.High : fj.Close < fi.Low) && Math.Sign(fj.Delta) == g.Dir)
                    {
                        if (!used.Add(j)) break;
                        res.Add(new KeystoneOfSignal { Time = fj.End, Bar = j, Dir = g.Dir, Kind = sweep == null && trend != null ? "TREND" : "CONFIRMED", Price = fj.Close,
                            Why = (sweep != null ? "1 manipulation: " + sweep + " • " : trend != null ? "1 " + trend + " • " : "") + "2 " + g.Kind + " " + (g.Dir > 0 ? "buy" : "sell") + " signal • 3 confirmed: closed " + (g.Dir > 0 ? "above its high" : "below its low") + " with delta " + (fj.Delta > 0 ? "+" : "") + fj.Delta });
                        break;
                    }
                }
            }
            return res;
        }
        // each signal's OUTCOME (+target ticks before −stop ticks within HorizonBars candles; both in one candle = a loss) and its PROBABILITY =
        // the hit rate of the same kind + side BEFORE it (no look-ahead). Returns the hit rate of every kind + side over the whole history.
        public static Dictionary<string, Tuple<int, int>> Score(List<KeystoneOfSignal> sigs, List<KeystoneFootprint> fps, double tick, KeystoneOfSettings s)
        {
            var seen = new Dictionary<string, int[]>();   // kind|dir → wins, decided
            foreach (var g in sigs.OrderBy(x => x.Bar))
            {
                double tgt = g.Price + g.Dir * s.TargetTicks * tick, stp = g.Price - g.Dir * s.StopTicks * tick; g.Outcome = 0;
                for (int k = g.Bar + 1; k < fps.Count && k <= g.Bar + s.HorizonBars; k++)
                {
                    var f = fps[k]; if (f.Empty) continue;
                    bool hitT = g.Dir > 0 ? f.High >= tgt : f.Low <= tgt, hitS = g.Dir > 0 ? f.Low <= stp : f.High >= stp;
                    if (hitS) { g.Outcome = -1; break; } if (hitT) { g.Outcome = 1; break; }
                }
                string key = g.Kind + "|" + g.Dir; int[] w; if (!seen.TryGetValue(key, out w)) seen[key] = w = new int[2];
                g.Wins = w[0]; g.N = w[1]; g.Prob = w[1] > 0 ? 100.0 * w[0] / w[1] : double.NaN;
                bool decided = g.Outcome != 0 && g.Bar + s.HorizonBars < fps.Count || g.Outcome != 0;
                if (decided) { w[1]++; if (g.Outcome > 0) w[0]++; }
            }
            return seen.ToDictionary(kv => kv.Key, kv => Tuple.Create(kv.Value[0], kv.Value[1]));
        }
    }
    // ✅ CONFIRMATIONS (the trading chart, analysis only): every check votes ▲ BUY (+1), ▼ SELL (−1) or neither (0) — price vs the VWAP,
    // the opening ranges and today's value area, then the order flow of the last CLOSED candle (its delta, its volume vs the 20 before,
    // stacked imbalances in the last 3) and the cumulative delta / buyers' share over the last 5. The forming candle only gives the price.
    // the chart's layers: the INDICATORS (VWAP, ORB, FVG, AI, setups, high / low lines, the chart's order flow parts) are kept PER INSTRUMENT
    // (user's request: switching one on MNQ does not change MGC) as KEY@SYMBOL; an instrument without its own value yet starts from the shared one
    public sealed class KeystoneLayerModes : IEnumerable<KeyValuePair<string, int>>
    {
        readonly Dictionary<string, int> map = new Dictionary<string, int>();
        public Func<string> Sym = () => "";
        public static bool PerInstrument(string k) { return k.StartsWith("IND.") || k.StartsWith("SETUPS") || k.StartsWith("LVL.") || k == "OF.BATTLE" || k == "OF.CHARTSIG" || k == "OF.CNUM" || k == "OF.CONF"; }
        public string Eff(string k) { if (k.IndexOf('@') >= 0 || !PerInstrument(k)) return k; string sy = Sym == null ? "" : Sym(); return string.IsNullOrEmpty(sy) ? k : k + "@" + sy; }
        public int this[string k] { get { return map[Eff(k)]; } set { map[Eff(k)] = value; } }
        public bool TryGetValue(string k, out int v) { return map.TryGetValue(Eff(k), out v); }
        public bool TryGetRaw(string k, out int v) { return map.TryGetValue(k, out v); }
        public void SetFor(string k, string sym, int v) { map[PerInstrument(k) && !string.IsNullOrEmpty(sym) ? k + "@" + sym : k] = v; }
        public IEnumerable<string> Keys { get { return map.Keys.ToList(); } }
        public IEnumerator<KeyValuePair<string, int>> GetEnumerator() { return map.GetEnumerator(); }
        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() { return map.GetEnumerator(); }
    }
    public sealed class KeystoneOfCheck { public string Name = "", Value = ""; public int Dir; }
    public static class KeystoneOfChecks
    {
        public static List<KeystoneOfCheck> Build(List<KeystoneFootprint> fps, double price, double vwap, double orb15Hi, double orb15Lo, double orb30Hi, double orb30Lo, KeystoneProfile prof)
        {
            var res = new List<KeystoneOfCheck>(); var IC = System.Globalization.CultureInfo.InvariantCulture;
            Func<double, string> px = v => v.ToString("0.00", IC);
            Func<long, string> sg = v => (v > 0 ? "+" : v < 0 ? "−" : "") + Math.Abs(v).ToString("N0", IC);
            Action<string, string, int> add = (n, v, d) => res.Add(new KeystoneOfCheck { Name = n, Value = v, Dir = d });
            if (double.IsNaN(price)) return res;
            if (!double.IsNaN(vwap)) add("VWAP", (price > vwap ? "above " : price < vwap ? "below " : "at ") + px(vwap), Math.Sign(price - vwap));
            Action<string, double, double> orb = (n, hi, lo) => { if (double.IsNaN(hi) || double.IsNaN(lo)) return; add(n, price > hi ? "above the high " + px(hi) : price < lo ? "below the low " + px(lo) : "inside " + px(lo) + " – " + px(hi), price > hi ? 1 : price < lo ? -1 : 0); };
            orb("ORB 15", orb15Hi, orb15Lo); orb("ORB 30", orb30Hi, orb30Lo);
            if (prof != null && !double.IsNaN(prof.Vah) && !double.IsNaN(prof.Val))
                add("VALUE AREA", price > prof.Vah ? "above VAH " + px(prof.Vah) : price < prof.Val ? "below VAL " + px(prof.Val) : "inside (POC " + px(prof.Poc) + ")", price > prof.Vah ? 1 : price < prof.Val ? -1 : 0);
            if (fps == null || fps.Count < 2) return res;
            int c = fps.Count - 2; var f = fps[c];   // the last closed candle
            if (f.Volume > 0) add("CANDLE DELTA", sg(f.Delta) + " of " + f.Volume.ToString("N0", IC) + " contracts (" + (100.0 * f.Delta / f.Volume).ToString("0", IC) + "%)", Math.Abs(f.Delta) * 20 >= f.Volume ? Math.Sign(f.Delta) : 0);
            int n0 = Math.Max(0, c - 20); long avg = 0; for (int i = n0; i < c; i++) avg += fps[i].Volume; avg = c > n0 ? avg / (c - n0) : 0;
            if (avg > 0) { bool big = f.Volume * 10 >= avg * 13; int up = double.IsNaN(f.Open) || double.IsNaN(f.Close) ? 0 : Math.Sign(f.Close - f.Open);
                add("VOLUME", f.Volume.ToString("N0", IC) + " vs " + avg.ToString("N0", IC) + " average" + (big ? " (" + (f.Volume / (double)avg).ToString("0.0", IC) + "×)" : " (normal)"), big ? up : 0); }
            if (c >= 3) { long d = f.Cvd - fps[c - 3].Cvd; add("CUM. DELTA (3 candles)", d > 0 ? "rising " + sg(d) : d < 0 ? "falling " + sg(d) : "flat", Math.Sign(d)); }
            int sb = 0, ss = 0; for (int i = Math.Max(0, c - 2); i <= c; i++) foreach (var st in fps[i].Stacks) { if (st.Side > 0) sb++; else ss++; }
            add("STACKED IMBALANCES (3)", sb + " buying • " + ss + " selling", sb > ss ? 1 : ss > sb ? -1 : 0);
            long bb = 0, sl = 0; for (int i = Math.Max(0, c - 4); i <= c; i++) { bb += fps[i].Buy; sl += fps[i].Sell; }
            if (bb + sl > 0) { double sh = 100.0 * bb / (bb + sl); add("BUYERS (5 candles)", sh.ToString("0", IC) + "% bought • " + (100 - sh).ToString("0", IC) + "% sold", sh >= 55 ? 1 : sh <= 45 ? -1 : 0); }
            return res;
        }
    }
    // 📒 ORDER FLOW SETUP JOURNAL: every confirmed setup once it is decided (target or stop hit), one line each in
    // Documents\KeystoneArcData\orderflow_setups.csv — the SETUP TRACKER counts the wins and losses per day / instrument / timeframe
    public static class KeystoneOfJournal
    {
        static readonly CultureInfo IC = CultureInfo.InvariantCulture; static readonly object gate = new object(); static HashSet<string> seen;
        public static string PathOf() { return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments), "KeystoneArcData", "orderflow_setups.csv"); }
        static void Load() { if (seen != null) return; seen = new HashSet<string>(); try { if (File.Exists(PathOf())) foreach (var l in File.ReadAllLines(PathOf())) { var a = l.Split(','); if (a.Length >= 6) seen.Add(string.Join(",", a.Take(5))); } } catch { } }
        public static void Log(string sym, int tf, KeystoneOfSignal g)
        {
            if (g == null || g.Outcome == 0) return;
            lock (gate)
            {
                Load(); string key = g.Time.ToString("yyyy-MM-dd HH:mm", IC) + "," + (sym ?? "") + "," + tf + "," + (g.Dir > 0 ? "BUY" : "SELL") + "," + (g.Kind ?? "").Replace(",", " ");
                if (!seen.Add(key)) return;
                try { Directory.CreateDirectory(Path.GetDirectoryName(PathOf())); File.AppendAllText(PathOf(), key + "," + (g.Outcome > 0 ? "WIN" : "LOSS") + "," + g.Price.ToString(IC) + "," + (double.IsNaN(g.Prob) ? "" : g.Prob.ToString("0", IC)) + "," + g.N + Environment.NewLine); } catch { }
            }
        }
        public static List<string[]> All() { var l = new List<string[]>(); lock (gate) { try { if (File.Exists(PathOf())) foreach (var x in File.ReadAllLines(PathOf())) { var a = x.Split(','); if (a.Length >= 6) l.Add(a); } } catch { } } return l; }
    }
    // the higher timeframes' trend at a candle: the close above (buy) / below (sell) the EMA 20 of the 5M / 15M / 1H candles built from the chart's candles
    public static class KeystoneMtf
    {
        static readonly Dictionary<string, double[]> cache = new Dictionary<string, double[]>();
        public static double[] Ema(List<KeystoneArcBar> cs, int tfMin)
        {
            if (cs == null || cs.Count == 0) return new double[0];
            string key = cs.GetHashCode() + "|" + tfMin + "|" + cs.Count + "|" + cs[cs.Count - 1].Time.Ticks + "|" + cs[cs.Count - 1].Close;
            lock (cache) { double[] got; if (cache.TryGetValue(key, out got)) return got; }
            var e = new double[cs.Count]; double k = 2.0 / 21, ema = double.NaN; long bucket = long.MinValue; double lastClose = 0; int done = 0;
            for (int i = 0; i < cs.Count; i++)
            {
                long b = (long)Math.Floor((cs[i].Time - DateTime.MinValue).TotalMinutes / tfMin);
                if (b != bucket) { if (bucket != long.MinValue) { ema = double.IsNaN(ema) ? lastClose : lastClose * k + ema * (1 - k); done++; } bucket = b; }
                lastClose = cs[i].Close; e[i] = done < 5 || double.IsNaN(ema) ? double.NaN : lastClose * k + ema * (1 - k);
            }
            lock (cache) { if (cache.Count > 40) cache.Clear(); cache[key] = e; }
            return e;
        }
    }
    public static class KeystoneDailyBook
    {
        static readonly CultureInfo IC = CultureInfo.InvariantCulture;
        public static List<KeystoneTrackerTrade> Parse(string text)
        {
            var res = new List<KeystoneTrackerTrade>(); DateTime d; double g, n; int c;
            foreach (var l in (text ?? "").Split('\n'))
            {
                var a = l.Trim().Split('|'); if (a.Length < 5 || !DateTime.TryParseExact(a[0], "yyyy-MM-dd", IC, DateTimeStyles.None, out d) || a[1] == "") continue;
                if (!double.TryParse(a[2], NumberStyles.Float, IC, out g) || !double.TryParse(a[3], NumberStyles.Float, IC, out n)) continue; int.TryParse(a[4], out c);
                Set(res, d, a[1], g, n, c);
            }
            return res;
        }
        public static string Serialize(List<KeystoneTrackerTrade> book)
        {
            return string.Join("\n", book.OrderBy(t => t.Day).ThenBy(t => t.Account, StringComparer.OrdinalIgnoreCase).Select(t => t.Day.ToString("yyyy-MM-dd", IC) + "|" + t.Account + "|" + t.Gross.ToString("0.##", IC) + "|" + t.Net.ToString("0.##", IC) + "|" + t.Count));
        }
        // today's numbers replace the saved ones (NinjaTrader's realized P/L only grows during the day)
        public static void Set(List<KeystoneTrackerTrade> book, DateTime day, string account, double gross, double net, int trades)
        {
            book.RemoveAll(t => t.Day == day.Date && string.Equals(t.Account, account, StringComparison.OrdinalIgnoreCase));
            book.Add(new KeystoneTrackerTrade { Day = day.Date, Account = account, Gross = gross, Net = net, Fees = Math.Max(0, Math.Round(gross - net, 2)), Count = Math.Max(0, trades) });
        }
        // the tracker's trades: the book's day rows win over the journal's single trades of that account + day (the journal keeps the
        // days the book does not have); a book row without a trade count takes the journal's count
        public static List<KeystoneTrackerTrade> Merge(List<KeystoneTrackerTrade> journal, List<KeystoneTrackerTrade> book)
        {
            journal = journal ?? new List<KeystoneTrackerTrade>(); book = book ?? new List<KeystoneTrackerTrade>();
            Func<KeystoneTrackerTrade, string> key = t => t.Day.ToString("yyyy-MM-dd", IC) + "|" + t.Account.ToUpperInvariant();
            var inBook = new HashSet<string>(book.Select(key)); var res = journal.Where(t => !inBook.Contains(key(t))).ToList();
            foreach (var b in book)
            {
                int jc = journal.Where(t => key(t) == key(b)).Sum(t => t.Count);
                res.Add(new KeystoneTrackerTrade { Day = b.Day, Account = b.Account, Gross = b.Gross, Net = b.Net, Fees = b.Fees, Count = b.Count > 0 ? b.Count : Math.Max(jc, Math.Abs(b.Gross) > 0.005 ? 1 : 0) });
            }
            return res;
        }
    }
    // 📋 THE ACCOUNT LOG (user's request: "every event and what is happening for every account"): fed every 2 s with an account's orders and
    // executions as NinjaTrader shows them (orders placed in NinjaTrader included), it writes every change as a line — order placed / moved /
    // part filled / filled / cancelled / rejected, each fill and what it did to the position — and rebuilds each TRADE: when it opened and
    // closed, the most contracts, how many were closed by a TARGET (limit), a STOP or at market, the P/L and the best / worst open P/L.
    public sealed class KeystoneJOrder { public string Id = "", Instrument = "", Name = "", Kind = "", State = ""; public int Side, Qty, Filled; public double Price; }
    public sealed class KeystoneJExec { public string Id = "", Instrument = "", OrderName = "", OrderKind = ""; public DateTime Time; public double Price, Commission; public int SignedQty; }
    public sealed class KeystoneJTrade
    {
        public string Account = "", Instrument = "", Note = ""; public DateTime Day, Open, Close; public int Side, MaxQty, ByTarget, ByStop, ByOther; public double AvgIn, AvgOut, Gross, Fees, Best, Worst;
        public double Net { get { return Gross - Fees; } }
        public string Key { get { return Account + "|" + Instrument + "|" + Open.Ticks; } }
    }
    public sealed class KeystoneAccountJournal
    {
        static readonly CultureInfo IC = CultureInfo.InvariantCulture;
        sealed class Pos { public int Qty, Side, MaxQty, ByTarget, ByStop, ByOther; public DateTime Since; public double Avg, InCost, InQty, OutCost, OutQty, Gross, Fees, Best, Worst; }
        public readonly string Account; readonly Dictionary<string, KeystoneJOrder> orders = new Dictionary<string, KeystoneJOrder>(); readonly HashSet<string> seen = new HashSet<string>();
        readonly Dictionary<string, Pos> pos = new Dictionary<string, Pos>();
        public readonly List<Tuple<DateTime, string>> Events = new List<Tuple<DateTime, string>>(); public readonly List<KeystoneJTrade> Finished = new List<KeystoneJTrade>();
        public KeystoneAccountJournal(string account) { Account = account ?? ""; }
        public bool QuietFirst; bool started;   // QuietFirst: the orders already working at the first look are noted silently (a restart does not log them again)
        public static DateTime DayOf(DateTime t) { return t.Hour >= 18 ? t.Date.AddDays(1) : t.Date; }
        static string P(double v) { return v.ToString("0.00##", IC); }
        static string M(double v) { return (v >= 0 ? "+$" : "−$") + Math.Abs(v).ToString("N0", IC); }
        static string Short(string ins) { var i = (ins ?? "").IndexOf(' '); return i > 0 ? ins.Substring(0, i) : ins ?? ""; }
        static string Ord(KeystoneJOrder o) { return (o.Side > 0 ? "BUY " : "SELL ") + o.Kind + " " + o.Qty + " " + Short(o.Instrument) + (o.Kind != "MARKET" && o.Price > 0 ? " @ " + P(o.Price) : "") + (o.Name != "" ? " (" + o.Name + ")" : ""); }
        void Ev(DateTime t, string x) { Events.Add(Tuple.Create(t, x)); }
        // a new picture of the account (now = New York time); pointValue / lastPrice by instrument (lastPrice NaN = unknown)
        public void Update(DateTime now, List<KeystoneJOrder> ords, List<KeystoneJExec> execs, Func<string, double> pointValue, Func<string, double> lastPrice)
        {
            // 1. the fills, oldest first: each one changes the position (open / add / reduce / close / reverse)
            foreach (var e in (execs ?? new List<KeystoneJExec>()).Where(x => x != null && x.SignedQty != 0 && !seen.Contains(x.Id)).OrderBy(x => x.Time))
            {
                seen.Add(e.Id); double pv = pointValue(e.Instrument); Pos p; if (!pos.TryGetValue(e.Instrument, out p)) pos[e.Instrument] = p = new Pos();
                int q = e.SignedQty; string by = e.OrderKind == "LIMIT" ? "TARGET / LIMIT" : e.OrderKind == "STOP" ? "STOP" : "MARKET";
                if (p.Qty == 0 || Math.Sign(p.Qty) == Math.Sign(q))
                {
                    if (p.Qty == 0) { p.Since = e.Time; p.Side = Math.Sign(q); p.MaxQty = 0; p.ByTarget = p.ByStop = p.ByOther = 0; p.InCost = p.InQty = p.OutCost = p.OutQty = p.Gross = p.Fees = 0; p.Best = p.Worst = 0; }
                    p.Avg = (p.Avg * Math.Abs(p.Qty) + e.Price * Math.Abs(q)) / (Math.Abs(p.Qty) + Math.Abs(q)); p.Qty += q; p.InCost += e.Price * Math.Abs(q); p.InQty += Math.Abs(q); p.Fees += e.Commission; p.MaxQty = Math.Max(p.MaxQty, Math.Abs(p.Qty));
                    Ev(e.Time, "FILL " + (q > 0 ? "BUY " : "SELL ") + Math.Abs(q) + " " + Short(e.Instrument) + " @ " + P(e.Price) + " • " + by + (e.OrderName != "" ? " (" + e.OrderName + ")" : "") + " → " + (p.Qty > 0 ? "LONG " : "SHORT ") + Math.Abs(p.Qty) + " @ " + P(p.Avg));
                    if (Math.Abs(p.Qty) == Math.Abs(q)) Ev(e.Time, "▶ TRADE OPENED " + (p.Side > 0 ? "LONG " : "SHORT ") + Math.Abs(q) + " " + Short(e.Instrument) + " @ " + P(e.Price));
                    continue;
                }
                int close = Math.Min(Math.Abs(q), Math.Abs(p.Qty)), rest = Math.Abs(q) - close; double feeShare = e.Commission * close / Math.Abs(q);
                double gain = (e.Price - p.Avg) * close * p.Side * pv; p.Gross += gain; p.Fees += feeShare; p.OutCost += e.Price * close; p.OutQty += close;
                if (e.OrderKind == "LIMIT") p.ByTarget += close; else if (e.OrderKind == "STOP") p.ByStop += close; else p.ByOther += close;
                p.Qty += Math.Sign(q) * close;
                Ev(e.Time, "FILL " + (q > 0 ? "BUY " : "SELL ") + close + " " + Short(e.Instrument) + " @ " + P(e.Price) + " • " + by + (e.OrderName != "" ? " (" + e.OrderName + ")" : "") + " • " + M(gain) + " → " + (p.Qty == 0 ? "FLAT" : (p.Qty > 0 ? "LONG " : "SHORT ") + Math.Abs(p.Qty) + " left"));
                if (p.Qty == 0)
                {
                    var tr = new KeystoneJTrade { Account = Account, Instrument = e.Instrument, Day = DayOf(p.Since), Open = p.Since, Close = e.Time, Side = p.Side, MaxQty = p.MaxQty, ByTarget = p.ByTarget, ByStop = p.ByStop, ByOther = p.ByOther,
                        AvgIn = p.InQty > 0 ? p.InCost / p.InQty : 0, AvgOut = p.OutQty > 0 ? p.OutCost / p.OutQty : 0, Gross = Math.Round(p.Gross, 2), Fees = Math.Round(p.Fees, 2), Best = Math.Round(Math.Max(p.Best, p.Gross), 2), Worst = Math.Round(Math.Min(p.Worst, p.Gross), 2) };
                    var parts = new List<string>(); if (tr.ByTarget > 0) parts.Add(tr.ByTarget + " by target / limit"); if (tr.ByStop > 0) parts.Add(tr.ByStop + " by stop"); if (tr.ByOther > 0) parts.Add(tr.ByOther + " at market");
                    tr.Note = string.Join(", ", parts) + (tr.ByTarget > 0 && tr.ByTarget < tr.MaxQty ? " • ⚠ the target closed only " + tr.ByTarget + " of " + tr.MaxQty : "");
                    Finished.Add(tr);
                    Ev(e.Time, "■ TRADE CLOSED " + (tr.Side > 0 ? "LONG " : "SHORT ") + Short(tr.Instrument) + " • up to " + tr.MaxQty + " contracts • " + M(tr.Net) + " after fees • " + tr.Note + " • best " + M(tr.Best) + " / worst " + M(tr.Worst));
                }
                if (rest > 0)
                {
                    p.Qty = Math.Sign(q) * rest; p.Side = Math.Sign(q); p.Since = e.Time; p.Avg = e.Price; p.MaxQty = rest; p.ByTarget = p.ByStop = p.ByOther = 0; p.InCost = e.Price * rest; p.InQty = rest; p.OutCost = p.OutQty = p.Gross = 0; p.Fees = e.Commission - feeShare; p.Best = p.Worst = 0;
                    Ev(e.Time, "▶ TRADE OPENED (reversal) " + (p.Side > 0 ? "LONG " : "SHORT ") + rest + " " + Short(e.Instrument) + " @ " + P(e.Price));
                }
            }
            // 2. the open trades: their best / worst open P/L (realized so far + the rest at the last price)
            foreach (var kv in pos) { var p = kv.Value; if (p.Qty == 0) continue; double lp = lastPrice(kv.Key); if (double.IsNaN(lp) || lp <= 0) continue; double open = p.Gross + (lp - p.Avg) * Math.Abs(p.Qty) * p.Side * pointValue(kv.Key); p.Best = Math.Max(p.Best, open); p.Worst = Math.Min(p.Worst, open); }
            // 3. the orders: placed / moved / part filled / filled / cancelled / rejected
            var now0 = new HashSet<string>();
            foreach (var o in ords ?? new List<KeystoneJOrder>())
            {
                if (o == null || o.Id == "") continue; now0.Add(o.Id); KeystoneJOrder was;
                if (!started && QuietFirst) { orders[o.Id] = Copy(o); continue; }
                if (!orders.TryGetValue(o.Id, out was)) { orders[o.Id] = Copy(o); if (o.State != "Filled" && o.State != "Cancelled" && o.State != "Rejected") Ev(now, "ORDER PLACED " + Ord(o) + " • " + o.State); else if (o.State == "Rejected") Ev(now, "✖ ORDER REJECTED " + Ord(o)); continue; }
                if (Math.Abs(was.Price - o.Price) > 1e-9 && o.Kind != "MARKET" && o.Price > 0 && o.State != "Filled") Ev(now, "ORDER MOVED " + (o.Side > 0 ? "BUY " : "SELL ") + o.Kind + " " + o.Qty + " " + Short(o.Instrument) + " " + P(was.Price) + " → " + P(o.Price));
                if (was.Qty != o.Qty && o.State != "Filled") Ev(now, "ORDER SIZE " + Ord(o) + " " + was.Qty + " → " + o.Qty + " contracts");
                if (was.State != o.State || was.Filled != o.Filled)
                {
                    if (o.State == "Filled") Ev(now, "✔ ORDER FILLED " + Ord(o) + " • " + o.Filled + " / " + o.Qty);
                    else if (o.State == "PartFilled" || (o.Filled > was.Filled && o.Filled < o.Qty)) Ev(now, "◐ PART FILLED " + Ord(o) + " • " + o.Filled + " of " + o.Qty + " so far");
                    else if (o.State == "Cancelled") Ev(now, "⊘ ORDER CANCELLED " + Ord(o) + (o.Filled > 0 ? " • " + o.Filled + " of " + o.Qty + " had filled" : ""));
                    else if (o.State == "Rejected") Ev(now, "✖ ORDER REJECTED " + Ord(o));
                    else if (o.State == "Working" && was.State != "Accepted" && was.State != "Working") Ev(now, "ORDER WORKING " + Ord(o));
                }
                orders[o.Id] = Copy(o);
            }
            started = true;
        }
        static KeystoneJOrder Copy(KeystoneJOrder o) { return new KeystoneJOrder { Id = o.Id, Instrument = o.Instrument, Name = o.Name, Kind = o.Kind, State = o.State, Side = o.Side, Qty = o.Qty, Filled = o.Filled, Price = o.Price }; }
        // the open position of an instrument as the log sees it (signed contracts)
        public int OpenQty(string instrument) { Pos p; return pos.TryGetValue(instrument ?? "", out p) ? p.Qty : 0; }
        public static string TradeLine(KeystoneJTrade t)
        {
            Func<string, string> c = x => (x ?? "").Replace(",", ";");
            return string.Join(",", new[] { t.Day.ToString("yyyy-MM-dd", IC), c(t.Account), c(t.Instrument), t.Side > 0 ? "LONG" : "SHORT", t.Open.ToString("yyyy-MM-dd HH:mm:ss", IC), t.Close.ToString("yyyy-MM-dd HH:mm:ss", IC), t.MaxQty.ToString(IC), P(t.AvgIn), P(t.AvgOut),
                t.ByTarget.ToString(IC), t.ByStop.ToString(IC), t.ByOther.ToString(IC), t.Gross.ToString("0.##", IC), t.Fees.ToString("0.##", IC), t.Best.ToString("0.##", IC), t.Worst.ToString("0.##", IC), c(t.Note) });
        }
        public static KeystoneJTrade ParseTrade(string l)
        {
            var a = (l ?? "").Split(','); if (a.Length < 17) return null; DateTime d, o, cl; int mq, bt, bs, bo; double ai, ao, g, f, b, w;
            if (!DateTime.TryParse(a[0], IC, DateTimeStyles.None, out d) || !DateTime.TryParse(a[4], IC, DateTimeStyles.None, out o) || !DateTime.TryParse(a[5], IC, DateTimeStyles.None, out cl)) return null;
            int.TryParse(a[6], NumberStyles.Integer, IC, out mq); double.TryParse(a[7], NumberStyles.Float, IC, out ai); double.TryParse(a[8], NumberStyles.Float, IC, out ao); int.TryParse(a[9], NumberStyles.Integer, IC, out bt); int.TryParse(a[10], NumberStyles.Integer, IC, out bs); int.TryParse(a[11], NumberStyles.Integer, IC, out bo);
            double.TryParse(a[12], NumberStyles.Float, IC, out g); double.TryParse(a[13], NumberStyles.Float, IC, out f); double.TryParse(a[14], NumberStyles.Float, IC, out b); double.TryParse(a[15], NumberStyles.Float, IC, out w);
            return new KeystoneJTrade { Day = d, Account = a[1], Instrument = a[2], Side = a[3] == "LONG" ? 1 : -1, Open = o, Close = cl, MaxQty = mq, AvgIn = ai, AvgOut = ao, ByTarget = bt, ByStop = bs, ByOther = bo, Gross = g, Fees = f, Best = b, Worst = w, Note = a[16] };
        }
    }
    public sealed class KeystoneTrackerLive
    {
        public string Account = "", Connection = "", Plan = "", Positions = "", Group = ""; public double Balance = double.NaN, Today = double.NaN, Open, OpenCost, Gross = double.NaN, Closed = double.NaN; public bool Connected;   // Gross / Closed: NinjaTrader's gross / realized P/L today   // Positions / Open / OpenCost: the open trade now (open P/L from NinjaTrader, ≈ commissions + 1 tick to close it)
        public double Start, Target, Dd, Floor = double.NaN, Room = double.NaN, Left = double.NaN, DayCap = double.NaN; public bool Funded;   /* DayCap: the most an EVALUATION day may make (consistency) */   // from the firm rules: start balance, target, drawdown, the floor now, room above it, left to pass
    }
    public static class KeystoneTracker
    {
        static readonly CultureInfo IC = CultureInfo.InvariantCulture;
        static string H(string v) { return System.Net.WebUtility.HtmlEncode(v ?? ""); }
        static string M(double v) { return (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", IC); }
        static string S(double v) { return (v > 0 ? "+$" : v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", IC); }
        static string Cls(double v) { return v > 0.5 ? "pos" : v < -0.5 ? "neg" : ""; }
        // the real trades for the tracker: RealTrades.csv (session, account, … gross, fees, net) + the older RealJournal.csv (net only)
        public static List<KeystoneTrackerTrade> ReadTrades(string realJournal, string realTrades)
        {
            var list = new List<KeystoneTrackerTrade>(); DateTime d; double g, f, n;
            try
            {
                if (realTrades != null && File.Exists(realTrades))
                    foreach (var a in File.ReadAllLines(realTrades).Skip(1).Select(l => l.Split(',')).Where(a => a.Length >= 13))
                        if (DateTime.TryParse(a[0], IC, DateTimeStyles.None, out d) && double.TryParse(a[10], NumberStyles.Float, IC, out g) && double.TryParse(a[11], NumberStyles.Float, IC, out f) && double.TryParse(a[12], NumberStyles.Float, IC, out n))
                            list.Add(new KeystoneTrackerTrade { Account = a[1], Day = d.Date, Gross = g, Fees = f, Net = n });
            }
            catch { }
            try
            {
                if (realJournal != null && File.Exists(realJournal))
                    foreach (var a in File.ReadAllLines(realJournal).Skip(1).Select(l => l.Split(',')).Where(a => a.Length >= 10))
                        if (DateTime.TryParse(a[6], IC, DateTimeStyles.None, out d) && double.TryParse(a[9], NumberStyles.Float, IC, out n))
                            list.Add(new KeystoneTrackerTrade { Account = a[0], Day = d.Hour >= 18 ? d.Date.AddDays(1) : d.Date, Gross = n, Fees = 0, Net = n });
            }
            catch { }
            return list;
        }
        public static string StatusColor(string st) { return st == "FUNDED" ? "#bc8cff" : st == "PASSED" ? "#3fb950" : st == "PAYOUT" ? "#e3b341" : st == "BLOWN" ? "#f85149" : st == "CLOSED" ? "#8b949e" : "#58a6ff"; }
        static readonly string[] AccPalette = { "#58a6ff", "#f778ba", "#3fb950", "#e3b341", "#bc8cff", "#ff7b72", "#39c5cf", "#ffa657", "#a5d6ff", "#7ee787", "#d2a8ff", "#ffdf5d", "#79c0ff", "#ffa198" };
        public static string Build(List<KeystonePoolAccount> pool, List<KeystoneTrackerTrade> trades, Dictionary<string, KeystoneTrackerLive> live, DateTime now, int refreshSeconds = 30, List<KeystoneTrackerGroup> groups = null, DateTime? dayShown = null)
        {
            pool = pool ?? new List<KeystonePoolAccount>(); trades = trades ?? new List<KeystoneTrackerTrade>(); live = live ?? new Dictionary<string, KeystoneTrackerLive>(); groups = groups ?? new List<KeystoneTrackerGroup>();
            // every account its own colour (the same on every tab), in name order: TPT 1, TPT 2 … TPT 10
            var accCol = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase); int ci0 = 0;
            foreach (var a in pool.OrderBy(a => (a.Nick != "" ? a.Nick : a.Account).Length).ThenBy(a => a.Nick != "" ? a.Nick : a.Account, StringComparer.OrdinalIgnoreCase)) accCol[a.Account] = AccPalette[ci0++ % AccPalette.Length];
            Func<string, string> colOf = acc => { string c; return accCol.TryGetValue(acc ?? "", out c) ? c : "#8b949e"; };
            Func<string, string> nickOf = acc => { var pa = pool.FirstOrDefault(x => string.Equals(x.Account, acc, StringComparison.OrdinalIgnoreCase)); return pa != null && pa.Nick != "" ? pa.Nick : acc; };
            Func<string, KeystoneTrackerGroup> groupOf = acc => groups.FirstOrDefault(g => g.Members.Contains(acc ?? "", StringComparer.OrdinalIgnoreCase));
            Func<KeystonePoolAccount, string[]> firm = a => { KeystoneTrackerLive lv; live.TryGetValue(a.Account, out lv); return KeystoneFirmNames.Detect(a.Account, lv != null ? lv.Connection : "", string.IsNullOrWhiteSpace(a.Firm) ? null : a.Firm); };
            Func<KeystonePoolAccount, KeystoneTrackerLive> lvOf = a => { KeystoneTrackerLive lv; live.TryGetValue(a.Account, out lv); return lv; };
            Func<KeystonePoolAccount, List<KeystoneTrackerTrade>> tradesOf = a => trades.Where(t => string.Equals(t.Account, a.Account, StringComparison.OrdinalIgnoreCase)).ToList();
            double spent = pool.Sum(a => a.Spent), paid = pool.Sum(a => a.PaidOut), fees = trades.Sum(t => t.Fees), tradeNet = trades.Sum(t => t.Net), gross = trades.Sum(t => t.Gross);
            double todayPnl = live.Values.Where(l => !double.IsNaN(l.Today) && l.Connected).Sum(l => l.Today); bool anyLive = live.Values.Any(l => l.Connected);
            int funded = pool.Count(a => a.Funded || a.Status == "PASSED"), blown = pool.Count(a => a.Status == "BLOWN"), evals = pool.Count(a => a.Status == "EVAL");
            DateTime sessNow = now.Hour >= 18 ? now.Date.AddDays(1) : now.Date, today = dayShown.HasValue && dayShown.Value != DateTime.MinValue ? dayShown.Value.Date : sessNow;   // today = the trading day NinjaTrader's numbers are from
            var days = new SortedDictionary<DateTime, double[]>();   // spent, paid, gross, fees, net, trades
            Func<DateTime, double[]> D = d => { double[] x; if (!days.TryGetValue(d.Date, out x)) days[d.Date] = x = new double[6]; return x; };
            foreach (var a in pool) { if (a.Started != DateTime.MinValue && a.Cost > 0) D(a.Started)[0] += a.Cost; foreach (var e in a.Expenses) D(e.Item1)[0] += e.Item2; foreach (var p in a.Payouts) D(p.Item1)[1] += p.Item2; }
            foreach (var t in trades) { var x = D(t.Day); x[2] += t.Gross; x[3] += t.Fees; x[4] += t.Net; x[5] += t.Count; }
            var sb = new StringBuilder();
            sb.Append("<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>");
            if (refreshSeconds > 0) sb.Append("<meta http-equiv='refresh' content='" + refreshSeconds + "'>");
            sb.Append("<title>Prop Tracker</title><style>:root{--bg:#0d1117;--card:#161b22;--card2:#1f2630;--line:#30363d;--text:#e6edf3;--mute:#8b949e;--pos:#3fb950;--neg:#f85149;--acc:#e3b341;--blue:#58a6ff;--violet:#bc8cff}");
            sb.Append("@media (prefers-color-scheme: light){:root{--bg:#f6f8fa;--card:#fff;--card2:#f0f3f6;--line:#d0d7de;--text:#1f2328;--mute:#656d76;--pos:#1a7f37;--neg:#cf222e;--acc:#9a6700;--blue:#0969da;--violet:#8250df}}");
