            sb.Append("<div class='top'><h1>Prop Tracker</h1><div class='mute'><span class='dot " + (anyLive ? "live" : "") + "' style='" + (anyLive ? "" : "background:var(--mute)") + "'></span>" + (anyLive ? "LIVE from NinjaTrader" : "last saved") + " • updated " + now.ToString("ddd yyyy-MM-dd HH:mm:ss", IC) + (refreshSeconds > 0 ? " • refreshes every " + refreshSeconds + " s" : "") + "</div></div>");
            sb.Append("<div class='tabs' id='tabs'><button data-t='today' class='on'>Today</button><button data-t='grp'>Groups</button><button data-t='ov'>Overview</button><button data-t='acc'>Accounts</button><button data-t='eval'>Evaluation</button><button data-t='fund'>Funded</button><button data-t='days'>Day by day</button><button data-t='money'>Costs &amp; payouts</button><button data-t='adv'>Advice</button></div>");
