            // ===== OVERVIEW
            Action<string, string, string> tile = (cap, val, cls) => sb.Append("<div class='tile'><span>" + H(cap) + "</span><b class='" + cls + "'>" + val + "</b></div>");
            int idx = 0; var ids = new Dictionary<string, string>();   // the account pages (a click on any row / card opens one)
