            // ===== TODAY: every account as NinjaTrader shows it now (gross, commissions, realized, open, the day), its group, its colour
            {
                string dayTag = "BLOWN " + today.ToString("yyyy-MM-dd", IC), dayTag2 = "BLOWN " + today.AddDays(-1).ToString("yyyy-MM-dd", IC);
                Func<KeystonePoolAccount, bool> blownToday = a => a.Status == "BLOWN" && a.Notes != null && (a.Notes.StartsWith(dayTag) || a.Notes.StartsWith(dayTag2));
                var rowsT = pool.Where(a => !a.Archived || blownToday(a)).Select(a => Tuple.Create(a, lvOf(a) ?? (blownToday(a) ? new KeystoneTrackerLive { Account = a.Account } : null))).Where(x => x.Item2 != null).OrderBy(x => nickOf(x.Item1.Account).Length).ThenBy(x => nickOf(x.Item1.Account), StringComparer.OrdinalIgnoreCase).ToList();
                Func<double, bool> ok = v => !double.IsNaN(v);
