                Func<KeystoneTrackerLive, double> pctOf = l => ok(l.Closed) && ok(l.DayCap) && l.DayCap > 0 ? l.Closed / l.DayCap : double.NaN;
                var overL = evalR.Where(x => pctOf(x.Item2) >= 1).ToList(); var nearL = evalR.Where(x => pctOf(x.Item2) >= 0.8 && pctOf(x.Item2) < 1).ToList();
                double tG = rowsT.Where(x => ok(x.Item2.Gross)).Sum(x => x.Item2.Gross), tR = rowsT.Where(x => ok(x.Item2.Closed)).Sum(x => x.Item2.Closed);
