                sb.Append("<section class='pane on' id='p-today'><h2>" + today.ToString("dddd yyyy-MM-dd", IC) + " <span class='todaychip'>" + (today < sessNow ? "LAST SESSION" : "TODAY") + "</span>" + (today < sessNow ? " <span class='mute' style='font-size:12px;font-weight:500'>the next trading day (" + sessNow.ToString("ddd dd", IC) + ") began at 18:00 New York — it shows here with your first trade</span>" : "") + "</h2><div class='hero'>");
                if (fundR.Count > 0) { double fR = fundR.Where(x => ok(x.Item2.Closed)).Sum(x => x.Item2.Closed), fO = fundR.Where(x => x.Item2.Positions != "").Sum(x => x.Item2.Open); hc("Funded • yours today", S(fR), fundR.Count + " funded" + (Math.Abs(fO) > 0.5 ? " • open " + S(fO) : "") + " • after fees", "#059669", "#0d9488"); }
