                hc("Over the day limit", overL.Count.ToString(IC), overL.Count > 0 ? H(string.Join(", ", overL.Select(x => nickOf(x.Item1.Account)))) : "none — good", overL.Count > 0 ? "#dc2626" : "#475569", overL.Count > 0 ? "#f43f5e" : "#64748b");
                hc("Near the limit (80%+)", nearL.Count.ToString(IC), nearL.Count > 0 ? H(string.Join(", ", nearL.Select(x => nickOf(x.Item1.Account)))) : "—", nearL.Count > 0 ? "#d97706" : "#475569", nearL.Count > 0 ? "#f59e0b" : "#64748b");
