            tile("Accounts bought", pool.Count.ToString(IC), ""); tile("In evaluation", evals.ToString(IC), ""); tile("Passed / funded", funded.ToString(IC), "pos"); tile("Blown", blown.ToString(IC), blown > 0 ? "neg" : "");
            tile("Spent", M(spent), "neg"); tile("Paid to you", M(paid), "pos"); tile("Trading P/L today", anyLive ? S(todayPnl) : "—", Cls(todayPnl)); double openNow = live.Values.Where(l => l.Connected && l.Positions != "").Sum(l => l.Open), openCost = live.Values.Where(l => l.Connected && l.Positions != "").Sum(l => l.OpenCost); int openN = live.Values.Count(l => l.Connected && l.Positions != "");
            if (openN > 0) { tile("Open now (" + openN + " account" + (openN == 1 ? "" : "s") + ")", S(openNow), Cls(openNow)); tile("Costs to close ≈", M(openCost), "neg"); } tile("Trading P/L (all)", S(tradeNet), Cls(tradeNet)); tile("Commissions", M(fees), fees > 0 ? "neg" : "");
            tile("Trades", trades.Sum(t => t.Count).ToString(IC), ""); tile("Green account-days", trades.Count > 0 ? (100.0 * trades.Count(t => t.Net > 0) / trades.Count).ToString("0", IC) + "%" : "—", "");
            sb.Append("</div>");
            if (days.Count >= 2)
            {
                var keys = days.Keys.ToList(); double cs = 0, cpd = 0, ct = 0; var ptsS = new List<double>(); var ptsP = new List<double>(); var ptsN = new List<double>(); var ptsT = new List<double>();
                foreach (var k in keys) { cs += days[k][0]; cpd += days[k][1]; ct += days[k][4]; ptsS.Add(cs); ptsP.Add(cpd); ptsN.Add(cpd - cs); ptsT.Add(ct); }
                double hi = Math.Max(1, new[] { ptsS.Max(), ptsP.Max(), ptsT.Max() }.Max()), lo = Math.Min(0, Math.Min(ptsN.Min(), ptsT.Min())); int W = 1000, Hh = 220, pad = 30;
                Func<int, double> X = i => pad + (W - 2 * pad) * (keys.Count == 1 ? 0 : i / (double)(keys.Count - 1)); Func<double, double> Y = v => 10 + (Hh - 30) * (hi - v) / Math.Max(1, hi - lo);
                Func<List<double>, string> path = l => string.Join(" ", l.Select((v, i) => (i == 0 ? "M" : "L") + X(i).ToString("0.#", IC) + "," + Y(v).ToString("0.#", IC)));
                sb.Append("<h2>Money over time</h2><div class='wrap' style='padding:10px'><svg viewBox='0 0 " + W + " " + Hh + "' width='100%' role='img' aria-label='spent, paid out, net and trading P/L over time'>");
                sb.Append("<line x1='" + pad + "' x2='" + (W - pad) + "' y1='" + Y(0).ToString("0.#", IC) + "' y2='" + Y(0).ToString("0.#", IC) + "' stroke='var(--line)'/>");
                sb.Append("<path d='" + path(ptsS) + "' fill='none' stroke='var(--neg)' stroke-width='2'/><path d='" + path(ptsP) + "' fill='none' stroke='var(--pos)' stroke-width='2'/><path d='" + path(ptsN) + "' fill='none' stroke='var(--acc)' stroke-width='3'/><path d='" + path(ptsT) + "' fill='none' stroke='var(--violet)' stroke-width='2' stroke-dasharray='5 4'/>");
                sb.Append("<text x='" + pad + "' y='" + (Hh - 4) + "' fill='var(--mute)' font-size='12'>" + keys[0].ToString("MMM d", IC) + "</text><text x='" + (W - pad) + "' y='" + (Hh - 4) + "' text-anchor='end' fill='var(--mute)' font-size='12'>" + keys[keys.Count - 1].ToString("MMM d", IC) + "</text></svg>");
                sb.Append("<div class='mute' style='font-size:12px'><span class='dot' style='background:var(--neg)'></span>spent &nbsp; <span class='dot' style='background:var(--pos)'></span>paid to you &nbsp; <span class='dot' style='background:var(--acc)'></span>net (lowest " + S(ptsN.Min()) + ") &nbsp; <span class='dot' style='background:var(--violet)'></span>trading P/L</div></div>");
            }
            sb.Append("<h2>By firm</h2><div class='wrap'><table><tr><th class='l'>Firm</th><th>Bought</th><th>Eval</th><th>Funded</th><th>Blown</th><th>Pass rate</th><th>Spent</th><th>Paid to you</th><th>Net</th><th>Trading P/L</th></tr>");
            foreach (var g in pool.GroupBy(a => firm(a)[1]).OrderByDescending(g => g.Sum(a => a.PaidOut - a.Spent)))
            {
                var f0 = firm(g.First()); int fin = g.Count(a => a.Status != "EVAL"), ps = g.Count(a => a.Funded || a.Status == "PASSED" || a.Payouts.Count > 0);
                var accs = new HashSet<string>(g.Select(a => a.Account), StringComparer.OrdinalIgnoreCase); double tn = trades.Where(t => accs.Contains(t.Account)).Sum(t => t.Net); double nt = g.Sum(a => a.PaidOut - a.Spent);
                sb.Append("<tr><td class='l'><span class='stripe' style='background:" + f0[2] + "'></span>" + H(g.Key) + "</td><td>" + g.Count() + "</td><td>" + g.Count(a => a.Status == "EVAL") + "</td><td class='pos'>" + g.Count(a => a.Funded) + "</td><td class='neg'>" + g.Count(a => a.Status == "BLOWN") + "</td><td>" + (fin > 0 ? (100.0 * ps / fin).ToString("0", IC) + "%" : "—") + "</td><td>" + M(g.Sum(a => a.Spent)) + "</td><td class='pos'>" + M(g.Sum(a => a.PaidOut)) + "</td><td class='" + Cls(nt) + "'><b>" + S(nt) + "</b></td><td class='" + Cls(tn) + "'>" + S(tn) + "</td></tr>");
            }
            sb.Append("</table></div></section>");
            // ===== ACCOUNTS (click a row → its page)
