            foreach (var st in new[] { "EVAL", "FUNDED", "PAYOUT", "BLOWN" }) sb.Append("<button data-f='" + st + "'>" + st + "</button>");
            sb.Append("<input id='q' placeholder='search account / firm'></div><div class='wrap'><table id='acc'><tr><th class='l'>Account</th><th class='l'>Firm</th><th class='l'>Status</th><th>Bought</th><th>Days</th><th>Balance now</th><th>Today</th><th>Auto-liquidation</th><th>Left to pass</th><th>Trading P/L</th><th>Commissions</th><th>Spent</th><th>Paid to you</th><th>Net</th></tr>");
            foreach (var a in pool.OrderBy(a => a.Archived).ThenBy(a => firm(a)[1]).ThenBy(a => a.Nick, StringComparer.OrdinalIgnoreCase))
