                string rowCls = (st == "FUNDED" || st == "PAYOUT" ? "funded" : st == "BLOWN" ? "blown" : "") + " click";
                sb.Append("<tr class='" + rowCls + "' data-id='" + id + "' data-s='" + st + "' data-t='" + H((a.Account + " " + a.Nick + " " + f0[1]).ToLowerInvariant()) + "'><td class='l'><span class='stripe' style='background:" + colOf(a.Account) + "'></span><b style='color:" + colOf(a.Account) + "'>" + H(a.Nick != "" ? a.Nick : a.Account) + "</b>" + (a.Nick != "" ? " <span class='mute'>" + H(a.Account) + "</span>" : "") + "</td>");
                sb.Append("<td class='l'>" + H(f0[1]) + "</td><td class='l'><span class='chip' style='background:" + StatusColor(st) + "'>" + st + "</span></td>");
                sb.Append("<td>" + (a.Started == DateTime.MinValue ? "—" : a.Started.ToString("yyyy-MM-dd", IC)) + "</td><td>" + (a.Started == DateTime.MinValue ? "—" : ((int)(today - a.Started.Date).TotalDays + 1).ToString(IC)) + "</td>");
                sb.Append("<td>" + (lv != null && !double.IsNaN(lv.Balance) ? M(lv.Balance) : "—") + "</td><td class='" + (lv != null ? Cls(lv.Today) : "") + "'>" + (lv != null && !double.IsNaN(lv.Today) && lv.Connected ? S(lv.Today) : "—") + "</td>");
                sb.Append("<td>" + (lv != null && !double.IsNaN(lv.Floor) ? M(lv.Floor) : "—") + "</td><td>" + (lv != null && !double.IsNaN(lv.Left) && !a.Funded ? M(lv.Left) : "—") + "</td>");
