                sb.Append("<div class='acard click' data-id='" + ids[a.Account] + "' style='border-top-color:" + f0[2] + ";cursor:pointer'><div style='display:flex;justify-content:space-between'><b style='font-size:16px'>" + H(a.Nick != "" ? a.Nick : a.Account) + "</b><span class='chip' style='background:" + StatusColor(a.Status) + "'>" + a.Status + "</span></div>");
                sb.Append("<div class='mute' style='font-size:12px'>" + H(f0[1]) + " • " + H(a.Account) + "</div><div style='font-size:22px;font-weight:700;margin:4px 0'>" + (double.IsNaN(bal) ? "—" : M(bal)) + (lv != null && lv.Connected && !double.IsNaN(lv.Today) ? " <span class='" + Cls(lv.Today) + "' style='font-size:14px'>" + S(lv.Today) + " today</span>" : "") + "</div>");
                if (lv != null && lv.Connected && lv.Positions != "") sb.Append("<div style='font-size:12.5px;font-weight:600;margin-bottom:4px'><span class='dot live'></span>" + H(lv.Positions) + " • open <span class='" + Cls(lv.Open) + "'>" + S(lv.Open) + "</span> • costs ≈ " + M(lv.OpenCost) + " • net if closed now <span class='" + Cls(lv.Open - lv.OpenCost) + "'>" + S(lv.Open - lv.OpenCost) + "</span></div>");
                if (lv != null && !double.IsNaN(lv.Room) && lv.Dd > 0) { double fr = Math.Max(0, Math.Min(1, lv.Room / lv.Dd)); sb.Append("<div class='mute' style='font-size:12px'>" + "auto-liquidation " + M(lv.Floor) + " (" + (a.Funded ? "🛡 intraday trailing" : "end of day") + ") • " + M(lv.Room) + " room</div><div class='meter'><i style='width:" + (100 * fr).ToString("0", IC) + "%;background:" + (fr < 0.3 ? "var(--neg)" : fr < 0.6 ? "var(--acc)" : a.Funded ? "var(--violet)" : "var(--blue)") + "'></i></div>"); }
