            sb.Append("<section class='pane' id='p-eval'><h2>Evaluation • end-of-day drawdown, consistency</h2><div class='cards'>"); foreach (var a in pool.Where(a => !a.Funded && !a.Archived).OrderBy(a => a.Nick, StringComparer.OrdinalIgnoreCase)) card(a); sb.Append("</div></section>");
            sb.Append("<section class='pane' id='p-fund'><h2>Funded • intraday trailing drawdown, payouts</h2><div class='cards'>"); foreach (var a in pool.Where(a => a.Funded).OrderBy(a => a.Nick, StringComparer.OrdinalIgnoreCase)) card(a);
            if (!pool.Any(a => a.Funded)) sb.Append("<p class='mute'>No funded account yet.</p>"); sb.Append("</div></section>");
            // where an account stands now (today's rows in DAY BY DAY): left to pass, drawdown left, auto-liquidation, the day limit
