                if (l.Funded) parts.Add("funded"); else if (!double.IsNaN(l.Left)) parts.Add(l.Left <= 0.5 ? "<b class='pos'>PASSED ✔</b>" : "to pass <b style='color:var(--blue)'>" + M(l.Left) + "</b>");
                if (!double.IsNaN(l.Room)) parts.Add("drawdown left <b>" + M(l.Room) + "</b>"); if (!double.IsNaN(l.Floor)) parts.Add("auto-liq " + M(l.Floor));
                if (!double.IsNaN(l.DayCap) && l.DayCap > 0 && !double.IsNaN(l.Closed)) parts.Add(l.Closed > l.DayCap ? "<span class='flag'>OVER the day limit</span>" : "day limit " + (100 * l.Closed / l.DayCap).ToString("0", IC) + "%");
                return string.Join(" • ", parts);
            };
