                sb.Append("<tr class='day" + (k == today ? " today" : "") + "' data-d='" + dk + "'><td class='l'>" + k.ToString("ddd yyyy-MM-dd", IC) + (k == today ? "<span class='todaychip'>TODAY</span>" : "") + "</td><td>" + (x[5] > 0 ? x[5].ToString("0", IC) : "") + "</td><td class='" + Cls(x[2]) + "'>" + (x[5] > 0 ? S(x[2]) : "") + "</td><td>" + (x[3] > 0 ? M(x[3]) : "") + "</td><td class='" + Cls(x[4]) + "'>" + (x[5] > 0 ? S(x[4]) : "") + "</td><td class='neg'>" + (x[0] > 0 ? M(x[0]) : "") + "</td><td class='pos'>" + (x[1] > 0 ? M(x[1]) : "") + "</td><td class='" + Cls(cash) + "'>" + (Math.Abs(cash) > 0.005 ? S(cash) : "") + "</td><td class='" + Cls(runAt[k]) + "'><b>" + S(runAt[k]) + "</b></td></tr>");
                // ▾ the day's accounts (click the day): each in its colour, its group, trades, gross, commissions, net
