            foreach (var e in ev.OrderByDescending(x => x.Item1)) sb.Append("<tr><td class='l'>" + e.Item1.ToString("ddd yyyy-MM-dd", IC) + "</td><td class='l'>" + H(e.Item2) + "</td><td class='l'>" + H(e.Item3) + "</td><td class='" + Cls(e.Item4) + "'><b>" + S(e.Item4) + "</b></td></tr>");
