                if (!a.Funded && lv.Plan.StartsWith("TODAY IS OVER")) adv.Add("<b class='neg'>" + nm + "</b>: today is over the consistency limit — stop trading it today; " + H(lv.Plan) + ".");
                else if (!a.Funded && !double.IsNaN(lv.Left) && lv.Left > 0 && lv.Target > 0 && lv.Left < lv.Target * 0.25) adv.Add("<b class='pos'>" + nm + "</b> is close to passing: " + H(lv.Plan) + ".");
                if (a.Funded && !double.IsNaN(lv.Balance) && lv.Start > 0 && lv.Balance - lv.Start > lv.Dd && lv.Dd > 0) adv.Add("<b class='pos'>" + nm + "</b> has " + S(lv.Balance - lv.Start) + " above the start — check the payout rules and ask for a payout."); }
            if (gross > 0 && fees / gross > 0.15) adv.Add("Commissions are " + (100 * fees / gross).ToString("0", IC) + "% of your gross profit — fewer, bigger trades keep more of it.");
            if (trades.Count >= 10) { var w = trades.Where(t => t.Net > 0).ToList(); var l = trades.Where(t => t.Net < 0).ToList(); if (w.Count > 0 && l.Count > 0) adv.Add("Average green account-day " + S(w.Average(t => t.Net)) + " vs red " + S(l.Average(t => t.Net)) + " (" + (100.0 * w.Count / trades.Count).ToString("0", IC) + "% green)" + (Math.Abs(l.Average(t => t.Net)) > w.Average(t => t.Net) ? " — your losses are bigger than your wins: tighter stops or let winners run." : " — keep it up.")); }
