            if (adv.Count == 0) adv.Add("All good — nothing needs attention right now.");
            sb.Append("<section class='pane' id='p-adv'><h2>What the numbers say</h2><ul class='advice'>" + string.Join("", adv.Select(x => "<li>" + x + "</li>")) + "</ul></section>");
            // ===== ACCOUNT PAGES (hidden; a click on a row / card opens one)
            foreach (var a in pool)
            {
                var f0 = firm(a); var lv = lvOf(a); var mine = tradesOf(a); string nm = a.Nick != "" ? a.Nick : a.Account;
