    public sealed class KeystonePoolStats { public int Days, Trades, Wins; public double Pnl, BestDayPct, LastBalance, Fees; }
    public static class KeystonePool
    {
        public static readonly string[] Statuses = { "EVAL", "PASSED", "FUNDED", "PAYOUT", "BLOWN", "CLOSED" };
        public static string Serialize(IEnumerable<KeystonePoolAccount> list)
        {
            var sb = new StringBuilder(); Func<string, string> c = x => (x ?? "").Replace("|", "/").Replace("\n", " ");
            foreach (var a in list)
            {
                sb.AppendLine(string.Join("|", "ACC", c(a.Account), c(a.Nick), c(a.Firm), c(a.Status), a.Started == DateTime.MinValue ? "" : a.Started.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture), a.Cost.ToString(CultureInfo.InvariantCulture), c(a.Notes)));
                foreach (var p in a.Payouts) sb.AppendLine(string.Join("|", "PAY", c(a.Account), p.Item1.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture), p.Item2.ToString(CultureInfo.InvariantCulture)));
                foreach (var e in a.Expenses) sb.AppendLine(string.Join("|", "EXP", c(a.Account), e.Item1.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture), e.Item2.ToString(CultureInfo.InvariantCulture), c(e.Item3)));
                if (a.PeakBal > 0 || a.FundedOn != DateTime.MinValue || a.AutoChecked || a.FundedDd != "INTRADAY") sb.AppendLine(string.Join("|", "STA", c(a.Account), a.FundedOn == DateTime.MinValue ? "" : a.FundedOn.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture), a.FundedPeak.ToString("0.##", CultureInfo.InvariantCulture), a.PeakBal.ToString("0.##", CultureInfo.InvariantCulture), a.LowBal.ToString("0.##", CultureInfo.InvariantCulture), a.MaxDd.ToString("0.##", CultureInfo.InvariantCulture), a.FundedDd, a.AutoChecked ? "1" : "0"));
            }
            return sb.ToString();
        }
        public static List<KeystonePoolAccount> Parse(string text)
        {
            var list = new List<KeystonePoolAccount>(); var by = new Dictionary<string, KeystonePoolAccount>(StringComparer.OrdinalIgnoreCase);
            foreach (var line in (text ?? "").Split(new[] { '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries))
            {
                var a = line.Split('|'); double v; DateTime d;
                if (a[0] == "ACC" && a.Length >= 8)
                {
                    var x = new KeystonePoolAccount { Account = a[1], Nick = a[2], Firm = a[3], Status = a[4], Notes = a[7] };
                    if (DateTime.TryParseExact(a[5], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d)) x.Started = d;
                    if (double.TryParse(a[6], NumberStyles.Float, CultureInfo.InvariantCulture, out v)) x.Cost = v;
                    list.Add(x); by[x.Account] = x;
                }
                else if (a[0] == "PAY" && a.Length >= 4 && by.ContainsKey(a[1]) && DateTime.TryParseExact(a[2], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d) && double.TryParse(a[3], NumberStyles.Float, CultureInfo.InvariantCulture, out v))
                    by[a[1]].Payouts.Add(Tuple.Create(d, v));
                else if (a[0] == "EXP" && a.Length >= 4 && by.ContainsKey(a[1]) && DateTime.TryParseExact(a[2], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d) && double.TryParse(a[3], NumberStyles.Float, CultureInfo.InvariantCulture, out v))
                    by[a[1]].Expenses.Add(Tuple.Create(d, v, a.Length >= 5 ? a[4] : "cost"));
                else if (a[0] == "STA" && a.Length >= 7 && by.ContainsKey(a[1]))
                {
                    var x = by[a[1]]; if (DateTime.TryParseExact(a[2], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d)) x.FundedOn = d;
                    double.TryParse(a[3], NumberStyles.Float, CultureInfo.InvariantCulture, out x.FundedPeak); double.TryParse(a[4], NumberStyles.Float, CultureInfo.InvariantCulture, out x.PeakBal);
                    double.TryParse(a[5], NumberStyles.Float, CultureInfo.InvariantCulture, out x.LowBal); double.TryParse(a[6], NumberStyles.Float, CultureInfo.InvariantCulture, out x.MaxDd);
                    if (a.Length >= 8 && (a[7] == "INTRADAY" || a[7] == "EOD")) x.FundedDd = a[7]; if (a.Length >= 9) x.AutoChecked = a[8] == "1";
                }
            }
            return list;
        }
        // the account's numbers from its daily closes and its journal rows (account,symbol,side,qty,entry_time,entry,exit_time,exit,points,net,…)
        public static KeystonePoolStats Stats(KeystoneAccountWatch w, IEnumerable<string[]> journal)
        {
            var st = new KeystonePoolStats();
            if (w != null && w.Closes.Count > 0) { var dp = w.DayProfits(); st.Days = dp.Count(x => Math.Abs(x) > 0.005); st.LastBalance = w.Closes.Values.Last(); st.Pnl = st.LastBalance - w.StartBalance; st.BestDayPct = w.ConsistencyPct(); }
            foreach (var r in journal ?? new List<string[]>())
            {
                double net; if (r.Length < 10 || !double.TryParse(r[9], NumberStyles.Float, CultureInfo.InvariantCulture, out net)) continue;
                st.Trades++; if (net > 0) st.Wins++;
            }
            return st;
        }
    }

    // ---- LIVE TRADING tools: level fade (NEAR mode), missing-minute finder + merge (refill after a disconnect), day locks ----
    public static class KeystoneLiveTools
    {
        // a level line's opacity: OFF 0, ALWAYS 1, NEAR = fades in as price comes within `near` points (1 at the level)
        public const int Off = 0, Near = 1, Always = 2;
        public static double LevelOpacity(int mode, double price, double level, double near)
        {
            if (mode <= Off || double.IsNaN(level) || double.IsNaN(price)) return 0; if (mode >= Always) return 1;
            double d = Math.Abs(price - level); return near <= 0 || d >= near ? 0 : 1 - d / near;
        }
        // CME futures (NY time): open Sunday 18:00 → Friday 17:00, with the daily break 17:00 → 18:00
        public static bool MarketOpen(DateTime ny)
        {
            var d = ny.DayOfWeek; int m = ny.Hour * 60 + ny.Minute;
            if (d == DayOfWeek.Saturday) return false; if (d == DayOfWeek.Sunday) return m >= 18 * 60; if (d == DayOfWeek.Friday) return m < 17 * 60;
            return m < 17 * 60 || m >= 18 * 60;
        }
        // runs of at least `minMissing` minutes with the market open and no bar, between `from` and `to` (bar Time = its close)
        public static List<Tuple<DateTime, DateTime>> Gaps(IList<KeystoneArcBar> bars, DateTime from, DateTime to, int minMissing)
        {
            var output = new List<Tuple<DateTime, DateTime>>(); if (bars == null) return output;
            var have = new HashSet<DateTime>(bars.Where(b => b != null).Select(b => b.Time));
            DateTime start = new DateTime(from.Year, from.Month, from.Day, from.Hour, from.Minute, 0).AddMinutes(1), runStart = DateTime.MinValue; int run = 0;
            for (var t = start; t <= to; t = t.AddMinutes(1))
            {
                bool missing = MarketOpen(t.AddMinutes(-1)) && !have.Contains(t);
                if (missing) { if (run == 0) runStart = t; run++; }
                else { if (run >= minMissing) output.Add(Tuple.Create(runStart, t.AddMinutes(-1))); run = 0; }
            }
            if (run >= minMissing) output.Add(Tuple.Create(runStart, to));
            return output;
        }
        // adds the bars whose minute is missing (keeps time order); returns how many were added
        public static int MergeBars(List<KeystoneArcBar> target, IEnumerable<KeystoneArcBar> add)
        {
            if (target == null || add == null) return 0; var have = new HashSet<DateTime>(target.Select(b => b.Time)); int n = 0;
            foreach (var b in add.Where(x => x != null).OrderBy(x => x.Time))
            {
                if (!have.Add(b.Time)) continue; n++;
                int i = target.Count; while (i > 0 && target[i - 1].Time > b.Time) i--; target.Insert(i, b);
            }
            return n;
        }
    }

    // LOCK FOR TODAY: an account refuses trading until the next session opens (18:00 NY; Friday → Sunday 18:00). Kept on disk.
    public sealed class KeystoneDayLocks
    {
        public readonly Dictionary<string, DateTime> Until = new Dictionary<string, DateTime>(StringComparer.OrdinalIgnoreCase);
        public static DateTime NextOpen(DateTime ny)
        {
            var t = ny.Date.AddHours(18); if (ny >= t) t = t.AddDays(1);
            while (t.DayOfWeek == DayOfWeek.Friday || t.DayOfWeek == DayOfWeek.Saturday) t = t.AddDays(1);   // Friday 18:00 is closed → Sunday
            return t;
        }
        // HARD = no unlock until the time (your choice when locking, and every NinjaTrader lockout); Why = who locked it
        public readonly HashSet<string> Hard = new HashSet<string>(StringComparer.OrdinalIgnoreCase); public readonly Dictionary<string, string> Why = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        public DateTime Lock(string account, DateTime ny) { var u = NextOpen(ny); Until[account ?? ""] = u; return u; }
        public DateTime Lock(string account, DateTime ny, bool hard, string why) { var u = Lock(account, ny); if (hard) Hard.Add(account ?? ""); else Hard.Remove(account ?? ""); Why[account ?? ""] = why ?? ""; return u; }
        // a lock to an exact time (a NinjaTrader lockout "locked until 5:00 PM"): always HARD
        public void LockUntil(string account, DateTime untilNy, string why) { Until[account ?? ""] = untilNy; Hard.Add(account ?? ""); Why[account ?? ""] = why ?? ""; }
        public bool CanUnlock(string account) { return !Hard.Contains(account ?? ""); }
        public bool Unlock(string account) { if (!CanUnlock(account)) return false; Until.Remove(account ?? ""); Why.Remove(account ?? ""); return true; }
        public bool IsLocked(string account, DateTime ny) { DateTime u; return account != null && Until.TryGetValue(account, out u) && ny < u; }
        public string Serialize() { return string.Join("\n", Until.Select(kv => kv.Key.Replace("|", "/") + "|" + kv.Value.ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture) + (Hard.Contains(kv.Key) ? "|H" : "|") + "|" + (Why.ContainsKey(kv.Key) ? Why[kv.Key].Replace("|", "/") : ""))); }
        public static KeystoneDayLocks Parse(string text)
        {
            var l = new KeystoneDayLocks();
            foreach (var line in (text ?? "").Split(new[] { '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries)) { var a = line.Split('|'); DateTime u; if (a.Length >= 2 && DateTime.TryParseExact(a[1], "yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture, DateTimeStyles.None, out u)) { l.Until[a[0]] = u; if (a.Length >= 3 && a[2] == "H") l.Hard.Add(a[0]); if (a.Length >= 4 && a[3] != "") l.Why[a[0]] = a[3]; } }
            return l;
        }
    }

    // ---- PROP FIRM RULES: presets for the accounts you trade (check them against the firm's dashboard; firms change rules) ----
    public sealed class KeystoneFirmPreset
    {
        // the firm's daily close (New York time): open positions are closed (or the account is breached) at this time; Zero = none.
        // FlatAuto = the firm closes them itself on normal days (holiday early closes: NOT — you must be flat yourself)
        public TimeSpan FlatBy = TimeSpan.Zero; public bool FlatAuto = true; public string FlatNote = "";
        public string Name = "", Firm = ""; public double Size, Dd, Target, ConsistencyPct, DayProfitCap, PayoutBuffer; public int MinDays, MaxMicros, MinHoldSeconds; public bool Automation = true, EodTrailing = true, NoNews; public string Notes = "";
    }
    // what a firm allows on YOUR accounts (LIVE TRADING ▸ 👥 ACCOUNTS ▸ step 4: your choice wins): automated strategies in the
    // evaluation / once funded, and copying between your own accounts — two different things (TPT: no automation once funded, copying OK)
    public sealed class KeystoneFirmPolicy { public bool AutoEval = true, AutoFunded = true, Copy = true; public string Note = ""; }
    public static class KeystoneFirmPolicies
    {
        public static readonly Dictionary<string, KeystoneFirmPolicy> Chosen = new Dictionary<string, KeystoneFirmPolicy>(StringComparer.OrdinalIgnoreCase);
        public static KeystoneFirmPolicy Default(string code)
        {
            switch ((code ?? "").Trim().ToUpperInvariant())
            {
                case "TPT": return new KeystoneFirmPolicy { AutoEval = false, AutoFunded = false, Copy = true, Note = "Take Profit Trader (the user's rule): no automation — in the evaluation and on funded (PRO) accounts the strategy only points (the buttons flash), you click; copying between your own TPT accounts is allowed. Switch it here if your plan allows it." };
                case "APEX": return new KeystoneFirmPolicy { AutoEval = true, AutoFunded = false, Copy = true, Note = "Apex: no fully automated trading on funded (PA) accounts; copying your own accounts is allowed. Check their current rules." };
                case "TOPSTEP": return new KeystoneFirmPolicy { Note = "Topstep: automated strategies and copying your own accounts are allowed. Check their current rules." };
                case "SIM": return new KeystoneFirmPolicy { Note = "Practice account: everything allowed." };
                case "LUCID": case "TRADEIFY": case "MFFU": case "BULENOX": case "ALPHA": case "ELITE": case "FUNDEDNEXT": case "TICKTICK":
                    return new KeystoneFirmPolicy { Note = "Not checked here — read the firm's rules page and switch automation off if they forbid it. Copying your own accounts is usually allowed." };
                default: return new KeystoneFirmPolicy { Note = "Unknown firm — read its rules page and set automation / copying here." };
            }
        }
        public static KeystoneFirmPolicy For(string code) { KeystoneFirmPolicy p; if (code != null && Chosen.TryGetValue(code.Trim(), out p)) { p.Note = Default(code).Note; return p; } return Default(code); }
        public static bool AutoAllowed(string code, bool funded) { var p = For(code); return funded ? p.AutoFunded : p.AutoEval; }
        public static bool ManualFor(string code, bool funded) { return !string.IsNullOrWhiteSpace(code) && !AutoAllowed(code, funded); }   /* 🧪 / 💰 labs: AUTO pauses for this firm and its buttons flash */
        public static bool CopyAllowed(string code) { return For(code).Copy; }
        public static string Serialize() { return string.Join("\n", Chosen.OrderBy(kv => kv.Key).Select(kv => kv.Key + "|" + (kv.Value.AutoEval ? 1 : 0) + "|" + (kv.Value.AutoFunded ? 1 : 0) + "|" + (kv.Value.Copy ? 1 : 0))); }
        public static void Parse(string text)
        {
            Chosen.Clear();
            foreach (var l in (text ?? "").Split('\n')) { var a = l.Trim().Split('|'); if (a.Length == 4 && a[0] != "") Chosen[a[0]] = new KeystoneFirmPolicy { AutoEval = a[1] == "1", AutoFunded = a[2] == "1", Copy = a[3] == "1" }; }
        }
    }
