        {
            Func<string, string> e = s => (s ?? string.Empty).Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;");
            Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            Func<double, string> c = v => v > 0 ? "#3fd28b" : (v < 0 ? "#ff6b6b" : "#9aa4b2");
            var sb = new StringBuilder();
            sb.Append("<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Keystone Prop Planner</title><style>")
              .Append("body{background:#0d1117;color:#e6edf3;font-family:Segoe UI,Arial,sans-serif;margin:0;padding:18px}h1{color:#f2c94c;margin:0 0 4px}h2{color:#56ccf2;margin:22px 0 6px}")
              .Append(".n{color:#9aa4b2;font-size:13px}.v{border:2px solid;border-radius:8px;padding:12px 14px;margin:12px 0;font-size:15px;font-weight:600}")
              .Append(".cards{display:flex;flex-wrap:wrap;gap:8px}.card{background:#161b22;border:1px solid #30363d;border-radius:8px;padding:8px 12px;min-width:150px}.card b{display:block;font-size:20px}")
              .Append("table{border-collapse:collapse;width:100%;font-size:13px}th{color:#f2c94c;text-align:left;border-bottom:1px solid #30363d;padding:5px}td{padding:5px;border-bottom:1px solid #21262d}.wrap{overflow-x:auto}</style></head><body>");
            sb.Append("<h1>SPASIX FUTURE • PROP PLANNER</h1><div class='n'>Historical research only • ").Append(DateTime.Now.ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture)).Append(" • days: ").Append(e(source)).Append("</div>");
            sb.Append("<p class='n'>").Append(e(x.Rules.Describe())).Append("<br>").Append(e(x.Plan.Describe())).Append("</p>");
            sb.Append("<div class='v' style='border-color:").Append(c(x.ValuePerEval)).Append("'>").Append(e(Verdict(x))).Append("</div>");
            if (x.Plan != null && x.Plan.Source == "BRACKET" && x.Plan.Bracket != null)
            {
                var bd = x.Plan.Bracket.Days.Where(d => d.Ok).ToList();
                sb.Append("<h2>THE RULE TO FOLLOW</h2><div class='n'>Tested on ").Append(bd.Count).Append(" trading days").Append(bd.Count > 0 ? " from " + bd.Min(d => d.Day).ToString("yyyy-MM-dd") + " to " + bd.Max(d => d.Day).ToString("yyyy-MM-dd") : "").Append(" • real 1-minute bars • stop counts first when a minute touches both</div><ol>");
                foreach (var step in KeystoneBracket.RuleSteps(x.Plan)) sb.Append("<li>").Append(e(step.Substring(step.IndexOf(' ') + 1))).Append("</li>");
                sb.Append("</ol>");
            }
            sb.Append("<div class='cards'>");
            foreach (var t in new[] { Tuple.Create("PASS RATE", x.PassRate.ToString("0.0") + "%"), Tuple.Create("DAYS TO PASS", x.AvgDaysToPass.ToString("0.0")), Tuple.Create("A FUNDED ACCOUNT PAYS", m(x.FundedValue)), Tuple.Create("PAYOUTS PER FUNDED", x.AvgPayouts.ToString("0.0")), Tuple.Create("VALUE OF ONE EVALUATION", m(x.ValuePerEval)), Tuple.Create("EVALUATIONS THAT LOSE MONEY", x.LosingShare.ToString("0") + "%"), Tuple.Create("FAILS IN A ROW (95%)", x.LongestFailStreak95.ToString()) })
                sb.Append("<div class='card'><span class='n'>").Append(t.Item1).Append("</span><b>").Append(e(t.Item2)).Append("</b></div>");
            sb.Append("</div>");
            if (programs != null && programs.Count > 0)
            {
                sb.Append("<h2>SEPARATE vs COPY vs ROTATION</h2><div class='wrap'><table><tr><th>HOW</th><th>ACCOUNTS</th><th>MONTHS</th><th>EVALS BOUGHT</th><th>PASSED</th><th>PAYOUTS</th><th>SPENT</th><th>RECEIVED</th><th>TYPICAL</th><th>BAD (1 IN 10)</th><th>GOOD (1 IN 10)</th><th>CHANCE OF LOSING</th><th>MONEY NEEDED</th></tr>");
                foreach (var p in programs)
                    sb.Append("<tr><td>").Append(p.Mode).Append("</td><td>").Append(p.Slots).Append("</td><td>").Append(p.MedianCurve.Count).Append("</td><td>").Append(p.AvgBought.ToString("0")).Append("</td><td>").Append(p.AvgPassed.ToString("0.0")).Append("</td><td>").Append(p.AvgPayouts.ToString("0.0")).Append("</td><td>").Append(m(p.AvgSpent)).Append("</td><td>").Append(m(p.AvgCash))
                      .Append("</td><td style='color:").Append(c(p.P50)).Append("'>").Append(m(p.P50)).Append("</td><td style='color:").Append(c(p.P10)).Append("'>").Append(m(p.P10)).Append("</td><td style='color:").Append(c(p.P90)).Append("'>").Append(m(p.P90)).Append("</td><td>").Append(p.NegativeChance.ToString("0")).Append("%</td><td>").Append(m(p.MoneyNeeded95)).Append("</td></tr>");
                sb.Append("</table></div>");
            }
            if (years != null && years.Count > 0)
            {
                sb.Append("<h2>HISTORY BY YEAR (one account slot walking the real days in order)</h2><div class='wrap'><table><tr><th>YEAR</th><th>EVALS BOUGHT</th><th>PASSED</th><th>PAYOUTS</th><th>FUNDED BLOWN</th><th>SPENT</th><th>RECEIVED</th><th>NET</th></tr>");
                foreach (var y in years) sb.Append("<tr><td>").Append(y.Year).Append("</td><td>").Append(y.Bought).Append("</td><td>").Append(y.Passed).Append("</td><td>").Append(y.Payouts).Append("</td><td>").Append(y.Blown).Append("</td><td>").Append(m(y.Spent)).Append("</td><td>").Append(m(y.Cash)).Append("</td><td style='color:").Append(c(y.Net)).Append("'>").Append(m(y.Net)).Append("</td></tr>");
                sb.Append("</table></div>");
            }
            if (proof != null && proof.Count > 0)
            {
                int held = proof.Count(t => t.Item2.ValuePerEval > 0);
                sb.Append("<h2>PROOF TEST • saved rules on data loaded now (").Append(e(proofRange)).Append(")</h2><div class='n'>").Append(held).Append(" of ").Append(proof.Count).Append(" rules stayed profitable. Found on ").Append(e(proof[0].Item1.FoundRange)).Append(KeystoneBracket.Overlaps(proof[0].Item1.FoundRange, proofRange) ? " — WARNING: the ranges overlap, this is not new data." : " — new data the rules never saw.").Append("</div><div class='wrap'><table><tr><th>#</th><th>RULE</th><th>FOUND: VALUE / EVAL</th><th>NOW: PASS</th><th>NOW: FUNDED PAYS</th><th>NOW: VALUE / EVAL</th><th>NOW: BY YEAR</th></tr>");
                foreach (var t in proof) sb.Append("<tr><td>").Append(t.Item1.Rank).Append("</td><td>").Append(e(t.Item2.Label)).Append("</td><td>").Append(m(t.Item1.FoundValue)).Append(" ").Append(e(t.Item1.FoundYears)).Append("</td><td>").Append(t.Item2.PassRate.ToString("0")).Append("%</td><td>").Append(m(t.Item2.FundedValue)).Append("</td><td style='color:").Append(c(t.Item2.ValuePerEval)).Append("'>").Append(m(t.Item2.ValuePerEval)).Append("</td><td style='color:").Append(t.Item2.EveryYear ? "#3fd28b" : "#ff6b6b").Append("'>").Append(e(t.Item2.YearText)).Append("</td></tr>");
                sb.Append("</table></div>");
            }
            if (sweet != null && sweet.Count > 0)
            {
                if (!string.IsNullOrEmpty(sweetRange)) sb.Append("<div class='n'>Sweet spot searched on ").Append(e(sweetRange)).Append(" • all ").Append(sweet.Count).Append(" plans</div>");
                sb.Append("<h2>SWEET SPOT • best plans first</h2><div class='wrap'><table><tr><th>#</th><th>PLAN</th><th>PASS</th><th>DAYS</th><th>FUNDED PAYS</th><th>VALUE / EVAL</th><th>LOSING EVALS</th><th>FAILS IN A ROW</th><th>BY YEAR</th></tr>");
                for (int i = 0; i < sweet.Count; i++) { var s = sweet[i]; sb.Append("<tr><td>").Append(i + 1).Append("</td><td>").Append(e(s.Label)).Append("</td><td>").Append(s.PassRate.ToString("0")).Append("%</td><td>").Append(s.AvgDaysToPass.ToString("0.0")).Append("</td><td>").Append(m(s.FundedValue)).Append("</td><td style='color:").Append(c(s.ValuePerEval)).Append("'>").Append(m(s.ValuePerEval)).Append("</td><td>").Append(s.LosingShare.ToString("0")).Append("%</td><td>").Append(s.LongestFailStreak95).Append("</td><td style='color:").Append(s.YearText.Length == 0 ? "#9aa4b2" : (s.EveryYear ? "#3fd28b" : "#ff6b6b")).Append("'>").Append(e(s.YearText.Length == 0 ? "—" : (s.EveryYear ? "✓ " : "✗ ") + s.YearText)).Append("</td></tr>"); }
                sb.Append("</table></div>");
            }
            sb.Append("<h2>HOW TO READ IT</h2><p class='n'>").Append(e(HowItWorks())).Append("</p></body></html>");
            return sb.ToString();
        }

        public static string HowItWorks()
        {
            return "Evaluations are the expense, payouts are the income. Each simulated evaluation is bought, traded day by day under the firm's rules (target, trailing drawdown that stops at the lock level, consistency, minimum days), and if it passes it becomes a funded account that is traded until it is lost or reaches the payout limit. Every 5 days of at least the qualifying profit pays the payout percent of the profit (up to the cap) and you keep your split. "
                 + "VALUE OF ONE EVALUATION = average cash received − average cost. Above zero the business makes money in the long run; below zero it loses no matter how many accounts you run. "
                 + "COIN FLIP means no strategy at all: a day ends at +target or −stop with the fair chance stop ÷ (target + stop) — the pure prop-firm math (the famous 32.65% for 2 days of +1,500 / −2,000). REAL days come from a strategy run (RECOIL) and are drawn at random from its history. REAL BRACKET replays one bracket trade a day (entry time, direction rule, target and stop in points) on every loaded 1-minute day; when a minute touches both the target and the stop the stop counts first, and days without the exact entry minute are skipped. The SWEET SPOT checks every rule year by year: a rule that only works in one year is luck, a rule that is positive in every year is a candidate. "
                 + "SEPARATE = every account trades its own days (diversified). COPY = every account takes the same trades (the same result × accounts: bigger swings, same value per evaluation). ROTATION = one stream of trades shared by the accounts in turn. MONEY NEEDED = the deepest the cash went in 19 of 20 simulations — have that much ready. Limits: an evaluation is dropped after 150 trading days and a funded account is retired after 250 (about a year), so a strong strategy's funded value is a one-year value.";
        }
    }

    // ---- INSTRUMENTS: the studio's symbols beyond MNQ / MGC (added from NinjaTrader with the + tab) ----------------------
    // MNQ and MGC keep their built-in values; an added symbol carries NinjaTrader's point value and tick size, a commission per
    // side and its type (FUTURE • FOREX • STOCK • CFD • INDEX …). Kept on disk (Studio\Instruments.txt).
    public sealed class KeystoneSymbolSpec
    {
        public string Symbol = string.Empty, Name = string.Empty, Type = "FUTURE";
        public double PointValue = 1, TickSize = 0.01, Commission = 0;   // commission per contract per side
        public int FullDayMinutes = 800;                                  // a complete day has at least this many 1-minute bars
        public bool Futures { get { return string.Equals(Type, "FUTURE", StringComparison.OrdinalIgnoreCase); } }
        public double CostPerContract { get { return 2 * Commission + TickSize * PointValue; } }   // round trip + 1 tick, like MNQ / MGC
    }
    public static class KeystoneSymbols
    {
        static readonly Dictionary<string, KeystoneSymbolSpec> specs = new Dictionary<string, KeystoneSymbolSpec>(StringComparer.OrdinalIgnoreCase);
        public static bool Builtin(string s) { return string.Equals(s, "MNQ", StringComparison.OrdinalIgnoreCase) || string.Equals(s, "MGC", StringComparison.OrdinalIgnoreCase); }
        public static bool Register(KeystoneSymbolSpec s)
        {
            if (s == null || string.IsNullOrWhiteSpace(s.Symbol) || Builtin(s.Symbol) || s.PointValue <= 0 || s.TickSize <= 0) return false;
            s.Symbol = s.Symbol.Trim().ToUpperInvariant(); lock (specs) specs[s.Symbol] = s; return true;
        }
        public static void Remove(string s) { lock (specs) specs.Remove(s ?? string.Empty); }
        public static KeystoneSymbolSpec Get(string s) { if (string.IsNullOrEmpty(s) || Builtin(s)) return null; lock (specs) { KeystoneSymbolSpec x; return specs.TryGetValue(s, out x) ? x : null; } }
        public static List<KeystoneSymbolSpec> All() { lock (specs) return specs.Values.OrderBy(x => x.Symbol).ToList(); }
        public static string Serialize(IEnumerable<KeystoneSymbolSpec> list)
        {
            Func<string, string> c = x => (x ?? string.Empty).Replace("|", "/").Replace("\n", " ");
            return string.Join("\n", (list ?? new List<KeystoneSymbolSpec>()).Select(s => string.Join("|", c(s.Symbol), c(s.Name), c(s.Type), s.PointValue.ToString(CultureInfo.InvariantCulture), s.TickSize.ToString(CultureInfo.InvariantCulture), s.Commission.ToString(CultureInfo.InvariantCulture), s.FullDayMinutes.ToString(CultureInfo.InvariantCulture))));
        }
        public static List<KeystoneSymbolSpec> Parse(string text)
        {
            var list = new List<KeystoneSymbolSpec>();
            foreach (var line in (text ?? string.Empty).Split(new[] { '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries))
            {
                var a = line.Split('|'); if (a.Length < 6) continue; double pv, tk, cm; int fd = 800;
                if (!double.TryParse(a[3], NumberStyles.Float, CultureInfo.InvariantCulture, out pv) || !double.TryParse(a[4], NumberStyles.Float, CultureInfo.InvariantCulture, out tk) || !double.TryParse(a[5], NumberStyles.Float, CultureInfo.InvariantCulture, out cm)) continue;
                if (a.Length > 6) int.TryParse(a[6], NumberStyles.Integer, CultureInfo.InvariantCulture, out fd);
                if (pv <= 0 || tk <= 0 || Builtin(a[0])) continue;
                list.Add(new KeystoneSymbolSpec { Symbol = a[0].Trim().ToUpperInvariant(), Name = a[1], Type = a[2], PointValue = pv, TickSize = tk, Commission = Math.Max(0, cm), FullDayMinutes = Math.Max(30, fd) });
            }
            return list;
        }
        // NinjaTrader's instrument type name → ours
        public static string TypeName(string ninjaType)
        {
            string t = (ninjaType ?? string.Empty).ToUpperInvariant();
            if (t.Contains("FUTURE")) return "FUTURE"; if (t.Contains("FOREX") || t.Contains("CURRENCY")) return "FOREX"; if (t.Contains("STOCK") || t.Contains("EQUITY")) return "STOCK";
            if (t.Contains("CFD")) return "CFD"; if (t.Contains("INDEX")) return "INDEX"; if (t.Contains("CRYPTO")) return "CRYPTO"; if (t.Contains("OPTION")) return "OPTION";
            return t == string.Empty ? "FUTURE" : t;
        }
        // a sensible commission per side and the minutes of a complete day for a new instrument
        public static double DefaultCommission(string type, double pointValue) { return type == "FUTURE" ? (pointValue <= 10 ? 0.62 : 2.25) : 0; }
        public static int DefaultFullDay(string type) { return type == "STOCK" ? 300 : type == "INDEX" ? 300 : 800; }
    }

    // ---- PROP SIMULATION (Backtest Studio) ------------------------------------------------------------------------------
    // N evaluation accounts traded day after day on the studio's replay. One account trades at a time (round robin); every
    // trade (from flat back to flat) is booked to the account that opened it. At the close the firm's rules move each account:
    // EVALUATION → FUNDED (target, minimum days, consistency, hold-time rule) → payouts (qualifying days, % of the profit, cap,
    // buffer, split; max payouts → RETIRED) — or BLOWN the moment its equity (open trades included) touches the drawdown floor.
    // Blown evaluations (and passed ones, if chosen) are replaced by new purchases. Everything is written to
    // Studio\PropSim\<run>\ as the days go by.
    public sealed class KeystoneSimRules
    {
        public string Name = "LUCID FLEX 50K";
        // EVALUATION
        public double EvalCost = 120, Target = 3000, EvalDrawdown = 2000, EvalLockAt = 100, EvalConsistency = 50, EvalDailyLoss = 0; public string EvalDdType = "EOD"; public int EvalMinDays = 2;
        // FUNDED
        public double Activation = 0, FundDrawdown = 2000, FundLockAt = 100, FundDailyLoss = 0; public string FundDdType = "EOD";
        // PAYOUTS (funded): after PayoutDays days of ≥ QualifyingDay (since the last payout), PayoutPercent of the balance above
        // PayoutBuffer, at most PayoutCap, at least PayoutMin; you keep Split %. PayoutConsistency: best day ≤ this % of the profit
        // since the last payout (0 = none). MaxPayouts reached → the account is RETIRED (moved on by the firm).
        public int PayoutDays = 5, MaxPayouts = 5; public double QualifyingDay = 150, PayoutConsistency = 0, PayoutPercent = 50, PayoutCap = 2000, PayoutMin = 0, PayoutBuffer = 0, Split = 90;
        // TRADING RULES: MinHoldSeconds (Lucid 11 s): at least MinHoldShare % of the profit from trades held longer (checked at a
        // pass / payout; the rotation never takes a target sooner) • MaxMicros (MNQ + MGC together) • flat by HHMM (New York) •
        // Automation = the firm allows automated trading (TPT: no)
        public int MinHoldSeconds = 0, MaxMicros = 40, FlatByHhmm = 1645; public double MinHoldShare = 50; public bool Automation = true;
        public bool HoldFundedOnly = true;   // the minimum hold (micro-scalping rule) only on FUNDED accounts (evaluations trade freely)
        public KeystoneSimRules Copy() { return (KeystoneSimRules)MemberwiseClone(); }
        public static List<KeystoneSimRules> Presets()
        {
            return new List<KeystoneSimRules>
            {
                new KeystoneSimRules { Name = "GENERIC PROP 50K", EvalCost = 100, Target = 3000, EvalDrawdown = 2000, EvalConsistency = 50, EvalMinDays = 2, FundDrawdown = 2000, PayoutDays = 5, QualifyingDay = 150, PayoutPercent = 50, PayoutCap = 2000, Split = 90, MaxPayouts = 0, MinHoldSeconds = 0, MaxMicros = 40, FlatByHhmm = 1655 },
                new KeystoneSimRules { Name = "LUCID FLEX 50K", EvalCost = 120, Target = 3000, EvalDrawdown = 2000, EvalConsistency = 50, EvalMinDays = 2, FundDrawdown = 2000, PayoutDays = 5, QualifyingDay = 150, PayoutPercent = 50, PayoutCap = 2000, Split = 90, MaxPayouts = 5, MinHoldSeconds = 11, MaxMicros = 40, FlatByHhmm = 1645 },
                new KeystoneSimRules { Name = "TRADEIFY SELECT 50K", EvalCost = 99, Target = 3000, EvalDrawdown = 2000, EvalConsistency = 40, EvalMinDays = 3, FundDrawdown = 2000, PayoutDays = 5, QualifyingDay = 150, PayoutPercent = 50, PayoutCap = 2500, Split = 90, MaxPayouts = 0, MaxMicros = 40, FlatByHhmm = 1659 },
                new KeystoneSimRules { Name = "TAKE PROFIT TRADER 50K", EvalCost = 170, Activation = 130, Target = 3000, EvalDrawdown = 2000, EvalConsistency = 50, EvalMinDays = 3, FundDrawdown = 2000, FundDdType = "INTRADAY", FundLockAt = 0, PayoutDays = 1, QualifyingDay = 0, PayoutPercent = 100, PayoutCap = 10000, PayoutMin = 250, PayoutBuffer = 2000, Split = 80, MaxPayouts = 0, MaxMicros = 60, FlatByHhmm = 1655, Automation = false },
                new KeystoneSimRules { Name = "MFFU RAPID 50K", EvalCost = 107, Target = 3000, EvalDrawdown = 2000, EvalConsistency = 30, EvalMinDays = 2, FundDrawdown = 2000, PayoutDays = 1, QualifyingDay = 0, PayoutPercent = 100, PayoutCap = 0, PayoutMin = 500, PayoutBuffer = 1600, Split = 90, MaxPayouts = 0, MaxMicros = 30, FlatByHhmm = 1610 },
                // 25K accounts (the numbers you gave: target $1,500, best day ≤ 50% = $750, payout cap $1,500) — CHECK the drawdown / price on the firm's site
                new KeystoneSimRules { Name = "25K • TARGET 1,500 • CAP 1,500 (check)", EvalCost = 90, Target = 1500, EvalDrawdown = 1250, EvalConsistency = 50, EvalMinDays = 2, FundDrawdown = 1250, PayoutDays = 5, QualifyingDay = 100, PayoutPercent = 50, PayoutCap = 1500, Split = 90, MaxPayouts = 5, MaxMicros = 20, FlatByHhmm = 1645 },
                new KeystoneSimRules { Name = "TAKE PROFIT TRADER 25K (check)", EvalCost = 150, Activation = 130, Target = 1500, EvalDrawdown = 1500, EvalConsistency = 50, EvalMinDays = 3, FundDrawdown = 1500, FundDdType = "INTRADAY", FundLockAt = 0, PayoutDays = 1, QualifyingDay = 0, PayoutPercent = 100, PayoutCap = 10000, PayoutMin = 250, PayoutBuffer = 1500, Split = 80, MaxPayouts = 0, MaxMicros = 30, FlatByHhmm = 1655, Automation = false },
                new KeystoneSimRules { Name = "CUSTOM" },
            };
        }
        public string Describe()
        {
            Func<double, string> m = v => "$" + v.ToString("N0", CultureInfo.InvariantCulture);
            return Name + " • evaluation " + m(EvalCost) + " → +" + m(Target) + " (drawdown " + m(EvalDrawdown) + " " + EvalDdType + (EvalConsistency > 0 ? ", best day ≤ " + EvalConsistency.ToString("0") + "%" : "") + ", ≥ " + EvalMinDays + " days)"
                + " • funded" + (Activation > 0 ? " (activation " + m(Activation) + ")" : "") + ": drawdown " + m(FundDrawdown) + " " + FundDdType
                + " • payout after " + PayoutDays + " day(s)" + (QualifyingDay > 0 ? " of ≥ " + m(QualifyingDay) : "") + ": " + PayoutPercent.ToString("0") + "%" + (PayoutBuffer > 0 ? " above " + m(PayoutBuffer) : "") + (PayoutCap > 0 ? " up to " + m(PayoutCap) : "") + (PayoutMin > 0 ? ", min " + m(PayoutMin) : "") + ", you keep " + Split.ToString("0") + "%" + (MaxPayouts > 0 ? ", max " + MaxPayouts : "")
                + (MinHoldSeconds > 0 ? " • " + MinHoldSeconds + "-second rule" : "") + " • max " + MaxMicros + " micros • flat by " + (FlatByHhmm / 100).ToString("00") + ":" + (FlatByHhmm % 100).ToString("00");
        }
    }

    public sealed class KeystoneSimSettings
    {
        public string Strategy = "ROTATION";     // ROTATION (random MNQ + MGC rotation) • STUDIO (a studio strategy, e.g. ASIAN 75 REVERSAL LEGS) • MANUAL (no strategy, you trade)
        public int Signal = 0;                    // STUDIO: the studio strategy (KeystoneReplaySignals.Names index; 0 = the one chosen in the studio)
        public bool Auto = true;                  // AUTO = the strategy / rotation enters by itself • false = I TRADE (its setup is shown, I click; exits still managed)
        // each account's day: NONE = keep trading (the limits decide) • ONEWIN = it stops after its first win (−500, −500, +1,500 = +500 locked)
        // • RECOVER = every trade aims to end the day at +target (after −500 the next one aims at +2,000), locked when reached
        public string DayPlan = "ONEWIN";
        // funded accounts may trade gentler: their own day plan (SAME = as the evaluations) and max trades a day (0 = as the evaluations)
        public string FundDayPlan = "SAME"; public int FundMaxTrades = 0;
        // WITH = funded accounts trade alongside the evaluations • AFTER = they wait until every evaluation is done (passed or blown)
        // ASK (default, PASS FIRST) = passed accounts wait in the funded pool until every evaluation has passed or blown, then you choose
        // how to trade them • AFTER = they start by themselves then • WITH = they trade alongside the evaluations
        // STAGES (default) = the simple plan: the evaluations trade until every one passed or blew; then the passed ones trade FUNDED by
        // themselves with the funded settings you chose; when every funded account is blown / retired, the next batch is bought
        public string FundedWhen = "STAGES";
        // START AS: EVAL = buy evaluations (pass → funded) • FUNDED = test only the funded stage: every account starts funded
        // (it costs the evaluation fee + activation, as if it had passed), so the funded plan can be judged on its own
        public string StartAs = "EVAL";
        public static readonly string[][] StartAsList = { new[] { "EVAL", "EVALUATIONS (buy evals → pass → funded)" }, new[] { "FUNDED", "FUNDED ONLY (test the funded stage: every account starts funded)" } };
        // CUSHION: once a funded balance reaches FundCushion (e.g. 4,000 = 1,500 + 1,500 + 1,000) its day target drops to
        // FundCushionTarget (e.g. 200: just a qualifying day) until the payout takes it back under (0 = off)
        public double FundCushion = 0, FundCushionTarget = 200;
        public bool Cushioned(KeystoneSimAccount a) { return a != null && a.Funded && FundCushion > 0 && a.Bal >= FundCushion - 1e-9; }
        public double DayGoalOf(KeystoneSimAccount a) { return Cushioned(a) ? FundCushionTarget : AcctDayTarget > 0 ? AcctDayTarget : Strategy == "ROTATION" ? (a != null && a.Funded ? FundRotTarget : RotTarget) : 0; }
        public static readonly string[][] FundedWhens = { new[] { "STAGES", "SIMPLE: EVALS FIRST → THEN THE PASSED ONES FUNDED (my funded settings) → THEN THE NEXT BATCH" }, new[] { "ASK", "PASS FIRST: THEY WAIT, THEN I CHOOSE (when every evaluation is done)" }, new[] { "AFTER", "BY THEMSELVES WHEN EVERY EVALUATION IS DONE" }, new[] { "WITH", "TOGETHER WITH THE EVALUATIONS" } };
        public static readonly string[][] FundDayPlans = { new[] { "SAME", "SAME AS THE EVALUATIONS" }, new[] { "ONEWIN", "ONE WIN A DAY" }, new[] { "RECOVER", "FULL RECOVERY" }, new[] { "NONE", "UNTIL THE DAY TARGET" } };
        public string PlanOf(bool funded) { return funded && FundDayPlan != "SAME" && !string.IsNullOrEmpty(FundDayPlan) ? FundDayPlan : DayPlan; }
        public int MaxTradesOf(bool funded) { return funded && FundMaxTrades > 0 ? FundMaxTrades : MaxTradesPerDay; }
        public bool DataOnly = false;             // run without drawing the charts (fastest; the PROP POOL shows the run)
        // after the day's CLOSE ALL (EndHhmm): the next day starts at the trading hours (HOURS: no waiting through the hours in
        // between) or at 18:00, the new session (1800). A 15-second prompt offers both when you watch; it picks this one.
        public string NextDay = "HOURS";
        public static readonly string[][] NextDays = { new[] { "HOURS", "AT MY HOURS (skip the time in between)" }, new[] { "1800", "AT 18:00 • THE NEW SESSION (watch it all)" } };
        public static readonly string[][] DayPlans = { new[] { "NONE", "UNTIL THE DAY TARGET (then locked)" }, new[] { "ONEWIN", "ONE WIN A DAY: stop after the first win" }, new[] { "RECOVER", "FULL RECOVERY: every trade aims at +target for the day" } };
        public static string DayPlanName(string code) { var d = DayPlans.FirstOrDefault(x => x[0] == code); return d == null ? code : d[1]; }
        // STUDIO / MANUAL (e.g. 1M FVG on MNQ and MGC): 1 = every setup gets its own account — MNQ and MGC each rotate through the
        // accounts, one setup per account per instrument a day • 2 = one account may hold an MNQ and an MGC setup at the same time
        public int SetupsPerAccount = 1;
        // PROP FIRMS (optional): name : evaluations : cost : target : drawdown : trailing (EOD / INTRADAY / STATIC) : stops trailing at : consistency % : min days : daily loss
        // per firm, ";" between firms • "" = one firm with the rules below and ACCOUNTS evaluations. The rotation takes them firm by firm.
        public string Firms = string.Empty;
        // ACCOUNTS: ROTATE = one account takes a trade, the next one the next trade (or day) • COPY = COPY TRADING: every account that
        // may trade when the trade starts takes the same trade (its own contracts, drawdown, locks, passes, payouts)
        public string Allocation = "ROTATE";
        public static readonly string[][] Allocations = { new[] { "ROTATE", "ROTATE: ONE ACCOUNT A TRADE, THEN THE NEXT" }, new[] { "COPY", "COPY TRADING: EVERY ACCOUNT TAKES EVERY TRADE" } };
        public int Accounts = 10; public bool ReplacePassed = true; public string RotateBy = "TRADE";   // MANUAL / STUDIO: the next account after every trade, or every DAY
        // new evaluations (a blown / passed one replaced): BREAKEVEN = the first ones are the whole budget — no new one until the
        // payouts have paid back everything spent, then the pool is refilled • ALWAYS = keep the account count (buy at once)
        public string BuyRule = "BATCH";
        public static readonly string[][] BuyRules = { new[] { "BATCH", "A NEW BATCH BY ITSELF: when every evaluation has passed or blown, the next day starts with new ones (the batch is saved)" }, new[] { "BREAKEVEN", "ONLY WHEN THE PAYOUTS HAVE PAID BACK ALL THAT WAS SPENT (then refill)" }, new[] { "ALWAYS", "ALWAYS: KEEP THE ACCOUNT COUNT (buy at once)" } };
        public DateTime From = DateTime.Today.AddMonths(-1), To = DateTime.Today;
        // ROTATION: MNQ and MGC each bought or sold (KeystoneSimRotation.Directions), one combined $ target and stop
        public string Indicator = string.Empty;  // INDICATOR sides: the 📡 entry indicator this run trades (KeystoneEntryIndicator.ToText, one line)
        public string Direction = "RANDOM";     // INDICATOR • RANDOM • RANDOM4 • RANDOMHEDGE • CYCLE4 • BUY • SELL • BS • SB • FOLLOW5 • FADE5 • FOLLOW5EACH • FADE5EACH
        public int MnqQty = 2, MgcQty = 2, FundMnqQty = 2, FundMgcQty = 2;
        // the default rotation: ONE trade a day per account, +1,500 or −500 (funded the same) — change it in the set-up, ⚖ COMPARE shows the others
        public double RotTarget = 1500, RotStop = 500, FundRotTarget = 1500, FundRotStop = 500, BreakevenAt = 0; public string LockTiers = string.Empty;
        // TRAILING STOP (on by default): the trade's stop follows its highest open P/L, always its stop $ below it — −$500 stop, peak +$635
        // → the stop is +$135 (it only moves up, never back down)
        public bool AskEachBatch = false;   // EVAL TEST: a finished batch waits for the choice — 💜 FUNDED STAGE (the passed ones trade to their payout, no new evaluations meanwhile) or 🔄 a NEW BATCH
        public bool TrailStop = false;   // OPTIONAL (user's request): the trade's stop stays where it was set unless this is ticked
        public bool AltInstrument = false;   // 🧪 EVAL LAB: ALTERNATE MNQ / MGC — rotation 1 trades only MNQ, rotation 2 only MGC, … (each with its own contracts)
        // AUTO with THE ENTRY INDICATOR: it waits for a setup; once the PAUSE is over and no setup (and no click) came, AUTO enters
        // this side by itself (WAIT = keep waiting for the indicator)
        public string AutoFallback = "BUY";
        public int PauseSeconds = 60, StartHhmm = 930, EndHhmm = 1555, MaxLossesPerDay = 0, MaxTradesPerDay = 1; public double AcctDayTarget = 0, AcctDayStop = 0;
        // 🧪 EVAL LAB ⚡ ALL AT ONCE: every alive account opens at the start time each day (one trade a day, held to +target / its stop or floor / the close)
        // AllSide: FIRM = each firm of the pool its own coin a day (no opposite positions inside a firm) • EACH = every account its own coin (opposite
        // positions inside a firm = hedging, most firms forbid it) • ALL = one coin for every account (all-or-nothing) • BUY / SELL = always
        public bool AllAtOnce = false; public string AllSide = "FIRM";
        // ⚡ STAGGERED (with AllAtOnce): every alive account trades every day, spread over 5 entry times (≈ 6 accounts each, by account number), one side per firm per time
        public bool Stagger = false; public int[] StaggerTimes = { 200, 830, 930, 1000, 1100 };
        // 🩹 SAME-DAY RECOVERY: after a stopped loss that left room, one more trade the same day from the next minute risking the room left (target $, side SAME / FLIP)
        public double RecTarget = 0; public string RecSide = "NONE";
        public int MinHoldSec = 0;   // 🧪 EVAL LAB: MIN TIME IN TRADE (s) — a take profit can't close before it (1-minute data: whole minutes, never in the entry minute); the floor is never delayed
        public int Seed = 7;
        public int SetupVersion = 5;   // 3 = PASS FIRST + the built-in 📡 indicator on the whole day (older saved set-ups get it once)
        // an account whose room to its floor (after the fees) is under this share of its normal stop can no longer carry a trade:
        // it is RETIRED "at the floor" (instead of being locked again every day and never trading) — 0 = keep locking it
        public double MinRoomShare = 0.25;              // 2 = the default rotation is one trade a day, +1,500 / −500 (older saved set-ups get it once)
        public KeystoneSimRules Rules = new KeystoneSimRules();
        public KeystoneSimSettings Copy() { var c = (KeystoneSimSettings)MemberwiseClone(); c.Rules = Rules.Copy(); return c; }
        public List<Tuple<double, double>> Tiers() { return new KeystoneRotationConfig { LockTiers = LockTiers }.Tiers(); }
        public string Describe()
        {
            Func<double, string> m = v => "$" + v.ToString("N0", CultureInfo.InvariantCulture);
            string how = Auto ? "AUTO" : "I TRADE";
            string strat = Strategy == "ROTATION" ? "ROTATION (" + how + ") " + KeystoneSimRotation.DirectionName(Direction) + " • " + MnqQty + " MNQ + " + MgcQty + " MGC (funded " + FundMnqQty + " + " + FundMgcQty + ") • +" + m(RotTarget) + " / −" + m(RotStop) + (BreakevenAt > 0 ? " • BE at +" + m(BreakevenAt) : "") + (FundCushion > 0 ? " • funded cushion: from +" + m(FundCushion) + " only +" + m(FundCushionTarget) + "/day" : "") + (FundDayPlan != "SAME" || FundMaxTrades > 0 ? " • funded: " + (FundDayPlan != "SAME" ? DayPlanName(FundDayPlan).Split(':')[0] : "") + (FundMaxTrades > 0 ? " max " + FundMaxTrades + " trade(s)/day" : "") : "") + (LockTiers != "" ? " • locks " + LockTiers : "") + " • " + KeystoneBracket.Hm(StartHhmm) + "–" + KeystoneBracket.Hm(EndHhmm)
                : Strategy == "MANUAL" ? "MANUAL (you trade, no strategy) • next account after every " + (RotateBy == "DAY" ? "day" : "trade") + " • " + KeystoneBracket.Hm(StartHhmm) + "–" + KeystoneBracket.Hm(EndHhmm)
                : (Signal > 0 && Signal < KeystoneReplaySignals.Names.Length ? KeystoneReplaySignals.Names[Signal] : "STUDIO STRATEGY") + " (" + how + ") • " + (SetupsPerAccount <= 1 ? "one setup per account: MNQ and MGC each rotate their accounts" : "next account after every " + (RotateBy == "DAY" ? "day" : "trade") + " (one account may hold both)") + " • " + KeystoneBracket.Hm(StartHhmm) + "–" + KeystoneBracket.Hm(EndHhmm);
            strat += " (close all)" + (NextDay == "1800" ? ", next day from 18:00" : "");
            if (Allocation == "COPY") strat = "📋 COPY TRADING (every account takes every trade) • " + strat;
            return Accounts + " accounts" + (BuyRule == "BREAKEVEN" ? " (new ones only after the payouts pay them back)" : "") + (StartAs == "FUNDED" ? " • FUNDED ONLY: every account starts funded (eval fee + activation)" : "") + (FundedWhen == "STAGES" && StartAs != "FUNDED" ? " • EVALS FIRST → then the passed ones funded → then the next batch" : "") + (FundedWhen == "ASK" ? " • PASS FIRST: passed accounts wait in the funded pool until every evaluation is done" : "") + (FundedWhen == "AFTER" ? " • funded trade only after every evaluation is done" : "") + " • " + From.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture) + " → " + To.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture) + " • " + strat + (DayPlan != "NONE" ? " • " + DayPlanName(DayPlan) : "");
        }
        // key=value lines (the rules as rules.<field>)
        public string ToText()
        {
            var lines = new List<string>();
            foreach (var f in typeof(KeystoneSimSettings).GetFields().Where(f => f.Name != "Rules")) lines.Add(f.Name + "=" + KeystoneSimText.Value(f.GetValue(this)));
            foreach (var f in typeof(KeystoneSimRules).GetFields()) lines.Add("rules." + f.Name + "=" + KeystoneSimText.Value(f.GetValue(Rules)));
            return string.Join("\n", lines);
        }
        public static KeystoneSimSettings FromText(string text)
        {
            var s = new KeystoneSimSettings();
            foreach (var line in (text ?? string.Empty).Split(new[] { '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries))
            {
                int k = line.IndexOf('='); if (k <= 0) continue; string key = line.Substring(0, k).Trim(), val = line.Substring(k + 1);
                if (key.StartsWith("rules.")) KeystoneSimText.Set(s.Rules, key.Substring(6), val); else KeystoneSimText.Set(s, key, val);
            }
            return s;
        }
    }

    public static class KeystoneSimText
    {
        public static string Value(object v)
        {
            if (v is DateTime) return ((DateTime)v).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
            if (v is double) return ((double)v).ToString(CultureInfo.InvariantCulture);
            if (v is bool) return (bool)v ? "1" : "0";
            return Convert.ToString(v, CultureInfo.InvariantCulture).Replace("\n", " ");
        }
        public static bool Set(object target, string field, string value)
        {
            if (target == null) return false; var f = target.GetType().GetField(field); if (f == null) return false; value = (value ?? string.Empty).Trim();
            try
            {
                if (f.FieldType == typeof(double)) { double d; if (!double.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out d)) return false; f.SetValue(target, d); }
                else if (f.FieldType == typeof(int)) { int i; if (!int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out i)) return false; f.SetValue(target, i); }
                else if (f.FieldType == typeof(bool)) f.SetValue(target, value == "1" || value.Equals("true", StringComparison.OrdinalIgnoreCase));
                else if (f.FieldType == typeof(DateTime)) { DateTime d; if (!DateTime.TryParseExact(value, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d)) return false; f.SetValue(target, d); }
                else if (f.FieldType == typeof(string)) f.SetValue(target, value);
                else return false;
                return true;
            }
            catch { return false; }
        }
    }

    public sealed class KeystoneSimFirm
    {
        public string Name = string.Empty, Code = string.Empty; public int Count; public KeystoneSimRules Rules;
        static string Clean(string x) { return (x ?? "").Replace(";", " ").Replace(":", " ").Replace("=", " ").Replace("\n", " ").Trim(); }
        public static string CodeOf(string name, int i)
        {
            var w = (name ?? "").ToUpperInvariant().Split(new[] { ' ', '-', '_', '.' }, StringSplitOptions.RemoveEmptyEntries).Where(x => x.Length > 0 && char.IsLetterOrDigit(x[0])).ToList();
            string c = w.Count >= 2 ? "" + w[0][0] + w[1][0] : w.Count == 1 ? (w[0].Length >= 2 ? w[0].Substring(0, 2) : w[0]) : ((char)('A' + i)).ToString();
            return c;
        }
        public string Line()
        {
            Func<double, string> d = v => v.ToString("0.##", CultureInfo.InvariantCulture); var r = Rules;
            return string.Join(":", Clean(Name), Count, d(r.EvalCost), d(r.Target), d(r.EvalDrawdown), r.EvalDdType, d(r.EvalLockAt), d(r.EvalConsistency), r.EvalMinDays, d(r.EvalDailyLoss));
        }
        public static string Text(IEnumerable<KeystoneSimFirm> firms) { return string.Join(";", firms.Select(f => f.Line())); }
        // the firms of a run (each with its own copy of the rules: the evaluation fields from its line, the rest from the run's rules)
        public static List<KeystoneSimFirm> Parse(string text, KeystoneSimRules baseRules, int accounts)
        {
            var list = new List<KeystoneSimFirm>();
            foreach (var part in (text ?? "").Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries))
            {
                var a = part.Split(':'); if (a.Length < 2 || a[0].Trim() == "") continue; var r = (baseRules ?? new KeystoneSimRules()).Copy();
                Func<int, double, double> D = (i, def) => { double v; return a.Length > i && double.TryParse(a[i], NumberStyles.Float, CultureInfo.InvariantCulture, out v) ? v : def; };
                int n; int.TryParse(a[1], out n);
                r.EvalCost = D(2, r.EvalCost); r.Target = D(3, r.Target); r.EvalDrawdown = D(4, r.EvalDrawdown); if (a.Length > 5 && (a[5] == "EOD" || a[5] == "INTRADAY" || a[5] == "STATIC")) r.EvalDdType = a[5];
                r.EvalLockAt = D(6, r.EvalLockAt); r.EvalConsistency = D(7, r.EvalConsistency); r.EvalMinDays = (int)D(8, r.EvalMinDays); r.EvalDailyLoss = D(9, r.EvalDailyLoss); r.Name = a[0].Trim();
                list.Add(new KeystoneSimFirm { Name = a[0].Trim(), Count = Math.Max(0, n), Rules = r });
            }
            // codes: two letters, unique
            var used = new HashSet<string>(); for (int i = 0; i < list.Count; i++) { string c = CodeOf(list[i].Name, i); string c0 = c; int k = 2; while (!used.Add(c)) c = c0 + (k++); list[i].Code = c; }
            if (list.Count == 0) list.Add(new KeystoneSimFirm { Name = (baseRules ?? new KeystoneSimRules()).Name, Code = "", Count = Math.Max(1, accounts), Rules = baseRules ?? new KeystoneSimRules() });
            return list;
        }
    }
    // ---- 🧪 EVAL LAB model (docs/redesign/EVAL_LAB_SPEC.md): pools of evaluation accounts by prop firm, the FIRM ROUND ROBIN,
    // plan templates. Pure data + text files (no UI): the window reads / writes them, the tests check them.
    public sealed class KeystoneEvalAccount { public string Firm = "", Nick = ""; public int Size = 50; public bool Archived; public DateTime StartOn = DateTime.MinValue; /* 💰 from the eval: the first funded session (the one after the pass; TPT after its day-3 trade) */ }
    public sealed class KeystoneEvalPool { public string Name = ""; public bool Simulated = true; public List<KeystoneEvalAccount> Accounts = new List<KeystoneEvalAccount>(); }
    public sealed class KeystoneEvalPlan
    {
        public string Name = "", Side = "BUY", Note = ""; public int Qm = 20, Qg = 0, Session = 3, Tries = 0, Pause = 0, MinHold = 0; public double Tp = 1500, Stop = 0, Be = 0; public bool AltInst, Preset;   /* Pause: s between rotations • MinHold: min s in a trade (0 = off) */
        public string Mode = "ROT", AllSide = "FIRM", RecSide = "NONE"; public double RecT = 0; public int DivN = 0; public double DayT = 0, DayS = 0;
        public int[] Times;   /* ⏱ BUILD 11f: the STAGGERED entry times (New York hhmm; null = 2:00 / 8:30 / 9:30 / 10:00 / 11:00) — the time presets A / B */   /* ➗ DIVIDED ROTATION (Tries 2): up to DivN trades a day, stop for the day at +DayT / −DayS */   /* ⚡ Mode ALL = every alive account at once • 🩹 RecT / RecSide = the same-day recovery */
        public string Summary()
        {
            Func<double, string> m = v => "$" + v.ToString("N0", CultureInfo.InvariantCulture);
            string inst = AltInst ? "ALTERNATE MNQ " + Qm + " / MGC " + Qg : Qm > 0 && Qg > 0 ? "MNQ " + Qm + " + MGC " + Qg : Qm > 0 ? "MNQ " + Qm : "MGC " + Qg;
            return (Mode == "STAG" ? "⚡ STAGGERED " + KeystoneLabFlow.TimesText(Times) + " (" + KeystoneEvalLab.AllSideName(AllSide) + ") • " : Mode == "ALL" ? "⚡ ALL AT ONCE" + (Session == 4 ? " 2:00 AM NY" : "") + " (" + KeystoneEvalLab.AllSideName(AllSide) + ") • " : "") + inst + " • +" + m(Tp) + " after costs • " + (Stop <= 0 ? "no stop (ride the full room)" : "stop −" + m(Stop)) + (RecSide != "NONE" && RecT > 0 ? " • 🩹 same-day recovery +" + m(RecT) + (RecSide == "FLIP" ? " flipped" : " same side") : "") + (Be > 0 ? " • breakeven at +" + m(Be) : "") + " • side " + KeystoneEvalLab.SideName(Side) + " • " + KeystoneEvalLab.SessionName(Session) + " • " + (Tries == 0 ? "1 trade a day per account" : "until +profit a day") + (Pause > 0 ? " • pause " + Pause + " s" : "") + (MinHold > 0 ? " • min hold " + MinHold + " s" : "");
        }
    }
    public static class KeystoneEvalLab
    {
        // the side rules and sessions as the Eval Lab shows them (codes shared with the ROTATE settings)
        public static readonly string[][] Sides = { new[] { "RANDOM", "🎲 RANDOM • BUY+BUY or SELL+SELL" }, new[] { "BUY", "▲▲ BUY • the next account keeps the side" }, new[] { "SELL", "▼▼ SELL • the next account keeps the side" }, new[] { "ORB30", "📐 NY 30-MIN OPENING RANGE BREAK" }, new[] { "LONDON", "🌍 LONDON CONTINUATION (3:00 → 9:30)" }, new[] { "ALTWIN", "🔁 FIRST BUY • after a WIN flip, after a loss keep" }, new[] { "ST15", "📈 SHORT-TERM TREND (last 15 min)" }, new[] { "MANUAL", "✋ NO STRATEGY • I decide each trade (replay)" } };
        public static readonly string[] Sessions = { "NEW YORK 9:30 – 11:30", "NEW YORK 8:00 – 12:00", "LONDON 2:00 – 11:00", "ALL DAY (flat by the firm's close)" };
        public static string SideName(string code) { var x = Sides.FirstOrDefault(a => a[0] == code); return x == null ? code : x[1]; }
        // ⚡ ALL AT ONCE: the sides (FIRM is the default: no opposite positions inside one firm)
        public static readonly string[][] AllSides = { new[] { "FIRM", "🏢 ONE SIDE PER FIRM (each firm its own coin a day)" }, new[] { "EACH", "🎲 OWN SIDE PER ACCOUNT (⚠ opposite positions inside a firm = hedging)" }, new[] { "ALL", "⚠ ONE SIDE FOR ALL (all-or-nothing)" }, new[] { "BUY", "▲ BUY ALL" }, new[] { "SELL", "▼ SELL ALL" } };
        public static string AllSideName(string code) { var x = AllSides.FirstOrDefault(a => a[0] == code); return x == null ? code : x[1]; }
        public static string AllSideWarning(string code) { return code == "EACH" ? "⚠ some accounts of the same firm buy while others sell at the same moment — most prop firms call that hedging between accounts and forbid it" : code == "ALL" ? "⚠ every account takes the same trade: a batch passes many or none (all-or-nothing)" : code == "FIRM" ? "each firm flips its own coin every day: all its accounts take that side (no opposite positions inside a firm)" : "every account takes this side every day"; }
        public static string SessionName(int i) { return i >= 0 && i < Sessions.Length ? Sessions[i] : Sessions[0]; }
        // a firm's evaluation by account size (the user's prop rules: EOD trailing, best day ≤ 50 %)
        public static double TargetOf(int size) { return size <= 25 ? 1500 : size <= 50 ? 3000 : size <= 100 ? 6000 : 9000; }
        public static double DrawdownOf(int size) { return size <= 25 ? 1500 : size <= 50 ? 2000 : size <= 100 ? 3000 : 4500; }
        // MIN TIME IN TRADE in whole minutes for the 1-minute engine: a take profit is never in the entry minute (≥ 1), 61 s → 2 minutes …
        public static int HoldMinutes(int sec) { return Math.Max(1, (int)Math.Ceiling(Math.Max(0, sec) / 60.0)); }
        // 🏢 each firm's evaluation from KeystoneFirmRules (the firm's plan of that size): target, drawdown, best-day %, minimum days
        // (TPT: 3 days = the extra day after passing; MFFU: best day ≤ 30 %) — firms without a plan use the size defaults (50 %, 2 days)
        public static void FirmRule(string firm, int size, out double target, out double dd, out double cons, out int minDays, out string why)
        {
            target = TargetOf(size); dd = DrawdownOf(size); cons = 50; minDays = 2; why = "size defaults (EOD, best day ≤ 50 %, 2 days)";
            string f = (firm ?? "").Trim().ToUpperInvariant(); string key = f == "TPT" ? "TAKE PROFIT TRADER" : f == "MFFU" ? "MYFUNDEDFUTURES" : f;
            var bk = KeystonePayoutRules.BookOf(f);
            if (bk != null && (bk.EvalTarget > 0 || bk.EvalDd > 0 || bk.EvalCons > 0 || bk.EvalMinDays > 0) && Math.Abs(bk.Size - size) <= 0.3 * size)
            {   /* 🏢 FIRMS & RULES: the rules you typed for this firm win */
                FirmRule(f + "\u0001", size, out target, out dd, out cons, out minDays, out why);   /* the plan's values first (the \u0001 key never matches the book) */
                if (bk.EvalTarget > 0) target = bk.EvalTarget; if (bk.EvalDd > 0) dd = bk.EvalDd; if (bk.EvalCons > 0) cons = bk.EvalCons; if (bk.EvalMinDays > 0) minDays = bk.EvalMinDays;
                why = "🏢 " + (bk.Name ?? f) + " (FIRMS & RULES): +" + target.ToString("N0", CultureInfo.InvariantCulture) + " • " + bk.EvalDdType + " " + dd.ToString("N0", CultureInfo.InvariantCulture) + " • best day ≤ " + cons.ToString("0", CultureInfo.InvariantCulture) + " % • " + minDays + " days"; return;
            }
            f = f.Replace("\u0001", ""); key = f == "TPT" ? "TAKE PROFIT TRADER" : f == "MFFU" ? "MYFUNDEDFUTURES" : f;
            var pr = KeystoneFirmRules.Presets.Where(x => string.Equals(x.Firm, key, StringComparison.OrdinalIgnoreCase) && x.Size > 0).OrderBy(x => Math.Abs(x.Size - size * 1000.0)).FirstOrDefault();
            if (pr == null || Math.Abs(pr.Size - size * 1000.0) > 0.3 * size * 1000.0) return;
            if (pr.Target > 0) target = pr.Target; if (pr.Dd > 0) dd = pr.Dd; if (pr.ConsistencyPct > 0) cons = pr.ConsistencyPct; minDays = Math.Max(2, pr.MinDays);
            why = pr.Name + ": +" + target.ToString("N0", CultureInfo.InvariantCulture) + " • EOD " + dd.ToString("N0", CultureInfo.InvariantCulture) + " • best day ≤ " + cons.ToString("0", CultureInfo.InvariantCulture) + " % • " + minDays + " days";
        }
        // THE FIRM ROUND ROBIN (hard rule): firm by firm — F1·1, F2·1, … Fn·1, F1·2 … — a firm with no account left drops out of the cycle
        public static List<KeystoneEvalAccount> RoundRobin(IEnumerable<KeystoneEvalAccount> accounts)
        {
            var live = (accounts ?? Enumerable.Empty<KeystoneEvalAccount>()).Where(a => a != null && !a.Archived).ToList();
            var firms = live.Select(a => a.Firm ?? "").Distinct().ToList(); var queues = firms.Select(f => new Queue<KeystoneEvalAccount>(live.Where(a => (a.Firm ?? "") == f))).ToList();
            var res = new List<KeystoneEvalAccount>(); bool any = true;
            while (any) { any = false; foreach (var q in queues) if (q.Count > 0) { res.Add(q.Dequeue()); any = true; } }
            return res;
        }
        // the engine's firms text (KeystoneSimFirm.Parse): one entry per firm + size, in the pool's firm order — the engine buys them
        // firm by firm (A, B, C, A …) and rotates by that order, so the run keeps the round robin
        public static string FirmsText(KeystoneEvalPool pool, KeystoneSimRules baseRules, double fee)
        {
            var live = pool == null ? new List<KeystoneEvalAccount>() : pool.Accounts.Where(a => !a.Archived).ToList(); var parts = new List<string>(); var r = baseRules ?? new KeystoneSimRules();
            foreach (var g in live.GroupBy(a => (a.Firm ?? "").Trim().ToUpperInvariant() + "|" + a.Size))
            {
                var a0 = g.First(); string nm = Clean(a0.Firm) + " " + a0.Size + "K"; Func<double, string> d = v => v.ToString("0.##", CultureInfo.InvariantCulture);
                double tg0, dd0, cs0; int md0; string why0; FirmRule(a0.Firm, a0.Size, out tg0, out dd0, out cs0, out md0, out why0);   /* 🏢 the firm's own evaluation rules */
                var bk0 = KeystonePayoutRules.BookOf(a0.Firm); double fee0 = bk0 != null && bk0.EvalPrice > 0 && (bk0.fromBookPrice) ? bk0.EvalCost : fee;   /* 🏢 the firm's own price (incl. the discount) when you set one */
                bool studio = bk0 != null && bk0.Studio;   /* 🎬 MFF STUDIO: STATIC drawdown, no minimum days (pass in one day), no consistency */
                parts.Add(string.Join(":", nm, g.Count(), d(fee0), d(tg0), d(dd0), studio ? "STATIC" : "EOD", d(r.EvalLockAt), d(studio ? 0 : cs0), studio ? Math.Max(1, md0) : Math.Max(md0, Math.Max(2, r.EvalMinDays)), d(0)));
            }
            return string.Join(";", parts);
        }
        static string Clean(string x) { return (x ?? "").Replace(";", " ").Replace(":", " ").Replace("|", " ").Replace("\n", " ").Trim(); }
        // pools.txt: POOL|name|1 (simulated) then ACC|firm|size|nick|0/1 (archived)
        public static string SavePools(IEnumerable<KeystoneEvalPool> pools)
        {
            var sb = new StringBuilder();
            foreach (var p in pools) { sb.AppendLine("POOL|" + Clean(p.Name) + "|" + (p.Simulated ? 1 : 0)); foreach (var a in p.Accounts) sb.AppendLine("ACC|" + Clean(a.Firm) + "|" + a.Size + "|" + Clean(a.Nick) + "|" + (a.Archived ? 1 : 0)); }
            return sb.ToString();
        }
        public static List<KeystoneEvalPool> LoadPools(string text)
        {
            var res = new List<KeystoneEvalPool>(); KeystoneEvalPool cur = null;
            foreach (var l in (text ?? "").Split('\n'))
            {
                var a = l.TrimEnd('\r').Split('|'); int n;
                if (a[0] == "POOL" && a.Length >= 3) { cur = new KeystoneEvalPool { Name = a[1], Simulated = a[2] == "1" }; res.Add(cur); }
                else if (a[0] == "ACC" && a.Length >= 5 && cur != null) cur.Accounts.Add(new KeystoneEvalAccount { Firm = a[1], Size = int.TryParse(a[2], out n) ? n : 50, Nick = a[3], Archived = a[4] == "1" });
            }
            return res;
        }
