    // ---- 🧪 EVAL LAB ⚡ CALCULATE + 🔮 HINDSIGHT (pure, no UI): one plan over a range in one go, the ranking of every plan / side on the
    // same days, and — HINDSIGHT, not tradeable — the side that would have reached +TP first at every rotation of the plan
    public sealed class KeystoneHindsight { public DateTime Day, Entry; public int Account, PlanIdx = -1, BestIdx = -1; public string Plan = "", Perfect = "", Wins = "", PlanHow = ""; public bool Match; public double PlanPnl; public int[] Out = new int[6]; }
    public sealed class KeystoneCalcRank { public string Plan = "", Side = ""; public int N, Passed, Blown, Live, Trades, Wins; public double AvgDays, FeePerPass, Pnl; public bool Mine, Hindsight; public KeystonePropSim Sim; }
    public static class KeystoneEvalCalc
    {
        public static readonly string[] SideNames = { "BUY BOTH", "SELL BOTH", "BUY MNQ", "SELL MNQ", "BUY MGC", "SELL MGC" };
        public static readonly int[][] SideDirs = { new[] { 1, 1 }, new[] { -1, -1 }, new[] { 1, 0 }, new[] { -1, 0 }, new[] { 0, 1 }, new[] { 0, -1 } };
        // the plan's bracket for a candidate: the take profit AFTER costs, the stop = the plan's (riding to the floor = the drawdown)
        public static void Bracket(KeystoneSimSettings s, int qM, int qG, out double target, out double stop)
        {
            double fees = qM * KeystoneRotationLab.CostMnq + qG * KeystoneRotationLab.CostMgc; target = s.RotTarget + fees;
            double dd = s.StartAs == "FUNDED" ? s.Rules.FundDrawdown : s.Rules.EvalDrawdown; if (dd <= 0) dd = 2000; stop = Math.Min(s.RotStop > 0 ? s.RotStop : dd, dd);
        }
        // each candidate side at (day, slot) with the plan's contracts: 1 = +TP first • −1 = the stop / floor first • 0 = neither by the end • −9 = no data / no contracts
        public static int[] Outcomes(KeystoneSimSettings s, KeystoneRotDay d, int k, int end, out double[] pnl, out int[] exits)
        {
            var res = new int[6]; pnl = new double[6]; exits = new int[6];
            for (int i = 0; i < 6; i++)
            {
                int qM = SideDirs[i][0] != 0 ? Math.Max(0, s.MnqQty) : 0, qG = SideDirs[i][1] != 0 ? Math.Max(0, s.MgcQty) : 0;
                bool bothSide = SideDirs[i][0] != 0 && SideDirs[i][1] != 0;   /* BUY / SELL BOTH needs contracts of both */
                if (qM + qG <= 0 || (bothSide && (qM == 0 || qG == 0))) { res[i] = -9; exits[i] = int.MaxValue; continue; }
                double tg, sl; Bracket(s, qM, qG, out tg, out sl); int how, xs; double pk, wr;
                pnl[i] = KeystoneRotationLab.Trade(d, k, end, SideDirs[i][0], SideDirs[i][1], qM, qG, tg, sl, 0, null, out how, out xs, out pk, out wr, false, KeystoneEvalLab.HoldMinutes(s.MinHoldSec));
                res[i] = how == 1 ? 1 : how == -9 ? -9 : how < 0 ? -1 : 0; exits[i] = how == -9 ? int.MaxValue : xs;
            }
            return res;
        }
        // the side that would have won: +TP first (the fastest of them), else the best $ — only sides the plan has contracts for
        public static int Best(int[] o, double[] pnl, int[] exits)
        {
            int b = -1; for (int i = 0; i < 6; i++) if (o[i] == 1 && (b < 0 || exits[i] < exits[b])) b = i;
            if (b >= 0) return b; for (int i = 0; i < 6; i++) if (o[i] != -9 && (b < 0 || pnl[i] > pnl[b])) b = i; return b;
        }
        // the plan's side from the trade's legs ("BUY 20 MNQ", "SELL 4 MNQ + SELL 4 MGC") → the index in SideNames, −1 = mixed sides
        public static int IndexOfLegs(string legs)
        {
            legs = legs ?? ""; bool m = legs.Contains("MNQ"), g = legs.Contains("MGC"); int dm = 0, dg = 0;
            foreach (var part in legs.Split('+')) { var x = part.Trim(); int dir = x.StartsWith("BUY") ? 1 : x.StartsWith("SELL") ? -1 : 0; if (x.Contains("MNQ")) dm = dir; if (x.Contains("MGC")) dg = dir; }
            if (m && g) return dm == dg ? (dm > 0 ? 0 : 1) : -1; if (m) return dm > 0 ? 2 : 3; if (g) return dg > 0 ? 4 : 5; return -1;
        }
        // 🔮 the HINDSIGHT sides for the engine (research only): every rotation takes the side that reaches +TP first
        public static Func<KeystoneRotDay, int, Tuple<int, int>> Oracle(KeystoneSimSettings s, int endSlot)
        {
            return (d, k) =>
            {
                double[] p; int[] x; var o = Outcomes(s, d, k, endSlot, out p, out x);
                if (s.AltInstrument)
                {   // ALTERNATE MNQ / MGC: the engine keeps one leg per rotation — each leg its own winning side
                    int sm = o[2] == 1 && (o[3] != 1 || x[2] <= x[3]) ? 1 : o[3] == 1 ? -1 : p[2] >= p[3] ? 1 : -1, sg = o[4] == 1 && (o[5] != 1 || x[4] <= x[5]) ? 1 : o[5] == 1 ? -1 : p[4] >= p[5] ? 1 : -1;
                    return Tuple.Create(s.MnqQty > 0 ? sm : 0, s.MgcQty > 0 ? sg : 0);
                }
                int b = Best(o, p, x); return b < 0 ? Tuple.Create(0, 0) : Tuple.Create(SideDirs[b][0], SideDirs[b][1]);
            };
        }
        public static List<KeystoneHindsight> Hindsight(KeystoneSimSettings s, KeystonePropSim sim, IList<KeystoneRotDay> days, int endSlot)
        {
            var res = new List<KeystoneHindsight>(); if (sim == null || days == null) return res; var byDay = new Dictionary<DateTime, KeystoneRotDay>(); foreach (var d in days) byDay[d.Day.Date] = d;
            foreach (var t in sim.Trades)
            {
                KeystoneRotDay d; if (!byDay.TryGetValue(t.Day.Date, out d)) continue; int k = KeystoneRotDay.SlotOf(t.Entry);
                double[] p; int[] x; var o = Outcomes(s, d, k, endSlot, out p, out x); int b = Best(o, p, x), pi = IndexOfLegs(t.Legs);
                res.Add(new KeystoneHindsight { Day = t.Day, Entry = t.Entry, Account = t.Account, PlanIdx = pi, BestIdx = b, Plan = pi >= 0 ? SideNames[pi] : (t.Legs ?? ""), Perfect = b >= 0 ? SideNames[b] : "—",
                    Wins = string.Join(" • ", Enumerable.Range(0, 6).Where(i => o[i] == 1).Select(i => SideNames[i])), Match = pi >= 0 && o[pi] == 1, PlanPnl = t.Pnl, PlanHow = t.Reason ?? "", Out = o });
            }
            return res;
        }
        // the whole range's result for one plan: every account bought (every batch)
        public static KeystoneCalcRank Summary(string plan, string side, KeystoneSimSettings s, KeystonePropSim sim, double fee)
        {
            var r = new KeystoneCalcRank { Plan = plan, Side = side, Sim = sim }; if (sim == null) return r; bool fr = s.StartAs == "FUNDED";
            Func<KeystoneSimAccount, bool> won = a => fr ? a.BufferOn != DateTime.MinValue || a.Payouts > 0 : a.PassedOn != DateTime.MinValue;
            var all = sim.Accounts.ToList(); r.N = all.Count; var ok = all.Where(won).ToList(); r.Passed = ok.Count; r.Blown = all.Count(a => !won(a) && !a.Alive); r.Live = all.Count(a => !won(a) && a.Alive);
            r.AvgDays = ok.Count == 0 ? 0 : ok.Average(a => (double)Math.Max(1, fr ? a.FundedDays : a.EvalDays)); r.FeePerPass = ok.Count == 0 ? 0 : r.N * fee / ok.Count;
            r.Trades = sim.Trades.Count; r.Wins = sim.Trades.Count(t => t.Pnl > 0); r.Pnl = sim.Trades.Sum(t => t.Pnl); return r;
        }
        // the CSV lines (Studio\EvalLab\calc\<stamp>\…)
        public const string HindsightHeader = "day,entry,account,plan_side,plan_result,plan_how,perfect_side,winning_sides,plan_matched,BUY_BOTH,SELL_BOTH,BUY_MNQ,SELL_MNQ,BUY_MGC,SELL_MGC";
        public static string Line(KeystoneHindsight h, string acc)
        {
            Func<int, string> o = v => v == 1 ? "TP" : v == -1 ? "STOP" : v == 0 ? "TIME" : "";
            return string.Join(",", h.Day.ToString("yyyy-MM-dd"), h.Entry.ToString("HH:mm"), (acc ?? "").Replace(",", " "), h.Plan.Replace(",", " "), h.PlanPnl.ToString("0.00", CultureInfo.InvariantCulture), h.PlanHow.Replace(",", " "), h.Perfect, h.Wins.Replace(",", " "), h.Match ? "1" : "0", o(h.Out[0]), o(h.Out[1]), o(h.Out[2]), o(h.Out[3]), o(h.Out[4]), o(h.Out[5]));
        }
        public const string RankHeader = "plan,side,accounts,passed,blown,in_eval,pass_rate,avg_days,fee_per_pass,trades,wins,pnl,yours,hindsight";
        public static string Line(KeystoneCalcRank r)
        {
            Func<double, string> d = v => v.ToString("0.##", CultureInfo.InvariantCulture);
            return string.Join(",", r.Plan.Replace(",", " "), r.Side.Replace(",", " "), r.N, r.Passed, r.Blown, r.Live, d(r.N == 0 ? 0 : 100.0 * r.Passed / r.N), d(r.AvgDays), d(r.FeePerPass), r.Trades, r.Wins, d(r.Pnl), r.Mine ? 1 : 0, r.Hindsight ? 1 : 0);
        }
    }
