    // 🧪💰 LABS (BUILD 2026-11-09a): the replay's flow rules in one testable place — the staggered slots, the day-done check, the clock,
    // the 🪑 bench (at most 5 active funded accounts per firm), the balance a tile shows, the event log
    public static class KeystoneLabFlow
    {
        public static readonly int[] StaggerTimes = { 200, 830, 930, 1000, 1100 };
        // ⏱ BUILD 11f: a plan's own entry times (the time presets A / B) — null / empty = the 5 default times
        public static int[] TimesOr(int[] t) { return t != null && t.Length > 0 ? t : StaggerTimes; }
        public static string TimesText(int[] t) { return string.Join(" / ", TimesOr(t).Select(h => (h / 100) + ":" + (h % 100).ToString("00"))); }
        public static string TimesKey(int[] t) { return t == null || t.Length == 0 ? "" : string.Join(" ", t.Select(h => h.ToString(CultureInfo.InvariantCulture))); }
        public static int[] ParseTimes(string s)
        {
            var l = new List<int>(); foreach (var w in (s ?? "").Split(new[] { ' ', ',', ';', '/' }, StringSplitOptions.RemoveEmptyEntries)) { int h; string x = w.Replace(":", ""); if (int.TryParse(x, NumberStyles.Integer, CultureInfo.InvariantCulture, out h) && h >= 0 && h <= 2359 && h % 100 < 60) l.Add(h); }
            return l.Count == 0 ? null : l.ToArray();
        }
        // the session start a STAGGERED day needs: 1:55 AM (the default times) or 18:00 when a time is in the evening / night before 1:55 (23:00, 0:00 …)
        public static int StaggerStart(int[] t) { int s0 = KeystoneRotDay.Slot(155); return TimesOr(t).Any(h => KeystoneRotDay.Slot(h) < s0) ? 1800 : 155; }
        // the account's entry time of the 5 (by its number: 1 → 2:00, 2 → 8:30 … 6 → 2:00) — ≈ 6 of 30 at each time
        public static int SlotOf(int accountId, int slots) { return slots <= 0 ? 0 : (Math.Max(1, accountId) - 1) % slots; }
        // one side per firm per time per day (the same for every account of the firm at that time: no opposite positions inside a firm)
        // 🐞 BUILD 2026-11-11a (item 30): a proper hash coin — `new Random(h).Next(2)` with near-identical seeds made firm F0 = F1 on 90 % of the days
        // (all-or-nothing batches). splitmix64 of (firm key, day, slot, seed): firms, slots and days are independent coins (≈ 50 % agreement, ≈ 50 % BUY)
        public static int SideOf(DateTime day, string firm, int slot, int seed = 0) { return Coin(day, firm, slot, seed); }
        public static ulong Mix64(ulong x) { unchecked { x += 0x9E3779B97F4A7C15UL; x = (x ^ (x >> 30)) * 0xBF58476D1CE4E5B9UL; x = (x ^ (x >> 27)) * 0x94D049BB133111EBUL; return x ^ (x >> 31); } }
        public static ulong KeyHash(string key) { unchecked { ulong h = 14695981039346656037UL; foreach (var ch in (key ?? "").ToUpperInvariant()) { h ^= ch; h *= 1099511628211UL; } return Mix64(h); } }
        public static int Coin(DateTime day, string key, int slot, int seed)
        {
            unchecked { ulong h = KeyHash(key); h = Mix64(h ^ (ulong)(day.Year * 400 + day.DayOfYear)); h = Mix64(h ^ (ulong)(uint)slot); h = Mix64(h ^ (ulong)(uint)seed); return (h >> 63) == 0 ? 1 : -1; }
        }
        // a well-mixed seed for a per-day System.Random (adjacent seeds give correlated first draws)
        public static int SeedOf(int a, int b) { unchecked { return (int)(Mix64(Mix64((ulong)(uint)a) ^ (ulong)(uint)b) & 0x7FFFFFFF); } }
        // 🎲 THE ONE SIDE SOURCE (BUILD 10b): ⚡ CALCULATE and the ▶ replay ask the same question and get the same answer — the firm's key (its index in the
        // run, or groups of 5 without firms), the rule (FIRM / EACH / ALL / BUY / SELL), the day, the entry time and the run's seed
        public static string SideKey(bool hasFirms, int firmIdx, int accountId) { return hasFirms ? "F" + firmIdx : "G" + ((Math.Max(1, accountId) - 1) / 5); }
        public static int PlanSide(string rule, DateTime day, string firmKey, int accountId, int slot, int seed)
        {
            string r = (rule ?? "FIRM").ToUpperInvariant(); if (r == "BUY") return 1; if (r == "SELL") return -1;
            if (r == "ALL") return SideOf(day, "ALL", 0, seed); if (r == "EACH") return SideOf(day, "A" + accountId, slot, seed); return SideOf(day, firmKey, slot, seed);
        }
        // what a tile shows: after the close the day's P/L is already in the balance (the user's catch: +$3,000 / −$1,044 shown twice)
        public static double TileBalance(double bal, double dayPnl, bool dayClosed) { return dayClosed ? bal : bal + dayPnl; }
        // the plan's stop wins: 0 / no stop = ride the full room (the floor) — never a panel default
        public static double PlanStop(double planStop, double room, double fees) { double st = planStop <= 0 || planStop >= 1e5 ? room - fees : Math.Min(planStop, room - fees); return st; }
        // the day is done when nobody is in a trade and no account may still trade today (or the session is over)
        public static bool DayDone(int openTrades, int mayStillTrade, bool sessionOver) { return sessionOver || (openTrades == 0 && mayStillTrade == 0); }
        public static string DayDoneText(DateTime day, int traded, int banked, int lost, int passed, int blown, bool more)
        {
            return "✅ " + day.ToString("ddd dd.MM.yyyy", CultureInfo.InvariantCulture) + " DONE • " + traded + " traded · " + banked + " banked +target · " + lost + " lost · " + passed + " passed · " + blown + " blown" + (more ? " — ▶ NEXT DAY to continue the evaluations" : " — the last saved day: ▶ NEXT DAY looks for the next saved day");
        }
        // 🕐 the phase of the day by NEW YORK time (BUILD 2026-11-10a, the user's request: AM / PM everywhere, the session named)
        public static string Phase(DateTime ny)
        {
            double h = ny.Hour + ny.Minute / 60.0;
            if (h >= 18 || h < 2) return "🌙 night / Asia"; if (h < 8) return "🌅 London morning"; if (h < 12) return "☀ New York morning"; if (h < 16) return "🌤 New York afternoon"; if (h < 17) return "🔔 close"; return "✓ done for the day";
        }
        // 02:20 AM — every time in the lab carries AM / PM (never an ambiguous 24h number)
        public static string Am(DateTime t) { return t.ToString("hh:mm tt", CultureInfo.InvariantCulture); }
        public static string AmHhmm(int hhmm) { return Am(new DateTime(2000, 1, 1, Math.Max(0, Math.Min(23, hhmm / 100)), Math.Max(0, Math.Min(59, hhmm % 100)), 0)); }
        public static DateTime ToEurope(DateTime ny)
        {
            try { var et = TimeZoneInfo.FindSystemTimeZoneById("Eastern Standard Time"); var ce = TimeZoneInfo.FindSystemTimeZoneById("Central Europe Standard Time"); return TimeZoneInfo.ConvertTime(DateTime.SpecifyKind(ny, DateTimeKind.Unspecified), et, ce); } catch { }
            try { var et = TimeZoneInfo.FindSystemTimeZoneById("America/New_York"); var ce = TimeZoneInfo.FindSystemTimeZoneById("Europe/Berlin"); return TimeZoneInfo.ConvertTime(DateTime.SpecifyKind(ny, DateTimeKind.Unspecified), et, ce); } catch { }
            return ny.AddHours(6);
        }
        // 🕐 ONE time in the whole lab (BUILD 10a, the user's request): STRATEGY TIME = New York (every rule and entry time is New York), AM / PM
        public static string Clock(DateTime ny) { return ny.ToString("ddd dd.MM.yyyy", CultureInfo.InvariantCulture) + " · " + Am(ny) + " New York · " + Phase(ny); }
        public static string Both(DateTime ny) { return Am(ny) + " New York"; }
        // the moment in another market (Windows id first, then IANA; daylight saving handled by TimeZoneInfo) — null when the zone is unknown here
        public static DateTime? InZone(DateTime ny, string winId, string ianaId)
        {
            foreach (var pair in new[] { new[] { "Eastern Standard Time", winId }, new[] { "America/New_York", ianaId } })
                try { var et = TimeZoneInfo.FindSystemTimeZoneById(pair[0]); var z = TimeZoneInfo.FindSystemTimeZoneById(pair[1]); return TimeZoneInfo.ConvertTime(DateTime.SpecifyKind(ny, DateTimeKind.Unspecified), et, z); } catch { }
            return null;
        }
        // 🌐 the SESSIONS BOX: the replay moment in each market + its status (New York = the strategy's time)
        public static List<string> Sessions(DateTime ny)
        {
            var res = new List<string>(); double h = ny.Hour + ny.Minute / 60.0; bool wkd = ny.DayOfWeek == DayOfWeek.Saturday || (ny.DayOfWeek == DayOfWeek.Sunday && h < 18) || (ny.DayOfWeek == DayOfWeek.Friday && h >= 17);
            Func<double, double, double, string> st = (now, open, close) => now >= open && now < close ? "open" : "closed · opens " + AmHhmm((int)(Math.Floor(open) * 100 + Math.Round((open - Math.Floor(open)) * 60)));
            res.Add("🗽 New York " + Am(ny) + " · strategy time · stocks " + (wkd ? "closed (weekend)" : st(h, 9.5, 16)));
            var chi = InZone(ny, "Central Standard Time", "America/Chicago"); bool cmeOpen = !wkd && !(h >= 17 && h < 18);
            res.Add("🌆 Chicago (CME) " + (chi.HasValue ? Am(chi.Value) : "—") + " · futures " + (cmeOpen ? "open" : wkd ? "closed (weekend)" : "daily break · opens 06:00 PM New York"));
            var lon = InZone(ny, "GMT Standard Time", "Europe/London"); res.Add("🇬🇧 London " + (lon.HasValue ? Am(lon.Value) + " · " + (wkd ? "closed (weekend)" : st(lon.Value.Hour + lon.Value.Minute / 60.0, 8, 16.5)) : "—"));
            var tok = InZone(ny, "Tokyo Standard Time", "Asia/Tokyo"); res.Add("🗼 Tokyo " + (tok.HasValue ? Am(tok.Value) + " · " + (tok.Value.DayOfWeek == DayOfWeek.Saturday || tok.Value.DayOfWeek == DayOfWeek.Sunday ? "closed (weekend)" : st(tok.Value.Hour + tok.Value.Minute / 60.0, 9, 15)) : "—"));
            return res;
        }
        // 📅 the replay's day line: "Day 2 of 2 · Fri 9 Oct (the futures day runs Thu 6 PM → Fri 5 PM New York) · range Thu 8 Oct – Fri 9 Oct"
        public static string DayLine(DateTime day, int i, int n, DateTime first, DateTime last)
        {
            Func<DateTime, string> d = x => x.ToString("ddd d MMM", CultureInfo.InvariantCulture); var prev = day.AddDays(day.DayOfWeek == DayOfWeek.Monday ? -3 : -1);
            return "Day " + (i + 1) + " of " + n + " · " + d(day) + " (the futures day runs " + prev.ToString("ddd", CultureInfo.InvariantCulture) + " 6 PM → " + day.ToString("ddd", CultureInfo.InvariantCulture) + " 5 PM New York) · range " + d(first) + " – " + d(last);
        }
        // 🔀 FIRM BY FIRM (the user's catch, BUILD 09d: two accounts of one firm in a row): the accounts in firm round robin (TPT 1, LUCID 1,
        // TRADEIFY 1, TPT 2 …) — the firms in the order they first appear, each firm's accounts in their own order
        public static List<T> Interleave<T>(IEnumerable<T> items, Func<T, string> firmOf)
        {
            var keys = new List<string>(); var by = new Dictionary<string, Queue<T>>();
            foreach (var x in items ?? Enumerable.Empty<T>()) { string k = ((firmOf != null ? firmOf(x) : "") ?? "").Trim().ToUpperInvariant(); Queue<T> q; if (!by.TryGetValue(k, out q)) { by[k] = q = new Queue<T>(); keys.Add(k); } q.Enqueue(x); }
            var res = new List<T>(); bool any = true;
            while (any) { any = false; foreach (var k in keys) if (by[k].Count > 0) { res.Add(by[k].Dequeue()); any = true; } }
            return res;
        }
        // the entry time of position pos of n (firm by firm): the times in BLOCKS, so inside a time and from one time to the next the firm changes
        public static int SlotByPos(int pos, int n, int slots) { if (slots <= 0 || n <= 0) return 0; return Math.Max(0, Math.Min(slots - 1, (int)((long)pos * slots / n))); }
        // today's accounts → id → { position in the firm-by-firm order, entry time 0..slots-1 } • one firm only = the old order (1 → 2:00, 2 → 8:30 …)
        public static Dictionary<int, int[]> Plan(IList<int> ids, IList<string> firms, int slots)
        {
            var res = new Dictionary<int, int[]>(); if (ids == null) return res; var idx = Enumerable.Range(0, ids.Count).OrderBy(i => ids[i]).ToList();
            bool many = firms != null && firms.Count == ids.Count && firms.Select(f => (f ?? "").Trim().ToUpperInvariant()).Distinct().Count() > 1;
            var order = many ? Interleave(idx, i => firms[i]) : idx;
            for (int p = 0; p < order.Count; p++) { int id = ids[order[p]]; res[id] = new[] { p, many ? SlotByPos(p, order.Count, slots) : SlotOf(id, slots) }; }
            return res;
        }
        // 💬 WHY (the user's request): every automated trade in one plain sentence — on screen and in the event log
        public static string Why(string name, DateTime ny, int dM, int qM, int dG, int qG, string firm, string rule, double tpAfterCosts, double stop, double room)
        {
            Func<double, string> m = v => "$" + Math.Round(Math.Abs(v)).ToString("N0", CultureInfo.InvariantCulture);
            int dir = dM != 0 ? dM : dG; string sd = dir > 0 ? "BUY" : "SELL";
            string legs = (qM > 0 ? (dM > 0 ? "BUY" : "SELL") + " MNQ " + qM : "") + (qM > 0 && qG > 0 ? " + " : "") + (qG > 0 ? (dG > 0 ? "BUY" : "SELL") + " MGC " + qG : "");
            string f = KeystonePipeline.Nice(firm); string r = (rule ?? "").ToUpperInvariant();
            string why = r == "FIRM" ? f + "'s coin for this slot is " + sd + " (one side per firm)" : r == "EACH" ? "its own coin for today is " + sd : r == "ALL" ? "today's one coin for every account is " + sd
                : r == "BUY" || r == "SELL" ? "the plan always " + (r == "BUY" ? "BUYS" : "SELLS") : "the plan's side rule (" + (rule ?? "") + ") says " + sd;
            return name + " · " + Am(ny) + " New York · " + legs + " — " + why + " · TP +" + m(tpAfterCosts) + " after costs · " + (stop >= 1e5 || stop >= room - 1 ? "no stop (room " + m(room) + ")" : "stop −" + m(stop) + " (room " + m(room) + ")");
        }
        // ✋ the banner when the replay waits for your click (a firm without automation) — or says that AUTO trades it (backtest only)
        public static string FirmLong(string firm) { string f = (firm ?? "").Trim().ToUpperInvariant(); return f == "TPT" ? "Take Profit Trader" : f == "LUCID" ? "Lucid Trading" : f == "TRADEIFY" ? "Tradeify" : KeystonePipeline.Nice(f); }
        public static string WaitBanner(string name, string firm, string sideText, bool autoAnyway)
        {
            if (autoAnyway) return "⚡ " + name + "'s turn — 'let AUTO trade TPT too (backtest only)' is ticked, so AUTO presses " + sideText + " for " + FirmLong(firm) + " here. Live stays manual: " + FirmLong(firm) + " doesn't allow automation.";
            return "✋ " + name + "'s turn — " + FirmLong(firm) + " doesn't allow automation, so YOU press the flashing " + sideText + " (the plan's side). Lucid / Tradeify accounts trade by themselves.";
        }
        // ⏩ TIME SKIP (backtest, AUTO on): with no open trade, jump to the next entry time (nothing is due in between) → the minute to go to (mk = stay)
        public static int SkipTo(int mk, int openTrades, IEnumerable<int> entrySlots, int end)
        {
            if (openTrades > 0) return mk; int nx = int.MaxValue; foreach (var k in entrySlots ?? Enumerable.Empty<int>()) if (k >= mk && k < nx) nx = k;
            if (nx == int.MaxValue) return mk; nx = Math.Min(nx, end); return nx > mk + 1 ? nx : mk;
        }
        public static string SkipNote(DateTime fromNy, DateTime toNy, string next) { return "⏩ " + Am(fromNy) + " → " + Am(toNy) + " New York" + (string.IsNullOrEmpty(next) ? "" : " (next: " + next + ")") + " — nothing open, nothing due in between"; }
        // 💰 the first funded session of an account that passed on passDay: the next session (TPT pending: after its day-3 tiny trade = the one after)
        public static DateTime FundedStart(DateTime passDay, bool tinyTradeFirst) { var d = passDay.Date; for (int q = 0; q < (tinyTradeFirst ? 2 : 1); q++) { d = d.AddDays(1); while (d.DayOfWeek == DayOfWeek.Saturday || d.DayOfWeek == DayOfWeek.Sunday) d = d.AddDays(1); } return d; }
        // 🧾 why an account is still in evaluation after the close (the DAY DONE box + its tag in the pool): "needs +$600 more" / "TPT day 3 (min 3 days)"
        public static string RemainTag(double bal, double target, int daysDone, int minDays, string firm)
        {
            if (bal < target - 0.5) return "needs +$" + Math.Ceiling(target - bal).ToString("N0", CultureInfo.InvariantCulture) + " more (a winning day)";
            if (minDays > 0 && daysDone < minDays) return KeystonePipeline.Nice(firm) + " day " + (daysDone + 1) + " (min " + minDays + " days · a tiny trade)";
            return "the best day is too big a share (consistency) — one more day";
        }
        public static string RemainLine(IList<string> tags)
        {
            if (tags == null || tags.Count == 0) return ""; int win = tags.Count(t => t.StartsWith("needs")), days = tags.Count(t => t.Contains(" day ") && t.Contains("min ")), cons = tags.Count - win - days;
            var parts = new List<string>(); if (win > 0) parts.Add(win + " need another winning day (a losing or partial day)"); if (days > 0) parts.Add(days + " need their minimum days (tiny trade)"); if (cons > 0) parts.Add(cons + " need a smaller best-day share (consistency)");
            return tags.Count + " still in evaluation — " + string.Join(", ", parts) + " · ▶ NEXT DAY continues them";
        }
        // 🔁 TRADE AGAIN IF THE TARGET WASN'T REACHED (same day, risking what's left): the rotation = until +profit a day; the timed models = one more
        // trade after a stop, the same side, the plan's take profit, risking the room left (tested: no gain)
        public static void TradeAgain(KeystoneSimSettings s, bool on)
        {
            if (s == null || !on) return; if (s.AllAtOnce) { if (s.RecTarget <= 0) { s.RecTarget = s.RotTarget; s.RecSide = "SAME"; } } else s.MaxTradesPerDay = 0;
        }
    }
    // 📈 THE LAB CHART'S VIEW (BUILD 2026-11-10a — the user: "move around the chart the same way as live trading"): the timeframe, the zoom
    // (visible bars: mouse wheel), the pan (bars back from the newest: drag left / right; the price shift: drag up / down), the price stretch
    // (drag the price axis), double-click = auto-fit • it follows the newest bar unless the user scrolled away (⟲ NOW returns)
    public sealed class KeystoneLabChartView
    {
        public static readonly int[] Tfs = { 1, 2, 3, 5, 15, 30, 60 };
        public int Tf = 1, Bars = 120, Back; public double YShift, YScale = 1;
        public bool Following { get { return Back == 0; } }
        public void Zoom(int delta) { if (delta == 0) return; Bars = Math.Max(15, Math.Min(600, (int)Math.Round(Bars * (delta > 0 ? 0.8 : 1.25)))); }
        public void Pan(double bars, double yFrac) { Back = Math.Max(0, Back + (int)Math.Round(bars)); YShift += yFrac; }
        public void Stretch(double f) { if (f > 0) YScale = Math.Max(0.2, Math.Min(8, YScale * f)); }
        public void Fit() { YShift = 0; YScale = 1; }
        public void Now() { Back = 0; YShift = 0; YScale = 1; }
        public void SetTf(int tf) { if (tf > 0) { Tf = tf; Back = 0; } }
        public sealed class Bar { public int K0, K1; public double O, H, L, C; }
        // the minute bars → Tf bars (aligned to 18:00 New York), up to the replay minute mk (never the future); the visible window = Bars, Back bars back
        public List<Bar> All(float[] o, float[] h, float[] l, float[] c, int first, int mk)
        {
            var all = new List<Bar>(); Bar cur = null; int curB = int.MinValue; if (c == null) return all;
            for (int k = Math.Max(0, first); k <= mk && k < c.Length; k++)
            {
                if (float.IsNaN(c[k])) continue; int b = k / Math.Max(1, Tf);
                if (cur == null || b != curB) { cur = new Bar { K0 = k, K1 = k, O = o[k], H = h[k], L = l[k], C = c[k] }; curB = b; all.Add(cur); } else { cur.K1 = k; cur.H = Math.Max(cur.H, h[k]); cur.L = Math.Min(cur.L, l[k]); cur.C = c[k]; }
            }
            return all;
        }
        public List<Bar> Visible(List<Bar> all)
        {
            if (all == null) return new List<Bar>(); int maxBack = Math.Max(0, all.Count - Bars); if (Back > maxBack) Back = maxBack;
            int end = all.Count - Back, start = Math.Max(0, end - Bars); return all.GetRange(start, Math.Max(0, end - start));
        }
        public static string Ohlc(Bar b, string inst, DateTime ny)
        {
            if (b == null) return ""; Func<double, string> f = v => v.ToString("0.00", CultureInfo.InvariantCulture);
            return inst + " " + KeystoneLabFlow.Am(ny) + " New York · O " + f(b.O) + "  H " + f(b.H) + "  L " + f(b.L) + "  C " + f(b.C) + "  · range " + f(b.H - b.L) + " · " + (b.C >= b.O ? "▲ +" : "▼ ") + f(b.C - b.O);
        }
    }
    // 📊 THE LAB'S RESULT TABLES (BUILD 2026-11-10b — the user: "always see the time period, what day they got blown, trades taken, statistics … all in
    // different tabs"): one pure builder for ⚡ CALCULATE and the ▶ replay — 🧪 EVAL RESULTS (per firm + per account, wins / losses, the streaks), 📅 DAYS,
    // 📜 TRADES, 💀 BLOWN, 💰 PAYOUTS, 📊 STATS — every table = a header row + rows (CSV + one summary HTML for the export)
    public sealed class KeystoneLabResults
    {
        public string Scope = "EVAL", Period = ""; public DateTime From, To; public int Sessions;
        /* BUILD 11a: Header = what the run is ("one batch of 30 bought on …; blown accounts are not replaced") • Note = ⏳ still running when the days ended •
           Sig = the settings it was made with (a changed setting → the stale banner) • Replay = made by ▶ REPLAY (Progress = "day n of N" while it plays) •
           DaysEnd = the last day the run could use (⏳ + ➕ EXTEND) */
        public string Header = "", Note = "", Sig = "", Progress = ""; public bool Replay; public DateTime DaysEnd;
        /* 🔁 BUILD 11d: Continuous = ⚡ CALCULATE kept buying until END (Months = the month-by-month table) • EndedEarly = a "one batch only" run whose batch finished
           before the END (EndTo = that END → the 🔁 keep buying button) */
        public bool Continuous, EndedEarly; public DateTime EndTo; public List<string[]> Months = new List<string[]>();
        public int Accounts, Passed, Blown, InEval, Wins, Losses, WinStreak, LossStreak, Payouts; public double Spent, Paid;
        public List<string[]> Eval = new List<string[]>(), PerAccount = new List<string[]>(), Days = new List<string[]>(), Trades = new List<string[]>(), BlownRows = new List<string[]>(), PayoutRows = new List<string[]>(), Stats = new List<string[]>();
        /* 📒 BUILD 11b (phase B): the ONE run record every view reads + its tables — 👤 ACCOUNTS, 💰 FUNDED RESULTS, 🕒 TIMELINE (built on demand with filters),
           💰 PAYOUTS by payout / account / firm / month + the accounts without one, 📊 the distributions; Trust = the data + costs + fills line (item 16) */
        public KeystoneRunRecord Record; public List<string[]> Accounts2 = new List<string[]>(), FundedFirm = new List<string[]>(), FundedAcc = new List<string[]>(), PayByPayout = new List<string[]>(), PayByAccount = new List<string[]>(), PayByFirm = new List<string[]>(), PayByMonth = new List<string[]>(), PayNone = new List<string[]>(), Dist = new List<string[]>();
        public string Trust = "", PayHeader = ""; public bool BestStarts;   /* 🏆 BEST START DAYS: a row opens that start's full results */
        // fills every record table (and the funded columns of the EVAL RESULTS tables, item 23) from the record — the counts come from it too
        public void FromRecord(KeystoneRunRecord rec)
        {
            Record = rec; if (rec == null) return; var IC = CultureInfo.InvariantCulture;
            Accounts2 = rec.AccountsTable(); FundedFirm = rec.FundedFirmTable(); FundedAcc = rec.FundedAccountsTable(); PayByPayout = rec.ByPayout(); PayByAccount = rec.ByAccount(); PayByFirm = rec.ByFirm(); PayByMonth = rec.ByMonth(); PayNone = rec.NoPayout(); Dist = rec.DistTable();
            Trust = rec.Trust; PayHeader = rec.PayoutHeader(); Payouts = rec.PayoutN; Paid = rec.PaidNet;
            if (Scope != "FUNDED" && rec.Accounts.Count > 0 && Eval.Count > 0 && Eval[0].Length == 11)
            {   /* item 23: the empty right side of the EVAL RESULTS tables → funded · paid · $ to you per firm, funded on · payouts · $ · status per account */
                Eval[0] = Eval[0].Concat(new[] { "FUNDED", "PAID", "$ TO YOU" }).ToArray();
                for (int i = 1; i < Eval.Count; i++) { string f = Eval[i][0]; var g = rec.Accounts.Where(a => f == "ALL" || a.FirmNice == f).ToList(); Eval[i] = Eval[i].Concat(new[] { g.Count(a => a.Funded).ToString(IC), g.Count(a => a.Payouts > 0).ToString(IC), M(g.Sum(a => a.Net)) }).ToArray(); }
                if (PerAccount.Count > 0 && PerAccount[0].Length == 8)
                {
                    PerAccount[0] = PerAccount[0].Concat(new[] { "FUNDED ON", "PAYOUTS", "$", "FUNDED STATUS" }).ToArray();
                    for (int i = 1; i < PerAccount.Count; i++) { var x = rec.Find(PerAccount[i][0]); PerAccount[i] = PerAccount[i].Concat(x == null ? new[] { "–", "–", "–", "–" } : new[] { x.FundedFrom == DateTime.MinValue ? "–" : x.FundedFrom.ToString("ddd dd MMM", IC), x.Payouts.ToString(IC), M(x.Net), x.Funded || x.Passed ? x.Status : "–" }).ToArray(); }
                }
            }
            if (Stats.Count > 0) { Stats.Add(new[] { "📊 days to pass / lock / payout (this run)", "see the DISTRIBUTIONS table below (median, 10th–90th)" }); }
        }
        static string M(double v) { return (v < 0 ? "−$" : "$") + Math.Abs(Math.Round(v)).ToString("N0", CultureInfo.InvariantCulture); }
        static string Sg(double v) { return (v >= 0 ? "+" : "−") + "$" + Math.Abs(Math.Round(v)).ToString("N0", CultureInfo.InvariantCulture); }
        static string P(int a, int n) { return n <= 0 ? "–" : (100.0 * a / n).ToString("0.0", CultureInfo.InvariantCulture) + " %"; }
        public static void Streaks(IList<double> pnls, out int win, out int loss)
        {
            win = loss = 0; int w = 0, l = 0; foreach (var v in pnls ?? new List<double>()) { if (v > 0) { w++; l = 0; } else { l++; w = 0; } win = Math.Max(win, w); loss = Math.Max(loss, l); }
        }
        public static KeystoneLabResults Of(string scope, KeystonePropSim sim, int firstN, Func<KeystoneSimAccount, string> nameOf, Func<KeystoneSimAccount, string> firmOf, KeystonePayoutRun pay, DateTime from, DateTime to, int sessions)
        {
            var r = new KeystoneLabResults { Scope = scope ?? "EVAL", From = from, To = to, Sessions = sessions }; var IC = CultureInfo.InvariantCulture;
            r.Period = from.ToString("ddd dd MMM yyyy", IC) + " → " + to.ToString("ddd dd MMM yyyy", IC) + " · " + sessions + " session" + (sessions == 1 ? "" : "s");
            if (nameOf == null) nameOf = a => a.Name; if (firmOf == null) firmOf = a => sim != null ? sim.FirmName(a) : "";
            var rec0 = KeystoneRunRecord.Of(scope, sim, firstN, nameOf, firmOf, pay, from, to, sessions);   /* 📒 the ONE record (BUILD 11b) */
            if (sim != null)
            {
                var acc = sim.Accounts.Take(firstN > 0 ? firstN : sim.Accounts.Count).ToList(); var ids = new HashSet<int>(acc.Select(a => a.Id));
                var trs = sim.Trades.Where(t => ids.Contains(t.Account)).OrderBy(t => t.Exit).ThenBy(t => t.Account).ToList(); var byId = acc.ToDictionary(a => a.Id);
                Func<KeystoneSimAccount, bool> ok = sim.PassedOrPending; Func<KeystoneSimAccount, bool> bl = a => !a.Alive && !ok(a);
                r.Accounts = acc.Count; r.Passed = acc.Count(ok); r.Blown = acc.Count(bl); r.InEval = r.Accounts - r.Passed - r.Blown; r.Wins = trs.Count(t => t.Pnl > 0); r.Losses = trs.Count - r.Wins; r.Spent = acc.Sum(a => a.Spent);
                int ws, ls; Streaks(trs.Select(t => t.Pnl).ToList(), out ws, out ls); r.WinStreak = ws; r.LossStreak = ls;
                r.Eval.Add(new[] { "FIRM", "ACCOUNTS", "PASSED", "BLOWN", "IN EVAL", "PASS %", "TRADES", "WON", "LOST", "WIN %", "P/L" });
                foreach (var g in acc.GroupBy(a => KeystonePipeline.Nice(firmOf(a))))
                {
                    var gt = trs.Where(t => g.Any(a => a.Id == t.Account)).ToList(); int gp = g.Count(ok), gb = g.Count(bl);
                    r.Eval.Add(new[] { g.Key, g.Count().ToString(IC), gp.ToString(IC), gb.ToString(IC), (g.Count() - gp - gb).ToString(IC), P(gp, g.Count()), gt.Count.ToString(IC), gt.Count(t => t.Pnl > 0).ToString(IC), gt.Count(t => t.Pnl <= 0).ToString(IC), P(gt.Count(t => t.Pnl > 0), gt.Count), Sg(gt.Sum(t => t.Pnl)) });
                }
                r.Eval.Add(new[] { "ALL", r.Accounts.ToString(IC), r.Passed.ToString(IC), r.Blown.ToString(IC), r.InEval.ToString(IC), P(r.Passed, r.Accounts), trs.Count.ToString(IC), r.Wins.ToString(IC), r.Losses.ToString(IC), P(r.Wins, trs.Count), Sg(trs.Sum(t => t.Pnl)) });
                r.PerAccount.Add(new[] { "ACCOUNT", "FIRM", "DAY 1", "DAY 2", "DAY 3", "TRADES", "P/L", "STATUS" });
                foreach (var a in acc)
                {
                    var days = trs.Where(t => t.Account == a.Id).GroupBy(t => t.Day.Date).OrderBy(x => x.Key).Select(x => x.Sum(t => t.Pnl)).ToList(); Func<int, string> dd = i => i < days.Count ? Sg(days[i]) : "–";
                    string st = ok(a) ? (sim.PassedPending(a) ? "✅ PASSED (day " + (a.EvalDays + 1) + ": tiny trade)" : "✅ PASSED") : bl(a) ? "💀 BLOWN" : "● IN EVAL";
                    r.PerAccount.Add(new[] { nameOf(a), KeystonePipeline.Nice(firmOf(a)), dd(0), dd(1), dd(2), trs.Count(t => t.Account == a.Id).ToString(IC), Sg(trs.Where(t => t.Account == a.Id).Sum(t => t.Pnl)), st });
                }
                Func<KeystoneSimAccount, DateTime, int> dayNo = (a, d) => trs.Where(t => t.Account == a.Id && t.Day.Date <= d.Date).Select(t => t.Day.Date).Distinct().Count();
                r.Days.Add(new[] { "DATE", "FIRM", "TRADES", "WON", "LOST", "P/L", "PASSED", "BLOWN" });
                foreach (var dg in trs.GroupBy(t => t.Day.Date).OrderBy(x => x.Key))
                    foreach (var fg in dg.GroupBy(t => KeystonePipeline.Nice(firmOf(byId[t.Account]))))
                        r.Days.Add(new[] { dg.Key.ToString("ddd yyyy-MM-dd", IC), fg.Key, fg.Count().ToString(IC), fg.Count(t => t.Pnl > 0).ToString(IC), fg.Count(t => t.Pnl <= 0).ToString(IC), Sg(fg.Sum(t => t.Pnl)), acc.Count(a => KeystonePipeline.Nice(firmOf(a)) == fg.Key && a.PassedOn.Date == dg.Key).ToString(IC), acc.Count(a => KeystonePipeline.Nice(firmOf(a)) == fg.Key && bl(a) && a.Ended.Date == dg.Key).ToString(IC) });
                r.Trades.Add(new[] { "DATE", "TIME (NEW YORK)", "ACCOUNT", "FIRM", "PHASE", "INSTRUMENT", "SIDE", "CONTRACTS", "ENTRY", "P/L AFTER COSTS", "HOW IT ENDED" });
                foreach (var t in trs) { var lg = (t.Legs ?? "").Split(' '); r.Trades.Add(new[] { t.Day.ToString("yyyy-MM-dd", IC), t.Entry == DateTime.MinValue ? "" : KeystoneLabFlow.Am(t.Entry) + " → " + KeystoneLabFlow.Am(t.Exit), nameOf(byId[t.Account]), KeystonePipeline.Nice(firmOf(byId[t.Account])), t.Phase, lg.Length > 2 ? lg[2] + ((t.Legs ?? "").Contains("+") ? " + MGC" : "") : t.Legs, lg.Length > 0 ? lg[0] : "", lg.Length > 1 ? lg[1] : "", t.EntryPx == 0 ? "" : t.EntryPx.ToString("0.00", IC), Sg(t.Pnl), t.Reason == "TARGET" ? "TP" : t.Reason == "STOP" ? "stop / floor" : t.Reason }); }
                r.BlownRows.Add(new[] { "ACCOUNT", "FIRM", "DATE BLOWN", "DAY No.", "LAST TRADE", "BALANCE", "REASON" });
                foreach (var a in acc.Where(bl)) { var lt = trs.LastOrDefault(t => t.Account == a.Id); r.BlownRows.Add(new[] { nameOf(a), KeystonePipeline.Nice(firmOf(a)), a.Ended.ToString("ddd yyyy-MM-dd", IC), dayNo(a, a.Ended).ToString(IC), lt == null ? "" : (lt.Legs + " " + Sg(lt.Pnl) + " (" + lt.Reason + ")"), Sg(a.Bal + (a.Ended == sim.Day ? 0 : 0)), string.IsNullOrEmpty(a.EndReason) ? "the floor" : a.EndReason }); }
                r.Stats.Add(new[] { "STAT", "VALUE" });
                r.Stats.Add(new[] { "period", r.Period }); r.Stats.Add(new[] { "accounts", r.Accounts.ToString(IC) }); r.Stats.Add(new[] { "passed", r.Passed + " (" + P(r.Passed, r.Accounts) + ")" }); r.Stats.Add(new[] { "blown", r.Blown + " (" + P(r.Blown, r.Accounts) + ")" }); r.Stats.Add(new[] { "still in evaluation", r.InEval.ToString(IC) });
                r.Stats.Add(new[] { "trades won / lost", r.Wins + " / " + r.Losses + " (" + P(r.Wins, trs.Count) + ")" }); r.Stats.Add(new[] { "longest winning streak (rotation order)", r.WinStreak.ToString(IC) }); r.Stats.Add(new[] { "longest losing streak (accounts hit in a row)", r.LossStreak.ToString(IC) });
                var okA = acc.Where(ok).ToList(); r.Stats.Add(new[] { "average days to pass", okA.Count == 0 ? "–" : okA.Average(a => (double)Math.Max(1, dayNo(a, a.PassedOn == DateTime.MinValue ? to : a.PassedOn))).ToString("0.0", IC) });
                foreach (var g in okA.GroupBy(a => dayNo(a, a.PassedOn == DateTime.MinValue ? to : a.PassedOn)).OrderBy(x => x.Key)) r.Stats.Add(new[] { "passed on day " + g.Key, g.Count().ToString(IC) });
                foreach (var g in acc.Where(bl).GroupBy(a => dayNo(a, a.Ended)).OrderBy(x => x.Key)) r.Stats.Add(new[] { "blown on day " + g.Key, g.Count().ToString(IC) });
                foreach (var g in trs.GroupBy(t => t.Day.Date.AddDays(-(((int)t.Day.DayOfWeek + 6) % 7))).OrderBy(x => x.Key)) r.Stats.Add(new[] { "week of " + g.Key.ToString("ddd dd MMM", IC), g.Count() + " trades · " + Sg(g.Sum(t => t.Pnl)) + " · passed " + acc.Count(a => a.PassedOn != DateTime.MinValue && a.PassedOn.Date >= g.Key && a.PassedOn.Date < g.Key.AddDays(7)) + " · blown " + acc.Count(a => bl(a) && a.Ended.Date >= g.Key && a.Ended.Date < g.Key.AddDays(7)) });
                r.Stats.Add(new[] { "evaluations bought", M(r.Spent) + (r.Passed > 0 ? " · " + M(r.Spent / r.Passed) + " per passed account" : "") });
            }
            else r.Stats.Add(new[] { "STAT", "VALUE" });
            r.PayoutRows.Add(new[] { "ACCOUNT", "FIRM", "DATE", "PAYOUT No.", "GROSS", "TO YOU", "DAYS SINCE THE LAST" });
            if (pay != null)
            {
                foreach (var a in pay.Accounts) { DateTime last = DateTime.MinValue; foreach (var e in a.Paid.OrderBy(x => x.Day)) { r.PayoutRows.Add(new[] { a.Name, KeystonePipeline.Nice(a.Firm), e.Day.ToString("ddd yyyy-MM-dd", IC), e.N.ToString(IC), M(e.Gross), M(e.Net), last == DateTime.MinValue ? "–" : ((int)(e.Day - last).TotalDays).ToString(IC) }); last = e.Day; } }
                r.Payouts = pay.Payouts; r.Paid = pay.Net;
                foreach (var t in pay.Trades.OrderBy(x => x.Day)) { var a = pay.Accounts.FirstOrDefault(x => x.Id == t.Account); var lg = (t.Legs ?? "").Split(' '); r.Trades.Add(new[] { t.Day.ToString("yyyy-MM-dd", IC), t.Entry == DateTime.MinValue ? "" : KeystoneLabFlow.Am(t.Entry) + (t.Exit == DateTime.MinValue ? "" : " → " + KeystoneLabFlow.Am(t.Exit)), a != null ? a.Name : "#" + t.Account, a != null ? KeystonePipeline.Nice(a.Firm) : "", "FUNDED", lg.Length > 2 ? lg[2] : t.Legs, lg.Length > 0 ? lg[0] : "", lg.Length > 1 ? lg[1] : "", "", Sg(t.Pnl), t.Reason }); }
                foreach (var a in pay.Accounts.Where(x => x.Stage == "BLOWN")) r.BlownRows.Add(new[] { a.Name, KeystonePipeline.Nice(a.Firm), a.Ended == DateTime.MinValue ? "" : a.Ended.ToString("ddd yyyy-MM-dd", IC), a.Days.ToString(IC), "FUNDED", Sg(a.Bal), "the funded floor (" + M(a.Floor) + ")" });
                foreach (var g in pay.Accounts.GroupBy(x => KeystonePipeline.Nice(x.Firm))) r.Stats.Add(new[] { "funded " + g.Key, g.Count() + " accounts · " + g.Sum(x => x.Payouts) + " payouts (" + P(g.Count(x => x.Payouts > 0), g.Count()) + " paid at least once) · " + M(g.Sum(x => x.Net)) + " to you · " + g.Count(x => x.Stage == "BLOWN") + " blown" });
                r.Stats.Add(new[] { "payouts", r.Payouts + " · " + M(r.Paid) + " to you" });
                // 📅 BUILD 11a (item 8): the funded days next to the eval days (one timeline, sorted by date; the firm marked "· funded")
                if (r.Days.Count == 0) r.Days.Add(new[] { "DATE", "FIRM", "TRADES", "WON", "LOST", "P/L", "PASSED", "BLOWN" });
                foreach (var dg in pay.Trades.GroupBy(t => t.Day.Date))
                    foreach (var fg in dg.GroupBy(t => { var a = pay.Accounts.FirstOrDefault(x => x.Id == t.Account); return a == null ? "" : KeystonePipeline.Nice(a.Firm); }))
                        r.Days.Add(new[] { dg.Key.ToString("ddd yyyy-MM-dd", IC), fg.Key + " · funded", fg.Count().ToString(IC), fg.Count(t => t.Pnl > 0).ToString(IC), fg.Count(t => t.Pnl <= 0).ToString(IC), Sg(fg.Sum(t => t.Pnl)), "💵 " + pay.Events.Count(e => e.Day.Date == dg.Key && KeystonePipeline.Nice(e.Firm) == fg.Key), pay.Accounts.Count(a => a.Stage == "BLOWN" && a.Ended.Date == dg.Key && KeystonePipeline.Nice(a.Firm) == fg.Key).ToString(IC) });
                var head = r.Days[0]; var body = r.Days.Skip(1).OrderBy(x => x[0].Length > 4 ? x[0].Substring(4) : x[0], StringComparer.Ordinal).ThenBy(x => x[1].Contains("funded") ? 1 : 0).ToList(); r.Days.Clear(); r.Days.Add(head); r.Days.AddRange(body);
            }
            r.FromRecord(rec0);
            r.Stats.Add(new[] { "money", "spent " + M(r.Spent) + " · paid " + M(r.Paid) + " · net " + Sg(r.Paid - r.Spent) });
            return r;
        }
        // 🔁 the BUSINESS RUN in the same result tabs (its ONE record: 👤 ACCOUNTS, 🕒 TIMELINE, 💵 PAYOUTS, 📦 EXPORT FOR CLAUDE)
        public static KeystoneLabResults FromBusiness(KeystoneBusinessRun b)
        {
            var r = new KeystoneLabResults { Scope = "BUSINESS" }; if (b == null) return r; var IC = CultureInfo.InvariantCulture; var rec = b.Record;
            r.From = b.From; r.To = b.To; r.Sessions = b.Sessions; r.Period = b.From.ToString("ddd dd MMM yyyy", IC) + " → " + b.To.ToString("ddd dd MMM yyyy", IC) + " · " + b.Sessions + " sessions";
            r.Header = (b.S != null ? b.S.Describe() + " • " : "") + b.Summary(); r.Accounts = rec.Accounts.Count; r.Passed = rec.PassedN; r.Blown = rec.EvalBlownN; r.InEval = rec.Accounts.Count(a => a.StillEval); r.Spent = b.Spent;
            r.Wins = rec.Trades.Count(t => t.Pnl > 0); r.Losses = rec.Trades.Count - r.Wins; int ws, ls; Streaks(rec.Trades.OrderBy(t => t.Exit).Select(t => t.Pnl).ToList(), out ws, out ls); r.WinStreak = ws; r.LossStreak = ls;
            r.Eval = b.FirmTable(); r.Days = b.MonthTable();
            r.Trades.Add(new[] { "DATE", "TIME (NEW YORK)", "ACCOUNT", "FIRM", "PHASE", "INSTRUMENT", "SIDE", "CONTRACTS", "ENTRY", "P/L AFTER COSTS", "HOW IT ENDED" });
            foreach (var t in rec.Trades.OrderBy(t => t.Entry)) r.Trades.Add(new[] { t.Day.ToString("yyyy-MM-dd", IC), t.Entry == DateTime.MinValue ? "" : KeystoneLabFlow.Am(t.Entry) + " → " + KeystoneLabFlow.Am(t.Exit), t.Account, KeystonePipeline.Nice(t.Firm), t.Stage, t.Instrument, t.Dir > 0 ? "BUY" : "SELL", t.Qty.ToString(IC), double.IsNaN(t.EntryPx) ? "" : t.EntryPx.ToString("0.00", IC), Sg(t.Pnl), t.How });
            r.BlownRows.Add(new[] { "ACCOUNT", "FIRM", "DATE BLOWN", "STAGE", "PAYOUTS", "STATUS" });
            foreach (var a in rec.Accounts.Where(x => x.Blown)) r.BlownRows.Add(new[] { a.Name, a.FirmNice, a.Ended.ToString("ddd yyyy-MM-dd", IC), a.EvalBlown ? "EVAL" : "FUNDED", a.Payouts.ToString(IC), a.Status });
            r.Stats.Add(new[] { "STAT", "VALUE" }); r.Stats.Add(new[] { "business run", b.Summary() }); r.Stats.Add(new[] { "evaluations bought", b.Bought + " (" + M(b.Spent) + ") in " + b.Cohorts + " purchase days" }); r.Stats.Add(new[] { "cash low", M(b.WorstCash) + " on " + (b.WorstDay == DateTime.MinValue ? "–" : b.WorstDay.ToString("ddd dd MMM yyyy", IC)) });
            if (b.S != null && b.S.Funding == "POCKET") r.Stats.Add(new[] { "out of pocket (at most)", M(b.OutOfPocket) }); if (b.TakeHome > 0) r.Stats.Add(new[] { "take-home (kept from the payouts)", M(b.TakeHome) });
            r.Stats.Add(new[] { "slot-days waiting for cash", b.WaitDays.ToString(IC) });
            r.FromRecord(rec); r.Trust = rec.Trust; r.Payouts = rec.PayoutN; r.Paid = rec.PaidNet;
            r.Stats.Add(new[] { "money", "spent " + M(r.Spent) + " · paid " + M(r.Paid) + " · net " + Sg(r.Paid - r.Spent) });
            return r;
        }
        // 🔁 BUILD 11d: a CONTINUOUS ⚡ CALCULATE (the business engine, out of pocket, every slot keeps its firm, a blown / finished account replaced the next
        // session until END) in the usual tabs — EVAL RESULTS opens with the month-by-month table, then per firm, then every account of every generation
        public static KeystoneLabResults FromContinuous(KeystoneBusinessRun b, string scope)
        {
            var r = new KeystoneLabResults { Scope = scope == "EVAL" ? "EVAL" : "BOTH", Continuous = true }; if (b == null) return r; var IC = CultureInfo.InvariantCulture; var rec = b.Record; bool eo = r.Scope == "EVAL";
            rec.Scope = r.Scope; r.From = b.From; r.To = b.To; r.Sessions = b.Sessions; r.DaysEnd = b.To;
            r.Period = b.From.ToString("ddd dd MMM yyyy", IC) + " → " + b.To.ToString("ddd dd MMM yyyy", IC) + " · " + b.Sessions + " sessions · 🔁 continuous";
            r.Header = b.ContinuousSummary(); rec.Header = r.Header;
            if (b.StillEval + b.StillFunded > 0) r.Note = "⏳ the END " + b.To.ToString("ddd d MMM yyyy", IC) + ": " + (b.StillEval > 0 ? b.StillEval + " still in eval" : "") + (b.StillEval > 0 && b.StillFunded > 0 ? " · " : "") + (b.StillFunded > 0 ? b.StillFunded + " funded still running" : "") + " (bought before the END, not finished yet)";
            r.Accounts = rec.Accounts.Count; r.Passed = rec.PassedN; r.Blown = rec.EvalBlownN; r.InEval = rec.Accounts.Count(a => a.StillEval); r.Spent = b.Spent;
            r.Wins = rec.Trades.Count(t => t.Pnl > 0); r.Losses = rec.Trades.Count - r.Wins; int ws, ls; Streaks(rec.Trades.OrderBy(t => t.Exit).Select(t => t.Pnl).ToList(), out ws, out ls); r.WinStreak = ws; r.LossStreak = ls;
            r.Months = b.ContinuousMonthTable(eo); r.Eval = b.FirmTable(); r.PerAccount = rec.AccountsTable();
            r.Days.Add(new[] { "DATE", "FIRM", "STAGE", "TRADES", "WON", "LOST", "P/L", "BOUGHT", "PASSED", "BLOWN", "PAYOUTS" });
            var evDay = rec.Events.GroupBy(e => e.Day.Date.ToString("yyyy-MM-dd", IC) + "|" + KeystonePipeline.Nice(e.Firm) + "|" + e.Stage).ToDictionary(g => g.Key, g => g.ToList());
            var keys = rec.Trades.Select(t => t.Day.Date.ToString("yyyy-MM-dd", IC) + "|" + KeystonePipeline.Nice(t.Firm) + "|" + t.Stage).Concat(evDay.Keys).Distinct().OrderBy(k => k, StringComparer.Ordinal).ToList();
            var trDay = rec.Trades.GroupBy(t => t.Day.Date.ToString("yyyy-MM-dd", IC) + "|" + KeystonePipeline.Nice(t.Firm) + "|" + t.Stage).ToDictionary(g => g.Key, g => g.ToList());
            foreach (var k in keys)
            {
                var p = k.Split('|'); List<KeystoneRunRecord.Trade> tr; if (!trDay.TryGetValue(k, out tr)) tr = new List<KeystoneRunRecord.Trade>(); List<KeystoneRunRecord.Event> ev; if (!evDay.TryGetValue(k, out ev)) ev = new List<KeystoneRunRecord.Event>();
                DateTime dd = DateTime.ParseExact(p[0], "yyyy-MM-dd", IC);
                r.Days.Add(new[] { dd.ToString("ddd yyyy-MM-dd", IC), p[1], p[2], tr.Count.ToString(IC), tr.Count(t => t.Pnl > 0).ToString(IC), tr.Count(t => t.Pnl <= 0).ToString(IC), Sg(tr.Sum(t => t.Pnl)), ev.Count(e => e.Kind == "BOUGHT").ToString(IC), ev.Count(e => e.Kind == "PASSED").ToString(IC), ev.Count(e => e.Kind == "BLOWN").ToString(IC), ev.Count(e => e.Kind == "PAYOUT").ToString(IC) });
            }
            r.Trades.Add(new[] { "DATE", "TIME (NEW YORK)", "ACCOUNT", "FIRM", "PHASE", "INSTRUMENT", "SIDE", "CONTRACTS", "ENTRY", "P/L AFTER COSTS", "HOW IT ENDED" });
            foreach (var t in rec.Trades.OrderBy(t => t.Entry)) r.Trades.Add(new[] { t.Day.ToString("yyyy-MM-dd", IC), t.Entry == DateTime.MinValue ? "" : KeystoneLabFlow.Am(t.Entry) + " → " + KeystoneLabFlow.Am(t.Exit), t.Account, KeystonePipeline.Nice(t.Firm), t.Stage, t.Instrument, t.Dir > 0 ? "BUY" : "SELL", t.Qty.ToString(IC), double.IsNaN(t.EntryPx) ? "" : t.EntryPx.ToString("0.00", IC), Sg(t.Pnl), t.How });
            r.BlownRows.Add(new[] { "ACCOUNT", "FIRM", "DATE BLOWN", "STAGE", "PAYOUTS", "STATUS" });
            foreach (var a in rec.Accounts.Where(x => x.Blown).OrderBy(x => x.Ended)) r.BlownRows.Add(new[] { a.Shown, a.FirmNice, a.Ended.ToString("ddd yyyy-MM-dd", IC), a.EvalBlown ? "EVAL" : a.Sprint && a.FundedDays <= 1 ? "FUNDED (⚡ sprint, day 1)" : "FUNDED", a.Payouts.ToString(IC), a.Status });
            r.Stats.Add(new[] { "STAT", "VALUE" }); r.Stats.Add(new[] { "continuous run", b.ContinuousSummary() });
            r.Stats.Add(new[] { "evaluations bought", b.Bought + " (" + M(b.Spent) + ") on " + b.Cohorts + " purchase days · " + b.Slots + " slots, up to " + b.Generations + " accounts in one slot" });
            r.Stats.Add(new[] { "pass rate", (b.Bought == 0 ? "–" : (100.0 * rec.PassedN / b.Bought).ToString("0.0", IC) + " %") + " of the evals bought (" + rec.PassedN + " / " + b.Bought + ") · " + (rec.PassedN + rec.EvalBlownN == 0 ? "–" : (100.0 * rec.PassedN / (rec.PassedN + rec.EvalBlownN)).ToString("0.0", IC) + " %") + " of the finished evals" });
            r.Stats.Add(new[] { "cost per passed account", rec.PassedN > 0 ? M(b.Spent / rec.PassedN) : "– (none passed)" });
            if (!eo)
            {
                r.Stats.Add(new[] { "went funded", b.WentFunded.ToString(IC) }); r.Stats.Add(new[] { "out of pocket (at most)", M(b.OutOfPocket) });
                var sp = rec.Accounts.Where(a => a.Sprint).ToList(); var sf = rec.Accounts.Where(a => a.FundedFrom != DateTime.MinValue && !a.Sprint).ToList();
                if (sp.Count > 0) { r.Stats.Add(new[] { "⚡ sprint accounts", sp.Count + " · " + sp.Count(a => a.Payouts > 0) + " paid · " + M(sp.Sum(a => a.Net)) + " to you · " + sp.Count(a => a.FundedBlown) + " blown (" + sp.Count(a => a.FundedBlown && a.FundedDays <= 1) + " on the first funded day)" }); r.Stats.Add(new[] { "🛟 SAFE (the other funded)", sf.Count + " · " + sf.Count(a => a.Payouts > 0) + " paid · " + M(sf.Sum(a => a.Net)) + " to you · " + sf.Count(a => a.FundedBlown) + " blown" }); }
            }
            if (rec.HasOwners) foreach (var ol in rec.OwnerTable().Skip(1)) r.Stats.Add(new[] { "👥 " + ol[0], ol[1] + " evals (" + ol[2] + ") · " + ol[3] + " passed (" + ol[4] + ") · " + ol[5] + " funded · " + ol[6] + " funded blown · " + ol[8] + " payouts · " + ol[9] + " to you · net " + ol[10] });   /* 👥 BUILD 11f: the split per owner */
            r.FromRecord(rec); r.Trust = rec.Trust; r.Payouts = rec.PayoutN; r.Paid = rec.PaidNet; r.PayoutRows = rec.ByPayout();
            r.Stats.Add(new[] { "money", "spent " + M(r.Spent) + " · paid " + M(r.Paid) + " · net " + Sg(r.Paid - r.Spent) });
            return r;
        }
        public static string Csv(List<string[]> t) { Func<string, string> q = x => "\"" + (x ?? "").Replace("\"", "'") + "\""; return string.Join("\n", (t ?? new List<string[]>()).Select(row => string.Join(",", row.Select(q)))); }
        public string Html()
        {
            Func<string, string> e = x => (x ?? "").Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;");
            Func<string, List<string[]>, string> tbl = (title, t) => t.Count <= 1 ? "" : "<h2>" + e(title) + "</h2><table><tr>" + string.Join("", t[0].Select(h => "<th>" + e(h) + "</th>")) + "</tr>" + string.Join("", t.Skip(1).Select(row => "<tr>" + string.Join("", row.Select(c => "<td>" + e(c) + "</td>")) + "</tr>")) + "</table>";
            return "<!doctype html><html><head><meta charset=\"utf-8\"><title>KeyStone lab results</title><style>body{font-family:Segoe UI,Arial;background:#101418;color:#e6e6e6;margin:24px}h1{color:#f5c542}h2{color:#4fc3f7;margin-top:28px}table{border-collapse:collapse;font-size:13px}td,th{border:1px solid #333;padding:4px 8px;text-align:left}th{background:#1c232b}</style></head><body>"
                + "<h1>🧪 KeyStone lab • " + e(Scope == "BOTH" ? "EVAL → FUNDED → PAYOUTS" : Scope == "FUNDED" ? "FUNDED ONLY" : "EVAL ONLY") + "</h1>" + (Header != "" ? "<p><b>" + e(Header) + "</b></p>" : "") + (Note != "" ? "<p>" + e(Note) + "</p>" : "") + "<p>" + e(Period) + " · " + Accounts + " bought · passed " + Passed + " · blown " + Blown + " · payouts " + Payouts + " · spent " + M(Spent) + " · paid " + M(Paid) + " · net " + Sg(Paid - Spent) + " • simulation only on saved minutes</p>"
                + (Trust != "" ? "<p><i>" + e(Trust) + "</i><br>" + e(KeystoneRunRecord.Verified) + "</p>" : "") + tbl("📅 MONTH BY MONTH", Months) + tbl("🧪 EVAL RESULTS (per firm)", Eval) + tbl("🧪 EVERY ACCOUNT", PerAccount) + tbl("👤 ACCOUNTS", Accounts2) + tbl("💰 FUNDED RESULTS (per firm)", FundedFirm) + tbl("💰 FUNDED ACCOUNTS", FundedAcc) + tbl("💵 EVERY PAYOUT + ITS CYCLE", PayByPayout) + tbl("💵 PAYOUTS BY MONTH", PayByMonth) + tbl("📊 DISTRIBUTIONS", Dist) + tbl("📅 DAYS", Days) + tbl("💀 BLOWN", BlownRows) + tbl("💰 PAYOUTS", PayoutRows) + tbl("📊 STATS", Stats) + tbl("📜 TRADES", Trades) + "</body></html>";
        }
        public string Export(string dir)
        {
