    }
    // 🧠 THE ANALOG % ON THE BUTTONS (BUILD 2026-11-10f): the fingerprint engine (KeystoneAnalog) finds the most similar past moments of the loaded days
    // (earlier days only, ±60 minutes of the time of day); each one is replayed with THIS trade's bracket → "X % reached +TP before the floor (n = …)"
    public static class KeystoneAnalogTrade
    {
        public static List<KeystoneArcBar> Bars(KeystoneRotDay d, int upTo, List<int> slots)
        {
            var b = new List<KeystoneArcBar>(); for (int k = 0; k <= upTo && k < KeystoneRotDay.Slots; k++) { if (!d.HasM(k)) continue; b.Add(new KeystoneArcBar { Time = d.Day.AddMinutes(18 * 60 + k - 1440), Symbol = "MNQ", Open = d.MO[k], High = d.MH[k], Low = d.ML[k], Close = d.MC[k] }); if (slots != null) slots.Add(k); }
            return b;
        }
        public static KeystoneAnalogIndex Index(IList<KeystoneRotDay> days)
        {
            var idx = new KeystoneAnalogIndex(); foreach (var d in (days ?? new List<KeystoneRotDay>()).OrderBy(x => x.Day)) KeystoneAnalog.AddSession(idx, Bars(d, KeystoneRotDay.Slots - 1, null), d.Day); return idx;
        }
        // → (the share that reached +TP first, n replayed) — n = 0 when there is too little history (the caller falls back)
        public static Tuple<double, int> Likelihood(KeystoneAnalogIndex idx, IList<KeystoneRotDay> days, int dayIdx, int mk, int end, int dM, int dG, int qM, int qG, double tg, double sl, int k = 30)
        {
            if (idx == null || days == null || dayIdx < 0 || dayIdx >= days.Count) return Tuple.Create(double.NaN, 0); var d = days[dayIdx]; var slots = new List<int>(); var bars = Bars(d, mk, slots); if (bars.Count <= KeystoneAnalog.Lookback) return Tuple.Create(double.NaN, 0);
            var f = KeystoneAnalog.Fingerprint(bars, bars.Count - 1); if (f == null) return Tuple.Create(double.NaN, 0);
            var ans = KeystoneAnalog.Query(idx, f, bars[bars.Count - 1].Time, KeystoneAnalog.DayKeyOf(d.Day), k, 60); int n = 0, w = 0;
            var byKey = days.ToDictionary(x => KeystoneAnalog.DayKeyOf(x.Day));
            foreach (var id in ans.Ids)
            {
                KeystoneRotDay dd; if (!byKey.TryGetValue(idx.DayKey[id], out dd)) continue; int slot = idx.Tod[id] + 1; if (slot >= end - 1) continue;
                int how, xs; double pk, wr; KeystoneRotationLab.Trade(dd, slot, end, dM, dG, qM, qG, tg, sl, 0, null, out how, out xs, out pk, out wr); if (how == -9) continue; n++; if (how == 1) w++;
            }
            return n == 0 ? Tuple.Create(double.NaN, 0) : Tuple.Create(w / (double)n, n);
        }
    }
    // 📅 THE 2-DAY TEST (BUILD 2026-11-10e): every weekday of a range = a batch that starts that day and runs its 2 sessions (3 with TPT: the tiny trade)
    // — passed / blown / still in eval per start day, by weekday (best / worst) and the distribution of the pass rate (one engine: KeystoneRotationLab.Run)
    public static class KeystoneTwoDay
    {
        public sealed class Row { public DateTime Start; public int N, Passed, Blown; public double PassPct { get { return N == 0 ? 0 : 100.0 * Passed / N; } } }
        public static List<Row> Run(KeystoneSimSettings st, IList<KeystoneRotDay> days, int sh, int eh, bool tpt, Func<bool> cancel = null, Action<int, int> progress = null)
        {
            var res = new List<Row>(); if (st == null || days == null) return res; int need = tpt ? 3 : 2; var ds = days.OrderBy(d => d.Day).ToList();
            for (int i = 0; i + need <= ds.Count; i++)
            {
                if (cancel != null && cancel()) break; var win = ds.Skip(i).Take(need).ToList(); var s0 = st.Copy(); s0.From = win[0].Day; s0.To = win[win.Count - 1].Day;
                var sim = KeystoneRotationLab.Run(s0, win, sh, eh, () => false, null, null); var acc = sim.Accounts.Take(Math.Max(1, s0.Accounts)).ToList();
                res.Add(new Row { Start = win[0].Day, N = acc.Count, Passed = acc.Count(sim.PassedOrPending), Blown = acc.Count(a => !a.Alive && !sim.PassedOrPending(a)) });
                if (progress != null) progress(i + 1, ds.Count - need + 1);
            }
            return res;
        }
        public static KeystoneLabResults Results(List<Row> rows, bool tpt)
        {
            var r = new KeystoneLabResults { Scope = "EVAL" }; var IC = CultureInfo.InvariantCulture; if (rows == null || rows.Count == 0) { r.Period = "no start day with " + (tpt ? 3 : 2) + " saved sessions"; return r; }
            r.From = rows[0].Start; r.To = rows[rows.Count - 1].Start; r.Sessions = rows.Count; r.Period = "📅 2-DAY TEST · " + rows.Count + " start days · " + r.From.ToString("ddd dd MMM yyyy", IC) + " → " + r.To.ToString("ddd dd MMM yyyy", IC) + (tpt ? " (TPT: 3 sessions)" : "");
            r.Accounts = rows.Sum(x => x.N); r.Passed = rows.Sum(x => x.Passed); r.Blown = rows.Sum(x => x.Blown); r.InEval = r.Accounts - r.Passed - r.Blown;
            r.Days.Add(new[] { "START DAY", "WEEKDAY", "ACCOUNTS", "PASSED", "BLOWN", "STILL IN EVAL", "PASS %" });
            foreach (var x in rows) r.Days.Add(new[] { x.Start.ToString("yyyy-MM-dd", IC), x.Start.DayOfWeek.ToString(), x.N.ToString(IC), x.Passed.ToString(IC), x.Blown.ToString(IC), (x.N - x.Passed - x.Blown).ToString(IC), x.PassPct.ToString("0.0", IC) + " %" });
            r.Eval.Add(new[] { "WEEKDAY", "START DAYS", "AVG PASS %", "BEST", "WORST" });
            var wk = rows.GroupBy(x => x.Start.DayOfWeek).OrderBy(g => ((int)g.Key + 6) % 7).ToList();
            foreach (var g in wk) r.Eval.Add(new[] { g.Key.ToString(), g.Count().ToString(IC), g.Average(x => x.PassPct).ToString("0.0", IC) + " %", g.Max(x => x.PassPct).ToString("0", IC) + " %", g.Min(x => x.PassPct).ToString("0", IC) + " %" });
            var best = wk.OrderByDescending(g => g.Average(x => x.PassPct)).First(); var worst = wk.OrderBy(g => g.Average(x => x.PassPct)).First();
            r.Stats.Add(new[] { "STAT", "VALUE" }); r.Stats.Add(new[] { "average pass rate", rows.Average(x => x.PassPct).ToString("0.0", IC) + " % (" + r.Passed + " of " + r.Accounts + ")" });
            r.Stats.Add(new[] { "best weekday to start", best.Key + " · " + best.Average(x => x.PassPct).ToString("0.0", IC) + " %" }); r.Stats.Add(new[] { "worst weekday to start", worst.Key + " · " + worst.Average(x => x.PassPct).ToString("0.0", IC) + " %" });
            foreach (var b in new[] { 0, 10, 20, 30, 40, 50, 60 }) { int lo = b, hi = b == 60 ? 101 : b + 10; r.Stats.Add(new[] { "start days passing " + lo + (b == 60 ? "+ %" : "–" + (hi - 1) + " %"), rows.Count(x => x.PassPct >= lo && x.PassPct < hi) + " " + new string('█', Math.Min(40, rows.Count(x => x.PassPct >= lo && x.PassPct < hi))) }); }
            return r;
        }
    }
    // 📅 the start date → the period: that session + the next (the eval minimum 2), 3 sessions when TPT is in the mix (its 3rd day = the tiny trade) —
    // the next sessions from the saved days when given (holidays skipped), else the weekdays
    public static class KeystoneLabPeriod
    {
        public static DateTime End(DateTime start, bool tpt, IEnumerable<DateTime> saved)
        {
            int need = tpt ? 3 : 2; var sv = saved == null ? new List<DateTime>() : saved.Select(x => x.Date).Where(x => x >= start.Date).Distinct().OrderBy(x => x).ToList();
            if (sv.Count >= need) return sv[need - 1]; var d = start.Date; int got = d.DayOfWeek == DayOfWeek.Saturday || d.DayOfWeek == DayOfWeek.Sunday ? 0 : 1;
            while (got < need) { d = d.AddDays(1); if (d.DayOfWeek != DayOfWeek.Saturday && d.DayOfWeek != DayOfWeek.Sunday) got++; } return d;
        }
    }
    // ● THE LABS' LIVE SIDE (BUILD 2026-11-10d, stage 3) — DETECT + ORGANISE + TRACK only. It reads NinjaTrader's account list (name, connection, balance)
    // and NEVER places an order: ✓ CONFIRM hands the chosen accounts (firm by firm) to ● LIVE TRADING ▸ 🔄 ROTATE, where the existing armed
    // KeystoneAccountLink path (ARM + limits + START ROTATION confirm, MANUAL presses) is the only way an order is sent.
    public sealed class KeystoneLiveAcct { public string Account = "", Connection = "", Firm = "", Stage = "?", Nick = ""; public double Balance, Start, Target = 3000, Today, Dd, Floor; public int Trades, DaysTraded, MinDays = 2; public bool Overridden, Connected = true, Active = true; public string LinkedEval = "", Why = ""; public string Display { get { return Nick != "" ? Nick : Account; } } }
    // one NinjaTrader account as ● LIVE TRADING reads it (ReadNinjaAccounts: NetLiquidation / cash + open, NinjaTrader's realized + open today, its connection
    // status) + its LIVE TRADING profile (the nickname "TPT 13", the firm you set, size / drawdown / target) — the labs reuse exactly these numbers
    public sealed class KeystoneLiveRaw { public string Name = "", Connection = "", Nick = "", Status = "", FirmOverride = ""; public double Balance, Today, Size, Dd, Target; public int Trades; public bool Connected = true; }
    public sealed class KeystoneLiveDay { public DateTime Date; public double StartBal, EndBal, Floor; public int Trades; public double Pnl { get { return EndBal - StartBal; } } }
    public static class KeystoneLabLive
    {
        // the stage keys per firm (upper case, comma separated; editable in Studio\\EvalLab\\live\\patterns.txt), matched on the name's tokens AFTER the firm's prefix — FUNDED keys decide, everything else is EVAL
        public static readonly Dictionary<string, string> FundedKeys = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase) { { "TPT", "PRO,PA-,FUNDED,LIVE" }, { "LUCID", "LFP,FUNDED,PRO,LIVE" }, { "TRADEIFY", "FUNDED,SF,LIVE" }, { "APEX", "PA-" }, { "TOPSTEP", "XFA,EXPRESS" }, { "MFFU", "FUNDED,LIVE" } };
        public static readonly Dictionary<string, string> EvalKeys = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase) { { "TPT", "TPT,TEST,EVAL,TAKEPROFIT" }, { "LUCID", "LT,EVAL,LUCID" }, { "TRADEIFY", "TDFY,EVAL,TRADEIFY" }, { "APEX", "APEX" }, { "TOPSTEP", "S1,TC,COMBINE" }, { "MFFU", "MFFU,EVAL" } };
        public static string SaveKeys() { return string.Join("\n", PrefixKeys.Select(kv => "PREFIX|" + kv.Key + "|" + kv.Value).Concat(FundedKeys.Select(kv => "FUNDED|" + kv.Key + "|" + kv.Value)).Concat(EvalKeys.Select(kv => "EVAL|" + kv.Key + "|" + kv.Value))); }
        public static void LoadKeys(string text) { foreach (var l in (text ?? "").Split('\n')) { var a = l.Trim().Split('|'); if (a.Length != 3 || a[1] == "") continue; if (a[0] == "FUNDED") FundedKeys[a[1]] = a[2].ToUpperInvariant(); else if (a[0] == "EVAL") EvalKeys[a[1]] = a[2].ToUpperInvariant(); else if (a[0] == "PREFIX") PrefixKeys[a[1]] = a[2].ToUpperInvariant(); } }
        public static bool IsProp(string firm) { string f = (firm ?? "").ToUpperInvariant(); return f != "" && f != "SIM" && KeystoneFirmNames.Known.Any(k => k[0] == f && k[0] != "SIM"); }
        // 🔤 the firm's own name prefix, stripped BEFORE the stage keys are matched (every TPT name has "PRO" inside TAKE-PRO-FIT: the prefix goes first,
        // then the keys are matched at the START of the name's remaining tokens) — editable in patterns.txt (PREFIX|firm|…), longest prefix first
        public static readonly Dictionary<string, string> PrefixKeys = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase) { { "TPT", "TAKEPROFITTRADER,TAKEPROFIT,TPT" }, { "LUCID", "LUCIDTRADING,LUCID,LT" }, { "TRADEIFY", "TRADEIFY,TDFY" }, { "APEX", "APEX" }, { "TOPSTEP", "TOPSTEP,TOPX" }, { "MFFU", "MYFUNDEDFUTURES,MYFUNDED,MFFU" } };
        static string[] KeysOf(string keys) { return (keys ?? "").ToUpperInvariant().Split(',').Select(k => k.Trim()).Where(k => k.Length > 0).ToArray(); }
        // the name's tokens after the firm's prefix: "TAKEPROFITPRO999531172" → [PRO999531172] • "TAKEPROFIT104385428" → [104385428] • "MFFUEVREOD7235" → [EVREOD7235] • "PRO98765-TPT" → [PRO98765, TPT]
        public static List<string> Tokens(string firm, string account)
        {
            var parts = (account ?? "").ToUpperInvariant().Split(new[] { '-', '_', ' ', '.', '/', '#', '|' }, StringSplitOptions.RemoveEmptyEntries).ToList(); if (parts.Count == 0) return parts;
            string pk; if (PrefixKeys.TryGetValue(firm ?? "", out pk)) { var pre = KeysOf(pk).OrderByDescending(k => k.Length).FirstOrDefault(k => parts[0].StartsWith(k)); if (pre != null) { parts[0] = parts[0].Substring(pre.Length); if (parts[0] == "") parts.RemoveAt(0); } }
            return parts;
        }
        // a key matches a token at its start ("PRO" ↔ PRO999…); a key written with a dash ("PA-") must be a whole token
        static bool Has(List<string> tokens, string keys) { return KeysOf(keys).Any(k => k.EndsWith("-") ? tokens.Any(t => t == k.TrimEnd('-')) : tokens.Any(t => t.StartsWith(k))); }
        // EVAL unless a FUNDED key matches the name after the firm's prefix — never FUNDED by accident (unsure = EVAL; the one-click override fixes the rest)
        public static string Stage(string firm, string account)
        {
            var tk = Tokens(firm, account); string fk; if (FundedKeys.TryGetValue(firm ?? "", out fk) && Has(tk, fk)) return "FUNDED"; return "EVAL";
        }
        // the account's starting size from its balance (25K / 50K / 100K / 150K: the nearest one it can be in, a drawdown below to a target above)
        public static double StartOf(double bal) { var sizes = new[] { 25000.0, 50000, 100000, 150000 }; foreach (var sz in sizes) if (bal >= sz - 6000 && bal <= sz + 12000) return sz; return bal > 0 ? Math.Round(bal / 25000) * 25000 : 0; }
        public static KeystoneSimRules RulesOf(string firm)
        {
            string f = (firm ?? "").ToUpperInvariant(); var all = KeystoneSimRules.Presets();
            var r = all.FirstOrDefault(x => f == "TPT" ? x.Name.StartsWith("TAKE PROFIT") : f != "" && x.Name.ToUpperInvariant().StartsWith(f)); return r ?? all.First();
        }
        // NinjaTrader's accounts (name, connection, balance, today, trades today) + the saved overrides (account → EVAL / FUNDED / firm) → the prop accounts
        public static List<KeystoneLiveAcct> Classify(IEnumerable<Tuple<string, string, double, double, int>> snaps, IDictionary<string, string> stageOverride, IDictionary<string, int> daysTraded)
        {
            return Classify((snaps ?? Enumerable.Empty<Tuple<string, string, double, double, int>>()).Select(sn => new KeystoneLiveRaw { Name = sn.Item1, Connection = sn.Item2, Balance = sn.Item3, Today = sn.Item4, Trades = sn.Item5 }), stageOverride, daysTraded);
        }
        public static List<KeystoneLiveAcct> Classify(IEnumerable<KeystoneLiveRaw> snaps, IDictionary<string, string> stageOverride, IDictionary<string, int> daysTraded)
        {
            var res = new List<KeystoneLiveAcct>();
            foreach (var sn in snaps ?? Enumerable.Empty<KeystoneLiveRaw>())
            {
                if (sn == null) continue; var fd = KeystoneFirmNames.Detect(sn.Name, sn.Connection, string.IsNullOrWhiteSpace(sn.FirmOverride) ? null : sn.FirmOverride); if (!IsProp(fd[0])) continue;
                var a = new KeystoneLiveAcct { Account = sn.Name, Connection = sn.Connection, Firm = fd[0], Balance = double.IsNaN(sn.Balance) ? 0 : sn.Balance, Today = double.IsNaN(sn.Today) ? 0 : sn.Today, Trades = sn.Trades, Nick = sn.Nick ?? "", Connected = sn.Connected };
                string ov; if (stageOverride != null && stageOverride.TryGetValue(a.Account, out ov) && (ov == "EVAL" || ov == "FUNDED")) { a.Stage = ov; a.Overridden = true; } else a.Stage = Stage(a.Firm, a.Account);
                // size / drawdown / target: the LIVE TRADING profile first, then the firm preset LIVE TRADING guesses from the name, then the balance
                KeystoneFirmPreset g = null; try { g = KeystoneFirmRules.Guess(a.Account); } catch { } if (g != null && !string.Equals(KeystoneFirmNames.Detect("", "", g.Firm)[0], a.Firm, StringComparison.OrdinalIgnoreCase)) g = null;
                var r = RulesOf(a.Firm); a.Start = sn.Size > 0 ? sn.Size : g != null && g.Size > 0 ? g.Size : StartOf(a.Balance); if (a.Start <= 0) a.Start = 50000;
                double scale = Math.Max(0.5, a.Start / 50000.0);
                a.Target = sn.Target > 0 ? sn.Target : g != null && g.Target > 0 && Math.Abs(g.Size - a.Start) < 1 ? g.Target : r.Target * scale;
                a.Dd = sn.Dd > 0 ? sn.Dd : g != null && g.Dd > 0 && Math.Abs(g.Size - a.Start) < 1 ? g.Dd : (a.Stage == "FUNDED" ? r.FundDrawdown : r.EvalDrawdown) * scale;
                a.Floor = a.Start - a.Dd; a.MinDays = r.EvalMinDays; int dt; if (daysTraded != null && daysTraded.TryGetValue(a.Account, out dt)) a.DaysTraded = dt;
                a.Why = InactiveWhy(a, sn.Status); a.Active = a.Why == "";
                res.Add(a);
            }
            return res;
        }
        // why an account is NOT active (empty = active): disconnected • disabled at the firm • a 0 / unknown balance • blown (at or under its floor)
        public static string InactiveWhy(KeystoneLiveAcct a, string status = "")
        {
            if (a == null) return "unknown"; string st = (status ?? "").ToUpperInvariant();
            if (!a.Connected) return "disconnected";
            if (st.Contains("DISABL") || st.Contains("LIQUIDAT") || st.Contains("HALT") || st.Contains("CLOSED") || st.Contains("INACTIVE") || st.Contains("BLOWN")) return "disabled at the firm (" + status + ")";
            if (double.IsNaN(a.Balance) || a.Balance <= 0) return "balance 0 / unknown";
            if (a.Floor > 0 && a.Balance <= a.Floor + 0.5) return "blown (balance " + M(a.Balance) + " at or under the floor " + M(a.Floor) + ")";
            return "";
        }
        public static List<KeystoneLiveAcct> ActiveOnly(IEnumerable<KeystoneLiveAcct> acc) { return (acc ?? Enumerable.Empty<KeystoneLiveAcct>()).Where(a => a.Active).ToList(); }
        public static List<KeystoneLiveAcct> InactiveOnly(IEnumerable<KeystoneLiveAcct> acc) { return (acc ?? Enumerable.Empty<KeystoneLiveAcct>()).Where(a => !a.Active).ToList(); }
        // the short progress of a row: "$229 to pass · days 1/3" (eval) • "qualifying days 2/5 · $650 to go" / "payout ready" (funded)
        public static string ShortProgress(KeystoneLiveAcct a, IList<KeystoneLiveDay> days = null)
        {
            if (a == null) return ""; double p = a.Balance - a.Start;
            if (a.Stage == "FUNDED")
            {
                var pr = KeystonePayoutRules.For(a.Firm, KeystonePayoutRules.Presets()); if (pr == null) return (p >= 0 ? "+" : "−") + M(p) + " since the funded start";
                if (pr.Tpt) { double needT = Math.Max(0, pr.Dd + pr.Cap - p); return "no qualifying days (TPT PRO) · " + (needT <= 0 ? "payout ready" : M(needT) + " to go (the " + M(pr.Dd) + " buffer + a " + M(pr.Cap) + " payout)"); }
                int q = (days ?? new List<KeystoneLiveDay>()).Count(x => x.Trades > 0 && x.Pnl >= pr.QualMin - 1e-9); double need = Math.Max(0, pr.MinPayout - Math.Max(0, p));
                return "qualifying days " + Math.Min(q, pr.QualDays) + "/" + pr.QualDays + " · " + (q >= pr.QualDays && need <= 0 ? "payout ready" : need > 0 ? M(need) + " to go" : (pr.QualDays - q) + " more day(s)");
            }
            if (TargetReached(a)) return "✅ target reached · waiting for the firm";
            return (p >= a.Target ? "target made" : M(a.Target - p) + " to pass") + " · days " + a.DaysTraded + "/" + a.MinDays;
        }
        // the plan of a group in plain words: "MNQ 20 · take profit +$1,500 · no stop (rides to the floor) · at 2:00 / 8:30 / 9:30 / 10:00 / 11:00 NY · TPT = manual: its button flashes"
        public static string PlanWords(IDictionary<string, string> m, bool tpt)
        {
            Func<string, string> g = k => { string v; return m != null && m.TryGetValue(k, out v) ? (v ?? "").Trim() : ""; };
            var times = g("times").Split(new[] { ' ', ',', ';' }, StringSplitOptions.RemoveEmptyEntries).Select(t => { int hm; return int.TryParse(t, out hm) ? (hm / 100) + ":" + (hm % 100).ToString("00") : t; }).ToList();
            double tp, st; double.TryParse(g("tp"), NumberStyles.Float, CultureInfo.InvariantCulture, out tp); double.TryParse(g("stop"), NumberStyles.Float, CultureInfo.InvariantCulture, out st);
            return "MNQ " + (g("mnq") == "" ? "?" : g("mnq")) + " · take profit +" + M(tp) + " · " + (st <= 0 ? "no stop (rides to the floor)" : "stop −" + M(st)) + (times.Count > 0 ? " · at " + string.Join(" / ", times) + " NY" : "") + (g("side") != "" && g("side") != "FIRM" ? " · side " + g("side") : "") + (tpt ? " · TPT = manual: its button flashes" : " · manual: you press each entry");
        }
        static string M(double v) { return "$" + Math.Round(Math.Abs(v)).ToString("N0", CultureInfo.InvariantCulture); }
        public static bool TargetReached(KeystoneLiveAcct a) { return a != null && a.Stage != "FUNDED" && a.Balance - a.Start >= a.Target - 0.5 && a.DaysTraded >= a.MinDays; }
        // "+$2,800 / $3,000 · $200 to go" • "✅ target reached: waiting for the firm to move it to funded"
        public static string Progress(KeystoneLiveAcct a)
        {
            if (a == null) return ""; double p = a.Balance - a.Start;
            if (a.Stage == "FUNDED") return (p >= 0 ? "+" : "−") + M(p) + " since the funded start" + (a.LinkedEval != "" ? " · was " + a.LinkedEval : "");
            if (TargetReached(a)) return "✅ target reached: waiting for the firm to move it to funded";
            return (p >= 0 ? "+" : "−") + M(p) + " / " + M(a.Target) + " · " + (p >= a.Target ? "target made · " + Math.Max(0, a.MinDays - a.DaysTraded) + " more day(s) needed" : M(a.Target - p) + " to go") + (a.MinDays > 0 ? " · days " + a.DaysTraded + "/" + a.MinDays : "");
        }
        // the ● LIVE button's label: "● LIVE · 1 TPT eval" — ACTIVE accounts only (empty = nothing active: the button stays grey)
        public static string Badge(IList<KeystoneLiveAcct> acc)
        {
            var act = ActiveOnly(acc); if (act.Count == 0) return ""; return "● LIVE · " + string.Join(" · ", act.GroupBy(a => a.Firm + "|" + a.Stage).Select(g => g.Count() + " " + KeystonePipeline.Nice(g.First().Firm) + " " + (g.First().Stage == "FUNDED" ? "funded" : g.First().Stage == "EVAL" ? "eval" : "account") + (g.Count() > 1 ? "s" : "")));
        }
        // one pool per firm per stage ("TPT · EVAL", "TPT · FUNDED" …), firms in the known order
        public static List<Tuple<string, List<KeystoneLiveAcct>>> Pools(IList<KeystoneLiveAcct> acc)
        {
            var order = KeystoneFirmNames.Known.Select(k => k[0]).ToList();
            return (acc ?? new List<KeystoneLiveAcct>()).GroupBy(a => a.Firm + " · " + (a.Stage == "?" ? "EVAL?" : a.Stage)).OrderBy(g => order.IndexOf(g.First().Firm) < 0 ? 99 : order.IndexOf(g.First().Firm)).ThenBy(g => g.First().Stage == "FUNDED" ? 1 : 0).Select(g => Tuple.Create(g.Key, g.OrderBy(a => a.Account).ToList())).ToList();
        }
        // ➕ YOUR GROUPS ("name|acc1,acc2" per line): a group can mix firms and keeps its own plan; an account is in one group only (the first one)
        public static List<Tuple<string, List<string>>> ParseGroups(string text)
        {
            var res = new List<Tuple<string, List<string>>>(); var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var l in (text ?? "").Split('\n')) { var a = l.Trim().Split('|'); if (a.Length != 2 || a[0].Trim() == "" || res.Any(x => string.Equals(x.Item1, a[0].Trim(), StringComparison.OrdinalIgnoreCase))) continue; var m = a[1].Split(',').Select(x => x.Trim()).Where(x => x != "" && seen.Add(x)).ToList(); if (m.Count > 0) res.Add(Tuple.Create(a[0].Trim(), m)); }
            return res;
        }
        public static string GroupsText(IEnumerable<Tuple<string, List<string>>> groups) { return string.Join("\n", (groups ?? Enumerable.Empty<Tuple<string, List<string>>>()).Where(g => g.Item2.Count > 0).Select(g => g.Item1.Replace("|", "/").Replace(",", " ") + "|" + string.Join(",", g.Item2))); }
        // the cards of YOUR ACTIVE ACCOUNTS: your own groups first ("GROUP:name"), then one automatic group per firm + stage for the rest ("TPT · EVAL")
        public static List<Tuple<string, string, List<KeystoneLiveAcct>>> Groups(IList<KeystoneLiveAcct> active, IList<Tuple<string, List<string>>> custom)
        {
            var res = new List<Tuple<string, string, List<KeystoneLiveAcct>>>(); var act = ActiveOnly(active); var used = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var g in custom ?? new List<Tuple<string, List<string>>>()) { var m = act.Where(a => g.Item2.Contains(a.Account, StringComparer.OrdinalIgnoreCase) && !used.Contains(a.Account)).OrderBy(a => a.Display).ToList(); if (m.Count == 0) continue; foreach (var a in m) used.Add(a.Account); res.Add(Tuple.Create("GROUP:" + g.Item1, g.Item1, m)); }
            foreach (var p in Pools(act.Where(a => !used.Contains(a.Account)).ToList())) res.Add(Tuple.Create(p.Item1, p.Item1, p.Item2.OrderBy(a => a.Display).ToList()));
            return res;
        }
        // the rotation order of the ticked accounts = the backtest's rule (firm by firm)
        public static List<string> Order(IEnumerable<KeystoneLiveAcct> picked) { return KeystoneLabFlow.Interleave(picked ?? Enumerable.Empty<KeystoneLiveAcct>(), a => a.Firm).Select(a => a.Account).ToList(); }
        // a FUNDED account that appears for a firm whose eval reached its target → linked to that eval's record (the first one waiting)
        public static void LinkFunded(IList<KeystoneLiveAcct> acc, IList<Tuple<string, string>> passedEvals /* (firm, eval account) */, IDictionary<string, string> links)
        {
            if (acc == null || links == null) return;
            foreach (var f in acc.Where(a => a.Stage == "FUNDED"))
            {
                string old; if (links.TryGetValue(f.Account, out old)) { f.LinkedEval = old; continue; }
                var ev = (passedEvals ?? new List<Tuple<string, string>>()).FirstOrDefault(x => string.Equals(x.Item1, f.Firm, StringComparison.OrdinalIgnoreCase) && !links.Values.Contains(x.Item2));
                if (ev != null) { links[f.Account] = ev.Item2; f.LinkedEval = ev.Item2; }
            }
        }
        // 📅 the daily tracking (one row per account per day): the first balance seen today = the start, the latest = the end
        public const string DayHeader = "date,start_balance,end_balance,pnl,trades,floor";
        public static string DayLine(KeystoneLiveDay d) { var ic = CultureInfo.InvariantCulture; return string.Join(",", d.Date.ToString("yyyy-MM-dd", ic), d.StartBal.ToString("0.##", ic), d.EndBal.ToString("0.##", ic), d.Pnl.ToString("0.##", ic), d.Trades, d.Floor.ToString("0.##", ic)); }
        public static List<KeystoneLiveDay> ParseDays(string csv)
        {
            var res = new List<KeystoneLiveDay>(); var ic = CultureInfo.InvariantCulture;
            foreach (var l in (csv ?? "").Split('\n').Skip(1)) { var a = l.Trim().Split(','); if (a.Length < 6) continue; try { res.Add(new KeystoneLiveDay { Date = DateTime.ParseExact(a[0], "yyyy-MM-dd", ic), StartBal = double.Parse(a[1], ic), EndBal = double.Parse(a[2], ic), Trades = int.Parse(a[4], ic), Floor = double.Parse(a[5], ic) }); } catch { } }
            return res;
        }
        public static void Upsert(List<KeystoneLiveDay> days, DateTime date, double bal, int trades, double floor)
        {
            var d = days.FirstOrDefault(x => x.Date == date.Date); if (d == null) { var prev = days.Where(x => x.Date < date.Date).OrderBy(x => x.Date).LastOrDefault(); d = new KeystoneLiveDay { Date = date.Date, StartBal = prev != null ? prev.EndBal : bal }; days.Add(d); days.Sort((x, y) => x.Date.CompareTo(y.Date)); }
            d.EndBal = bal; d.Trades = Math.Max(d.Trades, trades); d.Floor = floor;
        }
        public static string DaysCsv(IList<KeystoneLiveDay> days) { return DayHeader + "\n" + string.Join("\n", (days ?? new List<KeystoneLiveDay>()).Select(DayLine)); }
        // ✅ ELIGIBILITY (funded, the payout rules of the firm): qualifying days n / N, the profit still needed for the max payout, the earliest payout date
        public static string Eligibility(IList<KeystoneLiveDay> days, KeystonePayoutRules r, double start, DateTime today)
        {
            if (r == null) return ""; var ds = (days ?? new List<KeystoneLiveDay>()).OrderBy(x => x.Date).ToList(); int q = ds.Count(x => x.Trades > 0 && x.Pnl >= r.QualMin - 1e-9);
            double bal = ds.Count > 0 ? ds[ds.Count - 1].EndBal - start : 0; double maxBal = r.Pct > 0 ? r.Cap / (r.Pct / 100.0) : 0; double need = Math.Max(0, maxBal - bal);
            var d = today.Date; int left = Math.Max(0, r.QualDays - q); while (left > 0) { d = d.AddDays(1); if (d.DayOfWeek != DayOfWeek.Saturday && d.DayOfWeek != DayOfWeek.Sunday) left--; }
            return "qualifying days " + q + "/" + r.QualDays + " (≥ " + M(r.QualMin) + ") · " + (need > 0 ? M(need) + " more profit for the max payout" : "the max payout is reachable") + " · earliest payout " + (q >= r.QualDays ? "now" : d.ToString("ddd d MMM", CultureInfo.InvariantCulture));
        }
    }
    // 🪑 BENCH (the user's rule): at most 5 active funded accounts per prop firm — the extra passed ones wait on the bench (first in, first out)
    // and replace an active account of the same firm that is lost (blown) or finished (moved to live)
    public sealed class KeystoneBench
    {
        public int MaxPerFirm = 5;
        public readonly List<Tuple<string, string>> Active = new List<Tuple<string, string>>();   // (name, firm)
        public readonly List<Tuple<string, string>> Bench = new List<Tuple<string, string>>();
        public readonly List<string> Log = new List<string>();
        static string F(string firm) { return (firm ?? "").Trim().ToUpperInvariant(); }
        public int ActiveOf(string firm) { return Active.Count(x => F(x.Item2) == F(firm)); }
        public int LimitOf(string firm) { var bk = KeystonePayoutRules.BookOf(firm); return bk != null && bk.MaxFunded > 0 ? bk.MaxFunded : MaxPerFirm; }   /* 🏢 each firm's own max funded accounts */
        // a passed account arrives: active when its firm has room, else on the bench → true = active
        public bool Add(string name, string firm)
        {
            if (Active.Any(x => x.Item1 == name) || Bench.Any(x => x.Item1 == name)) return Active.Any(x => x.Item1 == name);
            if (ActiveOf(firm) < LimitOf(firm)) { Active.Add(Tuple.Create(name, firm)); Log.Add(name + " → FUNDED (" + F(firm) + " " + ActiveOf(firm) + " / " + LimitOf(firm) + ")"); return true; }
            Bench.Add(Tuple.Create(name, firm)); Log.Add(name + " → 🪑 BENCH (" + F(firm) + " already has " + LimitOf(firm) + " funded)"); return false;
        }
        // an active account ends (blown / moved to live): the first benched account of the same firm takes its place → its name or null
        public string Remove(string name, string why)
        {
            var a = Active.FirstOrDefault(x => x.Item1 == name); if (a == null) { Bench.RemoveAll(x => x.Item1 == name); return null; }
            Active.Remove(a); Log.Add(name + " out (" + why + ")");
            var b = Bench.FirstOrDefault(x => F(x.Item2) == F(a.Item2)); if (b == null) return null;
            Bench.Remove(b); Active.Add(b); Log.Add(b.Item1 + " 🪑 → FUNDED (replaces " + name + ")"); return b.Item1;
        }
    }
    // 👥 OWNERS (BUILD 2026-11-11f, the user's request: the accounts are split between him and his wife) — an owner per account (default "ME" / "WIFE",
    // editable, more allowed), saved as owners.txt (OWNER|name, ACC|account|owner) • a LIMIT per owner per firm: max accounts in eval and max funded (🏢 FIRMS & RULES,
    // default 5 each) — a warning when a new account would exceed it • the labs: "2 owners × 5 per firm" → the slots (LUCID 1–5 = ME, LUCID 6–10 = WIFE) and the
    // funded seats per owner. Pure (no UI), read only: nothing here places or blocks an order.
    public sealed class KeystoneOwners
    {
        public const int DefaultMax = 5;
        public List<string> Names = new List<string> { "ME", "WIFE" };
        public readonly Dictionary<string, string> Of = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);   /* account → owner */
        public static string Clean(string x) { return (x ?? "").Replace("|", " ").Replace(",", " ").Replace("\n", " ").Replace("\r", " ").Trim().ToUpperInvariant(); }
        public string First { get { return Names.Count > 0 ? Names[0] : "ME"; } }
        // the account's owner (not assigned yet = the first owner)
        public string OwnerOf(string account) { string o; return account != null && Of.TryGetValue(account, out o) && Names.Contains(o) ? o : First; }
        public bool Assigned(string account) { string o; return account != null && Of.TryGetValue(account, out o) && Names.Contains(o); }
        public void Set(string account, string owner) { string o = Clean(owner); if (string.IsNullOrEmpty(account) || o == "") return; if (!Names.Contains(o)) Names.Add(o); Of[account] = o; }
        // ONE CLICK: the next owner (ME → WIFE → … → ME), saved by the caller
        public string Next(string account) { if (Names.Count == 0) Names.Add("ME"); int i = Names.IndexOf(OwnerOf(account)); string n = Names[(i + 1) % Names.Count]; Of[account] = n; return n; }
        public bool AddName(string name) { string n = Clean(name); if (n == "" || Names.Contains(n)) return false; Names.Add(n); return true; }
        public bool Rename(string from, string to)
        {
            string a = Clean(from), b = Clean(to); int i = Names.IndexOf(a); if (i < 0 || b == "" || (b != a && Names.Contains(b))) return false; Names[i] = b;
            foreach (var k in Of.Keys.ToList()) if (Of[k] == a) Of[k] = b; return true;
        }
        public bool Remove(string name) { string a = Clean(name); if (Names.Count <= 1 || !Names.Remove(a)) return false; foreach (var k in Of.Keys.ToList()) if (Of[k] == a) Of.Remove(k); return true; }
        public string Save() { return string.Join("\n", Names.Select(n => "OWNER|" + n).Concat(Of.OrderBy(kv => kv.Key).Select(kv => "ACC|" + kv.Key.Replace("|", " ") + "|" + kv.Value))); }
        public static KeystoneOwners Load(string text)
        {
            var o = new KeystoneOwners(); var names = new List<string>();
            foreach (var l in (text ?? "").Split('\n')) { var a = l.TrimEnd('\r').Split('|'); if (a[0] == "OWNER" && a.Length >= 2) { string n = Clean(a[1]); if (n != "" && !names.Contains(n)) names.Add(n); } else if (a[0] == "ACC" && a.Length >= 3 && a[1].Trim() != "") o.Of[a[1].Trim()] = Clean(a[2]); }
            if (names.Count > 0) o.Names = names; foreach (var v in o.Of.Values.Distinct().ToList()) if (v != "" && !o.Names.Contains(v)) o.Names.Add(v); return o;
        }
        // 🏢 the limits per owner per firm (FIRMS & RULES; default 5 each)
        public static int MaxEval(string firm) { var bk = KeystonePayoutRules.BookOf(firm); return bk != null && bk.OwnerMaxEval > 0 ? bk.OwnerMaxEval : DefaultMax; }
        public static int MaxFunded(string firm) { var bk = KeystonePayoutRules.BookOf(firm); return bk != null && bk.OwnerMaxFunded > 0 ? bk.OwnerMaxFunded : DefaultMax; }
        public static int LimitOf(string firm, string stage) { return stage == "FUNDED" ? MaxFunded(firm) : MaxEval(firm); }
        // the accounts (owner, firm, stage) → one line per owner · firm · stage over its limit ("" lines are never returned)
        public static List<string> Over(IEnumerable<Tuple<string, string, string>> accounts)
        {
            var res = new List<string>();
            foreach (var g in (accounts ?? Enumerable.Empty<Tuple<string, string, string>>()).GroupBy(x => x.Item1 + "|" + (x.Item2 ?? "").ToUpperInvariant() + "|" + (x.Item3 == "FUNDED" ? "FUNDED" : "EVAL")))
            {
                var p = g.Key.Split('|'); int lim = LimitOf(p[1], p[2]); if (g.Count() > lim) res.Add("⚠ " + p[0] + " has " + g.Count() + " " + KeystonePipeline.Nice(p[1]) + " " + (p[2] == "FUNDED" ? "funded" : "eval") + " accounts — over the limit of " + lim + " per owner (🏢 FIRMS & RULES)");
            }
            return res;
        }
        // a NEW account for owner / firm / stage, with the accounts already there → the warning ("" = within the limit)
        public static string CheckNew(string owner, string firm, string stage, IEnumerable<Tuple<string, string, string>> existing)
        {
            string st = stage == "FUNDED" ? "FUNDED" : "EVAL"; int lim = LimitOf(firm, st);
            int n = (existing ?? Enumerable.Empty<Tuple<string, string, string>>()).Count(x => x.Item1 == owner && string.Equals(x.Item2, firm, StringComparison.OrdinalIgnoreCase) && (x.Item3 == "FUNDED" ? "FUNDED" : "EVAL") == st);
            return n + 1 > lim ? "⚠ a new " + KeystonePipeline.Nice(firm) + " " + (st == "FUNDED" ? "funded" : "eval") + " account for " + owner + " would be " + (n + 1) + " — over the limit of " + lim + " per owner (🏢 FIRMS & RULES)" : "";
        }
        // 🧪 the labs: the slot's owner from its number within its firm ("LUCID 7", perOwner 5 → the 2nd owner) — no number / no owners = ""
        public static string SlotOwner(string slot, int perOwner, IList<string> names)
        {
            if (names == null || names.Count == 0 || perOwner <= 0 || string.IsNullOrEmpty(slot)) return ""; string s = slot.Split('·')[0].Trim().TrimEnd('\''); int e = s.Length, b = e, n;
            while (b > 0 && char.IsDigit(s[b - 1])) b--; if (b == e || b == 0 || !(s[b - 1] == ' ' || s[b - 1] == '-') || !int.TryParse(s.Substring(b), NumberStyles.Integer, CultureInfo.InvariantCulture, out n) || n < 1) return "";
            return names[Math.Min(names.Count - 1, (n - 1) / perOwner)];
        }
        // the owners of a lab run: the saved names first, then OWNER 3, OWNER 4 …
        public static List<string> NamesFor(int count, IList<string> saved)
        {
            var l = new List<string>(); for (int i = 0; i < Math.Max(0, count); i++) l.Add(saved != null && i < saved.Count ? saved[i] : i == 0 ? "ME" : i == 1 ? "WIFE" : "OWNER " + (i + 1)); return l;
        }
        public static string SplitText(int owners, int perFirm) { return owners + " owner" + (owners == 1 ? "" : "s") + " × " + perFirm + " per firm = " + (owners * perFirm) + " accounts per firm"; }
    }
    // 🧭 the labs' STEP-BY-STEP SETUP WIZARD: ① accounts → ② plan → ③ days → ④ how to watch → ⑤ START • a step opens only when every step before it
    // is done (✓ + its one-line summary) • ← BACK re-opens the step before • editing a done step keeps the later ones (their summaries stay)
    public sealed class KeystoneLabWizard
    {
        public static readonly string[] Steps = { "ACCOUNTS", "PLAN", "DAYS", "WATCH", "START" };
        public int Step; public readonly bool[] Done = new bool[5]; public readonly string[] Summary = { "", "", "", "", "" }; public readonly bool[] Auto = new bool[5];   /* a step filled by itself (the funded days from the eval): skipped on the way */
        public bool CanOpen(int i) { if (i < 0 || i >= Steps.Length) return false; for (int j = 0; j < i; j++) if (!Done[j]) return false; return true; }
        public bool Open(int i) { if (!CanOpen(i)) return false; Step = i; return true; }
        public bool Complete(int i, string summary) { if (!CanOpen(i)) return false; Done[i] = true; Summary[i] = summary ?? ""; Step = Math.Min(Steps.Length - 1, i + 1); while (Step < Steps.Length - 1 && Auto[Step] && Done[Step]) Step++; return true; }
        public void Back() { if (Step > 0) Step--; }
        public bool Ready { get { return CanOpen(4); } }
        // ③ DAYS: at least 2 trading days — one picked day becomes that day + the next weekday
        public static DateTime TwoDaysEnd(DateTime from, DateTime to)
        {
            if (to.Date > from.Date) return to.Date; var t = from.Date.AddDays(1); while (t.DayOfWeek == DayOfWeek.Saturday || t.DayOfWeek == DayOfWeek.Sunday) t = t.AddDays(1); return t;
        }
        // ① a simulated mix: n accounts spread over the firms in round robin (TPT 1, LUCID 1, TRADEIFY 1, TPT 2 …)
        public static List<KeystoneEvalAccount> Mix(int n, IList<string> firms)
        {
            var res = new List<KeystoneEvalAccount>(); var fs = (firms ?? new List<string>()).Where(x => !string.IsNullOrWhiteSpace(x)).Select(x => x.Trim().ToUpperInvariant()).ToList(); if (fs.Count == 0) fs.Add("TPT");
            for (int i = 0; i < Math.Max(0, n); i++) { string f = fs[i % fs.Count]; res.Add(new KeystoneEvalAccount { Firm = f, Size = 50, Nick = f + " " + (i / fs.Count + 1) }); }
            return res;
        }
        // ① ACCOUNTS PER FIRM (the user's request: "5 per firm, changeable"): each firm its own count (1–50), dealt firm by firm (TPT 1, Lucid 1, Tradeify 1, TPT 2 …)
        public static List<KeystoneEvalAccount> Mix(IList<Tuple<string, int>> perFirm)
        {
            var res = new List<KeystoneEvalAccount>(); if (perFirm == null) return res;
            var fs = perFirm.Where(x => x != null && !string.IsNullOrWhiteSpace(x.Item1) && x.Item2 > 0).Select(x => Tuple.Create(x.Item1.Trim().ToUpperInvariant(), Math.Min(50, x.Item2))).ToList();
            int most = fs.Count == 0 ? 0 : fs.Max(x => x.Item2);
            for (int j = 1; j <= most; j++) foreach (var f in fs) if (j <= f.Item2) { var bk = KeystonePayoutRules.BookOf(f.Item1); res.Add(new KeystoneEvalAccount { Firm = f.Item1, Size = bk != null && bk.Studio ? bk.Size : 50, Nick = f.Item1 + " " + j }); }   /* 🎬 a Studio firm's own size ($20K …) */
            return res;
        }
        // "15 = 5 TPT + 5 Lucid + 5 Tradeify"
        public static string TotalText(IList<Tuple<string, int>> perFirm)
        {
            var fs = (perFirm ?? new List<Tuple<string, int>>()).Where(x => x != null && x.Item2 > 0).ToList(); int n = fs.Sum(x => Math.Min(50, x.Item2));
            return n + " = " + (fs.Count == 0 ? "no firm ticked" : string.Join(" + ", fs.Select(x => Math.Min(50, x.Item2) + " " + KeystonePipeline.Nice(x.Item1))));
        }
    }
    // 💰 the funded model of a firm (the tiles say "firm · model"): Lucid / Tradeify = EOD trailing $2,000 locking at +$100 + the payout cycle •
    // TPT PRO = intraday trailing until the floor locks, then withdrawals (parked only when the firm book says so)
    public static class KeystoneFundedModel
    {
        public static string Of(string firm, KeystonePayoutRules r)
        {
            string f = (firm ?? "").Trim().ToUpperInvariant(); string nm = f == "TPT" ? "TPT" : f == "LUCID" ? "Lucid" : f == "TRADEIFY" ? "Tradeify" : f;
            if (r == null || r.Parked) return nm + " · parked — the TPT trailing plan is a separate choice";
            if (r.Tpt) return nm + " · 🔒 intraday trailing $" + r.Dd.ToString("N0", CultureInfo.InvariantCulture) + " incl. open profit until +$" + r.Dd.ToString("N0", CultureInfo.InvariantCulture) + " locks the floor at the start → withdrawals that keep the $" + r.Dd.ToString("N0", CultureInfo.InvariantCulture) + " buffer (" + r.Split.ToString("0", CultureInfo.InvariantCulture) + " %; 🛟 SAFE: $1,000 at +$3,000)";
            return nm + " · EOD trailing $" + r.Dd.ToString("N0", CultureInfo.InvariantCulture) + " → locks at +$" + r.LockAt.ToString("N0", CultureInfo.InvariantCulture) + " · payout cycle";
        }
        // the top line: "5 funded accounts that passed the eval: 2 Lucid, 2 Tradeify, 1 TPT parked (+ 3 on the 🪑 bench)"
        public static string TopLine(IList<KeystonePayoutAccount> acc, int benched, bool fromEval)
        {
            var g = acc.GroupBy(a => (a.Firm ?? "").ToUpperInvariant()).Select(x => x.Count() + " " + (x.Key == "LUCID" ? "Lucid" : x.Key == "TRADEIFY" ? "Tradeify" : x.Key) + (x.All(a => a.Stage == "PARKED") ? " parked" : "")).ToList();
            return acc.Count + " funded account" + (acc.Count == 1 ? "" : "s") + (fromEval ? " that passed the eval" : " (a simulated mix)") + ": " + string.Join(", ", g) + (benched > 0 ? " (+ " + benched + " on the 🪑 bench)" : "");
        }
    }
    // 🔁 BUILD 2026-11-11a (items 8 + 31 + 5): ONE BATCH bought on the start date, blown accounts are not replaced (the BUSINESS RUN comes later) —
    // the eval runs day after day until each account passed or blew (or the days end: the END you typed / the saved data), every passed account goes
    // funded the session after its pass (TPT after its day-3 trade) on its own and trades its payout cycle to the plan's goal, blown or the end of the days
    public sealed class KeystoneBatchRun
    {
        public KeystonePropSim Sim; public KeystonePayoutRun Pay; public List<KeystoneEvalAccount> Passed = new List<KeystoneEvalAccount>();
        public DateTime Start, EvalEnd, LastDay, DaysEnd; public int Bought, EvalSessions, Sessions, StillEval, StillFunded, Blown;
        public bool DaysRanOut { get { return StillEval > 0 || StillFunded > 0; } }
        // "one batch of 30 bought on Tue 1 Sep 2026; blown accounts are not replaced (🔁 BUSINESS RUN does that)"
        public string Header { get { return "one batch of " + Bought + " bought on " + Start.ToString("ddd d MMM yyyy", CultureInfo.InvariantCulture) + "; blown accounts are not replaced (🔁 BUSINESS RUN does that)"; } }
        // 🔁 BUILD 11d ("one batch only"): the batch finished before the END — nothing left to trade (the old silent stop, now said + 🔁 keep buying until END)
        public bool EndedEarly(DateTime end) { return Bought > 0 && !DaysRanOut && LastDay.Date < end.Date; }
        public string EndedText(DateTime end, bool funded = true)
        {
            var ic = CultureInfo.InvariantCulture; int fb = Pay == null ? 0 : Pay.Accounts.Count(a => a.Stage == "BLOWN"), goal = Pay == null ? 0 : Pay.Accounts.Count(a => a.Stage == "GOAL" || a.Stage == "LIVE"), parked = Pay == null ? 0 : Pay.Accounts.Count(a => a.Stage == "PARKED");
            string why = funded ? Blown + " blown in eval · " + fb + " blown funded · " + goal + " reached the goal" + (parked > 0 ? " · " + parked + " parked" : "") : Blown + " blown in eval · " + Passed.Count + " passed";
            return "the batch ended " + LastDay.ToString("ddd d MMM yyyy", ic) + ": all " + Bought + " accounts finished (" + why + "), nothing left to trade until " + end.ToString("ddd d MMM yyyy", ic);
        }
        // ⏳ the days ended while accounts were still running (item 5)
        public string StillNote
        {
            get
            {
                if (!DaysRanOut) return ""; var ic = CultureInfo.InvariantCulture;
                return "⏳ the days end " + DaysEnd.ToString("ddd d MMM yyyy", ic) + ": " + (StillEval > 0 ? StillEval + " still in eval" : "") + (StillEval > 0 && StillFunded > 0 ? " · " : "") + (StillFunded > 0 ? StillFunded + " funded still running" : "")
                    + " — a payout needs ≥ 5 funded trading days (SAFE ≈ 19 on average)";
            }
        }
    }
    public static class KeystoneBatch
    {
        // every account of the batch passed (or passed pending TPT's day-3 tiny trade) or blew
        public static bool EvalDone(KeystonePropSim sim, int n) { return sim != null && sim.Accounts.Take(n).All(a => !a.Alive || sim.PassedOrPending(a)); }
        public static KeystoneBatchRun Run(KeystoneSimSettings st, IList<KeystoneRotDay> days, int startHhmm, int endHhmm, Func<KeystoneRotDay, int, Tuple<int, int>> sidesAt, bool funded,
            IList<KeystonePayoutRules> rules, KeystonePayoutPlan plan, Func<KeystonePropSim, KeystoneSimAccount, string> firmOf, Func<KeystonePropSim, KeystoneSimAccount, string> nameOf, Func<bool> cancel = null)
        {
            var res = new KeystoneBatchRun(); if (days == null || days.Count == 0 || st == null) return res; int n = st.Accounts; bool done = false; int used = 0; DateTime lastE = days[0].Day;
            res.Start = days[0].Day; res.Bought = n; res.DaysEnd = days[days.Count - 1].Day;
            var sim = KeystoneRotationLab.Run(st, days, startHhmm, endHhmm, () => done || (cancel != null && cancel()), sidesAt, (s0, d) => { used++; lastE = d; if (EvalDone(s0, n)) done = true; });
            res.Sim = sim; res.EvalSessions = used; res.EvalEnd = lastE;
            firmOf = firmOf ?? ((s0, a) => ((s0.FirmName(a) ?? "").Trim().Split(' ')[0]).ToUpperInvariant()); nameOf = nameOf ?? ((s0, a) => a.Name);
            var first = sim.Accounts.Take(n).ToList(); res.Blown = first.Count(a => !a.Alive && !sim.PassedOrPending(a)); res.StillEval = first.Count(a => a.Alive && !sim.PassedOrPending(a));
            foreach (var a in first.Where(sim.PassedOrPending))
            {
                var passDay = a.PassedOn != DateTime.MinValue ? a.PassedOn : sim.Trades.Where(t => t.Account == a.Id).Select(t => t.Day).DefaultIfEmpty(lastE).Max();
                res.Passed.Add(new KeystoneEvalAccount { Firm = (firmOf(sim, a) ?? "").ToUpperInvariant(), Nick = nameOf(sim, a), Size = 50, StartOn = KeystoneLabFlow.FundedStart(passDay, sim.PassedPending(a)) });
            }
            res.LastDay = lastE;
            if (funded && res.Passed.Count > 0)
            {
                var fdays = days.Where(d => d.Day > res.Start).ToList();
                if (fdays.Count > 0)
                {
                    res.Pay = KeystoneFundedBench.Run(rules, plan, res.Passed, fdays, new KeystoneBench(), cancel);
                    res.StillFunded = res.Pay.Accounts.Count(a => a.Active); if (res.Pay.DaysUsed > 0) { var lf = fdays[Math.Min(fdays.Count, res.Pay.DaysUsed) - 1].Day; if (lf > res.LastDay) res.LastDay = lf; }
                }
            }
            res.Sessions = days.Count(d => d.Day >= res.Start && d.Day <= res.LastDay);
            return res;
        }
    }
    // 💾 the funded plan choice, saved between sessions (item 27e): the plan's name, ⚡ SPRINT accounts per batch, the goal — both labs read it
    public static class KeystoneFundedChoice
    {
        public static string PlanName = ""; public static int Sprint = 0, Goal = 0; public static bool OneBatch;   /* 🔁 BUILD 11d: "one batch only (no replacements)" — off = ⚡ CALCULATE keeps buying until END • ⚡ BUILD 11f: SPRINT 0 = the default */
        /* ⚡ BUILD 11f: the defaults' version in the file — an older file (no "defaults=11f") whose sprint is the old default 2 was never changed by the user: it moves to the
           new default 0 ONCE (Migrated says so, the window logs it and saves the file); a value the user chose (0 / 1 / 3 / ALL, or 2 saved by this build) is kept */
        public const string DefaultsVersion = "11f"; public static string Migrated = "";
        public static string Text() { return "plan=" + (PlanName ?? "").Replace("\n", " ").Replace("\r", " ") + "\nsprint=" + Sprint + "\ngoal=" + Goal + "\nonebatch=" + (OneBatch ? 1 : 0) + "\ndefaults=" + DefaultsVersion; }
        public static void Parse(string text)
        {
            string ver = ""; bool hasSprint = false; Migrated = "";
            foreach (var l in (text ?? "").Split('\n')) { var t = l.TrimEnd('\r'); int e = t.IndexOf('='); if (e <= 0) continue; string k = t.Substring(0, e).Trim(), v = t.Substring(e + 1).Trim(); int i;
                if (k == "plan") PlanName = v; else if (k == "sprint" && int.TryParse(v, out i)) { Sprint = Math.Max(0, Math.Min(99, i)); hasSprint = true; } else if (k == "goal" && int.TryParse(v, out i)) Goal = Math.Max(0, Math.Min(99, i)); else if (k == "onebatch") OneBatch = v == "1"; else if (k == "defaults") ver = v; }
            if (ver != DefaultsVersion && hasSprint && Sprint == 2) { Sprint = 0; Migrated = "⚡ SPRINT 2 (the old default, never changed) → 0 (the new default, BUILD 2026-11-11f: " + KeystoneEvalLab.RealisticNote + ")"; }
        }
        public static void Load(string file)
        {
            try
            {
                if (!File.Exists(file)) return; Parse(File.ReadAllText(file));
                if (Migrated != "") { Save(file); File.AppendAllText(Path.Combine(Path.GetDirectoryName(file), "defaults-migration.log"), DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture) + " " + file + ": " + Migrated + Environment.NewLine); }
            }
            catch { }
        }
        public static void Save(string file) { try { Directory.CreateDirectory(Path.GetDirectoryName(file)); File.WriteAllText(file, Text()); } catch { } }
        public static int IndexIn(IList<KeystonePayoutPlan> plans) { if (plans == null) return 0; for (int i = 0; i < plans.Count; i++) if (plans[i].Name == PlanName) return i; return 0; }
        public static KeystonePayoutPlan Apply(KeystonePayoutPlan p) { if (p == null) return null; var q = p.Copy(); q.SprintAccounts = Sprint; q.Goal = Goal; return q; }
    }
    // 🪑 a funded run with the BENCH: max 5 active per firm, the extras wait; a blown / finished (moved to live) account is replaced from the bench (FIFO, same firm)
    public static class KeystoneFundedBench
    {
        public static KeystonePayoutRun Run(IList<KeystonePayoutRules> rules, KeystonePayoutPlan plan, IList<KeystoneEvalAccount> src, IList<KeystoneRotDay> days, KeystoneBench bench, Func<bool> cancel = null, Action<int, int> progress = null, KeystoneLabLog log = null)
        {
            var run = new KeystonePayoutRun { Plan = plan, Rules = (rules ?? KeystonePayoutRules.Presets()).ToList() }; var ctx = new KeystonePipeCtx(); bench = bench ?? new KeystoneBench();
            var byName = new Dictionary<string, KeystoneEvalAccount>(); int id = 0, sprints = 0;
            Func<string, int, KeystonePayoutAccount> make = (nm, seat) => { var e = byName[nm]; var r = KeystonePayoutRules.For(e.Firm, run.Rules); var a = new KeystonePayoutAccount { Id = ++id, Name = nm, Firm = (e.Firm ?? "").ToUpperInvariant(), Floor = r.FloorOf(0) };
                a.FirmNo = seat > 0 ? seat : run.Accounts.Count(x => x.Firm == a.Firm) + 1;   /* 11a: the number within the firm = its time + its coin (a bench replacement takes the seat) */
                if (!r.Tpt && !r.Parked && plan != null && sprints < plan.SprintAccounts) { a.Sprint = true; sprints++; }
                if (r.Parked) a.Stage = "PARKED"; run.Accounts.Add(a); return a; };
            foreach (var e in src ?? new List<KeystoneEvalAccount>())
            {
                string nm = string.IsNullOrEmpty(e.Nick) ? e.Firm + " " + (byName.Count + 1) : e.Nick; while (byName.ContainsKey(nm)) nm += "'"; byName[nm] = e;
                var r = KeystonePayoutRules.For(e.Firm, run.Rules);
                if (r.Parked) { make(nm, 0); continue; }   /* a parked firm (TPT) never takes a funded seat */
                if (bench.Add(nm, e.Firm)) make(nm, 0); else if (log != null) log.Add(DateTime.Now, "BENCH", nm, "🪑 on the bench — " + (e.Firm ?? "").ToUpperInvariant() + " already has " + bench.MaxPerFirm + " funded");
            }
            if (days == null || days.Count == 0) return run; run.From = days[0].Day; run.To = days[days.Count - 1].Day; int di = 0;
            foreach (var d in days)
            {
                di++; if (cancel != null && cancel()) break; if (!run.Accounts.Any(a => a.Active)) break; run.DaysUsed++;
                foreach (var a in run.Accounts.Where(x => x.Active).ToList())
                {
                    KeystoneEvalAccount e9; if (byName.TryGetValue(a.Name, out e9) && e9.StartOn > d.Day.Date) continue;   /* 💰 from the eval: each account starts on ITS own date */
                    if (a.Funded == DateTime.MinValue) a.Funded = d.Day;
                    int paid0 = a.Payouts; KeystonePayout.DayTracked(a, KeystonePayoutRules.For(a.Firm, run.Rules), plan, d, KeystonePayout.CoinOf(plan, d.Day, a, 1), ctx, run); KeystonePayout.ReachGoal(a, plan, d.Day);
                    if (log != null && a.Payouts > paid0) log.Add(d.Day, "PAYOUT", a.Name, "payout " + a.Payouts + " • $" + a.Paid[a.Paid.Count - 1].Net.ToString("N0", CultureInfo.InvariantCulture) + " to you");
                    if (a.Stage == "BLOWN" || a.Stage == "LIVE" || a.Stage == "GOAL")
                    {
                        if (log != null) log.Add(d.Day, a.Stage, a.Name, a.Stage == "BLOWN" ? "blown on the floor" : a.Stage == "GOAL" ? "🏁 the goal reached (" + a.Payouts + " payouts)" : "moved to live after " + a.Payouts + " payouts");
                        var nx = bench.Remove(a.Name, a.Stage.ToLowerInvariant()); if (nx != null) { var b = make(nx, a.FirmNo); if (log != null) log.Add(d.Day, "BENCH", nx, "🪑 → FUNDED (replaces " + a.Name + ")"); }
                    }
                }
                if (progress != null) progress(di, days.Count);
            }
            return run;
        }
    }
    // 📒 THE RUN RECORD (BUILD 2026-11-11b, phase B — the user: "one source of truth"): every result view is built from ONE record of a run — the output of
    // KeystoneBatch.Run (⚡ CALCULATE / ▶ REPLAY) or the 🔁 BUSINESS RUN: its accounts, trades, account-days, events and payouts. 👤 ACCOUNTS, the account card,
    // 🕒 TIMELINE, 💰 FUNDED RESULTS, 💰 PAYOUTS (by payout / account / firm / month), ⚖ COMPARE, the distributions in 📊 STATS, 📦 EXPORT FOR CLAUDE and the
    // business run all read it — no view recomputes on its own. Pure, no UI.
    public sealed class KeystoneRunRecord
    {
        public sealed class Acc
        {
            public string Key = "", Name = "", Firm = "", Status = "", Why = ""; public int Cohort, EvalDays, FundedDays, Trades, Won, Lost, QualDays, Payouts, FundedId = -1; public bool EvalBlown, FundedBlown, Passed, Funded, Sprint, StillEval, StillFunded, Locked;
            public DateTime Bought = DateTime.MinValue, PassedOn = DateTime.MinValue, FundedFrom = DateTime.MinValue, Ended = DateTime.MinValue, LockedOn = DateTime.MinValue; public double Spent, EvalPnl, FundedPnl, Best = double.NaN, Worst = double.NaN, Net, Gross, Largest, Bal, Floor, NeedMore;
            public List<int> DaysToPayout = new List<int>();   /* funded trading days from the funded start to payout 1, 2 … */
            public string Slot = ""; public int Gen;   /* 🔁 BUILD 11d: a continuous run's slot ("LUCID 1") and the account's generation in it (#3 = the third account bought for that slot) */
            public string Owner = "";   /* 👥 BUILD 11f: the owner of the slot ("ME" / "WIFE"; "" = no owners in this run) */
            public string Shown { get { return Name + SprintTag(Sprint); } }   /* the name + the ⚡ SPRINT badge (rows, cards) */
            public string FirmNice { get { return KeystonePipeline.Nice(Firm); } }
            public bool Blown { get { return EvalBlown || FundedBlown; } }
        }
        public sealed class Trade { public string Account = "", Firm = "", Stage = "", How = "", Legs = "", Source = ""; public DateTime Day, Entry, Exit; public int Dir, Qty; public string Instrument = "MNQ"; public double EntryPx = double.NaN, ExitPx = double.NaN, Pnl, Tp = double.NaN, Stop = double.NaN, Floor = double.NaN; }
        public sealed class Day { public string Account = "", Firm = "", Stage = ""; public DateTime Date; public double StartBal, EndBal, Pnl, Peak, Floor, Room; public int Trades, QualCount; public bool Qual, Locked; public string Note = ""; }
        public sealed class Event { public DateTime Day, Time; public string Account = "", Firm = "", Stage = "", Kind = "", Text = ""; public double Amount; }
        public sealed class Pay { public string Account = "", Firm = "", Rule = ""; public DateTime Day, CycleFrom; public int N, CycleDays, CycleQual, CycleTrades; public double Gross, Net, BalAfter, CycleProfit; }
        public string Scope = "EVAL", Build = "", Header = ""; public DateTime From, To; public int Sessions;
        public readonly List<Acc> Accounts = new List<Acc>(); public readonly List<Trade> Trades = new List<Trade>(); public readonly List<Day> Days = new List<Day>(); public readonly List<Event> Events = new List<Event>(); public readonly List<Pay> Payouts = new List<Pay>();
        public readonly List<KeyValuePair<string, string>> Settings = new List<KeyValuePair<string, string>>();
        public IList<KeystoneRotDay> Source;   /* the saved days the run read (the data facts + the optional price minutes in the export) — not exported as such */
        public List<KeystonePayoutRules> Rules = new List<KeystonePayoutRules>(); public KeystonePayoutPlan Plan; public KeystoneSimSettings EvalSettings;
        static readonly CultureInfo IC = CultureInfo.InvariantCulture;
        static string M(double v) { return (v < 0 ? "−$" : "$") + Math.Abs(Math.Round(v)).ToString("N0", IC); }
        static string Sg(double v) { return (v >= 0 ? "+" : "−") + "$" + Math.Abs(Math.Round(v)).ToString("N0", IC); }
        static string D(DateTime d) { return d == DateTime.MinValue ? "–" : d.ToString("ddd yyyy-MM-dd", IC); }
        static string P(int a, int n) { return n <= 0 ? "–" : (100.0 * a / n).ToString("0.0", IC) + " %"; }
        static string LegQty(string legs, out int qty, out string inst) { qty = 0; inst = "MNQ"; var w = (legs ?? "").Split(' '); if (w.Length > 2) { int.TryParse(w[1], out qty); inst = w[2]; } return legs; }
        public static string HowName(string reason) { string r = (reason ?? "").ToUpperInvariant(); return r == "TARGET" ? "TP" : r == "STOP" ? "stop" : r == "FLOOR" ? "floor (blown)" : r == "TIME" || r == "SESSION END" || r == "CLOSE" ? "session end" : r == "BREAKEVEN" ? "breakeven" : r == "LOCK" ? "lock" : (reason ?? ""); }
        public KeystonePayoutRules RulesOf(string firm) { return KeystonePayoutRules.For(firm, Rules != null && Rules.Count > 0 ? Rules : null); }
        public Acc Find(string key) { key = Untag(key); return Accounts.FirstOrDefault(a => a.Key == key) ?? Accounts.FirstOrDefault(a => a.Name == key); }
        // ⚡ the SPRINT badge (BUILD 11d, item 4): a sprint account rides MNQ 10 with no stop for its first funded days — one blown on its first funded day is the sprint's risk, not a bug
        public const string SprintBadge = "⚡ SPRINT";
        public const string SprintWhy = "⚡ SPRINT accounts trade their first 5 funded days on MNQ 10 with no stop (ride the room) for the max payout, then SAFE — one blown on its first funded day is the sprint's risk, not a bug";
        public static string SprintTag(bool sprint) { return sprint ? " · " + SprintBadge : ""; }
        public static string Untag(string key) { return key == null ? null : key.Replace(" · " + SprintBadge, ""); }
        // the trust line (item 16): what the numbers are made of, on every result
        public static string TrustOf(DateTime first, DateTime last)
        {
            return "calculated from your saved 1-minute MNQ / MGC minutes, " + (first == DateTime.MinValue ? "–" : first.ToString("ddd d MMM yyyy", IC)) + " → " + (last == DateTime.MinValue ? "–" : last.ToString("ddd d MMM yyyy", IC))
                + " • costs $1 a contract + 1 tick slippage each side (MNQ $1.50 + the entry tick in the fill) • fills: entry at the minute's open + 1 tick, TP on a touch (never in the entry minute), stop / floor on the minute's worst price, the rest at the session end";
        }
        public const string Verified = "✔ verified against the research engine — tests/LabEngineTests.cs pins it (lab Lucid SAFE 9:30 London 2020–26 paid at least once 68.8 % ± 3 points on the real minutes; costs, fills, coins, the MFF rules and the run record are tested there)";
        public string Trust { get { return TrustOf(Source != null && Source.Count > 0 ? Source[0].Day : From, Source != null && Source.Count > 0 ? Source[Source.Count - 1].Day : To); } }

        // ---- building the record from ONE batch (the eval sim + the funded run) — the cohort number keeps business-run batches apart
        public static KeystoneRunRecord Of(string scope, KeystonePropSim sim, int firstN, Func<KeystoneSimAccount, string> nameOf, Func<KeystoneSimAccount, string> firmOf, KeystonePayoutRun pay, DateTime from, DateTime to, int sessions = 0)
        {
            var rec = new KeystoneRunRecord { Scope = scope ?? "EVAL", From = from, To = to, Sessions = sessions }; rec.Add(sim, firstN, nameOf, firmOf, pay, 0, ""); rec.Finish(to); return rec;
        }
        public void Add(KeystonePropSim sim, int firstN, Func<KeystoneSimAccount, string> nameOf, Func<KeystoneSimAccount, string> firmOf, KeystonePayoutRun pay, int cohort, string prefix)
        {
            prefix = prefix ?? ""; if (pay != null && pay.Plan != null && Plan == null) Plan = pay.Plan; if (sim != null && EvalSettings == null) EvalSettings = sim.S;
            if (pay != null && pay.Rules != null && pay.Rules.Count > 0) foreach (var r in pay.Rules) if (!Rules.Any(x => x.Firm == r.Firm)) Rules.Add(r);
            var byName = new Dictionary<string, Acc>();
            if (sim != null)
            {
                if (nameOf == null) nameOf = a => a.Name; if (firmOf == null) firmOf = a => ((sim.FirmName(a) ?? "").Trim().Split(' ')[0]);
                var acc = sim.Accounts.Take(firstN > 0 ? firstN : sim.Accounts.Count).ToList(); var ids = acc.ToDictionary(a => a.Id);
                foreach (var a in acc)
                {
                    bool ok = sim.PassedOrPending(a); var tr = sim.Trades.Where(t => t.Account == a.Id).ToList(); var evTr = tr.Where(t => t.Phase != "FUNDED").ToList();
                    var x = new Acc { Key = prefix + nameOf(a), Name = prefix + nameOf(a), Firm = (firmOf(a) ?? "").Trim().ToUpperInvariant(), Cohort = cohort, Bought = a.Bought != DateTime.MinValue ? a.Bought.Date : from0(sim), Spent = a.Spent, Passed = ok, EvalBlown = !a.Alive && !ok, StillEval = a.Alive && !ok };
                    x.PassedOn = !ok ? DateTime.MinValue : a.PassedOn != DateTime.MinValue ? a.PassedOn : evTr.Select(t => t.Day).DefaultIfEmpty(sim.Day).Max();
                    if (x.EvalBlown) x.Ended = a.Ended.Date;
                    x.EvalDays = evTr.Select(t => t.Day.Date).Distinct().Count(); x.EvalPnl = evTr.Sum(t => t.Pnl); x.Bal = a.Bal; x.Floor = x.StillEval ? sim.Floor(a) : 0;
                    Accounts.Add(x); byName[nameOf(a)] = x;
                    foreach (var t in evTr) { int q; string inst; LegQty(t.Legs, out q, out inst); Trades.Add(new Trade { Account = x.Key, Firm = x.Firm, Stage = "EVAL", How = HowName(t.Reason), Legs = t.Legs, Source = t.Source, Day = t.Day.Date, Entry = t.Entry, Exit = t.Exit, Dir = t.Dir, Qty = q, Instrument = inst, EntryPx = t.EntryPx, ExitPx = t.ExitPx, Pnl = t.Pnl, Tp = t.Tp, Stop = t.Sl, Floor = t.FloorAt }); }
                    Events.Add(new Event { Day = x.Bought, Time = x.Bought, Account = x.Key, Firm = x.Firm, Stage = "EVAL", Kind = "BOUGHT", Amount = -a.Spent, Text = "🛒 evaluation bought (" + M(a.Spent) + ")" });
                    if (ok) Events.Add(new Event { Day = x.PassedOn.Date, Time = x.PassedOn.Date.AddHours(17), Account = x.Key, Firm = x.Firm, Stage = "EVAL", Kind = "PASSED", Text = "✅ PASSED the evaluation in " + Math.Max(1, x.EvalDays) + " trading day" + (x.EvalDays == 1 ? "" : "s") + (sim.PassedPending(a) ? " (TPT: its day-3 tiny trade pending)" : "") });
                    if (x.EvalBlown) Events.Add(new Event { Day = x.Ended, Time = a.Ended, Account = x.Key, Firm = x.Firm, Stage = "EVAL", Kind = "BLOWN", Text = "💀 BLOWN in eval (day " + Math.Max(1, x.EvalDays) + ") — " + (string.IsNullOrEmpty(a.EndReason) ? "the floor" : a.EndReason) });
                }
                foreach (var dr in sim.AccountDays) { KeystoneSimAccount sa; if (!ids.TryGetValue(dr.Account, out sa) || dr.Phase == "FUNDED") continue; var x = byName[nameOf(sa)]; Days.Add(new Day { Account = x.Key, Firm = x.Firm, Stage = "EVAL", Date = dr.Day.Date, StartBal = dr.Balance - dr.Pnl, EndBal = dr.Event == "PASSED" ? dr.Balance + 0 : dr.Balance, Pnl = dr.Pnl, Peak = dr.Peak, Floor = dr.Floor, Room = dr.Room, Trades = dr.Trades, Note = dr.Event ?? "" }); }
            }
            if (pay != null)
            {
                foreach (var a in pay.Accounts)
                {
                    string nm = a.Name.TrimEnd('\''); Acc x; if (!byName.TryGetValue(nm, out x)) x = Accounts.FirstOrDefault(q => q.Key == prefix + nm && q.FundedId < 0);   /* 🔁 a business run adds the funded run after its cohorts */
                    if (x == null) { x = new Acc { Key = prefix + a.Name, Name = prefix + a.Name, Firm = a.Firm, Cohort = cohort, Passed = true }; Accounts.Add(x); byName[a.Name] = x; }
                    var r = KeystonePayoutRules.For(a.Firm, pay.Rules); x.FundedId = a.Id; x.Funded = a.Funded != DateTime.MinValue || a.Stage != "FUNDED"; x.FundedFrom = a.Funded; x.FundedDays = a.Days; x.Payouts = a.Payouts; x.Net = a.Net; x.Gross = a.Gross; x.Sprint = a.Sprint; x.Locked = a.Locked; x.Bal = a.Bal; x.Floor = a.Floor;
                    x.FundedBlown = a.Stage == "BLOWN"; x.StillFunded = a.Stage == "FUNDED" && a.Funded != DateTime.MinValue; if (a.Stage != "FUNDED" && a.Ended != DateTime.MinValue) x.Ended = a.Ended.Date; x.Largest = a.Paid.Count == 0 ? 0 : a.Paid.Max(e => e.Net);
                    if (a.Stage == "PARKED") x.Status = "parked";
                    var ftr = pay.Trades.Where(t => t.Account == a.Id).ToList(); x.FundedPnl = ftr.Sum(t => t.Pnl);
                    foreach (var t in ftr) { int q; string inst; LegQty(t.Legs, out q, out inst); Trades.Add(new Trade { Account = x.Key, Firm = x.Firm, Stage = "FUNDED", How = HowName(t.Reason), Legs = t.Legs, Source = t.Source, Day = t.Day.Date, Entry = t.Entry, Exit = t.Exit, Dir = t.Dir, Qty = q, Instrument = inst, EntryPx = t.EntryPx, ExitPx = t.ExitPx, Pnl = t.Pnl, Tp = t.Tp, Stop = t.Sl, Floor = t.FloorAt }); }
                    var fdays = pay.AccountDays.Where(d0 => d0.Account == a.Id).OrderBy(d0 => d0.Day).ToList(); int fn = 0;
                    if (a.Funded != DateTime.MinValue) Events.Add(new Event { Day = a.Funded.Date, Time = a.Funded.Date.AddHours(-6), Account = x.Key, Firm = x.Firm, Stage = "FUNDED", Kind = "FUNDED", Text = "💰 went FUNDED" + (a.Sprint ? " (⚡ SPRINT)" : "") + " — " + KeystoneFundedModel.Of(a.Firm, r) });
                    foreach (var d0 in fdays)
                    {
                        if (d0.Trades > 0) fn++;
                        Days.Add(new Day { Account = x.Key, Firm = x.Firm, Stage = "FUNDED", Date = d0.Day.Date, StartBal = d0.StartBal, EndBal = d0.EndBal, Pnl = d0.Pnl, Peak = d0.Peak, Floor = d0.Floor, Room = d0.Room, Trades = d0.Trades, Qual = d0.Qual, QualCount = d0.QualCount, Locked = d0.Locked, Note = d0.Mode });
                        if (d0.Qual && !r.Studio && !r.Tpt) Events.Add(new Event { Day = d0.Day.Date, Time = d0.Day.Date.AddHours(16.9), Account = x.Key, Firm = x.Firm, Stage = "FUNDED", Kind = "QUALIFY", Amount = d0.Pnl, Text = "✓ qualifying day " + Math.Min(d0.QualCount, Math.Max(1, r.QualDays)) + "/" + r.QualDays + " (" + Sg(d0.Pnl) + " ≥ " + M(r.QualMin) + ")" });
                        if (d0.Locked && x.LockedOn == DateTime.MinValue) { x.LockedOn = d0.Day.Date; Events.Add(new Event { Day = d0.Day.Date, Time = d0.Day.Date.AddHours(16.95), Account = x.Key, Firm = x.Firm, Stage = "FUNDED", Kind = "LOCKED", Text = "🔒 the trailing floor LOCKED at the start (best equity +" + M(r.Dd) + ") after " + fn + " funded day" + (fn == 1 ? "" : "s") }); }
                        if (d0.Payouts > 0) for (int z = 0; z < d0.Payouts; z++) x.DaysToPayout.Add(fn);
                    }
                    DateTime cyc = a.Funded; bool firstCyc = true; foreach (var e in a.Paid.OrderBy(e => e.Day).ThenBy(e => e.N))
                    {
                        DateTime c0 = cyc; bool f0 = firstCyc; var cd = fdays.Where(d0 => (f0 ? d0.Day >= c0 : d0.Day > c0) && d0.Day <= e.Day).ToList(); firstCyc = false;
                        Payouts.Add(new Pay { Account = x.Key, Firm = x.Firm, Day = e.Day.Date, N = e.N, Gross = e.Gross, Net = e.Net, BalAfter = e.BalAfter, CycleFrom = cyc, CycleDays = cd.Count(d0 => d0.Trades > 0), CycleQual = cd.Count(d0 => d0.Qual), CycleTrades = cd.Sum(d0 => d0.Trades), CycleProfit = cd.Sum(d0 => d0.Pnl), Rule = RuleText(r) });
                        Events.Add(new Event { Day = e.Day.Date, Time = e.Day.Date.AddHours(16.99), Account = x.Key, Firm = x.Firm, Stage = "FUNDED", Kind = "PAYOUT", Amount = e.Net, Text = "💵 payout " + e.N + ": " + M(e.Gross) + " gross → " + M(e.Net) + " to you (" + RuleText(r) + ")" });
                        cyc = e.Day.Date;
                    }
                    if (x.FundedBlown) Events.Add(new Event { Day = x.Ended, Time = x.Ended.AddHours(16.5), Account = x.Key, Firm = x.Firm, Stage = "FUNDED", Kind = "BLOWN", Text = "💀 BLOWN funded after " + a.Days + " day" + (a.Days == 1 ? "" : "s") + " (the floor " + M(a.Floor) + ") · " + a.Payouts + " payout" + (a.Payouts == 1 ? "" : "s") });
                    else if (a.Stage == "GOAL") Events.Add(new Event { Day = x.Ended, Time = x.Ended.AddHours(17), Account = x.Key, Firm = x.Firm, Stage = "FUNDED", Kind = "GOAL", Text = "🏁 the goal reached (" + a.Payouts + " payout" + (a.Payouts == 1 ? "" : "s") + ")" });
                    else if (a.Stage == "LIVE") Events.Add(new Event { Day = x.Ended, Time = x.Ended.AddHours(17), Account = x.Key, Firm = x.Firm, Stage = "FUNDED", Kind = "LIVE", Text = "🎓 moved to live after " + a.Payouts + " payouts (" + M(a.Gross) + " gross)" });
                }
            }
        }
        static DateTime from0(KeystonePropSim sim) { return sim.Days.Count > 0 ? sim.Days[0].Day : sim.Day; }
        public static string RuleText(KeystonePayoutRules r)
        {
            if (r == null) return ""; Func<double, string> m = v => "$" + v.ToString("N0", IC);
            if (r.Studio) return "🎬 instant withdrawal (" + KeystonePayoutRules.WithdrawName(r.Withdraw) + "), " + r.Split.ToString("0", IC) + " % yours, " + m(r.TotalCap) + " total cap";
            if (r.Tpt) return "TPT PRO: the floor locked at the start, a withdrawal once the balance ≥ +" + m(r.Dd + 1000) + " (keeps the " + m(r.Dd) + " buffer)";
            return r.QualDays + " qualifying days (≥ " + m(r.QualMin) + ") + profit ≥ " + m(r.MinPayout / Math.Max(0.01, r.Pct / 100.0)) + " → " + r.Pct.ToString("0", IC) + " % of the profit (max " + m(r.Cap) + "), " + r.Split.ToString("0", IC) + " % yours";
        }
        // the statuses + the WHY (item 9 / 23 / 26): why an account has no payout yet
        public void Finish(DateTime dataEnd)
        {
            foreach (var x in Accounts)
            {
                var acTr = Trades.Where(t => t.Account == x.Key).ToList(); x.Trades = acTr.Count; x.Won = acTr.Count(t => t.Pnl > 0); x.Lost = x.Trades - x.Won;
                var dayP = acTr.GroupBy(t => t.Stage + t.Day.Ticks).Select(g => g.Sum(t => t.Pnl)).ToList(); if (dayP.Count > 0) { x.Best = dayP.Max(); x.Worst = dayP.Min(); }
                x.QualDays = Days.Count(d => d.Account == x.Key && d.Qual); var r = RulesOf(x.Firm);
                if (x.EvalBlown) x.Status = "💀 blown in eval " + D(x.Ended);
                else if (x.StillEval) x.Status = "● in eval (" + x.EvalDays + " day" + (x.EvalDays == 1 ? "" : "s") + ")";
                else if (x.Status == "parked") { }
                else if (!x.Funded) x.Status = "✅ passed " + D(x.PassedOn) + " · funded from " + D(x.FundedFrom == DateTime.MinValue ? x.PassedOn : x.FundedFrom);
                else if (x.FundedBlown) x.Status = "💀 blown funded " + D(x.Ended) + (x.Payouts > 0 ? " · paid " + x.Payouts : "");
                else if (x.Ended != DateTime.MinValue) x.Status = (x.Gross >= r.TotalCap - 0.01 && r.Studio ? "🎓 $" + r.TotalCap.ToString("N0", IC) + " cap → live" : "🏁 done") + " · paid " + x.Payouts;
                else x.Status = x.Payouts > 0 ? "💵 paid " + x.Payouts + " · funded running" : "💰 funded · building";
                x.Why = x.Payouts > 0 && !x.StillFunded ? "" : WhyNoPayout(x, r, dataEnd);
            }
        }
        public string WhyNoPayout(Acc x, KeystonePayoutRules r, DateTime dataEnd)
        {
            if (x.EvalBlown) return "blown in eval on " + D(x.Ended); if (x.StillEval) return "still in eval when the data ended (" + D(dataEnd) + ")";
            if (!x.Funded) return "passed — funded starts " + D(x.FundedFrom == DateTime.MinValue ? x.PassedOn : x.FundedFrom) + " (after the data ends)";
            if (x.FundedBlown) return "blown funded on " + D(x.Ended) + " after " + x.FundedDays + " funded day" + (x.FundedDays == 1 ? "" : "s");
            if (x.Payouts > 0 && !x.StillFunded) return "";
            double bal = x.Bal; string tail = x.StillFunded ? " · ⏳ data ended " + D(dataEnd) : "";
            if (r.Studio) { double need = Math.Max(0, r.WithdrawMin - bal); x.NeedMore = need; return (x.Payouts > 0 ? "next withdrawal: " : "") + "profit " + Sg(bal) + " — " + (need > 0 ? M(need) + " more to withdraw (≥ " + M(r.WithdrawMin) + ")" : "withdraws at the policy (" + KeystonePayoutRules.WithdrawName(r.Withdraw) + ")") + tail; }
            if (r.Tpt)
            {
                if (!x.Locked) { double best = Days.Where(d => d.Account == x.Key && d.Stage == "FUNDED").Select(d => d.Peak).DefaultIfEmpty(0).Max(); x.NeedMore = Math.Max(0, r.Dd - best); return "🔒 trailing not locked yet: best equity " + Sg(best) + " of +" + M(r.Dd) + tail; }
                double needT = Math.Max(0, r.Dd + 1000 - bal); x.NeedMore = needT; return "locked — balance " + Sg(bal) + " vs +" + M(r.Dd + 1000) + " needed: +" + M(needT) + " to go (keeps the " + M(r.Dd) + " buffer)" + tail;
            }
            int q = Days.Where(d => d.Account == x.Key && d.Stage == "FUNDED").SkipWhile(d => false).Count(d => d.Qual) - x.Payouts * Math.Max(1, r.QualDays); q = Math.Max(0, Math.Min(r.QualDays, q));
            double needP = Math.Max(0, r.MinPayout / Math.Max(0.01, r.Pct / 100.0) - bal); x.NeedMore = needP;
            return "qualifying " + q + "/" + r.QualDays + " · profit " + Sg(bal) + (needP > 0 ? " vs " + M(r.MinPayout / Math.Max(0.01, r.Pct / 100.0)) + " needed (+" + M(needP) + " to go)" : " (enough)") + tail;
        }
        // ---- the counts every header / footer uses (one definition: TPT day-3 pending counts as passed)
        public int Bought { get { return Accounts.Count(a => a.Bought != DateTime.MinValue); } }
        public int PassedN { get { return Accounts.Count(a => a.Passed); } }
        public int EvalBlownN { get { return Accounts.Count(a => a.EvalBlown); } }
        public int FundedN { get { return Accounts.Count(a => a.Funded); } }
        public int PayoutN { get { return Payouts.Count; } }
        public double PaidNet { get { return Payouts.Sum(p => p.Net); } }
        public double Spent { get { return Accounts.Sum(a => a.Spent); } }

        // ---- 📊 distributions (item 13): median, 10th–90th
        public static string Dist(IList<int> v)
        {
            if (v == null || v.Count == 0) return "–"; var s = v.OrderBy(x => x).ToList(); Func<double, int> q = f => s[Math.Max(0, Math.Min(s.Count - 1, (int)Math.Round(f * (s.Count - 1))))];
            return "median " + q(0.5) + " · 10th–90th " + q(0.1) + "–" + q(0.9) + " (n = " + s.Count + ")";
        }
        public List<int> DaysToPass(string firm) { return Accounts.Where(a => a.Passed && (firm == null || a.Firm == firm)).Select(a => Math.Max(1, a.EvalDays)).ToList(); }
        public List<int> DaysToLock(string firm) { return Accounts.Where(a => a.LockedOn != DateTime.MinValue && (firm == null || a.Firm == firm)).Select(a => Days.Count(d => d.Account == a.Key && d.Stage == "FUNDED" && d.Trades > 0 && d.Date <= a.LockedOn)).ToList(); }
        public List<int> DaysToPayout(string firm, int n) { return Accounts.Where(a => a.DaysToPayout.Count >= n && (firm == null || a.Firm == firm)).Select(a => a.DaysToPayout[n - 1]).ToList(); }
        public List<string[]> DistTable()
        {
            var t = new List<string[]> { new[] { "FIRM", "DAYS TO PASS (eval)", "DAYS TO LOCK THE TRAILING (TPT funded)", "DAYS TO PAYOUT 1", "DAYS TO PAYOUT 2", "DAYS TO PAYOUT 3" } };
            foreach (var f in Accounts.Select(a => a.Firm).Distinct().Concat(new string[] { null }))
                t.Add(new[] { f == null ? "ALL" : KeystonePipeline.Nice(f), Dist(DaysToPass(f)), Dist(DaysToLock(f)), Dist(DaysToPayout(f, 1)), Dist(DaysToPayout(f, 2)), Dist(DaysToPayout(f, 3)) });
            return t;
        }
        // ---- 👥 OWNERS (BUILD 11f): the owners of the run's accounts (from their slots), the split per owner
        public bool HasOwners { get { return Accounts.Any(a => !string.IsNullOrEmpty(a.Owner)); } }
        public void ApplyOwners(int perOwner, IList<string> names) { foreach (var a in Accounts) a.Owner = KeystoneOwners.SlotOwner(string.IsNullOrEmpty(a.Slot) ? a.Name : a.Slot, perOwner, names); }
        static List<string[]> WithOwner(List<string[]> t, Func<int, string> ownerOfRow)
        {   /* the OWNER column at the end (the other columns keep their places) */
            for (int i = 0; i < t.Count; i++) { var r = t[i]; var n = new string[r.Length + 1]; Array.Copy(r, n, r.Length); n[r.Length] = i == 0 ? "👥 OWNER" : ownerOfRow(i) ?? ""; t[i] = n; }
            return t;
        }
        public List<string[]> OwnerTable()
        {
            var t = new List<string[]> { new[] { "👥 OWNER", "EVALS BOUGHT", "$ SPENT", "PASSED", "PASS %", "FUNDED", "FUNDED BLOWN", "PAID ONCE", "PAYOUTS", "$ TO YOU", "NET" } };
            foreach (var g in Accounts.Where(a => !string.IsNullOrEmpty(a.Owner)).GroupBy(a => a.Owner).Concat(Accounts.Where(a => !string.IsNullOrEmpty(a.Owner)).GroupBy(a => "ALL")))
            {
                double sp = g.Sum(a => a.Spent), pd = g.Sum(a => a.Net); int ps = g.Count(a => a.Passed);
                t.Add(new[] { g.Key, g.Count().ToString(IC), M(sp), ps.ToString(IC), P(ps, g.Count()), g.Count(a => a.FundedFrom != DateTime.MinValue).ToString(IC), g.Count(a => a.FundedBlown).ToString(IC), g.Count(a => a.Payouts > 0).ToString(IC), g.Sum(a => a.Payouts).ToString(IC), M(pd), Sg(pd - sp) });
            }
            return t;
        }
        public List<string> OwnerLines() { return OwnerTable().Skip(1).Select(r => "👥 " + r[0] + ": " + r[1] + " evals (" + r[2] + ") · " + r[3] + " passed · " + r[5] + " funded · " + r[8] + " payouts · " + r[9] + " to you · net " + r[10]).ToList(); }
        // ---- 👤 ACCOUNTS (item 9): one row per account + per-firm summary rows (+ 👥 the owner, when the run has owners)
        public List<string[]> AccountsTable()
        {
            var t0 = AccountsTable0(); if (!HasOwners) return t0;
            var rows = new List<string> { "" }; rows.AddRange(Accounts.Select(a => a.Owner)); rows.AddRange(Accounts.GroupBy(a => a.FirmNice).Select(g => string.Join(" / ", g.GroupBy(a => a.Owner).Select(o => o.Key + " " + o.Count()))));
            WithOwner(t0, i => i < rows.Count ? rows[i] : "");
            foreach (var g in Accounts.GroupBy(a => a.Owner))
            {
                int tr = g.Sum(a => a.Trades), won = g.Sum(a => a.Won); var r = new string[t0[0].Length]; for (int i = 0; i < r.Length; i++) r[i] = "";
                r[0] = "Σ 👥 " + g.Key; r[1] = string.Join(" / ", g.GroupBy(a => a.FirmNice).Select(f => f.Count() + " " + f.Key)); r[2] = g.Sum(a => a.EvalDays).ToString(IC); r[3] = g.Count(a => a.Passed) + " passed"; r[4] = g.Count(a => a.Funded) + " funded"; r[6] = tr.ToString(IC); r[7] = won.ToString(IC); r[8] = (tr - won).ToString(IC); r[9] = P(won, tr); r[13] = g.Sum(a => a.Payouts).ToString(IC); r[14] = M(g.Sum(a => a.Net)); r[17] = g.Count(a => a.Blown) + " blown · " + g.Count(a => a.StillEval || a.StillFunded) + " running"; r[r.Length - 1] = g.Key; t0.Add(r);
            }
            return t0;
        }
        List<string[]> AccountsTable0()
        {
            var t = new List<string[]> { new[] { "ACCOUNT", "FIRM", "EVAL DAYS", "PASSED ON", "FUNDED FROM", "FUNDED DAYS", "TRADES", "WON", "LOST", "WIN %", "BEST DAY", "WORST DAY", "QUAL DAYS", "PAYOUTS", "$ TO YOU", "DAYS TO PAYOUT 1", "DAYS BETWEEN", "STATUS" } };
            foreach (var x in Accounts)
                t.Add(new[] { x.Shown, x.FirmNice, x.EvalDays.ToString(IC), x.Passed ? D(x.PassedOn) : "–", x.FundedFrom == DateTime.MinValue ? "–" : D(x.FundedFrom), x.FundedDays.ToString(IC), x.Trades.ToString(IC), x.Won.ToString(IC), x.Lost.ToString(IC), P(x.Won, x.Trades), double.IsNaN(x.Best) ? "–" : Sg(x.Best), double.IsNaN(x.Worst) ? "–" : Sg(x.Worst), x.QualDays.ToString(IC), x.Payouts.ToString(IC), M(x.Net), x.DaysToPayout.Count > 0 ? x.DaysToPayout[0].ToString(IC) : "–", x.DaysToPayout.Count > 1 ? (Enumerable.Range(1, x.DaysToPayout.Count - 1).Average(i => (double)(x.DaysToPayout[i] - x.DaysToPayout[i - 1]))).ToString("0.0", IC) : "–", x.Status });
            foreach (var g in Accounts.GroupBy(a => a.FirmNice))
            {
                int tr = g.Sum(a => a.Trades), won = g.Sum(a => a.Won); var p1 = g.Where(a => a.DaysToPayout.Count > 0).Select(a => (double)a.DaysToPayout[0]).ToList();
                t.Add(new[] { "Σ " + g.Key, g.Key, g.Sum(a => a.EvalDays).ToString(IC), g.Count(a => a.Passed) + " passed", g.Count(a => a.Funded) + " funded", g.Sum(a => a.FundedDays).ToString(IC), tr.ToString(IC), won.ToString(IC), (tr - won).ToString(IC), P(won, tr), "", "", g.Sum(a => a.QualDays).ToString(IC), g.Sum(a => a.Payouts).ToString(IC), M(g.Sum(a => a.Net)), p1.Count == 0 ? "–" : p1.Average().ToString("0.0", IC), "", g.Count(a => a.Blown) + " blown · " + g.Count(a => a.StillEval || a.StillFunded) + " running" });
            }
            return t;
        }
        // ---- 💰 FUNDED RESULTS (item 23)
        public List<string[]> FundedFirmTable()
        {
            var t = new List<string[]> { new[] { "FIRM", "FUNDED", "ALIVE", "BLOWN", "QUALIFYING REACHED", "PAYOUTS", "$ TO YOU", "PAID ONCE %", "AVG DAYS TO PAYOUT 1" } };
            /* ⚡ item 4 (BUILD 11d): each firm with sprint accounts is split — "Lucid · ⚡ SPRINT" and "Lucid · 🛟 SAFE" — next to its total */
            var fu = Accounts.Where(a => a.Funded).ToList(); var groups = new List<IGrouping<string, Acc>>();
            foreach (var g0 in fu.GroupBy(a => a.FirmNice)) { groups.Add(g0); if (g0.Any(a => a.Sprint)) { foreach (var g1 in g0.GroupBy(a => g0.Key + (a.Sprint ? " · " + SprintBadge : " · 🛟 SAFE")).OrderBy(g1 => g1.Key.Contains("SPRINT") ? 0 : 1)) groups.Add(g1); } }
            if (HasOwners) groups.AddRange(fu.GroupBy(a => "👥 " + a.Owner));   /* 👥 BUILD 11f: one row per owner */
            groups.AddRange(fu.GroupBy(a => "ALL"));
            foreach (var g in groups)
            {
                var r = RulesOf(g.First().Firm); var p1 = g.Where(a => a.DaysToPayout.Count > 0).Select(a => (double)a.DaysToPayout[0]).ToList();
                t.Add(new[] { g.Key, g.Count().ToString(IC), g.Count(a => a.StillFunded).ToString(IC), g.Count(a => a.FundedBlown).ToString(IC), g.Count(a => a.Payouts > 0 || (!r.Tpt && !r.Studio && a.QualDays >= r.QualDays)).ToString(IC), g.Sum(a => a.Payouts).ToString(IC), M(g.Sum(a => a.Net)), P(g.Count(a => a.Payouts > 0), g.Count()), p1.Count == 0 ? "–" : p1.Average().ToString("0.0", IC) });
            }
            return t;
        }
