                row.PerFirm = string.Join(" · ", acc.Where(br.Sim.PassedOrPending).GroupBy(a => KeystonePipeline.Nice(((br.Sim.FirmName(a) ?? "").Trim().Split(' ')[0]))).Select(g => g.Count() + " " + g.Key));
