        public DateTime Day = DateTime.MinValue; public KeystoneSimAccount Active; public bool DayOpen;
        int nextId = 1, lastTurn, lastFirm = -1; bool waitingNoted;
        // 📦 BATCHES: each set of evaluations bought together, once every one of them passed or blew (saved in batches.csv)
        public DateTime BatchStart = DateTime.MinValue; public List<KeystoneSimBatch> Batches = new List<KeystoneSimBatch>();
        void CloseBatch()
        {
            var acc = Accounts.Where(a => a.Bought >= BatchStart && a.Bought <= Day).ToList(); if (acc.Count == 0) return;
            var ids = new HashSet<int>(acc.Select(a => a.Id)); var tr = Trades.Where(t => ids.Contains(t.Account) && t.Phase == "EVAL").ToList();
            var b = new KeystoneSimBatch { No = Batches.Count + 1, From = acc.Min(a => a.Bought), To = tr.Count > 0 ? tr.Max(t => t.Day) : Day, Bought = acc.Count, Passed = acc.Count(a => a.PassedOn != DateTime.MinValue), Spent = acc.Sum(a => a.Spent),
                Days = tr.Select(t => t.Day).Distinct().Count(), Trades = tr.Count, Wins = tr.Count(t => t.Pnl > 0), Pnl = tr.Sum(t => t.Pnl) };
            b.Blown = acc.Count - b.Passed; Batches.Add(b); BatchStart = Day; BatchJustClosed = true;
            Event(Day, null, "BATCH", b.Spent, "📦 BATCH " + b.No + " DONE (" + b.From.ToString("yyyy-MM-dd") + " → " + b.To.ToString("yyyy-MM-dd") + "): " + b.Passed + " passed, " + b.Blown + " blown of " + b.Bought + " • " + b.Days + " trading days • " + b.Trades + " trades (" + b.Wins + " won) • evaluation P/L " + b.Pnl.ToString("+0;-0", CultureInfo.InvariantCulture) + " • spent $" + b.Spent.ToString("N0", CultureInfo.InvariantCulture) + " • new evaluations today");
            if (!string.IsNullOrEmpty(Folder)) try { string f = Path.Combine(Folder, "batches.csv"); bool fresh = !File.Exists(f); File.AppendAllText(f, (fresh ? KeystoneSimBatch.Header + "\n" : "") + b.Line() + "\n"); } catch { }
        }
        // ◀ PREVIOUS DAY: the run as it was when each day started (Folder\snaps\<day index>) — restored to replay a day again
        public void Snap()
        {
            if (string.IsNullOrEmpty(Folder)) return;
            try { SaveState(); string dst = Path.Combine(Folder, "snaps", PlanIndex.ToString(CultureInfo.InvariantCulture)); Directory.CreateDirectory(dst); foreach (var f in Directory.GetFiles(Folder)) File.Copy(f, Path.Combine(dst, Path.GetFileName(f)), true); } catch { }
        }
        public static bool HasSnap(string folder, int index) { return !string.IsNullOrEmpty(folder) && index >= 0 && Directory.Exists(Path.Combine(folder, "snaps", index.ToString(CultureInfo.InvariantCulture))); }
        public static KeystonePropSim Rewind(string folder, int index)
        {
            if (!HasSnap(folder, index)) return null;
            try
            {
                string src = Path.Combine(folder, "snaps", index.ToString(CultureInfo.InvariantCulture));
                foreach (var f in Directory.GetFiles(folder)) File.Delete(f);
                foreach (var f in Directory.GetFiles(src)) File.Copy(f, Path.Combine(folder, Path.GetFileName(f)), true);
                foreach (var d in Directory.GetDirectories(Path.Combine(folder, "snaps"))) { int k; if (int.TryParse(Path.GetFileName(d), out k) && k > index) Directory.Delete(d, true); }
                return Load(folder);
            }
            catch { return null; }
        } double spentToday, cashToday; int boughtToday, passedToday, blownToday, fundedBlownToday, payoutsToday;
        readonly Dictionary<int, double> floorAtOpen = new Dictionary<int, double>();   // each account's floor when the day began (how far it moved today)
        readonly List<KeystoneSimTrade> todayTrades = new List<KeystoneSimTrade>(); readonly List<KeystoneSimAccountDay> todayRows = new List<KeystoneSimAccountDay>(); readonly List<KeystoneSimEvent> todayEvents = new List<KeystoneSimEvent>();
        public KeystonePropSim(KeystoneSimSettings s) { S = s ?? new KeystoneSimSettings(); }

        public double Spent { get { return Accounts.Sum(a => a.Spent); } }
        public double Cash { get { return Accounts.Sum(a => a.Cash); } }
        public double Net { get { return Cash - Spent; } }
        public int Bought { get { return Accounts.Count; } }
        public int PassedCount { get { return Accounts.Count(a => a.PassedOn != DateTime.MinValue); } }
        public int BlownEval { get { return Accounts.Count(a => a.Phase == "BLOWN" && a.WasPhase == "EVAL"); } }
        public int BlownFunded { get { return Accounts.Count(a => a.Phase == "BLOWN" && a.WasPhase == "FUNDED"); } }
        public int PayoutCount { get { return Accounts.Sum(a => a.Payouts); } }
        public double PassRate { get { int done = Accounts.Count(a => a.PassedOn != DateTime.MinValue || (a.Phase == "BLOWN" && a.WasPhase == "EVAL")); return done == 0 ? 0 : 100.0 * PassedCount / done; } }
        // 🎲 THE ODDS (payouts − fees is the only score): funded accounts that got paid at least once, $ a funded account brings,
        // $ each evaluation bought brings, P(a payout per evaluation) = pass × payout rate, risk of ruin = (1 − that)^N
        public int FundedEver { get { return Accounts.Count(a => a.PassedOn != DateTime.MinValue); } }
        public int FundedPaid { get { return Accounts.Count(a => a.PassedOn != DateTime.MinValue && a.Payouts > 0); } }
        public int FundedDone { get { return Accounts.Count(a => a.PassedOn != DateTime.MinValue && (a.Payouts > 0 || !a.Alive)); } }   // paid, or ended without
        public double PayoutRate { get { return FundedDone == 0 ? 0 : 100.0 * FundedPaid / FundedDone; } }
        public double PerFunded { get { return FundedEver == 0 ? 0 : Cash / FundedEver; } }
        public double PerEval { get { return Bought == 0 ? 0 : Cash / Bought; } }
        public double PPayout { get { return PassRate / 100.0 * PayoutRate / 100.0; } }
        public double Ruin(int n) { return Math.Pow(1 - Math.Max(0, Math.Min(1, PPayout)), Math.Max(0, n)); }
        public double BreakevenPayoutRate { get { double cost = S.Rules.EvalCost; return PassRate <= 0 || PerFunded <= 0 || FundedPaid == 0 ? 0 : 100.0 * cost / (PassRate / 100.0 * (Cash / FundedPaid)); } }   // the payout rate that pays the evaluations back
        public const string AiOddsSystem = "You are a prop-firm coach. The trader simulates many evaluations of the same firm before buying any (the only score is payouts minus evaluation fees; unpaid balances count for nothing). Read the simulation: rules, pass rate, payout rate, $ per funded account, risk of ruin, batches, how trades won and lost by phase, side, hour and exit, the losers' best open profit. Give: 1) is this plan worth real money now, with the numbers, 2) what to change for the EVALUATION (goal: pass) — stop / target / trades a day / filters, 3) what to change for the FUNDED stage (goal: payouts) — the same, 4) one concrete next simulation to run, with its settings. Use only the numbers given; say when a number rests on too few accounts (under 30 = a hint).";
        public string OddsPrompt()
        {
            var sb = new StringBuilder(); var ic = CultureInfo.InvariantCulture; Func<double, string> m = v => (v < 0 ? "-$" : "$") + Math.Abs(v).ToString("N0", ic);
            sb.AppendLine("SIMULATION: " + S.Describe()); sb.AppendLine("FIRM RULES: " + S.Rules.Describe());
            sb.AppendLine("DAYS " + Days.Count + " of " + Plan.Count + " • evaluations bought " + Bought + " • spent " + m(Spent) + " • payouts received " + m(Cash) + " • NET " + m(Net));
            sb.AppendLine("PASS RATE " + PassRate.ToString("0.0", ic) + "% (" + PassedCount + " passed, " + BlownEval + " blown in evaluation) • FUNDED: " + FundedEver + " ever, " + FundedPaid + " paid at least once, payout rate " + PayoutRate.ToString("0.0", ic) + "% • " + PayoutCount + " payouts");
            sb.AppendLine("$ per funded account " + m(PerFunded) + " • $ per evaluation bought " + m(PerEval) + " (cost " + m(S.Rules.EvalCost) + ") • P(payout per evaluation) " + (100 * PPayout).ToString("0.0", ic) + "% • risk of ruin: 20 evals " + (100 * Ruin(20)).ToString("0.0", ic) + "%, 50 evals " + (100 * Ruin(50)).ToString("0.0", ic) + "%");
            foreach (var b in Batches) sb.AppendLine("BATCH " + b.No + ": " + b.From.ToString("yyyy-MM-dd") + "→" + b.To.ToString("yyyy-MM-dd") + " bought " + b.Bought + " passed " + b.Passed + " blown " + b.Blown + " days " + b.Days + " trades " + b.Trades + " won " + b.Wins + " eval P/L " + m(b.Pnl));
            Action<string, Func<KeystoneSimTrade, string>> by = (title, key) =>
            {
                sb.AppendLine("BY " + title + ":");
                foreach (var g in Trades.GroupBy(key).OrderBy(g => g.Key)) sb.AppendLine("  " + g.Key + ": " + g.Count() + " trades, won " + (100.0 * g.Count(t => t.Pnl > 0) / g.Count()).ToString("0", ic) + "%, " + m(g.Sum(t => t.Pnl)));
            };
            by("PHASE", t => t.Phase); by("SIDE", t => t.Dir > 0 ? "BUY" : t.Dir < 0 ? "SELL" : "?"); by("ENTRY HOUR (NY)", t => t.Entry.Hour.ToString("00")); by("EXIT", t => t.Reason); by("WEEKDAY", t => ((int)t.Day.DayOfWeek) + " " + t.Day.DayOfWeek);
            var los = Trades.Where(t => t.Pnl < 0 && !double.IsNaN(t.Peak)).ToList();
            if (los.Count > 0) sb.AppendLine("LOSERS: " + los.Count + " • best open profit before the loss: average " + m(los.Average(t => t.Peak)) + ", " + los.Count(t => t.Peak >= 500) + " were up $500+, " + los.Count(t => t.Peak >= 1000) + " up $1,000+");
            return sb.ToString();
        }
        public bool Finished { get { return Plan.Count > 0 && PlanIndex >= Plan.Count; } }

        List<KeystoneSimFirm> firms;
        public List<KeystoneSimFirm> FirmList { get { if (firms == null) firms = KeystoneSimFirm.Parse(S.Firms, S.Rules, S.Accounts); return firms; } }
        public bool HasFirms { get { return !string.IsNullOrWhiteSpace(S.Firms) && FirmList.Count > 0 && FirmList[0].Code != ""; } }
        // the account's firm rules (one firm = the run's rules)
        public KeystoneSimRules RulesOf(KeystoneSimAccount a) { var f = FirmList; return a != null && HasFirms && a.Firm >= 0 && a.Firm < f.Count ? f[a.Firm].Rules : S.Rules; }
        public string FirmName(KeystoneSimAccount a) { var f = FirmList; return a != null && HasFirms && a.Firm >= 0 && a.Firm < f.Count ? f[a.Firm].Name : S.Rules.Name; }
        public string Rule(KeystoneSimAccount a, string what)   // the account's phase rules
        {
            var r = RulesOf(a); bool f = a != null && a.Funded;
            if (what == "DDTYPE") return f ? r.FundDdType : r.EvalDdType;
            return string.Empty;
        }
        public double Drawdown(KeystoneSimAccount a) { var r = RulesOf(a); return a != null && a.Funded ? r.FundDrawdown : r.EvalDrawdown; }
        public double Floor(KeystoneSimAccount a)
        {
            var r = RulesOf(a); bool f = a.Funded; string type = f ? r.FundDdType : r.EvalDdType; double dd = f ? r.FundDrawdown : r.EvalDrawdown, lockAt = f ? r.FundLockAt : r.EvalLockAt;
            if (type == "STATIC") return -dd;
            double peak = type == "INTRADAY" ? a.PeakIntra : a.PeakEod;
            return Math.Min(peak - dd, lockAt);
        }
        // 🛡 the buffer is made the moment a funded account's trailing floor stops at the start (TPT PRO: best equity +$2,000)
        void NoteBuffer(KeystoneSimAccount a, DateTime when)
        {
            if (a == null || !a.Funded || a.BufferOn != DateTime.MinValue) return; var r = RulesOf(a); if (r.FundDdType == "STATIC") return;
            double peak = r.FundDdType == "INTRADAY" ? a.PeakIntra : a.PeakEod; if (peak - r.FundDrawdown < r.FundLockAt - 1e-9) return;
            a.BufferOn = when.Date; Event(when, a, "BUFFER", 0, a.Name + " 🛡 BUFFER MADE: its best equity reached +$" + r.FundDrawdown.ToString("N0", CultureInfo.InvariantCulture) + " → the trailing floor is locked at the start; everything above +$" + Math.Max(r.PayoutBuffer, r.FundDrawdown).ToString("N0", CultureInfo.InvariantCulture) + " can be withdrawn");
        }
        public double DailyLoss(KeystoneSimAccount a) { var r = RulesOf(a); return a.Funded ? r.FundDailyLoss : r.EvalDailyLoss; }
        // 🛡 THE TRAILING VIEW of an account right now (open = its open P/L): equity, the peak the floor trails (INTRADAY: the best
        // equity so far, open profit included, so the floor moves the moment the trade makes a new high • EOD: the best close —
        // the floor moves only at the close • STATIC: never), the floor, the buffer to it, the drawdown from the peak, and the goal
        // (evaluation: the profit target • funded: the payout buffer — everything above it can be withdrawn)
        public KeystoneTrailView Trail(KeystoneSimAccount a, double open)
        {
            var v = new KeystoneTrailView(); if (a == null) return v; var r = RulesOf(a); bool f = a.Funded;
            v.Type = f ? r.FundDdType : r.EvalDdType; v.MaxDd = f ? r.FundDrawdown : r.EvalDrawdown; double lockAt = f ? r.FundLockAt : r.EvalLockAt;
            v.Equity = a.Bal + a.DayPnl + open;
            v.Peak = v.Type == "INTRADAY" ? Math.Max(a.PeakIntra, v.Equity) : v.Type == "EOD" ? a.PeakEod : 0;
            v.Floor = v.Type == "STATIC" ? -v.MaxDd : Math.Min(v.Peak - v.MaxDd, lockAt); v.Locked = v.Type != "STATIC" && v.Peak - v.MaxDd >= lockAt - 1e-9;
            v.Room = v.Equity - v.Floor; v.FromPeak = Math.Max(0, v.Peak - v.Equity);
            v.Goal = f ? r.PayoutBuffer : r.Target; v.GoalName = f ? (r.PayoutBuffer > 0 ? "PAYOUT BUFFER" : "PROFIT") : "PROFIT TARGET"; v.GoalLeft = Math.Max(0, v.Goal - v.Equity);
            return v;
        }
        // room before the floor with `open` P/L on the table
        public double Room(KeystoneSimAccount a, double open) { return a.Bal + a.DayPnl + open - Floor(a); }
        // no room for a trade: RETIRED at the floor when even a small trade does not fit (true), else the caller locks it for today
        public bool RetireIfNoRoom(KeystoneSimAccount a, DateTime t, double fees)
        {
            if (a == null || !a.Alive || S.MinRoomShare <= 0) return false;
            double normal = a.Funded ? S.FundRotStop : S.RotStop, room = Room(a, 0) - fees;
            if (normal <= 0 || room >= S.MinRoomShare * normal) return false;
            a.WasPhase = a.Phase; a.Phase = "RETIRED"; a.Ended = Day; a.EndReason = "at the floor";
            Event(t, a, "RETIRED", 0, a.Name + " (" + a.WasPhase + ") is $" + Math.Max(0, Room(a, 0)).ToString("N0", CultureInfo.InvariantCulture) + " above its floor — too close to carry a trade (a $" + normal.ToString("N0", CultureInfo.InvariantCulture) + " stop + $" + fees.ToString("N0", CultureInfo.InvariantCulture) + " fees): RETIRED at the floor");
            if (Active == a) Rotate();
            return true;
        }

        KeystoneSimAccount Buy(DateTime day)
        {
            int fi = 0; var fl = FirmList;
            if (HasFirms)
            {
                // firm by firm (A, B, C, A, B, C …): the next firm after the last bought that still has room for its count
                Func<int, int> have = k => S.ReplacePassed ? Accounts.Count(x => x.Firm == k && x.Phase == "EVAL") : Accounts.Count(x => x.Firm == k && x.Alive);
                fi = -1; for (int j = 1; j <= fl.Count; j++) { int k = (lastFirm + j) % fl.Count; if (have(k) < fl[k].Count) { fi = k; break; } }
                if (fi < 0) fi = (lastFirm + 1) % fl.Count; lastFirm = fi;
            }
            var rr = HasFirms ? fl[fi].Rules : S.Rules;
            bool fo = S.StartAs == "FUNDED"; double cost0 = rr.EvalCost + (fo ? rr.Activation : 0);
            var a = new KeystoneSimAccount { Id = nextId++, Bought = day, Spent = cost0, Firm = fi };
            if (fo) { a.Phase = "FUNDED"; a.WasPhase = "FUNDED"; a.PassedOn = day; }
            a.Name = HasFirms ? fl[fi].Code + "-" + (Accounts.Count(x => x.Firm == fi) + 1).ToString("00") : "A" + a.Id.ToString("00");
            Accounts.Add(a); spentToday += cost0; boughtToday++;
            Event(day.AddHours(9), a, "BOUGHT", cost0, (fo ? "new FUNDED account (funded-stage test) " : "new evaluation ") + a.Name + (HasFirms ? " (" + fl[fi].Name + ")" : ""));
            return a;
        }
        void Event(DateTime t, KeystoneSimAccount a, string kind, double amount, string text) { var e = new KeystoneSimEvent { Time = t, Account = a == null ? 0 : a.Id, Kind = kind, Amount = amount, Text = text }; Events.Add(e); todayEvents.Add(e); }

        // a new trading day: replace dead slots, reset today, the evaluations that already reached the target only wait out the
        // minimum days (one tiny trade a day ≈ the commission)
        public void BeginDay(DateTime day)
        {
            Day = day.Date; DayOpen = true; BatchJustClosed = false; copyNow = null; copyLeader = null; copyPnl.Clear(); spentToday = cashToday = 0; boughtToday = passedToday = blownToday = fundedBlownToday = payoutsToday = 0;
            todayTrades.Clear(); todayRows.Clear(); todayEvents.Clear();
            int want = HasFirms ? Math.Max(1, FirmList.Sum(f => f.Count)) : Math.Max(1, S.Accounts);
            Func<int> filled = () => S.ReplacePassed && S.StartAs != "FUNDED" ? Accounts.Count(a => a.Phase == "EVAL") : Accounts.Count(a => a.Alive);
            // BREAKEVEN: the first evaluations are the budget; a new one only once the payouts have paid back all that was spent
            // BREAKEVEN: a new batch only when every evaluation of the last one is done (passed / blown) AND the payouts have paid back all spent
            bool evalsLeft = Accounts.Any(x => x.Phase == "EVAL");
            if (Accounts.Count > 0 && !evalsLeft && (S.BuyRule == "BATCH" || CopyMode)) CloseBatch();
            if (S.AskEachBatch && S.FundedWhen == "STAGES" && !Accounts.Any(x => x.Alive && x.Funded)) { S.FundedWhen = "ASK"; FundedStarted = false; }   // the funded stage is over: the next finished batch asks again
            BatchChoicePending = S.AskEachBatch && FundWhen == "ASK" && !FundedStarted && !evalsLeft && Accounts.Any(x => x.Alive && x.Funded) && ChoiceBatch != Batches.Count;
            bool fundedStage = FundWhen == "STAGES" && !CopyMode && Accounts.Any(x => x.Alive && x.Funded);   // STAGES: the funded stage first, then a new batch
            if (!BatchChoicePending && (Accounts.Count == 0 || (!fundedStage && (S.BuyRule == "ALWAYS" || CopyMode || (S.BuyRule == "BATCH" && !evalsLeft) || (Net >= -1e-6 && !evalsLeft)))))   // COPY: every day starts with the full count (a blown batch is bought again)
            {
                int before = Accounts.Count; double spent0 = Spent; while (filled() < want) Buy(Day); waitingNoted = false;
                if (before > 0 && Accounts.Count > before) Event(Day, null, "REFILL", Spent - spent0, "bought " + (Accounts.Count - before) + " new evaluations for $" + (Spent - spent0).ToString("N0", CultureInfo.InvariantCulture) + " from the payouts (back to " + want + ")");
            }
            else if (filled() < want && !waitingNoted) { waitingNoted = true; Event(Day, null, "WAITING", 0, "no new evaluation until " + (evalsLeft ? "every evaluation is done and " : "") + "the payouts pay back what was spent (" + (want - filled()) + " to buy, net " + (Net < 0 ? "−$" : "$") + Math.Abs(Net).ToString("N0", CultureInfo.InvariantCulture) + ")"); }
            floorAtOpen.Clear(); foreach (var a0 in Accounts.Where(x => x.Alive)) floorAtOpen[a0.Id] = Floor(a0);
            foreach (var b0 in Accounts.Where(x => !x.Alive)) { b0.DayPnl = 0; b0.TradedToday = false; b0.DayTrades = 0; }   /* 🐞 BUILD 10a (the user's blown −$4,018 = twice): a blown account's last day was already booked at the close — never again */
            foreach (var a in Accounts.Where(x => x.Alive))
            {
                a.DayPnl = 0; a.DayLow = 0; a.DayHigh = 0; a.DayTrades = 0; a.DayLosses = 0; a.TradedToday = false; a.LockedToday = false; a.DayNote = string.Empty; a.DaySyms.Clear();
                if (a.Phase == "EVAL" && a.Bal >= RulesOf(a).Target && ConsistentEval(a, 0))
                {
                    // target reached, waiting for the minimum days: a 1-micro open / close counts the day
                    a.LockedToday = true; a.TradedToday = true; a.DayPnl = -KeystoneMoveStudy.Cost("MNQ"); a.DayNote = "DAY-COUNT TRADE";
                }
            }
            Active = Next(true);
        }
        // ✅ PASSED ON THE TARGET DAY (BUILD 10a, the user's rule for TPT): +target and consistent = passed in every count; a firm's minimum-days
        // day is only a tiny open / close to activate (PassedOn comes then) — the funded stage waits for it
        public bool PassedPending(KeystoneSimAccount a) { if (a == null || !a.Alive || a.Phase != "EVAL" || a.PassedOn != DateTime.MinValue) return false; return a.Bal >= RulesOf(a).Target - 1e-6 && ConsistentEval(a, 0); }
        public bool PassedOrPending(KeystoneSimAccount a) { return a != null && (a.PassedOn != DateTime.MinValue || PassedPending(a)); }
        bool ConsistentEval(KeystoneSimAccount a, double extraDay, bool today = false)
        {
            var r = RulesOf(a); double best = Math.Max(a.BestDay, today ? extraDay : 0), total = a.Bal + extraDay;
            return r.EvalConsistency <= 0 || best <= r.EvalConsistency / 100.0 * total + 1e-9;
        }
        bool HoldOk(KeystoneSimAccount a)
        {
            var r = RulesOf(a); if (r.MinHoldSeconds <= 0 || (r.HoldFundedOnly && !a.Funded)) return true; double all = a.ProfitHeld + a.ProfitShort;
            return all <= 0 || a.ProfitHeld >= r.MinHoldShare / 100.0 * all - 1e-9;
        }
        public bool CanTrade(KeystoneSimAccount a) { return a != null && a.Alive && !a.LockedToday && DayOpen && !(a.Funded && (((FundWhen == "AFTER" || FundWhen == "STAGES") && Accounts.Any(x => x.Phase == "EVAL")) || (FundWhen == "ASK" && !FundedStarted))); }
        // PASS FIRST: the funded accounts start only when you say so (after every evaluation is done)
        public bool FundedStarted;
        public bool BatchChoicePending; public int ChoiceBatch = -1;   // EVAL TEST: today waits for FUNDED STAGE or NEW BATCH (ChoiceBatch = the batch count the choice was made at)
        // 🔄 a NEW BATCH now (the passed accounts stay aside, they do not trade)
        public void NewBatchNow()
        {
            ChoiceBatch = Batches.Count; BatchChoicePending = false; int want = Math.Max(1, S.Accounts); int before = Accounts.Count;
            while (Accounts.Count(a => a.Phase == "EVAL") < want) Buy(Day);
            foreach (var a in Accounts.Skip(before)) floorAtOpen[a.Id] = Floor(a);
            Active = Next(true);
        }
        // 💜 FUNDED STAGE now: only the passed accounts trade (to their payout); no new evaluations until they are done
        public void StartFundedStage() { ChoiceBatch = Batches.Count; BatchChoicePending = false; FundedStarted = true; S.FundedWhen = "STAGES"; Active = Next(true); }
        // COPY: always PASS FIRST — the batch passes together, then you choose how the funded accounts trade
        public string FundWhen { get { return CopyMode ? "ASK" : S.FundedWhen; } }
        public bool FundedWaiting { get { return FundWhen == "ASK" && !FundedStarted && (BatchJustClosed || !Accounts.Any(x => x.Phase == "EVAL")) && Accounts.Any(x => x.Funded); } }
        public bool BatchJustClosed;   // today: the last batch is done (and a new one may have been bought this morning)
        // TODAY (or any day of the run): how many accounts traded, reached their day target, were locked for the day, passed, blew,
        // were paid — and each account's day. A day is the session 18:00 (the evening before) → 17:00.
        public KeystoneSimDaySummary DaySummary(DateTime day)
        {
            day = day.Date; var r = new KeystoneSimDaySummary { Day = day, Open = DayOpen && Day == day }; DateTime from = day.AddDays(-1).AddHours(18), to = day.AddHours(17);
            Func<DateTime, bool> inDay = t => t > from && t <= to || t == day;
            var trades = Trades.Where(t => t.Day == day).ToList(); r.Trades = trades.Count; r.Wins = trades.Count(t => t.Pnl > 0);
            var ev = Events.Where(e => inDay(e.Time)).ToList();
            foreach (var a in Accounts)
            {
                var mine = trades.Where(t => t.Account == a.Id).ToList(); bool live = r.Open && a.Alive && a.TradedToday;
                if (mine.Count == 0 && !live && !(a.PassedOn == day) && !(a.Phase == "BLOWN" && a.Ended == day)) continue;
                double pnl = live ? a.DayPnl : mine.Sum(t => t.Pnl); string phase = mine.Count > 0 ? mine[0].Phase : a.Phase;
                double goal = S.Cushioned(a) && phase == "FUNDED" ? S.FundCushionTarget : S.AcctDayTarget > 0 ? S.AcctDayTarget : S.Strategy == "ROTATION" ? (phase == "FUNDED" ? S.FundRotTarget : S.RotTarget) : 0;
                bool atTarget = goal > 0 && pnl >= goal * 0.9 - 1e-9, locked = r.Open ? a.LockedToday : ev.Any(e => e.Kind == "LOCKED" && e.Account == a.Id);
                bool passed = a.PassedOn == day, blown = a.Phase == "BLOWN" && a.Ended == day, willPass = r.Open && PassesAtClose(a); if (willPass) r.WillPass++; var pay = ev.Where(e => e.Kind == "PAYOUT" && e.Account == a.Id).ToList();
                if (mine.Count > 0 || live) r.Traded++; if (atTarget) r.AtTarget++; if (locked) r.Locked++; if (passed) r.Passed++; if (blown) r.Blown++; r.Pnl += pnl;
                string state = blown ? "💀 BLOWN" : passed ? "✔ PASSED" : willPass ? "✔ AT THE EVAL TARGET • FUNDED AT THE CLOSE" : pay.Count > 0 ? "💰 PAYOUT" : atTarget ? "🎯 AT DAY TARGET" + (locked ? " 🔒" : "") : locked ? "🔒 LOCKED" + (a.DayNote != "" && r.Open ? " • " + a.DayNote : "") : r.Open && Active == a ? "▶ IN TURN" : "";
                r.Rows.Add(new KeystoneSimDayRow { Account = a, Pnl = pnl, Trades = mine.Count, Goal = goal, State = state, AtTarget = atTarget, Locked = locked });
            }
            r.Payouts = ev.Count(e => e.Kind == "PAYOUT"); r.PayoutCash = ev.Where(e => e.Kind == "PAYOUT").Sum(e => e.Amount); r.Bought = ev.Count(e => e.Kind == "BOUGHT");
            r.Rows = r.Rows.OrderByDescending(x => x.Pnl).ToList();
            return r;
        }
        // an evaluation that has reached its target today and passes at the day's close (days, consistency, hold-time rule)
        public bool PassesAtClose(KeystoneSimAccount a)
        {
            if (a == null || a.Phase != "EVAL" || !DayOpen || a.Bal + a.DayPnl < RulesOf(a).Target) return false;
            return a.Days + (a.TradedToday ? 1 : 0) >= Math.Max(1, RulesOf(a).EvalMinDays) && ConsistentEval(a, a.DayPnl, true) && HoldOk(a);
        }
        // 💰 a funded account's payout cycles in order: each day's funded P/L (qualifying or not), the payout that closed the cycle
        // (gross, to you, the balance carried over), and the cycle running now
        public List<KeystonePayoutCycle> PayoutCycles(KeystoneSimAccount a)
        {
            var r = RulesOf(a); var list = new List<KeystonePayoutCycle>(); if (a == null || a.PassedOn == DateTime.MinValue) return list;
            var days = Trades.Where(t => t.Account == a.Id && t.Phase == "FUNDED").GroupBy(t => t.Day.Date).OrderBy(g => g.Key).Select(g => Tuple.Create(g.Key, g.Sum(t => t.Pnl))).ToList();
            if (DayOpen && a.Funded && a.TradedToday) { days.RemoveAll(d => d.Item1 == Day); days.Add(Tuple.Create(Day, a.DayPnl)); }
            var pays = Events.Where(e => e.Account == a.Id && e.Kind == "PAYOUT").OrderBy(e => e.Time).ToList(); int pi = 0;
            var cur = new KeystonePayoutCycle { No = 1, Open = true }; double bal = 0;
            foreach (var d in days)
            {
                bal += d.Item2; bool q = r.QualifyingDay <= 0 || (d.Item2 > 0 && d.Item2 >= r.QualifyingDay - 1e-9); cur.Days.Add(Tuple.Create(d.Item1, d.Item2, q)); cur.Profit += d.Item2;
                if (pi < pays.Count && pays[pi].Time.Date == d.Item1)
                {
                    cur.Cash = pays[pi].Amount; cur.Gross = r.Split > 0 ? Math.Round(cur.Cash * 100.0 / r.Split) : cur.Cash; bal -= cur.Gross; cur.BalanceAfter = bal; cur.PaidOn = d.Item1; cur.Open = false;
                    list.Add(cur); cur = new KeystonePayoutCycle { No = cur.No + 1, Open = true }; pi++;
                }
            }
            cur.BalanceAfter = bal; if (a.Funded) list.Add(cur);
            return list;
        }
        // BREAKEVEN buying: what is still owed before a new evaluation can be bought (0 = free to buy)
        public double ToBreakeven { get { return S.BuyRule == "BREAKEVEN" ? Math.Max(0, -Net) : 0; } }
        // 📈 EVAL TRACKER: every closed day — evaluations bought (since the first ones), blown, passed, the money, and what the FIRST
        // INVESTMENT alone earned (the payouts of the day-1 accounts − their evaluations and activations), from the saved days + events
        public List<KeystoneSimGrowthRow> Growth()
        {
            var rows = new List<KeystoneSimGrowthRow>(); if (Days.Count == 0) return rows;
            var bought = Events.Where(e => e.Kind == "BOUGHT").ToList();
            DateTime firstDay = bought.Count > 0 ? bought.Min(e => e.Time.Date) : Days[0].Day;
            var initial = new HashSet<int>(bought.Where(e => e.Time.Date == firstDay).Select(e => e.Account));
            double firstCost = bought.Where(e => initial.Contains(e.Account)).Sum(e => e.Amount);
            int tb = 0, tbe = 0, tbf = 0, tp = 0, tpo = 0; double fCash = 0, fAct = 0; bool paidBack = false;
            foreach (var d in Days)
            {
                var ev = Events.Where(e => e.Time.Date == d.Day).ToList();
                tb += d.Bought; tbe += d.Blown; tbf += d.FundedBlown; tp += d.Passed; tpo += d.Payouts;
                fCash += ev.Where(e => e.Kind == "PAYOUT" && initial.Contains(e.Account)).Sum(e => e.Amount);
                fAct += ev.Where(e => e.Kind == "PASSED" && initial.Contains(e.Account)).Sum(e => e.Amount);
                var g = new KeystoneSimGrowthRow
                {
                    Day = d.Day, Bought = d.Bought, TotalBought = tb, Initial = initial.Count, BlownEval = d.Blown, BlownFunded = d.FundedBlown,
                    TotalBlownEval = tbe, TotalBlownFunded = tbf, Passed = d.Passed, TotalPassed = tp, Payouts = d.Payouts, TotalPayouts = tpo,
                    EvalActive = d.EvalActive, FundedActive = d.FundedActive, Cash = d.Cash, CumCash = d.CumCash, CumSpent = d.CumSpent,
                    FirstCash = fCash, FirstSpent = firstCost + fAct, Refill = ev.Any(e => e.Kind == "REFILL"), Breakeven = ev.Any(e => e.Kind == "BREAKEVEN")
                };
                if (!paidBack && g.FirstNet >= 0 && g.FirstCash > 0) { paidBack = true; g.FirstPaidBack = true; }
                rows.Add(g);
            }
            return rows;
        }

        // the next account in turn that may still trade today (round robin by id); null = none left today
        public KeystoneSimAccount Next(bool fromStart = false)
        {
            var list = Accounts.Where(CanTrade).OrderBy(a => a.Id).ToList(); if (list.Count == 0) return null;
            if (CopyMode) return list[0];   // COPY: the first account that may trade leads, every other one copies it
            if (fromStart) return list.FirstOrDefault(a => a.Id > lastTurn) ?? list[0];
            var nx = list.FirstOrDefault(a => a.Id > lastTurn) ?? list[0]; return nx;
        }
        public void Rotate() { if (Active != null) lastTurn = Active.Id; Active = Next(); }
        // ONE SETUP PER ACCOUNT (STUDIO / MANUAL, SetupsPerAccount 1): each instrument rotates through the accounts on its own
        public bool PerSetup { get { return S.Strategy != "ROTATION" && S.SetupsPerAccount <= 1 && !CopyMode; } }
        readonly Dictionary<string, int> lastTurnBy = new Dictionary<string, int>();
        // the next account for a setup on this instrument: may trade today, no setup on it today yet, not holding another setup now
        public KeystoneSimAccount NextFor(string sym, ICollection<KeystoneSimAccount> busy)
        {
            var list = Accounts.Where(a => CanTrade(a) && !a.DaySyms.Contains(sym ?? "") && (busy == null || !busy.Contains(a))).OrderBy(a => a.Id).ToList(); if (list.Count == 0) return null;
            int lt; lastTurnBy.TryGetValue(sym ?? "", out lt); return list.FirstOrDefault(a => a.Id > lt) ?? list[0];
        }
        public void Took(KeystoneSimAccount a, string sym) { if (a == null) return; a.DaySyms.Add(sym ?? ""); lastTurnBy[sym ?? ""] = a.Id; }

        // equity check while a trade is open: "" ok • "BLOWN" (floor touched) • "DAILY LOSS" (the firm's daily loss limit)
        public string CheckEquity(KeystoneSimAccount a, double open)
        {
            if (CopyMode && a != null && a.Alive)
                foreach (var f in Followers(a).ToList())
                {
                    double fo = open * CopyRatio(f, a); string st = CheckOne(f, fo); if (st == "") continue;
                    // a copy account at its floor / daily loss is out of this trade at that loss (the leader goes on)
                    f.DayPnl += fo; copyPnl[f] = (copyPnl.ContainsKey(f) ? copyPnl[f] : 0) + fo; copyNow.Remove(f);
                    EndOne(f, new KeystoneSimTrade { Entry = Day, Exit = Day, Pnl = copyPnl[f], Reason = st, Source = "COPY of " + a.Name, Legs = "copy" }, false);
                    if (f.Alive && st == "DAILY LOSS") Lock(f, Day, "firm daily loss limit");
                }
            return CheckOne(a, open);
        }
        // ---- 📋 COPY TRADING: the accounts copying the leader's open trade (taken when it starts), each sized by its contracts
        public bool CopyMode { get { return S.Allocation == "COPY"; } }
        KeystoneSimAccount copyLeader; List<KeystoneSimAccount> copyNow; readonly Dictionary<KeystoneSimAccount, double> copyPnl = new Dictionary<KeystoneSimAccount, double>();
        public List<KeystoneSimAccount> Followers(KeystoneSimAccount leader)
        {
            if (!CopyMode || leader == null) return new List<KeystoneSimAccount>();
            if (copyNow == null || copyLeader != leader) { copyLeader = leader; copyPnl.Clear(); copyNow = Accounts.Where(x => x != leader && CanTrade(x)).OrderBy(x => x.Id).ToList(); }
            return copyNow;
        }
        double QtyOf(KeystoneSimAccount a) { return a != null && a.Funded ? S.FundMnqQty + S.FundMgcQty : S.MnqQty + S.MgcQty; }
        public double CopyRatio(KeystoneSimAccount f, KeystoneSimAccount leader) { double q = QtyOf(leader); return q <= 0 ? 1 : QtyOf(f) / q; }
        string CheckOne(KeystoneSimAccount a, double open)
        {
            if (a == null || !a.Alive) return string.Empty;
            double eq = a.Bal + a.DayPnl + open; a.DayLow = Math.Min(a.DayLow, a.DayPnl + open); a.DayHigh = Math.Max(a.DayHigh, a.DayPnl + open);
            string type = a.Funded ? RulesOf(a).FundDdType : RulesOf(a).EvalDdType;
            if (type == "INTRADAY") a.PeakIntra = Math.Max(a.PeakIntra, eq);
            if (eq <= Floor(a) + 1e-9) return "BLOWN";
            NoteBuffer(a, Day);
            double dl = DailyLoss(a); if (dl > 0 && a.DayPnl + open <= -dl + 1e-9) return "DAILY LOSS";
            return string.Empty;
        }
        // realized P/L of a closed fill (both instruments of a rotation come one by one)
        public void AddFill(KeystoneSimAccount a, double net)
        {
            if (a == null || !a.Alive) return;
            if (CopyMode) foreach (var f in Followers(a)) { if (!f.Alive) continue; double v = net * CopyRatio(f, a); f.DayPnl += v; f.TradedToday = true; f.DayLow = Math.Min(f.DayLow, f.DayPnl); f.DayHigh = Math.Max(f.DayHigh, f.DayPnl); copyPnl[f] = (copyPnl.ContainsKey(f) ? copyPnl[f] : 0) + v; }
            AddOne(a, net);
        }
        void AddOne(KeystoneSimAccount a, double net) { if (a == null || !a.Alive) return; a.DayPnl += net; a.TradedToday = true; a.DayLow = Math.Min(a.DayLow, a.DayPnl); a.DayHigh = Math.Max(a.DayHigh, a.DayPnl); }
        // a whole trade (flat → flat) for the account: counts, the hold-time rule, day limits, blown?, the next account
        public void EndTrade(KeystoneSimAccount a, KeystoneSimTrade t)
        {
            if (a == null || t == null) return;
            if (CopyMode && copyLeader == a && copyNow != null)
            {
                foreach (var f in copyNow.Where(x => x.Alive).ToList())
                {
                    double pnl = copyPnl.ContainsKey(f) ? copyPnl[f] : 0;
                    var ct = new KeystoneSimTrade { Entry = t.Entry, Exit = t.Exit, EntryPx = t.EntryPx, ExitPx = t.ExitPx, Dir = t.Dir, Legs = t.Legs, Pnl = pnl, Reason = t.Reason, Source = "COPY of " + a.Name + (string.IsNullOrEmpty(t.Source) ? "" : " • " + t.Source) };
                    if (!f.TradedToday && pnl == 0) continue; EndOne(f, ct, false);
                }
                copyNow = null; copyLeader = null; copyPnl.Clear();
            }
            EndOne(a, t, true);
        }
        void EndOne(KeystoneSimAccount a, KeystoneSimTrade t, bool rotate)
        {
            if (a == null || t == null) return; t.Day = Day; t.Account = a.Id; t.Phase = a.Phase; Trades.Add(t); todayTrades.Add(t);
            a.Trades++; a.DayTrades++; if (t.Pnl > 0) a.Wins++; else a.DayLosses++;
            if (t.Pnl > 0) { if ((t.Exit - t.Entry).TotalSeconds >= RulesOf(a).MinHoldSeconds) a.ProfitHeld += t.Pnl; else a.ProfitShort += t.Pnl; }
            if (a.Alive && a.Bal + a.DayPnl <= Floor(a) + 1e-9) Blow(a, t.Exit, "equity at the drawdown floor");
            if (a.Alive)
            {
                // an evaluation at its target stops for today when it would pass (consistent); if its best day is still too big it
                // keeps trading to bring the share down
                double left = a.Phase == "EVAL" ? RulesOf(a).Target - (a.Bal + a.DayPnl) : double.MaxValue;
                if (left <= 0 && !ConsistentEval(a, a.DayPnl, true)) left = 1;
                double goal = S.DayGoalOf(a);
                if (S.PlanOf(a.Funded) == "ONEWIN" && t.Pnl > 0) Lock(a, t.Exit, "won today (one win a day) • day " + a.DayPnl.ToString("+0;-0", CultureInfo.InvariantCulture));
                else if (goal > 0 && a.DayPnl >= goal * 0.9 - 1e-9) Lock(a, t.Exit, "day target reached • day " + a.DayPnl.ToString("+0;-0", CultureInfo.InvariantCulture));
                else if (S.AcctDayStop > 0 && a.DayPnl <= -S.AcctDayStop + 1e-9) Lock(a, t.Exit, "day stop");
                else if (S.MaxLossesPerDay > 0 && a.DayLosses >= S.MaxLossesPerDay) Lock(a, t.Exit, a.DayLosses + " losses");
                else if (!PerSetup && S.MaxTradesOf(a.Funded) > 0 && a.DayTrades >= S.MaxTradesOf(a.Funded)) Lock(a, t.Exit, a.DayTrades + " trade" + (a.DayTrades == 1 ? "" : "s") + (a.Funded ? " (funded)" : ""));
                else if (left <= 0) Lock(a, t.Exit, "evaluation target reached");
                else if (DailyLoss(a) > 0 && a.DayPnl <= -DailyLoss(a) + 1e-9) Lock(a, t.Exit, "firm daily loss limit");
            }
            if (rotate && (S.Strategy == "ROTATION" || S.RotateBy != "DAY" || !CanTrade(Active))) Rotate();
        }
        public void Lock(KeystoneSimAccount a, DateTime t, string why) { if (a == null || a.LockedToday) return; a.LockedToday = true; a.DayNote = why; Event(t, a, "LOCKED", 0, a.Name + " done for today: " + why); }
        public void Blow(KeystoneSimAccount a, DateTime t, string why)
        {
            if (a == null || !a.Alive) return; a.WasPhase = a.Phase; a.Phase = "BLOWN"; a.Ended = Day; a.EndReason = why; a.LockedToday = true;
            if (a.WasPhase == "FUNDED") fundedBlownToday++; else blownToday++;
            Event(t, a, "BLOWN", a.Bal + a.DayPnl, a.Name + " " + a.WasPhase + " blown • " + why + " • balance " + (a.Bal + a.DayPnl).ToString("+0;-0", CultureInfo.InvariantCulture) + " vs floor " + Floor(a).ToString("+0;-0", CultureInfo.InvariantCulture));
            if (Active == a) Rotate();
        }

        // the close: days, pass, payouts, blown at the close, the account rows and the day row (saved)
        public KeystoneSimDay EndDay()
        {
            if (!DayOpen) return Days.LastOrDefault(); DayOpen = false; DateTime close = Day.AddHours(17);
            foreach (var a in Accounts.Where(x => (x.Alive && x.TradedToday) || (x.Phase == "BLOWN" && x.Ended == Day && x.TradedToday)))
            {
                var r = RulesOf(a);
                string ev = string.Empty; double pnl = a.DayPnl; bool wasAlive = a.Alive; string phaseToday = wasAlive ? a.Phase : a.WasPhase;
                a.Bal += pnl; a.Days++; if (phaseToday == "FUNDED") a.FundedDays++; else a.EvalDays++;
                if (!wasAlive) { todayRows.Add(new KeystoneSimAccountDay { Day = Day, Account = a.Id, Phase = phaseToday, Pnl = pnl, Low = a.DayLow, Balance = a.Bal, Floor = Floor(a), Trades = a.DayTrades, Event = "BLOWN" }); continue; }
                a.BestDay = Math.Max(a.BestDay, pnl); a.PeakEod = Math.Max(a.PeakEod, a.Bal); a.PeakIntra = Math.Max(a.PeakIntra, a.Bal); NoteBuffer(a, close);
                if (a.Bal <= Floor(a) + 1e-9) { Blow(a, close, "closed at the drawdown floor"); ev = "BLOWN"; }
                else if (a.Phase == "EVAL")
                {
                    double tolDC = a.DayNote == "DAY-COUNT TRADE" ? KeystoneMoveStudy.Cost("MNQ") + 0.01 : 0;   /* the day-count trade's own commission doesn't undo the pass (TPT passes on day 3, not 4) */
                    double balDC = a.Bal; a.Bal += tolDC; bool consistent = ConsistentEval(a, 0), hold = HoldOk(a); a.Bal = balDC;   /* … nor the best-day share */
                    if (a.Bal >= r.Target - tolDC && a.Days >= Math.Max(1, r.EvalMinDays) && consistent && hold)
                    {
                        a.Phase = "FUNDED"; a.WasPhase = "FUNDED"; a.PassedOn = Day; a.Spent += r.Activation; spentToday += r.Activation; passedToday++;
                        a.Bal = 0; a.PeakEod = 0; a.PeakIntra = 0; a.BestDay = 0; a.Days = 0; a.Qualifying = 0; a.SinceProfit = 0; a.SinceBest = 0; a.ProfitHeld = 0; a.ProfitShort = 0;
                        ev = "PASSED"; Event(close, a, "PASSED", r.Activation, a.Name + " PASSED the evaluation in " + a.EvalDays + " days → FUNDED" + (r.Activation > 0 ? " (activation $" + r.Activation.ToString("N0", CultureInfo.InvariantCulture) + ")" : ""));
                    }
                    else if (a.Bal >= r.Target) ev = !consistent ? "AT TARGET • consistency (best day " + (100 * a.BestDay / Math.Max(1, a.Bal)).ToString("0") + "%)" : !hold ? "AT TARGET • hold-time rule" : "AT TARGET • " + a.Days + " of " + r.EvalMinDays + " days";
                }
                else if (a.Phase == "FUNDED")
                {
                    if (pnl >= r.QualifyingDay - 1e-9 && pnl > 0 || r.QualifyingDay <= 0) a.Qualifying++;
                    a.SinceProfit += pnl; a.SinceBest = Math.Max(a.SinceBest, pnl);
                    bool cons = r.PayoutConsistency <= 0 || a.SinceBest <= r.PayoutConsistency / 100.0 * a.SinceProfit + 1e-9;
                    double above = a.Bal - r.PayoutBuffer;
                    if (a.Qualifying >= Math.Max(1, r.PayoutDays) && above > 0 && cons && HoldOk(a))
                    {
                        double gross = above * r.PayoutPercent / 100.0; if (r.PayoutCap > 0) gross = Math.Min(gross, r.PayoutCap); gross = Math.Floor(gross);
                        if (gross >= Math.Max(1, r.PayoutMin))
                        {
                            double cash = gross * r.Split / 100.0; a.Bal -= gross; a.Payouts++; a.Qualifying = 0; a.SinceProfit = 0; a.SinceBest = 0; a.Cash += cash; a.Gross += gross; cashToday += cash; payoutsToday++;
                            ev = "PAYOUT"; Event(close, a, "PAYOUT", cash, a.Name + " payout #" + a.Payouts + ": $" + gross.ToString("N0", CultureInfo.InvariantCulture) + " → you get $" + cash.ToString("N0", CultureInfo.InvariantCulture));
                            if (r.MaxPayouts > 0 && a.Payouts >= r.MaxPayouts) { a.WasPhase = "FUNDED"; a.Phase = "RETIRED"; a.Ended = Day; a.EndReason = "max payouts"; Event(close, a, "RETIRED", 0, a.Name + " reached " + r.MaxPayouts + " payouts (moved on by the firm)"); }
                        }
                    }
                }
                var rr0 = RulesOf(a); string ddt = a.Funded ? rr0.FundDdType : rr0.EvalDdType; double fl0 = a.Alive ? Floor(a) : 0; double prevFloor; floorAtOpen.TryGetValue(a.Id, out prevFloor);
                todayRows.Add(new KeystoneSimAccountDay { DdType = ddt, Peak = ddt == "INTRADAY" ? a.PeakIntra : a.PeakEod, Room = a.Alive ? a.Bal - fl0 : 0, FloorMove = a.Alive && floorAtOpen.ContainsKey(a.Id) && phaseToday == a.Phase ? fl0 - prevFloor : 0, Buffer = a.BufferOn == Day, Day = Day, Account = a.Id, Phase = phaseToday, Pnl = pnl, Low = a.DayLow, Balance = a.Bal, Floor = fl0, Trades = a.DayTrades, Event = ev != "" ? ev : a.DayNote });
            }
            var prev = Days.LastOrDefault();
            var d = new KeystoneSimDay { Day = Day, Trades = todayTrades.Count, Wins = todayTrades.Count(t => t.Pnl > 0), Pnl = todayRows.Sum(x => x.Pnl), Bought = boughtToday, Passed = passedToday, Blown = blownToday, FundedBlown = fundedBlownToday, Payouts = payoutsToday, Spent = spentToday, Cash = cashToday,
                CumSpent = (prev == null ? 0 : prev.CumSpent) + spentToday, CumCash = (prev == null ? 0 : prev.CumCash) + cashToday, EvalActive = Accounts.Count(a => a.Phase == "EVAL"), FundedActive = Accounts.Count(a => a.Phase == "FUNDED") };
            double prevNet = prev == null ? double.MinValue : prev.CumCash - prev.CumSpent, nowNet = d.CumCash - d.CumSpent;
            if (d.Cash > 0 && nowNet >= -1e-6 && (prev == null || prevNet < -1e-6)) Event(close, null, "BREAKEVEN", nowNet, "BREAKEVEN: the payouts have paid back everything spent ($" + d.CumSpent.ToString("N0", CultureInfo.InvariantCulture) + ") • net +$" + nowNet.ToString("N0", CultureInfo.InvariantCulture));
            AccountDays.AddRange(todayRows);   /* 📒 BUILD 11b: every account-day kept in memory (the run record, the account card, the export) */
            Days.Add(d); Save(d);
            return d;
        }

        // ---- saving (append as the days go by) and loading a run back
        void Save(KeystoneSimDay d)
        {
            if (string.IsNullOrEmpty(Folder)) return;
            try
            {
                Directory.CreateDirectory(Folder);
                Action<string, string, IEnumerable<string>> app = (file, head, lines) => { string p = Path.Combine(Folder, file); bool fresh = !File.Exists(p); var l = lines.ToList(); if (fresh) l.Insert(0, head); if (l.Count > 0) File.AppendAllLines(p, l); };
                app("days.csv", KeystoneSimDay.Header, new[] { d.Line() });
                app("account_days.csv", KeystoneSimAccountDay.Header, todayRows.Select(x => x.Line()));
                app("trades.csv", KeystoneSimTrade.Header, todayTrades.Select(x => x.Line()));
                app("events.csv", KeystoneSimEvent.Header, todayEvents.Select(x => x.Line()));
                SaveState();
            }
            catch { }
        }
        public void SaveState()
        {
            if (string.IsNullOrEmpty(Folder)) return;
            try
            {
                Directory.CreateDirectory(Folder);
                File.WriteAllText(Path.Combine(Folder, "settings.txt"), S.ToText());
                File.WriteAllLines(Path.Combine(Folder, "accounts.csv"), new[] { KeystoneSimAccount.Header }.Concat(Accounts.Select(a => a.Line())));
                File.WriteAllText(Path.Combine(Folder, "state.txt"), "plan=" + string.Join(";", Plan.Select(x => x.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture))) + "\nindex=" + PlanIndex + "\nnext=" + nextId + "\nturn=" + lastTurn + "\nfunded=" + (FundedStarted ? 1 : 0) + "\nchoice=" + ChoiceBatch + "\nfirm=" + lastFirm + "\nbatch=" + BatchStart.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture));
            }
            catch { }
        }
        public static KeystonePropSim Load(string folder)
        {
            if (string.IsNullOrEmpty(folder) || !Directory.Exists(folder)) return null;
            try
            {
                var set = File.Exists(Path.Combine(folder, "settings.txt")) ? KeystoneSimSettings.FromText(File.ReadAllText(Path.Combine(folder, "settings.txt"))) : new KeystoneSimSettings();
                var sim = new KeystonePropSim(set) { Folder = folder };
                string ap = Path.Combine(folder, "accounts.csv"); if (File.Exists(ap)) foreach (var l in File.ReadAllLines(ap).Skip(1)) { var a = KeystoneSimAccount.Parse(l); if (a != null) sim.Accounts.Add(a); }
                string dp = Path.Combine(folder, "days.csv"); if (File.Exists(dp)) foreach (var l in File.ReadAllLines(dp).Skip(1)) { var x = KeystoneSimDay.Parse(l); if (x != null) sim.Days.Add(x); }
                string ep = Path.Combine(folder, "events.csv"); if (File.Exists(ep)) foreach (var l in File.ReadAllLines(ep).Skip(1)) { var x = KeystoneSimEvent.Parse(l); if (x != null) sim.Events.Add(x); }
                string tp = Path.Combine(folder, "trades.csv");
                if (File.Exists(tp))
                    foreach (var l in File.ReadAllLines(tp).Skip(1))
                    {
                        var a = l.Split(','); if (a.Length < 11) continue; DateTime dd; double net; int acc, hold; if (!DateTime.TryParseExact(a[0], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out dd)) continue;
                        double.TryParse(a[8], NumberStyles.Float, CultureInfo.InvariantCulture, out net); int.TryParse(a[1], out acc); int.TryParse(a[5], out hold);
                        TimeSpan ti; DateTime entry = TimeSpan.TryParse(a[3], CultureInfo.InvariantCulture, out ti) ? dd.Add(ti) : dd;
                        var tr = new KeystoneSimTrade { Day = dd, Account = acc, Phase = a[2], Entry = entry, Exit = entry.AddSeconds(hold), Dir = a[6] == "BUY" ? 1 : a[6] == "SELL" ? -1 : 0, Legs = a[7], Pnl = net, Reason = a[9], Source = a[10] };
                        double pk, wr; if (a.Length > 12 && double.TryParse(a[11], NumberStyles.Float, CultureInfo.InvariantCulture, out pk) && double.TryParse(a[12], NumberStyles.Float, CultureInfo.InvariantCulture, out wr)) { tr.Peak = pk; tr.Worst = wr; }
                        double epx, xpx; if (a.Length > 14 && double.TryParse(a[13], NumberStyles.Float, CultureInfo.InvariantCulture, out epx) && double.TryParse(a[14], NumberStyles.Float, CultureInfo.InvariantCulture, out xpx)) { tr.EntryPx = epx; tr.ExitPx = xpx; }
                        sim.Trades.Add(tr);
                    }
                string sp = Path.Combine(folder, "state.txt");
                if (File.Exists(sp))
                    foreach (var l in File.ReadAllLines(sp))
                    {
                        int k = l.IndexOf('='); if (k < 0) continue; string key = l.Substring(0, k), v = l.Substring(k + 1);
                        if (key == "plan") foreach (var p in v.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries)) { DateTime d; if (DateTime.TryParseExact(p, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d)) sim.Plan.Add(d); }
                        else if (key == "batch") { DateTime bd; if (DateTime.TryParseExact(v.Trim(), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out bd)) sim.BatchStart = bd; }
                        else if (key == "index") int.TryParse(v, out sim.PlanIndex); else if (key == "next") int.TryParse(v, out sim.nextId); else if (key == "turn") int.TryParse(v, out sim.lastTurn); else if (key == "funded") sim.FundedStarted = v.Trim() == "1"; else if (key == "choice") int.TryParse(v, out sim.ChoiceBatch); else if (key == "firm") int.TryParse(v, out sim.lastFirm);
                    }
                string bp = Path.Combine(folder, "batches.csv"); if (File.Exists(bp)) foreach (var l in File.ReadAllLines(bp).Skip(1)) { var b = KeystoneSimBatch.Parse(l); if (b != null) sim.Batches.Add(b); }
                if (sim.nextId <= sim.Accounts.Count) sim.nextId = sim.Accounts.Count == 0 ? 1 : sim.Accounts.Max(a => a.Id) + 1;
                return sim;
            }
            catch { return null; }
        }
        // the run's weekdays: [from, to], weekdays only (the studio fetches a missing day from NinjaTrader)
        public static List<DateTime> Weekdays(DateTime from, DateTime to)
        {
            var list = new List<DateTime>(); for (var d = from.Date; d <= to.Date; d = d.AddDays(1)) if (d.DayOfWeek != DayOfWeek.Saturday && d.DayOfWeek != DayOfWeek.Sunday) list.Add(d);
            return list;
        }
    }

    // ROTATION driver: one trade at a time on MNQ + MGC together (both the same way), one combined $ target and stop from the
    // entry; profit-lock tiers and a breakeven step raise the stop; the target waits for the minimum hold time.
    // ---- 🧪 EVAL LAB 📅 START-DAY TEST (pure, no UI): a new batch of the pool starts on EVERY trading day of the range; each batch runs until every
    // account has passed or blown (or the data / 30 trading days end) — then the table by start weekday × period, and a self-contained HTML report
    public sealed class KeystoneStartBatch { public DateTime Start; public int N, Passed, Blown, Open, Days; }
    public sealed class KeystoneStartStat { public string Period = ""; public int Weekday, Batches, Open, Med, P10, P90; public double PassPct, Ge5, None, AvgDays; }
    public static class KeystoneStartDay
    {
        public static List<KeystoneStartBatch> Run(KeystoneSimSettings st, IList<KeystoneRotDay> days, Func<bool> cancel, Action<int, int> progress, int maxDays = 30, DateTime lastStart = default(DateTime))
        {
            var res = new List<KeystoneStartBatch>(); if (st == null || days == null) return res;
            var probe = new KeystonePropSim(st); int n = probe.HasFirms ? Math.Max(1, probe.FirmList.Sum(f => f.Count)) : Math.Max(1, st.Accounts);
            for (int i = 0; i < days.Count; i++)
            {
                if (cancel != null && cancel()) break; var d0 = days[i].Day.DayOfWeek; if (d0 == DayOfWeek.Saturday || d0 == DayOfWeek.Sunday) continue;
                if (lastStart != default(DateTime) && days[i].Day > lastStart) break;   /* batches start up to lastStart; later days only finish them */
                bool funded = st.StartAs == "FUNDED"; Func<KeystoneSimAccount, bool> won = a => funded ? a.BufferOn != DateTime.MinValue || a.Payouts > 0 : a.PassedOn != DateTime.MinValue;
                var s = st.Copy(); s.BuyRule = "BATCH"; s.AskEachBatch = false; if (!funded) s.FundedWhen = "ASK"; s.ReplacePassed = true;   /* the passed ones wait (they never take a turn from the evaluations) */ s.From = days[i].Day; s.To = days[Math.Min(days.Count - 1, i + maxDays - 1)].Day;
                bool done = false; int ran = 0; var slice = days.Skip(i).Take(maxDays).ToList();
                var sim = KeystoneRotationLab.Run(s, slice, s.StartHhmm, s.EndHhmm, () => done || (cancel != null && cancel()), null, (sm, day) =>
                {
                    ran++; var first = sm.Accounts.OrderBy(a => a.Id).Take(n).ToList();
                    if (first.Count >= n && first.All(a => won(a) || !a.Alive)) done = true;
                });
                var acc = sim.Accounts.OrderBy(a => a.Id).Take(n).ToList(); int passed = acc.Count(won), blown = acc.Count(a => !won(a) && !a.Alive);
                res.Add(new KeystoneStartBatch { Start = days[i].Day, N = n, Passed = passed, Blown = blown, Open = n - passed - blown, Days = ran });
                if (progress != null) progress(i + 1, days.Count);
            }
            return res;
        }
        // the periods relative to the last saved day: each year of the range, LAST YEAR, LAST 3 MONTHS, LAST 3 WEEKS, LAST 5 DAYS (the 5 latest starts)
        public static List<Tuple<string, Func<KeystoneStartBatch, bool>>> Periods(List<KeystoneStartBatch> b, DateTime lastDay)
        {
            var list = new List<Tuple<string, Func<KeystoneStartBatch, bool>>> { Tuple.Create("ALL", (Func<KeystoneStartBatch, bool>)(x => true)) };
            foreach (var y in b.Select(x => x.Start.Year).Distinct().OrderBy(y => y)) { int yy = y; list.Add(Tuple.Create(yy.ToString(CultureInfo.InvariantCulture), (Func<KeystoneStartBatch, bool>)(x => x.Start.Year == yy))); }
            list.Add(Tuple.Create("LAST YEAR", (Func<KeystoneStartBatch, bool>)(x => x.Start > lastDay.AddYears(-1))));
            list.Add(Tuple.Create("LAST 3 MONTHS", (Func<KeystoneStartBatch, bool>)(x => x.Start > lastDay.AddMonths(-3))));
            list.Add(Tuple.Create("LAST 3 WEEKS", (Func<KeystoneStartBatch, bool>)(x => x.Start > lastDay.AddDays(-21))));
            var last5 = new HashSet<DateTime>(b.Select(x => x.Start).Distinct().OrderByDescending(x => x).Take(5));
            list.Add(Tuple.Create("LAST 5 DAYS", (Func<KeystoneStartBatch, bool>)(x => last5.Contains(x.Start))));
            return list;
        }
        public static KeystoneStartStat Stat(string period, int weekday, IList<KeystoneStartBatch> q)
        {
            var r = new KeystoneStartStat { Period = period, Weekday = weekday, Batches = q.Count }; if (q.Count == 0) return r;
            int nAll = q.Sum(x => x.N); var per = q.Select(x => x.Passed).OrderBy(x => x).ToList();
            r.PassPct = nAll == 0 ? 0 : 100.0 * q.Sum(x => x.Passed) / nAll; r.Med = per[per.Count / 2]; r.P10 = per[per.Count / 10]; r.P90 = per[Math.Min(per.Count - 1, per.Count * 9 / 10)];
            r.Ge5 = 100.0 * per.Count(x => x >= 5) / per.Count; r.None = 100.0 * per.Count(x => x == 0) / per.Count; r.AvgDays = q.Average(x => (double)x.Days); r.Open = q.Sum(x => x.Open); return r;
        }
        public static List<KeystoneStartStat> Table(List<KeystoneStartBatch> b, DateTime lastDay)
        {
            var res = new List<KeystoneStartStat>();
            foreach (var p in Periods(b, lastDay)) { var q = b.Where(p.Item2).ToList(); if (q.Count == 0) continue; res.Add(Stat(p.Item1, 0, q)); for (int w = 1; w <= 5; w++) res.Add(Stat(p.Item1, w, q.Where(x => (int)x.Start.DayOfWeek == w).ToList())); }
            return res;
        }
        public static readonly string[] WeekdayNames = { "ALL WEEKDAYS", "MONDAY", "TUESDAY", "WEDNESDAY", "THURSDAY", "FRIDAY" };
        public static string Csv(string plan, List<KeystoneStartBatch> b, DateTime lastDay)
        {
            var ic = CultureInfo.InvariantCulture; var sb = new StringBuilder("plan,period,start_weekday,batches,pass_pct,median_per_batch,p10,p90,five_plus_pct,none_pct,days_per_batch,open_at_data_end\n");
            foreach (var r in Table(b, lastDay)) sb.AppendLine(string.Join(",", plan.Replace(",", " "), r.Period, WeekdayNames[r.Weekday], r.Batches, r.PassPct.ToString("0.0", ic), r.Med, r.P10, r.P90, r.Ge5.ToString("0", ic), r.None.ToString("0", ic), r.AvgDays.ToString("0.0", ic), r.Open));
            sb.AppendLine(); sb.AppendLine("plan,batch_start,weekday,accounts,passed,blown,open,trading_days");
            foreach (var x in b) sb.AppendLine(string.Join(",", plan.Replace(",", " "), x.Start.ToString("yyyy-MM-dd"), x.Start.DayOfWeek, x.N, x.Passed, x.Blown, x.Open, x.Days));
            return sb.ToString();
        }
        static string H(string x) { return System.Net.WebUtility.HtmlEncode(x ?? ""); }
        // a self-contained HTML report (prints cleanly: the browser's Print → Save as PDF)
        public static string Html(string title, List<Tuple<string, string, List<KeystoneStartBatch>>> plans, DateTime from, DateTime to, DateTime lastDay)
        {
            var ic = CultureInfo.InvariantCulture; var sb = new StringBuilder();
            sb.Append("<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>").Append(H(title)).Append("</title><style>");
            sb.Append(":root{--bg:#0f1320;--panel:#161b2b;--line:#2a3148;--tx:#dfe3ee;--mu:#8a91a8;--up:#22b8a0;--dn:#ef5466;--warn:#f2b33d}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--tx);font:15px/1.5 'Segoe UI',system-ui,sans-serif}");
            sb.Append(".wrap{max-width:1120px;margin:0 auto;padding:28px 16px 48px}h1{font-size:30px;margin:0 0 6px}h2{font-size:20px;margin:34px 0 8px}.sub{color:var(--mu);max-width:85ch}");
            sb.Append(".box{background:var(--panel);border:1px solid var(--line);border-left:4px solid var(--up);border-radius:10px;padding:12px 16px;margin:10px 0}.tbl{overflow-x:auto;background:var(--panel);border:1px solid var(--line);border-radius:10px;margin:10px 0}");
            sb.Append("table{border-collapse:collapse;width:100%;font-size:13.5px}th,td{padding:6px 10px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}th:first-child,td:first-child{text-align:left}th{color:var(--mu);font-weight:500;font-size:11px;text-transform:uppercase;letter-spacing:.05em}");
            sb.Append("td.n{font-family:Consolas,monospace}tr.hi td{background:#1b2c3a}small{color:var(--mu);font-size:11px}");
            sb.Append("@media print{body{background:#fff;color:#111}.box,.tbl{background:#fff;border-color:#bbb}th,small,.sub{color:#555}tr.hi td{background:#eef6f3}.tbl,.box{break-inside:avoid}h2{break-after:avoid}}</style></head><body><div class=\"wrap\">");
            sb.Append("<h1>").Append(H(title)).Append("</h1><p class=\"sub\">KeyStone 🧪 EVAL LAB • 📅 START-DAY TEST • saved MNQ + MGC minutes ").Append(from.ToString("yyyy-MM-dd", ic)).Append(" → ").Append(to.ToString("yyyy-MM-dd", ic))
              .Append(" • a new batch starts on every trading day and runs until every account has passed or blown • take profit after costs • $1 a contract round trip + 1 tick a side • the last day saved: ").Append(lastDay.ToString("ddd dd MMM yyyy", ic)).Append("</p>");
            sb.Append("<h2>How the drawdown room works</h2><div class=\"tbl\"><table><tr><th>Day result</th><th>Room the next day</th></tr><tr><td>+$1,500</td><td class=\"n\">$2,000 (full: the floor moved up with the balance)</td></tr><tr><td>breakeven</td><td class=\"n\">$2,000 (full)</td></tr><tr><td>−$1,500</td><td class=\"n\">$500</td></tr><tr><td>−$2,000</td><td class=\"n\">blown — can't trade</td></tr></table></div>");
            if (plans.Count > 1)
            {
                sb.Append("<h2>Plans side by side</h2><div class=\"tbl\"><table><tr><th>Plan</th>");
                var pers = plans.SelectMany(p => Periods(p.Item3, lastDay).Select(x => x.Item1)).Distinct().ToList(); foreach (var pe in pers) sb.Append("<th>").Append(H(pe)).Append("</th>"); sb.Append("</tr>");
                foreach (var p in plans) { var t = Table(p.Item3, lastDay); sb.Append("<tr><td>").Append(H(p.Item1)).Append("</td>"); foreach (var pe in pers) { var r = t.FirstOrDefault(x => x.Period == pe && x.Weekday == 0); sb.Append("<td class=\"n\">").Append(r == null ? "—" : r.PassPct.ToString("0.0", ic) + "%<br><small>" + r.Batches + "</small>").Append("</td>"); } sb.Append("</tr>"); }
                sb.Append("</table></div>");
            }
            foreach (var p in plans)
            {
                var t = Table(p.Item3, lastDay); var all = t.FirstOrDefault(x => x.Period == "ALL" && x.Weekday == 0);
                sb.Append("<h2>").Append(H(p.Item1)).Append("</h2><p class=\"sub\">").Append(H(p.Item2)).Append("</p>");
                if (all != null) sb.Append("<div class=\"box\"><b>").Append(all.PassPct.ToString("0.0", ic)).Append("% passed</b> over ").Append(all.Batches).Append(" batches • a median of <b>").Append(all.Med).Append("</b> per batch (10th–90th ").Append(all.P10).Append("–").Append(all.P90).Append(") • 5+ passed in ").Append(all.Ge5.ToString("0", ic)).Append("% • none passed in ").Append(all.None.ToString("0", ic)).Append("% • ").Append(all.AvgDays.ToString("0.0", ic)).Append(" trading days per batch</div>");
                sb.Append("<div class=\"tbl\"><table><tr><th>Batches started</th>"); foreach (var wn in WeekdayNames) sb.Append("<th>").Append(wn).Append("</th>"); sb.Append("<th>Median (10th–90th)</th><th>5+ passed</th><th>None</th><th>Days</th><th>Open at data end</th></tr>");
                foreach (var pe in t.Select(x => x.Period).Distinct())
                {
                    var row = t.Where(x => x.Period == pe).OrderBy(x => x.Weekday).ToList(); var a = row[0];
                    sb.Append("<tr class=\"").Append(pe == "ALL" ? "hi" : "").Append("\"><td>").Append(H(pe)).Append("</td>");
                    foreach (var r in row) sb.Append("<td class=\"n\">").Append(r.Batches == 0 ? "—" : r.PassPct.ToString("0.0", ic) + "%<br><small>" + r.Batches + "</small>").Append("</td>");
                    sb.Append("<td class=\"n\">").Append(a.Med).Append(" (").Append(a.P10).Append("–").Append(a.P90).Append(")</td><td class=\"n\">").Append(a.Ge5.ToString("0", ic)).Append("%</td><td class=\"n\">").Append(a.None.ToString("0", ic)).Append("%</td><td class=\"n\">").Append(a.AvgDays.ToString("0.0", ic)).Append("</td><td class=\"n\">").Append(a.Open).Append("</td></tr>");
                }
                sb.Append("</table></div>");
            }
            sb.Append("<p class=\"sub\">Past results don't promise future ones. Batches started in the last days may still be open when the saved data ends (the last column). Exits are checked on 1-minute bars.</p></div></body></html>");
            return sb.ToString();
        }
    }
    public sealed class KeystoneSimRotation
    {
        public bool InTrade; public int Dir, DirG; public DateTime OpenedAt = DateTime.MinValue, PauseUntil = DateTime.MinValue; public double Peak, Worst, Floor, Target, Stop, Fees; public KeystoneSimAccount Acct;
        public bool TrailStop;   // the stop follows the peak: Floor = max(Floor, Peak − Stop)
        readonly Random rng; int turn;
        public KeystoneSimRotation(int seed) { rng = new Random(seed); }
        // the direction choices: code, name (MNQ side first, then MGC)
        public static readonly string[][] Directions =
        {
            new[] { "RANDOM", "RANDOM • BUY-BUY OR SELL-SELL" }, new[] { "RANDOM4", "RANDOM • ANY OF THE 4 (BB / SS / BS / SB)" }, new[] { "RANDOMHEDGE", "RANDOM • BUY-SELL OR SELL-BUY" },
            new[] { "CYCLE4", "IN TURN • BB → SS → BS → SB" }, new[] { "BUY", "BUY MNQ + BUY MGC" }, new[] { "SELL", "SELL MNQ + SELL MGC" }, new[] { "BS", "BUY MNQ + SELL MGC" }, new[] { "SB", "SELL MNQ + BUY MGC" },
            new[] { "FOLLOW5", "FOLLOW THE LAST 5 MIN (BOTH AGREE)" }, new[] { "FADE5", "FADE THE LAST 5 MIN (BOTH AGREE)" }, new[] { "FOLLOW5EACH", "FOLLOW THE LAST 5 MIN • EACH ITS OWN" }, new[] { "FADE5EACH", "FADE THE LAST 5 MIN • EACH ITS OWN" },
            new[] { "NQLEAD5", "BOTH FOLLOW MNQ'S LAST 5 MIN (NQ LEADS)" },
            new[] { "INDICATOR", "📡 THE ENTRY INDICATOR (learned from the winners)" },
        };
        public Func<Tuple<int, int>> IndSides;   // INDICATOR: the indicator's sides for this moment ((0, 0) = WAIT)
        public static string Arrows(int dirM, int dirG) { return (dirM > 0 ? "▲" : dirM < 0 ? "▼" : "·") + (dirG > 0 ? "▲" : dirG < 0 ? "▼" : "·"); }
        public static bool Confirms(string mode) { return mode == "FOLLOW5" || mode == "FADE5" || mode == "FOLLOW5EACH" || mode == "FADE5EACH" || mode == "NQLEAD5"; }   // the sides come from the last 5 minutes
        public static string DirectionName(string code) { var d = Directions.FirstOrDefault(x => x[0] == code); return d == null ? code : d[1]; }
        public static string SidesName(int dirM, int dirG, bool mnq = true, bool mgc = true)
        {
            var l = new List<string>(); if (mnq && dirM != 0) l.Add((dirM > 0 ? "BUY" : "SELL") + " MNQ"); if (mgc && dirG != 0) l.Add((dirG > 0 ? "BUY" : "SELL") + " MGC"); return string.Join(" + ", l);
        }
        // 0 = wait (FOLLOW5 / FADE5 need both instruments' last 5 minutes to agree)
        public int PickDir(string mode, double move5Mnq, double move5Mgc) { var d = PickDirs(mode, move5Mnq, move5Mgc); return d.Item1 == d.Item2 ? d.Item1 : 0; }
        // both sides (MNQ, MGC): ±1 each • (0, 0) = wait
        public Tuple<int, int> PickDirs(string mode, double move5Mnq, double move5Mgc)
        {
            Func<int, int, Tuple<int, int>> T = (a, b) => Tuple.Create(a, b); int sM = Math.Sign(move5Mnq), sG = Math.Sign(move5Mgc);
            switch (mode)
            {
                case "BUY": return T(1, 1);
                case "SELL": return T(-1, -1);
                case "BS": return T(1, -1);
                case "SB": return T(-1, 1);
                case "RANDOM": { int d = rng.NextDouble() < 0.5 ? 1 : -1; return T(d, d); }
                case "RANDOMHEDGE": { int d = rng.NextDouble() < 0.5 ? 1 : -1; return T(d, -d); }
                case "RANDOM4": { int k = rng.Next(4); return k == 0 ? T(1, 1) : k == 1 ? T(-1, -1) : k == 2 ? T(1, -1) : T(-1, 1); }
                case "CYCLE4": { int k = turn++ % 4; return k == 0 ? T(1, 1) : k == 1 ? T(-1, -1) : k == 2 ? T(1, -1) : T(-1, 1); }
                case "FOLLOW5": case "FADE5": { if (sM == 0 || sM != sG) return T(0, 0); int d = sM * (mode == "FADE5" ? -1 : 1); return T(d, d); }
                case "FOLLOW5EACH": return T(sM, sG);
                case "FADE5EACH": return T(-sM, -sG);
                case "NQLEAD5": return T(sM, sM);
                case "INDICATOR": return IndSides != null ? IndSides() : T(0, 0);
            }
            return T(1, 1);
        }
        // the $ target / stop for this trade: the stop never goes past the account's room (or its day stop), an evaluation's target
        // never past what is left to its target (+ the fees)
        public bool Start(DateTime now, int dir, KeystoneSimAccount acct, double target, double stop, double fees) { return Start(now, dir, dir, acct, target, stop, fees); }
        public bool Start(DateTime now, int dirM, int dirG, KeystoneSimAccount acct, double target, double stop, double fees)
        {
            if ((dirM == 0 && dirG == 0) || target <= fees || stop <= 0) return false;
            InTrade = true; Dir = dirM; DirG = dirG; OpenedAt = now; Peak = 0; Worst = 0; Floor = -stop; Target = target; Stop = stop; Fees = fees; Acct = acct; return true;
        }
        // open = the trade's open P/L in $ (both legs, before fees) → "" (hold) or the exit reason
        public string Check(DateTime now, double open, int minHoldSeconds, double breakevenAt, List<Tuple<double, double>> tiers)
        {
            if (!InTrade) return string.Empty;
            Peak = Math.Max(Peak, open); Worst = Math.Min(Worst, open);
            if (tiers != null) foreach (var t in tiers) if (Peak >= t.Item1 - 1e-9) Floor = Math.Max(Floor, t.Item2);
            if (breakevenAt > 0 && Peak >= breakevenAt - 1e-9) Floor = Math.Max(Floor, Fees);
            if (TrailStop) Floor = Math.Max(Floor, Peak - Stop);
            if (open <= Floor + 1e-9) return Floor <= -Stop + 1e-9 ? "STOP" : TrailStop && Floor > -Stop + 1e-9 && Math.Abs(Floor - (Peak - Stop)) < 1e-6 ? "TRAIL STOP" : Floor <= Fees + 1e-9 ? "BREAKEVEN" : "LOCK";
            if (open >= Target - 1e-9 && (now - OpenedAt).TotalSeconds >= minHoldSeconds) return "TARGET";
            return string.Empty;
        }
        public void Done(DateTime now, int pauseSeconds) { InTrade = false; Acct = null; PauseUntil = now.AddSeconds(Math.Max(0, pauseSeconds)); ReadyAt = PauseUntil; }
        public DateTime ReadyAt = DateTime.MinValue;   // the end of the last pause (the indicator's AUTO fallback starts then)
    }

    // ---- the rotation on 1-minute bars (no replay): MNQ and MGC of one session day on one grid (slot = minutes since 18:00 NY,
    // the bar that opens then) — the PROP SIM's quick what-if over the sessions and the research harness use the same code
    public sealed class KeystoneRotDay
    {
        public const int Slots = 1380;
        public DateTime Day; public float[] MO, MH, ML, MC, GO, GH, GL, GC;
        public KeystoneRotDay() { MO = Nan(); MH = Nan(); ML = Nan(); MC = Nan(); GO = Nan(); GH = Nan(); GL = Nan(); GC = Nan(); }
        static float[] Nan() { var a = new float[Slots]; for (int i = 0; i < Slots; i++) a[i] = float.NaN; return a; }
        public static int Slot(int hhmm) { int m = hhmm / 100 * 60 + hhmm % 100 - 18 * 60; if (m < 0) m += 1440; return Math.Min(Slots - 1, m); }
        public static int SlotOf(DateTime t) { return Slot(t.Hour * 100 + t.Minute); }
        public bool HasM(int k) { return k >= 0 && k < Slots && !float.IsNaN(MC[k]); }
        public bool HasG(int k) { return k >= 0 && k < Slots && !float.IsNaN(GC[k]); }
        public double CloseM(int k) { for (int i = Math.Min(k, Slots - 1); i >= 0; i--) if (!float.IsNaN(MC[i])) return MC[i]; return double.NaN; }
        public double CloseG(int k) { for (int i = Math.Min(k, Slots - 1); i >= 0; i--) if (!float.IsNaN(GC[i])) return GC[i]; return double.NaN; }
        public double OpenM(int k) { for (int i = Math.Max(0, k); i < Slots; i++) if (!float.IsNaN(MO[i])) return MO[i]; return double.NaN; }
        public double OpenG(int k) { for (int i = Math.Max(0, k); i < Slots; i++) if (!float.IsNaN(GO[i])) return GO[i]; return double.NaN; }
        // bars carry their close time (the bar that opens 09:30 is stamped 09:31)
        public static KeystoneRotDay From(DateTime session, List<KeystoneArcBar> mnq, List<KeystoneArcBar> mgc)
        {
            var d = new KeystoneRotDay { Day = session.Date };
            Action<List<KeystoneArcBar>, float[], float[], float[], float[]> fill = (bars, o, h, l, c) =>
            {
                if (bars == null) return;
                foreach (var b in bars) { var op = b.Time.AddMinutes(-1); int m = op.Hour * 60 + op.Minute - 18 * 60; if (m < 0) m += 1440; if (m < 0 || m >= Slots) continue; o[m] = (float)b.Open; h[m] = (float)b.High; l[m] = (float)b.Low; c[m] = (float)b.Close; }
            };
            fill(mnq, d.MO, d.MH, d.ML, d.MC); fill(mgc, d.GO, d.GH, d.GL, d.GC); return d;
        }
    }

    // ---- 💰 FUNDED LAB (trailing drawdown) — pure, no UI (docs/reports/prop-strategy-report.html §3). Money is counted from the account's start
    // (0 = $50,000). INTRADAY trailing (TPT PRO): the floor follows the highest balance INCLUDING open profit, $2,000 below it, and stops at
    // start + LockAt; EOD trailing (other firms): the highest END-OF-DAY balance. Payout-ready = the closed balance at +Payout. 1-minute closes.
    public sealed class KeystoneFundedRules
    {
        public string Name = "TPT PRO 50K • intraday trailing $2,000"; public double Start = 50000, Dd = 2000, LockAt = 0, Payout = 2250; public bool Intraday = true;
        public bool MicroRule = true; public int MinHoldSec = 11; public double HeldShare = 50;   /* 🕐 micro-scalping: more than 50 % of the trades held ≥ 11 s */
        public KeystoneFundedRules Copy() { return (KeystoneFundedRules)MemberwiseClone(); }
        public double FloorOf(double peak) { return Math.Min(peak - Dd, LockAt); }
        public static List<KeystoneFundedRules> Presets()
        {
            return new List<KeystoneFundedRules>
            {
                new KeystoneFundedRules(),
                new KeystoneFundedRules { Name = "EOD trailing $2,000 (other firms' funded)", Intraday = false, MicroRule = false },
                new KeystoneFundedRules { Name = "25K • intraday trailing $1,500", Start = 25000, Dd = 1500, Payout = 1750 },
            };
        }
    }
    public sealed class KeystoneFundedPlan
    {
        public string Name = "", Note = "", Side = "RANDOM"; public int StartHhmm = 930, Qm = 10, Qg = 0, PerDay = 1; public double Tp = 2250, Stop = 0, HalfAt = 0, Trail = 0, DayTarget = 0, DayStop = 0; public bool BeAfterHalf, Preset;
        public KeystoneFundedPlan Copy() { return (KeystoneFundedPlan)MemberwiseClone(); }
        public string Summary()
        {
            Func<double, string> m = v => "$" + v.ToString("N0", CultureInfo.InvariantCulture);
            string inst = Qm > 0 && Qg > 0 ? "MNQ " + Qm + " + MGC " + Qg : Qm > 0 ? "MNQ " + Qm : "MGC " + Qg;
            return inst + " • " + (Side == "LONDON" ? "London move 3:00→9:30, at 9:30" : Side == "ORB30" ? "ORB 30m break (10:00–11:30)" : Side + " at " + (StartHhmm / 100) + ":" + (StartHhmm % 100).ToString("00")) + " • +" + m(Tp) + " after costs • "
                + (Stop <= 0 ? "stop = the trailing floor" : "stop −" + m(Stop)) + (HalfAt > 0 ? " • half off at +" + m(HalfAt) + (BeAfterHalf ? " then breakeven" : "") : "") + (Trail > 0 ? " • trail " + m(Trail) : "")
                + " • " + (PerDay <= 1 ? "1 trade a day" : PerDay + " trades a day") + (DayTarget > 0 ? " • day +" + m(DayTarget) : "") + (DayStop > 0 ? " • day −" + m(DayStop) : "");
        }
    }
    public sealed class KeystoneFundedAccount
    {
        public int Id, Days, Trades, Held, TradesToday, Qual; public string Name = "", Firm = "", State = "TRAILING", Phase = ""; public double Bal, Peak, PeakEod, Floor = -2000, Open, DayPnl; public bool Locked, TradedToday; public DateTime Started = DateTime.MinValue, Ended = DateTime.MinValue;
        public bool Done { get { return State == "PAYOUT" || State == "BLOWN"; } }
        public double Room { get { return Bal + Open - Floor; } }
        public double HeldPct { get { return Trades == 0 ? 100 : 100.0 * Held / Trades; } }
    }
    public sealed class KeystoneFundedTrade { public DateTime Day; public int Account, Dir, EntrySlot, ExitSlot; public double Entry, Pnl, PeakAfter, FloorAfter, BalAfter; public string How = "", Name = ""; public bool Held; }
    // one open position, marked minute by minute (the run and the replay share it)
    public sealed class KeystoneFundedPos
    {
        public int Acct, Dir, Slot0, Qm, Qg; public double EM, EG, Cost, Frac = 1, Banked, Best = double.MinValue, StopNet = double.NegativeInfinity, Tp, HalfAt, Trail; public bool Half, Be;
        public static KeystoneFundedPos Open(KeystoneRotDay d, int k, int dir, KeystoneFundedPlan p, int acct, double stopOverride)
        {
            if (d == null || dir == 0 || (p.Qm > 0 && double.IsNaN(d.OpenM(k))) || (p.Qg > 0 && double.IsNaN(d.OpenG(k)))) return null;
            /* BUILD 11a (item 27c): the labs' fill rule — the entry at the open + 1 tick, the costs once ($1 a contract + the exit tick), the target on a touch,
               the stop / the floor on the minute's worst price */
            var x = new KeystoneFundedPos { Acct = acct, Dir = dir, Slot0 = k, Qm = p.Qm, Qg = p.Qg, EM = p.Qm > 0 ? d.OpenM(k) + dir * KeystoneRotationLab.MnqTick : 0, EG = p.Qg > 0 ? d.OpenG(k) + dir * KeystoneRotationLab.MgcTick : 0, Tp = p.Tp, HalfAt = p.HalfAt, Trail = p.Trail, Be = p.BeAfterHalf };
            x.Cost = p.Qm * KeystoneRotationLab.CostMnq + p.Qg * KeystoneRotationLab.CostMgc; double st = stopOverride > 0 ? stopOverride : p.Stop; if (st > 0) x.StopNet = -st; return x;
        }
        public double Gross(KeystoneRotDay d, int i) { double g = 0; if (Qm > 0) g += (d.CloseM(i) - EM) * Qm * 2; if (Qg > 0) g += (d.CloseG(i) - EG) * Qg * 10; return Dir * g; }
        // the minute's worst / best gross (the low / high against / for the position; a missing leg at its close)
        public double GrossAt(KeystoneRotDay d, int i, bool best)
        {
            double g = 0; bool up = (Dir > 0) == best;
            if (Qm > 0) { double px = d.HasM(i) ? (up ? d.MH[i] : d.ML[i]) : d.CloseM(i); g += (px - EM) * Qm * 2; }
            if (Qg > 0) { double px = d.HasG(i) ? (up ? d.GH[i] : d.GL[i]) : d.CloseG(i); g += (px - EG) * Qg * 10; }
            return Dir * g;
        }
        public double Net(double g) { return Banked + Frac * g - Cost; }
        // one minute: the trailing floor (intraday: the peak includes the open profit), then the exits — null = still open
        public string Mark(KeystoneRotDay d, int i, KeystoneFundedAccount a, KeystoneFundedRules r, bool last, bool micro, out double pnl)
        {
            double g = Gross(d, i), net = Net(g); pnl = net; a.Open = net; double gw = GrossAt(d, i, false), gb = GrossAt(d, i, true); if (double.IsNaN(gw)) gw = g; if (double.IsNaN(gb)) gb = g;
            if (a.Bal + Net(gw) <= a.Floor + 1e-9) { pnl = Math.Min(net, a.Floor - a.Bal); return "FLOOR"; }   /* the floor on the minute's worst (the peak so far) */
            bool can = !micro || i > Slot0;   /* 🕐 never closed in the entry minute (held ≥ 11 s) */
            if (can && Tp > 0 && Net(gb) >= Tp - 1e-9) { pnl = Tp; return "TARGET"; }   /* the target is a limit: a touch fills it */
            if (r.Intraday && a.Bal + net > a.Peak) { a.Peak = a.Bal + net; a.Floor = r.FloorOf(a.Peak); }   /* intraday trailing: the open profit (the close) moves the floor */
            if (can && HalfAt > 0 && !Half && net >= HalfAt) { Banked = 0.5 * g; Frac = 0.5; Half = true; if (Be) StopNet = Math.Max(StopNet, Banked - Cost); }
            if (Trail > 0) { Best = Math.Max(Best, net); if (Best >= Trail) StopNet = Math.Max(StopNet, Best - Trail); }
            if (Net(gw) <= StopNet + 1e-9 && (can || StopNet < 0)) { pnl = StopNet; return Half ? "BREAKEVEN" : "STOP"; }   /* the stop order fills at its level (the exit tick is in the costs) */
            if (last) return "CLOSE";
            return null;
        }
    }
    public sealed class KeystoneFundedRun
    {
        public KeystoneFundedRules Rules; public KeystoneFundedPlan Plan; public string Mode = "ONE"; public List<KeystoneFundedAccount> Accounts = new List<KeystoneFundedAccount>(); public List<KeystoneFundedTrade> Trades = new List<KeystoneFundedTrade>(); public List<string> Log = new List<string>(); public int DaysUsed; public DateTime From, To;
        public int Ready { get { return Accounts.Count(a => a.State == "PAYOUT"); } }
        public int Blown { get { return Accounts.Count(a => a.State == "BLOWN"); } }
        public int Trailing { get { return Accounts.Count(a => !a.Done); } }
    }
    public sealed class KeystoneFundedStart { public DateTime Day; public int Hhmm, Days; public string Result = ""; }
    public sealed class KeystoneFundedRow { public string Group = "", Key = ""; public int N, Ready, Blown, Open; public double AvgDays; public double ReadyPct { get { return N == 0 ? 0 : 100.0 * Ready / N; } } }
    public static class KeystoneFunded
    {
        public static readonly string[][] Modes = { new[] { "ONE", "1️⃣ ONE AT A TIME (the research's pick: the next account starts when the last is payout-ready or blown)" }, new[] { "ALL", "⚡ ALL AT ONCE (one side per firm)" }, new[] { "ROT", "🔄 ROTATION THROUGH THE DAY (one after another from the start time)" } };
        public static readonly string[][] SideRules = { new[] { "RANDOM", "🎲 RANDOM (one coin a day per firm)" }, new[] { "BUY", "▲ BUY" }, new[] { "SELL", "▼ SELL" }, new[] { "LONDON", "🌍 LONDON CONTINUATION (3:00 → 9:30, at 9:30)" }, new[] { "ORB30", "📐 ORB 30m BREAK (10:00–11:30)" }, new[] { "MANUAL", "✋ I DECIDE (replay)" } };
        public static readonly int[] Times = { 200, 830, 930, 1000, 1330 };
        public static List<KeystoneFundedPlan> Presets()
        {
            return new List<KeystoneFundedPlan>
            {
                new KeystoneFundedPlan { Name = "⚡ ONE-SHOT LOCK • 9:30 • MNQ 10 • +$2,250", StartHhmm = 930, Qm = 10, Tp = 2250, Stop = 0, Side = "RANDOM", PerDay = 1, Preset = true, Note = "research (518 start days, 2020–26): 38 % payout-ready, decided on day 1 • 62 % blow — one try, then the next account" },
                new KeystoneFundedPlan { Name = "🛡 STEADY • London continuation • MNQ 4 • +$1,000 / −$500, half off", StartHhmm = 930, Qm = 4, Tp = 1000, Stop = 500, HalfAt = 500, BeAfterHalf = true, Side = "LONDON", PerDay = 1, Preset = true, Note = "research: 36.7 % payout-ready after a median of 9 sessions (smoother)" },
                new KeystoneFundedPlan { Name = "ORB 30 STEADY • MNQ 2 • ±$750, half off", StartHhmm = 1000, Qm = 2, Tp = 750, Stop = 750, HalfAt = 375, BeAfterHalf = true, Side = "ORB30", PerDay = 1, Preset = true, Note = "research: 36.5 % after a median of 19 sessions (slowest, smallest swings)" },
                new KeystoneFundedPlan { Name = "✋ I DECIDE • MNQ 4 • +$1,000 / −$500", StartHhmm = 930, Qm = 4, Tp = 1000, Stop = 500, Side = "MANUAL", PerDay = 3, Preset = true, Note = "replay: you press BUY / SELL; the target / stop are placed for you" },
            };
        }
        // the entry of a plan on a day: (slot, side) — side 0 = no trade today
        public static Tuple<int, int> EntryOf(KeystoneFundedPlan p, KeystoneRotDay d, Random rng, int coin)
        {
            int k = KeystoneRotDay.Slot(p.StartHhmm);
            if (p.Side == "BUY") return Tuple.Create(k, 1); if (p.Side == "SELL") return Tuple.Create(k, -1);
            if (p.Side == "LONDON") { double o = d.OpenM(KeystoneRotDay.Slot(300)), c = d.CloseM(KeystoneRotDay.Slot(929)); return Tuple.Create(KeystoneRotDay.Slot(930), double.IsNaN(o) || double.IsNaN(c) || o == c ? 0 : c > o ? 1 : -1); }
            if (p.Side == "ORB30")
            {
                int r0 = KeystoneRotDay.Slot(930), r1 = KeystoneRotDay.Slot(959), b0 = KeystoneRotDay.Slot(1000), b1 = KeystoneRotDay.Slot(1129); double hi = double.MinValue, lo = double.MaxValue;
                for (int i = r0; i <= r1; i++) if (d.HasM(i)) { hi = Math.Max(hi, d.MH[i]); lo = Math.Min(lo, d.ML[i]); }
                if (hi > lo) for (int i = b0; i <= b1; i++) if (d.HasM(i)) { if (d.MC[i] > hi) return Tuple.Create(i + 1, 1); if (d.MC[i] < lo) return Tuple.Create(i + 1, -1); }
                return Tuple.Create(k, 0);
            }
            return Tuple.Create(k, coin != 0 ? coin : (rng.Next(2) == 0 ? 1 : -1));
        }
        public static int EndSlot(KeystoneRotDay d) { int e = KeystoneRotDay.Slot(1654); for (int i = e; i > 0; i--) if (d.HasM(i)) return i; return e; }
        // the close of a day: EOD trailing moves the floor, then the states (blown / payout-ready / locked)
        public static void EndDay(KeystoneFundedAccount a, KeystoneFundedRules r, DateTime day)
        {
            a.Open = 0; if (!a.TradedToday || a.Done) { a.TradedToday = false; return; }
            a.Days++; a.TradedToday = false; a.DayPnl = 0; a.TradesToday = 0;
            if (!r.Intraday) { a.PeakEod = Math.Max(a.PeakEod, a.Bal); a.Peak = a.PeakEod; a.Floor = r.FloorOf(a.PeakEod); } else a.PeakEod = Math.Max(a.PeakEod, a.Bal);
            a.Locked = a.Floor >= r.LockAt - 1e-9;
            if (a.Bal <= a.Floor + 1e-9) { a.State = "BLOWN"; a.Ended = day; } else if (a.Bal >= r.Payout - 1e-9) { a.State = "PAYOUT"; a.Ended = day; }
        }
        public static KeystoneFundedTrade Close(KeystoneFundedAccount a, KeystoneFundedPos x, int exitSlot, double pnl, string how, KeystoneFundedRules r, DateTime day)
        {
            a.Bal += pnl; a.DayPnl += pnl; a.Open = 0; a.Trades++; a.TradesToday++; a.TradedToday = true; bool held = exitSlot > x.Slot0; if (held) a.Held++;
            if (r.Intraday && a.Bal > a.Peak) { a.Peak = a.Bal; a.Floor = r.FloorOf(a.Peak); }
            if (how == "FLOOR" || a.Bal <= a.Floor + 1e-9) { a.State = "BLOWN"; a.Ended = day; }
            return new KeystoneFundedTrade { Day = day, Account = a.Id, Name = a.Name, Dir = x.Dir, EntrySlot = x.Slot0, ExitSlot = exitSlot, Entry = x.Qm > 0 ? x.EM : x.EG, Pnl = pnl, How = how, Held = held, PeakAfter = a.Peak, FloorAfter = a.Floor, BalAfter = a.Bal };
        }
        // one trade from slot k to its exit (or the close)
        public static KeystoneFundedTrade TradeOne(KeystoneRotDay d, int k, int dir, KeystoneFundedPlan p, KeystoneFundedRules r, KeystoneFundedAccount a, double stopOverride)
        {
            var x = KeystoneFundedPos.Open(d, k, dir, p, a.Id, stopOverride); if (x == null) return null; int end = EndSlot(d); if (k >= end) return null;
            for (int i = k; i <= end; i++)
            {
                if (p.Qm > 0 && !d.HasM(i) && i < end) continue; double pnl; var how = x.Mark(d, i, a, r, i == end, r.MicroRule, out pnl);
                if (how != null) return Close(a, x, i, pnl, how, r, d.Day);
            }
            return null;
        }
        // a whole run over the days: ONE (one account at a time), ALL (every alive account each day, one side per firm), ROT (one after another through the day)
        public static KeystoneFundedRun Run(KeystoneFundedRules r, KeystoneFundedPlan p, IList<KeystoneEvalAccount> pool, int count, IList<KeystoneRotDay> days, string mode, int seed, double rotStop = 0, Func<bool> cancel = null)
        {
            var run = new KeystoneFundedRun { Rules = r, Plan = p, Mode = mode }; var rng = new Random(seed);
            var src = pool != null && pool.Count > 0 ? pool.Where(x => !x.Archived).ToList() : Enumerable.Range(1, Math.Max(1, count)).Select(i => new KeystoneEvalAccount { Firm = "TPT", Nick = "F" + i.ToString("00") }).ToList();
            for (int i = 0; i < src.Count; i++) run.Accounts.Add(new KeystoneFundedAccount { Id = i + 1, Name = string.IsNullOrEmpty(src[i].Nick) ? (src[i].Firm + " " + (i + 1)) : src[i].Nick, Firm = src[i].Firm ?? "", Floor = r.FloorOf(0) });
            if (days == null || days.Count == 0) return run; run.From = days[0].Day; run.To = days[days.Count - 1].Day;
            foreach (var d in days)
            {
                if (cancel != null && cancel()) break; if (run.Accounts.All(a => a.Done)) break; run.DaysUsed++;
                var firmCoin = new Dictionary<string, int>(); Func<string, int> coinOf = f => { int c; if (!firmCoin.TryGetValue(f ?? "", out c)) firmCoin[f ?? ""] = c = rng.Next(2) == 0 ? 1 : -1; return c; };
                IEnumerable<KeystoneFundedAccount> today = mode == "ONE" ? run.Accounts.Where(a => !a.Done).Take(1) : run.Accounts.Where(a => !a.Done);
                int clock = -1;
                foreach (var a in today.ToList())
                {
                    if (a.Started == DateTime.MinValue) a.Started = d.Day;
                    for (int t = 0; t < Math.Max(1, p.PerDay) && !a.Done; t++)
                    {
                        if (p.DayTarget > 0 && a.DayPnl >= p.DayTarget) break; if (p.DayStop > 0 && a.DayPnl <= -p.DayStop) break; if (a.Bal >= r.Payout) break;
                        var e = EntryOf(p, d, rng, p.Side == "RANDOM" ? coinOf(a.Firm) : 0); if (e.Item2 == 0) break;
                        int k = e.Item1; if (mode == "ROT" && clock >= 0) k = Math.Max(k, clock + 1); if (t > 0 && run.Trades.Count > 0 && run.Trades[run.Trades.Count - 1].Account == a.Id) k = Math.Max(k, run.Trades[run.Trades.Count - 1].ExitSlot + 1);
                        int dir = e.Item2; if (t > 0 && p.Side == "RANDOM") dir = rng.Next(2) == 0 ? 1 : -1;
                        var tr = TradeOne(d, k, dir, p, r, a, mode == "ROT" ? rotStop : 0); if (tr == null) break; run.Trades.Add(tr); clock = tr.ExitSlot;
                    }
                }
                foreach (var a in run.Accounts) EndDay(a, r, d.Day);
                run.Log.Add(d.Day.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture) + " • " + run.Ready + " payout-ready • " + run.Blown + " blown • " + run.Trailing + " trailing");
            }
            return run;
        }
        // 'what if we had started on day X at time Y': one account from every start day × time (each until payout-ready / blown / maxDays)
        public static List<KeystoneFundedStart> WhatIf(KeystoneFundedRules r, KeystoneFundedPlan p, IList<KeystoneRotDay> days, int[] times, int maxDays = 60, Func<bool> cancel = null)
        {
            var res = new List<KeystoneFundedStart>(); if (days == null) return res; times = times == null || times.Length == 0 ? new[] { p.StartHhmm } : times;
            bool timed = p.Side != "LONDON" && p.Side != "ORB30";
            for (int s = 0; s < days.Count; s++) foreach (var hh in (timed ? times : new[] { p.StartHhmm }))
            {
                if (cancel != null && cancel()) return res;
                var q = p.Copy(); q.StartHhmm = hh; var run = Run(r, q, null, 1, days.Skip(s).Take(maxDays).ToList(), "ONE", s * 31 + hh);
                var a = run.Accounts[0]; res.Add(new KeystoneFundedStart { Day = days[s].Day, Hhmm = hh, Days = Math.Max(1, a.Days), Result = a.State == "PAYOUT" ? "READY" : a.State == "BLOWN" ? "BLOWN" : "OPEN" });
            }
            return res;
        }
        static int IsoWeek(DateTime d) { return CultureInfo.InvariantCulture.Calendar.GetWeekOfYear(d, CalendarWeekRule.FirstFourDayWeek, DayOfWeek.Monday); }
        public static List<KeystoneFundedRow> Table(IEnumerable<KeystoneFundedStart> starts)
        {
            var res = new List<KeystoneFundedRow>(); var all = (starts ?? Enumerable.Empty<KeystoneFundedStart>()).ToList();
            Action<string, Func<KeystoneFundedStart, string>> add = (grp, key) =>
            {
                foreach (var g in all.GroupBy(key).OrderBy(x => x.Key))
                {
                    var L = g.ToList(); var fin = L.Where(x => x.Result == "READY").ToList();
                    res.Add(new KeystoneFundedRow { Group = grp, Key = g.Key, N = L.Count, Ready = fin.Count, Blown = L.Count(x => x.Result == "BLOWN"), Open = L.Count(x => x.Result == "OPEN"), AvgDays = fin.Count == 0 ? 0 : fin.Average(x => x.Days) });
                }
            };
            add("ALL", x => "ALL"); add("TIME", x => (x.Hhmm / 100).ToString("00") + ":" + (x.Hhmm % 100).ToString("00")); add("WEEKDAY", x => ((int)x.Day.DayOfWeek) + " " + x.Day.DayOfWeek.ToString().ToUpperInvariant());
            add("MONTH", x => x.Day.ToString("yyyy-MM", CultureInfo.InvariantCulture)); add("WEEK", x => x.Day.Year + "-W" + IsoWeek(x.Day).ToString("00"));
            return res;
        }
        // every plan from every start day of the range → ranked by payout-ready %
        public static List<Tuple<KeystoneFundedPlan, KeystoneFundedRow>> Rank(KeystoneFundedRules r, IEnumerable<KeystoneFundedPlan> plans, IList<KeystoneRotDay> days, Func<bool> cancel = null)
        {
            var res = new List<Tuple<KeystoneFundedPlan, KeystoneFundedRow>>();
            foreach (var p in plans.Where(x => x.Side != "MANUAL")) { var w = WhatIf(r, p, days, new[] { p.StartHhmm }, 60, cancel); var row = Table(w).FirstOrDefault(x => x.Group == "ALL") ?? new KeystoneFundedRow(); res.Add(Tuple.Create(p, row)); }
            return res.OrderByDescending(x => x.Item2.ReadyPct).ThenBy(x => x.Item2.AvgDays).ToList();
        }
        // the chance this plan's trade reaches its target before its stop / the floor (a fresh account, the other days of the range)
        public static double Likelihood(KeystoneFundedRules r, KeystoneFundedPlan p, IList<KeystoneRotDay> days, DateTime skip, int dir)
        {
            int n = 0, w = 0; var rng = new Random(7);
            foreach (var d in days ?? new List<KeystoneRotDay>()) { if (d.Day == skip) continue; var a = new KeystoneFundedAccount { Floor = r.FloorOf(0) }; var e = EntryOf(p.Side == "MANUAL" ? Q(p) : p, d, rng, dir); if (e.Item2 == 0) continue; var t = TradeOne(d, e.Item1, dir != 0 ? dir : e.Item2, p, r, a, 0); if (t == null) continue; n++; if (t.How == "TARGET" || t.Pnl > 0) w++; }
            return n == 0 ? double.NaN : 100.0 * w / n;
        }
        static KeystoneFundedPlan Q(KeystoneFundedPlan p) { var q = p.Copy(); q.Side = "BUY"; return q; }
        // user templates (plans.txt of Studio\FundedLab): name|side|hhmm|qm|qg|tp|stop|half|be|trail|perday|dayT|dayS
        public static string SavePlans(IEnumerable<KeystoneFundedPlan> plans)
        {
            Func<double, string> f = v => v.ToString("0.##", CultureInfo.InvariantCulture);
            return string.Join("\n", plans.Where(x => !x.Preset).Select(p => string.Join("|", (p.Name ?? "").Replace("|", " "), p.Side, p.StartHhmm, p.Qm, p.Qg, f(p.Tp), f(p.Stop), f(p.HalfAt), p.BeAfterHalf ? 1 : 0, f(p.Trail), p.PerDay, f(p.DayTarget), f(p.DayStop))));
        }
        public static List<KeystoneFundedPlan> LoadPlans(string text)
        {
            var res = new List<KeystoneFundedPlan>();
            foreach (var l in (text ?? "").Split('\n'))
            {
                var a = l.TrimEnd('\r').Split('|'); if (a.Length < 13 || a[0].Trim() == "") continue; int i; double v;
                Func<int, int> I = k => int.TryParse(a[k], out i) ? i : 0; Func<int, double> D = k => double.TryParse(a[k], NumberStyles.Float, CultureInfo.InvariantCulture, out v) ? v : 0;
                res.Add(new KeystoneFundedPlan { Name = a[0], Side = a[1], StartHhmm = I(2), Qm = I(3), Qg = I(4), Tp = D(5), Stop = D(6), HalfAt = D(7), BeAfterHalf = a[8] == "1", Trail = D(9), PerDay = Math.Max(1, I(10)), DayTarget = D(11), DayStop = D(12) });
            }
            return res;
        }
        public static string Csv(KeystoneFundedRun run)
        {
            var sb = new StringBuilder("day,account,side,entry_slot,exit_slot,pnl,how,held_11s,balance_after,peak_after,floor_after\n");
            foreach (var t in run.Trades) sb.AppendLine(string.Join(",", t.Day.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture), t.Name.Replace(",", " "), t.Dir > 0 ? "BUY" : "SELL", t.EntrySlot, t.ExitSlot, t.Pnl.ToString("0.00", CultureInfo.InvariantCulture), t.How, t.Held ? 1 : 0, t.BalAfter.ToString("0.00", CultureInfo.InvariantCulture), t.PeakAfter.ToString("0.00", CultureInfo.InvariantCulture), t.FloorAfter.ToString("0.00", CultureInfo.InvariantCulture)));
            sb.AppendLine(); sb.AppendLine("account,firm,state,days,trades,held_pct,balance,peak,floor,room");
            foreach (var a in run.Accounts) sb.AppendLine(string.Join(",", a.Name.Replace(",", " "), a.Firm, a.State, a.Days, a.Trades, a.HeldPct.ToString("0", CultureInfo.InvariantCulture), a.Bal.ToString("0.00", CultureInfo.InvariantCulture), a.Peak.ToString("0.00", CultureInfo.InvariantCulture), a.Floor.ToString("0.00", CultureInfo.InvariantCulture), a.Room.ToString("0.00", CultureInfo.InvariantCulture)));
            return sb.ToString();
        }
        // the print-friendly report (the browser's Print → Save as PDF)
        public static string Html(KeystoneFundedRun run, List<KeystoneFundedRow> table, List<Tuple<KeystoneFundedPlan, KeystoneFundedRow>> rank)
        {
            Func<string, string> H = s => System.Net.WebUtility.HtmlEncode(s ?? ""); Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture);
            var sb = new StringBuilder("<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Funded Lab report</title><style>");
            sb.Append(":root{color-scheme:dark}body{margin:0;background:#0f1320;color:#dfe3ee;font:14px/1.5 'Segoe UI',system-ui,sans-serif}.w{max-width:1100px;margin:0 auto;padding:24px 16px}h1{margin:0 0 4px}h2{margin:28px 0 8px;font-size:18px}.s{color:#8a91a8}");
            sb.Append("table{border-collapse:collapse;width:100%;font-size:13px;margin:6px 0}th,td{padding:6px 9px;border-bottom:1px solid #2a3148;text-align:right}th:first-child,td:first-child{text-align:left}th{color:#8a91a8;font-size:11px;text-transform:uppercase}");
            sb.Append(".k{display:inline-block;background:#161b2b;border:1px solid #2a3148;border-radius:8px;padding:8px 14px;margin:0 8px 8px 0}.k b{display:block;font-size:22px}.up{color:#22b8a0}.dn{color:#ef5466}");
            sb.Append("@media print{body{background:#fff;color:#111}.k{background:#fff;border-color:#bbb}th,.s{color:#555}td{border-color:#ccc}h2{break-after:avoid}table{break-inside:auto}}</style></head><body><div class=\"w\">");
            sb.Append("<h1>💰 Funded Lab</h1><p class=\"s\">").Append(H(run.Rules.Name)).Append(" • ").Append(H(run.Plan.Name)).Append("<br>").Append(H(run.Plan.Summary())).Append("<br>")
              .Append(run.From.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)).Append(" → ").Append(run.To.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)).Append(" • mode ").Append(H(run.Mode)).Append(" • saved MNQ + MGC minutes, simulation only</p>");
            sb.Append("<div><span class=\"k\">PAYOUT-READY<b class=\"up\">").Append(run.Ready).Append(" / ").Append(run.Accounts.Count).Append("</b></span><span class=\"k\">BLOWN<b class=\"dn\">").Append(run.Blown).Append("</b></span><span class=\"k\">STILL TRAILING<b>").Append(run.Trailing).Append("</b></span><span class=\"k\">DAYS USED<b>").Append(run.DaysUsed).Append("</b></span></div>");
            sb.Append("<h2>Accounts</h2><table><tr><th>Account</th><th>Firm</th><th>State</th><th>Days</th><th>Trades</th><th>Held ≥ 11 s</th><th>Balance</th><th>Highest peak</th><th>Floor</th><th>Room</th></tr>");
            foreach (var a in run.Accounts) sb.Append("<tr><td>").Append(H(a.Name)).Append("</td><td>").Append(H(a.Firm)).Append("</td><td>").Append(a.State).Append("</td><td>").Append(a.Days).Append("</td><td>").Append(a.Trades).Append("</td><td>").Append(a.HeldPct.ToString("0")).Append("%</td><td>").Append(m(a.Bal)).Append("</td><td>").Append(m(a.Peak)).Append("</td><td>").Append(m(a.Floor)).Append("</td><td>").Append(m(Math.Max(0, a.Bal - a.Floor))).Append("</td></tr>");
            sb.Append("</table>");
            if (table != null && table.Count > 0)
                foreach (var grp in new[] { "ALL", "TIME", "WEEKDAY", "MONTH", "WEEK" })
                {
                    var L = table.Where(x => x.Group == grp).ToList(); if (L.Count == 0) continue;
                    sb.Append("<h2>").Append(grp == "ALL" ? "If we had started on every day of the range" : "By start " + grp.ToLowerInvariant()).Append("</h2><table><tr><th>").Append(grp).Append("</th><th>Starts</th><th>Payout-ready</th><th>Blown</th><th>Open</th><th>Avg days to payout</th></tr>");
                    foreach (var r0 in L) sb.Append("<tr><td>").Append(H(r0.Key)).Append("</td><td>").Append(r0.N).Append("</td><td class=\"up\">").Append(r0.ReadyPct.ToString("0.0")).Append("%</td><td>").Append(r0.Blown).Append("</td><td>").Append(r0.Open).Append("</td><td>").Append(r0.AvgDays.ToString("0.0")).Append("</td></tr>");
                    sb.Append("</table>");
                }
            if (rank != null && rank.Count > 0)
            {
                sb.Append("<h2>Best plan for this range</h2><table><tr><th>Plan</th><th>Starts</th><th>Payout-ready</th><th>Avg days</th></tr>");
                foreach (var x in rank) sb.Append("<tr><td>").Append(H(x.Item1.Name)).Append("</td><td>").Append(x.Item2.N).Append("</td><td class=\"up\">").Append(x.Item2.ReadyPct.ToString("0.0")).Append("%</td><td>").Append(x.Item2.AvgDays.ToString("0.0")).Append("</td></tr>");
                sb.Append("</table>");
            }
            sb.Append("<h2>Trades</h2><table><tr><th>Day</th><th>Account</th><th>Side</th><th>Result</th><th>How</th><th>Balance</th><th>Peak</th><th>Floor</th></tr>");
            foreach (var t in run.Trades.Take(500)) sb.Append("<tr><td>").Append(t.Day.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)).Append("</td><td>").Append(H(t.Name)).Append("</td><td>").Append(t.Dir > 0 ? "BUY" : "SELL").Append("</td><td class=\"").Append(t.Pnl >= 0 ? "up" : "dn").Append("\">").Append(m(t.Pnl)).Append("</td><td>").Append(t.How).Append("</td><td>").Append(m(t.BalAfter)).Append("</td><td>").Append(m(t.PeakAfter)).Append("</td><td>").Append(m(t.FloorAfter)).Append("</td></tr>");
            sb.Append("</table><p class=\"s\">The floor follows the highest balance (intraday: including open profit) $").Append(run.Rules.Dd.ToString("N0", CultureInfo.InvariantCulture)).Append(" below it and stops at the start; payout-ready = the closed balance at +").Append(m(run.Rules.Payout)).Append(". 1-minute closes; past results don't promise future ones.</p></div></body></html>");
            return sb.ToString();
        }
    }
    // ✋ the Funded Lab's REPLAY (pure): minute by minute over the chosen days, AUTO or MANUAL (the buttons flash; nothing until pressed)
    public sealed class KeystoneFundedReplay
    {
        public KeystoneFundedRules Rules; public KeystoneFundedPlan Plan; public List<KeystoneRotDay> Days = new List<KeystoneRotDay>(); public List<KeystoneFundedAccount> Accounts = new List<KeystoneFundedAccount>(); public List<KeystoneFundedTrade> Trades = new List<KeystoneFundedTrade>();
        public int DayIdx, Slot, Cur; public KeystoneFundedPos Pos; public bool Auto = true, Waiting, DayDone; public string Mode = "ONE", Last = ""; public Func<string, bool> ManualFirm = f => false; Random rng = new Random(5); int coin;
        /* ★ MAX IN 5 in the replay (MaxPlan set): PUSH (MNQ Qm, TP = the profit still missing for the max payout, capped, stop, 1 trade) until the balance allows
           the firm's max payout, then QUALIFY (MNQ QualQm, +QualTp / −QualStop, up to QualTries) until QualDays qualifying days → PAYOUT (the max payout is due);
           🧩 Spread: each account its own entry time, one side a day per firm */
        public KeystonePayoutPlan MaxPlan; public List<KeystonePayoutRules> PayRules;
        public double MaxBalOf(KeystoneFundedAccount a) { var r = KeystonePayoutRules.For(a.Firm, PayRules); return r.Pct > 0 && r.Cap > 0 ? r.Cap / (r.Pct / 100.0) : Rules.Payout; }
        public KeystoneFundedPlan PlanFor(KeystoneFundedAccount a)
        {
            if (MaxPlan == null || a == null) return Plan; var q = Plan.Copy(); double mb = MaxBalOf(a);
            if (MaxPlan.Spread)
            {   /* 11a: the account's number WITHIN its firm = its time and its side (one coin per firm per time slot, = ⚡ CALCULATE) */
                var pa = new KeystonePayoutAccount { Id = a.Id, Firm = (a.Firm ?? "").ToUpperInvariant(), FirmNo = Accounts.Where(x => string.Equals(x.Firm, a.Firm, StringComparison.OrdinalIgnoreCase)).ToList().IndexOf(a) + 1 };
                q.StartHhmm = MaxPlan.TimeOf(pa); var d0 = Day; q.Side = d0 == null ? "BUY" : KeystonePayout.CoinOf(MaxPlan, d0.Day, pa, 1) > 0 ? "BUY" : "SELL";
            }
            if (a.Bal < mb - 1e-6) { a.Phase = "PUSH"; q.Qm = Math.Max(1, MaxPlan.Qm); q.Qg = 0; q.Tp = Math.Max(25, Math.Min(MaxPlan.PushCap, mb - a.Bal)); q.Stop = MaxPlan.Stop; q.PerDay = 1; q.HalfAt = 0; }
            else { a.Phase = "QUALIFY"; q.Qm = Math.Max(1, MaxPlan.QualQm); q.Qg = 0; q.Tp = MaxPlan.QualTp; q.Stop = MaxPlan.QualStop; q.PerDay = Math.Max(1, MaxPlan.QualTries); q.HalfAt = 0; }
            return q;
        }
        bool ReadyOf(KeystoneFundedAccount a)
        {
            if (MaxPlan == null) return a.Bal >= Rules.Payout; var r = KeystonePayoutRules.For(a.Firm, PayRules);
            return a.Bal >= MaxBalOf(a) - 1e-6 && a.Qual >= Math.Max(1, r.QualDays);
        }
        public KeystoneRotDay Day { get { return DayIdx >= 0 && DayIdx < Days.Count ? Days[DayIdx] : null; } }
        public KeystoneFundedAccount Current { get { return Cur >= 0 && Cur < Accounts.Count ? Accounts[Cur] : null; } }
        public void Load(int idx)
        {
            DayIdx = idx; Pos = null; Waiting = false; DayDone = false; coin = rng.Next(2) == 0 ? 1 : -1; var d = Day; if (d == null) { DayDone = true; return; }
            var e = KeystoneFunded.EntryOf(Plan.Side == "MANUAL" ? AsBuy() : Plan, d, rng, coin); Slot = Math.Max(0, (Plan.Side == "ORB30" ? KeystoneRotDay.Slot(930) : e.Item1) - 15);
            if (MaxPlan != null && MaxPlan.Spread && MaxPlan.SpreadTimes != null && MaxPlan.SpreadTimes.Length > 0) Slot = Math.Max(0, KeystoneRotDay.Slot(MaxPlan.SpreadTimes.Min()) - 15);
            if (Current == null || Current.Done) NextAccount();
        }
        KeystoneFundedPlan AsBuy() { var q = Plan.Copy(); q.Side = "BUY"; return q; }
        public bool NextAccount() { for (int k = 1; k <= Accounts.Count; k++) { int j = (Math.Max(0, Cur) + (Current == null || Current.Done ? k - 1 : k)) % Accounts.Count; if (!Accounts[j].Done) { Cur = j; return true; } } return false; }
        public bool Enter(int dir)
        {
            var d = Day; var a = Current; if (d == null || a == null || a.Done || Pos != null || dir == 0) return false;
            var pp = PlanFor(a); Pos = KeystoneFundedPos.Open(d, Slot, dir, pp, a.Id, 0); Waiting = false; if (Pos == null) return false; if (a.Started == DateTime.MinValue) a.Started = d.Day; Last = (dir > 0 ? "▲ BUY " : "▼ SELL ") + pp.Qm + " MNQ " + a.Name + (MaxPlan != null ? " • " + a.Phase + " +$" + pp.Tp.ToString("N0", CultureInfo.InvariantCulture) + " / −$" + pp.Stop.ToString("N0", CultureInfo.InvariantCulture) : ""); return true;
        }
        public KeystoneFundedTrade CloseNow(string why)
        {
            var d = Day; var a = Current; if (Pos == null || d == null || a == null) return null; double pnl = Pos.Net(Pos.Gross(d, Slot)); if (Rules.MicroRule && Slot <= Pos.Slot0) return null;   /* 🕐 the 11-second rule */
            var t = KeystoneFunded.Close(a, Pos, Slot, pnl, why, Rules, d.Day); Trades.Add(t); Pos = null; Last = a.Name + " " + why + " " + t.Pnl.ToString("0", CultureInfo.InvariantCulture); return t;
        }
        public bool HalfOff() { var d = Day; if (Pos == null || d == null || Pos.Half) return false; if (Rules.MicroRule && Slot <= Pos.Slot0) return false; double g = Pos.Gross(d, Slot); Pos.Banked = 0.5 * g; Pos.Frac = 0.5; Pos.Half = true; return true; }
        public bool Breakeven() { if (Pos == null) return false; Pos.StopNet = Math.Max(Pos.StopNet, Pos.Half ? Pos.Banked - Pos.Cost : 0); return true; }   /* the stop to breakeven after costs (net 0) */
        // one minute; returns a short note (an exit, a waiting signal) or ""
        public string Step()
        {
            var d = Day; if (d == null || DayDone) return ""; int end = KeystoneFunded.EndSlot(d);
            if (Slot >= end) { if (Pos != null) CloseNow("CLOSE"); EndDay(); return "the session closed"; }
            Slot++; var a = Current; if (a == null) return "";
            if (Pos != null)
            {
                double pnl; var how = Pos.Mark(d, Slot, a, Rules, Slot >= end, Rules.MicroRule, out pnl);
                if (how != null) { var t = KeystoneFunded.Close(a, Pos, Slot, pnl, how, Rules, d.Day); Trades.Add(t); Pos = null; Last = a.Name + " " + how + " " + pnl.ToString("+0;−0", CultureInfo.InvariantCulture); var pa = PlanFor(a); bool dayTgt = MaxPlan != null && a.Phase == "QUALIFY" && how == "TARGET"; if (a.Done || dayTgt || a.TradesToday >= Math.Max(1, pa.PerDay)) { a.TradesToday = Math.Max(a.TradesToday, Math.Max(1, pa.PerDay)); if (Mode == "ROT") NextAccount(); } return Last; }
                return "";
            }
            if (a.Done) { if (!NextAccount()) { DayDone = true; return "every account is done"; } return ""; }
            var pf = PlanFor(a); if (a.TradesToday >= Math.Max(1, pf.PerDay) || ReadyOf(a)) return "";
            var e = KeystoneFunded.EntryOf(pf.Side == "MANUAL" ? AsBuy() : pf, d, rng, coin);
            if (Slot < e.Item1 || e.Item2 == 0) return "";
            bool manual = !Auto || Plan.Side == "MANUAL" || (ManualFirm != null && ManualFirm(a.Firm));
            if (manual) { if (!Waiting) { Waiting = true; return "✋ " + a.Name + " • the plan says " + (e.Item2 > 0 ? "BUY" : "SELL") + " — press it"; } return ""; }
            Enter(e.Item2); return Last;
        }
        public int PlanSide() { var d = Day; if (d == null) return 0; var pf = Current != null ? PlanFor(Current) : Plan; return KeystoneFunded.EntryOf(pf.Side == "MANUAL" ? AsBuy() : pf, d, rng, coin).Item2; }
        public void EndDay()
        {
            var d = Day; if (d == null) return; if (Pos != null) CloseNow("CLOSE");
            foreach (var a in Accounts)
            {
                if (MaxPlan != null && a.TradedToday && !a.Done) { var r = KeystonePayoutRules.For(a.Firm, PayRules); if (a.DayPnl >= r.QualMin - 1e-9) a.Qual++; }
                var rr = Rules; if (MaxPlan != null) { rr = Rules.Copy(); rr.Payout = double.MaxValue; }
                KeystoneFunded.EndDay(a, rr, d.Day);
                if (MaxPlan != null && !a.Done && ReadyOf(a)) { a.State = "PAYOUT"; a.Ended = d.Day; }
            }
            DayDone = true; if (Current != null && Current.Done) NextAccount();
        }
        public bool NextDay() { if (!DayDone) EndDay(); if (DayIdx + 1 >= Days.Count) return false; Load(DayIdx + 1); return true; }
    }

    // ---- 💵 PAYOUT CYCLE + 🔁 PIPELINE + 🚦 STAGE INDICATORS (docs/reports/prop-strategy-report.html §7–10) — pure, no UI. Money from the start (0 = $50,000).
    // Funded (Lucid / Tradeify; every number editable): EOD trailing $2,000 that stops at start + $100. A payout after ≥ QualDays days of ≥ QualMin profit
    // since the last one: Pct % of the profit above the start, capped, at least MinPayout; Split % to the trader; the rest stays as buffer; at most
    // MaxPayouts (then the firm moves the account to live = the end here); a blown account ends. TPT: PARKED (its funded plan comes later).
    // 💰 THE BUDGET LADDER (report §9 + §11): starting money + the evaluation price → the steps (how many evals now, the reserve, when to scale, when to add a firm)
    public sealed class KeystoneBudgetPlan { public int PerWeek; public double FirstSpend, Reserve, ReserveGoal; public bool TooExpensive, TooLittle; public List<string> Steps = new List<string>(); }
    public static class KeystoneBudget
    {
        public static KeystoneBudgetPlan Ladder(double money, double price)
        {
            var b = new KeystoneBudgetPlan(); Func<double, string> m = v => "$" + Math.Round(v).ToString("N0", CultureInfo.InvariantCulture);
            if (money <= 0 || price <= 0) { b.TooLittle = true; b.Steps.Add("Type the money you start with and the price of one evaluation."); return b; }
            b.PerWeek = Math.Max(0, Math.Min(25, (int)Math.Floor(money / (3 * price) + 1e-9))); b.FirstSpend = b.PerWeek * price; b.Reserve = money - b.FirstSpend; b.ReserveGoal = 3 * Math.Max(1, b.PerWeek) * price;
            b.TooExpensive = price > 60; b.TooLittle = b.PerWeek < 3;
            if (b.TooExpensive) b.Steps.Add("⚠ At " + m(price) + " an evaluation the money runs out first in most cases (report §11: a $3,000 start at $120 went broke 44–80 % of the time). Wait for a coupon: at $40–60 it fell to ≈ 10–20 %.");
            if (b.TooLittle) { b.Steps.Add("⚠ " + m(money) + " buys fewer than 3 evaluations a week for 3 weeks — too little to start safely. Save up or find a cheaper price."); return b; }
            b.Steps.Add("STEP 1 • This week: buy " + b.PerWeek + " evaluations (" + m(b.FirstSpend) + "), Lucid + Tradeify (add TPT later, once the money is bigger). Keep " + m(b.Reserve) + " for weeks 2 and 3.");
            b.Steps.Add("STEP 2 • Evaluations: ★ ⚡ ALL AT ONCE 2:00 AM NY (every alive account, one side per firm, MNQ 20, +$1,500 after costs, no stop) — " + KeystoneEvalLab.RealisticNote + ".");
            b.Steps.Add("STEP 3 • Funded: ⚡ FAST CASH (MNQ 6, +$1,500 / −$500, one trade a day, each account its own entry) — take the FIRST eligible payout to keep the game going.");
            b.Steps.Add("STEP 4 • Weeks 2 and 3: buy up to " + b.PerWeek + " more a week from what is left. STOP buying if the money is under 3 evaluations and no payout is pending.");
            b.Steps.Add("STEP 5 • Every payout goes back into evaluations (100 %) until a reserve of " + m(b.ReserveGoal) + " (3 weeks of evaluations) is kept; above it the money is yours.");
            b.Steps.Add("STEP 6 • Scale up when the reserve covers 3 weeks of the bigger size: 30 → 60 → 90 evaluations a week (report §9: about 1 in 4 ladders still fail — never scale with money you need).");
            b.Steps.Add("STEP 7 • Add a firm when one firm has its maximum of funded accounts (5) and accounts wait on the 🪑 bench — 🏢 FIRMS & RULES ▸ ＋ ADD FIRM, check its rules, and the rotation includes it.");
            return b;
        }
    }
    public sealed class KeystonePayoutRules
    {
        public string Firm = "LUCID", Name = "Lucid 50K funded"; public double Dd = 2000, LockAt = 100, QualMin = 150, Pct = 50, Cap = 2000, MinPayout = 250, Split = 90; public int QualDays = 5, MaxPayouts = 5; public bool Parked;
        /* 🔒 TPT (Take Profit Trader PRO): phase 1 = pass the INTRADAY trailing $Dd (open profit counts) with the one-shot lock (TptStart, MNQ TptQm, +LockPayout);
           phase 2 after the lock (the floor stays at the start): withdraw Cap (gross) each time the balance keeps the $Dd buffer above it, Split % to the
           trader, no qualifying days, never more than DailyMax profit in a day (beyond = moved to live), at most MaxPayouts */
        public bool Tpt; public double LockPayout = 2250, DailyMax = 10000; public int TptQm = 10, TptStart = 930;
        /* 🏢 FIRMS & RULES (user's request 2026-11-09: 'I will be funding more and more prop firms'): one row per firm = its evaluation, its funded rules,
           what happens after payouts, how many funded accounts at once (the bench) and whether automation is allowed — every lab simulation reads it.
           EvalTarget / EvalDd / EvalCons / EvalMinDays 0 = the firm's plan of that size (KeystoneFirmRules) • EvalPrice × (1 − Discount %) = what an evaluation costs.
           After = "LIVE" (moved to live after MaxPayouts) or "COOLDOWN" (no live, no payout-count cap: after a payout CooldownDays calendar days
           (≈ ×5/7 trading days) without a payout request; CoolPause = no trades during the cooldown (research: slightly better than trading through it)) */
        public string Color = "", EvalDdType = "EOD", DdType = "EOD", After = "LIVE"; public int Size = 50, EvalMinDays, CooldownDays, MaxFunded = 5; public double EvalTarget, EvalDd, EvalCons, EvalPrice = 120, Discount;
        public int OwnerMaxEval = KeystoneOwners.DefaultMax, OwnerMaxFunded = KeystoneOwners.DefaultMax;   /* 👥 BUILD 11f: max accounts in eval / funded PER OWNER at this firm (default 5 each) */
        /* 🎬 MFF STUDIO (BUILD 11b, items 32 / 32b / 32c — My Funded Futures "Studio"): Kind STUDIO = a STATIC floor (start − Dd, it never moves, eval + funded),
           INSTANT withdrawals of any profit ≥ WithdrawMin (policy Withdraw: WIN = after every winning trade / DAY = at the day's end / CAP = only at the cap),
           Split % to you, no qualifying days, TotalCap = the total GROSS withdrawn, then the account is moved to live (the end here) */
        public string Kind = "", Withdraw = "WIN"; public double WithdrawMin = 250, TotalCap; public int MaxMicros;
        public bool Studio { get { return string.Equals(Kind, "STUDIO", StringComparison.OrdinalIgnoreCase); } }
        public bool StaticDd { get { return Studio || string.Equals(DdType, "STATIC", StringComparison.OrdinalIgnoreCase); } }
        public static string WithdrawName(string w) { string x = (w ?? "").ToUpperInvariant(); return x == "DAY" ? "at the day's end (≥ $250)" : x == "CAP" ? "only at the cap (everything at once)" : "after every winning trade (≥ $250)"; }
        public bool CoolPause = true, AutoEval = true, AutoFunded = true, Template; public bool fromBookPrice;   /* fromBookPrice: you typed this firm's price → the simulations use it (else the lab's FEE box) */
        public bool Cooldown { get { return string.Equals(After, "COOLDOWN", StringComparison.OrdinalIgnoreCase) && CooldownDays > 0; } }
        public int CoolTradingDays { get { return Cooldown ? Math.Max(1, (int)Math.Round(CooldownDays * 5 / 7.0)) : 0; } }
        public double EvalCost { get { return Math.Round(Math.Max(0, EvalPrice) * (1 - Math.Max(0, Math.Min(100, Discount)) / 100.0), 2); } }
        public KeystonePayoutRules Copy() { return (KeystonePayoutRules)MemberwiseClone(); }
        public double FloorOf(double peakEod) { return StaticDd && !Tpt ? -Dd : Math.Min(peakEod - Dd, LockAt); }   /* 🎬 STATIC: the floor never moves */
        // the payout due on a balance: Pct % of the profit, capped (MaxOnly: only the full cap) — 0 under the minimum
        public double Due(double bal, bool maxOnly)
        {
            if (bal <= 0) return 0; double w = Math.Min(Cap, Pct / 100.0 * bal); if (maxOnly && w < Cap - 1e-9) return 0;
            return w >= MinPayout - 1e-9 ? Math.Round(w, 2) : 0;
        }
        public double NetOf(double gross) { return Math.Round(gross * Split / 100.0, 2); }
        public string Line()
        {
            Func<double, string> m = v => "$" + v.ToString("N0", CultureInfo.InvariantCulture);
            if (Parked) return Name + " • PARKED: its funded plan comes later (shown, not traded)";
            if (Studio) return Name + " • 🎬 STATIC floor −" + m(Dd) + " (never moves) • withdraw any profit ≥ " + m(WithdrawMin) + " at once (" + WithdrawName(Withdraw) + ") • " + Split.ToString("0", CultureInfo.InvariantCulture) + " % yours • no qualifying days • total withdrawals capped at " + m(TotalCap) + " (gross), then moved to live";
            if (Cooldown && !Tpt) return Name + " • a payout after " + QualDays + " days of ≥ " + m(QualMin) + " • " + Pct.ToString("0", CultureInfo.InvariantCulture) + " % of the profit, max " + m(Cap) + " → you " + m(NetOf(Cap)) + " • then a " + CooldownDays + "-day cooldown" + (CoolPause ? " (no trades)" : "") + ", no live, no payout cap";
            if (Tpt) return Name + " • 🔒 phase 1: the one-shot lock (" + KeystoneBracket.Hm(TptStart) + ", MNQ " + TptQm + ", +" + m(LockPayout) + ", intraday trailing " + m(Dd) + " incl. open profit) • phase 2: withdraw " + m(Cap) + " each time the " + m(Dd) + " buffer stays → you " + m(NetOf(Cap)) + " (" + Split.ToString("0", CultureInfo.InvariantCulture) + " %) • never > " + m(DailyMax) + " a day • up to " + MaxPayouts;
            return Name + " • a payout after " + QualDays + " days of ≥ " + m(QualMin) + " • " + Pct.ToString("0", CultureInfo.InvariantCulture) + " % of the profit, max " + m(Cap) + " → you " + m(NetOf(Cap)) + " (" + Split.ToString("0", CultureInfo.InvariantCulture) + " %) • up to " + MaxPayouts + " • EOD trailing " + m(Dd) + " locks at +" + m(LockAt);
        }
