                DdType = "STATIC", EvalDdType = "STATIC", Size = size, EvalTarget = target, EvalDd = dd, EvalMinDays = 1, EvalCons = 100, EvalPrice = price, fromBookPrice = price > 0, MaxMicros = micros, After = "LIVE", Color = "#81C784", Template = true
