        }
    }
    // 📒 BUILD 11b: one funded account-day (the run record): the balance before / after, the peak, the floor, the room, qualifying y/n + the count, the lock
    public sealed class KeystonePayoutDay { public DateTime Day; public int Account, Trades, QualCount, Payouts; public string Mode = ""; public double StartBal, EndBal, Pnl, Peak, Floor, Room, Paid; public bool Qual, Locked; }
    public sealed class KeystonePayoutRun
    {
        public List<KeystonePayoutDay> AccountDays = new List<KeystonePayoutDay>();
        public KeystonePayoutPlan Plan; public List<KeystonePayoutRules> Rules = new List<KeystonePayoutRules>(); public List<KeystonePayoutAccount> Accounts = new List<KeystonePayoutAccount>();
        public List<KeystonePayoutEvent> Events = new List<KeystonePayoutEvent>(); public List<KeystoneSimTrade> Trades = new List<KeystoneSimTrade>(); public DateTime From, To; public int DaysUsed;
        public double Net { get { return Accounts.Sum(a => a.Net); } }
        public double Gross { get { return Accounts.Sum(a => a.Gross); } }
        public int Payouts { get { return Accounts.Sum(a => a.Payouts); } }
    }
    // a memo of trades: (day, slot, sides, sizes, target, stop) → (net, how, exit slot) — the clones of one firm reuse it (all their paths are the same)
    public sealed class KeystonePipeCtx { public Dictionary<string, double[]> Memo = new Dictionary<string, double[]>(); public Dictionary<int, KeystonePipeBatch> Batches = new Dictionary<int, KeystonePipeBatch>(); public Func<bool> Cancel; public Action<double> Progress; /* 0..100 for the UI's bar */ }
    public static class KeystonePayout
    {
        // a deterministic coin per (day, firm): every account of a firm takes the same side (no opposite positions inside a firm)
        public static int Coin(DateTime day, string firm, int salt)
        {
            return KeystoneLabFlow.Coin(day, "PAY:" + (firm ?? ""), 0, salt);   /* 🐞 11a: the shared hash coin (string.GetHashCode is not stable, the murmur tail weak) */
        }
        // 11a (item 27a): 🧩 SPREAD = one coin per firm per TIME SLOT (the account's number within its firm) — same-firm accounts at different times are
        // independent, never opposite at the same moment; without SPREAD one coin a day per firm
        public static int CoinOf(KeystonePayoutPlan p, DateTime day, KeystonePayoutAccount a, int salt)
        {
            if (p != null && p.Spread && a != null) return KeystoneLabFlow.SideOf(day, "FUNDED:" + (a.Firm ?? ""), a.SlotNo(p), salt);
            return Coin(day, a == null ? "" : a.Firm, salt);
        }
        // the plan's side today: LONDON = the NQ move 3:00 → 9:29 continued (a flat move: the coin) • BUY / SELL • FIRM / RANDOM = the firm's coin
        public static int SideOf(KeystonePayoutPlan p, KeystoneRotDay d, int coin)
        {
