            if (p.Side == "LONDON") { double o = d.OpenM(KeystoneRotDay.Slot(300)), c = d.CloseM(KeystoneRotDay.Slot(929)); if (!double.IsNaN(o) && !double.IsNaN(c) && o != c) return c > o ? 1 : -1; }
