                double maxBal = r.Cap / (r.Pct / 100.0), need = maxBal - a.Bal; int left = Math.Max(1, p.SprintDays - a.Days); sprintDay = true; a.Mode = "SPRINT"; qg = 0; tries = 1;
                if (need <= 0.01) { qm = 1; pTp = 200; pStop = p.Stop > 0 ? p.Stop : 300; }
