            int k = KeystoneRotDay.Slot(r.Tpt && p.TptStartHhmm > 0 ? p.TptStartHhmm : p.TimeOf(a)), end = KeystoneFunded.EndSlot(d); double day = 0; bool any = false; double fees = Fees(qm, qg), slip = Slip(qm, qg);
