            int qm = Math.Max(1, p.MffQm), tries = Math.Max(1, p.MffTries); int k = KeystoneRotDay.Slot(p.MffHhmm), end = KeystoneFunded.EndSlot(d); while (k < end && !d.HasM(k)) k++;
