        public sealed class Chip { public string Stage = "", Label = "", Detail = ""; public double Pct = double.NaN; public int Side, N; public bool Research; }
        public static Chip Indicator(string stage, string label, IList<KeystoneRotDay> days, int hhmm, string side, int qm, double tp, double stop, double research, KeystoneRotDay today = null)
        {
            var c = new Chip { Stage = stage, Label = label }; int n = 0, hb = 0, hs = 0, hl = 0; int k0 = KeystoneRotDay.Slot(hhmm); double fees = Fees(qm, 0);
            foreach (var d in days ?? new List<KeystoneRotDay>())
            {
                if (d == null) continue; int k = k0, end = KeystoneFunded.EndSlot(d); while (k < end && !d.HasM(k)) k++; if (k >= end - 1) continue;
                int how, xs; double pk, wr; n++;
                if (side == "LONDON") { int dir = SideOf(new KeystonePayoutPlan { Side = "LONDON" }, d, 0); if (dir == 0) { n--; continue; } KeystoneRotationLab.Trade(d, k, end, dir, 0, qm, 0, tp + fees, stop, 0, null, out how, out xs, out pk, out wr, false, 1); if (how == 1) hl++; continue; }
                KeystoneRotationLab.Trade(d, k, end, 1, 0, qm, 0, tp + fees, stop, 0, null, out how, out xs, out pk, out wr, false, 1); if (how == 1) hb++;
                KeystoneRotationLab.Trade(d, k, end, -1, 0, qm, 0, tp + fees, stop, 0, null, out how, out xs, out pk, out wr, false, 1); if (how == 1) hs++;
            }
            c.N = n;
            if (n == 0) { c.Pct = research; c.Research = true; c.Side = side == "LONDON" && today != null ? SideOf(new KeystonePayoutPlan { Side = "LONDON" }, today, 0) : 0; }
            else if (side == "LONDON") { c.Pct = 100.0 * hl / n; c.Side = today != null ? SideOf(new KeystonePayoutPlan { Side = "LONDON" }, today, 0) : 0; }
            else { c.Pct = 100.0 * (hb + hs) / (2.0 * n); c.Side = hb > hs ? 1 : hs > hb ? -1 : 0; }
            c.Detail = "MNQ " + qm + " • +$" + tp.ToString("N0", CultureInfo.InvariantCulture) + " before −$" + stop.ToString("N0", CultureInfo.InvariantCulture) + " • " + (c.Research ? "research value (no saved days here)" : n + " saved days");
            return c;
        }
        // the four stage chips (EVAL • FUNDED QUALIFY • FUNDED PUSH • PAYOUT DAY) — research fallbacks: 2:00 53.6 % / 9:30 50.6 % / 13:30 46.0 % •
        // qualify 2:00 68.1 % / 9:30 62.9 % • push (London side 9:30, +1,500 / −500 MNQ 4) 17.1 %
        public static List<Chip> StageChips(IList<KeystoneRotDay> days, KeystonePayoutAccount acct = null, KeystonePayoutRules rules = null)
        {
            var today = days != null && days.Count > 0 ? days[days.Count - 1] : null; var hist = days != null && days.Count > 1 ? days.Take(days.Count - 1).ToList() : days;
            var res = new List<Chip>
            {
                Indicator("EVAL", "EVAL 2:00", hist, 200, "RANDOM", 20, 1500, 2000, 53.6),
                Indicator("EVAL", "EVAL 9:30", hist, 930, "RANDOM", 20, 1500, 2000, 50.6),
                Indicator("EVAL", "EVAL 13:30", hist, 1330, "RANDOM", 20, 1500, 2000, 46.0),
                Indicator("QUALIFY", "FUNDED QUALIFY 2:00", hist, 200, "RANDOM", 4, 200, 500, 68.1),
                Indicator("QUALIFY", "FUNDED QUALIFY 9:30", hist, 930, "RANDOM", 4, 200, 500, 62.9),
                Indicator("PUSH", "FUNDED PUSH 9:30 (London side)", hist, 930, "LONDON", 4, 1500, 500, 17.1, today),
            };
            var pd = new Chip { Stage = "PAYOUT", Label = "PAYOUT DAY" };
            if (acct != null && rules != null && !rules.Parked) { double due = rules.Due(acct.Bal, false); int left = Math.Max(0, rules.QualDays - acct.Qual); pd.Pct = due > 0 && left == 0 ? 100 : 100.0 * Math.Min(acct.Qual, rules.QualDays) / Math.Max(1, rules.QualDays); pd.Detail = acct.Name + ": " + (left == 0 && due > 0 ? "payout due $" + due.ToString("N0", CultureInfo.InvariantCulture) + " (you $" + rules.NetOf(due).ToString("N0", CultureInfo.InvariantCulture) + ") • room after $" + (acct.Room - due).ToString("N0", CultureInfo.InvariantCulture) : left + " more qualifying day(s) • room $" + acct.Room.ToString("N0", CultureInfo.InvariantCulture) + (acct.Room < 1000 ? " • under $1,000: trade the qualify size" : "")); }
            else { pd.Detail = "the 5th qualifying day: 50 % of the profit (capped) → 90 % to you • then trade the qualify size while the room < $1,000"; }
            res.Add(pd); return res;
        }
    }
    // ---- 🔁 THE PIPELINE: a batch of evaluations (the Eval Lab's ⚡ GOING FORWARD: all at once, one side per firm, ride the room, +target after costs)
    // → the passed Lucid / Tradeify accounts are funded from the next day (the payout cycle) • TPT parked → payouts; per batch and per start day
    public sealed class KeystonePipeSettings
