        public double Fee = 120, EvalTp = 1500, EvalStop = 0; public int EvalQm = 20, EvalQg = 0, EvalStart = 200, Size = 50, MaxEvalDays = 40, MaxFundedDays = 150; public bool Stagger;
        public int[] StaggerTimes = { 200, 830, 930, 1000, 1100 };
