        }
    }
    public sealed class KeystonePipeAccount { public int Id, EvalDays; public string Name = "", Firm = "", Stage = "EVAL"; public DateTime PassedOn = DateTime.MinValue, EndedOn = DateTime.MinValue; public KeystonePayoutAccount F; }
    public sealed class KeystonePipeBatch
