        public List<KeystonePipeAccount> Accounts = new List<KeystonePipeAccount>(); public List<KeystonePayoutEvent> Events = new List<KeystonePayoutEvent>();
        public int Passed { get { return Accounts.Count(a => a.PassedOn != DateTime.MinValue); } }
        public int Blown { get { return Accounts.Count(a => a.Stage == "BLOWN" && a.PassedOn == DateTime.MinValue); } }
        public int Funded { get { return Accounts.Count(a => a.F != null && a.F.Stage != "PARKED"); } }
        public int Parked { get { return Accounts.Count(a => a.Stage == "PARKED"); } }
