    public static class KeystonePipeline
    {
        // one batch from days[i0]: the evaluation (each account: one trade a day at its time, the firm's coin, +target after costs or its room / stop,
        // EOD trailing, best day ≤ the firm's %, the firm's minimum days — TPT's extra day a tiny scratch day) → funded / parked → payouts
        public static KeystonePipeBatch Batch(KeystonePipeSettings s, IList<KeystoneRotDay> days, int i0, KeystonePipeCtx ctx = null)
        {
            KeystonePipeBatch cached; if (ctx != null && ctx.Batches.TryGetValue(i0, out cached)) return cached;
            var b = new KeystonePipeBatch { Start = days[i0].Day, StartIdx = i0, Cost = s.BatchCost }; int id = 0;
            foreach (var m in s.Mix) for (int j = 0; j < m.Item2; j++) { id++; b.Accounts.Add(new KeystonePipeAccount { Id = id, Firm = m.Item1.ToUpperInvariant(), Name = Nice(m.Item1) + " " + (j + 1) }); }
