            var tgt = new double[n]; var dd = new double[n]; var cons = new double[n]; var minD = new int[n];
            for (int a = 0; a < n; a++) { string why; KeystoneEvalLab.FirmRule(FirmCode(b.Accounts[a].Firm), s.Size, out tgt[a], out dd[a], out cons[a], out minD[a], out why); }
            int last = i0, used = 0; double fees = KeystonePayout.Fees(s.EvalQm, s.EvalQg), slip = KeystonePayout.Slip(s.EvalQm, s.EvalQg);
            for (int di = i0; di < days.Count && used < s.MaxEvalDays; di++)
