                    int k = KeystoneRotDay.Slot(s.Stagger ? s.StaggerTimes[(x.Id - 1) % s.StaggerTimes.Length] : s.EvalStart); while (k < end && !((s.EvalQm == 0 || d.HasM(k)) && (s.EvalQg == 0 || d.HasG(k)))) k++; if (k >= end - 1) continue;
                    double left = tgt[a] - bal[a], want = Math.Min(s.EvalTp, Math.Max(1, left)), maxStop = room - fees - slip - 1, stop = s.EvalStop <= 0 ? maxStop : Math.Min(s.EvalStop, maxStop);
