            b.EndIdx = endIdx; b.End = days[Math.Min(days.Count - 1, endIdx)].Day; if (ctx != null) ctx.Batches[i0] = b; return b;
        }
        static double[] Trade(KeystonePipeCtx ctx, KeystoneRotDay d, int k, int end, int dir, int qm, int qg, double target, double stop)
        {
            string key = null;
            if (ctx != null) { key = "E" + d.Day.Ticks + "|" + k + "|" + dir + "|" + qm + "|" + qg + "|" + Math.Round(target, 2) + "|" + Math.Round(stop, 2); double[] hit; if (ctx.Memo.TryGetValue(key, out hit)) return hit; }
            int how, xs; double pk, wr; double v = KeystoneRotationLab.Trade(d, k, end, qm > 0 ? dir : 0, qg > 0 ? dir : 0, qm, qg, target, stop, 0, null, out how, out xs, out pk, out wr, false, 1);
            var res = new double[] { v, how, xs }; if (key != null) ctx.Memo[key] = res; return res;
        }
        static int IndexAfter(IList<KeystoneRotDay> days, DateTime day) { for (int i = 0; i < days.Count; i++) if (days[i] != null && days[i].Day > day) return i; return days.Count; }
        public static string Nice(string firm) { string f = (firm ?? "").ToUpperInvariant(); return f == "LUCID" ? "Lucid" : f == "TRADEIFY" ? "Tradeify" : f == "TPT" ? "TPT" : f.StartsWith("MFF0") && f.Length == 6 ? "MFF " + f.Substring(3) : f; }
        static string FirmCode(string firm) { return (firm ?? "").ToUpperInvariant(); }
        // a batch started on every weekday of [from, to] (each runs on the days after it)
        public static List<KeystonePipeBatch> Starts(KeystonePipeSettings s, IList<KeystoneRotDay> days, DateTime from, DateTime to, KeystonePipeCtx ctx = null)
        {
            var res = new List<KeystonePipeBatch>(); ctx = ctx ?? new KeystonePipeCtx();
            for (int i = 0; i < days.Count; i++)
            {
                if (ctx.Cancel != null && ctx.Cancel()) break; if (ctx.Progress != null && i % 5 == 0) ctx.Progress(100.0 * i / Math.Max(1, days.Count)); var d = days[i]; if (d == null || d.Day < from.Date || d.Day > to.Date) continue;
                if (d.Day.DayOfWeek == DayOfWeek.Saturday || d.Day.DayOfWeek == DayOfWeek.Sunday) continue; res.Add(Batch(s, days, i, ctx));
            }
            return res;
        }
        // the table: period (ALL • each year • LAST YEAR • LAST 3 MONTHS — from the last day) × start weekday (0 = all, 1–5 MON–FRI)
        public static List<KeystonePipeRow> Table(IList<KeystonePipeBatch> batches, DateTime lastDay)
        {
            var res = new List<KeystonePipeRow>(); var all = (batches ?? new List<KeystonePipeBatch>()).ToList(); if (all.Count == 0) return res;
            var periods = new List<Tuple<string, Func<KeystonePipeBatch, bool>>> { Tuple.Create("ALL", (Func<KeystonePipeBatch, bool>)(x => true)) };
            foreach (var y in all.Select(x => x.Start.Year).Distinct().OrderBy(x => x)) { int yy = y; periods.Add(Tuple.Create(y.ToString(CultureInfo.InvariantCulture), (Func<KeystonePipeBatch, bool>)(x => x.Start.Year == yy))); }
            periods.Add(Tuple.Create("LAST YEAR", (Func<KeystonePipeBatch, bool>)(x => x.Start > lastDay.AddYears(-1)))); periods.Add(Tuple.Create("LAST 3 MONTHS", (Func<KeystonePipeBatch, bool>)(x => x.Start > lastDay.AddMonths(-3))));
            foreach (var p in periods)
                for (int wd = 0; wd <= 5; wd++)
                {
                    var L = all.Where(p.Item2).Where(x => wd == 0 || (int)x.Start.DayOfWeek == wd).ToList(); if (L.Count == 0) continue;
                    res.Add(new KeystonePipeRow { Group = p.Item1, Key = wd == 0 ? "ALL" : ((DayOfWeek)wd).ToString().Substring(0, 3).ToUpperInvariant(), N = L.Count, Passed = L.Average(x => x.Passed), Funded = L.Average(x => x.Funded), Payouts = L.Average(x => x.Payouts), Net = L.Average(x => x.Net), Profit = L.Average(x => x.Net - x.Cost), Paid = L.Count(x => x.Net >= x.Cost - 0.01), Zero = L.Count(x => x.Net <= 0.01) });
                }
            return res;
        }
        // 🔁 THE BUSINESS LOOP: one batch; the next only when the current batch has paid back its own cost (or it is finished without that = a rebuy)
        public static KeystoneLoopResult Loop(KeystonePipeSettings s, IList<KeystoneRotDay> days, DateTime from, KeystonePipeCtx ctx = null)
        {
            var res = new KeystoneLoopResult(); ctx = ctx ?? new KeystonePipeCtx(); int i0 = -1;
            for (int i = 0; i < days.Count; i++) if (days[i] != null && days[i].Day >= from.Date && days[i].Day.DayOfWeek != DayOfWeek.Saturday && days[i].Day.DayOfWeek != DayOfWeek.Sunday) { i0 = i; break; }
            if (i0 < 0) return res; res.From = days[i0].Day; res.To = days[days.Count - 1].Day;
            var byDay = new Dictionary<DateTime, List<Tuple<int, double>>>(); var bPaid = new List<double>(); var bEnd = new List<int>(); int cur = -1, lastLaunch = -1;
            Action<int> launch = t =>
            {
                var b = Batch(s, days, t, ctx); res.Launched.Add(b); res.Batches++; res.Spent += b.Cost; bPaid.Add(0); bEnd.Add(b.EndIdx); cur = res.Batches - 1; lastLaunch = t;
                foreach (var e in b.Events) { List<Tuple<int, double>> L; if (!byDay.TryGetValue(e.Day, out L)) byDay[e.Day] = L = new List<Tuple<int, double>>(); L.Add(Tuple.Create(cur, e.Net)); }
            };
            launch(i0);
            for (int t = i0; t < days.Count; t++)
            {
                if (ctx.Cancel != null && ctx.Cancel()) break; if (ctx.Progress != null && t % 5 == 0) ctx.Progress(100.0 * (t - i0) / Math.Max(1, days.Count - i0)); var d = days[t]; if (d == null) continue;
                List<Tuple<int, double>> ev; if (byDay.TryGetValue(d.Day, out ev)) foreach (var x in ev) { res.Paid += x.Item2; bPaid[x.Item1] += x.Item2; }
                res.Worst = Math.Min(res.Worst, res.Paid - res.Spent); if (res.FirstEven == DateTime.MinValue && res.Paid >= res.Spent - 0.01) res.FirstEven = d.Day;
                if (t > lastLaunch && t + 1 < days.Count && (bPaid[cur] >= s.BatchCost - 0.01 || t >= bEnd[cur])) { if (bPaid[cur] < s.BatchCost - 0.01) res.Rebuys++; launch(t + 1); }
                res.Timeline.Add(Tuple.Create(d.Day, res.Spent, res.Paid, res.Batches));
            }
            return res;
        }
