        // the print-friendly HTML report (the browser's Print → Save as PDF)
        public static string Html(KeystonePipeSettings s, KeystonePipeBatch one, List<KeystonePipeBatch> batches, List<KeystonePipeRow> table, KeystoneLoopResult loop)
        {
            Func<string, string> H = x => System.Net.WebUtility.HtmlEncode(x ?? ""); Func<double, string> m = v => (v < 0 ? "−$" : "$") + Math.Abs(Math.Round(v)).ToString("N0", CultureInfo.InvariantCulture); var ic = CultureInfo.InvariantCulture;
            var sb = new StringBuilder("<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Eval to payouts pipeline</title><style>");
            sb.Append(":root{color-scheme:dark}body{margin:0;background:#0f1320;color:#dfe3ee;font:14px/1.5 'Segoe UI',system-ui,sans-serif}.w{max-width:1120px;margin:0 auto;padding:24px 16px}h1{margin:0 0 4px}h2{margin:28px 0 8px;font-size:18px}.s{color:#8a91a8}");
            sb.Append("table{border-collapse:collapse;width:100%;font-size:13px;margin:6px 0}th,td{padding:6px 9px;border-bottom:1px solid #2a3148;text-align:right}th:first-child,td:first-child{text-align:left}th{color:#8a91a8;font-size:11px;text-transform:uppercase}");
            sb.Append(".k{display:inline-block;background:#161b2b;border:1px solid #2a3148;border-radius:8px;padding:8px 14px;margin:0 8px 8px 0}.k b{display:block;font-size:22px}.up{color:#22b8a0}.dn{color:#ef5466}");
            sb.Append("@media print{body{background:#fff;color:#111}.k{background:#fff;border-color:#bbb}th,.s{color:#555}td{border-color:#ccc}h2{break-after:avoid}}</style></head><body><div class=\"w\">");
            sb.Append("<h1>🔁 Eval → funded → payouts</h1><p class=\"s\">").Append(H(s.Summary())).Append("<br>").Append(H(s.Funded.Summary())).Append("<br>");
            foreach (var r in s.Rules) sb.Append(H(r.Line())).Append("<br>"); sb.Append("Simulation on the saved MNQ + MGC minutes • the firms' fine print must be checked</p>");
            if (one != null)
            {
                sb.Append("<h2>One batch from ").Append(one.Start.ToString("ddd yyyy-MM-dd", ic)).Append("</h2><div><span class=\"k\">PASSED<b class=\"up\">").Append(one.Passed).Append(" / ").Append(one.Accounts.Count).Append("</b></span><span class=\"k\">FUNDED (Lucid + Tradeify)<b>").Append(one.Funded).Append("</b></span><span class=\"k\">PAYOUTS<b class=\"up\">").Append(one.Payouts).Append("</b></span><span class=\"k\">TO YOU<b class=\"up\">").Append(m(one.Net)).Append("</b></span><span class=\"k\">NET OF THE ").Append(m(one.Cost)).Append(" SPENT<b class=\"").Append(one.Net >= one.Cost ? "up" : "dn").Append("\">").Append(m(one.Net - one.Cost)).Append("</b></span></div>");
                sb.Append("<table><tr><th>Account</th><th>Firm</th><th>Stage</th><th>Eval days</th><th>Passed on</th><th>Payouts</th><th>To you</th><th>Room</th></tr>");
                foreach (var a in one.Accounts) sb.Append("<tr><td>").Append(H(a.Name)).Append("</td><td>").Append(H(a.Firm)).Append("</td><td>").Append(a.Stage).Append("</td><td>").Append(a.EvalDays).Append("</td><td>").Append(a.PassedOn == DateTime.MinValue ? "" : a.PassedOn.ToString("yyyy-MM-dd", ic)).Append("</td><td>").Append(a.F != null ? a.F.Payouts : 0).Append("</td><td>").Append(m(a.F != null ? a.F.Net : 0)).Append("</td><td>").Append(a.F != null && a.F.Active ? m(a.F.Room) : "").Append("</td></tr>");
                sb.Append("</table>");
            }
            if (table != null && table.Count > 0)
            {
                sb.Append("<h2>A batch started on every weekday</h2><table><tr><th>Period</th><th>Start day</th><th>Batches</th><th>Passed / 30</th><th>Funded</th><th>Payouts</th><th>To you</th><th>Net of the cost</th><th>Paid back</th><th>Nothing paid</th></tr>");
                foreach (var r in table) sb.Append("<tr><td>").Append(H(r.Group)).Append("</td><td>").Append(r.Key).Append("</td><td>").Append(r.N).Append("</td><td>").Append(r.Passed.ToString("0.0", ic)).Append("</td><td>").Append(r.Funded.ToString("0.0", ic)).Append("</td><td>").Append(r.Payouts.ToString("0.0", ic)).Append("</td><td class=\"up\">").Append(m(r.Net)).Append("</td><td class=\"").Append(r.Profit >= 0 ? "up" : "dn").Append("\">").Append(m(r.Profit)).Append("</td><td>").Append((100.0 * r.Paid / r.N).ToString("0", ic)).Append("%</td><td>").Append((100.0 * r.Zero / r.N).ToString("0", ic)).Append("%</td></tr>");
                sb.Append("</table>");
            }
            if (loop != null && loop.Batches > 0)
            {
                sb.Append("<h2>🔁 The business loop from ").Append(loop.From.ToString("yyyy-MM-dd", ic)).Append("</h2><p class=\"s\">The next batch only when the current one has paid back its cost (a batch that ends without it = a rebuy).</p><div><span class=\"k\">BATCHES<b>").Append(loop.Batches).Append("</b></span><span class=\"k\">REBUYS<b>").Append(loop.Rebuys).Append("</b></span><span class=\"k\">SPENT<b>").Append(m(loop.Spent)).Append("</b></span><span class=\"k\">PAID TO YOU<b class=\"up\">").Append(m(loop.Paid)).Append("</b></span><span class=\"k\">NET<b class=\"").Append(loop.Net >= 0 ? "up" : "dn").Append("\">").Append(m(loop.Net)).Append("</b></span><span class=\"k\">WORST POINT<b class=\"dn\">").Append(m(loop.Worst)).Append("</b></span><span class=\"k\">FIRST BREAK-EVEN<b>").Append(loop.FirstEven == DateTime.MinValue ? "—" : loop.FirstEven.ToString("yyyy-MM-dd", ic)).Append("</b></span></div>");
                if (loop.Timeline.Count > 1)
                {
                    double lo = loop.Timeline.Min(x => Math.Min(-x.Item2, x.Item3 - x.Item2)), hi = loop.Timeline.Max(x => Math.Max(x.Item3, x.Item3 - x.Item2)); if (hi <= lo) hi = lo + 1; int n = loop.Timeline.Count;
                    Func<int, double> X = i => 40 + 1040.0 * i / Math.Max(1, n - 1); Func<double, double> Y = v => 10 + 220 * (1 - (v - lo) / (hi - lo));
                    Func<Func<Tuple<DateTime, double, double, int>, double>, string> pts = f => string.Join(" ", loop.Timeline.Select((x, i) => X(i).ToString("0.#", ic) + "," + Y(f(x)).ToString("0.#", ic)));
                    sb.Append("<svg viewBox=\"0 0 1100 250\" style=\"width:100%;height:auto;background:#161b2b;border-radius:8px\"><line x1=\"40\" x2=\"1080\" y1=\"").Append(Y(0).ToString("0.#", ic)).Append("\" y2=\"").Append(Y(0).ToString("0.#", ic)).Append("\" stroke=\"#8a91a8\" stroke-dasharray=\"4 4\"/>");
                    sb.Append("<polyline fill=\"none\" stroke=\"#ef5466\" stroke-width=\"2\" points=\"").Append(pts(x => -x.Item2)).Append("\"/><polyline fill=\"none\" stroke=\"#22b8a0\" stroke-width=\"2\" points=\"").Append(pts(x => x.Item3)).Append("\"/><polyline fill=\"none\" stroke=\"#f2b33d\" stroke-width=\"2.5\" points=\"").Append(pts(x => x.Item3 - x.Item2)).Append("\"/></svg><p class=\"s\">red = money spent (negative) • green = paid to you • gold = net</p>");
                }
            }
            if (batches != null && batches.Count > 0)
            {
                sb.Append("<h2>Every batch</h2><table><tr><th>Start</th><th>Passed</th><th>Lucid / Tradeify / TPT</th><th>Funded</th><th>Payouts</th><th>To you</th><th>Net of the cost</th><th>Ends</th></tr>");
                foreach (var b in batches.Take(600)) sb.Append("<tr><td>").Append(b.Start.ToString("ddd yyyy-MM-dd", ic)).Append("</td><td>").Append(b.Passed).Append("</td><td>").Append(b.PassedOf("LUCID")).Append(" / ").Append(b.PassedOf("TRADEIFY")).Append(" / ").Append(b.PassedOf("TPT")).Append("</td><td>").Append(b.Funded).Append("</td><td>").Append(b.Payouts).Append("</td><td class=\"up\">").Append(m(b.Net)).Append("</td><td class=\"").Append(b.Net >= b.Cost ? "up" : "dn").Append("\">").Append(m(b.Net - b.Cost)).Append("</td><td>").Append(b.End.ToString("yyyy-MM-dd", ic)).Append("</td></tr>");
                sb.Append("</table>");
            }
            sb.Append("<p class=\"s\">1-minute closes; the eval and the funded trades go through the same engine as the Eval Lab. Assumptions: funded EOD trailing $2,000 locking at +$100, payouts per the firm rules above, no activation / monthly fees, no daily loss limits. Past results don't promise future ones.</p></div></body></html>");
            return sb.ToString();
        }
    }
    public static class KeystoneRotationLab
    {
        public const double MnqPv = 2, MgcPv = 10, MnqTick = 0.25, MgcTick = 0.1;
        /* 🐞 BUILD 2026-11-11a (item 27b): the costs counted ONCE = $1 commission per contract round trip + 1 tick each side (the entry tick is in the fill
           price, the exit tick is here) — the old $1.74 (commission + a tick) plus the entry and the stop-exit ticks counted the slippage twice */
        public const double CommRt = 1.0;
        public static double CostMnq { get { return CommRt + MnqTick * MnqPv; } }
        public static double CostMgc { get { return CommRt + MgcTick * MgcPv; } }
        // the sessions of the what-if (NY time; a day = 18:00 → 17:00)
        public static readonly string[] SessionNames = { "ASIA 20:00–00:00", "LONDON 03:00–07:00", "NY PRE 08:00–09:30", "NY OPEN 09:30–11:00", "NY MID 11:00–13:30", "NY CLOSE 13:30–15:55", "NY DAY 09:30–15:55", "ALL DAY 18:00–16:55" };
        public static readonly int[][] SessionHours = { new[] { 2000, 2359 }, new[] { 300, 659 }, new[] { 800, 929 }, new[] { 930, 1059 }, new[] { 1100, 1329 }, new[] { 1330, 1555 }, new[] { 930, 1555 }, new[] { 1800, 1655 } };

        // the $ target / stop of the next rotation trade for the account in turn (the same rules as the replay): its day never ends
        // above its day target (FULL RECOVERY aims at exactly that), an evaluation never aims past what is left, the stop never past
        // the account's day stop or its room to the floor
        public static void Bracket(KeystoneSimSettings s, KeystoneSimAccount a, double fees, double room, out double target, out double stop, KeystonePropSim sim0 = null)
        {
            target = s.Cushioned(a) ? s.FundCushionTarget : a.Funded ? s.FundRotTarget : s.RotTarget; stop = a.Funded ? s.FundRotStop : s.RotStop;
            double goal = s.Cushioned(a) ? s.FundCushionTarget : s.AcctDayTarget > 0 ? s.AcctDayTarget : target;
            target += fees;   // the $ target is what the account keeps: +1,500 = +1,500 after the fees (two such days = +3,000)
            if (s.PlanOf(a.Funded) == "RECOVER") target = Math.Max(fees + 1, goal - a.DayPnl + fees);
            else if (a.DayPnl > 0) target = Math.Min(target, Math.Max(fees + 1, goal - a.DayPnl + fees));
            if (!a.Funded) { double left = (sim0 != null ? sim0.RulesOf(a) : s.Rules).Target - (a.Bal + a.DayPnl); if (left > 0) target = Math.Min(target, left + fees); }
            if (s.AcctDayStop > 0) stop = Math.Min(stop, s.AcctDayStop + a.DayPnl);
            stop = Math.Min(stop, room - fees);   /* ride the room = the floor itself (the exit tick is in the fees) */
        }

        // one combined trade from slot k (market at the bar's open + 1 tick): dM / dG sides (0 = that leg not traded), qM / qG
        // contracts. Each minute: the stop first with both legs at their worst (conservative), then the target / breakeven / locks on
        // the minute's close (real prices only). → net $ after costs; how: 1 target • −1 stop • −2 breakeven • −3 lock • 0 time • −9 no data
        public static double Trade(KeystoneRotDay d, int k, int end, int dM, int dG, int qM, int qG, double target, double stop, double breakevenAt, List<Tuple<double, double>> tiers, out int how, out int exitSlot, out double peak, out double worst, bool trail = false, int minHoldMin = 1)
        {
            how = 0; exitSlot = end; peak = 0; worst = 0; if (dM == 0) qM = 0; if (dG == 0) qG = 0;
            if (qM + qG <= 0 || k >= end) { how = -9; return 0; }
            double eM = double.NaN, eG = double.NaN;
            if (qM > 0) { if (!d.HasM(k)) { how = -9; return 0; } eM = d.MO[k] + dM * MnqTick; }
            if (qG > 0) { if (!d.HasG(k)) { how = -9; return 0; } eG = d.GO[k] + dG * MgcTick; }
            double fees = qM * CostMnq + qG * CostMgc, slip = qM * MnqTick * MnqPv + qG * MgcTick * MgcPv, lastM = eM, lastG = eG, floor = -stop;
            for (int i = k; i <= end; i++)
            {
                double w = 0, c = 0;
                if (qM > 0) { if (d.HasM(i)) { lastM = d.MC[i]; w += (dM > 0 ? d.ML[i] - eM : d.MH[i] - eM) * dM * qM * MnqPv; } else w += (lastM - eM) * dM * qM * MnqPv; c += (lastM - eM) * dM * qM * MnqPv; }
                if (qG > 0) { if (d.HasG(i)) { lastG = d.GC[i]; w += (dG > 0 ? d.GL[i] - eG : d.GH[i] - eG) * dG * qG * MgcPv; } else w += (lastG - eG) * dG * qG * MgcPv; c += (lastG - eG) * dG * qG * MgcPv; }
                worst = Math.Min(worst, w);
                if (w <= floor) { exitSlot = i; how = floor <= -stop + 1e-9 ? -1 : floor <= fees + 1e-9 ? -2 : -3; return floor - fees; }   /* the exit tick is in the fees (11a) */
                peak = Math.Max(peak, c);
                double bx = c;   /* 🎯 the take profit is a LIMIT order: one instrument → it fills when the minute's high (buy) / low (sell) reaches it (🐞 it waited for a close above the target while the stop used the wick: a bias against every plan); two legs → their closes */
                if (qM > 0 && qG == 0 && d.HasM(i)) bx = ((dM > 0 ? d.MH[i] : d.ML[i]) - eM) * dM * qM * MnqPv; else if (qG > 0 && qM == 0 && d.HasG(i)) bx = ((dG > 0 ? d.GH[i] : d.GL[i]) - eG) * dG * qG * MgcPv;
                if (i - k >= Math.Max(1, minHoldMin) && Math.Max(c, bx) >= target) { exitSlot = i; how = 1; return target - fees; }   /* MIN TIME IN TRADE: whole minutes after the entry minute */
                if (tiers != null) foreach (var t in tiers) if (peak >= t.Item1 - 1e-9) floor = Math.Max(floor, t.Item2);
                if (breakevenAt > 0 && peak >= breakevenAt - 1e-9) floor = Math.Max(floor, fees);
                if (trail) floor = Math.Max(floor, peak - stop);   // TRAILING STOP: its stop $ below the best close so far
                if (i == end) { exitSlot = i; return c - fees; }
            }
            return -fees;
        }

        // a whole prop run of the rotation in one session window (startHhmm → endHhmm, close all at the end) over the given days,
        // with the settings' accounts, sides, sizes, brackets and each account's day plan — the same engine as the PROP SIM
        // 🩹 SAME-DAY RECOVERY (both engines): after a stop that left room, one more trade from the next minute risking the room left,
        // its target = RecTarget after costs, the side SAME or FLIP → (net $, how, exit slot, worst, peak) or null when there is none
        public static double[] Recovery(KeystoneSimSettings s, KeystoneRotDay d, int afterSlot, int end, int dM, int dG, int qM, int qG, double roomLeft)
        {
            if (s == null || s.RecTarget <= 0 || (s.RecSide != "SAME" && s.RecSide != "FLIP")) return null;
            int k = afterSlot + 1; while (k < end && !((qM == 0 || d.HasM(k)) && (qG == 0 || d.HasG(k)))) k++; if (k >= end - 1) return null;
            double fees = qM * CostMnq + qG * CostMgc, stop = roomLeft - fees; if (stop <= 25) return null;
            int f = s.RecSide == "FLIP" ? -1 : 1, how, xs; double pk, wr;
            double v = Trade(d, k, end, dM * f, dG * f, qM, qG, s.RecTarget + fees, stop, 0, null, out how, out xs, out pk, out wr, false, KeystoneEvalLab.HoldMinutes(s.MinHoldSec));
            if (how == -9) return null; return new double[] { v, how, xs, wr, pk, k };
        }
        // ⚡ ALL AT ONCE (🧪 EVAL LAB; reference: docs/reports/eval-plan-2026.html): every alive account opens at the start slot each day — one trade,
        // +target after costs or its stop / the floor (stop 0 = ride the full room) or the end — then the optional same-day recovery. The prop sim keeps
        // the accounts (batches, firm rules, consistency, passes), exactly as in the rotation.
        public static KeystonePropSim RunAllAtOnce(KeystoneSimSettings settings, IList<KeystoneRotDay> days, int startHhmm, int endHhmm, Func<bool> cancel, Func<KeystoneRotDay, int, Tuple<int, int>> sidesAt = null, Action<KeystonePropSim, DateTime> dayDone = null)
        {
            var s = settings.Copy(); s.Strategy = "ROTATION"; s.StartHhmm = startHhmm; s.EndHhmm = endHhmm; s.MaxTradesPerDay = 0;
            var sim = new KeystonePropSim(s); var tiers = s.Tiers();
            int s0 = KeystoneRotDay.Slot(startHhmm), e0 = KeystoneRotDay.Slot(endHhmm); if (s.Rules.FlatByHhmm > 0) e0 = Math.Min(e0, KeystoneRotDay.Slot(s.Rules.FlatByHhmm) - 1);
            for (int di = 0; di < days.Count; di++)
            {
                if (cancel != null && cancel()) break;
                var d = days[di]; sim.BeginDay(d.Day); var rng = new Random(KeystoneLabFlow.SeedOf(s.Seed, d.Day.Year * 400 + d.Day.DayOfYear));
                int k0 = s0; while (k0 < e0 && !d.HasM(k0) && !d.HasG(k0)) k0++;
                if (k0 < e0 - 1 || s.Stagger)
                {
                    var coins = new Dictionary<string, int>(); int all = rng.Next(2) == 0 ? 1 : -1;
                    var todays0 = sim.Accounts.Where(sim.CanTrade).OrderBy(a => a.Id).ToList();
                    int nSl = s.StaggerTimes != null ? s.StaggerTimes.Length : 0; var plan = KeystoneLabFlow.Plan(todays0.Select(a => a.Id).ToList(), todays0.Select(a => sim.HasFirms ? "F" + a.Firm : "").ToList(), nSl);   /* 🔀 firm by firm (BUILD 10a) */
                    var todays = todays0.OrderBy(a => s.Stagger && nSl > 0 ? plan[a.Id][1] : 0).ThenBy(a => plan[a.Id][0]).ToList();
                    foreach (var a in todays)
                    {
                        if (!sim.CanTrade(a)) continue;
                        int k = k0, slotNo = 0;   /* ⚡ STAGGERED: this account's own entry time (2:00 / 8:30 / 9:30 / 10:00 / 11:00, the firms dealt in turn) */
                        if (s.Stagger && nSl > 0) { slotNo = plan[a.Id][1]; k = KeystoneRotDay.Slot(s.StaggerTimes[slotNo]); while (k < e0 && !d.HasM(k) && !d.HasG(k)) k++; if (k >= e0 - 1) continue; }
                        int qM = a.Funded ? s.FundMnqQty : s.MnqQty, qG = a.Funded ? s.FundMgcQty : s.MgcQty; if (!d.HasM(k)) qM = 0; if (!d.HasG(k)) qG = 0; if (qM + qG <= 0) continue;
                        int side;
                        if (sidesAt != null) { var sd = sidesAt(d, k); side = sd.Item1 != 0 ? sd.Item1 : sd.Item2; }
                        else side = KeystoneLabFlow.PlanSide(s.AllSide, d.Day, KeystoneLabFlow.SideKey(sim.HasFirms, a.Firm, a.Id), a.Id, slotNo, s.Seed);   /* 🎲 BUILD 10b: ONE side source for CALCULATE and the replay (FIRM: no pool → groups of 5 • STAGGERED: one side per firm per time) */
                        if (side == 0) continue; int dM = qM > 0 ? side : 0, dG = qG > 0 ? side : 0;
                        double fees = qM * CostMnq + qG * CostMgc, target, stop; Bracket(s, a, fees, sim.Room(a, 0), out target, out stop, sim);
                        if (stop <= fees || target <= fees) { sim.Lock(a, d.Day, "no room for a trade"); continue; }
                        int how, xs; double peak, worst; double v = Trade(d, k, e0, dM, dG, qM, qG, target, stop, s.BreakevenAt, tiers, out how, out xs, out peak, out worst, s.TrailStop, KeystoneEvalLab.HoldMinutes(s.MinHoldSec));
                        if (how == -9) continue;
                        sim.CheckEquity(a, peak); string st = sim.CheckEquity(a, worst); if (st == "BLOWN") v = Math.Min(v, sim.Floor(a) - (a.Bal + a.DayPnl));
                        string reason = how == 1 ? "TARGET" : how == -1 ? "STOP" : how == -2 ? "BREAKEVEN" : how == -3 ? "LOCK" : "TIME";
                        if (how == -1 && st != "BLOWN")
                        {   /* 🩹 the same-day recovery: risk the room left */
                            var rc = Recovery(s, d, xs, e0, dM, dG, qM, qG, sim.Room(a, v));
                            if (rc != null) { string st2 = sim.CheckEquity(a, v + rc[3]); sim.CheckEquity(a, v + rc[4]); v += rc[0]; if (st2 == "BLOWN") v = Math.Min(v, sim.Floor(a) - (a.Bal + a.DayPnl)); xs = (int)rc[2]; reason = "STOP → 🩹 RECOVERY " + (rc[1] == 1 ? "TARGET" : rc[1] == -1 ? "STOP" : "TIME"); st = st2; }
                        }
                        DateTime t0 = d.Day.AddMinutes(18 * 60 + k - 1440), t1 = d.Day.AddMinutes(18 * 60 + xs + 1 - 1440);
                        sim.AddFill(a, v);
                        sim.EndTrade(a, new KeystoneSimTrade { Entry = t0, Exit = t1, Dir = side, Legs = (qM > 0 ? (dM > 0 ? "BUY " : "SELL ") + qM + " MNQ" : "") + (qM > 0 && qG > 0 ? " + " : "") + (qG > 0 ? (dG > 0 ? "BUY " : "SELL ") + qG + " MGC" : ""), Pnl = v, Reason = reason, Source = "⚡ ALL AT ONCE",
                            EntryPx = qM > 0 ? d.MO[k] + dM * MnqTick : d.GO[k] + dG * MgcTick, ExitPx = qM > 0 && qG > 0 ? double.NaN : (qM > 0 ? d.MO[k] + dM * MnqTick : d.GO[k] + dG * MgcTick) + side * (v + fees) / (qM > 0 ? qM * MnqPv : qG * MgcPv), Tp = target - fees, Sl = stop, FloorAt = sim.Floor(a) });
                        if (st == "BLOWN" && a.Alive) sim.Blow(a, t1, "equity touched the drawdown floor");
                        if (a.Alive) sim.Lock(a, t1, "one trade a day (all at once)");
                    }
                }
                sim.EndDay(); if (dayDone != null) dayDone(sim, d.Day);
            }
            return sim;
        }
        [ThreadStatic] static int altWinSide, altRot;   // 🧪 EVAL LAB: ALTWIN (after a win the next account flips, after a loss it keeps the side) • ALTERNATE MNQ / MGC
        public static KeystonePropSim Run(KeystoneSimSettings settings, IList<KeystoneRotDay> days, int startHhmm, int endHhmm, Func<bool> cancel, Func<KeystoneRotDay, int, Tuple<int, int>> sidesAt = null, Action<KeystonePropSim, DateTime> dayDone = null)   // sidesAt: research only — the sides of a trade at (day, slot) instead of the settings' rule
        {
            if (settings != null && settings.AllAtOnce) return RunAllAtOnce(settings, days, startHhmm, endHhmm, cancel, sidesAt, dayDone);   /* ⚡ ALL AT ONCE */
            var s = settings.Copy(); s.Strategy = "ROTATION"; s.StartHhmm = startHhmm; s.EndHhmm = endHhmm;
            var sim = new KeystonePropSim(s); var tiers = s.Tiers(); var ind = s.Direction == "INDICATOR" ? KeystoneEntryIndicator.FromText(s.Indicator) : null; int pauseMin = ind != null ? 0 : (int)Math.Ceiling(Math.Max(0, s.PauseSeconds) / 60.0);   // the indicator waits for its setups, not a pause
            int s0 = KeystoneRotDay.Slot(startHhmm), e0 = KeystoneRotDay.Slot(endHhmm); if (s.Rules.FlatByHhmm > 0) e0 = Math.Min(e0, KeystoneRotDay.Slot(s.Rules.FlatByHhmm) - 1);
            for (int di = 0; di < days.Count; di++)
            {
                if (cancel != null && cancel()) break;
                var d = days[di]; sim.BeginDay(d.Day); var rot = new KeystoneSimRotation(KeystoneLabFlow.SeedOf(s.Seed, di)); int k = s0, ready = s0; int fbPause = (int)Math.Ceiling(Math.Max(0, s.PauseSeconds) / 60.0);
                if (di == 0) { altWinSide = 1; altRot = 0; }
                if (ind != null) rot.IndSides = () => ind.Signal(d, k);
                while (k < e0 - 1 && sim.Active != null)
                {
                    var a = sim.Active; int qM = a.Funded ? s.FundMnqQty : s.MnqQty, qG = a.Funded ? s.FundMgcQty : s.MgcQty;
                    if (s.AltInstrument) { if (altRot % 2 == 0) qG = 0; else qM = 0; }
                    if (!d.HasM(k)) qM = 0; if (!d.HasG(k)) qG = 0; if (qM + qG <= 0) { k++; continue; }
                    double m5 = k >= 5 ? d.CloseM(k - 1) - d.OpenM(k - 5) : 0, g5 = k >= 5 ? d.CloseG(k - 1) - d.OpenG(k - 5) : 0;
                    var dd = sidesAt != null ? sidesAt(d, k) : s.Direction == "ALTWIN" ? Tuple.Create(altWinSide, altWinSide) : rot.PickDirs(s.Direction, double.IsNaN(m5) ? 0 : m5, double.IsNaN(g5) ? 0 : g5);
                    if (dd.Item1 == 0 && dd.Item2 == 0 && ind != null && s.Auto && s.AutoFallback != "WAIT" && k >= ready) dd = rot.PickDirs(s.AutoFallback, double.IsNaN(m5) ? 0 : m5, double.IsNaN(g5) ? 0 : g5);   // no indicator setup by the end of the pause
                    int dM = qM > 0 ? dd.Item1 : 0, dG = qG > 0 ? dd.Item2 : 0;
                    if (dM == 0 && dG == 0) { k++; continue; } if (dM == 0) qM = 0; if (dG == 0) qG = 0;
                    double fees = qM * CostMnq + qG * CostMgc, target, stop; Bracket(s, a, fees, sim.Room(a, 0), out target, out stop, sim);
                    if (stop <= fees || target <= fees) { if (!sim.RetireIfNoRoom(a, d.Day.AddHours(9.5), fees)) { sim.Lock(a, d.Day, "no room for another trade"); sim.Rotate(); } continue; }
                    int how, xs; double peak, worst; double v = Trade(d, k, e0, dM, dG, qM, qG, target, stop, s.BreakevenAt, tiers, out how, out xs, out peak, out worst, s.TrailStop, KeystoneEvalLab.HoldMinutes(s.MinHoldSec));
                    if (how == -9) { k++; continue; }
                    sim.CheckEquity(a, peak); string st = sim.CheckEquity(a, worst);
                    if (st == "BLOWN") v = Math.Min(v, sim.Floor(a) - (a.Bal + a.DayPnl));
                    string recNote = null;
                    if (how == -1 && st != "BLOWN")
                    {   /* 🩹 SAME-DAY RECOVERY in the rotation: the same account, from the next minute, risking the room left */
                        var rc = Recovery(s, d, xs, e0, dM, dG, qM, qG, sim.Room(a, v));
                        if (rc != null) { string st2 = sim.CheckEquity(a, v + rc[3]); sim.CheckEquity(a, v + rc[4]); v += rc[0]; if (st2 == "BLOWN") v = Math.Min(v, sim.Floor(a) - (a.Bal + a.DayPnl)); xs = (int)rc[2]; recNote = "STOP → 🩹 RECOVERY " + (rc[1] == 1 ? "TARGET" : rc[1] == -1 ? "STOP" : "TIME"); st = st2; how = rc[1] == 1 ? 1 : (int)rc[1]; }
                    }
                    DateTime t0 = d.Day.AddMinutes(18 * 60 + k - 1440), t1 = d.Day.AddMinutes(18 * 60 + xs + 1 - 1440);
                    sim.AddFill(a, v);
                    sim.EndTrade(a, new KeystoneSimTrade { Entry = t0, Exit = t1, Dir = dM != 0 ? dM : dG, Legs = (qM > 0 ? (dM > 0 ? "BUY " : "SELL ") + qM + " MNQ" : "") + (qM > 0 && qG > 0 ? " + " : "") + (qG > 0 ? (dG > 0 ? "BUY " : "SELL ") + qG + " MGC" : ""), Pnl = v, Reason = recNote ?? (how == 1 ? "TARGET" : how == -1 ? "STOP" : how == -2 ? "BREAKEVEN" : how == -3 ? "LOCK" : "SESSION END"), Source = "WHAT-IF", Peak = peak, Worst = worst,
                        EntryPx = qM > 0 ? d.MO[k] + dM * MnqTick : d.GO[k] + dG * MgcTick, ExitPx = qM > 0 && qG > 0 ? double.NaN : (qM > 0 ? d.MO[k] + dM * MnqTick : d.GO[k] + dG * MgcTick) + (dM != 0 ? dM : dG) * (v + fees) / (qM > 0 ? qM * MnqPv : qG * MgcPv), Tp = target - fees, Sl = stop, FloorAt = sim.Floor(a) });
                    if (st == "BLOWN" && a.Alive) sim.Blow(a, t1, "equity touched the drawdown floor");
                    if (s.Direction == "ALTWIN" && v >= 0) altWinSide = -altWinSide; altRot++;
                    k = xs + 1 + pauseMin; ready = xs + 1 + fbPause;
                }
                sim.EndDay(); if (dayDone != null) dayDone(sim, d.Day);   /* 🔄 ROTATION STUDIO: a per-day snapshot for its replay (read only) */
            }
            return sim;
        }
        // the account-days that reached their day target (≈: 90% of it, fees in)
        public static int DaysAtTarget(KeystonePropSim sim)
        {
            var s = sim.S; int n = 0;
            foreach (var g in sim.Trades.GroupBy(t => t.Day.ToString("yyyyMMdd") + "|" + t.Account))
            {
                var first = g.First(); double goal = s.AcctDayTarget > 0 ? s.AcctDayTarget : first.Phase == "FUNDED" ? s.FundRotTarget : s.RotTarget;
                if (goal > 0 && g.Sum(t => t.Pnl) >= goal * 0.9) n++;
            }
            return n;
        }
        // the saved minute bars of the given sessions (MNQ + MGC, both needed) as rotation days — one read per month file
        public static List<KeystoneRotDay> LoadDays(string folder, IEnumerable<DateTime> sessions)
        {
            var want = sessions.Select(d => d.Date).Distinct().OrderBy(d => d).ToList(); var list = new List<KeystoneRotDay>(); if (want.Count == 0) return list;
            Func<string, Dictionary<DateTime, List<KeystoneArcBar>>> load = sym => KeystoneStudioStore.Load(folder, sym, want[0], want[want.Count - 1]).GroupBy(b => KeystoneStudioStore.SessionOf(b.Time)).ToDictionary(g => g.Key, g => g.ToList());
            var m = load("MNQ"); var g0 = load("MGC");
            foreach (var d in want) { List<KeystoneArcBar> a, b; if (m.TryGetValue(d, out a) && g0.TryGetValue(d, out b) && a.Count >= 60 && b.Count >= 60) list.Add(KeystoneRotDay.From(d, a, b)); }
            return list;
        }
        // ⚖ COMPARE SESSIONS: the same days and settings, the rotation in each session window (your own hours first when they are
        // not one of the windows). Minute bars, the lab's engine, so every row is measured the same way.
        public static List<KeystoneSessionWhatIf> Compare(KeystoneSimSettings settings, IList<KeystoneRotDay> days, Func<bool> cancel, Action<int, int> progress)
        {
            var windows = SessionNames.Select((n, i) => Tuple.Create(n, SessionHours[i][0], SessionHours[i][1])).ToList();
            if (!windows.Any(x => x.Item2 == settings.StartHhmm && x.Item3 == settings.EndHhmm)) windows.Insert(0, Tuple.Create("YOUR HOURS " + KeystoneBracket.Hm(settings.StartHhmm) + "–" + KeystoneBracket.Hm(settings.EndHhmm), settings.StartHhmm, settings.EndHhmm));
            var list = new List<KeystoneSessionWhatIf>();
            bool fundOwn = settings.FundMnqQty != settings.MnqQty || settings.FundMgcQty != settings.MgcQty || settings.FundRotTarget != settings.RotTarget || settings.FundRotStop != settings.RotStop || (settings.FundDayPlan != "SAME" && settings.FundDayPlan != settings.DayPlan) || settings.FundMaxTrades > 0;
            if (fundOwn)
            {
                // the funded accounts traded exactly like the evaluations (your hours) — against your funded settings in the ▶ row
                var same = settings.Copy(); same.FundMnqQty = same.MnqQty; same.FundMgcQty = same.MgcQty; same.FundRotTarget = same.RotTarget; same.FundRotStop = same.RotStop; same.FundDayPlan = "SAME"; same.FundMaxTrades = 0;
                if (cancel == null || !cancel()) list.Add(KeystoneSessionWhatIf.Of("YOUR HOURS • FUNDED TRADED LIKE THE EVALUATIONS", settings.StartHhmm, settings.EndHhmm, Run(same, days, settings.StartHhmm, settings.EndHhmm, cancel)));
            }
            for (int i = 0; i < windows.Count; i++)
            {
                if (cancel != null && cancel()) break;
                var sim = Run(settings, days, windows[i].Item2, windows[i].Item3, cancel);
                var r = KeystoneSessionWhatIf.Of(windows[i].Item1, windows[i].Item2, windows[i].Item3, sim); r.Mine = windows[i].Item2 == settings.StartHhmm && windows[i].Item3 == settings.EndHhmm; list.Add(r);
                if (progress != null) progress(i + 1, windows.Count);
            }
            return list;
        }
        // ⚖ ACCOUNT COUNTS: the same days and settings with 50 / 40 / 30 / 20 / 10 / 5 accounts (your own count marked ▶)
        public static List<KeystoneSessionWhatIf> CompareAccounts(KeystoneSimSettings settings, IList<KeystoneRotDay> days, Func<bool> cancel, Action<int, int> progress)
        {
            var counts = new[] { 50, 40, 30, 20, 10, 5 }.Union(new[] { settings.Accounts }).Distinct().OrderByDescending(x => x).ToList(); var list = new List<KeystoneSessionWhatIf>();
            for (int i = 0; i < counts.Count; i++)
            {
                if (cancel != null && cancel()) break;
                var s = settings.Copy(); s.Accounts = counts[i];
                var r = KeystoneSessionWhatIf.Of(counts[i] + " ACCOUNTS • budget " + "$" + (counts[i] * s.Rules.EvalCost).ToString("N0", CultureInfo.InvariantCulture), settings.StartHhmm, settings.EndHhmm, Run(s, days, settings.StartHhmm, settings.EndHhmm, cancel));
                r.Mine = counts[i] == settings.Accounts; list.Add(r); if (progress != null) progress(i + 1, counts.Count);
            }
            return list;
        }
        // ⚖ 📡 INDICATOR vs RANDOM: the same days, accounts and rules with the indicator's sides against random sides (10 seeds:
        // the luckiest and the middle one), the fixed rules and one side always — the indicator is only worth it above the luck
        public static List<KeystoneSessionWhatIf> CompareSides(KeystoneSimSettings settings, IList<KeystoneRotDay> days, Func<bool> cancel, Action<int, int> progress)
        {
            var list = new List<KeystoneSessionWhatIf>(); int total = 1 + 10 + 6, done = 0;
            Func<string, int, KeystoneSimSettings> with = (dir, seed) => { var c = settings.Copy(); c.Direction = dir; c.Seed = seed; return c; };
            Action<string, KeystoneSimSettings, bool> add = (name, st, mine) => { if (cancel != null && cancel()) return; var r = KeystoneSessionWhatIf.Of(name, settings.StartHhmm, settings.EndHhmm, Run(st, days, settings.StartHhmm, settings.EndHhmm, cancel)); r.Mine = mine; list.Add(r); if (progress != null) progress(++done, total); };
            add("📡 THE ENTRY INDICATOR", with("INDICATOR", settings.Seed), true);
            var rnd = new List<KeystoneSessionWhatIf>();
            for (int i = 1; i <= 10; i++) { if (cancel != null && cancel()) break; rnd.Add(KeystoneSessionWhatIf.Of("RANDOM", settings.StartHhmm, settings.EndHhmm, Run(with("RANDOM4", 100 + i), days, settings.StartHhmm, settings.EndHhmm, cancel))); if (progress != null) progress(++done, total); }
            if (rnd.Count > 0)
            {
                var o = rnd.OrderBy(r => r.Net).ToList(); var lucky = o[o.Count - 1]; var mid = o[(o.Count - 1) / 2];
                lucky.Name = "RANDOM SIDES • THE LUCKIEST OF " + o.Count + " SEEDS"; list.Add(lucky);
                if (mid != lucky) { mid.Name = "RANDOM SIDES • THE MIDDLE OF " + o.Count + " SEEDS"; list.Add(mid); }
            }
            foreach (var d in new[] { "FOLLOW5", "FADE5", "NQLEAD5", "RANDOM", "BUY", "SELL" }) add(KeystoneSimRotation.DirectionName(d), with(d, settings.Seed), false);
            return list;
        }
        // ⚖ FUNDED / BUDGET: your settings vs funded traded like the evaluations vs buying new evaluations at once
        public static List<KeystoneSessionWhatIf> CompareChoices(KeystoneSimSettings settings, IList<KeystoneRotDay> days, Func<bool> cancel, Action<int, int> progress)
        {
            var v = new List<Tuple<string, KeystoneSimSettings>>();
            v.Add(Tuple.Create("YOUR SETTINGS", settings.Copy()));
            var same = settings.Copy(); same.FundMnqQty = same.MnqQty; same.FundMgcQty = same.MgcQty; same.FundRotTarget = same.RotTarget; same.FundRotStop = same.RotStop; same.FundDayPlan = "SAME"; same.FundMaxTrades = 0; v.Add(Tuple.Create("FUNDED TRADED LIKE THE EVALUATIONS", same));
            var one = settings.Copy(); one.FundDayPlan = "ONEWIN"; one.FundMaxTrades = 1; v.Add(Tuple.Create("FUNDED: ONE TRADE A DAY", one));
            foreach (var fw in new[] { "ASK", "AFTER", "WITH" })
            {
                if (fw == settings.FundedWhen) continue; var fx = settings.Copy(); fx.FundedWhen = fw;
                v.Add(Tuple.Create(fw == "ASK" ? "PASS ONLY: FUNDED NOT TRADED" : fw == "AFTER" ? "FUNDED ONLY AFTER EVERY EVALUATION IS DONE" : "FUNDED TOGETHER WITH THE EVALUATIONS", fx));
            }
            var cush = settings.Copy(); if (cush.FundCushion > 0) cush.FundCushion = 0; else { cush.FundCushion = 4000; cush.FundCushionTarget = 200; }
            v.Add(Tuple.Create(cush.FundCushion > 0 ? "FUNDED CUSHION: at +$4,000 only +$200 a day to the payout" : "FUNDED WITHOUT THE CUSHION (full target every day)", cush));
            var tpd = settings.Copy(); tpd.MaxTradesPerDay = settings.MaxTradesPerDay == 1 ? 3 : 1; v.Add(Tuple.Create(tpd.MaxTradesPerDay == 1 ? "ONE TRADE A DAY PER ACCOUNT" : "UP TO 3 TRADES A DAY PER ACCOUNT (" + KeystoneSimSettings.DayPlanName(settings.DayPlan).Split(':')[0] + ")", tpd));
            foreach (var br in new[] { Tuple.Create(1500.0, 500.0), Tuple.Create(1000.0, 500.0), Tuple.Create(1500.0, 1000.0) })
            {
                if (Math.Abs(br.Item1 - settings.RotTarget) < 0.5 && Math.Abs(br.Item2 - settings.RotStop) < 0.5) continue;
                var bx = settings.Copy(); bx.RotTarget = br.Item1; bx.RotStop = br.Item2; if (Math.Abs(settings.FundRotTarget - settings.RotTarget) < 0.5 && Math.Abs(settings.FundRotStop - settings.RotStop) < 0.5) { bx.FundRotTarget = br.Item1; bx.FundRotStop = br.Item2; }
                v.Add(Tuple.Create("TARGET / STOP +$" + br.Item1.ToString("N0", CultureInfo.InvariantCulture) + " / −$" + br.Item2.ToString("N0", CultureInfo.InvariantCulture), bx));
            }
            // the evaluation drawdown: fixed vs trailing at the end of the day vs trailing intraday (every firm)
            foreach (var dt in new[] { "STATIC", "EOD", "INTRADAY" })
            {
                var dx = settings.Copy(); dx.Rules = settings.Rules.Copy(); dx.Rules.EvalDdType = dt;
                var fl = KeystoneSimFirm.Parse(settings.Firms, settings.Rules, settings.Accounts); if (!string.IsNullOrWhiteSpace(settings.Firms)) { foreach (var f in fl) f.Rules.EvalDdType = dt; dx.Firms = KeystoneSimFirm.Text(fl); }
                var curTypes = string.IsNullOrWhiteSpace(settings.Firms) ? new List<string> { settings.Rules.EvalDdType } : KeystoneSimFirm.Parse(settings.Firms, settings.Rules, settings.Accounts).Select(g => g.Rules.EvalDdType).ToList();
                if (curTypes.All(t0 => t0 == dt)) continue;   // that is already the run
                v.Add(Tuple.Create("DRAWDOWN " + (dt == "STATIC" ? "FIXED (no trailing)" : dt == "EOD" ? "TRAILING AT THE DAY'S CLOSE" : "TRAILING INTRADAY (open profit too)"), dx));
            }
            var cp = settings.Copy(); cp.Allocation = settings.Allocation == "COPY" ? "ROTATE" : "COPY"; v.Add(Tuple.Create(cp.Allocation == "COPY" ? "📋 COPY TRADING: EVERY ACCOUNT TAKES EVERY TRADE" : "🔄 ROTATE: ONE ACCOUNT A TRADE, THEN THE NEXT", cp));
            var buy = settings.Copy(); buy.BuyRule = buy.BuyRule == "BREAKEVEN" ? "ALWAYS" : "BREAKEVEN"; v.Add(Tuple.Create(buy.BuyRule == "ALWAYS" ? "BUY NEW EVALUATIONS AT ONCE (no budget wait)" : "NEW EVALUATIONS ONLY AFTER BREAKEVEN", buy));
            var list = new List<KeystoneSessionWhatIf>();
            for (int i = 0; i < v.Count; i++)
            {
                if (cancel != null && cancel()) break;
                var r = KeystoneSessionWhatIf.Of(v[i].Item1, settings.StartHhmm, settings.EndHhmm, Run(v[i].Item2, days, settings.StartHhmm, settings.EndHhmm, cancel)); r.Mine = i == 0; list.Add(r);
                if (progress != null) progress(i + 1, v.Count);
            }
            return list;
        }
        // 🏆 WINNERS: what came before each rotation trade (both instruments' last 5 / 15 / 30 minutes, the session, the sides) and how
        // it ended — to see which conditions the winners shared, against every trade
        public static List<KeystoneTradeContext> Contexts(KeystonePropSim sim, IList<KeystoneRotDay> days)
        {
            var byDay = days.ToDictionary(d => d.Day.Date, d => d); var list = new List<KeystoneTradeContext>();
            foreach (var t in sim.Trades)
            {
                KeystoneRotDay d; if (!byDay.TryGetValue(t.Day.Date, out d)) continue; int k = KeystoneRotDay.SlotOf(t.Entry);
                Func<bool, int, int> mv = (mnq, n) => { double a = mnq ? d.CloseM(k - 1) : d.CloseG(k - 1), b = mnq ? d.CloseM(k - 1 - n) : d.CloseG(k - 1 - n); return double.IsNaN(a) || double.IsNaN(b) || k - 1 - n < 0 ? 0 : Math.Sign(a - b); };
                string legs = t.Legs ?? ""; int sM = 0;
                int sG = 0; int gi = legs.IndexOf("MGC"); if (gi > 0) { string before = legs.Substring(0, gi); int lb = before.LastIndexOf("BUY"), ls = before.LastIndexOf("SELL"); sG = lb > ls ? 1 : -1; }
                int mi = legs.IndexOf("MNQ"); if (mi > 0) { string before = legs.Substring(0, mi); int lb = before.LastIndexOf("BUY"), ls = before.LastIndexOf("SELL"); sM = lb > ls ? 1 : -1; }
                var c = new KeystoneTradeContext { Trade = t, SideM = sM, SideG = sG, M5 = mv(true, 5), M15 = mv(true, 15), M30 = mv(true, 30), G5 = mv(false, 5), G15 = mv(false, 15), G30 = mv(false, 30), Minutes = (t.Exit - t.Entry).TotalMinutes, Won = t.Reason == "TARGET" };
                int hh = t.Entry.Hour * 100 + t.Entry.Minute; c.Session = SessionNames.Where((n, i) => i < 6 && KeystoneRotDay.Slot(hh) >= KeystoneRotDay.Slot(SessionHours[i][0]) && KeystoneRotDay.Slot(hh) <= KeystoneRotDay.Slot(SessionHours[i][1])).DefaultIfEmpty("OTHER HOURS").First();
                list.Add(c);
            }
            return list;
        }
        // the winners' share per condition: trades with it, how many reached the target, the win rate against all trades
        public static List<Tuple<string, string, int, int, double>> WinnerTable(List<KeystoneTradeContext> cx)
        {
            var rows = new List<Tuple<string, string, int, int, double>>(); if (cx.Count == 0) return rows;
            Action<string, Func<KeystoneTradeContext, string>> group = (fam, key) => { foreach (var g in cx.GroupBy(key).OrderBy(g => g.Key)) rows.Add(Tuple.Create(fam, g.Key, g.Count(), g.Count(x => x.Won), g.Where(x => x.Won).Select(x => x.Minutes).DefaultIfEmpty(0).Average())); };
            Func<int, int, string> rel = (side, mv) => mv == 0 || side == 0 ? "flat before" : side == mv ? "WITH the move" : "AGAINST the move";
            group("SESSION", x => x.Session);
            group("SIDES", x => KeystoneSimRotation.SidesName(x.SideM, x.SideG));
            group("MNQ vs its last 5 min", x => rel(x.SideM, x.M5)); group("MGC vs its last 5 min", x => rel(x.SideG, x.G5));
            group("MNQ vs its last 15 min", x => rel(x.SideM, x.M15)); group("MGC vs its last 15 min", x => rel(x.SideG, x.G15));
            group("MNQ vs its last 30 min", x => rel(x.SideM, x.M30)); group("MGC vs its last 30 min", x => rel(x.SideG, x.G30));
            group("MNQ + MGC last 5 min", x => x.M5 == 0 || x.G5 == 0 ? "one flat" : x.M5 == x.G5 ? "moved the SAME way" : "moved OPPOSITE ways");
            group("HOUR", x => x.Trade.Entry.ToString("HH") + ":00");
            return rows;
        }
        // the clear winner: the most money (payouts − evaluations), then the pass rate, then the trading P/L, then the days at target
        public static KeystoneSessionWhatIf Winner(IList<KeystoneSessionWhatIf> rows)
        {
            return rows == null || rows.Count == 0 ? null : rows.OrderByDescending(r => Math.Round(r.Net, 2)).ThenByDescending(r => r.PassRate).ThenByDescending(r => Math.Round(r.Pnl, 2)).ThenByDescending(r => r.AtTarget).First();
        }
    }

    // ---- 🛑 LOSERS + BREAKEVEN MATH: every losing trade's best open profit before it lost, and every rotation trade replayed on its
    // 1-minute bars with a breakeven step at +$X (once the open P/L reaches +X the stop moves to + the fees) — which X saves the most
    // losers without cutting more winners. The same engine as the runs (stop first at the minute's worst, targets at a close).
    public sealed class KeystoneBeRow { public double At; public int Trades, Wins, Saved, Cut; public double Net, Change; }
    public sealed class KeystoneLoser { public KeystoneSimTrade Trade; public double Peak, Worst; }
    public static class KeystoneBreakevenStudy
    {
        // "BUY 10 MNQ + SELL 10 MGC" → sides and contracts
        public static bool Legs(string legs, out int dM, out int dG, out int qM, out int qG)
        {
            dM = dG = qM = qG = 0; if (string.IsNullOrEmpty(legs)) return false;
            foreach (var part in legs.Split('+'))
            {
                var w = part.Trim().Split(' '); if (w.Length < 3) continue; int q; if (!int.TryParse(w[1], out q)) continue; int d = w[0] == "BUY" ? 1 : w[0] == "SELL" ? -1 : 0;
                if (w[2] == "MNQ") { dM = d; qM = q; } else if (w[2] == "MGC") { dG = d; qG = q; }
            }
            return qM + qG > 0;
        }
        public static List<double> Levels(double target) { var l = new List<double>(); for (double x = 100; x < target - 1e-9; x += 100) l.Add(x); return l; }
        // every rotation trade of the run replayed: the baseline (no breakeven) and each level; losers with their recomputed peak
        public static List<KeystoneBeRow> Run(KeystonePropSim sim, IList<KeystoneRotDay> days, IList<double> levels, out List<KeystoneLoser> losers, Func<bool> cancel)
        {
            var byDay = days.ToDictionary(d => d.Day.Date, d => d); var s = sim.S; losers = new List<KeystoneLoser>();
            int end = KeystoneRotDay.Slot(s.EndHhmm); if (s.Rules.FlatByHhmm > 0) end = Math.Min(end, KeystoneRotDay.Slot(s.Rules.FlatByHhmm) - 1);
            var rows = new List<KeystoneBeRow> { new KeystoneBeRow { At = 0 } }; rows.AddRange(levels.Select(x => new KeystoneBeRow { At = x }));
            var tiers = s.Tiers();
            foreach (var t in sim.Trades)
            {
                if (cancel != null && cancel()) break;
                KeystoneRotDay d; int dM, dG, qM, qG; if (!byDay.TryGetValue(t.Day.Date, out d) || !Legs(t.Legs, out dM, out dG, out qM, out qG)) continue;
                int k = KeystoneRotDay.SlotOf(t.Entry); bool funded = t.Phase == "FUNDED";
                double fees = qM * KeystoneRotationLab.CostMnq + qG * KeystoneRotationLab.CostMgc, target = (funded ? s.FundRotTarget : s.RotTarget) + fees, stop = funded ? s.FundRotStop : s.RotStop;
                int how0, xs; double pk, wr; double v0 = KeystoneRotationLab.Trade(d, k, end, dM, dG, qM, qG, target, stop, 0, tiers, out how0, out xs, out pk, out wr);
                if (how0 == -9) continue;
                if (v0 < 0) losers.Add(new KeystoneLoser { Trade = t, Peak = pk, Worst = wr });
                foreach (var r in rows)
                {
                    int how = how0; double v = v0; if (r.At > 0) v = KeystoneRotationLab.Trade(d, k, end, dM, dG, qM, qG, target, stop, r.At, tiers, out how, out xs, out pk, out wr);
                    r.Trades++; r.Net += v; if (how == 1) r.Wins++;
                    if (r.At > 0 && how0 == -1 && how != -1) r.Saved++;      // a stopped loser that the breakeven step closed earlier
                    if (r.At > 0 && how0 == 1 && how != 1) r.Cut++;          // a winner the breakeven step closed before its target
                }
            }
            foreach (var r in rows) r.Change = r.Net - rows[0].Net;
            return rows;
        }
        // the best level: the most $ above no breakeven (null when none helps)
        public static KeystoneBeRow Best(IList<KeystoneBeRow> rows) { return rows == null ? null : rows.Where(r => r.At > 0 && r.Change > 1e-6).OrderByDescending(r => r.Change).FirstOrDefault(); }
    }
    // ---- 🗓 SESSIONS BY DAY: every day of a test replayed in every session window (same accounts, rules, sides, size, bracket), one
    // day at a time → per day the best session; saved to a RESEARCH POOL that grows with every test (one row per day × session × set-up)
    public sealed class KeystoneDaySession
    {
        public DateTime Day; public int Session; public string Setup = string.Empty; public int Trades, Wins, AtTarget, AcctDays; public double Pnl;
        public int[] SideTrades = new int[4], SideWins = new int[4];   // BB, SS, BS, SB
        public static readonly string[] SideNames = { "BUY BUY", "SELL SELL", "BUY MNQ • SELL MGC", "SELL MNQ • BUY MGC" };
        public string Key { get { return Day.ToString("yyyy-MM-dd") + "|" + Session + "|" + Setup; } }
        public const string Header = "day,session,setup,trades,wins,at_target,account_days,pnl,bb_t,bb_w,ss_t,ss_w,bs_t,bs_w,sb_t,sb_w";
        public string Line() { return string.Join(",", Day.ToString("yyyy-MM-dd"), Session, Setup.Replace(",", " "), Trades, Wins, AtTarget, AcctDays, Pnl.ToString("0.00", CultureInfo.InvariantCulture), string.Join(",", Enumerable.Range(0, 4).Select(i => SideTrades[i] + "," + SideWins[i]))); }
        public static KeystoneDaySession Parse(string l)
        {
            var a = (l ?? "").Split(','); if (a.Length < 16) return null; DateTime d; if (!DateTime.TryParseExact(a[0], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out d)) return null;
            var x = new KeystoneDaySession { Day = d, Setup = a[2] }; int.TryParse(a[1], out x.Session); int.TryParse(a[3], out x.Trades); int.TryParse(a[4], out x.Wins); int.TryParse(a[5], out x.AtTarget); int.TryParse(a[6], out x.AcctDays);
            double.TryParse(a[7], NumberStyles.Float, CultureInfo.InvariantCulture, out x.Pnl); for (int i = 0; i < 4; i++) { int.TryParse(a[8 + 2 * i], out x.SideTrades[i]); int.TryParse(a[9 + 2 * i], out x.SideWins[i]); }
            return x;
        }
        // the six windows of a day (NY time) — the same as ⚖ COMPARE SESSIONS
        public static readonly int[] Windows = { 0, 1, 2, 3, 4, 5 };
        public static string SetupOf(KeystoneSimSettings s) { return s.Direction + " " + s.MnqQty + "+" + s.MgcQty + " +" + s.RotTarget.ToString("0", CultureInfo.InvariantCulture) + "/-" + s.RotStop.ToString("0", CultureInfo.InvariantCulture) + " " + s.DayPlan + " " + s.MaxTradesPerDay + "/day " + s.Accounts + "acc"; }
        public static List<KeystoneDaySession> Run(KeystoneSimSettings settings, IList<KeystoneRotDay> days, Func<bool> cancel, Action<int, int> progress)
        {
            var list = new List<KeystoneDaySession>(); string setup = SetupOf(settings); int n = 0, total = days.Count * Windows.Length;
            foreach (var d in days)
                foreach (int w in Windows)
                {
                    if (cancel != null && cancel()) return list;
                    var s = settings.Copy(); s.BuyRule = "ALWAYS"; s.FundedWhen = "ASK";
                    var sim = KeystoneRotationLab.Run(s, new List<KeystoneRotDay> { d }, KeystoneRotationLab.SessionHours[w][0], KeystoneRotationLab.SessionHours[w][1], cancel);
                    var x = new KeystoneDaySession { Day = d.Day, Session = w, Setup = setup, Trades = sim.Trades.Count, Wins = sim.Trades.Count(t => t.Pnl > 0), Pnl = sim.Trades.Sum(t => t.Pnl), AtTarget = KeystoneRotationLab.DaysAtTarget(sim), AcctDays = sim.Trades.Select(t => t.Account).Distinct().Count() };
                    foreach (var t in sim.Trades) { int dM, dG, qM, qG; KeystoneBreakevenStudy.Legs(t.Legs, out dM, out dG, out qM, out qG); int k = dM >= 0 && dG >= 0 ? 0 : dM <= 0 && dG <= 0 ? 1 : dM > 0 ? 2 : 3; if (dM == 0 && dG == 0) continue; x.SideTrades[k]++; if (t.Pnl > 0) x.SideWins[k]++; }
                    list.Add(x); if (progress != null) progress(++n, total);
                }
            return list;
        }
        // the best session of each day: the most accounts at their target, then the most $
        public static Dictionary<DateTime, int> BestOf(IEnumerable<KeystoneDaySession> rows)
        {
            return rows.GroupBy(r => r.Day).ToDictionary(g => g.Key, g => g.OrderByDescending(r => r.AtTarget).ThenByDescending(r => r.Pnl).First().Session);
        }
        // the AI's question: the research pool summed up (by session, weekday × session, month, sides per session)
        public const string AiSystem = "You are the quantitative research reviewer inside SPASIX FUTURE, a futures backtesting platform used to PASS prop-firm evaluations with an MNQ + MGC rotation (one combined trade at a time, a fixed $ target / stop, accounts in turn). "
            + "You get a RESEARCH POOL: many historical days, each replayed in six session windows (New York time), with trades, wins, the accounts that reached their day target, the P/L and the sides (BUY BUY / SELL SELL / BUY MNQ+SELL MGC / SELL MNQ+BUY MGC) that won. "
            + "Find the patterns that would help pass evaluations: which session, which weekday / month, which sides, and how stable each pattern is (sample sizes, consistency across years, luck). Be honest about noise; never promise profit. "
            + "Give: 1) the 3–5 strongest findings with numbers, 2) what to try next in the simulator, 3) what looks like luck. Plain text, at most 30 lines, no markdown tables.";
        public static string AiPrompt(IList<KeystoneDaySession> pool)
        {
            var sb = new StringBuilder(); var setups = pool.Select(p => p.Setup).Distinct().ToList();
            sb.AppendLine("RESEARCH POOL: " + pool.Select(p => p.Day).Distinct().Count() + " days • " + pool.Count + " day × session rows • set-ups: " + string.Join(" | ", setups.Take(6)));
            var best = BestOf(pool);
            sb.AppendLine("BY SESSION (days best • account-days at target • trades • win % • P/L):");
            foreach (var g in pool.GroupBy(p => p.Session).OrderBy(g => g.Key))
            {
                int t = g.Sum(x => x.Trades), w = g.Sum(x => x.Wins); sb.AppendLine("- " + KeystoneRotationLab.SessionNames[g.Key] + ": best on " + best.Count(b => b.Value == g.Key) + " days • " + g.Sum(x => x.AtTarget) + " at target • " + t + " trades • " + (t == 0 ? 0 : 100.0 * w / t).ToString("0") + "% • $" + g.Sum(x => x.Pnl).ToString("0", CultureInfo.InvariantCulture));
                sb.AppendLine("  sides: " + string.Join(", ", Enumerable.Range(0, 4).Select(i => SideNames[i] + " " + g.Sum(x => x.SideWins[i]) + "/" + g.Sum(x => x.SideTrades[i]))));
            }
            sb.AppendLine("BEST SESSION BY WEEKDAY (days):");
            foreach (var g in best.GroupBy(b => b.Key.DayOfWeek).OrderBy(g => (int)g.Key)) sb.AppendLine("- " + g.Key + ": " + string.Join(", ", g.GroupBy(b => b.Value).OrderByDescending(x => x.Count()).Select(x => KeystoneRotationLab.SessionNames[x.Key].Split(' ')[0] + " " + x.Count())));
            sb.AppendLine("BY YEAR (at-target account-days per session):");
            foreach (var g in pool.GroupBy(p => p.Day.Year).OrderBy(g => g.Key)) sb.AppendLine("- " + g.Key + ": " + string.Join(", ", g.GroupBy(x => x.Session).OrderBy(x => x.Key).Select(x => KeystoneRotationLab.SessionNames[x.Key].Split(' ')[0] + " " + x.Sum(y => y.AtTarget))));
            sb.AppendLine("Find the patterns.");
            return sb.ToString();
        }
    }
    public sealed class KeystoneTradeContext { public KeystoneSimTrade Trade; public int SideM, SideG, M5, M15, M30, G5, G15, G30; public double Minutes; public bool Won; public string Session = string.Empty; }

    // ---- 📡 ENTRY INDICATOR: the confirmation learned from the winners of a TRAINING date range ------------------------------
    // Every few minutes of every training day, all 4 sides (BB / SS / BS / SB) are traded with the run's own bracket (+target / −stop,
    // contracts, costs) on 1-minute bars, so every state has each side's real outcome — not only the sides a run happened to pick.
    // A state = MNQ and MGC up / down / flat over the last W minutes (and the session, when that helps). A state gets a rule only
    // with enough trades and a win rate clearly above all sides' average (the coin flip); otherwise the indicator says WAIT.
    // W (5 / 15 / 30) and session-or-not are chosen on the LATER half of the training days after learning on the earlier half, so
    // the choice itself is checked on days it did not learn from; the chosen version is then learned on every training day.
    public sealed class KeystoneIndicatorSample { public DateTime Day; public int Hhmm; public int[] M = new int[3], G = new int[3]; public bool[] Fresh = new bool[3]; public bool[] Win = new bool[4]; public double[] Pnl = new double[4]; }
    public sealed class KeystoneIndicatorRule { public string Key = string.Empty; public int DirM, DirG, Trades, Wins; public double Pnl; public double WinPct { get { return Trades == 0 ? 0 : 100.0 * Wins / Trades; } }
        public int[] Win4 = new int[4];   // how often EACH side (BB • SS • BS • SB) won in this state (0s = an older indicator that kept only the best)
        public bool HasAll { get { return Win4 != null && Win4.Length == 4 && Win4.Sum() > 0; } } }
    public sealed class KeystoneEntryIndicator
    {
        public static readonly int[] Windows = { 5, 15, 30 };
        public static readonly int[][] Sides = { new[] { 1, 1 }, new[] { -1, -1 }, new[] { 1, -1 }, new[] { -1, 1 } };   // BB • SS • BS • SB
        public int Window = 15; public bool BySession; public int MinTrades = 30, Step = 1; public double MinEdge = 3;   // edge in win-rate points over the coin flip
        public DateTime Formed = DateTime.MinValue; public string Source = string.Empty;   // when it was formed and from what (BUILD or the run it learned from)
        public DateTime TrainFrom = DateTime.MinValue, TrainTo = DateTime.MinValue; public int StartHhmm = 930, EndHhmm = 1555, Days, Samples;
        public double Target, Stop, BaseWin, HoldoutWin, HoldoutBase; public int HoldoutTrades; public string Variants = string.Empty;
        public List<KeystoneIndicatorRule> Rules = new List<KeystoneIndicatorRule>();
        public bool HoldoutEdge { get { return HoldoutTrades >= 30 && HoldoutWin > HoldoutBase; } }

        public static int SessionOf(int hhmm)
        {
            int s = KeystoneRotDay.Slot(hhmm);
            for (int i = 0; i < 6; i++) if (s >= KeystoneRotDay.Slot(KeystoneRotationLab.SessionHours[i][0]) && s <= KeystoneRotDay.Slot(KeystoneRotationLab.SessionHours[i][1])) return i;
            return 6;
        }
        public static string SessionName(int i) { return i >= 0 && i < 6 ? KeystoneRotationLab.SessionNames[i] : "OTHER HOURS"; }
        static string KeyOf(int m, int g, int session, bool bySession) { return m + "," + g + (bySession ? "," + session : ""); }
        static int Sgn(double v) { return double.IsNaN(v) || Math.Abs(v) < 1e-9 ? 0 : Math.Sign(v); }
        public static string StateName(string key, int window)
        {
            var a = key.Split(','); Func<string, string> arrow = s => s == "1" ? "▲ up" : s == "-1" ? "▼ down" : "· flat";
            int sess; return "MNQ " + arrow(a[0]) + " • MGC " + arrow(a.Length > 1 ? a[1] : "0") + " (last " + window + " min)" + (a.Length > 2 && int.TryParse(a[2], out sess) ? " • " + SessionName(sess) : "");
        }

        // a SETUP FORMS when MNQ's / MGC's direction over the last W minutes changes into a new state (a minute ago it was another):
        // the indicator learns from those moments only, and trades only when one forms (no fixed pause in between)
        // every setup moment (checked every Step minutes) of every day inside startHhmm → endHhmm: all 4 sides traded with the bracket
        public static List<KeystoneIndicatorSample> Sample(KeystoneSimSettings s, IList<KeystoneRotDay> days, int step, Func<bool> cancel)
        {
            var list = new List<KeystoneIndicatorSample>(); step = Math.Max(1, step);
            int s0 = KeystoneRotDay.Slot(s.StartHhmm), e0 = KeystoneRotDay.Slot(s.EndHhmm); if (s.Rules.FlatByHhmm > 0) e0 = Math.Min(e0, KeystoneRotDay.Slot(s.Rules.FlatByHhmm) - 1);
            int qM = Math.Max(0, s.MnqQty), qG = Math.Max(0, s.MgcQty); if (qM + qG == 0) return list;
            double fees = qM * KeystoneRotationLab.CostMnq + qG * KeystoneRotationLab.CostMgc, target = s.RotTarget + fees, stop = s.RotStop;
            foreach (var d in days)
            {
                if (cancel != null && cancel()) break;
                for (int k = Math.Max(s0, 30); k < e0 - 1; k += step)
                {
                    if ((qM > 0 && !d.HasM(k)) || (qG > 0 && !d.HasG(k))) continue;
                    var x = new KeystoneIndicatorSample { Day = d.Day }; int mins = (18 * 60 + k) % 1440; x.Hhmm = mins / 60 * 100 + mins % 60; bool any = false;
                    for (int w = 0; w < Windows.Length; w++)
                    {
                        x.M[w] = Sgn(d.CloseM(k - 1) - d.OpenM(k - Windows[w])); x.G[w] = Sgn(d.CloseG(k - 1) - d.OpenG(k - Windows[w]));
                        int pm = Sgn(d.CloseM(k - 2) - d.OpenM(k - 1 - Windows[w])), pg = Sgn(d.CloseG(k - 2) - d.OpenG(k - 1 - Windows[w]));
                        x.Fresh[w] = x.M[w] != 0 && x.G[w] != 0 && (x.M[w] != pm || x.G[w] != pg); any |= x.Fresh[w];
                    }
                    if (!any) continue;
                    bool ok = true;
                    for (int c = 0; c < 4 && ok; c++)
                    {
                        int how, xs; double pk, wr; double v = KeystoneRotationLab.Trade(d, k, e0, Sides[c][0], Sides[c][1], qM, qG, target, stop, 0, null, out how, out xs, out pk, out wr);
                        if (how == -9) ok = false; x.Win[c] = how == 1; x.Pnl[c] = v;
                    }
                    if (ok) list.Add(x);
                }
            }
            return list;
        }
        // the rules of one version (window index w, session or not) learned from these samples
        static List<KeystoneIndicatorRule> Learn(List<KeystoneIndicatorSample> xs, int w, bool bySession, int minTrades, double minEdge, out double baseWin)
        {
            xs = xs.Where(x => x.Fresh[w]).ToList();   // the moments a setup of this window formed
            var rules = new List<KeystoneIndicatorRule>(); baseWin = xs.Count == 0 ? 0 : 100.0 * xs.Sum(x => x.Win.Count(b => b)) / (4.0 * xs.Count);
            foreach (var g in xs.GroupBy(x => KeyOf(x.M[w], x.G[w], SessionOf(x.Hhmm), bySession)))
            {
                if (g.Key.StartsWith("0,") || g.Key.Split(',')[1] == "0") continue;   // a flat instrument says nothing
                int n = g.Count(); if (n < minTrades) continue; int best = -1; double bestWin = -1, bestPnl = 0;
                for (int c = 0; c < 4; c++) { double wp = 100.0 * g.Count(x => x.Win[c]) / n, pl = g.Sum(x => x.Pnl[c]); if (wp > bestWin + 1e-9 || (Math.Abs(wp - bestWin) < 1e-9 && pl > bestPnl)) { best = c; bestWin = wp; bestPnl = pl; } }
                if (best < 0 || bestWin < baseWin + minEdge) continue;
                rules.Add(new KeystoneIndicatorRule { Key = g.Key, DirM = Sides[best][0], DirG = Sides[best][1], Trades = n, Wins = g.Count(x => x.Win[best]), Pnl = bestPnl, Win4 = Enumerable.Range(0, 4).Select(c => g.Count(x => x.Win[c])).ToArray() });
            }
            return rules.OrderByDescending(r => r.WinPct).ToList();
        }
        // the rules applied to other samples → trades taken, their win rate, and all sides' average there (the coin flip)
        static void Score(List<KeystoneIndicatorRule> rules, List<KeystoneIndicatorSample> xs, int w, bool bySession, out int n, out double win, out double baseWin)
        {
            xs = xs.Where(x => x.Fresh[w]).ToList(); var map = rules.ToDictionary(r => r.Key, r => r); n = 0; int wins = 0;
            baseWin = xs.Count == 0 ? 0 : 100.0 * xs.Sum(x => x.Win.Count(b => b)) / (4.0 * xs.Count);
            foreach (var x in xs)
            {
                KeystoneIndicatorRule r; if (!map.TryGetValue(KeyOf(x.M[w], x.G[w], SessionOf(x.Hhmm), bySession), out r)) continue;
                int c = Array.FindIndex(Sides, sd => sd[0] == r.DirM && sd[1] == r.DirG); n++; if (x.Win[c]) wins++;
            }
            win = n == 0 ? 0 : 100.0 * wins / n;
        }
        // 🎯 BUILD: sample the training days, choose the version on the later half, learn it on all of them
        public static KeystoneEntryIndicator Build(KeystoneSimSettings s, IList<KeystoneRotDay> days, int step, int minTrades, double minEdge, Func<bool> cancel)
        {
            var ind = new KeystoneEntryIndicator { Step = Math.Max(1, step), MinTrades = Math.Max(5, minTrades), MinEdge = minEdge, StartHhmm = s.StartHhmm, EndHhmm = s.EndHhmm, Days = days.Count, Formed = new DateTime(DateTime.Now.Year, DateTime.Now.Month, DateTime.Now.Day, DateTime.Now.Hour, DateTime.Now.Minute, 0), Source = "BUILD" };
            var xs = Sample(s, days, ind.Step, cancel); ind.Samples = xs.Count;
            int qM = Math.Max(0, s.MnqQty), qG = Math.Max(0, s.MgcQty); ind.Target = s.RotTarget; ind.Stop = s.RotStop;
            if (days.Count > 0) { ind.TrainFrom = days.Min(d => d.Day); ind.TrainTo = days.Max(d => d.Day); }
            if (xs.Count == 0) return ind;
            var dayList = xs.Select(x => x.Day).Distinct().OrderBy(d => d).ToList(); var cut = dayList[dayList.Count / 2];
            var early = xs.Where(x => x.Day < cut).ToList(); var late = xs.Where(x => x.Day >= cut).ToList();
            double bestScore = double.NegativeInfinity; int bw = 1; bool bs = false; var notes = new List<string>();
            for (int w = 0; w < Windows.Length; w++)
                foreach (bool sess in new[] { false, true })
                {
                    double b0; var r0 = Learn(early, w, sess, Math.Max(5, ind.MinTrades / 2), minEdge, out b0); int n; double win, bl; Score(r0, late, w, sess, out n, out win, out bl);
                    double score = n < 30 ? double.NegativeInfinity : (win - bl) * Math.Sqrt(n);
                    notes.Add(Windows[w] + "m" + (sess ? "+session" : "") + ": " + r0.Count + " rules, later half " + n + " trades " + win.ToString("0.0", CultureInfo.InvariantCulture) + "% vs " + bl.ToString("0.0", CultureInfo.InvariantCulture) + "%");
                    if (score > bestScore) { bestScore = score; bw = w; bs = sess; ind.HoldoutTrades = n; ind.HoldoutWin = win; ind.HoldoutBase = bl; }
                }
            ind.Window = Windows[bw]; ind.BySession = bs; ind.Variants = string.Join(" | ", notes);
            double bwin; ind.Rules = Learn(xs, bw, bs, ind.MinTrades, minEdge, out bwin); ind.BaseWin = bwin;
            return ind;
        }
        // the rule for a state: MNQ's / MGC's move over the last Window minutes → (dM, dG), or (0, 0) = no rule
        public Tuple<int, int> Signal(double moveM, double moveG, int hhmm)
        {
            string key = KeyOf(Sgn(moveM), Sgn(moveG), SessionOf(hhmm), BySession); var r = Rules.FirstOrDefault(x => x.Key == key);
            return r == null ? Tuple.Create(0, 0) : Tuple.Create(r.DirM, r.DirG);
        }
        // the rule of the state now (null = this state has no edge → it waits)
        public KeystoneIndicatorRule RuleFor(double moveM, double moveG, int hhmm) { string key = KeyOf(Sgn(moveM), Sgn(moveG), SessionOf(hhmm), BySession); return Rules.FirstOrDefault(x => x.Key == key); }
        public static bool Forms(double moveM, double moveG, double prevM, double prevG) { return !(Sgn(moveM) == Sgn(prevM) && Sgn(moveG) == Sgn(prevG)); }
        // the entry NOW: only when a setup forms this minute (a minute ago the state was another) and it has a rule; else WAIT
        public Tuple<int, int> Signal(double moveM, double moveG, int hhmm, double prevM, double prevG)
        {
            if (Sgn(moveM) == Sgn(prevM) && Sgn(moveG) == Sgn(prevG)) return Tuple.Create(0, 0);
            return Signal(moveM, moveG, hhmm);
        }
        public Tuple<int, int> Signal(KeystoneRotDay d, int k)
        {
            if (k < Window + 1) return Tuple.Create(0, 0); int mins = (18 * 60 + k) % 1440;
            return Signal(d.CloseM(k - 1) - d.OpenM(k - Window), d.CloseG(k - 1) - d.OpenG(k - Window), mins / 60 * 100 + mins % 60, d.CloseM(k - 2) - d.OpenM(k - 1 - Window), d.CloseG(k - 2) - d.OpenG(k - 1 - Window));
        }
        // what it waits for, in words (the panel / chart while no setup has formed)
        public string Waiting(double moveM, double moveG)
        {
            Func<int, string> ar = v => v > 0 ? "▲" : v < 0 ? "▼" : "·";
            return "📡 now MNQ " + ar(Sgn(moveM)) + " MGC " + ar(Sgn(moveG)) + " (last " + Window + " min) • waiting for a setup to form: " + (Rules.Count == 0 ? "none has an edge" : string.Join(" • ", Rules.Take(4).Select(r => { var a = r.Key.Split(','); return "MNQ " + ar(int.Parse(a[0])) + " MGC " + ar(int.Parse(a[1])) + " → " + KeystoneSimRotation.Arrows(r.DirM, r.DirG); })));
        }
        public string Describe()
        {
            Func<double, string> p = v => v.ToString("0.0", CultureInfo.InvariantCulture) + "%";
            return (Formed != DateTime.MinValue ? "formed " + Formed.ToString("yyyy-MM-dd HH:mm") + (Source != "" ? " (" + Source + ")" : "") + " • " : "") + "trained " + TrainFrom.ToString("yyyy-MM-dd") + " → " + TrainTo.ToString("yyyy-MM-dd") + " (" + Days + " days, " + Samples + " moments × 4 sides) • last " + Window + " min" + (BySession ? " + session" : "") + " • +$" + Target.ToString("N0", CultureInfo.InvariantCulture) + " / −$" + Stop.ToString("N0", CultureInfo.InvariantCulture)
                + " • " + Rules.Count + " rules • coin flip " + p(BaseWin) + " • later-half check: " + HoldoutTrades + " trades " + p(HoldoutWin) + " vs " + p(HoldoutBase) + (HoldoutEdge ? " (EDGE)" : " (NO EDGE)");
        }
        // one line (it travels inside the run's settings, so a run keeps the indicator it traded)
        public string ToText()
        {
            Func<double, string> d = v => v.ToString("0.####", CultureInfo.InvariantCulture);
            var head = new[] { "W=" + Window, "S=" + (BySession ? 1 : 0), "MIN=" + MinTrades, "EDGE=" + d(MinEdge), "STEP=" + Step, "TF=" + TrainFrom.ToString("yyyy-MM-dd"), "TT=" + TrainTo.ToString("yyyy-MM-dd"), "H0=" + StartHhmm, "H1=" + EndHhmm, "D=" + Days, "N=" + Samples, "TG=" + d(Target), "ST=" + d(Stop), "BASE=" + d(BaseWin), "HW=" + d(HoldoutWin), "HB=" + d(HoldoutBase), "HN=" + HoldoutTrades, "FM=" + (Formed == DateTime.MinValue ? "" : Formed.ToString("yyyy-MM-dd HH:mm")), "SRC=" + (Source ?? "").Replace("|", " ").Replace(";", " ").Replace("=", " ") };
            return string.Join("|", head) + "|R=" + string.Join(";", Rules.Select(r => r.Key + ":" + r.DirM + ":" + r.DirG + ":" + r.Trades + ":" + r.Wins + ":" + d(r.Pnl) + (r.HasAll ? ":" + string.Join("/", r.Win4) : "")));
        }
        public static KeystoneEntryIndicator FromText(string text)
        {
            if (string.IsNullOrWhiteSpace(text) || !text.Contains("R=")) return null; var ind = new KeystoneEntryIndicator();
            foreach (var part in text.Trim().Split('|'))
            {
                int e = part.IndexOf('='); if (e <= 0) continue; string k = part.Substring(0, e), v = part.Substring(e + 1); double dv; int iv; DateTime dt;
                double.TryParse(v, NumberStyles.Float, CultureInfo.InvariantCulture, out dv); int.TryParse(v, out iv); DateTime.TryParseExact(v, "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out dt);
                switch (k)
                {
                    case "W": ind.Window = iv > 0 ? iv : 15; break; case "S": ind.BySession = iv == 1; break; case "MIN": ind.MinTrades = iv; break; case "EDGE": ind.MinEdge = dv; break; case "STEP": ind.Step = iv; break;
                    case "TF": ind.TrainFrom = dt; break; case "TT": ind.TrainTo = dt; break; case "H0": ind.StartHhmm = iv; break; case "H1": ind.EndHhmm = iv; break; case "D": ind.Days = iv; break; case "N": ind.Samples = iv; break;
                    case "FM": { DateTime fm; if (DateTime.TryParseExact(v, "yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture, DateTimeStyles.None, out fm)) ind.Formed = fm; break; }
                    case "SRC": ind.Source = v; break;
                    case "TG": ind.Target = dv; break; case "ST": ind.Stop = dv; break; case "BASE": ind.BaseWin = dv; break; case "HW": ind.HoldoutWin = dv; break; case "HB": ind.HoldoutBase = dv; break; case "HN": ind.HoldoutTrades = iv; break;
                    case "R":
                        foreach (var r in v.Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries))
                        {
                            var a = r.Split(':'); if (a.Length < 6) continue; var x = new KeystoneIndicatorRule { Key = a[0] };
                            int.TryParse(a[1], out x.DirM); int.TryParse(a[2], out x.DirG); int.TryParse(a[3], out x.Trades); int.TryParse(a[4], out x.Wins); double.TryParse(a[5], NumberStyles.Float, CultureInfo.InvariantCulture, out x.Pnl);
                            if (a.Length >= 7) { var w4 = a[6].Split('/'); if (w4.Length == 4) for (int q = 0; q < 4; q++) int.TryParse(w4[q], out x.Win4[q]); }
                            ind.Rules.Add(x);
                        }
                        break;
                }
            }
            return ind;
        }
        // 🤖 the AI review: the indicator, its checks and (when run) the test on unseen days, in plain text for the model
        public const string AiSystem = "You are the quantitative research reviewer inside SPASIX FUTURE, a futures backtesting platform for prop-firm evaluations (micro contracts: MNQ $2 a point, MGC $10 a point). "
            + "You get an ENTRY INDICATOR learned from historical 1-minute bars: for each market state (MNQ and MGC up/down over the last N minutes, optionally the session) the sides (BUY/SELL MNQ, BUY/SELL MGC) that most often reached a fixed $ target before a fixed $ stop, against the average of all four sides (the coin flip). "
            + "You also get its check on the later half of the training days and, when available, a test on days it never saw, against random sides. "
            + "Judge honestly whether this is a real edge or noise: consider sample sizes, how far above the coin flip, whether the later-half and unseen-day results agree, multiple-testing luck, and costs. "
            + "Then give: a verdict (REAL EDGE / WEAK / NOISE), the rules worth keeping and the ones to drop, and 2-4 concrete next confirmations to test (only from data a 1-minute backtest can see). "
            + "Never promise profits; it is research on history. Plain text, short sections, at most 25 lines, no markdown tables.";
        public string AiPrompt(IList<KeystoneSessionWhatIf> test, DateTime testFrom, DateTime testTo)
        {
            var sb = new StringBuilder();
            sb.AppendLine("ENTRY INDICATOR"); sb.AppendLine(Describe());
            sb.AppendLine("choices checked on the later half of the training days: " + Variants);
            sb.AppendLine("RULES (state → sides • trades • win rate • trading $):");
            foreach (var r in Rules) sb.AppendLine("- " + StateName(r.Key, Window) + " → " + KeystoneSimRotation.SidesName(r.DirM, r.DirG) + " • " + r.Trades + " • " + r.WinPct.ToString("0.0", CultureInfo.InvariantCulture) + "% • $" + r.Pnl.ToString("0", CultureInfo.InvariantCulture));
            if (Rules.Count == 0) sb.AppendLine("- none: no state beat the coin flip by the minimum edge");
            if (test != null && test.Count > 0)
            {
                sb.AppendLine("TEST ON THE RUN'S DAYS " + testFrom.ToString("yyyy-MM-dd") + " → " + testTo.ToString("yyyy-MM-dd") + (testFrom <= TrainTo && testTo >= TrainFrom ? " (WARNING: overlaps the training days)" : " (never seen in training)") + " — whole prop runs with the same accounts and rules:");
                foreach (var t in test) sb.AppendLine("- " + t.Name + ": trades " + t.Trades + ", won " + t.WinPct.ToString("0", CultureInfo.InvariantCulture) + "%, passed " + t.Passed + "/" + t.Bought + ", payouts " + t.Payouts + ", net $" + t.Net.ToString("0", CultureInfo.InvariantCulture) + ", ROI " + t.Roi.ToString("0", CultureInfo.InvariantCulture) + "%");
            }
            else sb.AppendLine("No test on unseen days has been run yet.");
            sb.AppendLine("Review it.");
            return sb.ToString();
        }
    }

    // one row of ⚖ COMPARE SESSIONS: a whole prop run of the rotation in one session window
    // THE MONEY ROAD of a prop run, from its days and accounts: the most money out of pocket at once (the budget it really
    // needed), the longest runs of losing / winning days for your bank (eval fees out vs payouts in), the longest wait without
    // a payout, and the payout cycle (bought → passed → first payout)
    public sealed class KeystoneSimRoad
    {
        public double MaxBudget; public DateTime MaxBudgetDay = DateTime.MinValue;   // the deepest point of payouts − spent (as a positive amount)
        public int LoseDays, WinDays, NoPayoutDays; public double LoseAmount, WinAmount; public DateTime LoseFrom, LoseTo, WinFrom, WinTo, NoPayFrom, NoPayTo;
        public int MonthsUp, MonthsDown, PaidAccounts, FundedAccounts, Finished; public double AvgDaysToPass = double.NaN, AvgDaysToFirstPay = double.NaN, AvgPayout = double.NaN, PaidPerFunded = double.NaN;
        public double SpentBeforeFirstPay; public int EvalsBeforeFirstPay;
        public int BufferMade, BlownBeforeBuffer; public double AvgDaysToBuffer = double.NaN;   // funded: the trailing buffer made (floor locked at the start) / blown before it
        public static KeystoneSimRoad Of(KeystonePropSim sim)
        {
            var o = new KeystoneSimRoad(); if (sim == null) return o;
            double prev = 0; int run = 0; double runAmt = 0; DateTime runFrom = DateTime.MinValue;   // run > 0 winning days, < 0 losing days (a flat day keeps the run)
            DateTime lastPay = DateTime.MinValue; int noPay = 0; var months = new SortedDictionary<string, double>();
            for (int i = 0; i < sim.Days.Count; i++)
            {
                var d = sim.Days[i]; double net = d.CumCash - d.CumSpent, ch = net - prev; prev = net;
                if (-net > o.MaxBudget + 1e-9) { o.MaxBudget = -net; o.MaxBudgetDay = d.Day; }
                string mk = d.Day.ToString("yyyy-MM", CultureInfo.InvariantCulture); double mv; months.TryGetValue(mk, out mv); months[mk] = mv + ch;
                int sg = ch > 1e-9 ? 1 : ch < -1e-9 ? -1 : 0;
                if (sg != 0)
                {
                    if (run == 0 || Math.Sign(run) != sg) { run = 0; runAmt = 0; runFrom = d.Day; }
                    run += sg; runAmt += ch;
                    if (run < 0 && -run > o.LoseDays) { o.LoseDays = -run; o.LoseAmount = runAmt; o.LoseFrom = runFrom; o.LoseTo = d.Day; }
                    if (run > 0 && run > o.WinDays) { o.WinDays = run; o.WinAmount = runAmt; o.WinFrom = runFrom; o.WinTo = d.Day; }
                }
                if (d.Payouts > 0) { lastPay = d.Day; noPay = 0; }
                else if (++noPay > o.NoPayoutDays) { o.NoPayoutDays = noPay; o.NoPayFrom = lastPay == DateTime.MinValue ? sim.Days[0].Day : lastPay; o.NoPayTo = d.Day; }
                if (d.CumCash <= 0) o.SpentBeforeFirstPay = d.CumSpent;
            }
            foreach (var m in months.Values) { if (m > 1e-9) o.MonthsUp++; else if (m < -1e-9) o.MonthsDown++; }
            int fp = KeystoneSessionWhatIf.FirstPayout(sim); if (fp > 0) { var fd = sim.Days[fp - 1].Day; o.EvalsBeforeFirstPay = sim.Accounts.Count(a => a.Bought != DateTime.MinValue && a.Bought <= fd); o.SpentBeforeFirstPay = fp > 1 ? sim.Days[fp - 2].CumSpent : 0; }
            else if (sim.Days.Count > 0) o.EvalsBeforeFirstPay = sim.Accounts.Count;
            var passed = sim.Accounts.Where(a => a.PassedOn != DateTime.MinValue && a.Bought != DateTime.MinValue).ToList();
            o.FundedAccounts = passed.Count; o.PaidAccounts = sim.Accounts.Count(a => a.Payouts > 0); o.Finished = sim.Accounts.Count(a => !a.Alive || a.PassedOn != DateTime.MinValue);
            if (passed.Count > 0) o.AvgDaysToPass = passed.Average(a => sim.Days.Count(x => x.Day >= a.Bought.Date && x.Day <= a.PassedOn.Date));
            var firstPay = sim.Events.Where(e => e.Kind == "PAYOUT").GroupBy(e => e.Account).ToDictionary(g => g.Key, g => g.Min(e => e.Time));
            var cyc = passed.Where(a => firstPay.ContainsKey(a.Id)).Select(a => (double)sim.Days.Count(x => x.Day > a.PassedOn.Date && x.Day <= firstPay[a.Id].Date)).ToList();
            if (cyc.Count > 0) o.AvgDaysToFirstPay = cyc.Average();
            var fundedEver = sim.Accounts.Where(a => a.PassedOn != DateTime.MinValue).ToList();
            o.BufferMade = fundedEver.Count(a => a.BufferOn != DateTime.MinValue); o.BlownBeforeBuffer = fundedEver.Count(a => a.Phase == "BLOWN" && a.BufferOn == DateTime.MinValue);
            var bd = fundedEver.Where(a => a.BufferOn != DateTime.MinValue).Select(a => (double)sim.Days.Count(x => x.Day > a.PassedOn.Date && x.Day <= a.BufferOn.Date)).ToList(); if (bd.Count > 0) o.AvgDaysToBuffer = bd.Average();
            int nPay = sim.Accounts.Sum(a => a.Payouts); double cash = sim.Accounts.Sum(a => a.Cash);
            if (nPay > 0) o.AvgPayout = cash / nPay; if (passed.Count > 0) o.PaidPerFunded = cash / passed.Count;
            return o;
        }
    }
    public sealed class KeystoneSessionWhatIf
    {
        public string Name = string.Empty; public int Start, End; public bool Mine;
        public int Days, AcctDays, AtTarget, Trades, Wins, Bought, Passed, BlownEval, BlownFunded, Payouts;
        public double PassRate, Pnl, Cash, Spent, Net, AvgPassDays, BestDay, WorstDay, MaxDrop;
        public int FirstPayoutDay = -1, BreakevenDay = -1, Accounts;   // trading days until the first payout / until payouts ≥ all spent (−1 = never)
        public double Roi { get { return Spent <= 0 ? 0 : 100.0 * Net / Spent; } }
        public List<double> Curve = new List<double>();   // net money (payouts − evaluations) after each day
        public double AtTargetPct { get { return AcctDays == 0 ? 0 : 100.0 * AtTarget / AcctDays; } }
        public double WinPct { get { return Trades == 0 ? 0 : 100.0 * Wins / Trades; } }
        public static KeystoneSessionWhatIf Of(string name, int start, int end, KeystonePropSim sim)
        {
            var r = new KeystoneSessionWhatIf { Name = name, Start = start, End = end, Days = sim.Days.Count, Trades = sim.Trades.Count, Wins = sim.Trades.Count(t => t.Pnl > 0), Bought = sim.Bought, Passed = sim.PassedCount, BlownEval = sim.BlownEval, BlownFunded = sim.BlownFunded, Payouts = sim.PayoutCount, PassRate = sim.PassRate, Pnl = sim.Trades.Sum(t => t.Pnl), Cash = sim.Cash, Spent = sim.Spent, Net = sim.Net };
            r.AcctDays = sim.Trades.Select(t => t.Day.ToString("yyyyMMdd") + "|" + t.Account).Distinct().Count(); r.AtTarget = KeystoneRotationLab.DaysAtTarget(sim);
            r.AvgPassDays = sim.Accounts.Where(a => a.PassedOn != DateTime.MinValue).Select(a => (double)a.EvalDays).DefaultIfEmpty(0).Average();
            r.BestDay = sim.Days.Select(d => d.Pnl).DefaultIfEmpty(0).Max(); r.WorstDay = sim.Days.Select(d => d.Pnl).DefaultIfEmpty(0).Min();
            double peak = 0; foreach (var d in sim.Days) { double v = d.CumCash - d.CumSpent; r.Curve.Add(v); peak = Math.Max(peak, v); r.MaxDrop = Math.Max(r.MaxDrop, peak - v); }
            r.Accounts = sim.S.Accounts; r.FirstPayoutDay = FirstPayout(sim); r.BreakevenDay = Breakeven(sim);
            return r;
        }
        public static int FirstPayout(KeystonePropSim sim) { for (int i = 0; i < sim.Days.Count; i++) if (sim.Days[i].CumCash > 0) return i + 1; return -1; }
        public static int Breakeven(KeystonePropSim sim) { for (int i = 0; i < sim.Days.Count; i++) if (sim.Days[i].CumCash > 0 && sim.Days[i].CumCash >= sim.Days[i].CumSpent) return i + 1; return -1; }
        static readonly string[] Fields = { "Name", "Start", "End", "Mine", "Days", "AcctDays", "AtTarget", "Trades", "Wins", "Bought", "Passed", "BlownEval", "BlownFunded", "Payouts", "PassRate", "Pnl", "Cash", "Spent", "Net", "AvgPassDays", "BestDay", "WorstDay", "MaxDrop" };
        public string Line()
        {
            var t = typeof(KeystoneSessionWhatIf); return string.Join("|", Fields.Select(f => KeystoneSimText.Value(t.GetField(f).GetValue(this)).Replace("|", "/"))) + "|" + string.Join(";", Curve.Select(v => Math.Round(v, 2).ToString(CultureInfo.InvariantCulture))) + "|" + FirstPayoutDay + "|" + BreakevenDay + "|" + Accounts;
        }
        public static KeystoneSessionWhatIf Parse(string line)
        {
            var a = (line ?? string.Empty).Split('|'); if (a.Length < Fields.Length) return null; var r = new KeystoneSessionWhatIf();
            for (int i = 0; i < Fields.Length; i++) KeystoneSimText.Set(r, Fields[i], a[i]);
            if (a.Length > Fields.Length) foreach (var v in a[Fields.Length].Split(new[] { ';' }, StringSplitOptions.RemoveEmptyEntries)) { double d; if (double.TryParse(v, NumberStyles.Float, CultureInfo.InvariantCulture, out d)) r.Curve.Add(d); }
            if (a.Length > Fields.Length + 3) { int x; if (int.TryParse(a[Fields.Length + 1], out x)) r.FirstPayoutDay = x; if (int.TryParse(a[Fields.Length + 2], out x)) r.BreakevenDay = x; if (int.TryParse(a[Fields.Length + 3], out x)) r.Accounts = x; }
            return r;
        }
        // saved with the run (Studio\PropSim\<run>\sessions.txt)
        public static void Save(string folder, IList<KeystoneSessionWhatIf> rows, string file = "sessions.txt") { try { if (!string.IsNullOrEmpty(folder)) { Directory.CreateDirectory(folder); File.WriteAllLines(Path.Combine(folder, file), rows.Select(r => r.Line()).ToArray()); } } catch { } }
        public static List<KeystoneSessionWhatIf> Load(string folder, string file = "sessions.txt")
        {
            try { string f = Path.Combine(folder ?? "", file); if (File.Exists(f)) return File.ReadAllLines(f).Select(Parse).Where(r => r != null).ToList(); } catch { }
            return new List<KeystoneSessionWhatIf>();
        }
    }

    // 📄 EXPORT HTML: one self-contained page of a prop simulation run (opens in any browser, nothing loaded from the internet)
    public static class KeystonePropSimReport
    {
        static string H(string t) { return System.Net.WebUtility.HtmlEncode(t ?? string.Empty); }
        static string M(double v) { return (v < 0 ? "−$" : "$") + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture); }
        static string S(double v) { return (v > 0 ? "+" : v < 0 ? "−" : "") + "$" + Math.Abs(v).ToString("N0", CultureInfo.InvariantCulture); }
        static string C(double v) { return v > 0 ? "up" : v < 0 ? "down" : "flat"; }
        static string P(double v) { return v.ToString("0", CultureInfo.InvariantCulture) + "%"; }
        static string Svg(IList<double> vals, int w, int h, string color)
        {
            if (vals == null || vals.Count < 2) return "";
            double lo = Math.Min(0, vals.Min()), hi = Math.Max(0, vals.Max()); if (hi - lo < 1) hi = lo + 1;
            Func<double, string> y = v => (6 + (hi - v) / (hi - lo) * (h - 12)).ToString("0.#", CultureInfo.InvariantCulture);
            var pts = string.Join(" ", vals.Select((v, i) => (4 + (w - 8.0) * i / (vals.Count - 1)).ToString("0.#", CultureInfo.InvariantCulture) + "," + y(v)));
            return "<svg viewBox='0 0 " + w + " " + h + "' preserveAspectRatio='none'><line x1='0' x2='" + w + "' y1='" + y(0) + "' y2='" + y(0) + "' class='zero'/><polyline points='" + pts + "' fill='none' stroke='" + color + "' stroke-width='2' vector-effect='non-scaling-stroke'/></svg>";
        }
        public static string Html(KeystonePropSim sim, IList<KeystoneSessionWhatIf> sessions)
        {
            var s = sim.S; var r = s.Rules; var b = new StringBuilder();
            string title = Path.GetFileName((sim.Folder ?? "").TrimEnd('\\', '/'));
            b.Append("<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Prop Simulation Report</title><style>");
            b.Append(":root{--bg:#0b0f17;--panel:#121a26;--card:#182233;--line:#24324a;--text:#e6edf6;--muted:#8796ab;--green:#22c55e;--red:#ef4444;--gold:#f5b942;--cyan:#22d3ee;--violet:#a78bfa;--orange:#fb923c}");
            b.Append("*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 'Segoe UI',system-ui,sans-serif}main{max-width:1240px;margin:0 auto;padding:24px 16px 60px}");
            b.Append("h1{font-size:26px;margin:0 0 4px;color:var(--gold)}h2{font-size:17px;margin:30px 0 10px;color:var(--cyan);letter-spacing:.04em}.sub{color:var(--muted);margin:2px 0}");
            b.Append(".kpis{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;margin-top:18px}.kpi{background:var(--card);border-radius:12px;padding:10px 14px;border-bottom:3px solid var(--line)}.kpi b{display:block;font:700 22px Consolas,monospace}.kpi span{color:var(--muted);font-size:11px;font-weight:700;letter-spacing:.05em}.kpi i{display:block;color:var(--muted);font-size:11px;font-style:normal}");
            b.Append(".up{color:var(--green)}.down{color:var(--red)}.flat{color:var(--muted)}.chart{background:var(--panel);border-radius:12px;padding:10px;height:190px}.chart svg{width:100%;height:100%}.zero{stroke:#4a5a72;stroke-dasharray:4 4}");
            b.Append(".wrap{overflow-x:auto;background:var(--panel);border-radius:12px}table{border-collapse:collapse;width:100%;font:12.5px Consolas,monospace}th{position:sticky;top:0;background:var(--card);color:var(--muted);font:700 11px 'Segoe UI',sans-serif;text-align:left;padding:8px 10px;letter-spacing:.04em}td{padding:6px 10px;border-top:1px solid var(--line);white-space:nowrap}tr.click{cursor:pointer}tr.click:hover td{background:#1b2638}");
            b.Append("tr.win td{background:rgba(34,197,94,.14);animation:pulse 1.4s ease-in-out infinite alternate}tr.win td:first-child{border-left:4px solid var(--green)}@keyframes pulse{from{background:rgba(34,197,94,.08)}to{background:rgba(34,197,94,.30)}}tr.mine td:first-child{color:var(--gold)}");
            b.Append("tr.more{display:none}tr.more.open{display:table-row}tr.more td{white-space:normal;background:#0f1622;color:var(--text);padding:12px 14px}.grid2{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:6px 18px}.grid2 div{display:flex;justify-content:space-between;border-bottom:1px dashed var(--line);padding:2px 0}.grid2 em{color:var(--muted);font-style:normal}");
            b.Append(".tag{display:inline-block;border-radius:8px;padding:1px 8px;font:700 11px 'Segoe UI';color:#fff}.EVAL{background:#0e7490}.FUNDED{background:#7c3aed}.BLOWN{background:#b91c1c}.RETIRED{background:#a16207}.note{color:var(--muted);font-size:12px;margin-top:8px}.winner{margin:8px 0 12px;padding:10px 14px;border-radius:12px;background:rgba(34,197,94,.12);border:1px solid var(--green)}");
            b.Append("</style></head><body><main>");
            b.Append("<h1>🏦 Prop Simulation Report</h1><p class='sub'>" + H(title) + " • made " + DateTime.Now.ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture) + (sim.Finished ? " • finished" : " • stopped at day " + Math.Min(sim.PlanIndex, sim.Plan.Count) + " of " + sim.Plan.Count) + "</p>");
            b.Append("<p class='sub'>" + H(s.Describe()) + "</p><p class='sub'>" + H(r.Describe()) + "</p>");
            Action<string, string, string, string> kpi = (cap, val, cls, sub) => b.Append("<div class='kpi'><span>" + H(cap) + "</span><b class='" + cls + "'>" + H(val) + "</b>" + (sub != "" ? "<i>" + H(sub) + "</i>" : "") + "</div>");
            b.Append("<div class='kpis'>");
            kpi("DAYS", sim.Days.Count.ToString(), "", sim.Days.Count > 0 ? sim.Days[0].Day.ToString("yyyy-MM-dd") + " → " + sim.Days[sim.Days.Count - 1].Day.ToString("yyyy-MM-dd") : "");
            kpi("EVALUATIONS BOUGHT", sim.Bought.ToString(), "", M(r.EvalCost) + " each");
            kpi("PASSED", sim.PassedCount.ToString(), "up", P(sim.PassRate) + " of the finished");
            kpi("BLOWN", (sim.BlownEval + sim.BlownFunded).ToString(), "down", sim.BlownEval + " eval • " + sim.BlownFunded + " funded");
            kpi("PAYOUTS", sim.PayoutCount.ToString(), "up", M(sim.Cash) + " to you");
            kpi("SPENT", M(sim.Spent), "", "evaluations + activations");
            kpi("NET", S(sim.Net), C(sim.Net), sim.Bought > 0 ? S(sim.Net / sim.Bought) + " per evaluation" : "");
            if (s.Strategy == "ROTATION") { int ad = sim.Trades.Select(t => t.Day.ToString("yyyyMMdd") + "|" + t.Account).Distinct().Count(), at = KeystoneRotationLab.DaysAtTarget(sim); kpi("ACCOUNT-DAYS AT TARGET", at + " / " + ad, at > 0 ? "up" : "flat", ad > 0 ? P(100.0 * at / ad) + " of the days traded" : ""); }
            kpi("TRADES • WON", sim.Trades.Count + " • " + (sim.Trades.Count == 0 ? "0%" : P(100.0 * sim.Trades.Count(t => t.Pnl > 0) / sim.Trades.Count)), "", S(sim.Trades.Sum(t => t.Pnl)) + " traded");
            b.Append("</div>");
            if (sim.Days.Count >= 2)
            {
                var net = sim.Days.Select(d => d.CumCash - d.CumSpent).ToList(); var pnl = new List<double>(); double run = 0; foreach (var d in sim.Days) { run += d.Pnl; pnl.Add(run); }
                b.Append("<h2>NET MONEY • payouts received − evaluations bought</h2><div class='chart'>" + Svg(net, 1000, 170, net[net.Count - 1] >= 0 ? "#22c55e" : "#ef4444") + "</div>");
                b.Append("<h2>TRADING P/L • all accounts together</h2><div class='chart'>" + Svg(pnl, 1000, 170, "#22d3ee") + "</div>");
            }
            if (sessions != null && sessions.Count > 0)
            {
                var win = KeystoneRotationLab.Winner(sessions);
                b.Append("<h2>⚖ WHAT IF: THE SAME DAYS IN EVERY SESSION</h2><div class='winner'>WINNER: <b class='up'>" + H(win.Name) + "</b> • net " + S(win.Net) + " • passed " + win.Passed + " of " + win.Bought + " (" + P(win.PassRate) + ") • " + win.AtTarget + " account-days at the day target</div>");
                b.Append("<div class='wrap'><table><tr><th>SESSION</th><th>DAYS AT TARGET</th><th>TRADES • WON</th><th>PASSED</th><th>BLOWN</th><th>PAYOUTS</th><th>NET</th><th>DAYS TO PASS</th></tr>");
                int k = 0;
                foreach (var x in sessions)
                {
                    string cls = "click" + (x == win ? " win" : "") + (x.Mine ? " mine" : "");
                    b.Append("<tr class='" + cls + "' onclick=\"document.getElementById('d" + k + "').classList.toggle('open')\"><td>" + (x.Mine ? "▶ " : "") + H(x.Name) + (x == win ? " ★" : "") + "</td><td>" + x.AtTarget + " / " + x.AcctDays + " (" + P(x.AtTargetPct) + ")</td><td>" + x.Trades + " • " + P(x.WinPct) + "</td><td>" + x.Passed + " / " + x.Bought + " (" + P(x.PassRate) + ")</td><td>" + (x.BlownEval + x.BlownFunded) + "</td><td>" + x.Payouts + " • " + M(x.Cash) + "</td><td class='" + C(x.Net) + "'>" + S(x.Net) + "</td><td>" + (x.Passed > 0 ? x.AvgPassDays.ToString("0.0", CultureInfo.InvariantCulture) : "—") + "</td></tr>");
                    b.Append("<tr class='more' id='d" + k + "'><td colspan='8'><div class='grid2'>");
                    foreach (var kv in new[] { Tuple.Create("hours (NY)", KeystoneBracket.Hm(x.Start) + " – " + KeystoneBracket.Hm(x.End)), Tuple.Create("days", x.Days.ToString()), Tuple.Create("account-days traded", x.AcctDays.ToString()), Tuple.Create("account-days at the day target", x.AtTarget + " (" + P(x.AtTargetPct) + ")"), Tuple.Create("trades • won", x.Trades + " • " + x.Wins), Tuple.Create("trading P/L", S(x.Pnl)), Tuple.Create("best day • worst day", S(x.BestDay) + " • " + S(x.WorstDay)), Tuple.Create("evaluations bought", x.Bought.ToString()), Tuple.Create("passed • pass rate", x.Passed + " • " + P(x.PassRate)), Tuple.Create("blown eval • funded", x.BlownEval + " • " + x.BlownFunded), Tuple.Create("payouts • to you", x.Payouts + " • " + M(x.Cash)), Tuple.Create("spent", M(x.Spent)), Tuple.Create("net", S(x.Net)), Tuple.Create("deepest drop of the net", M(x.MaxDrop)), Tuple.Create("average days to pass", x.Passed > 0 ? x.AvgPassDays.ToString("0.0", CultureInfo.InvariantCulture) : "—") })
                        b.Append("<div><em>" + H(kv.Item1) + "</em><span>" + H(kv.Item2) + "</span></div>");
                    b.Append("</div>" + (x.Curve.Count >= 2 ? "<div class='chart' style='height:120px;margin-top:10px'>" + Svg(x.Curve, 1000, 110, x.Net >= 0 ? "#22c55e" : "#ef4444") + "</div>" : "") + "</td></tr>");
                    k++;
                }
                b.Append("</table></div><p class='note'>Every row: the same days, accounts, sizes, $ target / stop and day plan, traded only inside that session (close all at its end) on 1-minute bars: the stop is checked first with both legs at their worst of the minute, targets at a minute's close, costs per contract. Click a row for all its numbers. Your replay run (second by second) can differ a little from the ▶ row.</p>");
            }
            b.Append("<h2>ACCOUNTS</h2><div class='wrap'><table><tr><th>ACCOUNT</th><th>NOW</th><th>BOUGHT</th><th>PASSED</th><th>ENDED</th><th>EVAL • FUNDED DAYS</th><th>TRADES • WON</th><th>BALANCE</th><th>PAYOUTS</th><th>SPENT</th><th>RECEIVED</th><th>NET</th></tr>");
            Func<DateTime, string> dt = d => d == DateTime.MinValue ? "—" : d.ToString("yyyy-MM-dd");
            foreach (var a in sim.Accounts.OrderBy(x => x.Id))
                b.Append("<tr><td>" + H(a.Name) + "</td><td><span class='tag " + H(a.Phase) + "'>" + H(a.Phase) + "</span> " + H(a.Alive ? "" : a.EndReason) + "</td><td>" + dt(a.Bought) + "</td><td>" + dt(a.PassedOn) + "</td><td>" + dt(a.Ended) + "</td><td>" + a.EvalDays + " • " + a.FundedDays + "</td><td>" + a.Trades + " • " + (a.Trades == 0 ? "0%" : P(100.0 * a.Wins / a.Trades)) + "</td><td class='" + C(a.Bal) + "'>" + S(a.Bal) + "</td><td>" + a.Payouts + "</td><td>" + M(a.Spent) + "</td><td>" + M(a.Cash) + "</td><td class='" + C(a.Net) + "'>" + S(a.Net) + "</td></tr>");
            b.Append("</table></div>");
            b.Append("<h2>EVERY DAY</h2><div class='wrap'><table><tr><th>DAY</th><th>TRADES • WON</th><th>P/L</th><th>BOUGHT</th><th>PASSED</th><th>BLOWN E / F</th><th>PAYOUTS</th><th>SPENT</th><th>RECEIVED</th><th>NET SO FAR</th><th>EVAL • FUNDED</th></tr>");
            foreach (var d in sim.Days) b.Append("<tr><td>" + d.Day.ToString("ddd yyyy-MM-dd", CultureInfo.InvariantCulture) + "</td><td>" + d.Trades + " • " + d.Wins + "</td><td class='" + C(d.Pnl) + "'>" + S(d.Pnl) + "</td><td>" + d.Bought + "</td><td>" + d.Passed + "</td><td>" + d.Blown + " / " + d.FundedBlown + "</td><td>" + d.Payouts + "</td><td>" + M(d.Spent) + "</td><td>" + M(d.Cash) + "</td><td class='" + C(d.CumCash - d.CumSpent) + "'>" + S(d.CumCash - d.CumSpent) + "</td><td>" + d.EvalActive + " • " + d.FundedActive + "</td></tr>");
            b.Append("</table></div>");
            var pays = sim.Events.Where(e => e.Kind == "PAYOUT").ToList();
            if (pays.Count > 0) { b.Append("<h2>PAYOUTS</h2><div class='wrap'><table><tr><th>DATE</th><th>ACCOUNT</th><th>TO YOU</th><th>DETAIL</th></tr>"); foreach (var e in pays) b.Append("<tr><td>" + e.Time.ToString("yyyy-MM-dd") + "</td><td>A" + e.Account.ToString("00") + "</td><td class='up'>" + M(e.Amount) + "</td><td>" + H(e.Text) + "</td></tr>"); b.Append("</table></div>"); }
            const int maxTrades = 3000;
            b.Append("<h2>TRADES (" + sim.Trades.Count + ")</h2><div class='wrap' style='max-height:640px'><table><tr><th>DAY</th><th>ACCOUNT</th><th>PHASE</th><th>IN</th><th>OUT</th><th>SIDES</th><th>NET</th><th>WHY</th><th>BY</th></tr>");
            foreach (var t in sim.Trades.Take(maxTrades)) b.Append("<tr><td>" + t.Day.ToString("yyyy-MM-dd") + "</td><td>A" + t.Account.ToString("00") + "</td><td>" + H(t.Phase) + "</td><td>" + t.Entry.ToString("HH:mm:ss") + "</td><td>" + t.Exit.ToString("HH:mm:ss") + "</td><td>" + H(t.Legs == "" ? (t.Dir > 0 ? "BUY" : "SELL") : t.Legs) + "</td><td class='" + C(t.Pnl) + "'>" + S(t.Pnl) + "</td><td>" + H(t.Reason) + "</td><td>" + H(t.Source) + "</td></tr>");
            b.Append("</table></div>" + (sim.Trades.Count > maxTrades ? "<p class='note'>The first " + maxTrades + " trades are shown; all of them are in trades.csv in the run's folder.</p>" : ""));
            b.Append("<p class='note'>A simulation on historical 1-minute data with the firm rules above: not a promise of future results. Every number comes from the run saved in " + H(title) + ".</p>");
            b.Append("</main></body></html>");
            return b.ToString();
        }
    }

