    // ⚖ DRAWDOWN LAB (user's request): the SAME trades on simulated prop accounts with a TRAILING drawdown (the floor follows the
    // highest equity — open profit included — every tick, so every pull-back from a new peak is buffer lost for good) and an
    // END-OF-DAY drawdown (the floor moves only at the day's close, from the closing balance). Simulation only: it never places an order.
    public sealed class KeystoneDdPoint { public DateTime Time; public double Equity, Peak, Floor; }
    // one finished trade of a lab account: open → close, its best / worst moment, the lowest buffer it left, how it ended
    public sealed class KeystoneDdTrade { public string Account = "", Kind = "", Symbol = "", Why = ""; public DateTime Open, Close; public int Qty; public double Entry, Exit, Pnl, BestOpen, WorstOpen, PeakEquity, MaxDdFromPeak, MinBuffer, FloorAtClose; }
    public sealed class KeystoneDdAccount
    {
        public string Name = "", Kind = "TRAILING", Symbol = "MGC"; public int Dir = 1, Qty = 1;
        public double Start = 50000, MaxDd = 2000, Target = 3000, TakeProfit = 0, StopLoss = 0, LockAt = 0;   // LockAt > 0: the floor never rises above it (e.g. the start balance)
        public int Pos; public double Avg, Realized, Peak, Floor, LastPx = double.NaN, LastRaise; public bool Blown, Passed; public DateTime RaisedAt = DateTime.MinValue, BlownAt = DateTime.MinValue; public string Note = "";
        public readonly List<KeystoneDdPoint> History = new List<KeystoneDdPoint>(); public readonly List<string> Log = new List<string>();
        public readonly List<KeystoneDdTrade> Trades = new List<KeystoneDdTrade>(); KeystoneDdTrade cur;   // the trade in progress (from flat to flat)
        public double MaxDdFromPeak, MinBuffer = double.MaxValue;   // the account's deepest drop from its highest equity, its lowest buffer
        void TradeOpened(DateTime t, int qty, double px) { cur = new KeystoneDdTrade { Account = Name, Kind = Kind, Symbol = Symbol, Open = t, Qty = qty, Entry = px, BestOpen = 0, WorstOpen = 0, MinBuffer = double.MaxValue }; }
        void TradeClosed(DateTime t, double px, string why) { if (cur == null) return; cur.Close = t; cur.Exit = px; cur.Pnl = Realized - realizedAtOpen; cur.Why = why; cur.FloorAtClose = Floor; cur.PeakEquity = Peak; Trades.Add(cur); cur = null; }
        double realizedAtOpen;
        public double PointValue { get { return Symbol.StartsWith("MGC", StringComparison.OrdinalIgnoreCase) ? 10 : Symbol.StartsWith("MNQ", StringComparison.OrdinalIgnoreCase) ? 2 : Symbol.StartsWith("NQ", StringComparison.OrdinalIgnoreCase) ? 20 : Symbol.StartsWith("GC", StringComparison.OrdinalIgnoreCase) ? 100 : 1; } }
        public bool Trailing { get { return Kind == "TRAILING"; } }
        public void Reset() { Pos = 0; Avg = 0; Realized = 0; Peak = Start; Floor = CapFloor(Start - MaxDd); Blown = Passed = false; LastRaise = 0; RaisedAt = BlownAt = DateTime.MinValue; History.Clear(); Log.Clear(); Note = ""; Trades.Clear(); cur = null; MaxDdFromPeak = 0; MinBuffer = double.MaxValue; }
        double CapFloor(double f) { return LockAt > 0 ? Math.Min(f, LockAt) : f; }
        public double Open(double px) { return Pos == 0 || double.IsNaN(px) ? 0 : Pos * (px - Avg) * PointValue; }
        public double Equity(double px) { return Start + Realized + Open(px); }
        public double Buffer(double px) { return Equity(px) - Floor; }
        public double Profit(double px) { return Realized + Open(px); }
        void Say(DateTime t, string s) { Log.Add(t.ToString("HH:mm:ss", CultureInfo.InvariantCulture) + "  " + s); if (Log.Count > 300) Log.RemoveAt(0); }
        // a market order (simulated, filled at px): +qty buys, −qty sells; reverses through zero
        public void Trade(DateTime t, int qty, double px)
        {
            if (Blown || qty == 0 || double.IsNaN(px)) return; int np = Pos + qty; if (Pos == 0) { realizedAtOpen = Realized; TradeOpened(t, qty, px); }
            if (Pos == 0 || Math.Sign(Pos) == Math.Sign(qty)) { Avg = (Avg * Math.Abs(Pos) + px * Math.Abs(qty)) / Math.Abs(np); Pos = np; }
            else
            {
                int closing = Math.Min(Math.Abs(qty), Math.Abs(Pos)); Realized += Math.Sign(Pos) * closing * (px - Avg) * PointValue; Pos += Math.Sign(qty) * closing;
                int rest = Math.Abs(qty) - closing; if (Pos == 0) TradeClosed(t, px, rest > 0 ? "reversed" : "closed by an opposite order"); if (rest > 0) { Pos = Math.Sign(qty) * rest; Avg = px; realizedAtOpen = Realized; TradeOpened(t, Pos, px); } else if (Pos == 0) Avg = 0;
            }
            Say(t, (qty > 0 ? "BUY " : "SELL ") + Math.Abs(qty) + " @ " + px.ToString("0.00", CultureInfo.InvariantCulture) + " → position " + Pos); Mark(t, px);
        }
        public void Close(DateTime t, double px, string why) { if (Pos == 0 || double.IsNaN(px)) return; double pl = Open(px); Realized += pl; Say(t, "CLOSE " + Pos + " @ " + px.ToString("0.00", CultureInfo.InvariantCulture) + " " + (pl >= 0 ? "+" : "−") + "$" + Math.Abs(pl).ToString("N0", CultureInfo.InvariantCulture) + (why != "" ? " (" + why + ")" : "")); Pos = 0; Avg = 0; TradeClosed(t, px, why == "" ? "closed" : why); Mark(t, px); }
        // every price: the peak and the TRAILING floor follow the equity; the take profit / stop of the open trade; the floor breached = blown
        public void Mark(DateTime t, double px)
        {
            if (double.IsNaN(px)) return; LastPx = px; if (Blown) return;
            double eq = Equity(px);
            if (cur != null) { double op = Open(px); cur.BestOpen = Math.Max(cur.BestOpen, op); cur.WorstOpen = Math.Min(cur.WorstOpen, op); }
            if (Trailing && eq > Peak)
            {
                Peak = eq; double nf = CapFloor(Peak - MaxDd);
                if (nf > Floor + 0.004) { LastRaise = nf - Floor; Floor = nf; RaisedAt = t; }
            }
            if (Pos != 0 && TakeProfit > 0 && Open(px) >= TakeProfit) { Close(t, px, "take profit"); return; }
            if (Pos != 0 && StopLoss > 0 && Open(px) <= -StopLoss) { Close(t, px, "stop loss"); return; }
            if (!Passed && Target > 0 && eq - Start >= Target) { Passed = true; Say(t, "🏆 TARGET +$" + Target.ToString("N0", CultureInfo.InvariantCulture) + " reached"); }
            double bufNow = Equity(px) - Floor; MinBuffer = Math.Min(MinBuffer, bufNow); MaxDdFromPeak = Math.Max(MaxDdFromPeak, Math.Max(Peak, eq) - eq);
            if (cur != null) { cur.MinBuffer = Math.Min(cur.MinBuffer, bufNow); cur.MaxDdFromPeak = Math.Max(cur.MaxDdFromPeak, Math.Max(Peak, eq) - eq); }
            if (eq <= Floor + 0.004)
            {
                if (Pos != 0) { double pl = Open(px); Realized += pl; Pos = 0; Avg = 0; TradeClosed(t, px, "💀 blown"); }
                Blown = true; BlownAt = t; Say(t, "💀 BLOWN — equity $" + eq.ToString("N0", CultureInfo.InvariantCulture) + " touched the " + (Trailing ? "trailing" : "EOD") + " floor $" + Floor.ToString("N0", CultureInfo.InvariantCulture));
            }
            if (History.Count == 0 || (t - History[History.Count - 1].Time).TotalSeconds >= 1 || Blown) { History.Add(new KeystoneDdPoint { Time = t, Equity = eq, Peak = Trailing ? Peak : Math.Max(Peak, eq), Floor = Floor }); if (History.Count > 4000) History.RemoveRange(0, 1000); }
        }
        // the day's close: an EOD account's floor moves up from the closing equity (a trailing account already followed it)
        public void EndOfDay(DateTime t, double px)
        {
            if (Blown || Trailing) return; double eq = Equity(px); if (eq > Peak) Peak = eq; double nf = CapFloor(Peak - MaxDd);
            if (nf > Floor + 0.004) { LastRaise = nf - Floor; Floor = nf; RaisedAt = t; Say(t, "END OF DAY: closed at $" + eq.ToString("N0", CultureInfo.InvariantCulture) + " → the floor rises to $" + Floor.ToString("N0", CultureInfo.InvariantCulture)); }
            else Say(t, "END OF DAY: closed at $" + eq.ToString("N0", CultureInfo.InvariantCulture) + " → the floor stays $" + Floor.ToString("N0", CultureInfo.InvariantCulture));
        }
    }
    // ==== BUILD 2026-11-11c (phase C) — the pure pieces behind the new screens (tests/fullcompile/UiSmokeTest.cs pins them) ====
    // 📅 DATE PICKING (items 18 / 28 / 29): the quick ranges (a day, a week, a month, a quarter, a year, the last 1 / 3 / 6 / 12 months, all 6 years) and the
    // tick boxes (years "Y2025", months "M2026-09", weeks "W2026-09-07" = its Monday, days "D2026-09-01") → contiguous ticks = ONE range, ticks apart =
    // separate periods (each run on its own, shown per period + combined) • the summary line lists what was picked ("2025 + 2026 · 470 trading days")
        // 🏷 item 37: the chart's trade labels live in a reserved RIGHT GUTTER (like TradingView's order labels): Stack nudges the wanted y's apart (min gap,
    // inside top..bottom, order kept); Intersects = a label rectangle against the candle area (the smoke test: none may)
    public static class KeystoneChartGutter
    {
        public static List<double> Stack(IList<double> wanted, double gap, double top, double bottom)
        {
            var n = wanted == null ? 0 : wanted.Count; var o = new double[n]; if (n == 0) return new List<double>();
            var idx = Enumerable.Range(0, n).OrderBy(i => wanted[i]).ToList(); double prev = double.MinValue;
            foreach (var i in idx) { double y = Math.Max(top + gap / 2, Math.Min(bottom, wanted[i])); if (y < prev + gap) y = prev + gap; o[i] = y; prev = y; }
            double over = prev - bottom; if (over > 0) foreach (var i in idx) o[i] -= over;   /* pushed past the bottom: shift the stack up */
            return o.ToList();
        }
        public static bool Intersects(double x, double y, double w, double h, double ax, double ay, double aw, double ah) { return x < ax + aw && ax < x + w && y < ay + ah && ay < y + h; }
        /* 💵 BUILD 11f (the user: "I don't see dollar amounts on the orders"): the Backtest Studio's order labels put the DOLLARS FIRST and stay short ("TP +$1,025",
           "SL −$150", "LONG 25 • +$450"); the points / the price go on the tooltip (after "\n"). The gutter is sized to the widest label (min 170, max 240 px) and
           the ✕ / ⇕ handles keep their own Handle px — a number is never cut. TextWidth is a safe estimate (the real build also measures the label and takes the larger) */
        public const double Min = 170, Max = 240, Handle = 34;
        static readonly CultureInfo IC = CultureInfo.InvariantCulture;
        public static string Usd(double v, bool plus) { return (v < 0 ? "−$" : plus ? "+$" : "$") + Math.Abs(Math.Round(v)).ToString("N0", IC); }
        public static string Tp(double pts, double pv, int qty) { return "TP " + Usd(Math.Abs(pts) * pv * Math.Max(1, qty), true); }
        public static string Sl(double pts, double pv, int qty) { return "SL " + Usd(-Math.Abs(pts) * pv * Math.Max(1, qty), false); }
        public static string Locked(double pts, double pv, int qty) { return "🔒 " + Usd(Math.Abs(pts) * pv * Math.Max(1, qty), true) + " locked"; }
        public static string Entry(int position, double openUsd) { return (position > 0 ? "LONG " : "SHORT ") + Math.Abs(position) + " • " + Usd(openUsd, true); }
        public static string Detail(double pts, double price, string fmtPrice) { return (pts >= 0 ? "+" : "−") + Math.Abs(pts).ToString("0.00", IC) + " pts · @ " + fmtPrice; }
        public static double TextWidth(string s, double fontSize)
        {
            double w = 0; foreach (char c in s ?? "") w += char.IsSurrogate(c) ? 0.62 * fontSize : c > 0x2000 ? 1.2 * fontSize : char.IsDigit(c) || c == '$' || c == '+' || c == '−' || c == '-' || c == '@' ? 0.64 * fontSize : char.IsUpper(c) ? 0.74 * fontSize : c == ' ' || c == '.' || c == ',' || c == ':' || c == '·' ? 0.34 * fontSize : 0.6 * fontSize;
            return w;
        }
        // the label box as drawn: a stop / target / order pill (the dot, the text at 10.5 bold, the ⇕, the padding) or the entry (the head at 12.5 + the $ at 14)
        public static double LabelWidth(string main, bool entry)
        {
            string m = (main ?? "").Replace("  (drag)", "").Split('\n')[0];
            if (entry && m.Contains(" • ")) { int k = m.LastIndexOf(" • "); return 22 + TextWidth(m.Substring(0, k) + "  ", 12.5) + TextWidth(m.Substring(k + 3), 14) + 4; }
            return 7 + 6 + TextWidth(m, 10.5) + TextWidth("  ⇕", 10.5) + 17 + 4;
        }
        // the gutter for these label widths: the widest + the handles, between Min and Max
        public static double Fit(IEnumerable<double> widths) { double mx = (widths ?? Enumerable.Empty<double>()).DefaultIfEmpty(0).Max(); return Math.Max(Min, Math.Min(Max, Math.Ceiling(mx + Handle + 4))); }
        public static bool Fits(string main, bool entry, double gutter) { return LabelWidth(main, entry) <= gutter - Handle + 1e-9; }
    }
    // ✋ BUILD 2026-11-11h (the user: "when we drag the TP / SL over the entry it skips and bugs"): ONE drag of the position's own TP / SL line, owned
    // from the first move to the release. While it is Active nothing else can be grabbed (Grab = the dragged kind, the entry is not interactive and fades
    // to EntryOpacity), the price follows the mouse rounded to the tick only (no snapping to other lines), a STOP is held 2 ticks short of the last price
    // (never an instant fill: Clamped + a note), Esc = Cancel (the old price stays, nothing sent), and Release hands the price over ONCE — the only moment
    // the real order changes (through the same armed link, limits and checks as before). Label = the live "TP 120.75 pts · +$242" (after costs),
    // LabelTop = where that label sits on the line so it never covers the entry's label (above, else below, else past the entry's label)
    public sealed class KeystoneBracketDrag
    {
        public string Kind { get; private set; }
        public bool Active { get { return Kind != null; } }
        public double OrigPrice { get; private set; }
        public double Price { get; private set; }
        public bool Clamped { get; private set; }
        public int Commits { get; private set; }
        public bool EntryInteractive { get { return !Active; } }
        public double EntryOpacity { get { return Active ? 0.3 : 1.0; } }
        public const double FadedOpacity = 0.3;
        public void Begin(string kind, double origPrice) { Kind = kind == "STOP" || kind == "TARGET" ? kind : null; OrigPrice = origPrice; Price = 0; Clamped = false; }
        /* what a click / hover may grab: during a drag only the dragged line — never the entry, the other bracket line or any level */
        public string Grab(string candidate) { return Active ? Kind : candidate; }
        public double Move(double rawPrice, double tick, int side, double lastPrice)
        {
            if (!Active || tick <= 0 || double.IsNaN(rawPrice)) return Price;
            double p = Math.Round(Math.Round(rawPrice / tick) * tick, 8); Clamped = false;
            if (Kind == "STOP" && side != 0 && lastPrice > 0)
            {
                double lim = Math.Round(lastPrice - side * 2 * tick, 8);
                if (side * (p - lim) > 0) { p = lim; Clamped = true; }
            }
            Price = p; return p;
        }
        /* the mouse is released: the price to place (once), NaN = nothing to place */
        public double Release() { if (!Active) return double.NaN; Kind = null; double p = Price; Price = 0; Clamped = false; if (p <= 0) return double.NaN; Commits++; return p; }
        /* Esc: the drag ends, nothing is placed — the line stays at OrigPrice */
        public double Cancel() { Kind = null; Price = 0; Clamped = false; return OrigPrice; }
        public static double Points(double entry, double price) { return Math.Abs(price - entry); }
        public static double NetUsd(string kind, int side, double entry, double price, double pointValue, int qty, double costPerContract)
        {
            int q = Math.Abs(qty); double gross = side * (price - entry) * pointValue * q;
            return gross - costPerContract * q;
        }
        public static string Usd(double v) { double a = Math.Abs(v); return (v >= 0 ? "+$" : "−$") + a.ToString(a >= 100 ? "N0" : "N2", CultureInfo.InvariantCulture); }
        public static string Label(string kind, int side, double entry, double price, double pointValue, int qty, double costPerContract)
        {
            double pts = Points(entry, price), net = NetUsd(kind, side, entry, price, pointValue, qty, costPerContract);
            bool profitStop = kind == "STOP" && side * (price - entry) > 0;
            return (kind == "STOP" ? (profitStop ? "SL 🔒" : "SL") : "TP") + " " + pts.ToString("0.00", CultureInfo.InvariantCulture) + " pts · " + Usd(net);
        }
        public static bool Overlaps(double a0, double a1, double b0, double b1) { return a0 < b1 && b0 < a1; }
        public static double LabelTop(double lineY, double labelH, double entryTop, double entryBottom, double top, double bottom)
        {
            Func<double, double> fit = y => Math.Max(top, Math.Min(bottom - labelH, y));
            double above = fit(lineY - labelH - 3); if (!Overlaps(above, above + labelH, entryTop, entryBottom)) return above;
            double below = fit(lineY + 3); if (!Overlaps(below, below + labelH, entryTop, entryBottom)) return below;
            double mid = (entryTop + entryBottom) / 2, past = lineY <= mid ? entryTop - labelH - 2 : entryBottom + 2;
            if (past < top || past + labelH > bottom) past = lineY <= mid ? entryBottom + 2 : entryTop - labelH - 2;
            return fit(past);
        }
    }
    public static class KeystoneDatePick
    {
        static readonly CultureInfo IC = CultureInfo.InvariantCulture;
        public static readonly string[] Quick = { "DAY", "WEEK", "MONTH", "QUARTER", "YEAR", "LAST 1 MONTH", "LAST 3 MONTHS", "LAST 6 MONTHS", "LAST 12 MONTHS", "ALL 6 YEARS" };
        public static bool Weekday(DateTime d) { return d.DayOfWeek != DayOfWeek.Saturday && d.DayOfWeek != DayOfWeek.Sunday; }
        public static int TradingDays(DateTime a, DateTime b) { int n = 0; for (var d = a.Date; d <= b.Date; d = d.AddDays(1)) if (Weekday(d)) n++; return n; }
        static DateTime NextWeekday(DateTime d) { d = d.Date.AddDays(1); while (!Weekday(d)) d = d.AddDays(1); return d; }
        public static Tuple<DateTime, DateTime> Clip(DateTime a, DateTime b, DateTime first, DateTime last)
        {
            a = a.Date; b = b.Date; if (first != DateTime.MinValue && a < first.Date) a = first.Date; if (last != DateTime.MinValue && b > last.Date) b = last.Date; if (b < a) b = a;
            while (!Weekday(a) && a < b) a = a.AddDays(1); while (!Weekday(b) && b > a) b = b.AddDays(-1); return Tuple.Create(a, b);
        }
        // a quick choice → [from, to]: DAY / WEEK / MONTH / QUARTER / YEAR around the anchor (the picked day or the START), LAST n MONTHS / ALL 6 YEARS up to the last saved day
        public static Tuple<DateTime, DateTime> Range(string kind, DateTime anchor, DateTime first, DateTime last)
        {
            anchor = anchor.Date; DateTime a = anchor, b = anchor; string k = (kind ?? "").Trim().ToUpperInvariant(); if (last == DateTime.MinValue) last = anchor;
            if (k == "WEEK") { a = anchor.AddDays(-(((int)anchor.DayOfWeek + 6) % 7)); b = a.AddDays(4); }
            else if (k == "MONTH") { a = new DateTime(anchor.Year, anchor.Month, 1); b = a.AddMonths(1).AddDays(-1); }
            else if (k == "QUARTER") { a = new DateTime(anchor.Year, (anchor.Month - 1) / 3 * 3 + 1, 1); b = a.AddMonths(3).AddDays(-1); }
            else if (k == "YEAR") { a = new DateTime(anchor.Year, 1, 1); b = new DateTime(anchor.Year, 12, 31); }
            else if (k.StartsWith("LAST ")) { int n; var w = k.Split(' '); if (w.Length < 2 || !int.TryParse(w[1], out n)) n = 1; b = last.Date; a = b.AddMonths(-Math.Max(1, n)).AddDays(1); }
            else if (k.StartsWith("ALL")) { b = last.Date; a = first != DateTime.MinValue ? first.Date : b.AddYears(-6); }
            return Clip(a, b, first, last);
        }
        // contiguous (no weekday between) or overlapping ranges merge into one; the rest stay separate periods
        public static List<Tuple<DateTime, DateTime>> Merge(IEnumerable<Tuple<DateTime, DateTime>> ranges)
        {
            var l = (ranges ?? new List<Tuple<DateTime, DateTime>>()).Where(r => r != null && r.Item2 >= r.Item1).OrderBy(r => r.Item1).ToList(); var o = new List<Tuple<DateTime, DateTime>>();
            foreach (var r in l)
            {
                if (o.Count > 0 && r.Item1 <= NextWeekday(o[o.Count - 1].Item2)) { var p = o[o.Count - 1]; o[o.Count - 1] = Tuple.Create(p.Item1, r.Item2 > p.Item2 ? r.Item2 : p.Item2); }
                else o.Add(Tuple.Create(r.Item1.Date, r.Item2.Date));
            }
            return o;
        }
        public static List<Tuple<DateTime, DateTime>> FromDays(IEnumerable<DateTime> days) { return Merge((days ?? new List<DateTime>()).Select(d => Tuple.Create(d.Date, d.Date))); }
        // a tick box → its range
        public static Tuple<DateTime, DateTime> OfTick(string tick)
        {
            string t = tick ?? ""; if (t.Length < 2) return null; string v = t.Substring(1); DateTime d;
            if (t[0] == 'Y') { int y; return int.TryParse(v, out y) ? Tuple.Create(new DateTime(y, 1, 1), new DateTime(y, 12, 31)) : null; }
            if (t[0] == 'M' && DateTime.TryParseExact(v, "yyyy-MM", IC, DateTimeStyles.None, out d)) return Tuple.Create(d, d.AddMonths(1).AddDays(-1));
            if (t[0] == 'W' && DateTime.TryParseExact(v, "yyyy-MM-dd", IC, DateTimeStyles.None, out d)) return Tuple.Create(d, d.AddDays(4));
            if (t[0] == 'D' && DateTime.TryParseExact(v, "yyyy-MM-dd", IC, DateTimeStyles.None, out d)) return Tuple.Create(d, d);
            return null;
        }
        public static string TickLabel(string tick)
        {
            var r = OfTick(tick); if (r == null) return tick ?? ""; char c = tick[0];
            return c == 'Y' ? r.Item1.Year.ToString(IC) : c == 'M' ? r.Item1.ToString("MMM yyyy", IC) : c == 'W' ? "week of " + r.Item1.ToString("d MMM yyyy", IC) : r.Item1.ToString("ddd d MMM yyyy", IC);
        }
        public static List<Tuple<DateTime, DateTime>> OfTicks(IEnumerable<string> ticks, DateTime first, DateTime last)
        {
            return Merge((ticks ?? new List<string>()).Select(OfTick).Where(r => r != null).Select(r => Clip(r.Item1, r.Item2, first, last)).Where(r => TradingDays(r.Item1, r.Item2) > 0));
        }
        // a range said in words: a whole year → "2025", whole years → "2025 – 2026", a whole month → "Sep 2026", one day, else "1 Sep 2026 → 3 Oct 2026"
        public static string Label(Tuple<DateTime, DateTime> r)
        {
            if (r == null) return ""; DateTime a = r.Item1.Date, b = r.Item2.Date;
            Func<DateTime, DateTime> wkF = d => { while (!Weekday(d)) d = d.AddDays(1); return d; }; Func<DateTime, DateTime> wkB = d => { while (!Weekday(d)) d = d.AddDays(-1); return d; };
            if (a == wkF(new DateTime(a.Year, 1, 1)) && b == wkB(new DateTime(b.Year, 12, 31))) return a.Year == b.Year ? a.Year.ToString(IC) : a.Year.ToString(IC) + " – " + b.Year.ToString(IC);
            if (a.Year == b.Year && a.Month == b.Month && a == wkF(new DateTime(a.Year, a.Month, 1)) && b == wkB(new DateTime(a.Year, a.Month, 1).AddMonths(1).AddDays(-1))) return a.ToString("MMM yyyy", IC);
            if (a == b) return a.ToString("ddd d MMM yyyy", IC);
            return a.ToString("d MMM yyyy", IC) + " → " + b.ToString("d MMM yyyy", IC);
        }
        public static string Summary(IList<Tuple<DateTime, DateTime>> periods, IList<string> picked)
        {
            var p = periods ?? new List<Tuple<DateTime, DateTime>>(); if (p.Count == 0) return "nothing picked";
            var words = picked != null && picked.Count > 0 ? picked.ToList() : p.Select(Label).ToList(); int n = p.Sum(x => TradingDays(x.Item1, x.Item2));
            return string.Join(" + ", words) + " · " + n + " trading day" + (n == 1 ? "" : "s") + (p.Count > 1 ? " · " + p.Count + " separate periods (each run on its own, shown per period + combined)" : "");
        }
        public static List<string> YearTicks(DateTime first, DateTime last) { var o = new List<string>(); if (last == DateTime.MinValue) return o; for (int y = last.Year; y >= (first == DateTime.MinValue ? last.Year - 6 : first.Year); y--) o.Add("Y" + y.ToString(IC)); return o; }
        public static List<string> MonthTicks(DateTime first, DateTime last, int max)
        {
            var o = new List<string>(); if (last == DateTime.MinValue) return o; var m = new DateTime(last.Year, last.Month, 1);
            while (o.Count < max && (first == DateTime.MinValue || m.AddMonths(1) > first)) { o.Add("M" + m.ToString("yyyy-MM", IC)); m = m.AddMonths(-1); }
            return o;
        }
        public static List<string> WeekTicks(DateTime last, int max)
        {
            var o = new List<string>(); if (last == DateTime.MinValue) return o; var w = last.Date.AddDays(-(((int)last.DayOfWeek + 6) % 7));
            for (int i = 0; i < max; i++) { o.Add("W" + w.ToString("yyyy-MM-dd", IC)); w = w.AddDays(-7); }
            return o;
        }
        // shift-click: every weekday between two clicks (either order)
        public static List<DateTime> Between(DateTime a, DateTime b) { if (b < a) { var t = a; a = b; b = t; } var o = new List<DateTime>(); for (var d = a.Date; d <= b.Date; d = d.AddDays(1)) if (Weekday(d)) o.Add(d); return o; }
    }
    // 🟩 THE ACCOUNT TILE (item 12 — "the simulation for trailing drawdown accounts"): one model for every pool tile (eval, funded, business run):
    // the buffer bar floor → balance (incl. open P/L) → target / payout need, the floor's kind (TPT INTRADAY trailing incl. open profit until the +$2,000
    // lock, then 🔒 + the $2,000 buffer filling to the next withdrawal • Lucid / Tradeify EOD trailing until it locks at +$100 • MFF STATIC), the state colour key,
    // "days to lock: n so far / usually ≈ m" (the run record's history), the qualifying-day dots and when a tile flashes (target / payout / blow)
    public sealed class KeystoneTileModel
    {
        static readonly CultureInfo IC = CultureInfo.InvariantCulture;
        public string Firm = "", Kind = "EOD", State = "EVAL", TopLabel = "", Line = ""; public double Lo, Hi, Floor, Bal, Top, Dd, LockAt; public bool Locked, Funded;
        public double Peak = double.NaN;   /* 📈 11f: the practice bar's PEAK marker + the "given back" segment (NaN = none) */
        public double PeakFrac { get { return double.IsNaN(Peak) ? double.NaN : C01((Peak - Lo) / (Hi - Lo)); } }
        static double C01(double v) { return double.IsNaN(v) ? 0 : Math.Max(0, Math.Min(1, v)); }
        public double FloorFrac { get { return C01((Floor - Lo) / (Hi - Lo)); } }
        public double BalFrac { get { return C01((Bal - Lo) / (Hi - Lo)); } }
        public double StartFrac { get { return C01((0 - Lo) / (Hi - Lo)); } }
        public double Room { get { return Bal - Floor; } }
        public double ToTop { get { return Math.Max(0, Top - Bal); } }
        static string M(double v) { return "$" + Math.Abs(Math.Round(v)).ToString("N0", IC); }
        static string Sg(double v) { return (v >= 0 ? "+" : "−") + "$" + Math.Abs(Math.Round(v)).ToString("N0", IC); }
        public static string KindOf(KeystonePayoutRules r, bool funded) { if (r == null) return "EOD"; if (r.Studio || r.StaticDd) return "STATIC"; if (r.Tpt && funded) return "INTRADAY"; string t = ((funded ? r.DdType : r.EvalDdType) ?? "EOD").ToUpperInvariant(); return t == "INTRADAY" ? "INTRADAY" : t == "STATIC" ? "STATIC" : "EOD"; }
        // bal / floor / top counted from the start (0 = the account size) • dd = the drawdown • lockAt = where the trail stops (TPT 0 = the start, Lucid +$100)
        public static KeystoneTileModel Make(string firm, string kind, bool funded, double bal, double floor, double dd, double lockAt, double top, bool locked, string state, string topLabel)
        {
            var m = new KeystoneTileModel { Firm = firm ?? "", Kind = kind ?? "EOD", Funded = funded, Bal = bal, Floor = floor, Dd = Math.Max(1, dd), LockAt = lockAt, Top = top, Locked = locked, State = state ?? "EVAL", TopLabel = topLabel ?? "" };
            m.Lo = Math.Min(-m.Dd, Math.Min(floor, bal)); m.Hi = Math.Max(top, Math.Max(bal, floor + 1)); if (m.Hi - m.Lo < 1) m.Hi = m.Lo + 1;
            if (m.Kind == "STATIC") m.Line = "▬ static floor " + Sg(floor) + " (never moves) · room " + M(Math.Max(0, m.Room));
            else if (m.Kind == "INTRADAY") m.Line = locked ? "🔒 floor locked at the start · buffer " + M(Math.Max(0, m.Room)) + " of " + M(m.Dd) + (funded ? " → the next withdrawal at " + Sg(top) : "") : "⟳ intraday trailing incl. open P/L · floor " + Sg(floor) + " · locks when the best equity reaches " + Sg(lockAt + m.Dd);
            else m.Line = locked ? "🔒 EOD trail locked at " + Sg(floor) + " · room " + M(Math.Max(0, m.Room)) : "⟳ end-of-day trailing · floor " + Sg(floor) + (lockAt < 1e8 ? " · locks at " + Sg(lockAt) : "") + " · room " + M(Math.Max(0, m.Room));
            return m;
        }
        public static int Median(IList<int> v) { if (v == null || v.Count == 0) return -1; var s = v.OrderBy(x => x).ToList(); return s[s.Count / 2]; }
        public static string DaysToLock(int soFar, IList<int> history, string what) { int md = Median(history); return "days to " + (what ?? "lock") + ": " + soFar + " so far / usually ≈ " + (md < 0 ? "–" : md.ToString(IC)); }
        public static string Dots(int n, int of) { if (of <= 0) return ""; n = Math.Max(0, Math.Min(of, n)); return new string('●', n) + new string('○', of - n); }
        // a tile flashes once when its state changes to the target / a payout / a blow
        public static bool Flash(string prev, string now) { return prev != null && prev != now && (now == "PASSED" || now == "READY" || now == "PAID" || now == "BLOWN" || now == "LOCKED"); }
        public static string StateName(string s) { switch (s ?? "") { case "TRADE": return "IN A TRADE"; case "BANKED": return "DAY BANKED"; case "LOST": return "LOST TODAY"; case "PASSED": return "PASSED"; case "FUNDED": return "FUNDED · building"; case "READY": return "PAYOUT READY"; case "PAID": return "PAID"; case "BLOWN": return "BLOWN"; case "LIVE": return "MOVED TO LIVE"; case "LOCKED": return "🔒 LOCKED"; default: return "IN EVAL"; } }
    }
    // 🎯 PRACTICE AS A PROP ACCOUNT (item 34, BACKTEST STUDIO ▸ REGULAR BACKTESTING) + the AUTO BRACKET IN $ (34b) — simulation only (the Backtest Studio's
    // own practice trader): the presets, the floor (STATIC / EOD trailing / INTRADAY trailing incl. open profit, optional lock), PASSED / BLOWN, the attempts log,
    // the prices where the OPEN position would hit the floor / the target, and $ → points after costs for the contracts chosen (MNQ $2 / pt, MGC $10 / pt)
    // 🎮 NINJATRADER SIMULATION ACCOUNTS (BUILD 2026-11-11i, the user: "it doesn't list the sim account to test it"): Sim101 / Sim* / DEMO* / PLAYBACK* are
    // listed in ● LIVE TRADING's account dropdown AFTER the real prop accounts, under a 🎮 SIMULATION header, and linked like any account (ARM + limits,
    // orders through the same link to the Sim account). They stay OUT of every prop logic (labs' counts, the autopilot feed, copier / rotation pools —
    // KeystoneLabLive.IsProp is false for SIM). The 🎯 PRACTICE AS A PROP ACCOUNT overlay is offered on them only (never on a real prop account).
    public static class KeystoneSimAccounts
    {
        public const string Header = "🎮 SIMULATION (practice / testing — not a prop account)";
        public static bool IsSim(string name)
        {
            string n = (name ?? "").Trim().ToUpperInvariant();
            return (n.StartsWith("SIM") && (n.Length == 3 || !char.IsLetter(n[3]))) || n.StartsWith("DEMO") || n.StartsWith("PLAYBACK");
        }
        // the dropdown's order: (name, connected, today) → the prop accounts (best today first), then the header ("") and the simulation accounts
        public static List<string> MenuOrder(IEnumerable<Tuple<string, bool, double>> accounts)
        {
            var l = (accounts ?? Enumerable.Empty<Tuple<string, bool, double>>()).Where(x => x != null && x.Item2 && !string.IsNullOrEmpty(x.Item1)).ToList();
            var o = l.Where(x => !IsSim(x.Item1)).OrderByDescending(x => x.Item3).Select(x => x.Item1).ToList();
            var sims = l.Where(x => IsSim(x.Item1)).OrderBy(x => x.Item1, StringComparer.OrdinalIgnoreCase).Select(x => x.Item1).ToList();
            if (sims.Count > 0) { o.Add(""); o.AddRange(sims); }
            return o;
        }
        // the 🎯 practice overlay on LIVE data: only a simulation account (by its name AND its firm = SIM — a firm you set for it wins)
        public static bool PracticeOffered(string account, string connection, string firmOverride)
        {
            if (!IsSim(account)) return false; var d = KeystoneFirmNames.Detect(account, connection, string.IsNullOrWhiteSpace(firmOverride) ? null : firmOverride); return d != null && d[0] == "SIM";
        }
    }
    // the live practice "account" = a ledger on top of the Sim account: its closed P/L = the Sim's realized since the practice start (RESET re-bases);
    // nothing here ever touches the Sim account itself
    public sealed class KeystonePracticeLedger
    {
        public double Base;
        public void Rebase(double realizedNow) { Base = -realizedNow; }
        public double Closed(double realizedNow) { return Base + realizedNow; }
    }

    /* 📐 BUILD 2026-11-11j — THE TRAILING-DRAWDOWN VIEW, exact (the user: "hugely visual and accurate"): for the practice account and ONE position (or a hypothetical one
       of `qty` at the price when flat), money from the start: equity = closed + open (open = pos·pv·(px − avg) − cost·|pos|, cost = the round trip per contract: both sides'
       commission + 1 tick) • PEAK = the best equity incl. open (every tick / the bar's best) • FLOOR = peak − DD, never down, locked at the start once peak − DD ≥ LockAt (TPT
       PRO: +$2,000) • LOCK = the equity +LockAt + DD (net of costs) • the prices where the position's equity = the floor / the peak / the lock (PriceAt) • ROOM = equity −
       floor ($ and points for this size) • GIVEN BACK = peak − equity • TO LOCK = lock − equity ($ and points). Simulation only. */
    public sealed class KeystonePracticeTrail
    {
        public double Equity, Peak, Floor, Room, GivenBack, LockLevel, ToLock, FloorPx = double.NaN, PeakPx = double.NaN, LockPx = double.NaN, RoomPts, LockPts; public bool Locked, Blown, HasLock; public int Qty;
        public static KeystonePracticeTrail Of(KeystonePractice p, double closed, int pos, double avg, double price, double pv, double cost)
        {
            var v = new KeystonePracticeTrail(); if (p == null || pos == 0 || pv <= 0) return v; int q = Math.Abs(pos); v.Qty = q;
            double open = pos * pv * (price - avg) - cost * q; v.Equity = closed + open;
            double oAll = v.Equity - p.Closed;   /* the account's whole open P/L as the practice sees it (closed = the account's equity without this position) */
            double pk = p.PeakNow(oAll); v.Peak = double.IsNaN(pk) ? Math.Max(0, v.Equity) : Math.Max(pk, v.Equity); v.Floor = p.FloorNow(oAll); v.Locked = p.Locked; v.Blown = p.Blown || v.Equity <= v.Floor + 1e-9;
            v.Room = Math.Max(0, v.Equity - v.Floor); v.GivenBack = Math.Max(0, v.Peak - v.Equity); v.RoomPts = v.Room / (q * pv);
            v.HasLock = !double.IsNaN(p.LockAt) && p.Funded; v.LockLevel = p.Kind == "TPT" && !v.Locked ? p.LockAt + p.Dd : p.Goal; v.ToLock = Math.Max(0, v.LockLevel - v.Equity); v.LockPts = v.ToLock / (q * pv);
            v.FloorPx = KeystonePractice.PriceAt(v.Floor, closed, pos, avg, pv, cost); v.PeakPx = KeystonePractice.PriceAt(v.Peak, closed, pos, avg, pv, cost); v.LockPx = KeystonePractice.PriceAt(v.LockLevel, closed, pos, avg, pv, cost);
            return v;
        }
        // the first tick where the account dies (a long: at or below the floor price; a short: at or above)
        public static double DeathTick(double floorPx, int pos, double tick) { if (double.IsNaN(floorPx) || tick <= 0) return double.NaN; double n = floorPx / tick; return Math.Round((pos > 0 ? Math.Floor(n + 1e-9) : Math.Ceiling(n - 1e-9)) * tick, 6); }
        static readonly CultureInfo IC = CultureInfo.InvariantCulture;
        static string M(double v) { return "$" + Math.Abs(Math.Round(v)).ToString("N0", IC); }
        public string FloorLabel(Func<double, string> px) { return "FLOOR " + px(FloorPx) + " · " + M(Room) + " left"; }
        public string LockLabel(Func<double, string> px) { return Locked ? "🔒 LOCKED · floor at the start" : "LOCK " + px(LockPx) + " · +" + M(ToLock) + " to go"; }
        public string PeakLabel() { return "PEAK " + (Peak >= 0 ? "+" : "−") + M(Peak) + " (given back " + M(GivenBack) + ")"; }
    }

    /* 🏷 BUILD 11k — the right-gutter LABEL STACK (the user: "a bunch of order lines overlapping"): labels whose prices are within MergeTicks of the group's first
       are MERGED into one ("FLOOR · LOCK"), then stacked with at least the label height + 2 px between them, pushed away from the live price label (reserved),
       above it upward and below it downward. Pure: returns (top y, text, the indices merged) per label. */
    /* 📼 BUILD 11k — LIVE DEMO HISTORY (the user: the D chart showed ONE candle): the sessions BEFORE today behind the live bars = the studio's saved days first, NinjaTrader's
       for the gaps (a session the store does not have), never both, the newest `days` sessions — pure, the studio does the requests */
    public static class KeystoneLiveHistory
    {
        public static List<KeystoneArcBar> Merge(IEnumerable<KeystoneArcBar> saved, IEnumerable<KeystoneArcBar> nt, DateTime today, int days, out int fromSaved, out int fromNt)
        {
            fromSaved = fromNt = 0; var bySes = new SortedDictionary<DateTime, List<KeystoneArcBar>>(); var src = new Dictionary<DateTime, bool>();
            foreach (var g in (saved ?? new List<KeystoneArcBar>()).Where(b => b != null).GroupBy(b => KeystoneStudioStore.SessionOf(b.Time)).Where(g => g.Key < today.Date)) { bySes[g.Key] = g.GroupBy(b => b.Time).Select(x => x.First()).OrderBy(b => b.Time).ToList(); src[g.Key] = true; }
            foreach (var g in (nt ?? new List<KeystoneArcBar>()).Where(b => b != null).GroupBy(b => KeystoneStudioStore.SessionOf(b.Time)).Where(g => g.Key < today.Date && !bySes.ContainsKey(g.Key))) { bySes[g.Key] = g.GroupBy(b => b.Time).Select(x => x.First()).OrderBy(b => b.Time).ToList(); src[g.Key] = false; }
            var keep = bySes.Keys.Where(k => bySes[k].Count >= 30).OrderByDescending(k => k).Take(Math.Max(1, days)).OrderBy(k => k).ToList();
            foreach (var k in keep) { if (src[k]) fromSaved++; else fromNt++; }
            return keep.SelectMany(k => bySes[k]).ToList();
        }
        // the weekdays in [from, to] the store has no session for (what to ask NinjaTrader for)
        public static List<DateTime> Missing(IEnumerable<DateTime> have, DateTime from, DateTime to)
        {
            var h = new HashSet<DateTime>((have ?? new List<DateTime>()).Select(d => d.Date)); var o = new List<DateTime>();
            for (var d = from.Date; d <= to.Date; d = d.AddDays(1)) if (d.DayOfWeek != DayOfWeek.Saturday && d.DayOfWeek != DayOfWeek.Sunday && !h.Contains(d)) o.Add(d);
            return o;
        }
    }
    /* 🧮 BUILD 11l — THE PRACTICE TILES (the studio header, the user: "better data representation"): every number once, from the practice account + the open position.
       Balance = realised since the attempt start · Open = the open P/L after costs · Peak = the best equity incl. open (its time) · Given back = peak − equity ·
       Floor = the live drawdown line ($ and the price for the open position) · Room = equity − floor ($ + points for the open size, the drain fraction of the DD) ·
       To lock / target ($ + points + progress) · MANUAL: day P/L, peak, the max drawdown seen, trades / win % (no floor, no goal). Pure. */
    public sealed class KeystonePracticeTiles
    {
        public bool Manual, InTrade, HasGoal, Locked, Blown; public double Balance, Open, Equity, Peak, GivenBack, Floor, FloorPx = double.NaN, Room, RoomPts = double.NaN, RoomFrac, ToGoal, ToGoalPts = double.NaN, Progress, DayPnl, MaxDdSeen, WinPct;
        public int Trades, Wins; public DateTime PeakTime; public string GoalName = "", PosText = "", FloorKind = "";
        static readonly CultureInfo IC = CultureInfo.InvariantCulture;
        public static KeystonePracticeTiles Of(KeystonePractice p, double closed, double open, int pos, double avg, double price, double pv, double cost, double dayPnl, DateTime peakTime, int trades, int wins)
        {
            var t = new KeystonePracticeTiles(); if (p == null) return t; t.Manual = p.Manual; t.Balance = closed; t.Open = open; t.Equity = closed + open; t.DayPnl = dayPnl; t.Trades = trades; t.Wins = wins; t.WinPct = trades > 0 ? 100.0 * wins / trades : 0;
            t.InTrade = pos != 0; int q = Math.Abs(pos); if (t.InTrade) t.PosText = (pos > 0 ? "LONG " : "SHORT ") + q + " @ " + avg.ToString("0.00", IC);
            double pk = p.Manual || string.Equals(p.DdType, "INTRADAY", StringComparison.OrdinalIgnoreCase) ? Math.Max(p.Peak, t.Equity) : string.Equals(p.DdType, "STATIC", StringComparison.OrdinalIgnoreCase) ? Math.Max(Math.Max(0, p.BestEq), t.Equity) : Math.Max(p.PeakEod, 0);
            t.Peak = pk; t.PeakTime = peakTime; t.GivenBack = Math.Max(0, pk - t.Equity); t.MaxDdSeen = Math.Max(p.MaxDdSeen, Math.Max(p.BestEq, t.Equity) - t.Equity); t.Blown = p.Blown;
            if (p.Manual) return t;
            t.Floor = p.FloorNow(open); t.Room = Math.Max(0, t.Equity - t.Floor); t.RoomFrac = Math.Max(0, Math.Min(1, t.Room / Math.Max(1, p.Dd))); t.Locked = p.Locked;
            t.FloorKind = string.Equals(p.DdType, "STATIC", StringComparison.OrdinalIgnoreCase) ? "static" : p.Locked ? "locked at the start" : string.Equals(p.DdType, "EOD", StringComparison.OrdinalIgnoreCase) ? "moves at the close" : "trailing incl. open";
            if (t.InTrade && pv > 0) { t.FloorPx = KeystonePractice.PriceAt(t.Floor, closed, pos, avg, pv, cost); t.RoomPts = t.Room / (q * pv); }
            t.HasGoal = true; bool tpt = p.Kind == "TPT";
            t.GoalName = tpt ? (p.Locked ? "WITHDRAWABLE ABOVE" : "TO LOCK") : p.Kind == "EVAL" ? "TO TARGET" : "TO " + p.GoalName.ToUpperInvariant();
            double goal = p.Goal; t.ToGoal = Math.Max(0, goal - (tpt ? Math.Max(pk, t.Equity) : t.Equity)); if (t.InTrade && pv > 0) t.ToGoalPts = t.ToGoal / (q * pv);
            t.Progress = tpt && p.Locked ? 1 : Math.Max(0, Math.Min(1, ((tpt ? Math.Max(pk, t.Equity) : t.Equity) + p.Dd) / Math.Max(1, goal + p.Dd)));
            return t;
        }
    }
    /* 📊 BUILD 11l — THE PRACTICE ATTEMPTS TRACKER (Studio\practice-attempts.csv — the 11c file, extended: the first six columns stay as they were): one row per attempt
       (#, preset, mode replay / live demo / Sim101, start → end in the practice's own time, result LOCKED / PASSED / BLOWN / RESET (↺ by hand) / DAY (🆓 MANUAL: one row a
       session), trades, wins / losses, P/L, peak, the max drawdown from the peak, the floor at the end) + the summary bar. Attempt numbers continue after a restart. Pure. */
    public sealed class KeystonePracticeAttempt
    {
        public int No, Days, Trades, Wins, Losses; public string Preset = "", Mode = "", Result = ""; public DateTime When, Start, End; public double Pnl, Peak, MaxDd, Floor = double.NaN;
        public TimeSpan Duration { get { return End > Start ? End - Start : TimeSpan.Zero; } }
        public bool Passed { get { return Result == "LOCKED" || Result == "PASSED"; } }
    }
    public static class KeystonePracticeAttempts
    {
        static readonly CultureInfo IC = CultureInfo.InvariantCulture;
        public const string Header = "when,account,result,days,trades,closed,attempt,mode,start,end,wins,losses,peak,maxdd,floor";
        static string C(string x) { return (x ?? "").Replace(",", " ").Replace("\n", " "); }
        static string T(DateTime d) { return d == DateTime.MinValue ? "" : d.ToString("yyyy-MM-dd HH:mm:ss", IC); }
        public static string Line(KeystonePracticeAttempt a)
        {
            return string.Join(",", a.When.ToString("yyyy-MM-dd HH:mm", IC), C(a.Preset), a.Result, a.Days, a.Trades, a.Pnl.ToString("0.##", IC), a.No, C(a.Mode), T(a.Start), T(a.End), a.Wins, a.Losses, a.Peak.ToString("0.##", IC), a.MaxDd.ToString("0.##", IC), double.IsNaN(a.Floor) ? "" : a.Floor.ToString("0.##", IC));
        }
        public static KeystonePracticeAttempt Parse(string line, int fallbackNo)
        {
            var c = (line ?? "").Split(','); if (c.Length < 6 || c[0] == "when") return null;
            try
            {
                Func<int, double> D = k => k < c.Length && c[k] != "" ? double.Parse(c[k], NumberStyles.Float, IC) : 0; Func<int, int> I = k => k < c.Length && c[k] != "" ? int.Parse(c[k], IC) : 0;
                Func<int, DateTime> Tm = k => { DateTime d; return k < c.Length && DateTime.TryParseExact(c[k], "yyyy-MM-dd HH:mm:ss", IC, DateTimeStyles.None, out d) ? d : DateTime.MinValue; };
                var a = new KeystonePracticeAttempt { When = DateTime.ParseExact(c[0], "yyyy-MM-dd HH:mm", IC), Preset = c[1], Result = c[2], Days = I(3), Trades = I(4), Pnl = D(5), No = c.Length > 6 && c[6] != "" ? I(6) : fallbackNo, Mode = c.Length > 7 ? c[7] : "", Start = Tm(8), End = Tm(9), Wins = I(10), Losses = I(11), Peak = D(12), MaxDd = D(13), Floor = c.Length > 14 && c[14] != "" ? D(14) : double.NaN };
                if (a.Start == DateTime.MinValue) a.Start = a.When; if (a.End == DateTime.MinValue) a.End = a.When; return a;
            }
            catch { return null; }
        }
        public static List<KeystonePracticeAttempt> Load(string text)
        {
            var o = new List<KeystonePracticeAttempt>(); int n = 0; foreach (var l in (text ?? "").Split('\n')) { var a = Parse(l.TrimEnd('\r'), n + 1); if (a != null) { o.Add(a); n = Math.Max(n, a.No); } } return o;
        }
        public static int NextNo(IList<KeystonePracticeAttempt> all) { return (all == null || all.Count == 0 ? 0 : all.Max(a => a.No)) + 1; }
        public static string Chip(string result) { switch (result) { case "LOCKED": return "🔒 LOCKED"; case "PASSED": return "✅ PASSED"; case "BLOWN": return "💀 BLOWN"; case "OPEN": return "⏸ open"; case "DAY": return "📅 DAY"; default: return "↺ reset by hand"; } }
        public static string Dur(TimeSpan t) { return t.TotalDays >= 1 ? ((int)t.TotalDays) + "d " + t.Hours + "h" : t.TotalHours >= 1 ? ((int)t.TotalHours) + "h " + t.Minutes.ToString("00", IC) + "m" : ((int)t.TotalMinutes) + "m " + t.Seconds.ToString("00", IC) + "s"; }
        public static List<KeystonePracticeAttempt> Filter(IList<KeystonePracticeAttempt> all, string preset, string mode, DateTime from, DateTime to)
        {
            return (all ?? new List<KeystonePracticeAttempt>()).Where(a => (string.IsNullOrEmpty(preset) || a.Preset == preset) && (string.IsNullOrEmpty(mode) || a.Mode == mode) && (from == DateTime.MinValue || a.Start.Date >= from.Date) && (to == DateTime.MinValue || a.Start.Date <= to.Date)).ToList();
        }
        // the summary bar: attempts (📅 DAY rows apart), 🔒 / ✅, 💀, open, pass % (of the finished ones), avg / median time to pass, avg trades, the net, the streak
        public static List<string[]> Summary(IList<KeystonePracticeAttempt> all)
        {
            var at = (all ?? new List<KeystonePracticeAttempt>()).Where(a => a.Result != "DAY").ToList(); int pass = at.Count(a => a.Passed), blown = at.Count(a => a.Result == "BLOWN"), open = at.Count(a => a.Result == "OPEN"), fin = pass + blown;
            var tp = at.Where(a => a.Passed).Select(a => a.Duration.TotalSeconds).OrderBy(x => x).ToList(); Func<double, string> dur = sec => Dur(TimeSpan.FromSeconds(sec));
            string streak = "–"; var seq = at.Where(a => a.Result != "OPEN").OrderBy(a => a.No).ToList();
            if (seq.Count > 0) { var last = seq[seq.Count - 1]; bool lp = last.Passed; int k = 0; for (int i = seq.Count - 1; i >= 0 && (lp ? seq[i].Passed : seq[i].Result == last.Result); i--) k++; streak = k + " × " + (lp ? "🔒 / ✅" : Chip(last.Result)); }
            Func<double, string> sg = v => (v >= 0 ? "+" : "−") + "$" + Math.Abs(Math.Round(v)).ToString("N0", IC);
            return new List<string[]>
            {
                new[] { "attempts", at.Count.ToString(IC) }, new[] { "🔒 / ✅ passed", pass.ToString(IC) }, new[] { "💀 blown", blown.ToString(IC) }, new[] { "⏸ open", open.ToString(IC) },
                new[] { "pass %", fin == 0 ? "–" : (100.0 * pass / fin).ToString("0.0", IC) + " %" },
                new[] { "time to pass (avg / median)", tp.Count == 0 ? "–" : dur(tp.Average()) + " / " + dur(tp.Count % 2 == 1 ? tp[tp.Count / 2] : (tp[tp.Count / 2 - 1] + tp[tp.Count / 2]) / 2) },
                new[] { "trades / attempt", at.Count == 0 ? "–" : at.Average(a => a.Trades).ToString("0.0", IC) }, new[] { "net P/L", sg(at.Sum(a => a.Pnl)) }, new[] { "streak", streak },
            };
        }
    }
    public static class KeystoneLabelStack
    {
        public const int MergeTicks = 2;
        public static List<Tuple<double, string, int[]>> Layout(IList<double> ys, IList<double> prices, IList<string> texts, double h, double tick, double reservedY = double.NaN)
        {
            var o = new List<Tuple<double, string, int[]>>(); if (ys == null || ys.Count == 0) return o; if (tick <= 0) tick = 0.25;
            var idx = Enumerable.Range(0, ys.Count).Where(i => !double.IsNaN(ys[i])).OrderBy(i => ys[i]).ToList(); var groups = new List<List<int>>();
            foreach (int i in idx) { var g = groups.Count == 0 ? null : groups[groups.Count - 1]; if (g != null && Math.Abs(prices[i] - prices[g[0]]) <= MergeTicks * tick + 1e-9) g.Add(i); else groups.Add(new List<int> { i }); }
            var items = groups.Select(g => new { Y = g.Average(i => ys[i]), Text = string.Join(" · ", g.Select(i => texts[i])), Ix = g.ToArray() }).ToList();
            double gap = 2; var placed = new List<Tuple<double, string, int[]>>();
            if (double.IsNaN(reservedY))
            {
                double cur = double.NegativeInfinity; foreach (var it in items.OrderBy(x => x.Y)) { double t = Math.Max(it.Y - h / 2, cur); placed.Add(Tuple.Create(t, it.Text, it.Ix)); cur = t + h + gap; }
            }
            else
            {
                double cur = reservedY + h / 2 + gap; foreach (var it in items.Where(x => x.Y >= reservedY).OrderBy(x => x.Y)) { double t = Math.Max(it.Y - h / 2, cur); placed.Add(Tuple.Create(t, it.Text, it.Ix)); cur = t + h + gap; }
                cur = reservedY - h / 2 - gap; foreach (var it in items.Where(x => x.Y < reservedY).OrderByDescending(x => x.Y)) { double t = Math.Min(it.Y - h / 2, cur - h); placed.Add(Tuple.Create(t, it.Text, it.Ix)); cur = t - gap; }
            }
            return placed.OrderBy(x => x.Item1).ToList();
        }
    }

    public sealed class KeystonePractice
    {
        static readonly CultureInfo IC = CultureInfo.InvariantCulture;
        public string Name = "custom", DdType = "EOD"; public double Size = 50000, Dd = 2000, Target = 3000, LockAt = double.NaN; public int MaxQty = 40; public bool Funded;
        public double Closed, Peak, PeakEod, LastOpen; public bool Blown, Passed; public int Days, Trades; public string How = "";
        /* 🎯 BUILD 11f (the user: "I chose TPT funded … I don't see the buffer"): a FUNDED preset has no "pass" target — Kind says what its goal is:
           TPT = intraday trailing incl. open P/L until the best equity reaches LockAt + Dd (+$2,000: the floor locks at the start), then the $2,000 buffer is kept and
           💰 WITHDRAW books WithdrawAmt at ≥ WithdrawAt (+$3,000: $1,000 → Split % to you) • PAYOUT (Lucid / Tradeify) = EOD trailing locking at +$100, qualifying days
           (≥ QualMin) n / QualDays and the payout when they are done AND the profit ≥ Target (Pct % of it, max Cap) • MFF = a static floor, WITHDRAW any profit ≥ Target
           ($250) up to Cap ($5,000) in total • EVAL = the target passes. Simulation only. */
        // 📈 11f: the PEAK (INTRADAY) also takes the best open P/L the position reached between two looks (a long at the bar's high, a short at the bar's low) — the floor = peak − DD, never down
        public void SeeBest(double closed, double bestOpen) { if (Blown || Passed || !string.Equals(DdType, "INTRADAY", StringComparison.OrdinalIgnoreCase)) return; if (closed + bestOpen > Peak) Peak = closed + bestOpen; }
        public double PeakNow(double open) { string t = (DdType ?? "").ToUpperInvariant(); return t == "STATIC" ? double.NaN : t == "INTRADAY" ? Math.Max(Peak, Equity(open)) : PeakEod; }
        public void ApplyTyped() { if (Kind == "TPT") LockAt = Math.Max(-Dd, Target - Dd); }   /* TPT funded: the floor locks once the best equity reaches the typed TARGET (= the LOCK) */
        public bool CloseAtGoal = true;   /* ✅ 11f: flatten everything when the account target (eval) / the TPT lock is reached (on by default for those; off for the payout / MFF kinds) */
        public bool GoalCloses { get { return Kind == "EVAL" || (Kind == "TPT" && !Locked); } }
        // the level the open position's equity just reached that should close everything ("" = none): the eval target / the TPT lock (best equity incl. open)
        public string GoalHit(double open) { if (!CloseAtGoal || Blown || Passed || Math.Abs(open) < 0.005 || !GoalCloses) return ""; double eq = Equity(open); if (Kind == "EVAL") return Target > 0 && eq >= Target - 1e-9 ? "TARGET" : ""; return Math.Max(Peak, eq) - Dd >= LockAt - 1e-9 ? "LOCK" : ""; }
        public string Kind = "EVAL"; public double WithdrawAt = 3000, WithdrawAmt = 1000, Split = 80, QualMin = 150, Pct = 50, PayCap; public int QualDays = 5;
        public int Qual, Payouts; public double Withdrawn, ToYou; bool lockSeen; double eodClosed, dayWd;
        public KeystonePractice Copy() { var c = (KeystonePractice)MemberwiseClone(); c.Reset(); return c; }
        public void Reset() { Closed = Peak = PeakEod = LastOpen = 0; Blown = Passed = false; Days = Trades = 0; How = ""; Qual = Payouts = 0; Withdrawn = ToYou = 0; lockSeen = false; eodClosed = dayWd = 0; BestEq = MaxDdSeen = 0; }
        /* 🆓 BUILD 11l — MANUAL (no rules): a plain simulated account — a start balance, optional max contracts / daily loss — no floor, no lock, no pass, never blown,
           never auto-reset; the tiles show balance, open, day P/L, peak and the max drawdown seen from the peak • BestEq / MaxDdSeen are kept for every kind (the attempts log) */
        public bool Manual { get { return Kind == "MANUAL"; } }
        public double DailyLoss, BestEq, MaxDdSeen;
        public const string ManualName = "🆓 MANUAL — no rules (a plain simulated account)";
        public static string TargetLabelOf(string kind) { return kind == "TPT" ? "TRAILING TO BEAT $" : kind == "PAYOUT" ? "PAYOUT NEED $" : kind == "MFF" ? "WITHDRAW ≥ $" : "TARGET $"; }
        public string TargetLabel { get { return TargetLabelOf(Kind); } }
        // the goal now (money from the start): TPT the lock (+Dd above LockAt), then the next withdrawal • PAYOUT the profit needed • MFF the next withdrawal • EVAL the target
        public double Goal { get { return Kind == "TPT" ? (Locked ? FloorNow(0) + Dd : LockAt + Dd) : Kind == "MFF" ? Math.Max(250, Target) : Target; } }
        public string GoalName { get { return Kind == "TPT" ? (Locked ? "withdrawable above" : "beat the trailing") : Kind == "PAYOUT" ? "payout need" : Kind == "MFF" ? "withdraw ≥" : "target"; } }
        // 💰 what a withdrawal / payout would book now (gross; 0 = not yet): flat only
        public double CanWithdraw(double open)
        {
            if (!Funded || Blown || Math.Abs(open) > 0.005) return 0; double eq = Equity(open);
            if (Kind == "TPT") return Locked ? Math.Max(0, Math.Floor(eq - (FloorNow(open) + Dd))) : 0;   /* TPT phase 2: anything above the $2,000 buffer */
            if (Kind == "MFF") { double left = PayCap > 0 ? PayCap - Withdrawn : double.MaxValue; return eq >= Math.Max(250, Target) - 1e-9 && left > 0 ? Math.Min(eq, left) : 0; }
            if (Kind == "PAYOUT") { if (Qual < QualDays || eq < Target - 1e-9) return 0; double g = Math.Max(250, eq * Pct / 100.0); return PayCap > 0 ? Math.Min(PayCap, g) : g; }
            return 0;
        }
        public double Withdraw(double open, double amount = 0)
        {
            double g = CanWithdraw(open); if (amount > 0) g = Math.Min(g, amount); if (g <= 0) return 0; Withdrawn += g; ToYou += g * Split / 100.0; Payouts++; Closed -= g; dayWd += g; if (Kind == "PAYOUT") Qual = 0;
            How = "💰 " + (Kind == "PAYOUT" ? "payout " : "withdrawal ") + Payouts + ": " + M(g) + " → you " + M(g * Split / 100.0) + " (" + Split.ToString("0", IC) + " %)"; return g;
        }
        static KeystonePractice P(string n, string t, double size, double dd, double tg, int q, double lockAt, bool funded) { return new KeystonePractice { Name = n, DdType = t, Size = size, Dd = dd, Target = tg, MaxQty = q, LockAt = lockAt, Funded = funded }; }
        /* 🎯 LOCK RACE (BUILD 11j, the user approved it): TPT PRO 50K funded, 60 MNQ, the target +$2,000 NET (= the lock), the stop = the trailing floor — one race to the lock */
        public const string RaceName = "🎯 LOCK RACE · MNQ 10 @ 9:30 with the 60-min trend · +$2,000 lock · stop = the trailing floor";
        public const string RaceNote = "Research 2023–26, one trade a day: MNQ 10 @9:30 trend ≈ 40% lock (36% day 1); MNQ 5 ≈ 39%; MNQ 60 ≈ 31%. No edge ceiling ≈ 37%.\n"
            + "• 9:30 trend MNQ 10, TP $2K, SL floor ≈ 40% lock, 1 trade, 35% day 1\n• 9:30 trend MNQ 5, TP $2K, SL $500 ≈ 41–43%, median 2 trades / 2 days\n• 4:00 trend MNQ 5, TP $1K, SL $250, BE 75% ≈ 45%, median ~10 trades / 10 days";
        public static readonly int[] RaceSizes = { 5, 10, 15, 20, 30, 40, 60 };   /* the size is a choice (user's request); MNQ 10 by default */
        public static readonly double[] RaceTps = { 2000, 1000 };          /* TP per trade: the lock (default) / $1,000 */
        public static readonly double[] RaceSls = { 0, 1000, 500, 250 };   /* SL: 0 = the floor (default) / $1,000 / $500 / $250 — the real stop = the tighter of it and the live floor */
        // the next race trade's TP $: the choice, but never more than what is still missing to the lock (after a trade closes the next one aims for the rest)
        public static double RaceNextTp(double tpChoice, double equity, double lockLevel) { return Math.Max(0, Math.Min(tpChoice <= 0 ? double.MaxValue : tpChoice, lockLevel - equity)); }
        // the stop $: the floor (0) or the chosen $, whichever is TIGHTER than the room to the live floor
        public static double RaceStopUsd(double slChoice, double room) { room = Math.Max(0, room); return slChoice <= 0 ? room : Math.Min(slChoice, room); }
        // breakeven at 75 % of the TP: the open profit ($, after costs) that triggers it, and the stop then = entry + the costs (points beyond the entry, on the tick, never less)
        public static double BeTrigger(double tpUsd) { return 0.75 * Math.Max(0, tpUsd); }
        public static double BeStopPts(double costPerContract, double pv, double tick) { if (pv <= 0) return 0; if (tick <= 0) tick = 0.25; return Math.Ceiling(costPerContract / pv / tick - 1e-9) * tick; }
        public bool Race; public int RaceQty; public double RaceTp;
        static KeystonePractice AsRace(KeystonePractice p) { p.Race = true; p.RaceQty = 10; p.RaceTp = 2000; return p; }
        // the race's side at 9:30 NY: the last 60 minutes' close vs open (1-minute bars stamped at their close; 8:30 → 9:30) — +1 up, −1 down, 0 = flat / not enough bars
        public static int RaceSide(IList<KeystoneArcBar> bars, DateTime day)
        {
            if (bars == null) return 0; DateTime a = day.Date.AddHours(8).AddMinutes(30), b = day.Date.AddHours(9).AddMinutes(30);
            var w = bars.Where(x => x != null && x.Time > a && x.Time <= b).OrderBy(x => x.Time).ToList(); if (w.Count < 30) return 0;
            double d = w[w.Count - 1].Close - w[0].Open; return d > 1e-9 ? 1 : d < -1e-9 ? -1 : 0;
        }
        static KeystonePractice F(KeystonePractice p, string kind, double cap, double split) { p.Kind = kind; p.PayCap = cap; p.Split = split; p.CloseAtGoal = kind == "TPT"; return p; }
        public static List<KeystonePractice> Presets()
        {
