            config.EvalTierFilter = tierOf(evalTierBox); config.FundedTierFilter = tierOf(fundedTierBox);
            config.AsianEvalStageEnabled = asian75 && asianEvalStageBox != null && asianEvalStageBox.IsChecked == true ? 1 : 0;
