        }

        // Exports browser-openable SVG evidence charts instead of opaque screenshot pixels.  The files retain
        // the exact requested bars, entry prices, outcomes, and labels, and remain sharp when zoomed or printed.
        private void ExportEvidencePackage() { ExportEvidencePackage(true); }

        private void ExportEvidencePackage(bool charts)
        {
            if (events.Count == 0) { UpdateUi("RUN DETECTION BEFORE EVIDENCE EXPORT", Red); return; }
            if (operationBusy || isProcessing) { UpdateUi("WAIT FOR THE ACTIVE OPERATION BEFORE EVIDENCE EXPORT", Gold); return; }
            List<KeystoneArcEvent> eventCopy = CloneEvents(events);
            List<KeystoneArcBar> mnqCopy = new List<KeystoneArcBar>(mnqSetupBars);
            List<KeystoneArcBar> mgcCopy = new List<KeystoneArcBar>(mgcSetupBars);
            KeystoneArcRunConfig cfgCopy = CloneConfig(config);
            string rangeName = SessionDateLabel(cfgCopy).Replace(" → ", "_to_").Replace(" ", "_");
            string root = Path.Combine(DataDirectory(), "KeystoneEvidence_" + rangeName + "_" + DateTime.Now.ToString("yyyyMMdd_HHmmss"));
            if (!charts) root += "_DATA";
            BeginBusy(charts ? "EXPORTING EVIDENCE PACKAGE" : "EXPORTING DATA ONLY (NO CHARTS)");
            UpdateUi("EXPORTING INSTRUMENT FOLDERS, SESSION CHARTS, AND HTML LEDGERS", Gold);
            // The CSVs and the index page read the lab's controls: WPF allows that only on the lab's thread
            // ("the calling thread cannot access this object"). The slow SVG session charts are written in the background.
            System.Threading.ThreadPool.QueueUserWorkItem(delegate
            {
                string failure = null; int written = 0;
                var manifest = new StringBuilder();
                    manifest.Append("<h2>Evidence charts and raw ledgers</h2><div class='card'><strong>One package, one starting page.</strong> The links below open each instrument's SVG session charts and CSV ledger. Charts are generated from the selected direct NinjaTrader setup bars; they are a research record for visual validation, not proof that the detector or outcome model is correct.</div><p><a href='events.csv'>Complete event ledger CSV</a> • <a href='research_findings.csv'>Evidence-only research findings CSV</a> • <a href='first_returns.csv'>First-return dashboard CSV</a> • <a href='payout_accounts.csv'>Payout-account profitability CSV</a> • <a href='daily_selected_session.csv'>Daily selected-session scoreboard CSV</a> • <a href='account_snapshot.csv'>Account snapshot CSV</a> • <a href='account_days.csv'>Daily lifecycle CSV</a> • <a href='payout_cycles.csv'>Payout-cycle dashboard CSV</a> • <a href='balance_matrix.csv'>Balance matrix CSV</a> • <a href='capital_policy.csv'>Initial-investment and replacement policy CSV</a></p><ul>");
                try
                {
                    Directory.CreateDirectory(root);
                    if (charts)
                    {
                        written += ExportInstrumentEvidence(root, "MNQ", mnqCopy, eventCopy, cfgCopy, manifest);
                        written += ExportInstrumentEvidence(root, "MGC", mgcCopy, eventCopy, cfgCopy, manifest);
                    }
                    else manifest.Append("<li>DATA ONLY export: session charts were skipped (use EXPORT RESEARCH PACKAGE for them). events.csv holds every setup.</li>");
                    manifest.Append("</ul><p class='footer'>Charts written: ").Append(written).Append(". This page contains the run summary, account/payout scenario data, filters, comparisons, and detailed ledger; MNQ/MGC folders contain linked visual charts and machine-readable rows.</p>");
                }
                catch (Exception ex) { failure = ex.Message; }
                DispatchToLab(delegate
                {
                    string result;
                    try
                    {
                        if (failure != null) throw new Exception(failure);
                        File.WriteAllText(Path.Combine(root, "events.csv"), EventCsv(eventCopy), Encoding.UTF8);
                        File.WriteAllText(Path.Combine(root, "account_snapshot.csv"), AccountCsv(), Encoding.UTF8);
                        File.WriteAllText(Path.Combine(root, "account_days.csv"), AccountDayCsv(), Encoding.UTF8);
                        File.WriteAllText(Path.Combine(root, "first_returns.csv"), FirstReturnCsv(), Encoding.UTF8);
                        File.WriteAllText(Path.Combine(root, "payout_accounts.csv"), PayoutAccountCsv(), Encoding.UTF8);
                        File.WriteAllText(Path.Combine(root, "daily_selected_session.csv"), DailySessionScoreCsv(), Encoding.UTF8);
                        File.WriteAllText(Path.Combine(root, "research_findings.csv"), ResearchFindingsCsv(), Encoding.UTF8);
                        File.WriteAllText(Path.Combine(root, "payout_cycles.csv"), PayoutCycleCsv(), Encoding.UTF8);
                        File.WriteAllText(Path.Combine(root, "balance_matrix.csv"), BalanceMatrixCsv(), Encoding.UTF8);
                        File.WriteAllText(Path.Combine(root, "capital_policy.csv"), CapitalPolicyCsv(), Encoding.UTF8);
                        File.WriteAllText(Path.Combine(root, "index.html"), BuildEvidencePackageIndex(manifest.ToString()), Encoding.UTF8);
                        result = "EVIDENCE PACKAGE READY • OPEN index.html • " + (charts ? written + " SVG SESSION CHART(S) • ONE MAIN WEBSITE + MNQ/MGC ASSET FOLDERS • " : "DATA ONLY (no charts) • ") + root;
                    }
                    catch (Exception ex) { result = "EVIDENCE EXPORT ERROR • " + ex.Message; }
                    EndBusy();
                    if (result.StartsWith("EVIDENCE PACKAGE READY")) { unsavedResearch = false; RefreshSavedRuns(); UpdateUi(result + " • RUN ARCHIVE UPDATED", Green); try { System.Diagnostics.Process.Start(Path.Combine(root, "index.html")); } catch { } }
                    else UpdateUi(result, Red);
                });
            });
        }

        // ---- Report dashboard (top of the exported report) -----------------------------------
        private static string Hx(string v) { return System.Net.WebUtility.HtmlEncode(v ?? string.Empty); }

        private static string SvgLineChart(List<DateTime> xs, List<Tuple<string, string, List<double>>> series, int width, int height)
        {
            if (xs == null || xs.Count < 2 || series.Count == 0) return "<div class='muted'>Not enough data for a chart.</div>";
            double min = series.SelectMany(t => t.Item3).DefaultIfEmpty(0).Min(), max = series.SelectMany(t => t.Item3).DefaultIfEmpty(0).Max();
            min = Math.Min(min, 0); max = Math.Max(max, 0); if (max - min < 1) max = min + 1;
            int padL = 70, padR = 12, padT = 12, padB = 26;
            Func<int, double> X = i => padL + (width - padL - padR) * (double)i / (xs.Count - 1);
            Func<double, double> Y = v => padT + (height - padT - padB) * (max - v) / (max - min);
            var sb = new StringBuilder("<svg class='chart' viewBox='0 0 " + width + " " + height + "' preserveAspectRatio='none'>");
            for (int k = 0; k <= 4; k++)
            {
                double v = min + (max - min) * k / 4.0; double yy = Y(v);
                sb.Append("<line x1='" + padL + "' x2='" + (width - padR) + "' y1='" + yy.ToString("0.#", CultureInfo.InvariantCulture) + "' y2='" + yy.ToString("0.#", CultureInfo.InvariantCulture) + "' class='grid'/>");
                sb.Append("<text x='4' y='" + (yy + 4).ToString("0.#", CultureInfo.InvariantCulture) + "' class='axis'>" + Hx(Cash(v)) + "</text>");
            }
            double zero = Y(0); sb.Append("<line x1='" + padL + "' x2='" + (width - padR) + "' y1='" + zero.ToString("0.#", CultureInfo.InvariantCulture) + "' y2='" + zero.ToString("0.#", CultureInfo.InvariantCulture) + "' class='zero'/>");
            int step = Math.Max(1, xs.Count / 6);
            for (int i = 0; i < xs.Count; i += step) sb.Append("<text x='" + X(i).ToString("0.#", CultureInfo.InvariantCulture) + "' y='" + (height - 6) + "' class='axis' text-anchor='middle'>" + xs[i].ToString("yyyy-MM-dd") + "</text>");
            foreach (var t in series)
            {
                var pts = new StringBuilder();
                for (int i = 0; i < t.Item3.Count && i < xs.Count; i++) pts.Append(X(i).ToString("0.#", CultureInfo.InvariantCulture)).Append(',').Append(Y(t.Item3[i]).ToString("0.#", CultureInfo.InvariantCulture)).Append(' ');
                sb.Append("<polyline fill='none' stroke='" + t.Item2 + "' stroke-width='2.2' points='" + pts.ToString().Trim() + "'><title>" + Hx(t.Item1) + "</title></polyline>");
            }
            sb.Append("</svg><div class='legend'>");
            foreach (var t in series) sb.Append("<span><i style='background:" + t.Item2 + "'></i>" + Hx(t.Item1) + " " + Hx(Cash(t.Item3.Count == 0 ? 0 : t.Item3[t.Item3.Count - 1])) + "</span>");
            return sb.Append("</div>").ToString();
        }

        private static string SvgMonthBars(List<Tuple<DateTime, double, double, double>> months, int width, int height)
        {
            if (months == null || months.Count == 0) return "<div class='muted'>No monthly money flow yet.</div>";
            double max = Math.Max(1, months.Max(m => Math.Max(m.Item2, m.Item3))), minNet = Math.Min(0, months.Min(m => m.Item4));
            double top = Math.Max(max, months.Max(m => m.Item4));
            int padL = 70, padB = 26, padT = 12;
            double plotH = height - padT - padB, slot = (width - padL - 10) / (double)months.Count, bw = Math.Max(2, slot * 0.36);
            Func<double, double> Y = v => padT + plotH * (top - v) / (top - minNet);
            var sb = new StringBuilder("<svg class='chart' viewBox='0 0 " + width + " " + height + "' preserveAspectRatio='none'>");
            double zero = Y(0); sb.Append("<line x1='" + padL + "' x2='" + (width - 10) + "' y1='" + zero.ToString("0.#", CultureInfo.InvariantCulture) + "' y2='" + zero.ToString("0.#", CultureInfo.InvariantCulture) + "' class='zero'/>");
            sb.Append("<text x='4' y='" + (Y(top) + 4).ToString("0.#", CultureInfo.InvariantCulture) + "' class='axis'>" + Hx(Cash(top)) + "</text><text x='4' y='" + (zero + 4).ToString("0.#", CultureInfo.InvariantCulture) + "' class='axis'>$0</text>");
            var net = new StringBuilder();
            for (int i = 0; i < months.Count; i++)
            {
                var m = months[i]; double x0 = padL + i * slot + slot * 0.1;
                sb.Append("<rect x='" + x0.ToString("0.#", CultureInfo.InvariantCulture) + "' y='" + Y(m.Item2).ToString("0.#", CultureInfo.InvariantCulture) + "' width='" + bw.ToString("0.#", CultureInfo.InvariantCulture) + "' height='" + Math.Max(0, zero - Y(m.Item2)).ToString("0.#", CultureInfo.InvariantCulture) + "' class='bank'><title>" + m.Item1.ToString("MMM yyyy") + " to bank " + Hx(Cash(m.Item2)) + "</title></rect>");
                sb.Append("<rect x='" + (x0 + bw).ToString("0.#", CultureInfo.InvariantCulture) + "' y='" + Y(m.Item3).ToString("0.#", CultureInfo.InvariantCulture) + "' width='" + bw.ToString("0.#", CultureInfo.InvariantCulture) + "' height='" + Math.Max(0, zero - Y(m.Item3)).ToString("0.#", CultureInfo.InvariantCulture) + "' class='cost'><title>" + m.Item1.ToString("MMM yyyy") + " cost " + Hx(Cash(m.Item3)) + "</title></rect>");
                net.Append((x0 + bw).ToString("0.#", CultureInfo.InvariantCulture)).Append(',').Append(Y(m.Item4).ToString("0.#", CultureInfo.InvariantCulture)).Append(' ');
                if (months.Count <= 24 || i % Math.Max(1, months.Count / 12) == 0) sb.Append("<text x='" + (x0 + bw).ToString("0.#", CultureInfo.InvariantCulture) + "' y='" + (height - 6) + "' class='axis' text-anchor='middle'>" + m.Item1.ToString("MMM yy") + "</text>");
            }
            sb.Append("<polyline fill='none' class='netline' points='" + net.ToString().Trim() + "'><title>Net to date</title></polyline></svg>");
            sb.Append("<div class='legend'><span><i class='bank'></i>To your bank</span><span><i class='cost'></i>Account cost</span><span><i class='netline'></i>Net to date</span></div>");
            return sb.ToString();
        }

        private string BuildDashboardHtml(List<KeystoneArcEvent> accepted, KeystoneArcCapitalPolicySummary capital)
        {
            var sb = new StringBuilder();
            bool asian = string.Equals(config.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase);
            KeystoneArcPoolInsights x = KeystoneArcPoolInsights.Build(accounts, accepted.Where(e => asian || !string.IsNullOrWhiteSpace(e.AssignedVirtualAccount)), config);
            List<KeystoneArcDayScore> days = KeystoneArcScoreboard.Days(accepted, config);
            double strategy = days.Sum(d => d.Pnl); int winDays = days.Count(d => d.Pnl > 0);
            double eq = 0, peak = 0, dd = 0; foreach (var d in days) { eq += d.Pnl; peak = Math.Max(peak, eq); dd = Math.Max(dd, peak - eq); }
            Func<string, string, string, string, string> card = (label, value, note, cls) => "<div class='card kpi'><div class='label'>" + Hx(label) + "</div><div class='value " + cls + "'>" + Hx(value) + "</div><div class='muted'>" + Hx(note) + "</div></div>";
            sb.Append("<section id='dashboard' class='dash'><h2>DASHBOARD</h2>");
            sb.Append("<div class='answer'>").Append(Hx(KeystoneArcPoolInsights.InvestmentAnswer(capital, x))).Append("</div>");
            sb.Append("<div class='answer'>").Append(Hx(KeystoneArcPoolInsights.CashFlowAnswer(capital))).Append("</div>");
            sb.Append("<div class='grid kpis'>");
            sb.Append(card("Strategy P/L (one account)", Cash(strategy), days.Count + (asian ? " nights" : " days") + " • " + (days.Count == 0 ? "—" : (100.0 * winDays / days.Count).ToString("0") + "% winning"), strategy >= 0 ? "green" : "red"));
            sb.Append(card("Max drawdown", Cash(-dd), "deepest drop of the strategy", "red"));
            sb.Append(card("To your bank", Cash(x.CashAfterShare), "gross " + Cash(x.Gross) + " before the split", "gold"));
            sb.Append(card("All account costs", Cash(x.Cost), x.EvaluationPurchases + " accounts bought", "orchid"));
            sb.Append(card("Net after all costs", Cash(x.Net), x.PositiveMonths + " winning / " + x.NegativeMonths + " losing months", x.Net >= 0 ? "green" : "red"));
            sb.Append(card("First payout", x.FirstPayoutDate == DateTime.MinValue ? "none" : x.FirstPayoutDate.ToString("yyyy-MM-dd"), x.FirstPayoutAccount + (x.PaidAccounts > 0 ? " • avg " + x.AverageDaysToFirstPayout.ToString("0") + " days to first payout" : ""), "gold"));
            sb.Append(card("Profitable from", capital != null && capital.ProfitabilityReached ? capital.ProfitabilityDate.ToString("yyyy-MM-dd") : "not reached", "payout cash ≥ every account bought", capital != null && capital.ProfitabilityReached ? "green" : "red"));
            sb.Append(card("Blowups", x.BlowupEvents.ToString(), "evaluation " + x.EvaluationFails + " • funded " + x.FundedBlowups + " • funded now " + x.FundedNow + " / " + x.Accounts, x.BlowupEvents > 0 ? "red" : "green"));
            sb.Append("</div>");
            // Equity charts.
            var dayList = days.Select(d => d.Day.Date).ToList();
            var moneyByDay = accounts.SelectMany(a => a.DayHistory).GroupBy(d => d.Day.Date).ToDictionary(g => g.Key, g => g.Sum(d => d.PayoutCashDelta - d.CostDelta));
            var axis = dayList.Union(moneyByDay.Keys).Distinct().OrderBy(d => d).ToList();
            var dayPnl = days.ToDictionary(d => d.Day.Date, d => d.Pnl);
            double cs = 0, cm = 0; var strat = new List<double>(); var money = new List<double>();
            foreach (DateTime d in axis) { double v; if (dayPnl.TryGetValue(d, out v)) cs += v; if (moneyByDay.TryGetValue(d, out v)) cm += v; strat.Add(cs); money.Add(cm); }
            sb.Append("<div class='two'><div class='card'><div class='label'>Strategy equity vs cash in your bank (net of all account costs)</div>")
              .Append(SvgLineChart(axis, new List<Tuple<string, string, List<double>>> { Tuple.Create("Strategy P/L", "#58a6ff", strat), Tuple.Create("Net cash", "#f4c450", money) }, 1000, 260)).Append("</div>");
            var monthRows = accounts.SelectMany(a => a.DayHistory).GroupBy(d => new DateTime(d.Day.Year, d.Day.Month, 1)).OrderBy(g => g.Key).ToList();
            var monthBars = new List<Tuple<DateTime, double, double, double>>(); double running = 0;
            foreach (var g in monthRows) { double bank = g.Sum(d => d.PayoutCashDelta), cost = g.Sum(d => d.CostDelta); running += bank - cost; monthBars.Add(Tuple.Create(g.Key, bank, cost, running)); }
            sb.Append("<div class='card'><div class='label'>Month by month • money</div>").Append(SvgMonthBars(monthBars, 1000, 260)).Append("</div></div>");
            // OPTIMAL BEST ENTRIES FOR PROP + comparisons (strategies, accounts) + payout diagnosis.
            KeystoneArcBestEntryPlan bestPlan = KeystoneArcAnalyst.BestEntries(accepted, config, lastAccountRows, lastStrategyRows);
            sb.Append("<h2 id='best-entries'>★ OPTIMAL BEST ENTRIES FOR PROP TRADING</h2><div class='answer'>").Append(Hx(bestPlan.Headline)).Append("</div>");
            if (bestPlan.Filters.Count > 1)
            {
                sb.Append("<div class='table-wrap'><table><thead><tr><th>Trade</th><th>Setups</th><th>Win %</th><th>Per setup</th><th>Profit factor</th><th>Max drawdown</th><th>Worst day</th><th>Per day</th><th>Days to eval target</th><th>Best for</th></tr></thead><tbody>");
                foreach (KeystoneArcFilterRow r in bestPlan.Filters)
                    sb.Append("<tr class='").Append(r.EvalPick || r.FundedPick ? "win" : "").Append("'><td><b>").Append(Hx(r.Label)).Append("</b></td><td>").Append(r.Setups).Append("</td><td>").Append(r.WinRate.ToString("0", CultureInfo.InvariantCulture)).Append("%</td><td class='").Append(r.PerSetup >= 0 ? "green" : "red").Append("'>").Append(Hx(Cash(r.PerSetup))).Append("</td><td>").Append(r.ProfitFactor.ToString("0.00", CultureInfo.InvariantCulture)).Append("</td><td class='red'>").Append(Hx(Cash(-r.MaxDrawdown))).Append("</td><td>").Append(Hx(Cash(r.WorstDay))).Append("</td><td>").Append(Hx(Cash(r.PerDay))).Append("</td><td>").Append(double.IsNaN(r.DaysToEvalTarget) ? "—" : r.DaysToEvalTarget.ToString("0", CultureInfo.InvariantCulture)).Append("</td><td class='gold'>").Append((r.EvalPick ? "EVALUATION " : "") + (r.FundedPick ? "FUNDED" : "")).Append("</td></tr>");
                sb.Append("</tbody></table></div><div class='muted'>Grades are learned walk-forward (each setup graded only from setups that had finished before it). EVALUATION = fastest to the target while the drawdown stays inside the evaluation limit; FUNDED = most profit per setup with profit factor above 1.</div>");
            }
            sb.Append("<div class='insights'>");
            foreach (KeystoneArcInsight f in bestPlan.Cards)
                sb.Append("<div class='insight ").Append(f.Level.ToLowerInvariant()).Append("'><div class='tag'>").Append(Hx(f.Level)).Append("</div><div><b>").Append(Hx(f.Title)).Append("</b><br>").Append(Hx(f.Text)).Append("</div></div>");
            sb.Append("</div>");
            string whyNoPayout = KeystoneArcPoolCompare.PayoutDiagnosis(accounts, config);
            if (!string.IsNullOrEmpty(whyNoPayout)) sb.Append("<div class='card'><div class='label'>Why no / few payouts</div>").Append(Hx(whyNoPayout)).Append("</div>");
            if (!string.IsNullOrEmpty(lastStrategyComparison)) sb.Append("<h3 id='strategy-compare'>Which strategy wins • same bars, session and prop rules</h3><pre class='cmp'>").Append(Hx(lastStrategyComparison)).Append("</pre>");
            else sb.Append("<div class='muted'>Press COMPARE STRATEGIES in the lab to add BH vs FVG (and how often both give the same entry) to this report.</div>");
            if (!string.IsNullOrEmpty(lastAccountComparison)) sb.Append("<h3 id='account-compare'>Account count and allocation</h3><pre class='cmp'>").Append(Hx(lastAccountComparison)).Append("</pre>");
            else sb.Append("<div class='muted'>Press COMPARE ACCOUNTS in the lab to add the 1 / 2 / 3 / 5 / 10 / 20 accounts and copy-group comparison.</div>");
            // MONTHS / WEEKS / SESSIONS.
            EnsureMonthsAndSessions();
            if (lastMonthRows != null && lastMonthRows.Count > 0)
            {
                sb.Append("<h2 id='months-sessions'>MONTHS &amp; SESSIONS</h2><div class='muted'>POOL = the loaded run during that month. ALONE = that month on its own with new accounts on its first day. ★ best, ✖ worst.</div>");
                sb.Append("<div class='answer'>").Append(Hx(lastMonthRows.Count(r => r.TradePnl > 0) + " of " + lastMonthRows.Count + " months made money on trades • best " + (lastMonthRows.FirstOrDefault(r => r.Best) == null ? "—" : lastMonthRows.First(r => r.Best).Label) + " • worst " + (lastMonthRows.FirstOrDefault(r => r.Worst) == null ? "—" : lastMonthRows.First(r => r.Worst).Label))).Append("</div>");
                sb.Append("<div class='table-wrap'><table><thead><tr><th>Month</th><th>Setups</th><th>W / L / exit</th><th>Win %</th><th>Trade P/L</th><th>Worst day</th><th>Max DD</th><th>Pool payouts</th><th>Blowups</th><th>Pool net</th><th>Alone net</th><th>Alone payouts</th><th>1st payout</th></tr></thead><tbody>");
                foreach (KeystoneArcPeriodRow r in lastMonthRows)
                    sb.Append("<tr class='").Append(r.Best ? "win" : (r.Worst ? "loss" : "")).Append("'><td><b>").Append(Hx((r.Best ? "★ " : r.Worst ? "✖ " : "") + r.Label)).Append("</b></td><td>").Append(r.Setups).Append("</td><td>").Append(r.Wins + " / " + r.Losses + " / " + r.Exits).Append("</td><td>").Append(r.WinRate.ToString("0", CultureInfo.InvariantCulture)).Append("%</td><td class='").Append(r.TradePnl >= 0 ? "green" : "red").Append("'>").Append(Hx(Cash(r.TradePnl))).Append("</td><td>").Append(Hx(Cash(r.WorstDay))).Append("</td><td class='red'>").Append(Hx(Cash(-r.MaxDrawdown))).Append("</td><td>").Append(r.Payouts).Append("</td><td>").Append(r.Blowups).Append("</td><td class='").Append(r.Net >= 0 ? "green" : "red").Append("'>").Append(Hx(Cash(r.Net))).Append("</td><td>").Append(r.FreshRan ? Hx(Cash(r.FreshNet)) : "—").Append("</td><td>").Append(r.FreshRan ? r.FreshPayouts.ToString(CultureInfo.InvariantCulture) : "—").Append("</td><td>").Append(r.FreshDaysToFirstPayout >= 0 ? r.FreshDaysToFirstPayout + " d" : "—").Append("</td></tr>");
                sb.Append("</tbody></table></div>");
            }
            if (lastSessionReport != null && lastSessionReport.Windows.Count > 0)
            {
                sb.Append("<h3>Session finder (NY time) • ranked per setup, picked on the first 2/3, checked on the last 1/3</h3><div class='answer'>").Append(Hx(lastSessionReport.Verdict)).Append("</div>");
                sb.Append("<div class='table-wrap'><table><thead><tr><th>Session</th><th>Setups</th><th>Win %</th><th>Per setup</th><th>PF</th><th>Trade P/L</th><th>Max DD</th><th>First 2/3</th><th>Last 1/3</th><th>Pool net</th><th>Payouts</th></tr></thead><tbody>");
                foreach (KeystoneArcSessionRow r in lastSessionReport.Windows.Where(w => w.Loaded))
                    sb.Append("<tr class='").Append(r.Best ? "win" : "").Append("'><td><b>").Append(Hx((r.Best ? "★ " : "") + r.Label)).Append("</b></td><td>").Append(r.Loaded ? r.Setups.ToString(CultureInfo.InvariantCulture) : "not loaded").Append("</td><td>").Append(r.WinRate.ToString("0", CultureInfo.InvariantCulture)).Append("%</td><td class='").Append(r.PerSetup >= 0 ? "green" : "red").Append("'>").Append(Hx(Cash(r.PerSetup))).Append("</td><td>").Append(r.ProfitFactor.ToString("0.00", CultureInfo.InvariantCulture)).Append("</td><td>").Append(Hx(Cash(r.TradePnl))).Append("</td><td class='red'>").Append(Hx(Cash(-r.MaxDrawdown))).Append("</td><td>").Append(r.FirstN == 0 ? "—" : Hx(Cash(r.FirstPerSetup))).Append("</td><td>").Append(r.LaterN == 0 ? "—" : Hx(Cash(r.LaterPerSetup))).Append("</td><td>").Append(r.PoolRan ? Hx(Cash(r.PoolNet)) : "—").Append("</td><td>").Append(r.PoolRan ? r.PoolPayouts.ToString(CultureInfo.InvariantCulture) : "—").Append("</td></tr>");
                sb.Append("</tbody></table></div>");
                if (lastSessionReport.Hours.Count > 0) sb.Append("<div class='mono'>").Append(Hx("BY HOUR (per setup): " + string.Join("  ", lastSessionReport.Hours.Select(h => h.Label.Substring(0, 2) + ":00 " + Cash(h.PerSetup) + " (" + h.Setups + ")")))).Append("</div>");
            }
            // LIVE ACCOUNT.
            KeystoneArcLiveSettings liveSet = lastLiveSettings ?? ReadLiveSettings();
            KeystoneArcLiveResult liveRes = lastLiveResult ?? KeystoneArcLiveAccount.Simulate(events, config, liveSet);
            sb.Append("<h2 id='live-account'>LIVE ACCOUNT • personal account on the same setups</h2><pre class='cmp'>").Append(Hx(KeystoneArcLiveAccount.Summary(liveRes, liveSet))).Append("</pre>");
            // AI analysis.
            sb.Append("<h2 id='analysis'>AI ANALYSIS • WHAT THE NUMBERS SAY</h2><div class='muted'>Written automatically from this run only. Every sentence points at a number in this report; nothing is predicted. For deeper optimisation use EXPORT FOR CLAUDE in the lab and share the file.</div><div class='insights'>");
            foreach (KeystoneArcInsight f in KeystoneArcAnalyst.Analyze(accounts, accepted, config, capital))
                sb.Append("<div class='insight ").Append(f.Level.ToLowerInvariant()).Append("'><div class='tag'>").Append(Hx(f.Level)).Append("</div><div><b>").Append(Hx(f.Title)).Append("</b><br>").Append(Hx(f.Text)).Append("</div></div>");
            sb.Append("</div>");
            // Month table.
            var stratByMonth = days.GroupBy(d => new DateTime(d.Day.Year, d.Day.Month, 1)).ToDictionary(g => g.Key, g => g.ToList());
            sb.Append("<h2 id='months'>MONTHS</h2><div class='table-wrap'><table><thead><tr><th>#</th><th>Month</th><th>").Append(asian ? "Nights" : "Days").Append("</th><th>Win %</th><th>Strategy P/L</th><th>Payouts</th><th>To bank</th><th>Cost</th><th>Net</th><th>Net to date</th></tr></thead><tbody>");
            var allMonths = stratByMonth.Keys.Union(monthRows.Select(g => g.Key)).Distinct().OrderBy(m => m).ToList(); running = 0; int mi = 0;
            foreach (DateTime m in allMonths)
            {
                List<KeystoneArcDayScore> md; stratByMonth.TryGetValue(m, out md); md = md ?? new List<KeystoneArcDayScore>();
                var g = monthRows.FirstOrDefault(r => r.Key == m);
                double bank = g == null ? 0 : g.Sum(d => d.PayoutCashDelta), cost = g == null ? 0 : g.Sum(d => d.CostDelta); int pays = g == null ? 0 : accounts.Sum(a => a.DayHistory.Where(d => d.Day.Year == m.Year && d.Day.Month == m.Month && d.PayoutCashDelta > 0).Count());
                running += bank - cost; double p = md.Sum(d => d.Pnl);
                sb.Append("<tr class='").Append(bank - cost > 0 ? "win" : (bank - cost < 0 ? "loss" : "")).Append("'><td>").Append(++mi).Append("</td><td>").Append(m.ToString("yyyy-MM")).Append("</td><td>").Append(md.Count).Append("</td><td>").Append(md.Count == 0 ? "—" : (100.0 * md.Count(d => d.Pnl > 0) / md.Count).ToString("0") + "%").Append("</td><td class='").Append(p >= 0 ? "green" : "red").Append("'>").Append(Hx(Cash(p))).Append("</td><td>").Append(pays).Append("</td><td class='gold'>").Append(Hx(Cash(bank))).Append("</td><td class='orchid'>").Append(Hx(Cash(cost))).Append("</td><td class='").Append(bank - cost >= 0 ? "green" : "red").Append("'>").Append(Hx(Cash(bank - cost))).Append("</td><td>").Append(Hx(Cash(running))).Append("</td></tr>");
            }
            sb.Append("</tbody></table></div>");
            // Account cards with filters.
            sb.Append("<h2 id='account-cards'>ACCOUNTS</h2><div class='filters' id='acctFilters'><button class='active' data-f='all'>ALL</button><button data-f='funded'>FUNDED NOW</button><button data-f='eval'>IN EVALUATION</button><button data-f='paid'>PAID</button><button data-f='never'>NEVER PAID</button><button data-f='blown'>HAD BLOWUPS</button><input id='acctSearch' placeholder='search account…'></div><div class='acct-grid' id='acctGrid'>");
            foreach (KeystoneArcVirtualAccount a in accounts)
            {
                string state = a.Funded && !a.Blown ? "funded" : (!a.Funded && !a.Blown && !a.ReplacementPending ? "eval" : "other");
                int blows = a.FailedEvaluations + a.FailedFunded;
                string cls = a.Funded && !a.Blown ? "st-funded" : (a.Blown && !a.ReplacementPending ? "st-ended" : "st-eval");
                sb.Append("<div class='acct ").Append(cls).Append("' data-state='").Append(state).Append("' data-paid='").Append(a.Payouts > 0 ? "1" : "0").Append("' data-blown='").Append(blows > 0 ? "1" : "0").Append("' data-name='").Append(Hx(a.Name.ToLowerInvariant())).Append("'>");
                sb.Append("<div class='acct-head'><b>").Append(Hx(a.Name)).Append("</b><span>").Append(Hx(AccountLifecycleLabel(a))).Append("</span></div>");
                sb.Append("<div class='acct-row'><span>Payouts</span><b>").Append(a.Payouts).Append("</b></div>");
                sb.Append("<div class='acct-row'><span>First → latest</span><b>").Append(a.FirstPayoutDate == DateTime.MinValue ? "—" : a.FirstPayoutDate.ToString("yyyy-MM-dd") + (a.LastPayoutDate > a.FirstPayoutDate ? " → " + a.LastPayoutDate.ToString("yyyy-MM-dd") : "")).Append("</b></div>");
                sb.Append("<div class='acct-row'><span>To bank / cost</span><b>").Append(Hx(Cash(a.PayoutCash))).Append(" / ").Append(Hx(Cash(a.EvaluationCost))).Append("</b></div>");
                sb.Append("<div class='acct-row'><span>Net</span><b class='").Append(a.PayoutCash - a.EvaluationCost >= 0 ? "green" : "red").Append("'>").Append(Hx(Cash(a.PayoutCash - a.EvaluationCost))).Append("</b></div>");
                sb.Append("<div class='acct-row'><span>Blowups</span><b class='").Append(blows > 0 ? "red" : "green").Append("'>").Append(blows).Append("</b></div>");
                if (a.Funded && !a.Blown) sb.Append("<div class='acct-row'><span>Carry-over balance</span><b>").Append(Hx(Cash(a.FundedBalance))).Append("</b></div>");
                sb.Append("</div>");
            }
            sb.Append("</div><script>(function(){var f='all',q='';var cards=[].slice.call(document.querySelectorAll('#acctGrid .acct'));function show(){cards.forEach(function(c){var ok=f==='all'||(f==='funded'&&c.dataset.state==='funded')||(f==='eval'&&c.dataset.state==='eval')||(f==='paid'&&c.dataset.paid==='1')||(f==='never'&&c.dataset.paid==='0')||(f==='blown'&&c.dataset.blown==='1');if(q&&c.dataset.name.indexOf(q)<0)ok=false;c.style.display=ok?'':'none';});}[].slice.call(document.querySelectorAll('#acctFilters button')).forEach(function(b){b.addEventListener('click',function(){[].slice.call(document.querySelectorAll('#acctFilters button')).forEach(function(o){o.classList.remove('active');});b.classList.add('active');f=b.dataset.f;show();});});document.getElementById('acctSearch').addEventListener('input',function(e){q=e.target.value.toLowerCase();show();});})();</script>");
            sb.Append("<h2 class='audit-head'>DETAILED AUDIT</h2><div class='muted'>Everything below is the full original audit: every rule, cycle, account and event.</div></section>");
            return sb.ToString();
        }

        private string BuildEvidencePackageIndex(string evidenceSection)
        {
            string report = BuildHtmlReport();
            int anchor = report.LastIndexOf("<p class='footer'>", StringComparison.OrdinalIgnoreCase);
            if (anchor < 0) anchor = report.LastIndexOf("</div><script>", StringComparison.OrdinalIgnoreCase);
            if (anchor < 0) return report + (evidenceSection ?? string.Empty);
            return report.Insert(anchor, evidenceSection ?? string.Empty);
        }

        private int ExportInstrumentEvidence(string root, string symbol, List<KeystoneArcBar> sourceBars, List<KeystoneArcEvent> sourceEvents, KeystoneArcRunConfig cfg, StringBuilder manifest)
        {
            List<KeystoneArcEvent> rows = sourceEvents.Where(x => string.Equals(x.Symbol, symbol, StringComparison.OrdinalIgnoreCase)).OrderBy(x => x.TriggerTime).ToList();
            string folder = Path.Combine(root, symbol); Directory.CreateDirectory(folder);
            File.WriteAllText(Path.Combine(folder, symbol + "_events.csv"), EventCsv(rows), Encoding.UTF8);
            File.WriteAllText(Path.Combine(folder, symbol + "_summary.html"), BuildInstrumentEvidenceSummaryHtml(symbol, rows, cfg), Encoding.UTF8);
            var index = new StringBuilder(); index.Append("<!doctype html><html><head><meta charset='utf-8'><title>").Append(symbol).Append(" evidence</title><style>body{background:#09111f;color:#edf3ff;font:15px Segoe UI,Arial;margin:32px}a{color:#4bd9ff}li{margin:8px}.notice{color:#f6c64e}</style></head><body><h1>").Append(symbol).Append(" Evidence Charts</h1><p><a href='").Append(symbol).Append("_summary.html'>Open ").Append(symbol).Append(" summary and data explanation</a> • <a href='").Append(symbol).Append("_events.csv'>Open full event ledger CSV</a></p><p class='notice'>Each numbered SVG is the exact selected setup-bar chart for one tested session. Elevated badges and dashed leaders point to the exact entry-price line without covering candle bodies or wicks.</p><ol>");
            int number = 0;
            foreach (IGrouping<DateTime, KeystoneArcEvent> group in rows.GroupBy(x => KeystoneArcEngine.SessionGroupingDate(x.TriggerTime, cfg)).OrderBy(x => x.Key))
            {
                DateTime sessionStart = ConfiguredSessionStartFor(group.Key, cfg), sessionEnd = TradingSessionEndFor(group.Key, cfg);
                List<KeystoneArcBar> bars = sourceBars.Where(x => x.Time >= sessionStart && x.Time <= sessionEnd).OrderBy(x => x.Time).ToList();
                if (bars.Count == 0) continue;
                number++;
                string name = number.ToString("D3") + "_" + group.Key.ToString("yyyy-MM-dd") + "_" + symbol + "_setup_evidence.svg";
                File.WriteAllText(Path.Combine(folder, name), BuildEvidenceSvg(symbol, group.Key, bars, group.OrderBy(x => x.TriggerTime).ToList(), cfg), Encoding.UTF8);
                index.Append("<li><a href='").Append(Html(name)).Append("'>").Append(Html(name)).Append("</a> • ").Append(group.Count()).Append(" detected setup(s)</li>");
            }
            if (number == 0) index.Append("<li>No detected setups for this instrument in the selected test range.</li>");
            index.Append("</ol></body></html>"); File.WriteAllText(Path.Combine(folder, "index.html"), index.ToString(), Encoding.UTF8);
            manifest.Append("<li><a href='").Append(symbol).Append("/index.html'>").Append(symbol).Append(" evidence folder</a> • ").Append(number).Append(" session chart(s) • <a href='").Append(symbol).Append("/").Append(symbol).Append("_summary.html'>summary</a></li>");
            return number;
        }

        private string BuildInstrumentEvidenceSummaryHtml(string symbol, List<KeystoneArcEvent> rows, KeystoneArcRunConfig cfg)
        {
            bool outcomesVerified = cfg != null && cfg.OutcomeModelEnabled == 1;
            bool asian = cfg != null && string.Equals(cfg.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase);
            string itemLabel = asian ? "REVERSAL LEGS" : "DETECTED SETUPS";
            int wins = rows.Count(x => x.Outcome == "WIN"), losses = rows.Count(x => x.Outcome.StartsWith("LOSS")), exits = rows.Count(x => x.Outcome == "SESSION EXIT"), noEntry = rows.Count(x => x.Outcome == "NO ENTRY DATA");
            double gross = rows.Sum(x => x.GrossPnl);
            var sb = new StringBuilder();
            sb.Append("<!doctype html><html><head><meta charset='utf-8'><title>").Append(symbol).Append(" Keystone Evidence Summary</title><style>body{background:#09111f;color:#edf3ff;font:15px Segoe UI,Arial;margin:32px;line-height:1.45}.card{background:#142039;border:1px solid #2cd7cb;border-radius:10px;padding:16px;margin:14px 0}.grid{display:flex;flex-wrap:wrap;gap:10px}.metric{min-width:150px;background:#111b2d;border:1px solid #2f4669;border-radius:8px;padding:12px}.label{color:#9baec6;font-size:11px;font-weight:700}.value{font-size:22px;font-weight:700;color:#edf3ff}.violet{color:#e563ff}.amber{color:#ffbe3b}.ice{color:#9ee0ff}.cyan{color:#39d9ff}table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:8px;border-bottom:1px solid #2f4669;text-align:left}th{color:#39d9ff}.note{color:#f6c64e}</style></head><body>");
            sb.Append("<h1>").Append(symbol).Append(" • SpasiX Future Evidence Summary</h1><div class='card'><strong>Tested range:</strong> ").Append(Html(SessionDateLabel(cfg))).Append("<br><strong>Setup timeframe:</strong> ").Append(cfg.SetupMinutes).Append(" minutes<br><strong>Session:</strong> ").Append(Html(cfg.SessionMode)).Append("<br><strong>Outcome boundary:</strong> historical model only; use the chart SVGs to validate setup placement before relying on any outcome aggregation.</div>");
            sb.Append("<div class='grid'><div class='metric'><div class='label'>").Append(itemLabel).Append("</div><div class='value cyan'>").Append(rows.Count).Append("</div></div><div class='metric'><div class='label'>OUTCOME STATUS</div><div class='value ").Append(outcomesVerified ? "violet'>VERIFIED 1M" : "amber'>NOT AVAILABLE").Append("</div></div>");
            if (outcomesVerified) sb.Append("<div class='metric'><div class='label'>WINS</div><div class='value violet'>").Append(wins).Append("</div></div><div class='metric'><div class='label'>LOSSES</div><div class='value amber'>").Append(losses).Append("</div></div><div class='metric'><div class='label'>SESSION EXITS</div><div class='value ice'>").Append(exits).Append("</div></div><div class='metric'><div class='label'>MODEL GROSS</div><div class='value'>").Append(Html(gross.ToString("C0"))).Append("</div></div>");
            sb.Append("</div>");
            sb.Append("<p class='note'>").Append(outcomesVerified ? "No-entry rows: " + noEntry + ". The CSV contains the complete resolved model ledger and pool decision." : "The matching 1-minute series was not proven against the selected setup bars. This package intentionally contains setup placements and no win/loss, exit, P/L, pool, balance, or payout claim.").Append("</p>");
            sb.Append(outcomesVerified ? "<h2>Session chart index</h2><table><thead><tr><th>Session date</th><th>" + (asian ? "Reversal legs" : "Setups") + "</th><th>Wins</th><th>Losses</th><th>Session exits</th><th>Model P/L</th></tr></thead><tbody>" : "<h2>Session chart index • setup placement only</h2><table><thead><tr><th>Session date</th><th>" + (asian ? "Reversal legs" : "Setups") + "</th><th>Outcome status</th></tr></thead><tbody>");
            foreach (var g in rows.GroupBy(x => KeystoneArcEngine.SessionGroupingDate(x.TriggerTime, cfg)).OrderBy(x => x.Key))
            {
                if (outcomesVerified) sb.Append("<tr><td>").Append(g.Key.ToString("yyyy-MM-dd")).Append("</td><td>").Append(g.Count()).Append("</td><td>").Append(g.Count(x => x.Outcome == "WIN")).Append("</td><td>").Append(g.Count(x => x.Outcome.StartsWith("LOSS"))).Append("</td><td>").Append(g.Count(x => x.Outcome == "SESSION EXIT")).Append("</td><td>").Append(Html(g.Sum(x => x.GrossPnl).ToString("C0"))).Append("</td></tr>");
                else sb.Append("<tr><td>").Append(g.Key.ToString("yyyy-MM-dd")).Append("</td><td>").Append(g.Count()).Append("</td><td class='amber'>UNVERIFIED 1M</td></tr>");
            }
            sb.Append("</tbody></table></body></html>"); return sb.ToString();
        }

        private static DateTime ConfiguredSessionStartFor(DateTime date, KeystoneArcRunConfig cfg)
        {
            DateTime start, end;
            GetConfiguredSessionBounds(date.Date, date.Date, cfg, out start, out end);
            return start;
        }

        private static DateTime TradingSessionEndFor(DateTime date, KeystoneArcRunConfig cfg)
        {
            DateTime start, end;
            GetConfiguredSessionBounds(date.Date, date.Date, cfg, out start, out end);
            return end;
        }

        private static string BuildEvidenceSvg(string symbol, DateTime day, List<KeystoneArcBar> bars, List<KeystoneArcEvent> marks, KeystoneArcRunConfig cfg)
        {
            const double height = 900, left = 85, top = 132, bottom = 70, right = 24;
            double candle = cfg.SetupMinutes <= 1 ? 8 : 18, width = Math.Max(1500, left + right + bars.Count * candle);
            double min = bars.Min(x => x.Low), max = bars.Max(x => x.High); foreach (KeystoneArcEvent e in marks) { min = Math.Min(min, e.Entry); max = Math.Max(max, e.Entry); }
            double pad = Math.Max((max - min) * .09, symbol == "MGC" ? 1 : 8); min -= pad; max += pad;
            Func<double, double> y = p => top + (max - p) / Math.Max(.0000001, max - min) * (height - top - bottom);
            bool asian = cfg != null && string.Equals(cfg.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase);
            var sb = new StringBuilder(); sb.Append("<svg xmlns='http://www.w3.org/2000/svg' width='").Append(width.ToString("0", CultureInfo.InvariantCulture)).Append("' height='900' viewBox='0 0 ").Append(width.ToString("0", CultureInfo.InvariantCulture)).Append(" 900'><rect width='100%' height='100%' fill='#0a0f1a'/>");
            sb.Append("<text x='").Append(left).Append("' y='24' fill='#52e0d5' font-family='Segoe UI,Arial' font-size='18' font-weight='700'>").Append(Html(symbol)).Append(" • SESSION ").Append(day.ToString("yyyy-MM-dd")).Append(" • DIRECT ").Append(cfg.SetupMinutes).Append("M SETUP BARS • ").Append(bars.Count).Append(" CANDLES • ").Append(marks.Count).Append(asian ? " ASIAN REVERSAL LEGS" : " DETECTED SETUPS").Append("</text>");
            sb.Append("<text x='").Append(left).Append("' y='48' fill='#dce9f8' font-family='Segoe UI,Arial' font-size='12'>Compact circle: S = setup awaiting verified 1M outcome • W = win • L = loss • E = session exit. Full data are in the package index.</text>");
            for (int p = 0; p <= 5; p++) { double price = min + (max - min) * p / 5, py = y(price); sb.Append("<text x='5' y='").Append((py + 4).ToString("0.0", CultureInfo.InvariantCulture)).Append("' fill='#dce9f8' font-family='Consolas' font-size='11'>").Append(price.ToString(symbol == "MGC" ? "0.0" : "0.00", CultureInfo.InvariantCulture)).Append("</text>"); }
            var index = new Dictionary<DateTime, int>();
            for (int i = 0; i < bars.Count; i++) { KeystoneArcBar b = bars[i]; index[b.Time] = i; double x = left + i * candle + candle / 2, oy = y(b.Open), cy = y(b.Close), hy = y(b.High), ly = y(b.Low); string color = b.Close > b.Open ? "#309780" : (b.Close < b.Open ? "#bc526a" : "#d0a74e"); sb.Append("<line x1='").Append(x.ToString("0.0", CultureInfo.InvariantCulture)).Append("' x2='").Append(x.ToString("0.0", CultureInfo.InvariantCulture)).Append("' y1='").Append(hy.ToString("0.0", CultureInfo.InvariantCulture)).Append("' y2='").Append(ly.ToString("0.0", CultureInfo.InvariantCulture)).Append("' stroke='#c2d3e4' stroke-width='1.25'/><rect x='").Append((x - candle / 2 + 2).ToString("0.0", CultureInfo.InvariantCulture)).Append("' y='").Append(Math.Min(oy, cy).ToString("0.0", CultureInfo.InvariantCulture)).Append("' width='").Append(Math.Max(2, candle - 4).ToString("0.0", CultureInfo.InvariantCulture)).Append("' height='").Append(Math.Max(1, Math.Abs(cy - oy)).ToString("0.0", CultureInfo.InvariantCulture)).Append("' fill='").Append(color).Append("' stroke='#c2d3e4' stroke-width='.55'/>"); if (b.Time.Minute == 0 || i == 0) sb.Append("<text x='").Append((x - 14).ToString("0.0", CultureInfo.InvariantCulture)).Append("' y='").Append(height - 34).Append("' fill='#9aabc0' font-family='Consolas' font-size='10'>").Append(b.Time.ToString("HH:mm")).Append("</text>"); }
            var svgGroups = marks.Select(mark => new { Event = mark, Index = EvidenceEntryBarIndex(bars, mark) }).Where(marker => marker.Index >= 0).GroupBy(marker => marker.Index).OrderBy(group => group.Key).ToList();
            var edges = new double[] { double.MinValue, double.MinValue, double.MinValue, double.MinValue };
            for (int groupNumber = 0; groupNumber < svgGroups.Count; groupNumber++)
            {
                List<KeystoneArcEvent> grouped = svgGroups[groupNumber].Select(marker => marker.Event).OrderBy(record => record.TriggerTime).ToList();
                KeystoneArcEvent e = grouped[0];
                int i = svgGroups[groupNumber].Key;
                double x = left + i * candle + candle / 2, hy = y(bars[i].High);
                string result = e.Outcome == "UNVERIFIED 1M" ? "#39d9ff" : (e.Outcome == "WIN" ? "#c269ff" : (e.Outcome.StartsWith("LOSS") ? "#ffba46" : "#99daff"));
                int wins = grouped.Count(record => record.Outcome == "WIN"), losses = grouped.Count(record => record.Outcome.StartsWith("LOSS")), exits = grouped.Count(record => record.Outcome == "SESSION EXIT");
                if (grouped.Count > 1) result = wins > 0 && losses == 0 && exits == 0 ? "#c269ff" : (losses > 0 && wins == 0 && exits == 0 ? "#ffba46" : "#39d9ff");
                int lane = 0; for (; lane < edges.Length; lane++) if (x - edges[lane] >= 31) break; if (lane >= edges.Length) lane = Array.IndexOf(edges, edges.Min());
                double markerX = x + (i % 2 == 0 ? 9 : -9), pinY = Math.Max(top + 6, hy - 23 - lane * 17), pinX = Math.Max(left, markerX - 8), leaderY = pinY + 16;
                string shortResult = grouped.Count == 1 ? (e.Outcome == "UNVERIFIED 1M" ? "↑" : (e.Outcome == "WIN" ? "W" : (e.Outcome.StartsWith("LOSS") ? "L" : "E"))) : grouped.Count.ToString(CultureInfo.InvariantCulture);
                sb.Append("<line x1='").Append(markerX.ToString("0.0", CultureInfo.InvariantCulture)).Append("' y1='").Append(leaderY.ToString("0.0", CultureInfo.InvariantCulture)).Append("' x2='").Append(x.ToString("0.0", CultureInfo.InvariantCulture)).Append("' y2='").Append((hy - 2).ToString("0.0", CultureInfo.InvariantCulture)).Append("' stroke='").Append(result).Append("' stroke-width='2' stroke-dasharray='5 5' opacity='.50'/><circle cx='").Append((pinX + 8).ToString("0.0", CultureInfo.InvariantCulture)).Append("' cy='").Append((pinY + 8).ToString("0.0", CultureInfo.InvariantCulture)).Append("' r='8' fill='").Append(result).Append("' stroke='#101623'/><text x='").Append((pinX + 5.2).ToString("0.0", CultureInfo.InvariantCulture)).Append("' y='").Append((pinY + 11.2).ToString("0.0", CultureInfo.InvariantCulture)).Append("' fill='#101623' font-family='Segoe UI,Arial' font-size='8' font-weight='700'>").Append(shortResult).Append("</text>");
                edges[lane] = pinX + 16;
            }
            return sb.Append("</svg>").ToString();
        }

        private string BuildHtmlReport()
        {
            List<KeystoneArcEvent> all = events.OrderBy(x => x.EntryTime == DateTime.MinValue ? x.TriggerTime : x.EntryTime).ToList();
            List<KeystoneArcEvent> accepted = all.Where(x => string.Equals(x.ReviewState, "ACCEPTED", StringComparison.OrdinalIgnoreCase)).ToList();
            bool outcomesVerified = config.OutcomeModelEnabled == 1;
            int wins = all.Count(x => x.Outcome == "WIN");
            int losses = all.Count(x => x.Outcome.StartsWith("LOSS", StringComparison.OrdinalIgnoreCase));
            int exits = all.Count(x => x.Outcome == "SESSION EXIT");
            int noEntry = all.Count(x => x.Outcome == "NO ENTRY DATA");
            bool asianReport = string.Equals(config.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase);
            string strategyName = asianReport ? "Asian Cycle Backtest • Copy Trading" : string.Equals(config.StrategyCode, "GLD", StringComparison.OrdinalIgnoreCase) ? "Golden Setup • First BH / FVG After The Open" : (string.Equals(config.StrategyCode, "RLY", StringComparison.OrdinalIgnoreCase) ? "Last-Hour Relay • Time Momentum" : string.Equals(config.StrategyCode, "VWP", StringComparison.OrdinalIgnoreCase) ? "VWAP Snap-Back • Midday Reversion" : string.Equals(config.StrategyCode, "ENG", StringComparison.OrdinalIgnoreCase) ? "123 Engulfing • Buy / Sell" : (string.Equals(config.StrategyCode, "FVG", StringComparison.OrdinalIgnoreCase) ? "FVG Retest • Long" : "BH Long • Break-High"));
            string strategyAudit = asianReport ? "MNQ + MGC • exact " + config.AsianStartHhmm.ToString("0000") + " ET simultaneous start • " + config.AsianMnqInitialDirection + " MNQ / " + config.AsianMgcInitialDirection + " MGC • " + (config.AsianRiskMode == "PRICE" ? "instrument price-move reversal limits" : "fixed cash reversal limits") + " • next-minute opposite entry • +1 micro per leg • combined boundaries close-confirmed" : "red candle • bullish reference close • immediate next-bar high break";
            int poolWins = accepted.Count(x => x.Outcome == "WIN");
            int poolLosses = accepted.Count(x => x.Outcome.StartsWith("LOSS", StringComparison.OrdinalIgnoreCase));
            int poolExits = accepted.Count(x => x.Outcome == "SESSION EXIT");
            int assigned = accepted.Count(x => !string.IsNullOrWhiteSpace(x.AssignedVirtualAccount));
            int skipped = accepted.Count(x => !string.IsNullOrWhiteSpace(x.SkipReason));
            int excluded = all.Count(x => !string.Equals(x.ReviewState, "ACCEPTED", StringComparison.OrdinalIgnoreCase));
            double gross = all.Sum(x => x.GrossPnl);
            double poolGross = accepted.Sum(x => x.GrossPnl);
            bool personalReport = string.Equals(config.AccountPath, "PERSONAL", StringComparison.OrdinalIgnoreCase);
            int testedDays = EvidenceSessionDateCount();
            List<KeystoneArcEvent> finalLiveLedger = personalReport ? FinalLiveAccountLedger() : new List<KeystoneArcEvent>();
            bool liveLedgerReady = personalReport && HasFinalLiveAccountLedger();
            int liveRangeTrades = finalLiveLedger.Count;
            double liveAccountGross = finalLiveLedger.Sum(x => x.GrossPnl);
            int liveWins = finalLiveLedger.Count(x => x.Outcome == "WIN");
            int liveLosses = finalLiveLedger.Count(x => x.Outcome.StartsWith("LOSS", StringComparison.OrdinalIgnoreCase));
            int liveExits = finalLiveLedger.Count(x => x.Outcome == "SESSION EXIT");
            int liveNotSelected = accepted.Count(x => string.IsNullOrWhiteSpace(x.AssignedVirtualAccount) && !string.IsNullOrWhiteSpace(x.SkipReason));
            double payoutCash = accounts.Sum(x => x.PayoutCash);
            double evaluationCost = accounts.Sum(x => x.EvaluationCost);
            double netCashAfterEvaluationCost = payoutCash - evaluationCost;
            KeystoneArcCapitalPolicySummary capital = KeystoneArcEngine.BuildCapitalPolicySummary(accounts, config);
            List<KeystoneArcPayoutCycleRow> payoutCycles = KeystoneArcEngine.BuildPayoutCycleRows(accounts, config);
            List<KeystoneArcBalanceMatrixRow> balanceMatrix = KeystoneArcEngine.BuildBalanceMatrixRows(accounts, config);
            int evaluationPasses = accounts.Sum(x => x.EvaluationPasses);
            int currentlyFunded = accounts.Count(x => x.Funded);
            string payoutExplanation = config.EvaluationEnabled < 0 ? "One-day study: lifecycle is off."
                : (config.EvaluationEnabled == 0 ? (payoutCash > 0 ? "Payout cycle(s) recorded." : "Direct-funded slots have not met the selected payout gate.")
                : (payoutCash > 0 ? "Payout cycle(s) recorded." : (evaluationPasses == 0 ? "No evaluation passed the selected gate." : (currentlyFunded == 0 ? "No slot is currently funded." : "Funded slots have not met the selected payout gate."))));
            KeystoneArcRiskSequenceStats personalRisk = CalculateRiskSequenceStats(personalReport ? finalLiveLedger : all, config.PersonalStartingBalance);
            KeystoneArcRiskSequenceStats propRisk = CalculateWorstVirtualAccountRisk(config.PropStartingBalance);
            var sb = new StringBuilder();
