        private string BuildStudyScopeLabel()
        {
            if (config == null || config.Start == DateTime.MinValue) return "CURRENT STUDY • configure a date, session, instruments, and setup timeframe.";
            bool asian = string.Equals(config.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase);
            string setup = asian ? "ASIAN CYCLE BACKTEST • COPY" : StrategyDisplayName();
            string detail = asian
                ? config.AsianStartHhmm.ToString("0000") + " ET " + config.AsianMnqInitialDirection + " MNQ / " + config.AsianMgcInitialDirection + " MGC • " + (config.AsianRiskMode == "PRICE" ? "PRICE-MOVE REVERSALS" : "FIXED-CASH REVERSALS")
                : (string.Equals(config.StrategyCode, "RLY", StringComparison.OrdinalIgnoreCase) ? "LAST-HOUR RELAY" : string.Equals(config.StrategyCode, "VWP", StringComparison.OrdinalIgnoreCase) ? "VWAP SNAP-BACK" : string.Equals(config.StrategyCode, "ENG", StringComparison.OrdinalIgnoreCase) ? "123 ENGULFING" : string.Equals(config.StrategyCode, "FVG", StringComparison.OrdinalIgnoreCase) ? "FVG RETEST" : (config.BhAggressionFilter == "STRONGER" ? "STRONGER BH" : "ALL VALID BH"));
            return "CURRENT STUDY • SESSION DATE(S) " + SessionDateLabel(config) + " • DATA WINDOW " + config.Start.ToString("yyyy-MM-dd HH:mm") + " → " + config.End.ToString("yyyy-MM-dd HH:mm") + " • " + config.Scope + " • " + config.SessionMode + " • " + config.SetupMinutes + "M • " + setup + " • " + detail;
        }

        private string BuildEvidenceStudyLabel()
        {
            if (config == null || config.Start == DateTime.MinValue) return "CURRENT TEST RANGE • not configured";
            string setup = string.Equals(config.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase) ? "ASIAN 75 REVERSAL • COPY • FIXED 1M" : (HelixStudy() ? "HELIX ROTATION BASKETS" : RecoilStudy() ? "RECOIL LADDERS" : string.Equals(config.StrategyCode, "GLD", StringComparison.OrdinalIgnoreCase) ? "GOLDEN SETUP" : string.Equals(config.StrategyCode, "ASIAN75", StringComparison.OrdinalIgnoreCase) ? "ASIAN 75 CYCLE" : (string.Equals(config.StrategyCode, "RLY", StringComparison.OrdinalIgnoreCase) ? "LAST-HOUR RELAY" : string.Equals(config.StrategyCode, "VWP", StringComparison.OrdinalIgnoreCase) ? "VWAP SNAP-BACK" : string.Equals(config.StrategyCode, "ENG", StringComparison.OrdinalIgnoreCase) ? "123 ENGULFING" : string.Equals(config.StrategyCode, "FVG", StringComparison.OrdinalIgnoreCase) ? "FVG RETEST" : (config.BhAggressionFilter == "STRONGER" ? "STRONGER BH FILTER" : "ALL VALID BH")));
            return "CURRENT TEST RANGE • " + SessionDateLabel(config) + " • " + config.Scope + " • " + config.SessionMode + " • " + config.SetupMinutes + "-MINUTE SETUPS • " + setup + " • SELECT A DATE TAB BELOW TO INSPECT ONE COMPLETE SESSION";
        }
        private static void GetConfiguredSessionBounds(DateTime firstDate, DateTime lastDate, KeystoneArcRunConfig cfg, out DateTime start, out DateTime end)
        {
            bool overnight = KeystoneArcEngine.UsesOvernightSessionDate(cfg);
            int startHhmm = cfg.SessionMode == "ASIA" ? 1900 : ((cfg.SessionMode == "FULL_GLOBEX" || cfg.SessionMode == "ALL_ELIGIBLE") ? 1800 : (cfg.SessionMode == "ASIAN75" ? cfg.AsianStartHhmm : cfg.CustomStart));
            if (cfg.SessionMode == "LONDON") startHhmm = 300;
            if (cfg.SessionMode == "NY_EARLY") startHhmm = 800;
            if (cfg.SessionMode == "NY_OPEN" || cfg.SessionMode == "NY_AFTER_0930") startHhmm = 930;
            // BOTH must request from the earliest instrument-specific session (MGC 08:00).
            // The detector still applies MNQ 09:30 / MGC 08:00 independently, but the shared
            // chart and export window must never silently start at midnight.
            if (cfg.SessionMode == "INSTRUMENT_DEFAULT") startHhmm = 800;
            int endHhmm = cfg.SessionMode == "ASIA" ? 300 : (cfg.SessionMode == "LONDON" ? 1130 : (cfg.SessionMode == "ASIAN75" ? cfg.AsianEndHhmm : cfg.EndTime));
            start = firstDate.Date.AddHours(startHhmm / 100).AddMinutes(startHhmm % 100);
            end = lastDate.Date.AddHours(endHhmm / 100).AddMinutes(endHhmm % 100);
            if (overnight || end < start) end = end.AddDays(1);
        }
        private DateTime ConfiguredSessionStart(DateTime sessionDate)
        {
            if (config == null) return sessionDate.Date.AddHours(18);
            DateTime start, end; GetConfiguredSessionBounds(sessionDate.Date, sessionDate.Date, config, out start, out end); return start;
        }
        private DateTime TradingSessionEnd(DateTime sessionDate)
        {
            if (config == null) return sessionDate.Date.AddDays(1).AddHours(15).AddMinutes(55);
            DateTime start, end; GetConfiguredSessionBounds(sessionDate.Date, sessionDate.Date, config, out start, out end); return end;
        }
        private void UpdateUi(string text, Brush brush) { if (statusText != null) { statusText.Text = text; statusText.Foreground = brush; } }
        private static double Number(TextBox box, double fallback) { double v; return box != null && double.TryParse(box.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out v) && v > 0 ? v : fallback; }
        private static double NumberSigned(TextBox box, double fallback) { double v; return box != null && double.TryParse(box.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out v) ? v : fallback; }
        private static double NumberAllowZero(TextBox box, double fallback) { double v; return box != null && double.TryParse(box.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out v) && v >= 0 ? v : fallback; }
        private static int Integer(TextBox box, int fallback) { int v; return box != null && int.TryParse(box.Text, NumberStyles.Any, CultureInfo.InvariantCulture, out v) && v >= 0 ? v : fallback; }
        private static int Number(ComboBox box, int fallback) { int v; return box != null && int.TryParse((box.SelectedItem ?? "").ToString(), out v) ? v : fallback; }
        private static int SetupMinutesFromDisplay(string value)
        {
            string first = (value ?? string.Empty).Trim().Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries).FirstOrDefault();
            int minutes;
            return int.TryParse(first, out minutes) && (minutes == 1 || minutes == 5 || minutes == 15 || minutes == 30 || minutes == 60 || minutes == 240) ? minutes : 5;
        }
        private static string DirectionModeFromDisplay(string value)
        {
            string first = (value ?? string.Empty).Trim().Split(new[] { ' ', '•' }, StringSplitOptions.RemoveEmptyEntries).FirstOrDefault() ?? string.Empty;
            first = first.ToUpperInvariant();
            return first == "SS" || first == "SL" || first == "BS" ? first : "BB";
        }
        private static bool IsValidHhmm(int value) { return value >= 0 && value <= 2359 && value % 100 < 60; }
        private static string SessionModeFromDisplay(string value)
        {
            string v = (value ?? string.Empty).ToUpperInvariant();
            if (v.StartsWith("ASIAN 75")) return "ASIAN75";
            if (v.StartsWith("ASIA")) return "ASIA";
            if (v.StartsWith("LONDON")) return "LONDON";
            if (v.StartsWith("NY EARLY")) return "NY_EARLY";
            if (v.StartsWith("NY OPEN")) return "NY_OPEN";
            if (v.StartsWith("FULL GLOBEX")) return "FULL_GLOBEX";
            if (v.StartsWith("CUSTOM")) return "CUSTOM";
            return "INSTRUMENT_DEFAULT";
        }
        private static SolidColorBrush ColorBrush(byte r, byte g, byte b) { var x = new SolidColorBrush(Color.FromRgb(r, g, b)); x.Freeze(); return x; }
        private static string Cash(double value)
        {
            return value < 0 ? "-$" + Math.Abs(value).ToString("N0", CultureInfo.InvariantCulture) : "$" + value.ToString("N0", CultureInfo.InvariantCulture);
        }
        private static TextBlock MetricTile(Panel parent, string label, string initialValue, string caption, Brush accent, double minHeight = 82, double valueFontSize = 25)
        {
            var content = new StackPanel { Margin = new Thickness(5) };
            var title = new TextBlock { Text = label, Foreground = accent, FontSize = 10, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap };
            content.Children.Add(title);
            var value = new TextBlock { Text = initialValue, Foreground = accent, FontSize = valueFontSize, FontWeight = FontWeights.Bold, FontFamily = new FontFamily("Segoe UI"), TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 3, 0, 0) };
            content.Children.Add(value);
            var note = new TextBlock { Text = caption, Foreground = Muted, FontSize = 9, FontWeight = FontWeights.Normal, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 0) };
            content.Children.Add(note);
            var border = new Border { Background = Card, BorderBrush = accent, BorderThickness = new Thickness(1.5), CornerRadius = new CornerRadius(5), Padding = new Thickness(6), Margin = new Thickness(3), MinHeight = minHeight, Child = content };
            value.Tag = Tuple.Create(title, note, border);
            parent.Children.Add(border);
            return value;
        }

        private static void UpdateMetricTile(TextBlock value, string label, string displayedValue, string caption, Brush accent)
        {
            if (value == null) return;
            value.Text = displayedValue;
            value.Foreground = accent;
            value.ToolTip = caption;
            var parts = value.Tag as Tuple<TextBlock, TextBlock, Border>;
            if (parts == null) return;
            parts.Item1.Text = label;
            parts.Item1.Foreground = accent;
            parts.Item2.Text = caption;
            parts.Item3.BorderBrush = accent;
        }
        private static void CycleMetric(Panel parent, string label, string value, Brush accent, string explain)
        {
            CycleMetric(parent, label + " ⓘ", value, accent);
            var tile = parent.Children[parent.Children.Count - 1] as FrameworkElement;
            if (tile != null) tile.ToolTip = explain;
        }
        private static void CycleMetric(Panel parent, string label, string value, Brush accent)
        {
            var content = new StackPanel { Margin = new Thickness(5) };
            content.Children.Add(new TextBlock { Text = label, Foreground = accent, FontSize = 9, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap });
            content.Children.Add(new TextBlock { Text = value, Foreground = accent, FontSize = 16, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap });
            parent.Children.Add(new Border { Background = Card, BorderBrush = accent, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(4), Margin = new Thickness(2), MinHeight = 48, Child = content });
        }
        private static TextBlock Txt(string text, Brush brush, double size, FontWeight weight) { return new TextBlock { Text = text, Foreground = brush, FontSize = size, FontWeight = weight, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(6) }; }
        private static TextBox Input(string value) { return new TextBox { Text = value, Background = Card, Foreground = Text, Margin = new Thickness(6), Padding = new Thickness(5) }; }
        private static ComboBox Select(params string[] values) { var x = new ComboBox { Background = Card, Foreground = Text, Margin = new Thickness(6) }; foreach (string s in values) x.Items.Add(s); return x; }
        private static string ToolShortName(string tool)
        {
            switch (tool) { case "CURSOR": return "CURSOR"; case "HLINE": return "H-LINE"; case "VLINE": return "V-LINE"; case "TREND": return "TREND"; case "RAY": return "RAY"; case "RECT": return "RECT"; case "FVG": return "FVG"; case "FIB": return "FIB"; case "ARROWUP": return "UP"; case "ARROWDN": return "DOWN"; case "TEXT": return "TEXT"; case "LONG": return "LONG"; case "SHORT": return "SHORT"; case "CLEAR": return "CLEAR"; default: return tool; }
        }
        // STUDIO STRATEGY SETTINGS: the parameters each studio strategy shows (label • target object • field • choices)
        private static List<string[]> StudioStrategyParams(int kind)
        {
            var l = new List<string[]>();
            Action<string, string, string, string> p = (label, target, field, choices) => l.Add(new[] { label, target, field, choices ?? "" });
            if (kind >= 1 && kind <= 3) { p("TARGET PTS • MNQ (0 = 30)", "fvg", "MNQ", null); p("TARGET PTS • MGC (0 = 3)", "fvg", "MGC", null); }
            else if (kind == 4) { p("MIN DIP INTO THE BOX %", "cfg", "FvgMinDepthPercent", null); p("MIN GAP • MNQ PTS", "cfg", "FvgMnqMinGap", null); p("MIN GAP • MGC PTS", "cfg", "FvgMgcMinGap", null); p("TRIES PER BOX", "cfg", "FvgMaxEntriesPerBox", null); p("STOP", "cfg", "FvgStopMode", "FORMATION_LOW,BOX,GREEN_LOW,FIXED"); }
            else if (kind == 5) { p("TARGET MOVE • MNQ PTS", "cfg", "MnqTargetMove", null); p("TARGET MOVE • MGC PTS", "cfg", "MgcTargetMove", null); p("STOP MOVE • MNQ PTS", "cfg", "MnqStandardStopMove", null); p("STOP MOVE • MGC PTS", "cfg", "MgcStandardStopMove", null); p("STOP OFFSET • MNQ PTS", "cfg", "MnqStopOffsetPoints", null); p("STOP OFFSET • MGC PTS", "cfg", "MgcStopOffsetPoints", null); }
            else if (kind == 6) { p("STOP", "cfg", "GoldenStopMode", "PATTERN,FIXED"); p("TARGET MOVE • MNQ PTS", "cfg", "MnqTargetMove", null); p("TARGET MOVE • MGC PTS", "cfg", "MgcTargetMove", null); }
            else if (kind == 7)
            {
                p("START (HHMM, NY)", "cfg", "AsianStartHhmm", null); p("END (HHMM, NY)", "cfg", "AsianEndHhmm", null);
                p("FIRST LEG • MNQ", "cfg", "AsianMnqInitialDirection", "LONG,SHORT"); p("FIRST LEG • MGC", "cfg", "AsianMgcInitialDirection", "LONG,SHORT");
                p("REVERSE AFTER A LOSS OF $", "cfg", "AsianReversalLossDollars", null); p("REVERSAL MOVE • MNQ PTS", "cfg", "AsianMnqReversalPriceMove", null); p("REVERSAL MOVE • MGC PTS", "cfg", "AsianMgcReversalPriceMove", null);
                p("CYCLE TARGET $", "cfg", "AsianCycleTargetDollars", null); p("MAX REVERSALS • MNQ", "cfg", "AsianMnqMaxReversals", null); p("MAX REVERSALS • MGC", "cfg", "AsianMgcMaxReversals", null);
                p("MAX LEGS PER INSTRUMENT", "cfg", "AsianMaxTotalLegsPerInstrument", null); p("STARTING CONTRACTS", "cfg", "AsianStartingQuantity", null);
                p("COMBINED STOP $", "cfg", "AsianCombinedStopLossDollars", null); p("DAILY LOSS LIMIT $", "cfg", "AsianDailyLossLimitDollars", null);
            }
            else if (kind == 11)
            {
                string r = "rule3";
                p("OPENING TIME (HHMM, NY)", r, "OpenHhmm", null); p("FVG CANDLES (MINUTES)", r, "FvgMinutes", "5,1,2,3,15"); p("THE 09:30 CANDLE IS THE FVG'S (0 = FIRST CANDLE • 1 = MIDDLE / GAP CANDLE)", r, "FvgFrom", "0,1");
                p("ENTRY AT % OF THE FVG ZONE", r, "FvgPct", "50,10,15,25,33,40,60,75"); p("STOP $ (THE BLOW-UP)", r, "StopUsd", null); p("TARGET $", r, "TargetUsd", null);
                p("INSTRUMENTS", r, "Symbols", "MNQ,MGC,BOTH"); p("CONTRACTS (= your contracts) • the $ → points", r, "Contracts", null); p("FUNDED: STOP $ (0 = SAME)", r, "FundStopUsd", null); p("FUNDED: TARGET $ (0 = SAME)", r, "FundTargetUsd", null);
                p("THE ZONE GROWS WITH (ALL = every FVG the same way until filled • ROW = only FVGs in a row)", r, "JoinMode", "ALL,ROW"); p("FILTER: FVGS IN THE ZONE AT LEAST", r, "MinStack", "1,2,3"); p("FILTER: ZONE SET BY (HHMM, 0 = ANY TIME)", r, "ZoneByHhmm", null); p("FILTER: OVERNIGHT MOVE (18:00→09:30) VS THE SIDE", r, "Overnight", "ANY,WITH,AGAINST"); p("FILTER: 09:30 OPEN IN THE OVERNIGHT RANGE (side-relative)", r, "OpenPos", "ANY,LOW,MID,HIGH"); p("NO FILL BY / FLAT BY (HHMM)", r, "ExitHhmm", null); p("SIDE (0 BOTH • 1 BUYS • -1 SELLS)", r, "Side", null);
            }
            else if (kind >= 12 && kind <= 14)
            {
                string r = "rule" + (kind - 8);
                p("NEW SETUPS FROM (HHMM, NY)", r, "OpenHhmm", null); p("NEW SETUPS UNTIL (HHMM)", r, "WindowEndHhmm", null); p("FVG CANDLES (MINUTES)", r, "FvgMinutes", "5,1,2,3,15");
                p("THE 09:30 CANDLE IS THE FVG'S (0 = FIRST CANDLE • 1 = MAY BE THE MIDDLE / GAP CANDLE: candle 1 = 09:25)", r, "FvgFrom", "0,1");
                p("A SETUP THAT FORMS DURING A TRADE (1 = WAITS FOR THE EXIT, if still valid • 0 = SKIPPED)", r, "WaitExit", "1,0"); p("SMALLEST GAP (POINTS)", r, "MinGapPts", null); p("ONLY ON THE VWAP SIDE (1 = buys above VWAP, sells below • 0 = every FVG)", r, "VwapSide", "1,0");
                p("INVERSION (1 = the same FVGs and prices, the OPPOSITE side: a bullish FVG SELLS, a bearish one BUYS • 0 = normal)", r, "Invert", "0,1");
                p("ENTRY AT % OF THE FVG", r, "FvgPct", "10,15,25,33,50,75"); p("ORDER VALID (MINUTES)", r, "EntryWindow", "60,30,15,90,120"); p("STOP $", r, "StopUsd", null); p("TARGET $", r, "TargetUsd", null);
                p("CONTRACTS (= your contracts) • the $ → points", r, "Contracts", null); p("FUNDED: STOP $ (0 = SAME)", r, "FundStopUsd", null); p("FUNDED: TARGET $ (0 = SAME)", r, "FundTargetUsd", null);
                p("FLAT BY (HHMM)", r, "ExitHhmm", null); p("INSTRUMENTS", r, "Symbols", "MNQ,MGC,BOTH"); p("SIDE (0 BOTH • 1 BUYS • -1 SELLS)", r, "Side", null);
            }
            else if (kind >= 8 && kind - 8 < KeystoneReplaySignals.Rules.Count)
            {
                string r = "rule" + (kind - 8);
                p("OPENING TIME (HHMM, NY)", r, "OpenHhmm", null); p("RANGE MINUTES", r, "Minutes", null); p("ENTRY", r, "Mode", "CANDLE,BREAK");
                p("STOP × 14-DAY RANGE (0 = THE RANGE)", r, "StopAtr", null); p("TARGET R (0 = NONE)", r, "TargetR", null); p("ENTRY WINDOW MIN (BREAK)", r, "EntryWindow", null);
                p("FLAT BY (HHMM)", r, "ExitHhmm", null); p("SKIP FOMC / PAYROLLS DAYS", r, "SkipNews", "True,False"); p("SIDE (0 BOTH • 1 BUYS • -1 SELLS)", r, "Side", null);
            }
            return l;
        }

        private static string GetParam(object target, string field)
        {
            var f = target == null ? null : target.GetType().GetField(field); if (f == null) return "";
            return Convert.ToString(f.GetValue(target), CultureInfo.InvariantCulture);
        }

        private static bool SetParam(object target, string field, string value)
        {
            var f = target == null ? null : target.GetType().GetField(field); if (f == null) return false;
            try
            {
                object v;
                if (f.FieldType == typeof(int)) v = (int)Math.Round(double.Parse(value, CultureInfo.InvariantCulture));
                else if (f.FieldType == typeof(double)) v = double.Parse(value, CultureInfo.InvariantCulture);
                else if (f.FieldType == typeof(bool)) v = value.Trim().ToUpperInvariant() == "TRUE" || value.Trim() == "1";
                else v = value.Trim();
                f.SetValue(target, v); return true;
            }
            catch { return false; }
        }

        private static void PaintBtn(Button b, Brush brush) { b.Background = brush; b.Foreground = IsLightBrush(brush) ? Bg : Text; }   // toggles: the text colour follows the background (gold → dark text, dark → light text)
        private static Button Btn(string text, Brush brush) { var b = new Button { Content = text, Background = brush, Foreground = IsLightBrush(brush) ? Bg : Text, FontWeight = FontWeights.SemiBold, Height = 32, Margin = new Thickness(4), Cursor = System.Windows.Input.Cursors.Hand }; try { b.Template = KeyButtonTemplate(); } catch { } return b; }
        // KEYSTONE buttons: rounded, a soft top sheen, a hairline edge; hover lightens, press darkens, disabled fades (not the NinjaTrader skin)
        private static ControlTemplate keyButtonTemplate;
        // ▶ THE RESUME window (start-up): SPASIX FUTURE, the build (⬆ upgraded from …), a short loading ring, then what resumes — one button
        private static bool ResumeWindow(Window owner, string upgradedFrom, string build, List<string> lines, List<string> skipped)
        {
            bool any = lines != null && lines.Count > 0, ok = false;
            var dw = new Window { WindowStyle = WindowStyle.None, AllowsTransparency = true, Background = System.Windows.Media.Brushes.Transparent, SizeToContent = SizeToContent.WidthAndHeight, ShowInTaskbar = false, Topmost = true, WindowStartupLocation = owner != null ? WindowStartupLocation.CenterOwner : WindowStartupLocation.CenterScreen };
            try { if (owner != null) dw.Owner = owner; } catch { }
            var cyan = Color.FromRgb(0x39, 0xC5, 0xCF); var violet = Color.FromRgb(0xBC, 0x8C, 0xFF);
            var root = new StackPanel { Margin = new Thickness(26, 22, 26, 20), Width = 560 };
            var head = new StackPanel { Orientation = Orientation.Horizontal };
            var ring = new System.Windows.Shapes.Ellipse { Width = 34, Height = 34, StrokeThickness = 3.5, Stroke = new LinearGradientBrush(cyan, violet, 45), StrokeDashArray = new DoubleCollection { 6, 3 }, RenderTransformOrigin = new Point(0.5, 0.5), Margin = new Thickness(0, 0, 14, 0) };
            var rot = new RotateTransform(0); ring.RenderTransform = rot; rot.BeginAnimation(RotateTransform.AngleProperty, new DoubleAnimation(0, 360, TimeSpan.FromSeconds(1.6)) { RepeatBehavior = RepeatBehavior.Forever });
            head.Children.Add(ring);
            var ht = new StackPanel(); ht.Children.Add(new TextBlock { Text = "SPASIX FUTURE", Foreground = new SolidColorBrush(cyan), FontSize = 20, FontWeight = FontWeights.Bold });
            ht.Children.Add(new TextBlock { Text = upgradedFrom != null ? "⬆ UPGRADED TO " + build + "   (was " + upgradedFrom + ")" : build, Foreground = upgradedFrom != null ? new SolidColorBrush(violet) : Muted, FontSize = 12.5, FontWeight = FontWeights.Bold });
            head.Children.Add(ht); root.Children.Add(head);
            var bar = new Border { Height = 3, CornerRadius = new CornerRadius(2), Margin = new Thickness(0, 14, 0, 12), Background = new LinearGradientBrush(Color.FromArgb(0, 0x39, 0xC5, 0xCF), cyan, 0), Width = 0, HorizontalAlignment = HorizontalAlignment.Left };
            bar.BeginAnimation(FrameworkElement.WidthProperty, new DoubleAnimation(0, 508, TimeSpan.FromMilliseconds(900)) { EasingFunction = new CubicEase() });
            root.Children.Add(bar);
            var body = new StackPanel { Opacity = 0 };
            body.Children.Add(new TextBlock { Text = any ? "Your session is still running — resume it:" : "Loaded • nothing to resume (the copier starts OFF)", Foreground = Text, FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 8) });
            foreach (var l in lines ?? new List<string>()) body.Children.Add(new TextBlock { Text = l, Foreground = l.TrimStart().StartsWith("⚠") ? Orange : l.StartsWith("⇉") || l.StartsWith("●") ? Text : Muted, FontSize = 12.5, FontWeight = l.StartsWith("⇉") || l.StartsWith("●") ? FontWeights.Bold : FontWeights.Normal, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 1, 0, 1) });
            foreach (var l in skipped ?? new List<string>()) body.Children.Add(new TextBlock { Text = l, Foreground = Orange, FontSize = 12.5, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 0) });
            var btns = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 16, 0, 0) };
            if (any)
            {
                var no = Btn("START CLEAN", Card); no.Height = 38; no.Padding = new Thickness(18, 0, 18, 0); no.Click += delegate { ok = false; dw.Close(); };
                var yes = Btn("▶ RESUME EVERYTHING", Green); yes.Height = 38; yes.Padding = new Thickness(22, 0, 22, 0); yes.IsDefault = true; yes.Click += delegate { ok = true; dw.Close(); };
                btns.Children.Add(no); btns.Children.Add(yes);
            }
            else { var okB = Btn("OK", Card); okB.Height = 34; okB.Padding = new Thickness(24, 0, 24, 0); okB.IsDefault = true; okB.Click += delegate { dw.Close(); }; btns.Children.Add(okB); }
            body.Children.Add(btns); root.Children.Add(body);
            var frame = new Border { CornerRadius = new CornerRadius(18), Margin = new Thickness(18), Background = new LinearGradientBrush(Color.FromRgb(0x0E, 0x16, 0x28), Color.FromRgb(0x08, 0x0C, 0x18), 90), BorderBrush = new LinearGradientBrush(cyan, violet, 0), BorderThickness = new Thickness(1.6), Child = root,
                Effect = new System.Windows.Media.Effects.DropShadowEffect { Color = cyan, BlurRadius = 26, ShadowDepth = 0, Opacity = 0.5 } };
            dw.Content = frame; dw.KeyDown += (s0, e0) => { if (e0.Key == System.Windows.Input.Key.Escape) { ok = false; dw.Close(); } };
            frame.Opacity = 0; frame.BeginAnimation(UIElement.OpacityProperty, new DoubleAnimation(0, 1, TimeSpan.FromMilliseconds(260)));
            var tReveal = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromMilliseconds(950) };
            tReveal.Tick += delegate { tReveal.Stop(); body.BeginAnimation(UIElement.OpacityProperty, new DoubleAnimation(0, 1, TimeSpan.FromMilliseconds(350))); rot.BeginAnimation(RotateTransform.AngleProperty, new DoubleAnimation(0, 360, TimeSpan.FromSeconds(6)) { RepeatBehavior = RepeatBehavior.Forever }); };
            tReveal.Start();
            if (!any) { var tClose = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(4) }; tClose.Tick += delegate { tClose.Stop(); try { dw.Close(); } catch { } }; tClose.Start(); }
            try { dw.ShowDialog(); } catch { }
            return ok;
        }
        // ☰ every right-click menu of our windows: dark glass, rounded, a cyan → violet edge with a soft glow (NinjaTrader's own menus untouched)
        private static ControlTemplate menuTemplate, menuItemTemplate; private static bool menuHooked, menuItemTried;
        // every menu row (and its SUBMENU — the default one opened white): dark rounded rows, a cyan glow under the mouse, › for a submenu,
        // the submenu in the same dark glass panel as the menu (like SpasiX for MT5)
        private const string MenuItemXaml = @"<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='MenuItem'>
  <Grid SnapsToDevicePixels='True'>
    <Border x:Name='bg' CornerRadius='6' Background='Transparent' Margin='2,0,2,0'/>
    <DockPanel Margin='{TemplateBinding Padding}'>
      <TextBlock x:Name='arrow' DockPanel.Dock='Right' Text='›' Margin='16,0,0,0' FontSize='15' Foreground='#8FA0BC' VerticalAlignment='Center' Visibility='Collapsed'/>
      <ContentPresenter ContentSource='Header' RecognizesAccessKey='False' VerticalAlignment='Center'/>
    </DockPanel>
    <Popup x:Name='PART_Popup' Placement='Right' HorizontalOffset='-2' VerticalOffset='-10' AllowsTransparency='True' Focusable='False' PopupAnimation='Fade'
           IsOpen='{Binding IsSubmenuOpen, RelativeSource={RelativeSource TemplatedParent}}'>
      <Border CornerRadius='10' Background='#F80C1220' BorderThickness='1.4' Padding='4,6,4,6' Margin='8'>
        <Border.BorderBrush><LinearGradientBrush StartPoint='0,0' EndPoint='1,0'><GradientStop Color='#39C5CF' Offset='0'/><GradientStop Color='#BC8CFF' Offset='1'/></LinearGradientBrush></Border.BorderBrush>
        <Border.Effect><DropShadowEffect Color='#39C5CF' BlurRadius='14' ShadowDepth='0' Opacity='0.45'/></Border.Effect>
        <ScrollViewer VerticalScrollBarVisibility='Auto' MaxHeight='640'><StackPanel IsItemsHost='True' KeyboardNavigation.DirectionalNavigation='Cycle'/></ScrollViewer>
      </Border>
    </Popup>
  </Grid>
  <ControlTemplate.Triggers>
    <Trigger Property='HasItems' Value='True'><Setter TargetName='arrow' Property='Visibility' Value='Visible'/></Trigger>
    <Trigger Property='IsHighlighted' Value='True'><Setter TargetName='bg' Property='Background' Value='#3339C5CF'/><Setter TargetName='arrow' Property='Foreground' Value='#39C5CF'/></Trigger>
    <Trigger Property='IsSubmenuOpen' Value='True'><Setter TargetName='bg' Property='Background' Value='#2639C5CF'/></Trigger>
    <Trigger Property='IsEnabled' Value='False'><Setter Property='Opacity' Value='0.55'/></Trigger>
  </ControlTemplate.Triggers>
</ControlTemplate>";
        private static void HookMenus()
        {
            if (menuHooked) return; menuHooked = true;
            try { EventManager.RegisterClassHandler(typeof(ContextMenu), ContextMenu.OpenedEvent, new RoutedEventHandler((s0, e0) => { try { var cm = s0 as ContextMenu; if (cm != null && cm.PlacementTarget != null && Window.GetWindow(cm.PlacementTarget) is KeystoneWindow) StyleMenu(cm); } catch { } })); } catch { }
        }
        private static void StyleMenu(ContextMenu cm)
        {
            if (menuTemplate == null)
            {
                var cyan = Color.FromRgb(0x39, 0xC5, 0xCF);
                var bd = new FrameworkElementFactory(typeof(Border));
                bd.SetValue(Border.CornerRadiusProperty, new CornerRadius(10)); bd.SetValue(Border.BackgroundProperty, new SolidColorBrush(Color.FromArgb(248, 12, 18, 32)));
                bd.SetValue(Border.BorderBrushProperty, new LinearGradientBrush(cyan, Color.FromRgb(0xBC, 0x8C, 0xFF), 0)); bd.SetValue(Border.BorderThicknessProperty, new Thickness(1.4));
                bd.SetValue(Border.PaddingProperty, new Thickness(4, 6, 4, 6)); bd.SetValue(FrameworkElement.MarginProperty, new Thickness(8));
                bd.SetValue(UIElement.EffectProperty, new System.Windows.Media.Effects.DropShadowEffect { Color = cyan, BlurRadius = 14, ShadowDepth = 0, Opacity = 0.45 });
                var sp = new FrameworkElementFactory(typeof(StackPanel)); sp.SetValue(System.Windows.Controls.Panel.IsItemsHostProperty, true); bd.AppendChild(sp);
                menuTemplate = new ControlTemplate(typeof(ContextMenu)) { VisualTree = bd };
            }
            if (cm.Template != menuTemplate) { cm.Template = menuTemplate; cm.HasDropShadow = false; }
            cm.Foreground = Text; cm.FontSize = 12.5;
            Action<ItemCollection> paint = null;
            if (!menuItemTried) { menuItemTried = true; try { menuItemTemplate = (ControlTemplate)System.Windows.Markup.XamlReader.Parse(MenuItemXaml); } catch { menuItemTemplate = null; } }   // no template = the old look, never an error
            paint = items => { foreach (var it in items) { var mi = it as MenuItem; if (mi != null) { if (mi.ReadLocalValue(Control.ForegroundProperty) == DependencyProperty.UnsetValue) mi.Foreground = mi.IsEnabled ? Text : Muted; mi.Padding = new Thickness(10, 5, 12, 5); if (menuItemTemplate != null) mi.Template = menuItemTemplate; if (mi.Items.Count > 0) paint(mi.Items); } var sep = it as Separator; if (sep != null) { sep.Background = new SolidColorBrush(Color.FromArgb(70, 0x39, 0xC5, 0xCF)); sep.Margin = new Thickness(10, 4, 10, 4); } } };
            paint(cm.Items);
        }
        private static ControlTemplate KeyButtonTemplate()
        {
            if (keyButtonTemplate != null) return keyButtonTemplate;
            var bd = new FrameworkElementFactory(typeof(Border), "bd");
            bd.SetValue(Border.CornerRadiusProperty, new CornerRadius(7)); bd.SetValue(Border.BackgroundProperty, new TemplateBindingExtension(Control.BackgroundProperty));
            bd.SetValue(Border.BorderBrushProperty, new SolidColorBrush(Color.FromArgb(70, 255, 255, 255))); bd.SetValue(Border.BorderThicknessProperty, new Thickness(1));
            var g = new FrameworkElementFactory(typeof(Grid));
            var sheen = new FrameworkElementFactory(typeof(Border)); sheen.SetValue(Border.CornerRadiusProperty, new CornerRadius(6)); sheen.SetValue(Border.BackgroundProperty, new LinearGradientBrush(Color.FromArgb(55, 255, 255, 255), Color.FromArgb(0, 255, 255, 255), 90));
            var hover = new FrameworkElementFactory(typeof(Border), "hover"); hover.SetValue(Border.CornerRadiusProperty, new CornerRadius(6)); hover.SetValue(Border.BackgroundProperty, System.Windows.Media.Brushes.Transparent);
            var cp = new FrameworkElementFactory(typeof(ContentPresenter)); cp.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Center); cp.SetValue(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center); cp.SetValue(FrameworkElement.MarginProperty, new Thickness(10, 0, 10, 0));
            g.AppendChild(sheen); g.AppendChild(hover); g.AppendChild(cp); bd.AppendChild(g);
            var t = new ControlTemplate(typeof(Button)) { VisualTree = bd };
            var over = new Trigger { Property = UIElement.IsMouseOverProperty, Value = true }; over.Setters.Add(new Setter(Border.BackgroundProperty, new SolidColorBrush(Color.FromArgb(40, 255, 255, 255)), "hover"));
            over.Setters.Add(new Setter(UIElement.EffectProperty, new System.Windows.Media.Effects.DropShadowEffect { Color = Color.FromRgb(0x39, 0xC5, 0xCF), BlurRadius = 12, ShadowDepth = 0, Opacity = 0.55 }, "bd"));   // a soft cyan glow under the mouse over.Setters.Add(new Setter(Border.BorderBrushProperty, new SolidColorBrush(Color.FromArgb(150, 255, 255, 255)), "bd"));
            var press = new Trigger { Property = Button.IsPressedProperty, Value = true }; press.Setters.Add(new Setter(Border.BackgroundProperty, new SolidColorBrush(Color.FromArgb(70, 0, 0, 0)), "hover"));
            var off = new Trigger { Property = UIElement.IsEnabledProperty, Value = false }; off.Setters.Add(new Setter(UIElement.OpacityProperty, 0.4, "bd"));
            t.Triggers.Add(over); t.Triggers.Add(press); t.Triggers.Add(off);
            keyButtonTemplate = t; return t;
        }
        // KEYSTONE dialogs: every question / message in our own design (title bar, coloured badge, rounded buttons); Enter = the main button, Esc = cancel
        private static MessageBoxResult KBox(string text) { return KBox(null, text, "SPASIX FUTURE", MessageBoxButton.OK, MessageBoxImage.Information); }
        private static MessageBoxResult KBox(string text, string caption) { return KBox(null, text, caption, MessageBoxButton.OK, MessageBoxImage.Information); }
        private static MessageBoxResult KBox(string text, string caption, MessageBoxButton buttons) { return KBox(null, text, caption, buttons, MessageBoxImage.Question); }
        private static MessageBoxResult KBox(string text, string caption, MessageBoxButton buttons, MessageBoxImage image) { return KBox(null, text, caption, buttons, image); }
        // a one-shot line the next KBox shows big in a softly flashing colour (e.g. "BUY 1 MGC × 5 ACCOUNTS = 5 CONTRACTS"), so a wrong size is seen
        private static string KBoxFlash;
        private static MessageBoxResult KBox(Window owner, string text, string caption, MessageBoxButton buttons, MessageBoxImage image)
        {
            string flashLine = KBoxFlash; KBoxFlash = null;
            if (Application.Current == null) return MessageBox.Show((flashLine != null ? flashLine + "\n\n" : "") + text, caption, buttons, image);   // no WPF app (the tests): the plain box
            MessageBoxResult result = buttons == MessageBoxButton.OK ? MessageBoxResult.OK : buttons == MessageBoxButton.YesNo ? MessageBoxResult.No : MessageBoxResult.Cancel;
            // our own dialog, never the grey system box: 1st with the Keystone frame on its owner, 2nd without an owner (e.g. the owner is
            // closing), 3rd a plain borderless window with the same design; the system box only if all three fail (the reason is logged)
            var errors = new List<string>();
            for (int attempt = 0; attempt < 3; attempt++)
            try
            {
                if (attempt == 0 && owner == null) owner = Application.Current.Windows.OfType<Window>().FirstOrDefault(x => x.IsActive && x.IsVisible);
                if (attempt > 0) owner = null;
                bool warn = image == MessageBoxImage.Warning, err = image == MessageBoxImage.Error, ask = image == MessageBoxImage.Question;
                var accent = new SolidColorBrush(err ? Color.FromRgb(255, 69, 96) : warn ? Color.FromRgb(255, 184, 0) : ask ? Color.FromRgb(0, 229, 255) : Color.FromRgb(124, 140, 255));
                string cap = (caption ?? "").Replace("SPASIX FUTURE • ", "").Replace("KEYSTONE • ", "").Replace("SPASIX FUTURE", "").Trim();
                Window d = attempt < 2 ? new KeystoneWindow() : new Window { WindowStyle = WindowStyle.None };
                d.Title = "SPASIX FUTURE" + (cap == "" ? "" : " • " + cap); d.SizeToContent = SizeToContent.WidthAndHeight; d.ResizeMode = ResizeMode.NoResize; d.WindowStartupLocation = owner != null ? WindowStartupLocation.CenterOwner : WindowStartupLocation.CenterScreen; d.Background = Bg; d.Foreground = Text; d.ShowInTaskbar = owner == null; d.Topmost = owner == null;
                if (owner != null) d.Owner = owner; d.MinWidth = 640; d.MinHeight = 300;   /* larger, readable questions (BUILD 11e) */
                var body = new StackPanel { Margin = new Thickness(30, 26, 30, 24), MinWidth = 580, MaxWidth = 760 };
                var top = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 12) };
                var badge = new Border { Width = 34, Height = 34, CornerRadius = new CornerRadius(17), Background = new SolidColorBrush(Color.FromArgb(40, accent.Color.R, accent.Color.G, accent.Color.B)), BorderBrush = accent, BorderThickness = new Thickness(1.6), Margin = new Thickness(0, 0, 12, 0),
                    Child = new TextBlock { Text = err ? "✕" : warn ? "!" : ask ? "?" : "i", Foreground = accent, FontSize = 17, FontWeight = FontWeights.Bold, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center } };
                top.Children.Add(badge);
                top.Children.Add(new TextBlock { Text = cap == "" ? (ask ? "Please confirm" : warn ? "Attention" : "SpasiX Future") : cap, Foreground = accent, FontSize = 21, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center, TextWrapping = TextWrapping.Wrap, MaxWidth = 680 });
                body.Children.Add(top);
                if (flashLine != null)
                {
                    var fl = new Border { CornerRadius = new CornerRadius(10), Padding = new Thickness(14, 8, 14, 9), Margin = new Thickness(46, 0, 0, 14), BorderThickness = new Thickness(2), BorderBrush = new SolidColorBrush(Color.FromRgb(255, 64, 160)), Background = new SolidColorBrush(Color.FromArgb(46, 255, 64, 160)),
                        Child = new TextBlock { Text = flashLine, Foreground = new SolidColorBrush(Color.FromRgb(255, 120, 200)), FontSize = 19, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap } };
                    fl.BeginAnimation(UIElement.OpacityProperty, new DoubleAnimation(1, 0.45, TimeSpan.FromMilliseconds(650)) { AutoReverse = true, RepeatBehavior = RepeatBehavior.Forever });
                    body.Children.Add(fl);
                }
                body.Children.Add(new TextBlock { Text = text ?? "", Foreground = Text, FontSize = 16, TextWrapping = TextWrapping.Wrap, LineHeight = 24, Margin = new Thickness(46, 0, 0, 22) });
                var row = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Right };
                Action<MessageBoxResult> done = r0 => { result = r0; d.Close(); };
                Func<string, bool, MessageBoxResult, Border> button = (label, primary, r0) =>
                {
                    var tb = new TextBlock { Text = label, Foreground = primary ? Bg : Text, FontSize = 15.5, FontWeight = FontWeights.Bold, HorizontalAlignment = HorizontalAlignment.Center };
                    var b = new Border { MinWidth = 130, MinHeight = 42, Padding = new Thickness(22, 10, 22, 11), Margin = new Thickness(10, 0, 0, 0), CornerRadius = new CornerRadius(9), Cursor = System.Windows.Input.Cursors.Hand, Child = tb,
                        Background = primary ? (Brush)new LinearGradientBrush(accent.Color, Color.FromRgb((byte)(accent.Color.R * 0.75), (byte)(accent.Color.G * 0.75), (byte)(accent.Color.B * 0.75)), 90) : Card, BorderBrush = primary ? accent : new SolidColorBrush(Color.FromArgb(80, 255, 255, 255)), BorderThickness = new Thickness(1) };
                    b.MouseEnter += delegate { b.Opacity = 0.85; }; b.MouseLeave += delegate { b.Opacity = 1; };
                    b.MouseLeftButtonUp += delegate { done(r0); };
                    row.Children.Add(b); return b;
                };
                MessageBoxResult enter = MessageBoxResult.OK, esc = result;
                if (buttons == MessageBoxButton.OK) { button("OK", true, MessageBoxResult.OK); enter = esc = MessageBoxResult.OK; }
                else if (buttons == MessageBoxButton.OKCancel) { button("Cancel", false, MessageBoxResult.Cancel); button("OK", true, MessageBoxResult.OK); enter = MessageBoxResult.OK; }
                else if (buttons == MessageBoxButton.YesNo) { button("No", false, MessageBoxResult.No); button("Yes", true, MessageBoxResult.Yes); enter = MessageBoxResult.Yes; }
                else { button("Cancel", false, MessageBoxResult.Cancel); button("No", false, MessageBoxResult.No); button("Yes", true, MessageBoxResult.Yes); enter = MessageBoxResult.Yes; }
                body.Children.Add(row);
                if (attempt < 2) d.Content = new Border { Background = Bg, Child = body };
                else
                {
                    // borderless: our own slim title strip (drag to move) and an accent edge
                    var outer = new DockPanel { LastChildFill = true };
                    var strip = new DockPanel { Height = 30, Background = new LinearGradientBrush(Color.FromRgb(8, 11, 22), Color.FromRgb(16, 22, 44), 0) };
                    strip.Children.Add(new TextBlock { Text = "SPASIX FUTURE" + (cap == "" ? "" : "  •  " + cap), Foreground = new SolidColorBrush(Color.FromRgb(150, 165, 195)), FontSize = 12, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(12, 0, 12, 0) });
                    var dd0 = d; strip.MouseLeftButtonDown += delegate { try { dd0.DragMove(); } catch { } };
                    DockPanel.SetDock(strip, Dock.Top); outer.Children.Add(strip); outer.Children.Add(body);
                    d.Content = new Border { Background = Bg, BorderBrush = accent, BorderThickness = new Thickness(1.2), Child = outer };
                }
                d.PreviewKeyDown += (s0, e0) => { if (e0.Key == System.Windows.Input.Key.Enter) { e0.Handled = true; done(enter); } else if (e0.Key == System.Windows.Input.Key.Escape) { e0.Handled = true; done(esc); } };
                d.ShowDialog();
                return result;
            }
            catch (Exception ex) { errors.Add("attempt " + attempt + ": " + ex.GetType().Name + " " + ex.Message); }
            try { var lf = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments), "KeystoneArcData", "dialog_errors.log"); Directory.CreateDirectory(Path.GetDirectoryName(lf)); File.AppendAllLines(lf, new[] { DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") + " • " + caption + " • " + string.Join(" | ", errors) }); } catch { }
            return MessageBox.Show(text, caption, buttons, image);
        }
        // Light buttons (gold, cyan, green, blue, orchid) get dark text; dark and red ones keep light text.
        private static bool IsLightBrush(Brush brush)
        {
            var solid = brush as SolidColorBrush; if (solid == null) return false;
            Color c = solid.Color;
            return (0.299 * c.R + 0.587 * c.G + 0.114 * c.B) / 255.0 > 0.52;
        }
        private static StackPanel Stack() { return new StackPanel { Margin = new Thickness(8) }; }
        private static Grid TwoColumns() { var g = new Grid { Margin = new Thickness(6) }; g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); return g; }
        private static Border PanelCard(UIElement child) { return new Border { Background = Panel, BorderBrush = Card, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(6), Padding = new Thickness(6), Margin = new Thickness(6), Child = child }; }
        private static Grid Row(string label, UIElement control) { var g = new Grid { Margin = new Thickness(2) }; g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); g.Children.Add(Txt(label, Muted, 10, FontWeights.Bold)); Grid.SetColumn(control, 1); g.Children.Add(control); return g; }
        // Pool settings must remain readable at normal NinjaTrader window sizes.  These rows have
        // a stable compact width, so a WrapPanel creates clean rows instead of vertically-stretched
        // controls or a hidden lower half of the settings page.
        // A labelled pool-settings field. Checkbox / dropdown rows are wider and checkbox text wraps,
        // so option names are never cut off.
        private static Border SettingsBlock(UIElement child, Brush accent) { return new Border { Background = Card, BorderBrush = accent, BorderThickness = new Thickness(1, 1, 1, 1), CornerRadius = new CornerRadius(6), Padding = new Thickness(8, 5, 8, 5), Margin = new Thickness(0, 4, 0, 4), Child = child }; }
        private static TextBlock SettingsExplain(string text) { var t = Txt(text, Muted, 10, FontWeights.Normal); t.TextWrapping = TextWrapping.Wrap; t.Margin = new Thickness(2, 1, 2, 4); return t; }
        private static Grid PoolRow(string label, UIElement control)
        {
            bool wide = control is CheckBox || control is ComboBox;
            var g = new Grid { Width = wide ? 380 : 300, MinHeight = 34, Margin = new Thickness(3, 2, 3, 2), VerticalAlignment = VerticalAlignment.Top };
            g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(wide ? 0.95 : 1.25, GridUnitType.Star) });
            g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(wide ? 1.45 : 0.95, GridUnitType.Star) });
            var caption = Txt(label, Muted, 10, FontWeights.Bold); caption.TextWrapping = TextWrapping.Wrap; caption.VerticalAlignment = VerticalAlignment.Center; g.Children.Add(caption);
            var box = control as CheckBox;
            if (box != null && box.Content is string) box.Content = new TextBlock { Text = (string)box.Content, TextWrapping = TextWrapping.Wrap };
            FrameworkElement compactControl = control as FrameworkElement;
            if (compactControl != null) { compactControl.VerticalAlignment = VerticalAlignment.Center; if (box == null) compactControl.Height = 28; else compactControl.MinHeight = 28; compactControl.Margin = new Thickness(3, 1, 3, 1); }
            Grid.SetColumn(control, 1); g.Children.Add(control); return g;
        }

