            var export = Btn("EXPORT STUDY (HTML + CSV)", Gold); export.ToolTip = "Writes the full study (every table and every entry) as an HTML report and a CSV of every entry.";
            var chart = Btn("ENTRIES ON THE CHART", Blue);
