                    new[] { Gold, Text, Text, MoneyBrush(y.ChosenPlain), MoneyBrush(y.ChosenProp), Green, Green, Muted, MoneyBrush(y.HindProp) }, cw, MoneyBrush(y.ChosenProp), null);
