        // ---- LIVE FEED: NinjaTrader's real-time 1-minute bars for one instrument (the front contract), the last ~3 sessions first
        private sealed class LiveFeed
        {
            public string Symbol = "", Contract = "", Problem = ""; public bool Ready, Stopped; public Instrument Inst; public DateTime LastUpdate = DateTime.UtcNow;
            public readonly object Gate = new object(); public List<KeystoneArcBar> Initial; public readonly Queue<KeystoneArcBar> Updates = new Queue<KeystoneArcBar>();
            public BarsRequest Request; public EventHandler<BarsUpdateEventArgs> Handler;
            public void Stop() { Stopped = true; try { if (Request != null) { if (Handler != null) Request.Update -= Handler; Request.Dispose(); } } catch { } Request = null; }
        }

        // ---- the link's connection to one NinjaTrader account + instrument (the studio's live contract): reads EVERY working order
        // and execution on it (the studio's and NinjaTrader's own), places / changes / cancels orders, flattens.
        private sealed class NinjaBroker : IKeystoneBroker, IKeystoneNamedBroker
        {
            public readonly Account Acct; public readonly Instrument Inst; readonly Dictionary<Order, KeystoneBrokerOrder> wrap = new Dictionary<Order, KeystoneBrokerOrder>(); int seq;
            public string AccountName { get { try { return Acct != null ? Acct.Name ?? "" : ""; } catch { return ""; } } }   // 🔒 the link reads this account's NinjaTrader lockout
            public static int Made;   /* 🛡 11j guardrail test: how many were ever built (the BACKTEST STUDIO's ● LIVE DEMO must build none) */
            public NinjaBroker(Account a, Instrument i) { Acct = a; Inst = i; Made++; }
            public bool Connected
            {
                get
                {
                    object conn = ReflectionValue(Acct, "Connection"); if (conn == null) return false; object st = ReflectionValue(conn, "Status");
                    string t = Convert.ToString(st ?? "Connected"); return t.IndexOf("Connected", StringComparison.OrdinalIgnoreCase) >= 0 && t.IndexOf("Dis", StringComparison.OrdinalIgnoreCase) < 0;
                }
            }
            bool Mine(Instrument i) { return i != null && Inst != null && i.FullName == Inst.FullName; }
            // a copy of a NinjaTrader collection (they change on other threads)
            static List<T> Copy<T>(System.Collections.IEnumerable src) { var l = new List<T>(); if (src == null) return l; lock (src) foreach (object x in src) if (x is T) l.Add((T)x); return l; }
            Position Pos()
            {
                try { foreach (Position p in Copy<Position>(Acct.Positions)) if (p != null && Mine(p.Instrument) && p.MarketPosition != MarketPosition.Flat) return p; } catch { }
                return null;
            }
            public int Qty { get { var p = Pos(); return p == null ? 0 : (p.MarketPosition == MarketPosition.Long ? p.Quantity : -p.Quantity); } }
            public double AvgPrice { get { var p = Pos(); return p == null ? 0 : p.AveragePrice; } }
            public double DayPnl { get { try { return Acct.Get(AccountItem.RealizedProfitLoss, Currency.UsDollar) + Acct.Get(AccountItem.UnrealizedProfitLoss, Currency.UsDollar); } catch { return 0; } } }
            public double Tick { get { try { return Inst.MasterInstrument.TickSize; } catch { return 0.25; } } }
            static string KindOf(OrderType t) { return t == OrderType.Market ? "MARKET" : (t == OrderType.StopMarket || t == OrderType.StopLimit) ? "STOP" : "LIMIT"; }
            void Refresh(KeystoneBrokerOrder o, Order n)
            {
                var st = n.OrderState; o.Filled = n.Filled; o.Rejected = st == OrderState.Rejected;
                o.Done = st == OrderState.Filled || st == OrderState.Cancelled || st == OrderState.Rejected || st == OrderState.Unknown;
                if (st == OrderState.CancelPending || st == OrderState.CancelSubmitted) o.CancelSent = true;
                o.Kind = KindOf(n.OrderType); o.Side = n.OrderAction == OrderAction.Buy || n.OrderAction == OrderAction.BuyToCover ? 1 : -1; o.Qty = n.Quantity; o.Oco = n.Oco ?? ""; o.Name = n.Name ?? "";
                if (!(st == OrderState.ChangePending || st == OrderState.ChangeSubmitted)) o.Price = o.Kind == "STOP" ? n.StopPrice : o.Kind == "LIMIT" ? n.LimitPrice : 0;
            }
            public List<KeystoneBrokerOrder> Working()
            {
                var list = new List<KeystoneBrokerOrder>();
                try
                {
                    foreach (Order n in Copy<Order>(Acct.Orders))
                    {
                        if (n == null || !Mine(n.Instrument)) continue;
                        KeystoneBrokerOrder o; if (!wrap.TryGetValue(n, out o)) { o = new KeystoneBrokerOrder { Id = "N" + (++seq), Native = n }; wrap[n] = o; }
                        Refresh(o, n); if (!o.Done) list.Add(o);
                    }
                    foreach (var kv in wrap.ToList()) { Refresh(kv.Value, kv.Key); if (kv.Value.Done && wrap.Count > 400) wrap.Remove(kv.Key); }
                }
                catch { }
                return list;
            }
            public List<KeystoneExec> Executions()
            {
                var list = new List<KeystoneExec>();
                try
                {
                    foreach (Execution e in Copy<Execution>(Acct.Executions))
                        if (e != null && Mine(e.Instrument) && e.Quantity > 0)
                            list.Add(new KeystoneExec { Id = e.ExecutionId ?? (e.Time.Ticks + "|" + e.Price), Time = e.Time, Price = e.Price, SignedQty = e.MarketPosition == MarketPosition.Long ? e.Quantity : -e.Quantity, Commission = e.Commission, Name = e.Order != null ? (e.Order.Name ?? "") : "" });
                }
                catch { }
                return list;
            }
            public KeystoneBrokerOrder Submit(string kind, int signedQty, double price, string oco, bool automated)
            {
                try
                {
                    if (Inst != null && price > 0) price = Inst.MasterInstrument.RoundToTickSize(price);
                    OrderType type = kind == "STOP" ? OrderType.StopMarket : kind == "LIMIT" ? OrderType.Limit : OrderType.Market;
                    Order n = Acct.CreateOrder(Inst, signedQty > 0 ? OrderAction.Buy : OrderAction.Sell, type, automated ? OrderEntry.Automated : OrderEntry.Manual,
                        kind == "MARKET" ? TimeInForce.Day : TimeInForce.Gtc, Math.Abs(signedQty), kind == "LIMIT" ? price : 0, kind == "STOP" ? price : 0, oco ?? string.Empty, "KEYSTONE " + kind, NinjaTrader.Core.Globals.MaxDate, null);
                    if (n == null) return null;
                    Acct.Submit(new[] { n });
                    var o = new KeystoneBrokerOrder { Id = "K" + (++seq), Kind = kind, Side = Math.Sign(signedQty), Qty = Math.Abs(signedQty), Price = price, Oco = oco ?? string.Empty, Name = "KEYSTONE " + kind, Native = n };
                    wrap[n] = o; return o;
                }
                catch { return null; }
            }
            public void ChangePrice(KeystoneBrokerOrder o, double price)
            {
                var n = o.Native as Order; if (n == null) return;
                try
                {
                    price = Inst.MasterInstrument.RoundToTickSize(price);
                    if (n.OrderType == OrderType.StopMarket) n.StopPriceChanged = price;
                    else if (n.OrderType == OrderType.StopLimit) { n.LimitPriceChanged = n.LimitPrice + (price - n.StopPrice); n.StopPriceChanged = price; }
                    else n.LimitPriceChanged = price;
                    Acct.Change(new[] { n }); o.Price = price;
                }
                catch { }
            }
            public void Cancel(KeystoneBrokerOrder o) { var n = o.Native as Order; o.CancelSent = true; if (n == null) return; try { Acct.Cancel(new[] { n }); } catch { } }
            public void Flatten() { try { Acct.Flatten(new[] { Inst }); } catch { } }
        }

        // 📊 ORDER FLOW data from NinjaTrader. The tick history comes from a 1-tick BarsRequest (each trade: time, price, size, and the bid / ask
        // at that moment where NinjaTrader has them → the aggressor; else the tick rule). The live trades come from NinjaTrader's MarketData
        // feed (every Last with the current Bid / Ask). Both are reached BY NAME at run time, so a NinjaTrader version without one of these
        // members still compiles — the indicator then says what is missing.
        private static Type FindNtType(string full) { foreach (var a in AppDomain.CurrentDomain.GetAssemblies()) { try { var t = a.GetType(full); if (t != null) return t; } catch { } } return null; }
        // GetBid / GetAsk of a Bars, looked up ONCE (millions of trades: a lookup per trade froze the load)
        private static Func<int, double> BarsQuoteFn(object bars, string method)
        {
            try
            {
                var m = bars.GetType().GetMethod(method, new[] { typeof(int) }); if (m == null) return null;
                if (m.ReturnType == typeof(double)) return (Func<int, double>)Delegate.CreateDelegate(typeof(Func<int, double>), bars, m);
                return i => { try { return Convert.ToDouble(m.Invoke(bars, new object[] { i }), CultureInfo.InvariantCulture); } catch { return 0; } };
            }
            catch { return null; }
        }
        // ⏱ item 36: NinjaTrader's 1-second bars (the fallback when no tick history exists)
        private void RequestSecondBars(Instrument inst, DateTime from, DateTime to, Dispatcher disp, Action<List<KeystoneArcBar>, string> done)
        {
            BarsRequest rq = null;
            try
            {
                rq = new BarsRequest(inst, from, to) { BarsPeriod = new BarsPeriod { BarsPeriodType = BarsPeriodType.Second, Value = 1 }, MergePolicy = MergePolicy.UseGlobalSettings };
                rq.Request(delegate(BarsRequest reply, ErrorCode error, string message)
                {
                    var list = new List<KeystoneArcBar>(); string problem = "";
                    try { if (error != ErrorCode.NoError || reply == null || reply.Bars == null) problem = error + " " + message; else { var bs = reply.Bars; for (int i = 0; i < bs.Count; i++) { double c = bs.GetClose(i); if (c <= 0) continue; list.Add(new KeystoneArcBar { Time = bs.GetTime(i), Open = bs.GetOpen(i), High = bs.GetHigh(i), Low = bs.GetLow(i), Close = c, Volume = bs.GetVolume(i) }); } } }
                    catch (Exception ex) { problem = ex.Message; }
                    try { reply.Dispose(); } catch { }
                    disp.BeginInvoke(new Action(() => done(list, problem)));
                });
            }
            catch (Exception ex) { try { if (rq != null) rq.Dispose(); } catch { } disp.BeginInvoke(new Action(() => done(new List<KeystoneArcBar>(), ex.Message))); }
        }
        private void RequestTicks(Instrument inst, DateTime from, DateTime to, Dispatcher disp, Action<List<KeystoneOfTick>, int, string> done)
        {
            BarsRequest rq = null;
            try
            {
                rq = new BarsRequest(inst, from, to) { BarsPeriod = new BarsPeriod { BarsPeriodType = BarsPeriodType.Tick, Value = 1 }, MergePolicy = MergePolicy.UseGlobalSettings };
                rq.Request(delegate(BarsRequest reply, ErrorCode error, string message)
                {
                    var list = new List<KeystoneOfTick>(); string problem = ""; int quoted = 0;
                    try
                    {
                        if (error != ErrorCode.NoError || reply == null || reply.Bars == null) problem = error + " " + message;
                        else
                        {
                            var bs = reply.Bars; double prev = 0; int prevSide = 0; var gBid = BarsQuoteFn(bs, "GetBid"); var gAsk = BarsQuoteFn(bs, "GetAsk"); bool hasQuotes = gBid != null && gAsk != null;
                            list.Capacity = Math.Max(16, bs.Count);
                            for (int i = 0; i < bs.Count; i++)
                            {
                                double px = bs.GetClose(i); long sz = bs.GetVolume(i); if (px <= 0 || sz <= 0) continue;
                                double bid = 0, ask = 0; if (hasQuotes) { try { bid = gBid(i); ask = gAsk(i); } catch { bid = ask = 0; } }
                                if (i == 200 && quoted == 0) hasQuotes = false;   // this history has no bid / ask: stop asking (speed)
                                bool q = bid > 0 && ask > 0 && ask >= bid; int side = KeystoneOrderFlow.Classify(px, q ? bid : 0, q ? ask : 0, prev, prevSide); if (q) quoted++;
                                list.Add(new KeystoneOfTick { Time = bs.GetTime(i), Price = px, Size = sz, Side = side, Quoted = q }); prev = px; prevSide = side;
                            }
                        }
                    }
                    catch (Exception ex) { problem = ex.Message; }
                    try { reply.Dispose(); } catch { }
                    disp.BeginInvoke(new Action(() => done(list, quoted, problem)));
                });
            }
            catch (Exception ex) { try { if (rq != null) rq.Dispose(); } catch { } disp.BeginInvoke(new Action(() => done(new List<KeystoneOfTick>(), 0, ex.Message))); }
        }
        private sealed class OfLiveTap
        {
            public object Md; public System.Reflection.EventInfo Ev; public Delegate H; public readonly List<KeystoneOfTick> Fresh = new List<KeystoneOfTick>(); public readonly object Gate = new object();
            public double Bid, Ask, LastPx; public int LastSide; public string Problem = ""; public long Count; public DateTime LastAt = DateTime.MinValue;
            static double D(object o) { try { return o == null ? 0 : Convert.ToDouble(o, CultureInfo.InvariantCulture); } catch { return 0; } }
            readonly Dictionary<string, System.Reflection.PropertyInfo> props = new Dictionary<string, System.Reflection.PropertyInfo>(); Type propsOf;
            object ReflectionValue(object e, string name)   // each property looked up once (the feed fires thousands of times a minute)
            {
                if (e == null) return null; var t = e.GetType(); if (t != propsOf) { props.Clear(); propsOf = t; }
                System.Reflection.PropertyInfo pi; if (!props.TryGetValue(name, out pi)) props[name] = pi = t.GetProperty(name);
                try { return pi == null ? null : pi.GetValue(e, null); } catch { return null; }
            }
            public void On(object sender, EventArgs e)
            {
                try
                {
                    string k = Convert.ToString(ReflectionValue(e, "MarketDataType")); double p = D(ReflectionValue(e, "Price"));
                    if (k == "Bid") { if (p > 0) Bid = p; return; } if (k == "Ask") { if (p > 0) Ask = p; return; } if (k != "Last" || p <= 0) return;
                    long v = (long)D(ReflectionValue(e, "Volume")); if (v <= 0) return; double b = D(ReflectionValue(e, "Bid")), a = D(ReflectionValue(e, "Ask")); if (b > 0) Bid = b; if (a > 0) Ask = a;
                    object tt = ReflectionValue(e, "Time"); DateTime t = tt is DateTime ? (DateTime)tt : DateTime.Now; bool q = Bid > 0 && Ask > 0 && Ask >= Bid;
                    int side = KeystoneOrderFlow.Classify(p, q ? Bid : 0, q ? Ask : 0, LastPx, LastSide); LastPx = p; LastSide = side;
                    lock (Gate) { Fresh.Add(new KeystoneOfTick { Time = t, Price = p, Size = v, Side = side, Quoted = q }); Count++; LastAt = DateTime.Now; }
                }
                catch { }
            }
            public void Stop() { try { if (Ev != null && Md != null && H != null) Ev.RemoveEventHandler(Md, H); } catch { } H = null; }
        }
        // 📚 the ORDER BOOK (market depth): the resting buy / sell orders at each price, kept from NinjaTrader's depth updates (add / update /
        // remove at a position, 0 = best). Reached by name like the trades; no depth subscription = the panel says so
        private sealed class OfDepthTap
        {
            public object Md; public System.Reflection.EventInfo Ev; public Delegate H; public string Problem = ""; public long Count; public readonly object Gate = new object();
            readonly List<double[]> bids = new List<double[]>(), asks = new List<double[]>();
            readonly Dictionary<string, System.Reflection.PropertyInfo> props = new Dictionary<string, System.Reflection.PropertyInfo>(); Type propsOf;
            object P(object e, string name)
            {
                if (e == null) return null; var t = e.GetType(); if (t != propsOf) { props.Clear(); propsOf = t; }
                System.Reflection.PropertyInfo pi; if (!props.TryGetValue(name, out pi)) props[name] = pi = t.GetProperty(name);
                try { return pi == null ? null : pi.GetValue(e, null); } catch { return null; }
            }
            static double D(object o) { try { return o == null ? 0 : Convert.ToDouble(o, CultureInfo.InvariantCulture); } catch { return 0; } }
            public void On(object sender, EventArgs e)
            {
                try
                {
                    string side = Convert.ToString(P(e, "MarketDataType")); var book = side == "Ask" ? asks : side == "Bid" ? bids : null; if (book == null) return;
                    string op = Convert.ToString(P(e, "Operation")); int pos = (int)D(P(e, "Position")); double px = D(P(e, "Price")), v = D(P(e, "Volume"));
                    lock (Gate)
                    {
                        if (op == "Add") { if (pos >= 0 && pos <= book.Count) book.Insert(pos, new[] { px, v }); }
                        else if (op == "Update") { if (pos >= 0 && pos < book.Count) book[pos] = new[] { px, v }; }
                        else if (op == "Remove") { if (pos >= 0 && pos < book.Count) book.RemoveAt(pos); }
                        Count++;
                    }
                }
                catch { }
            }
            // the best n levels of one side (price, contracts), best first
            public List<double[]> Side(bool ask, int n) { lock (Gate) return (ask ? asks : bids).Where(x => x[0] > 0).Take(n).Select(x => new[] { x[0], x[1] }).ToList(); }
            public void Stop() { try { if (Ev != null && Md != null && H != null) Ev.RemoveEventHandler(Md, H); } catch { } H = null; }
        }
        private static OfDepthTap StartDepthTap(Instrument inst)
        {
            var tap = new OfDepthTap();
            try
            {
                var tg = FindNtType("NinjaTrader.Data.MarketDepth`1"); var tr = FindNtType("NinjaTrader.Data.MarketDepthRow");
                if (tg == null || tr == null || inst == null) { tap.Problem = "NinjaTrader's MarketDepth not found"; return tap; }
                var t = tg.MakeGenericType(tr); tap.Md = Activator.CreateInstance(t, new object[] { inst }); tap.Ev = t.GetEvent("Update");
                if (tap.Ev == null) { tap.Problem = "MarketDepth has no Update event"; return tap; }
                tap.H = Delegate.CreateDelegate(tap.Ev.EventHandlerType, tap, typeof(OfDepthTap).GetMethod("On")); tap.Ev.AddEventHandler(tap.Md, tap.H);
            }
            catch (Exception ex) { tap.Problem = ex.Message; }
            return tap;
        }
        private static OfLiveTap StartOfTap(Instrument inst)
        {
            var tap = new OfLiveTap();
            try
            {
                var t = FindNtType("NinjaTrader.Data.MarketData"); if (t == null || inst == null) { tap.Problem = "NinjaTrader's MarketData not found"; return tap; }
                tap.Md = Activator.CreateInstance(t, new object[] { inst }); tap.Ev = t.GetEvent("Update"); if (tap.Ev == null) { tap.Problem = "MarketData has no Update event"; return tap; }
                tap.H = Delegate.CreateDelegate(tap.Ev.EventHandlerType, tap, typeof(OfLiveTap).GetMethod("On")); tap.Ev.AddEventHandler(tap.Md, tap.H);
            }
            catch (Exception ex) { tap.Problem = ex.Message; }
            return tap;
        }
        // 1-minute bars of a time range from NinjaTrader (history to scroll back, minutes refilled after a disconnect)
        private void RequestRange(Instrument inst, string sym, DateTime from, DateTime to, Dispatcher disp, Action<List<KeystoneArcBar>, string> done)
        {
            BarsRequest rq = null;
            try
            {
                string hs; TradingHours hours = null; try { hours = ResolveRequestTradingHours(sym, 1, out hs); } catch { }
                rq = new BarsRequest(inst, from, to) { BarsPeriod = new BarsPeriod { BarsPeriodType = BarsPeriodType.Minute, Value = 1 }, TradingHours = hours, MergePolicy = MergePolicy.UseGlobalSettings };
                rq.Request(delegate(BarsRequest reply, ErrorCode error, string message)
                {
                    var list = new List<KeystoneArcBar>(); string problem = "";
                    try { if (error != ErrorCode.NoError || reply == null || reply.Bars == null) problem = error + " " + message; else for (int i = 0; i < reply.Bars.Count; i++) list.Add(new KeystoneArcBar { Symbol = sym, Time = reply.Bars.GetTime(i), Open = reply.Bars.GetOpen(i), High = reply.Bars.GetHigh(i), Low = reply.Bars.GetLow(i), Close = reply.Bars.GetClose(i), Volume = reply.Bars.GetVolume(i) }); }
                    catch (Exception ex) { problem = ex.Message; }
                    try { reply.Dispose(); } catch { }
                    disp.BeginInvoke(new Action(() => done(list, problem)));
                });
            }
            catch (Exception ex) { try { if (rq != null) rq.Dispose(); } catch { } disp.BeginInvoke(new Action(() => done(new List<KeystoneArcBar>(), ex.Message))); }
        }

        private LiveFeed StartLiveFeed(string sym, Dispatcher disp, Action<LiveFeed> ready)
        {
            var f = new LiveFeed { Symbol = sym }; string source; Instrument inst = null; bool mgc = KeystoneMoveStudy.IsMgc(sym);
            try { inst = ResolveStudioInstrument(sym, DateTime.Now.AddDays(mgc ? 10 : 14), out source); } catch (Exception ex) { source = ex.Message; }
            if (inst == null) { f.Problem = "NO CONTRACT • " + source; disp.BeginInvoke(new Action(() => ready(f))); return f; }
            f.Contract = inst.FullName; f.Inst = inst;
            string hs; TradingHours hours = null; try { hours = ResolveRequestTradingHours(sym, 1, out hs); } catch { }
            try { f.Request = new BarsRequest(inst, 4000) { BarsPeriod = new BarsPeriod { BarsPeriodType = BarsPeriodType.Minute, Value = 1 }, TradingHours = hours, MergePolicy = MergePolicy.UseGlobalSettings }; }
            catch (Exception ex) { f.Problem = "REQUEST ERROR • " + ex.Message; disp.BeginInvoke(new Action(() => ready(f))); return f; }
            Func<Bars, int, KeystoneArcBar> read = (bs, i) => new KeystoneArcBar { Symbol = sym, Time = bs.GetTime(i), Open = bs.GetOpen(i), High = bs.GetHigh(i), Low = bs.GetLow(i), Close = bs.GetClose(i), Volume = bs.GetVolume(i) };
            f.Handler = (sender, e) =>
            {
                try { var rq = f.Request; if (rq == null || rq.Bars == null || f.Stopped) return; f.LastUpdate = DateTime.UtcNow; lock (f.Gate) for (int i = Math.Max(0, e.MinIndex); i <= e.MaxIndex && i < rq.Bars.Count; i++) f.Updates.Enqueue(read(rq.Bars, i)); } catch { }
            };
            f.Request.Update += f.Handler;
            f.Request.Request(delegate(BarsRequest reply, ErrorCode error, string message)
            {
                var list = new List<KeystoneArcBar>();
                try { if (error != ErrorCode.NoError || reply == null || reply.Bars == null) f.Problem = error + " " + message; else for (int i = 0; i < reply.Bars.Count; i++) list.Add(read(reply.Bars, i)); }
                catch (Exception ex) { f.Problem = ex.Message; }
                f.Initial = list; f.Ready = f.Problem == "" && list.Count > 0; if (list.Count == 0 && f.Problem == "") f.Problem = "NINJATRADER SENT NO BARS (is the data connection on?)";
                disp.BeginInvoke(new Action(() => ready(f)));
            });
            return f;
        }
