        // 1-minute bars already saved on this PC by earlier loads (the saved-data cache and the bar store): the biggest file per
        // instrument, so the replay trader works without loading anything first.
        private static List<KeystoneArcBar> SavedOneMinuteBars(string symbol)
        {
            try
            {
                string folder = LabCacheFolder(); if (!Directory.Exists(folder)) return null;
                foreach (var f in new DirectoryInfo(folder).GetFiles("*.bars").OrderByDescending(x => x.Length))
                {
                    using (var reader = new BinaryReader(File.OpenRead(f.FullName)))
                    {
                        string key = reader.ReadString(); var parts = key.Split('|');
                        if (parts.Length < 4 || !string.Equals(parts[1], symbol, StringComparison.OrdinalIgnoreCase) || parts[3] != "1") continue;
                        if (parts[0] == "store1") { int nr = reader.ReadInt32(); for (int i = 0; i < nr; i++) { reader.ReadInt64(); reader.ReadInt64(); } }
                        else if (parts[0] != "v1") continue;
                        int n = reader.ReadInt32(); var list = new List<KeystoneArcBar>(n);
                        for (int i = 0; i < n; i++) list.Add(new KeystoneArcBar { Time = new DateTime(reader.ReadInt64()), Symbol = symbol, Open = reader.ReadDouble(), High = reader.ReadDouble(), Low = reader.ReadDouble(), Close = reader.ReadDouble(), Volume = reader.ReadInt64() });
                        if (list.Count > 100) return list.OrderBy(b => b.Time).ToList();
                    }
                }
            }
            catch { }
            return null;
        }

        // ---- REPLAY TRADER v3: one tab per instrument on one clock and one account; a TradingView-style chart in each tab --
        // one logged pattern plan: resolved when the replay clock passes its first barrier touch or 30 minutes
        private sealed class PredRecord { public DateTime Session, Time; public string Symbol = ""; public int Side, BarIndex; public double Entry, Barrier, UpShare, BaseUp; public bool Taken; }
        private static string PredictionLogFile() { return Path.Combine(StudioFolder(), "PredictionLog.csv"); }
        private sealed class ReplayDrawing { public string Kind = "HLINE"; public DateTime T1, T2; public double P1, P2; public string Color = "#E040FB"; public double Width = 1.5; public string Text = string.Empty; }
        // chart templates: background, grid, candles, text
        private sealed class ChartTheme { public string Name; public SolidColorBrush Bg, Grid, Up, Down, Text; public bool Hollow; public string Style = "", Group = ""; }
        private static SolidColorBrush HexBrush(string hex)
        {
            try
            {
                string h = (hex ?? "").TrimStart('#'); if (h.Length == 6) h = "FF" + h;
                var b = new SolidColorBrush(Color.FromArgb(Convert.ToByte(h.Substring(0, 2), 16), Convert.ToByte(h.Substring(2, 2), 16), Convert.ToByte(h.Substring(4, 2), 16), Convert.ToByte(h.Substring(6, 2), 16))); b.Freeze(); return b;
            }
            catch { return new SolidColorBrush(Color.FromRgb(255, 0, 255)); }
        }
        // ---- KEYSTONE window frame: our own title bar (logo, title, minimize / maximize / close) instead of the Windows / NinjaTrader one
        private sealed class KeystoneWindow : Window
        {
            private bool wrapping; private TextBlock titleText; private DockPanel frame;
            public bool KeepSize;   // a window placed beside a chart: opens at its own size, never maximized by itself
            private static ImageSource icon;
            /* 🪟 BUILD 2026-11-11j — OPEN WINDOWS (like SpasiX MT5's title-bar tabs): every main window's title bar has ⧉ WINDOWS ▾ — the windows open now (click = to
               the front), 🏠 HOME and the studios to open (each one of its kind: an open one comes to the front) */
            public static readonly List<KeystoneWindow> Open = new List<KeystoneWindow>();
            public static Func<List<Tuple<string, Action>>> Launch;   // set by the add-on: (label, open it)
            public static bool IsMain(Window x) { return x != null && x.Owner == null && x.SizeToContent == SizeToContent.Manual && (double.IsNaN(x.Width) || x.Width >= 700); }
            public static List<KeystoneWindow> MainOpen() { return Open.Where(x => IsMain(x)).ToList(); }
            public static void ShowWindowsMenu(KeystoneWindow from, UIElement target)
            {
                var cm = new ContextMenu();
                cm.Items.Add(new MenuItem { Header = "⧉ OPEN WINDOWS", IsEnabled = false, FontWeight = FontWeights.Bold });
                foreach (var x in MainOpen())
                {
                    var wx = x; var mi = new MenuItem { Header = (wx == from ? "●  " : "     ") + (wx.Title ?? "").Replace("SPASIX FUTURE • ", "").Replace("SPASIX FUTURE", "SPASIX FUTURE (HOME)"), FontWeight = wx == from ? FontWeights.Bold : FontWeights.Normal };
                    mi.Click += delegate { try { if (wx.WindowState == WindowState.Minimized) wx.WindowState = WindowState.Maximized; wx.Activate(); } catch { } }; cm.Items.Add(mi);
                }
                var l = Launch != null ? Launch() : null;
                if (l != null && l.Count > 0) { cm.Items.Add(new Separator()); cm.Items.Add(new MenuItem { Header = "OPEN (one of each — an open one comes to the front)", IsEnabled = false, FontWeight = FontWeights.Bold }); foreach (var it in l) { var act = it.Item2; var mi = new MenuItem { Header = it.Item1 }; mi.Click += delegate { try { act(); } catch { } }; cm.Items.Add(mi); } }
                cm.PlacementTarget = target; cm.IsOpen = true;
            }
            public KeystoneWindow()
            {
                Open.Add(this); Closed += delegate { Open.Remove(this); };
                HookMenus();   // ☰ our right-click menus in the glowing design
                try
                {
                    System.Windows.Shell.WindowChrome.SetWindowChrome(this, new System.Windows.Shell.WindowChrome { CaptionHeight = 34, ResizeBorderThickness = new Thickness(6), GlassFrameThickness = new Thickness(0), CornerRadius = new CornerRadius(0), UseAeroCaptionButtons = false });
                    Icon = BrandIcon();
                    // smooth: a dark window (never a white / blank flash), no Windows zoom animation, the content fades in once it is laid out
                    Background = new SolidColorBrush(Color.FromRgb(9, 13, 20));
                    SourceInitialized += delegate { try { var h = new System.Windows.Interop.WindowInteropHelper(this).Handle; int on = 1; DwmSetWindowAttribute(h, 3, ref on, 4); } catch { } };
                    Loaded += delegate { var c0 = Content as UIElement; if (c0 != null) c0.BeginAnimation(UIElement.OpacityProperty, new DoubleAnimation(0, 1, TimeSpan.FromMilliseconds(200)) { EasingFunction = new QuadraticEase { EasingMode = EasingMode.EaseOut } }); };
                    StateChanged += delegate { if (frame != null) frame.Margin = WindowState == WindowState.Maximized ? new Thickness(7) : new Thickness(0); };
                    // every main window (the launcher, live trading, the studios, labs, reports) opens full screen; small dialogs and
                    // windows placed beside a chart keep their size
                    // (BUILD 2026-11-11e, user's request "always default all windows larger squared size"): every resizable main window opens MAXIMIZED,
                    // its restore size (the ▢ button) = 90 % of the screen's work area, centred • question dialogs (fixed size / sized to content) and
                    // windows placed beside a chart (KeepSize) keep their own size
                    SourceInitialized += delegate { if (!KeepSize && Width >= 700 && SizeToContent == SizeToContent.Manual && (ResizeMode == ResizeMode.CanResize || ResizeMode == ResizeMode.CanResizeWithGrip)) MaximizeWithRestore(this); };
                }
                catch { }
            }
            [System.Runtime.InteropServices.DllImport("dwmapi.dll")] private static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int value, int size);   // 3 = DWMWA_TRANSITIONS_FORCEDISABLED
            public new string Title { get { return base.Title; } set { base.Title = value; if (titleText != null) titleText.Text = (value ?? "").Replace("SPASIX FUTURE • ", "").Replace("SPASIX FUTURE", ""); } }
            // the logo: a keystone (the top stone of an arch) in cyan → violet, with its hollow core
            public static ImageSource BrandIcon()
            {
                if (icon != null) return icon;
                try
                {
                    var g = new GeometryDrawing(new LinearGradientBrush(Color.FromRgb(0, 229, 255), Color.FromRgb(124, 77, 255), 90), null, Geometry.Parse("M0,0 L24,0 L18.5,22 L5.5,22 Z M8,5 L16,5 L13.6,16 L10.4,16 Z"));
                    var di = new DrawingImage(g); di.Freeze(); icon = di;
                }
                catch { }
                return icon;
            }
            public static FrameworkElement Logo(double scale)
            {
                var c = new System.Windows.Controls.Canvas { Width = 24 * scale, Height = 22 * scale, VerticalAlignment = VerticalAlignment.Center };
                Func<double, double, System.Windows.Point> P = (x, y) => new System.Windows.Point(x * scale, y * scale);
                c.Children.Add(new System.Windows.Shapes.Polygon { Fill = new LinearGradientBrush(Color.FromRgb(0, 229, 255), Color.FromRgb(124, 77, 255), 90), Points = new PointCollection { P(0, 0), P(24, 0), P(18.5, 22), P(5.5, 22) } });
                c.Children.Add(new System.Windows.Shapes.Polygon { Fill = new SolidColorBrush(Color.FromRgb(9, 13, 20)), Points = new PointCollection { P(8, 5), P(16, 5), P(13.6, 16), P(10.4, 16) } });
                var dot = new System.Windows.Shapes.Ellipse { Width = 3.4 * scale, Height = 3.4 * scale, Fill = new SolidColorBrush(Color.FromRgb(255, 209, 102)) }; System.Windows.Controls.Canvas.SetLeft(dot, 10.3 * scale); System.Windows.Controls.Canvas.SetTop(dot, 8.2 * scale); c.Children.Add(dot);
                return c;
            }
            protected override void OnContentChanged(object oldContent, object newContent)
            {
                base.OnContentChanged(oldContent, newContent);
                if (wrapping || newContent == null || ReferenceEquals(newContent, frame)) return;
                var inner = newContent as UIElement; if (inner == null) return;
                wrapping = true;
                try
                {
                    // the bar: logo • SPASIX FUTURE wordmark • window title • — ▢ ✕, a thin cyan → violet line under it
                    var bar = new DockPanel { Height = 34, Background = new LinearGradientBrush(Color.FromRgb(8, 11, 22), Color.FromRgb(16, 22, 44), 0), LastChildFill = true };
                    var left = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(12, 0, 12, 0), VerticalAlignment = VerticalAlignment.Center };
                    left.Children.Add(Logo(0.82));
                    var word = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(9, 0, 14, 0) };
                    word.Children.Add(new TextBlock { Text = "SPASIX", Foreground = System.Windows.Media.Brushes.White, FontSize = 13, FontWeight = FontWeights.Bold, FontFamily = new FontFamily("Segoe UI") });
                    word.Children.Add(new TextBlock { Text = " FUTURE", Foreground = new LinearGradientBrush(Color.FromRgb(0, 229, 255), Color.FromRgb(124, 77, 255), 0), FontSize = 13, FontWeight = FontWeights.Bold, FontFamily = new FontFamily("Segoe UI") });
                    left.Children.Add(word);
                    if (IsMain(this))
                    {   /* ⧉ WINDOWS ▾: switch between the open studios / open another one (11j) */
                        var wb = new Border { Background = new SolidColorBrush(Color.FromArgb(60, 0, 229, 255)), CornerRadius = new CornerRadius(4), Padding = new Thickness(9, 2, 9, 2), Margin = new Thickness(0, 0, 12, 0), Cursor = System.Windows.Input.Cursors.Hand, VerticalAlignment = VerticalAlignment.Center, Tag = "win.windows",
                            ToolTip = "the SPASIX FUTURE windows open now (click one = to the front), 🏠 HOME and the studios — several stay open at once",
                            Child = new TextBlock { Text = "⧉ WINDOWS ▾", Foreground = new SolidColorBrush(Color.FromRgb(200, 230, 255)), FontSize = 11, FontWeight = FontWeights.Bold, FontFamily = new FontFamily("Segoe UI Symbol") } };
                        System.Windows.Shell.WindowChrome.SetIsHitTestVisibleInChrome(wb, true);
                        wb.MouseLeftButtonUp += delegate { ShowWindowsMenu(this, wb); }; left.Children.Add(wb);
                    }
                    DockPanel.SetDock(left, Dock.Left); bar.Children.Add(left);
                    var btns = new StackPanel { Orientation = Orientation.Horizontal }; DockPanel.SetDock(btns, Dock.Right); bar.Children.Add(btns);
                    Func<string, Color, Action, Border> cap = (glyph, hover, act) =>
                    {
                        var b = new Border { Width = 46, Height = 34, Background = System.Windows.Media.Brushes.Transparent, Cursor = System.Windows.Input.Cursors.Hand, Child = new TextBlock { Text = glyph, Foreground = new SolidColorBrush(Color.FromRgb(200, 210, 230)), FontSize = 12, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center, FontFamily = new FontFamily("Segoe UI Symbol") } };
                        System.Windows.Shell.WindowChrome.SetIsHitTestVisibleInChrome(b, true);
                        b.MouseEnter += delegate { b.Background = new SolidColorBrush(hover); }; b.MouseLeave += delegate { b.Background = System.Windows.Media.Brushes.Transparent; };
                        b.MouseLeftButtonUp += delegate { act(); };
                        btns.Children.Add(b); return b;
                    };
                    if (ResizeMode != ResizeMode.NoResize) cap("—", Color.FromRgb(40, 50, 75), () => WindowState = WindowState.Minimized);
                    if (ResizeMode == ResizeMode.CanResize || ResizeMode == ResizeMode.CanResizeWithGrip) cap("▢", Color.FromRgb(40, 50, 75), () => WindowState = WindowState == WindowState.Maximized ? WindowState.Normal : WindowState.Maximized);
                    cap("✕", Color.FromRgb(232, 17, 35), () => Close());
                    titleText = new TextBlock { Text = (base.Title ?? "").Replace("SPASIX FUTURE • ", "").Replace("SPASIX FUTURE", ""), Foreground = new SolidColorBrush(Color.FromRgb(150, 165, 195)), FontSize = 12, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center, TextTrimming = TextTrimming.CharacterEllipsis };
                    bar.Children.Add(titleText);
                    var line = new Border { Height = 2, Background = new LinearGradientBrush(Color.FromRgb(0, 229, 255), Color.FromArgb(0, 124, 77, 255), 0) };
                    var f = new DockPanel { LastChildFill = true };
                    DockPanel.SetDock(bar, Dock.Top); f.Children.Add(bar); DockPanel.SetDock(line, Dock.Top); f.Children.Add(line);
                    frame = f; Content = f;   // the window lets go of the content first, then the frame takes it
                    f.Children.Add(inner);
                }
                finally { wrapping = false; }
            }
        }
