            Func<List<KeystoneArcBar>, DateTime, DateTime, DateTime, DateTime, int, int, double, double, double, Tuple<string, DateTime, DateTime, double>> playOut = (bars, from, entryUntil, exitBy, now, dir, entryKind, ent, stp, tgt) =>
            {
