                var hoverDraw = pn.MouseOver && pn.Drag == null && pn.Tool == "CURSOR" ? (prevHandles.Where(h => pn.MouseX >= h.Item1[0] && pn.MouseX <= h.Item1[2] && pn.MouseY >= h.Item1[1] && pn.MouseY <= h.Item1[3]).Select(h => h.Item2).LastOrDefault() ?? drawingAt(pn, pn.MouseX, pn.MouseY)) : null;
                foreach (var d in (liveWindow && layerOf("DRAWINGS", KeystoneLiveTools.Always) == KeystoneLiveTools.Off ? new List<ReplayDrawing>() : pn.Drawings).Concat(pn.Preview != null ? new[] { pn.Preview } : new ReplayDrawing[0]))
                {
                    double x1 = xOfIndex(pn, indexOfTime(pn, d.T1)), x2 = xOfIndex(pn, indexOfTime(pn, d.T2)), y1 = yOf(pn, d.P1), y2 = yOf(pn, d.P2);
                    var dc = colorOf(d.Color); double dw = d.Width <= 0 ? 1.5 : d.Width;
