                        Func<SolidColorBrush, SolidColorBrush, double> cd0 = (p1, p2) => Math.Sqrt(Math.Pow(p1.Color.R - p2.Color.R, 2) + Math.Pow(p1.Color.G - p2.Color.G, 2) + Math.Pow(p1.Color.B - p2.Color.B, 2));
                        var cands = d.Text == "bullish" ? new[] { "#00E676", "#76FF03", "#448AFF", "#00E5FF", "#64FFDA" } : new[] { "#FF1744", "#D500F9", "#FF6D00", "#FF4081", "#F50057" };
                        dc = cands.Select(h => colorOf(h)).OrderByDescending(b0 => Math.Min(Math.Min(cd0(b0, th.Up), cd0(b0, th.Down)), 140)).First();
