                        double ym = (y1 + y2) / 2; cv.Children.Add(new System.Windows.Shapes.Line { X1 = left, X2 = pn.PlotW, Y1 = ym, Y2 = ym, Stroke = dc, StrokeThickness = 1, StrokeDashArray = new DoubleCollection { 4, 3 } });
