                            var fvl = new Border { Background = Tint(Bg, 225), BorderBrush = dc, BorderThickness = new Thickness(1, 1, 3, 1), CornerRadius = new CornerRadius(3), Padding = new Thickness(4, 0, 4, 1), Child = fvt, Opacity = hovF ? 1 : 0.85 };
                            fvl.Measure(new Size(double.PositiveInfinity, double.PositiveInfinity));
