                    {
                        var hs = new List<Tuple<double, double, string>>();
                        double xl = Math.Min(x1, x2), xr2 = Math.Max(x1, x2), yt = Math.Min(y1, y2), yb = Math.Max(y1, y2);
                        string tL = x1 <= x2 ? "T1" : "T2", tR = x1 <= x2 ? "T2" : "T1", pT = y1 <= y2 ? "P1" : "P2", pB = y1 <= y2 ? "P2" : "P1";
                        switch (d.Kind)
