                            case "HLINE": hs.Add(Tuple.Create(pn.PlotW / 2, y1, "P1")); hs.Add(Tuple.Create(pn.PlotW / 4, y1, "P1")); hs.Add(Tuple.Create(pn.PlotW * 3 / 4, y1, "P1")); break;
