                {
                    Func<string, Brush> kindBrush = k => k == "buy" ? Cyan : k == "sell" ? Orchid : k == "exit" ? Text : Gold;
                    // report times are New York clock times of the session: 18:00–23:59 belong to the evening BEFORE the session date
                    Func<TimeSpan, DateTime> repAt = t0 => t0.Hours >= 18 ? session.Date.AddDays(-1) + t0 : session.Date + t0;
                    foreach (var mk in pn.ReportDay.Markers)
                    {
                        var at = repAt(mk.Time); if (at.AddMinutes(1) > r.Time) continue;
                        double mx = xOfIndex(pn, indexOfTime(pn, at.AddMinutes(1))); if (mx < 0 || mx > pn.PlotW) continue;
                        double my = double.IsNaN(mk.Price) ? pn.Top + 14 : yOf(pn, mk.Price) + (mk.Kind == "sell" ? -14 : 14);
                        var dot = new System.Windows.Shapes.Ellipse { Width = 9, Height = 9, Fill = kindBrush(mk.Kind), Stroke = System.Windows.Media.Brushes.White, StrokeThickness = 1 };
                        System.Windows.Controls.Canvas.SetLeft(dot, mx - 4.5); System.Windows.Controls.Canvas.SetTop(dot, my - 4.5); cv.Children.Add(dot);
                        var lb = new Border { Background = Tint(Bg, 210), BorderBrush = kindBrush(mk.Kind), BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(3), Padding = new Thickness(4, 1, 4, 1), Child = new TextBlock { Text = mk.Text, Foreground = kindBrush(mk.Kind), FontSize = 10.5, FontWeight = FontWeights.Bold } };
                        System.Windows.Controls.Canvas.SetLeft(lb, mx + 7); System.Windows.Controls.Canvas.SetTop(lb, my - 9); cv.Children.Add(lb);
                    }
                    foreach (var rt in pn.ReportDay.Trades)
