                        double x1 = xOfIndex(pn, indexOfTime(pn, tin.AddMinutes(1))), y1 = yOf(pn, rt.Entry); var tout = repAt(rt.ExitTime); bool closed = tout <= r.Time && !double.IsNaN(rt.Exit);
                        var tri = new System.Windows.Shapes.Polygon { Fill = rt.Dir > 0 ? Cyan : Orchid, Points = new PointCollection { new System.Windows.Point(x1, y1), new System.Windows.Point(x1 - 6, y1 + (rt.Dir > 0 ? 10 : -10)), new System.Windows.Point(x1 + 6, y1 + (rt.Dir > 0 ? 10 : -10)) } }; cv.Children.Add(tri);
                        if (!closed) continue;
