                        cv.Children.Add(new System.Windows.Shapes.Line { X1 = x1, Y1 = y1, X2 = x2, Y2 = y2, Stroke = MoneyBrush(rt.Pnl), StrokeThickness = 1.5, StrokeDashArray = new DoubleCollection { 3, 2 } });
                        var pl = new TextBlock { Text = "REPORT " + (rt.Dir > 0 ? "LONG" : "SHORT") + " " + Signed(rt.Pnl) + (rt.Why != "" ? " • " + rt.Why : ""), Foreground = MoneyBrush(rt.Pnl), FontSize = 10.5, FontWeight = FontWeights.Bold };
                        System.Windows.Controls.Canvas.SetLeft(pl, x2 + 6); System.Windows.Controls.Canvas.SetTop(pl, y2 - 8); cv.Children.Add(pl);
                    }
                }
                // LIVE: the setup arrows take the two colours furthest from this theme's candles; ONLY NEW hides the ones formed before the window opened
                Brush buyC = Cyan, sellC = Orchid;
                if (liveWindow)
                {
                    Func<Brush, Color> colOf = b0 => { var sb = b0 as SolidColorBrush; return sb != null ? sb.Color : Color.FromRgb(128, 128, 128); };
                    Color cu = colOf(th.Up), cd = colOf(th.Down);
                    Func<string, double> farness = hx => { var c0 = colorOf(hx).Color; Func<Color, double> dist = c1 => Math.Sqrt(Math.Pow(c0.R - c1.R, 2) + Math.Pow(c0.G - c1.G, 2) + Math.Pow(c0.B - c1.B, 2)); return Math.Min(dist(cu), dist(cd)); };
                    var ranked = new[] { "#FFEA00", "#FF9100", "#FFFFFF", "#76FF03", "#2979FF", "#00E5FF", "#E040FB" }.OrderByDescending(farness).ToList();
                    buyC = colorOf("#00E676"); sellC = colorOf("#FF1744");   // every indicator: BUY = green box arrow, SELL = red box arrow
                    if (setupsFrom == DateTime.MinValue) setupsFrom = r.Time;
                }
                bool onlyNew = liveWindow && layerOf("SETUPS.NEW", 0) == 1;
                // every strategy setup that reached its outcome is recorded once (taken by you or not) → SetupLog.csv
                if (!pn.IsSplit && signalBox.SelectedIndex > 0 && signalBox.SelectedIndex < KeystoneReplaySignals.Names.Length)
                {
                    string srcS = KeystoneReplaySignals.Names[signalBox.SelectedIndex];
                    foreach (var sg in pn.Signals.Where(x => x.Time <= r.Time))
                    {
                        string sk = sg.Time.Ticks + "|" + sg.Dir + "|" + sg.Tag; if (setupLogged.Contains((liveWindow ? "" : "R|") + pn.Symbol + "|" + srcS + "|" + sk)) continue;
                        double entS = sg.Entry, stpS = !double.IsNaN(sg.Stop) ? sg.Stop : sg.StopDist > 0 ? entS - sg.Dir * sg.StopDist : double.NaN;
                        if (double.IsNaN(stpS) || Math.Abs(entS - stpS) <= 0) continue;
                        double tgtS = !double.IsNaN(sg.Target) ? sg.Target : sg.TargetDist > 0 ? entS + sg.Dir * sg.TargetDist : entS + sg.Dir * 2 * Math.Abs(entS - stpS);
                        int kindS = sg.Order == "STOP" || sg.Inverted ? 2 : sg.Order == "LIMIT" ? 1 : 0;
                        DateTime untilS = kindS == 0 ? sg.Time : sg.CancelAt == DateTime.MaxValue ? sg.Time.AddHours(2) : sg.CancelAt, exitS = sg.Exit > sg.Time ? sg.Exit : sg.Time.AddHours(4);
                        logPlayed(pn, srcS, sk, sg.Dir, sg.Time, (sg.Order == "MARKET" ? "at the signal" : sg.Order.ToLowerInvariant() + " order") + (sg.Tier != "" ? " • grade " + sg.Tier : ""), entS, stpS, tgtS, playOut(r.Bars, sg.Time, untilS, exitS, r.Time, sg.Dir, kindS, entS, stpS, tgtS));
                    }
                }
                // a MATCHES entry waiting for its outcome: price back to the entry within 30 min, then target / stop, out after 60 min
                {
