                    if (!pn.IsSplit && matchPending.TryGetValue(pn.Symbol, out mp))
                    {
                        var resM = playOut(r.Bars, mp.Item1, mp.Item1.AddMinutes(30), mp.Item1.AddMinutes(60), r.Time, mp.Item2, 1, mp.Item3, mp.Item4, mp.Item5);
                        if (resM != null) { logPlayed(pn, "MATCHES", mp.Item1.Ticks.ToString(), mp.Item2, mp.Item1, "pullback limit", mp.Item3, mp.Item4, mp.Item5, resM); matchPending.Remove(pn.Symbol); }
                    }
                }
                // the chart's trades (backtest): each finished trade from its entry to its exit — ✔ WIN +$ green / ✖ LOSS −$ red with the
                // account it was booked to (prop sim); a pending limit / stop entry of the strategy flashes until it fills or is cancelled
                if (!liveWindow && pn.Trader != null && !pn.IsSplit)   // CLEAN keeps the trades (entries / exits / WIN-LOSS)
                {
                    double pulse = 0.5 + 0.5 * Math.Sin(DateTime.Now.TimeOfDay.TotalMilliseconds / 200.0);
                    var tradeTagRects = new List<double[]>(); studioTradeTags = tradeTagRects;   /* the result tags drawn (x, y, w, h, the candles' top / bottom under them) — the smoke test checks them */
                    foreach (var f in pn.Trader.Fills.Where(f0 => f0.ExitTime <= r.Time).Reverse().Take(40))
                    {
                        double x1 = xOfIndex(pn, indexOfTime(pn, f.EntryTime)), x2 = xOfIndex(pn, indexOfTime(pn, f.ExitTime)); if (x2 < 0 || x1 > pn.PlotW) continue;
                        double y1 = yOf(pn, f.Entry), y2 = yOf(pn, f.Exit); bool won = f.Net > 0; Brush wc = won ? Green : Red; int fd = f.Side == "BUY" ? 1 : -1;
                        cv.Children.Add(new System.Windows.Shapes.Line { X1 = x1, Y1 = y1, X2 = x2, Y2 = y2, Stroke = wc, StrokeThickness = 1.6, StrokeDashArray = new DoubleCollection { 4, 2 }, Opacity = 0.9 });
                        // the entry arrow: once the trade is closed it takes the result's colour (green = winner, red = loser)
                        var inDot = new System.Windows.Shapes.Polygon { Fill = wc, Stroke = System.Windows.Media.Brushes.White, StrokeThickness = 1, Points = new PointCollection { new System.Windows.Point(x1, y1), new System.Windows.Point(x1 - 7, y1 + fd * 12), new System.Windows.Point(x1 + 7, y1 + fd * 12) } };
                        string fAcc = fillAccount != null ? fillAccount(f) : ""; string fInfo = (won ? "✔ WINNER " : "✖ LOSER ") + f.Side + " " + f.Qty + " " + pn.Symbol + " • in " + f.EntryTime.ToString("HH:mm:ss") + " @ " + fmt(f.Entry) + " • out " + f.ExitTime.ToString("HH:mm:ss") + " @ " + fmt(f.Exit) + " (" + f.Reason + ") • " + f.Points.ToString("+0.##;-0.##", CultureInfo.InvariantCulture) + " pts • " + Signed(f.Net) + " net • held " + ((int)(f.ExitTime - f.EntryTime).TotalMinutes) + " min" + (fAcc != "" ? " • " + fAcc : "");
