                foreach (var pn in panes.Where(p => p.Trader != null)) { pn.Trader.CancelOrders(); pn.Trader.CloseAll(hitGoal ? "DAY GOAL" : "DAY LOSS LIMIT"); saveFills(pn); }
                dayLocked = true; status.Text = (hitGoal ? "DAY GOAL REACHED • " : "DAY LOSS LIMIT • ") + Signed(realized()) + " • flat and locked for today (END DAY + SAVE)"; status.Foreground = hitGoal ? Green : Red;
            };
            Action<ReplayPane> autoTrade = pn =>
            {
                if (modeBox.SelectedIndex != 1 || dayLocked || blown || pn.Trader == null) return; var r = pn.Trader;
                // tested rules: work their stop orders (one cancels the other), then the bracket from the fill and the time exit
                if (pn.AutoPending.Count > 0)
                {
                    if (r.Position != 0)
                    {
                        var filled = pn.AutoPending.FirstOrDefault(x => x.Dir == Math.Sign(r.Position)) ?? pn.AutoPending[0];
                        r.CancelOrders(); pn.AutoPending.Clear(); pn.AutoOpen = filled;
                        status.Text = "AUTO " + pn.Symbol + " • " + filled.Tag + " FILLED " + (filled.Dir > 0 ? "LONG " : "SHORT ") + Math.Abs(r.Position) + " @ " + fmt(r.AvgPrice) + " • other side cancelled"; status.Foreground = filled.Dir > 0 ? Green : Red;
                    }
