                            pg.Entry = stg.Item4; pg.ZoneLo = stg.Item2; pg.ZoneHi = stg.Item3; pg.Stop = pg.Entry - pg.Dir * pg.StopDist; pg.Target = pg.Entry + pg.Dir * pg.TargetDist;
                            r.Place(pg.Inverted ? "STOP" : "LIMIT", pg.Dir, q0, pg.Entry);
                            status.Text = "AUTO " + pn.Symbol + " • the FVG zone grew (" + fmt(stg.Item2) + " – " + fmt(stg.Item3) + ") • " + (pg.Dir > 0 ? "BUY LIMIT " : "SELL LIMIT ") + q0 + " moved to " + fmt(pg.Entry); status.Foreground = Cyan;
                        }
                    }
