                        if (Math.Abs(r.Position) + pendP0 + qP0 > prac.MaxQty) { refuse("🎯 PRACTICE MAX " + prac.MaxQty + " CONTRACTS on " + prac.Name + " • " + pn.Symbol + " holds " + Math.Abs(r.Position), Gold); return; }
