                    var nlO = newsLockAt(r.Time); if (nlO != null && Math.Sign(r.Position) != -sign) { refuse("NEWS LOCK • " + nlO.Time.ToString("HH:mm") + " " + nlO.Title + " • no new trades ±" + NumberAllowZero(newsLockBox, 0) + " min (closing is allowed)", Orange); return; }
