                    .Where(x => (x.Dir > 0 && buysBox.IsChecked == true) || (x.Dir < 0 && sellsBox.IsChecked == true)).ToList();
                // the coach: the same strategy on the 20 saved days before this one (background, cached per day + strategy)
                int kind = signalBox.SelectedIndex; string key = pn.Symbol + "|" + kind + "|" + session.ToString("yyyy-MM-dd"); if (pn.CoachKey == key) return;
                pn.CoachKey = key; pn.Coach = null; var cfgCopy = CloneConfig(studioCfg); double tpPts = NumberAllowZero(pn.Tp, 0); string symx = pn.Symbol; DateTime day = session; var disp = w.Dispatcher;
