                    if (side == 0) { status.Text = "🎯 LOCK RACE: no 60-minute trend before 9:30 NY on " + tNow.ToString("ddd d MMM", CultureInfo.InvariantCulture) + " yet (needs 8:30 → 9:30 on the chart)"; status.Foreground = Gold; return; }
