                Func<ReplayPane, string> coachContext = pc =>
                {
                    var sb = new StringBuilder(); var r = pc.Trader; if (r == null || r.Bars.Count == 0) return "no live data on " + pc.Symbol + " yet";
                    double pv = KeystoneMoveStudy.PointValue(pc.Symbol);
                    sb.AppendLine("instrument " + pc.Symbol + " (micro, $" + pv.ToString("0.##", CultureInfo.InvariantCulture) + " a point, tick " + r.Tick.ToString("0.##", CultureInfo.InvariantCulture) + ") • now " + r.Time.ToString("ddd yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture) + " • last " + fmt(r.Price) + " • chart timeframe " + pc.Tf + "m");
                    var sess1 = r.Bars; double hod = sess1.Max(b => b.High), lod = sess1.Min(b => b.Low), open0 = sess1[0].Open;
                    sb.AppendLine("session (from 18:00): open " + fmt(open0) + " high " + fmt(hod) + " low " + fmt(lod) + " • move " + (r.Price - open0 >= 0 ? "+" : "") + fmt(r.Price - open0) + " pts");
                    if (!double.IsNaN(pc.Pdh)) sb.AppendLine("yesterday: high " + fmt(pc.Pdh) + " low " + fmt(pc.Pdl) + " close " + fmt(pc.Pdc));
                    double spv = 0, sv = 0; foreach (var b in sess1) { double tp = (b.High + b.Low + b.Close) / 3, v = Math.Max(1, b.Volume); spv += tp * v; sv += v; } if (sv > 0) sb.AppendLine("VWAP (session) " + fmt(spv / sv));
                    var c5 = KeystoneEngLab.Candles(sess1, 5); sb.AppendLine("last 5-minute candles (time open high low close):");
                    foreach (var c in c5.Skip(Math.Max(0, c5.Count - 30))) sb.AppendLine("  " + c.Time.AddMinutes(-5).ToString("HH:mm") + " " + fmt(c.Open) + " " + fmt(c.High) + " " + fmt(c.Low) + " " + fmt(c.Close));
                    var c1 = sess1.Skip(Math.Max(0, sess1.Count - 15)).ToList(); sb.AppendLine("last 1-minute closes: " + string.Join(" ", c1.Select(b => fmt(b.Close))));
                    // open fair-value gaps on 5 minutes
                    var gaps = new List<string>();
                    for (int i = Math.Max(2, c5.Count - 120); i < c5.Count; i++)
                    {
                        double a1 = c5[i - 2].High, b1 = c5[i].Low, a2 = c5[i].High, b2 = c5[i - 2].Low; bool bull = b1 - a1 >= 2 * r.Tick, bear = b2 - a2 >= 2 * r.Tick; if (!bull && !bear) continue;
                        double lo = bull ? a1 : a2, hi = bull ? b1 : b2; bool filled = false; for (int j = i + 1; j < c5.Count && !filled; j++) filled = bull ? c5[j].Low <= lo : c5[j].High >= hi;
                        if (!filled) gaps.Add((bull ? "bullish " : "bearish ") + fmt(lo) + "-" + fmt(hi) + " (" + c5[i - 1].Time.AddMinutes(-5).ToString("HH:mm") + ")");
                    }
                    sb.AppendLine("open 5m fair-value gaps: " + (gaps.Count == 0 ? "none" : string.Join("; ", gaps.Skip(Math.Max(0, gaps.Count - 5)))));
                    if (r.Position == 0) sb.AppendLine("position: flat");
                    else
                    {
                        int dir = Math.Sign(r.Position); double un = r.Unrealized - KeystoneMoveStudy.Cost(pc.Symbol) * Math.Abs(r.Position);
                        sb.AppendLine("position: " + (dir > 0 ? "LONG " : "SHORT ") + Math.Abs(r.Position) + " @ " + fmt(r.AvgPrice) + " • open " + (un >= 0 ? "+$" : "-$") + Math.Abs(un).ToString("0.00", CultureInfo.InvariantCulture) + " (" + fmt(dir * (r.Price - r.AvgPrice)) + " pts) • stop " + (r.StopPts != 0 ? fmt(r.AvgPrice - dir * r.StopPts) : "NONE") + " • target " + (r.TargetPts > 0 ? fmt(r.AvgPrice + dir * r.TargetPts) : "none") + (r.Orders.Count > 0 ? " • working: " + string.Join(", ", r.Orders.Select(o => o.Label + " " + o.Qty + " @ " + fmt(o.Price))) : ""));
                    }
                    foreach (var o2 in panes.Where(x => x != pc && x.Trader != null && x.Trader.Position != 0)) sb.AppendLine("also open: " + o2.Symbol + " " + (o2.Trader.Position > 0 ? "LONG " : "SHORT ") + Math.Abs(o2.Trader.Position) + " @ " + fmt(o2.Trader.AvgPrice));
                    double tv; Func<string, double> T = k => todayVals.TryGetValue(k, out tv) ? tv : double.NaN;
                    sb.AppendLine("account " + (linkedName ?? "none") + (anyArmed() ? " (ARMED)" : " (not armed)") + " • today " + (double.IsNaN(T("today")) ? "?" : T("today").ToString("0.00", CultureInfo.InvariantCulture)) + " • balance " + (double.IsNaN(T("bal")) ? "?" : T("bal").ToString("0.00", CultureInfo.InvariantCulture))
                        + " • drawdown floor " + (double.IsNaN(T("floor")) || T("floor") == 0 ? "?" : T("floor").ToString("0.00", CultureInfo.InvariantCulture)) + " • max contracts " + realMaxBox.Text.Trim() + " • stop-at day loss $" + realLossBox.Text.Trim() + " (0 = off) • day profit cap $" + realCapBox.Text.Trim() + " (consistency)");
                    var upcoming = sessionNews.Where(e => e.Time >= r.Time.AddMinutes(-30)).Take(4).ToList();
