                    var tb = new TextBlock { Text = label, Foreground = br, FontSize = 10.5, FontWeight = FontWeights.Bold, Tag = tag + ".label" }; Canvas.SetLeft(tb, W + 4); Canvas.SetTop(tb, y - 8); rpCanvas.Children.Add(tb);
                };
