            int reveal = int.MaxValue; List<double[]> ghosts = null; var replayTimer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromMilliseconds(170) };
            // what the chart shows: id -1 = NOW (your chart's last 30 minutes + the next 30 still empty), else a past moment
            int curId = int.MinValue, sel = -1; List<KeystoneArcBar> curBars = null; double curSp = 1;
            Func<string, Brush, double, double, bool, UIElement> tag = (text, br, x, yy, rightAlign) =>
            {
                var b = new Border { Background = Tint(Bg, 230), BorderBrush = br, BorderThickness = new Thickness(1.2), CornerRadius = new CornerRadius(4), Padding = new Thickness(6, 2, 6, 3), Child = new TextBlock { Text = text, Foreground = br, FontSize = 11, FontWeight = FontWeights.Bold } };
                b.Measure(new Size(double.PositiveInfinity, double.PositiveInfinity)); double bw = b.DesiredSize.Width > 0 ? b.DesiredSize.Width : 7 * text.Length;
                System.Windows.Controls.Canvas.SetLeft(b, rightAlign ? x - bw : x); System.Windows.Controls.Canvas.SetTop(b, yy - 10); return b;
            };
            Action<int> show = id =>
            {
                if (id != curId) sel = -1; curId = id;
                cv.Children.Clear(); bool isNow = id == -1;
                DateTime t; DateTime sess; double barrier; List<KeystoneArcBar> bars; int o = 0;
                if (isNow)
                {
                    bars = nowBars ?? new List<KeystoneArcBar>(); t = bars.Count > 0 ? bars[bars.Count - 1].Time : now; sess = t.Date; barrier = mv;
                }
                else
                {
                    t = KeystoneAnalog.TimeOf(idx, id); sess = KeystoneAnalog.SessionOfKey(idx.DayKey[id]); barrier = idx.Barrier[id]; o = idx.Outcome[id];
                    bars = KeystoneStudioStore.Load(StudioFolder(), sym, sess, sess).Where(b => b.Time > t.AddMinutes(-31) && b.Time <= t.AddMinutes(31)).ToList();
                }
                if (bars.Count < 5) { cv.Children.Add(new TextBlock { Text = isNow ? "your chart has fewer than 5 minutes loaded" : "no saved bars for that moment", Foreground = Muted, Margin = new Thickness(20) }); return; }
                int slots = isNow ? bars.Count + 30 : bars.Count;   // NOW: room on the right for the next 30 minutes
                double W = cv.ActualWidth > 100 ? cv.ActualWidth : 700, H = cv.ActualHeight > 100 ? cv.ActualHeight : 600, top = 58, plotH = H - 92, plotW = W - 110;
                var entryBar = bars.LastOrDefault(b => b.Time <= t) ?? bars[0]; double entry = entryBar.Close; int ei = bars.IndexOf(entryBar);
                double hi = Math.Max(bars.Max(b => b.High), entry + barrier), lo = Math.Min(bars.Min(b => b.Low), entry - barrier);
                // the closest moments' next 30 minutes, scaled to today's volatility: the median path and the middle half (25–75 %)
                double[] med = null, q25 = null, q75 = null;
                if (isNow && ghosts != null && ghosts.Count >= 5)
                {
                    med = new double[31]; q25 = new double[31]; q75 = new double[31];
                    for (int k = 0; k <= 30; k++) { var vals = ghosts.Where(g => g.Length > k && !double.IsNaN(g[k])).Select(g => g[k]).OrderBy(v => v).ToList(); if (vals.Count == 0) { med[k] = q25[k] = q75[k] = double.NaN; continue; } med[k] = vals[vals.Count / 2]; q25[k] = vals[vals.Count / 4]; q75[k] = vals[Math.Min(vals.Count - 1, vals.Count * 3 / 4)]; hi = Math.Max(hi, entry + q75[k]); lo = Math.Min(lo, entry + q25[k]); }
                }
                double pad = (hi - lo) * 0.08; hi += pad; lo -= pad;
                Func<double, double> y = p => top + (hi - p) / Math.Max(1e-9, hi - lo) * plotH; double sp = plotW / slots;
                curBars = bars; curSp = sp;
                // future side shading + the "now" line
                double mx = (ei + 1) * sp;
                var shade = new System.Windows.Shapes.Rectangle { Width = Math.Max(0, plotW - mx), Height = plotH, Fill = Tint(Card, 70) }; System.Windows.Controls.Canvas.SetLeft(shade, mx); System.Windows.Controls.Canvas.SetTop(shade, top); cv.Children.Add(shade);
                // target / stop for the side with the edge (both barriers when there is none)
                int s2 = lean ? side : 0;
                foreach (var lv in new[] { Tuple.Create(entry + barrier, s2 >= 0 ? (Brush)Green : Red, s2 > 0 ? "TARGET +" : s2 < 0 ? "STOP +" : "UP +", 1), Tuple.Create(entry - barrier, s2 <= 0 ? (Brush)Red : Green, s2 > 0 ? "STOP −" : s2 < 0 ? "TARGET −" : "DOWN −", -1) })
                {
                    double ly = y(lv.Item1); var br = s2 == 0 ? (lv.Item4 > 0 ? (Brush)Cyan : Orchid) : lv.Item2;
                    cv.Children.Add(new System.Windows.Shapes.Line { X1 = 0, X2 = plotW, Y1 = ly, Y2 = ly, Stroke = br, StrokeThickness = 1.2, StrokeDashArray = new DoubleCollection { 5, 3 } });
                    double pct = lv.Item4 > 0 ? up : dn;
                    cv.Children.Add(tag(lv.Item3 + barrier.ToString("0.##", CultureInfo.InvariantCulture) + " pts (" + Cash(barrier * pv) + ") • first " + pct.ToString("0") + "%", br, plotW + 104, ly, true));
                }
                cv.Children.Add(new System.Windows.Shapes.Line { X1 = 0, X2 = plotW, Y1 = y(entry), Y2 = y(entry), Stroke = Gold, StrokeThickness = 1, StrokeDashArray = new DoubleCollection { 2, 3 } });
                cv.Children.Add(new System.Windows.Shapes.Line { X1 = mx, X2 = mx, Y1 = top, Y2 = top + plotH, Stroke = Gold, StrokeThickness = 1.5 });
                // NOW: where the closest moments went next — faint paths, the middle-half band and the median path in gold
                if (isNow && ghosts != null && med != null)
                {
                    foreach (var g in ghosts)
                    {
                        var pcol = new PointCollection(); for (int k = 0; k <= 30 && k < g.Length; k++) if (!double.IsNaN(g[k])) pcol.Add(new System.Windows.Point((ei + k) * sp + sp / 2, y(entry + g[k])));
                        double fin = g.Reverse().FirstOrDefault(v => !double.IsNaN(v)); if (pcol.Count > 1) cv.Children.Add(new System.Windows.Shapes.Polyline { Points = pcol, Stroke = fin >= 0 ? Green : Red, StrokeThickness = 1, Opacity = 0.22 });
                    }
                    var band = new PointCollection(); for (int k = 0; k <= 30; k++) if (!double.IsNaN(q75[k])) band.Add(new System.Windows.Point((ei + k) * sp + sp / 2, y(entry + q75[k]))); for (int k = 30; k >= 0; k--) if (!double.IsNaN(q25[k])) band.Add(new System.Windows.Point((ei + k) * sp + sp / 2, y(entry + q25[k])));
                    if (band.Count > 2) cv.Children.Add(new System.Windows.Shapes.Polygon { Points = band, Fill = Gold, Opacity = 0.10 });
                    var mp = new PointCollection(); for (int k = 0; k <= 30; k++) if (!double.IsNaN(med[k])) mp.Add(new System.Windows.Point((ei + k) * sp + sp / 2, y(entry + med[k])));
                    if (mp.Count > 1) { cv.Children.Add(new System.Windows.Shapes.Polyline { Points = mp, Stroke = Gold, StrokeThickness = 2.6 }); var lastM = med.Reverse().FirstOrDefault(v => !double.IsNaN(v)); cv.Children.Add(tag("median of " + ghosts.Count + " matches: " + (lastM >= 0 ? "+" : "−") + Math.Abs(lastM).ToString("0.##", CultureInfo.InvariantCulture) + " pts in 30 min (" + (lastM >= 0 ? "+" : "−") + Cash(Math.Abs(lastM) * pv) + " a micro)", Gold, mp[mp.Count - 1].X - 4, mp[mp.Count - 1].Y - 16, true)); }
                    // the usual dip before the move: where an entry made the most sense in those matches
                    int dirM = med[30] >= 0 ? 1 : -1; var dips = ghosts.Where(g => g.Length > 30 && !double.IsNaN(g[30]) && Math.Sign(g[30]) == dirM).Select(g => dirM > 0 ? g.Take(16).Where(v => !double.IsNaN(v)).DefaultIfEmpty(0).Min() : g.Take(16).Where(v => !double.IsNaN(v)).DefaultIfEmpty(0).Max()).OrderBy(v => v).ToList();
                    if (dips.Count >= 3 && Math.Abs(dips[dips.Count / 2]) >= 0.5)
                    {
                        double zdip = dips[dips.Count / 2], zy = y(entry + zdip);
                        var zone = new System.Windows.Shapes.Rectangle { Width = Math.Max(1, 16 * sp), Height = 10, Fill = dirM > 0 ? Green : Red, Opacity = 0.35 }; System.Windows.Controls.Canvas.SetLeft(zone, (ei + 1) * sp); System.Windows.Controls.Canvas.SetTop(zone, zy - 5); cv.Children.Add(zone);
                        cv.Children.Add(tag("better " + (dirM > 0 ? "BUY" : "SELL") + " zone ≈ " + (entry + zdip).ToString("0.00", CultureInfo.InvariantCulture) + " (the usual pullback first in " + dips.Count + " matches)", dirM > 0 ? Green : Red, (ei + 17) * sp, zy, false));
                    }
                }
                // candles
                for (int i = 0; i < bars.Count; i++)
                {
                    if (!isNow && i > ei + reveal) break;   // REPLAY: what came next appears candle by candle
                    var b = bars[i]; double x = i * sp + sp / 2; Brush br = b.Close >= b.Open ? Green : Red;
                    if (i == sel) { var hl = new System.Windows.Shapes.Rectangle { Width = sp, Height = plotH, Fill = Tint(Gold, 40) }; System.Windows.Controls.Canvas.SetLeft(hl, i * sp); System.Windows.Controls.Canvas.SetTop(hl, top); cv.Children.Add(hl); }
                    cv.Children.Add(new System.Windows.Shapes.Line { X1 = x, X2 = x, Y1 = y(b.High), Y2 = y(b.Low), Stroke = br, StrokeThickness = 1 });
                    var body = new System.Windows.Shapes.Rectangle { Width = Math.Max(1, sp * 0.7), Height = Math.Max(1, Math.Abs(y(b.Open) - y(b.Close))), Fill = br }; System.Windows.Controls.Canvas.SetLeft(body, x - sp * 0.35); System.Windows.Controls.Canvas.SetTop(body, Math.Min(y(b.Open), y(b.Close))); cv.Children.Add(body);
                }
                // YOU ARE HERE + where to enter
                double ex = ei * sp + sp / 2, ey = y(entry);
                cv.Children.Add(tag((isNow ? "◀ YOU ARE HERE " : "◀ SAME SHAPE AS NOW ") + entry.ToString("0.00", CultureInfo.InvariantCulture), Gold, ex + 10, ey, false));
                if (lean)
                {
                    var arrow = new TextBlock { Text = side > 0 ? "▲" : "▼", Foreground = side > 0 ? Green : Red, FontSize = 26, FontWeight = FontWeights.Bold };
                    System.Windows.Controls.Canvas.SetLeft(arrow, ex - 10); System.Windows.Controls.Canvas.SetTop(arrow, side > 0 ? y(entryBar.Low) + 4 : y(entryBar.High) - 34); cv.Children.Add(arrow);
                    cv.Children.Add(tag((side > 0 ? "BUY" : "SELL") + " here • " + (side > 0 ? up : dn).ToString("0") + "% hit the target first (normal " + (side > 0 ? baseUp : 100 - baseUp).ToString("0") + "%)", side > 0 ? Green : Red, Math.Max(4, ex - 160), side > 0 ? y(entryBar.Low) + 50 : y(entryBar.High) - 50, false));
                }
                else cv.Children.Add(tag("NO ENTRY: buy " + up.ToString("0") + "% vs sell " + dn.ToString("0") + "% is a coin flip — wait", Gold, Math.Max(4, ex - 160), Math.Min(top + plotH - 12, ey + 40), false));
                // a past moment: where the move was decided
                if (!isNow)
                {
                    for (int i = ei + 1; i < bars.Count && bars[i].Time <= t.AddMinutes(30) && i <= ei + reveal; i++)
                    {
                        bool hu = bars[i].High >= entry + barrier, hd = bars[i].Low <= entry - barrier; if (!hu && !hd) continue;
                        bool upHit = hu && (!hd || o > 0); double hx = i * sp + sp / 2, hy = upHit ? y(entry + barrier) : y(entry - barrier);
                        var ring = new System.Windows.Shapes.Ellipse { Width = 12, Height = 12, Stroke = upHit ? Cyan : Orchid, StrokeThickness = 2.5 }; System.Windows.Controls.Canvas.SetLeft(ring, hx - 6); System.Windows.Controls.Canvas.SetTop(ring, hy - 6); cv.Children.Add(ring);
                        cv.Children.Add(tag((upHit ? "▲ up side hit " : "▼ down side hit ") + bars[i].Time.ToString("HH:mm") + " (" + (int)(bars[i].Time - t).TotalMinutes + " min)", upHit ? Cyan : Orchid, hx + 8, hy + (upHit ? -16 : 16), false));
                        break;
                    }
                }
                var title = new TextBlock { Text = isNow ? "NOW • " + sym + " " + t.ToString("ddd yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture) + " • your last 30 minutes; shaded right = the next 30 the matches vote on" : sess.ToString("ddd yyyy-MM-dd", CultureInfo.InvariantCulture) + " " + t.ToString("HH:mm") + " • " + (o > 0 ? "▲ went up first" : o < 0 ? "▼ went down first" : "• neither in 30 min") + " • left of the gold line = the matched 30 minutes, shaded = what came next", Foreground = Gold, FontSize = 12, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap, Width = W - 20 };
                System.Windows.Controls.Canvas.SetLeft(title, 6); System.Windows.Controls.Canvas.SetTop(title, 6); cv.Children.Add(title);
                var odds = new TextBlock { Text = "ALL " + ans.Neighbors + " MATCHES: BUY wins " + up.ToString("0") + "% • SELL wins " + dn.ToString("0") + "% • normal at this hour " + baseUp.ToString("0") + "/" + (100 - baseUp).ToString("0") + " • click any candle for its details", Foreground = Muted, FontSize = 11 };
                System.Windows.Controls.Canvas.SetLeft(odds, 6); System.Windows.Controls.Canvas.SetTop(odds, 36); cv.Children.Add(odds);
                // the clicked candle's details
                if (sel >= 0 && sel < bars.Count)
                {
                    var b = bars[sel]; double mvp = b.Close - entry; int mins = (int)Math.Round((b.Time - t).TotalMinutes);
                    var info = new Border { Background = Tint(Bg, 240), BorderBrush = Gold, BorderThickness = new Thickness(1.5), CornerRadius = new CornerRadius(6), Padding = new Thickness(10, 6, 10, 8) };
                    var ist = new StackPanel(); info.Child = ist;
                    ist.Children.Add(new TextBlock { Text = b.Time.ToString("ddd yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture) + (mins == 0 ? "  • the matched minute" : mins < 0 ? "  • " + (-mins) + " min before" : "  • " + mins + " min after"), Foreground = Gold, FontSize = 12, FontWeight = FontWeights.Bold });
                    ist.Children.Add(new TextBlock { Text = (b.Close >= b.Open ? "▲ UP candle " : "▼ DOWN candle ") + Math.Abs(b.Close - b.Open).ToString("0.00", CultureInfo.InvariantCulture) + " pts • range " + (b.High - b.Low).ToString("0.00", CultureInfo.InvariantCulture) + " pts", Foreground = b.Close >= b.Open ? Green : Red, FontSize = 12, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 2, 0, 2) });
                    ist.Children.Add(new TextBlock { Text = "O " + b.Open.ToString("0.00", CultureInfo.InvariantCulture) + "   H " + b.High.ToString("0.00", CultureInfo.InvariantCulture) + "   L " + b.Low.ToString("0.00", CultureInfo.InvariantCulture) + "   C " + b.Close.ToString("0.00", CultureInfo.InvariantCulture), Foreground = Text, FontSize = 11.5, FontFamily = new FontFamily("Consolas") });
                    if (mins > 0) ist.Children.Add(new TextBlock { Text = "vs the gold line: " + (mvp >= 0 ? "+" : "−") + Math.Abs(mvp).ToString("0.00", CultureInfo.InvariantCulture) + " pts = a BUY there " + (mvp >= 0 ? "+" : "−") + Cash(Math.Abs(mvp * pv)) + " / a SELL " + (mvp >= 0 ? "−" : "+") + Cash(Math.Abs(mvp * pv)) + " a micro", Foreground = mvp >= 0 ? Green : Red, FontSize = 11.5, Margin = new Thickness(0, 2, 0, 0) });
                    System.Windows.Controls.Canvas.SetLeft(info, Math.Min(plotW - 330, Math.Max(4, sel * sp + sp + 8))); System.Windows.Controls.Canvas.SetTop(info, top + 6); cv.Children.Add(info);
                }
            };
            cv.MouseLeftButtonUp += (s0, e0) =>
            {
                if (curBars == null) return; var p = e0.GetPosition(cv); int i = (int)Math.Floor(p.X / Math.Max(1e-9, curSp));
                sel = i >= 0 && i < curBars.Count && sel != i ? i : -1; show(curId);
            };
            var rows = new List<Border>();
            Action<Border, int> addRow = (row, id) => { row.MouseLeftButtonUp += delegate { foreach (var r2 in rows) r2.BorderBrush = System.Windows.Media.Brushes.Transparent; row.BorderBrush = Gold; show(id); }; row.BorderThickness = new Thickness(1.5); row.BorderBrush = System.Windows.Media.Brushes.Transparent; rows.Add(row); list.Children.Add(row); };
            if (nowBars != null && nowBars.Count >= 5)
                addRow(new Border { Background = Tint(Gold, 40), CornerRadius = new CornerRadius(4), Margin = new Thickness(0, 0, 0, 5), Padding = new Thickness(8, 5, 8, 5), Cursor = System.Windows.Input.Cursors.Hand,
                    Child = new TextBlock { Text = "★  NOW • your chart " + nowBars[nowBars.Count - 1].Time.ToString("HH:mm") + " • where to enter", Foreground = Gold, FontFamily = new FontFamily("Consolas"), FontSize = 12, FontWeight = FontWeights.Bold } }, -1);
            for (int n = 0; n < Math.Min(20, ans.Ids.Count); n++)
            {
                int id = ans.Ids[n]; var t = KeystoneAnalog.TimeOf(idx, id); int o = idx.Outcome[id];
                addRow(new Border { Background = Card, CornerRadius = new CornerRadius(4), Margin = new Thickness(0, 0, 0, 3), Padding = new Thickness(8, 4, 8, 4), Cursor = System.Windows.Input.Cursors.Hand,
                    Child = new TextBlock { Text = (n + 1).ToString().PadLeft(2) + ".  " + KeystoneAnalog.SessionOfKey(idx.DayKey[id]).ToString("ddd yyyy-MM-dd", CultureInfo.InvariantCulture) + "  " + t.ToString("HH:mm") + "   " + (o > 0 ? "▲ up first" : o < 0 ? "▼ down first" : "• neither") + "   closeness " + ans.Dist[n].ToString("0.00", CultureInfo.InvariantCulture), Foreground = o > 0 ? Cyan : o < 0 ? Orchid : Muted, FontFamily = new FontFamily("Consolas"), FontSize = 12 } }, id);
            }
            int firstId = nowBars != null && nowBars.Count >= 5 ? -1 : ans.Ids.Count > 0 ? ans.Ids[0] : int.MinValue;
            if (firstId != int.MinValue) { if (rows.Count > 0) rows[0].BorderBrush = Gold; cv.SizeChanged += delegate { show(curId == int.MinValue ? firstId : curId); }; show(firstId); }
            replayTimer.Tick += delegate { if (curId == -1 || curId == int.MinValue) { replayTimer.Stop(); return; } reveal++; show(curId); if (reveal > 32) { replayTimer.Stop(); reveal = int.MaxValue; replayBtn.Content = "▶ REPLAY THIS MATCH"; } };
            replayBtn.Click += delegate
            {
                if (curId == -1 || curId == int.MinValue) { ghostNote.Text = "pick one of the past moments on the left, then REPLAY"; return; }
                if (replayTimer.IsEnabled) { replayTimer.Stop(); reveal = int.MaxValue; replayBtn.Content = "▶ REPLAY THIS MATCH"; show(curId); return; }
                reveal = 0; replayBtn.Content = "■ STOP"; show(curId); replayTimer.Start();
            };
            w.Closed += delegate { replayTimer.Stop(); };
            // the 20 closest moments' next 30 minutes (per minute, in points from their matched minute, scaled to today's move size) — background
            {
                double scaleTo = mv; var disp = w.Dispatcher;
                System.Threading.ThreadPool.QueueUserWorkItem(delegate
                {
                    var g = MatchPaths(sym, idx, ans, scaleTo);
                    disp.BeginInvoke(new Action(() =>
                    {
                        ghosts = g; int upN = g.Count(a => a.Length > 30 && a[30] > 0), dnN = g.Count(a => a.Length > 30 && a[30] < 0);
                        ghostNote.Text = g.Count == 0 ? "no saved bars for the matches" : "HOW TO READ IT: the thin lines are what the " + g.Count + " most similar past moments did in the next 30 minutes (" + upN + " went up, " + dnN + " down). The thick gold line is the typical path; the shaded band is where most of them stayed. If most lines go one way, that side has the edge; if they spread both ways, wait. Also drawn on your chart (click its ✕ to remove).";
                        if (curId == -1) show(-1);
                        if (onGhosts != null && g.Count > 0) onGhosts(g);
                    }));
                });
            }
            AskBeforeClosing(w, "MATCHES", null);
            w.Show(); return w;
        }

        // ---- PATTERN MEMORY: the similar-moments index per instrument, built from the studio's saved days (background) ------------
        private readonly Dictionary<string, KeystoneAnalogIndex> analogIndexes = new Dictionary<string, KeystoneAnalogIndex>();
        private readonly HashSet<string> analogBuilding = new HashSet<string>(); private readonly Dictionary<string, string> analogVerdicts = new Dictionary<string, string>();
        private readonly Dictionary<string, int> analogBuiltFrom = new Dictionary<string, int>(); private readonly Dictionary<string, DateTime> analogLastTry = new Dictionary<string, DateTime>();
        private void EnsureAnalogIndex(string sym, Dispatcher disp, Action done)
        {
            var sessions = KeystoneStudioStore.Sessions(StudioFolder(), sym).Where(kv => kv.Value >= 60).Select(kv => kv.Key).OrderBy(d => d).ToList();
            int have; if (sessions.Count < 60 || analogBuilding.Contains(sym) || (analogIndexes.ContainsKey(sym) && analogBuiltFrom.TryGetValue(sym, out have) && have == sessions.Count)) { if (done != null && analogIndexes.ContainsKey(sym)) done(); return; }
            analogBuilding.Add(sym); string folder = StudioFolder();
            System.Threading.ThreadPool.QueueUserWorkItem(delegate
            {
                var idx = new KeystoneAnalogIndex { Symbol = sym };
                try
                {
                    foreach (var month in sessions.GroupBy(d => new DateTime(d.Year, d.Month, 1)).OrderBy(g => g.Key))
                    {
                        var bars = KeystoneStudioStore.Load(folder, sym, month.First(), month.Last());
                        foreach (var g in bars.GroupBy(b => KeystoneStudioStore.SessionOf(b.Time)).OrderBy(g => g.Key)) KeystoneAnalog.AddSession(idx, g.ToList(), g.Key);
                    }
                }
                catch { }
                Action apply = delegate { analogBuilding.Remove(sym); analogIndexes[sym] = idx; analogBuiltFrom[sym] = sessions.Count; if (done != null) done(); };
                if (disp != null) disp.BeginInvoke(apply); else apply();
            });
        }

        // ---- PATTERN LAB: the honest test — does "similar moments" predict the next 30 minutes better than the baseline? -------------
        private Window patternLabWindow; private Action<string> patternLabRun;
        private void OpenPatternLab()
        {
            if (patternLabWindow != null) { patternLabWindow.Activate(); return; }
            var w = new KeystoneWindow { Title = "SPASIX FUTURE • PATTERN LAB", Width = 1100, Height = 860, MinWidth = 720, MinHeight = 480, Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterScreen, ShowInTaskbar = true };
            patternLabWindow = w;
            var stack = new StackPanel { Margin = new Thickness(16) };
            stack.Children.Add(Txt("PATTERN LAB • SIMILAR MOMENTS", Orchid, 22, FontWeights.Bold));
            stack.Children.Add(new TextBlock { Text = "Every saved minute (every 2 minutes) becomes a fingerprint: the last 30 minutes' path, the last six 5-minute moves, where price sits in the day's range, the move since the open, how busy the market is — scaled by the recent 1-minute range (ATR). The outcome is what came next in 30 minutes: +3 ATR first, −3 ATR first, or neither.\nWALK FORWARD: each test moment is judged ONLY from the days before it, among moments at a similar time of day (±30 min). A call = the closest moments' up-first share at or above the threshold (buy) or at or below 1 − threshold (sell). The BASELINE is what you would get by always taking that side at that time of day. Only beating the baseline means anything.", Foreground = Muted, FontSize = 11.5, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 4, 0, 10) });
            Action<string, UIElement, System.Windows.Controls.Panel> add = (l, e, p) => { var sp = new StackPanel { Margin = new Thickness(0, 0, 10, 0) }; sp.Children.Add(new TextBlock { Text = l, Foreground = Muted, FontSize = 9.5, FontWeight = FontWeights.Bold }); sp.Children.Add(e); p.Children.Add(sp); };
            var form = new WrapPanel();
            var symBox = Select("MNQ", "MGC"); symBox.SelectedIndex = 0; symBox.Width = 90;
            var hoursBox = Select("NEW YORK 09:30–16:00", "ALL 24 HOURS"); hoursBox.SelectedIndex = 0; hoursBox.Width = 190;
            var everyBox = Input("15"); everyBox.Width = 50; var thrBox = Input("0.60"); thrBox.Width = 60; var kBox = Input("100"); kBox.Width = 60; var minDaysBox = Input("60"); minDaysBox.Width = 60;
            var run = Btn("RUN THE TEST", Green); run.Height = 32; run.Margin = new Thickness(0, 12, 0, 0); run.Padding = new Thickness(18, 0, 18, 0);
            add("INSTRUMENT", symBox, form); add("HOURS", hoursBox, form); add("A TEST EVERY … MIN", everyBox, form); add("CALL AT ≥ (0.5–0.9)", thrBox, form); add("CLOSEST MOMENTS (K)", kBox, form); add("FIRST TEST AFTER … DAYS", minDaysBox, form); form.Children.Add(run);
            stack.Children.Add(form);
            var status = new TextBlock { Text = "Needs at least 100 saved days (LOAD ALL 6 YEARS gives ~1,500). The test runs in the background; it can take a few minutes.", Foreground = Cyan, FontSize = 12.5, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 10, 0, 6) };
            stack.Children.Add(status);
            var results = new StackPanel(); stack.Children.Add(results);
            w.Content = new ScrollViewer { Content = stack, VerticalScrollBarVisibility = ScrollBarVisibility.Auto };
            bool running = false;
            Action<KeystoneAnalogReport, string> show = (rep, sym) =>
            {
                results.Children.Clear();
                bool good = rep.Verdict.StartsWith("PROMISING");
                results.Children.Add(new Border { Background = Card, BorderBrush = good ? Green : Gold, BorderThickness = new Thickness(2), CornerRadius = new CornerRadius(6), Padding = new Thickness(12), Margin = new Thickness(0, 4, 0, 10), Child = new TextBlock { Text = sym + " • " + rep.Verdict, Foreground = good ? Green : Gold, FontSize = 16, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap } });
                results.Children.Add(new TextBlock { Text = rep.TrainSamples.ToString("N0", CultureInfo.InvariantCulture) + " moments in memory • " + rep.Queries.ToString("N0", CultureInfo.InvariantCulture) + " tested • " + rep.Calls.ToString("N0", CultureInfo.InvariantCulture) + " calls • right " + (100 * rep.Hit).ToString("0.0") + "% (baseline " + (100 * rep.BaseHit).ToString("0.0") + "%) • " + (rep.Calls == 0 ? 0 : rep.R / rep.Calls).ToString("+0.00;-0.00") + "R a call before costs (1R = the 3-ATR barrier)", Foreground = Text, FontSize = 13, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 10) });
                results.Children.Add(Txt("EACH YEAR (judged only from the years before)", Gold, 13, FontWeights.Bold));
                var yg = new Grid { Margin = new Thickness(0, 4, 0, 12) }; foreach (var wd in new[] { 70.0, 90, 110, 110, 110, 120 }) yg.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(wd) });
                int row = 0; Action<string[], Brush> yrow = (cells, br) => { yg.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); for (int c = 0; c < cells.Length; c++) { var tb = new TextBlock { Text = cells[c], Foreground = br, FontSize = 12, Margin = new Thickness(0, 2, 8, 2), FontWeight = row == 0 ? FontWeights.Bold : FontWeights.Normal }; Grid.SetRow(tb, row); Grid.SetColumn(tb, c); yg.Children.Add(tb); } row++; };
                yrow(new[] { "YEAR", "CALLS", "RIGHT", "BASELINE", "EDGE", "R A CALL" }, Muted);
                foreach (var y in rep.Years) yrow(new[] { y.Year.ToString(), y.Calls.ToString("N0"), (100 * y.Hit).ToString("0.0") + "%", (100 * y.BaseHit).ToString("0.0") + "%", (100 * (y.Hit - y.BaseHit)).ToString("+0.0;-0.0") + " pts", (y.Calls == 0 ? 0 : y.R / y.Calls).ToString("+0.00;-0.00") }, y.Hit > y.BaseHit && y.R > 0 ? Green : Red);
                results.Children.Add(yg);
                results.Children.Add(Txt("CALIBRATION • when the closest moments said X% up-first, how often was it up-first? (a good model: the two columns match)", Gold, 13, FontWeights.Bold));
                var cg = new StackPanel { Margin = new Thickness(0, 4, 0, 0) };
                for (int b = 0; b < 10; b++) if (rep.CalCount[b] >= 30) cg.Children.Add(new TextBlock { Text = "said " + (b * 10) + "–" + (b * 10 + 10) + "% (avg " + (100 * rep.CalPredicted[b]).ToString("0") + "%) → happened " + (100 * rep.CalRealized[b]).ToString("0") + "%   (" + rep.CalCount[b].ToString("N0") + " moments)", Foreground = Math.Abs(rep.CalPredicted[b] - rep.CalRealized[b]) <= 0.05 ? Green : Text, FontSize = 12, FontFamily = new FontFamily("Consolas") });
                results.Children.Add(cg);
                results.Children.Add(new TextBlock { Text = "\nHow to read it: an edge of +2 to +5 points over the baseline that holds in most years is already valuable for many small trades; a model that is right 70% when the baseline is also 70% has no edge. Costs (commission + 1 tick) are not in the R yet.", Foreground = Muted, FontSize = 11, TextWrapping = TextWrapping.Wrap });
            };
            patternLabRun = sym =>
            {
                if (running) return; running = true; run.IsEnabled = false;
                int every = Math.Max(2, Integer(everyBox, 15)), k = Math.Max(20, Integer(kBox, 100)), minDays = Math.Max(20, Integer(minDaysBox, 60)); double thr = Math.Max(0.5, Math.Min(0.95, NumberAllowZero(thrBox, 0.6)));
                bool ny = hoursBox.SelectedIndex == 0; var disp = w.Dispatcher;
                status.Text = "BUILDING THE PATTERN MEMORY FROM YOUR SAVED " + sym + " DAYS…"; status.Foreground = Cyan;
                EnsureAnalogIndex(sym, disp, delegate
                {
                    KeystoneAnalogIndex idx; if (!analogIndexes.TryGetValue(sym, out idx) || idx.Sessions < 100) { running = false; run.IsEnabled = true; status.Text = "NOT ENOUGH DATA • " + (idx == null ? 0 : idx.Sessions) + " saved days of " + sym + " (needs 100+) • LOAD ALL 6 YEARS first"; status.Foreground = Red; return; }
                    status.Text = "TESTING " + idx.Count.ToString("N0", CultureInfo.InvariantCulture) + " moments from " + idx.Sessions + " days… (background)";
                    System.Threading.ThreadPool.QueueUserWorkItem(delegate
                    {
                        KeystoneAnalogReport rep = null; string err = null;
                        try { rep = KeystoneAnalog.WalkForward(idx, every, thr, k, 30, minDays, ny ? 930 : 0, ny ? 1320 : 1440, (d, t) => { if (disp != null) disp.BeginInvoke(new Action(delegate { status.Text = "TESTING… " + (t == 0 ? 0 : 100 * d / t) + "%"; })); }); }
                        catch (Exception ex) { err = ex.Message; }
                        Action fin = delegate
                        {
                            running = false; run.IsEnabled = true;
                            if (err != null) { status.Text = "TEST FAILED • " + err; status.Foreground = Red; return; }
                            status.Text = "DONE • " + sym + " • " + DateTime.Now.ToString("HH:mm"); status.Foreground = Green;
                            analogVerdicts[sym] = rep.Verdict.StartsWith("PROMISING") ? "PROMISING (" + (100 * (rep.Hit - rep.BaseHit)).ToString("+0.0") + " pts over baseline)" : rep.Verdict.StartsWith("NO RELIABLE") ? "NO RELIABLE EDGE on your history — treat the box as information only" : "not enough calls to judge";
                            show(rep, sym);
                            try
                            {
                                string dir = Path.Combine(DataStoreDirectory(), "PatternLab"); Directory.CreateDirectory(dir);
                                string f = Path.Combine(dir, "patternlab_" + sym + "_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".csv");
                                var lines = new List<string> { "# " + sym + " • " + rep.Verdict.Replace(",", " "), "# settings: every " + every + " min • call at " + thr.ToString(CultureInfo.InvariantCulture) + " • K " + k + " • first test after " + minDays + " days • " + (ny ? "NY 09:30-16:00" : "24h") + " • " + rep.TrainSamples + " moments", "year,calls,right_pct,baseline_pct,edge_pts,r_per_call" };
                                lines.AddRange(rep.Years.Select(y => string.Join(",", y.Year, y.Calls, (100 * y.Hit).ToString("0.0", CultureInfo.InvariantCulture), (100 * y.BaseHit).ToString("0.0", CultureInfo.InvariantCulture), (100 * (y.Hit - y.BaseHit)).ToString("0.0", CultureInfo.InvariantCulture), (y.Calls == 0 ? 0 : y.R / y.Calls).ToString("0.000", CultureInfo.InvariantCulture))));
                                lines.Add("ALL," + rep.Calls + "," + (100 * rep.Hit).ToString("0.0", CultureInfo.InvariantCulture) + "," + (100 * rep.BaseHit).ToString("0.0", CultureInfo.InvariantCulture) + "," + (100 * (rep.Hit - rep.BaseHit)).ToString("0.0", CultureInfo.InvariantCulture) + "," + (rep.Calls == 0 ? 0 : rep.R / rep.Calls).ToString("0.000", CultureInfo.InvariantCulture));
                                lines.Add(""); lines.Add("said_from_pct,said_avg_pct,happened_pct,moments");
                                for (int b = 0; b < 10; b++) if (rep.CalCount[b] > 0) lines.Add((b * 10) + "," + (100 * rep.CalPredicted[b]).ToString("0.0", CultureInfo.InvariantCulture) + "," + (100 * rep.CalRealized[b]).ToString("0.0", CultureInfo.InvariantCulture) + "," + rep.CalCount[b]);
                                File.WriteAllLines(f, lines.ToArray()); status.Text += " • saved " + f;
                            }
                            catch { }
                        };
                        if (disp != null) disp.BeginInvoke(fin); else fin();
                    });
                });
                if (!analogBuilding.Contains(sym) && !analogIndexes.ContainsKey(sym)) { running = false; run.IsEnabled = true; status.Text = "NOT ENOUGH DATA • needs 100+ saved days of " + sym + " • LOAD ALL 6 YEARS first"; status.Foreground = Red; }
            };
            run.Click += delegate { patternLabRun(Convert.ToString(symBox.Items[Math.Max(0, symBox.SelectedIndex)])); };
            AskBeforeClosing(w, "PATTERN LAB", () => "Close the PATTERN LAB?" + (running ? " The running test stops showing here." : ""));
            w.Closed += delegate { patternLabWindow = null; patternLabRun = null; };
            w.Show();
        }

        // ---- PICK A DAY: every weekday of the last 6 years with ONLY its news (no ranges or moves — nothing to bias the trade) ----
        // ● saved on this PC (loads at once) • ○ not saved yet (LOAD DAY gets it from NinjaTrader). RANDOM DAY = blind practice.
        private Window dayPickerWindow; private Action<string> dayPickerFilter;
        private void OpenDayPicker(Action<DateTime> load)
        {
            if (dayPickerWindow != null) { dayPickerWindow.Activate(); return; }
            var w = new KeystoneWindow { Title = "SPASIX FUTURE • PICK A DAY", Width = 760, Height = 860, MinWidth = 560, MinHeight = 420, Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterScreen, ShowInTaskbar = true };
            dayPickerWindow = w;
            string folder = StudioFolder(); var news = LoadStudioNews(); var rnd = new Random();
            SortedDictionary<DateTime, int> mnq = null, mgc = null; List<DateTime> days = null; HashSet<DateTime> askedWeeks = new HashSet<DateTime>();
            Action readStore = delegate
            {
                mnq = KeystoneStudioStore.Sessions(folder, "MNQ"); mgc = KeystoneStudioStore.Sessions(folder, "MGC"); days = new List<DateTime>();
                try { askedWeeks = new HashSet<DateTime>(KeystoneStudioStore.Requested(folder, "MNQ")); } catch { askedWeeks = new HashSet<DateTime>(); }
                for (var d = LastClosedSession(); d >= SixYearsBack(); d = d.AddDays(-1)) if (d.DayOfWeek != DayOfWeek.Saturday && d.DayOfWeek != DayOfWeek.Sunday) days.Add(d);
            };
            readStore();
            Func<DateTime, bool> saved = d => { int a, g; return (mnq.TryGetValue(d, out a) && a >= 60) || (mgc.TryGetValue(d, out g) && g >= 60); };
            // its week was fetched from NinjaTrader and the day came back empty: the market was closed (a holiday), nothing to load
            Func<DateTime, bool> closed = d => !saved(d) && d < DateTime.Today.AddDays(-21) && askedWeeks.Contains(KeystoneStudioStore.WeekKey(d));
            var root = new Grid { Margin = new Thickness(12) };
            for (int k = 0; k < 3; k++) root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            var head = new StackPanel(); head.Children.Add(Txt("PICK A DAY", Gold, 20, FontWeights.Bold));
            var info = new TextBlock { Text = "", Foreground = Muted, FontSize = 11, TextWrapping = TextWrapping.Wrap }; head.Children.Add(info);
            var loadRow = new WrapPanel { Margin = new Thickness(0, 6, 0, 0) };
            var allBtn = Btn("LOAD ALL 6 YEARS", Green); allBtn.Height = 30; allBtn.Margin = new Thickness(0, 0, 8, 0); allBtn.Padding = new Thickness(14, 0, 14, 0);
            var stopBtn = Btn("STOP", Card); stopBtn.Height = 30; stopBtn.Margin = new Thickness(0, 0, 8, 0);
            var randomBtn = Btn("🎲 RANDOM DAY", Orchid); randomBtn.Height = 30; randomBtn.Padding = new Thickness(14, 0, 14, 0); randomBtn.ToolTip = "A random saved day from the list as filtered — practise without knowing what comes.";
            var dlText = new TextBlock { Text = "", Foreground = Cyan, FontSize = 11.5, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 4, 0, 0) };
            var blsBtn = Btn("GET CPI / PPI / NFP HISTORY", Card); blsBtn.Height = 30; blsBtn.Margin = new Thickness(8, 0, 0, 0); blsBtn.Padding = new Thickness(12, 0, 12, 0); blsBtn.ToolTip = "Reads every past CPI, PPI and payrolls release day from the BLS archive pages (bls.gov) into News.csv.";
            var updBtn = Btn("⟳ UPDATE TO TODAY", Cyan); updBtn.Height = 30; updBtn.Margin = new Thickness(0, 0, 8, 0); updBtn.Padding = new Thickness(14, 0, 14, 0); updBtn.ToolTip = "Gets every recent day that is not saved yet (the last 3 weeks of MNQ + MGC) — it also runs by itself when this window opens.";
            loadRow.Children.Add(updBtn); loadRow.Children.Add(allBtn); loadRow.Children.Add(stopBtn); loadRow.Children.Add(randomBtn); loadRow.Children.Add(blsBtn); head.Children.Add(loadRow); head.Children.Add(dlText);
            // practise a range: every weekday from → to, one after the other, then a report
            var rangeRow = new WrapPanel { Margin = new Thickness(0, 8, 0, 0) };
            rangeRow.Children.Add(new TextBlock { Text = "PRACTISE A RANGE:", Foreground = Gold, FontSize = 12, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 6, 8, 0) });
            var rFrom = Input(DateTime.Today.AddDays(-14).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)); rFrom.Width = 96; var rTo = Input(DateTime.Today.AddDays(-1).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)); rTo.Width = 96;
            rangeRow.Children.Add(rFrom); rangeRow.Children.Add(new TextBlock { Text = " → ", Foreground = Muted, Margin = new Thickness(2, 6, 2, 0) }); rangeRow.Children.Add(rTo);
            Func<string, Button> rb = t => { var b = Btn(t, Card); b.Height = 26; b.FontSize = 11; b.Margin = new Thickness(6, 0, 0, 0); b.Padding = new Thickness(8, 0, 8, 0); rangeRow.Children.Add(b); return b; };
            var r2w = rb("LAST 2 WEEKS"); var r1m = rb("LAST MONTH"); var rRnd = rb("🎲 RANDOM 2 WEEKS"); var rGo = rb("START RANGE ▶"); rGo.Background = Green;
            head.Children.Add(rangeRow);
            Grid.SetRow(head, 0); root.Children.Add(head);
            var bar = new WrapPanel { Margin = new Thickness(0, 8, 0, 6) }; string filter = "ALL"; string year = "ALL"; bool savedOnly = false;
            var list = new StackPanel(); var scroll = new ScrollViewer { Content = list, VerticalScrollBarVisibility = ScrollBarVisibility.Auto };
            var filterButtons = new List<Button>(); Action fill = null; var shownDays = new List<DateTime>();
            foreach (var f in new[] { "ALL", "ANY NEWS", "FOMC", "NFP", "CPI", "PPI", "NO NEWS" })
            {
                var ff = f; var b = Btn(f, f == "ALL" ? Gold : Card); b.Height = 26; b.FontSize = 11; b.Margin = new Thickness(0, 0, 4, 4); b.Padding = new Thickness(10, 0, 10, 0);
                b.Click += delegate { filter = ff; foreach (var x in filterButtons) x.Background = Convert.ToString(x.Content) == ff ? Gold : Card; fill(); }; filterButtons.Add(b); bar.Children.Add(b);
            }
            var yearBox = Select(new[] { "ALL YEARS" }.Concat(days.Select(d => d.Year.ToString(CultureInfo.InvariantCulture)).Distinct()).ToArray()); yearBox.SelectedIndex = 0; yearBox.Width = 110; yearBox.Margin = new Thickness(8, 0, 6, 4);
            yearBox.SelectionChanged += delegate { year = yearBox.SelectedIndex <= 0 ? "ALL" : Convert.ToString(yearBox.Items[yearBox.SelectedIndex]); fill(); };
            var savedBox = new CheckBox { Content = "SAVED ONLY", IsChecked = false, Foreground = Text, Margin = new Thickness(4, 4, 0, 0) };
            savedBox.Checked += delegate { savedOnly = true; fill(); }; savedBox.Unchecked += delegate { savedOnly = false; fill(); };
            bar.Children.Add(yearBox); bar.Children.Add(savedBox);
            Grid.SetRow(bar, 1); root.Children.Add(bar);
            Grid.SetRow(scroll, 3); root.Children.Add(scroll);
            w.Content = root;
            fill = delegate
            {
                list.Children.Clear(); shownDays.Clear(); int nSaved = days.Count(saved), nClosed = days.Count(closed);
                foreach (var d in days)
                {
                    if (year != "ALL" && d.Year.ToString(CultureInfo.InvariantCulture) != year) continue;
                    bool isSaved = saved(d); if (savedOnly && !isSaved) continue;
                    var ev = KeystoneNews.ForSession(news, d, true); var tags = KeystoneNews.Tags(ev);
                    bool ok = filter == "ALL" || (filter == "ANY NEWS" && tags.Count > 0) || (filter == "NO NEWS" && tags.Count == 0) || tags.Contains(filter);
                    if (!ok) continue; shownDays.Add(d);
                    var row = new Grid { Margin = new Thickness(0, 0, 0, 2), Background = Card, Cursor = System.Windows.Input.Cursors.Hand };
                    row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(26) }); row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(150) }); row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                    Action<int, string, Brush, bool> cell = (c, t, b, bold) => { var tb = new TextBlock { Text = t, Foreground = b, FontSize = 12.5, FontWeight = bold ? FontWeights.Bold : FontWeights.Normal, Margin = new Thickness(8, 5, 4, 5), TextWrapping = TextWrapping.Wrap }; Grid.SetColumn(tb, c); row.Children.Add(tb); };
                    bool isClosed = !isSaved && closed(d);
                    cell(0, isSaved ? "●" : isClosed ? "–" : "○", isSaved ? Green : Muted, true);
                    cell(1, d.ToString("ddd yyyy-MM-dd", CultureInfo.InvariantCulture), isSaved ? Text : Muted, true);
                    if (isClosed) { cell(2, "market closed (holiday) • no session", Muted, false); var dd0 = d; row.ToolTip = "No session that day (fetched from NinjaTrader: empty)"; list.Children.Add(row); continue; }
                    cell(2, tags.Count == 0 ? "no high-impact news" : string.Join(" • ", ev.Select(e => e.Time.ToString("HH:mm") + " " + KeystoneNews.Tag(e)).Distinct()), tags.Count == 0 ? Muted : tags.Contains("FOMC") || tags.Contains("NFP") || tags.Contains("CPI") ? Orange : Gold, false);
                    row.ToolTip = isSaved ? "Saved • click to load" : "Not saved yet • click: LOAD DAY gets this week from NinjaTrader and saves it";
                    var dd = d; row.MouseLeftButtonUp += delegate { load(dd); CloseToolQuietly(w); };
                    list.Children.Add(row);
                }
                info.Text = days.Count + " weekdays in the last 6 years (to " + (days.Count > 0 ? days[0].ToString("ddd yyyy-MM-dd", CultureInfo.InvariantCulture) : "-") + ", the last finished session) • " + nSaved + " saved (●) • " + (nClosed > 0 ? nClosed + " market holidays (–) • " : "") + (days.Count - nSaved - nClosed > 0 ? (days.Count - nSaved - nClosed) + " missing (○: ⟳ UPDATE / LOAD ALL) • " : "all saved • ") + shownDays.Count + " shown • news: FOMC + payrolls built in; CPI / PPI from the ForexFactory feed and your News.csv (DATA LIBRARY → OPEN NEWS FILE) • click a day to load it";
            };
            dayPickerFilter = f => { filter = f; fill(); };
            fill();
            Action showDl = delegate
            {
                dlText.Text = StudioDownloadStatus(); allBtn.IsEnabled = !dlBusy; stopBtn.IsEnabled = dlBusy;
                if (!dlBusy || dlDone % 8 == 0) { readStore(); fill(); }
            };
            dlChanged += showDl; showDl();
            allBtn.Click += delegate { dlText.Text = StartSixYears(w.Dispatcher); };
            updBtn.Click += delegate { dlText.Text = StartUpdateToToday(w.Dispatcher); };
            // up to date by itself: the recent days that are missing are fetched as the window opens
            if (!dlBusy && days.Take(15).Any(d => !saved(d))) dlText.Text = StartUpdateToToday(w.Dispatcher);
            Action getBls = delegate
            {
                var disp = w.Dispatcher; dlText.Text = "READING CPI / PPI / PAYROLLS HISTORY FROM BLS…";
                System.Threading.ThreadPool.QueueUserWorkItem(delegate
                {
                    string msg; try { msg = FetchBlsNewsHistory(true); } catch (Exception ex) { msg = "BLS HISTORY FAILED • " + ex.Message; }
                    if (disp != null) disp.BeginInvoke(new Action(delegate
                    {
                        dlText.Text = msg; news = LoadStudioNews(); fill();
                        if (msg.Contains("MISSING"))
                        {
                            try { Directory.CreateDirectory(BlsSavedFolder()); System.Diagnostics.Process.Start(BlsSavedFolder()); foreach (var u in BlsArchivePages) System.Diagnostics.Process.Start(u); } catch { }
                            KBox("BLS blocks programs, but your browser can open the pages.\n\nThree BLS pages just opened in your browser (CPI, PPI, Employment Situation). On each one press Ctrl+S and save it into the folder that opened:\n" + BlsSavedFolder() + "\n\nThen press GET CPI / PPI / NFP HISTORY again.", "CPI / PPI HISTORY", MessageBoxButton.OK, MessageBoxImage.Information);
                        }
                    }));
                });
            };
            blsBtn.Click += delegate { getBls(); };
            if (!LoadStudioNews().Any(e => e.Source == "FILE" && (e.Title ?? "").Contains("(BLS)"))) { var disp0 = w.Dispatcher; System.Threading.ThreadPool.QueueUserWorkItem(delegate { string msg = null; try { msg = FetchBlsNewsHistory(false); } catch { } if (msg != null && disp0 != null) disp0.BeginInvoke(new Action(delegate { dlText.Text = msg; news = LoadStudioNews(); fill(); })); }); }
            Func<DateTime, DateTime, List<DateTime>> weekdays = (a, b) => { var l = new List<DateTime>(); for (var d = a.Date; d <= b.Date; d = d.AddDays(1)) if (d.DayOfWeek != DayOfWeek.Saturday && d.DayOfWeek != DayOfWeek.Sunday) l.Add(d); return l; };
            r2w.Click += delegate { rFrom.Text = DateTime.Today.AddDays(-14).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture); rTo.Text = DateTime.Today.AddDays(-1).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture); };
            r1m.Click += delegate { rFrom.Text = DateTime.Today.AddMonths(-1).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture); rTo.Text = DateTime.Today.AddDays(-1).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture); };
            rRnd.Click += delegate
            {
                var savedDays = days.Where(saved).OrderBy(d => d).ToList(); if (savedDays.Count < 12) { info.Text = "LOAD MORE DAYS FIRST (random 2 weeks needs saved days)"; return; }
                var start = savedDays[rnd.Next(savedDays.Count - 10)]; rFrom.Text = start.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture); rTo.Text = start.AddDays(13).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
            };
            rGo.Click += delegate
            {
                DateTime a = ParseStudioDate(rFrom.Text), b = ParseStudioDate(rTo.Text);
                if (a == DateTime.MinValue || b == DateTime.MinValue || b < a) { info.Text = "RANGE: type the dates as yyyy-MM-dd, FROM before TO"; return; }
                if (b >= DateTime.Today) b = DateTime.Today.AddDays(-1);
                var rlist = weekdays(a, b); if (rlist.Count == 0 || studioStartRange == null) { info.Text = studioStartRange == null ? "START RANGE plays the days in the 🎬 BACKTEST STUDIO's chart — open it from the launcher (in the labs: ▶ START HERE ▸ 📅 picks the dates)" : "NO WEEKDAYS IN THAT RANGE"; return; }
                studioStartRange(rlist); CloseToolQuietly(w);
            };
            stopBtn.Click += delegate { StopStudioDownload(); };
            randomBtn.Click += delegate
            {
                var pool = shownDays.Where(saved).ToList(); if (pool.Count == 0) pool = shownDays.ToList();
                if (pool.Count == 0) { info.Text = "NO DAY IN THIS FILTER"; return; }
                var pick = pool[rnd.Next(pool.Count)]; load(pick); CloseToolQuietly(w);
            };
            AskBeforeClosing(w, "PICK A DAY", () => "Close PICK A DAY?" + (dlBusy ? " The 6-year load goes on in the background." : ""));
            w.Closed += delegate { dlChanged -= showDl; dayPickerWindow = null; dayPickerFilter = null; };
            w.Show();
        }

