                    if (simC == null || simC.Finished) { note.Text = simC == null ? "That run could not be read." : "That run is finished (look at it in the PROP POOL tab)."; return; }
                    if (StyledConfirm(owner, "CONTINUE THE RUN?", Path.GetFileName(folder) + "\n\n" + simC.S.Describe() + "\n\nday " + (simC.PlanIndex + 1) + " of " + simC.Plan.Count + " • net so far " + Signed(simC.Net), "CONTINUE", Cyan)) start(simC.S, folder, false);
                };
            }
            // ONE STEP AT A TIME: the numbered steps on top, BACK / NEXT at the bottom of each
            var pills = new WrapPanel { Margin = new Thickness(0, 0, 0, 8) }; host.Children.Insert(0, pills);
            var pillBtns = new List<Button>(); Action<int> showStep = null;
            for (int k = 0; k < stepBorders.Count; k++)
            {
                int kk = k; var pb = Btn(stepLabels[k].Item1, Card); pb.Height = 28; pb.FontSize = 11; pb.Padding = new Thickness(8, 0, 8, 0); pb.Margin = new Thickness(0, 0, 4, 4);
                pb.Click += delegate { showStep(kk); }; pills.Children.Add(pb); pillBtns.Add(pb);
            }
            for (int k = 0; k < Math.Min(4, stepBodies.Count); k++)
            {
                int kk = k; var nav = new WrapPanel { Margin = new Thickness(0, 8, 0, 0) };
                if (k > 0) { var bk = btn("◀ BACK", Card); bk.Click += delegate { showStep(kk - 1); }; nav.Children.Add(bk); }
                if (k < 3) { var nx = btn("NEXT ▶  " + stepLabels[k + 1].Item1, Green); nx.Click += delegate { showStep(kk + 1); }; nav.Children.Add(nx); }
                if (nav.Children.Count > 0) stepBodies[k].Children.Add(nav);
            }
            showStep = k => { for (int i = 0; i < stepBorders.Count; i++) { stepBorders[i].Visibility = i == k ? Visibility.Visible : Visibility.Collapsed; PaintBtn(pillBtns[i], i == k ? stepLabels[i].Item2 : Card); } };
            showStep(0);
            // the settings from the boxes (null + why when something is not valid)
            Func<string[], KeystoneSimSettings> read = why =>
            {
                var s = new KeystoneSimSettings(); s.Rules = rules.Copy();
                foreach (var e in editors) { string v = e.Item3(); if (!KeystoneSimText.Set(e.Item1 is KeystoneSimRules ? (object)s.Rules : s, e.Item2, v)) { string lab0; PropSimLabels.TryGetValue(e.Item2, out lab0); why[0] = "Not valid: " + (lab0 ?? e.Item2) + " = \"" + v + "\""; return null; } }
                s.Strategy = codeOf(); s.Signal = s.Strategy == "STUDIO" ? codeSel() : 0; s.Auto = s.Strategy == "MANUAL" ? false : auto;
                DateTime a = ParseStudioDate(fromBox.Text), b = ParseStudioDate(toBox.Text); if (a == DateTime.MinValue || b == DateTime.MinValue || b < a) { why[0] = "FROM / TO: yyyy-MM-dd, FROM before TO."; return null; }
                s.From = a; s.To = b > DateTime.Today ? DateTime.Today : b;
                if (KeystonePropSim.Weekdays(s.From, s.To).Count == 0) { why[0] = "No weekday in FROM → TO (a weekend day has no session) — pick a weekday."; return null; }
                s.Firms = string.Join(";", firmRows.Select(f => f()));
                var fl = KeystoneSimFirm.Parse(s.Firms, s.Rules, 0);
                if (fl.Count != firmRows.Count || fl.Any(f => f.Count < 1 || f.Rules.Target <= 0 || f.Rules.EvalDrawdown <= 0 || f.Rules.EvalCost < 0)) { why[0] = "PROP FIRMS: every firm needs a name, 1+ evaluations, a target and a drawdown above $0."; return null; }
                s.Accounts = fl.Sum(f => f.Count);
                if (s.Accounts < 1 || s.Accounts > 500) { why[0] = "EVALUATIONS: 1 to 500 in all."; return null; }
                if (s.Strategy == "ROTATION" && s.Direction == "INDICATOR")
                {
                    if (indPool.Count == 0) { why[0] = "SIDES = 📡 INDICATOR needs an indicator: finish a rotation test first (it forms one) or BUILD one in PROP POOL ▸ 📡 INDICATOR."; return null; }
                    s.Indicator = indPool[Math.Max(0, Math.Min(indPool.Count - 1, indBox.SelectedIndex))].Item2.ToText();
                }
                else s.Indicator = string.Empty;
                if (s.Strategy == "ROTATION" && sameBox.IsChecked == true) { s.FundMnqQty = s.MnqQty; s.FundMgcQty = s.MgcQty; s.FundRotTarget = s.RotTarget; s.FundRotStop = s.RotStop; s.FundDayPlan = "SAME"; s.FundMaxTrades = 0; }
                if (s.Strategy == "ROTATION")
                {
                    if (s.MnqQty < 0 || s.MgcQty < 0 || s.FundMnqQty < 0 || s.FundMgcQty < 0 || s.MnqQty + s.MgcQty < 1 || s.FundMnqQty + s.FundMgcQty < 1) { why[0] = "The rotation needs at least 1 contract (MNQ and / or MGC), evaluation and funded."; return null; }
                    if (s.Rules.MaxMicros > 0 && (s.MnqQty + s.MgcQty > s.Rules.MaxMicros || s.FundMnqQty + s.FundMgcQty > s.Rules.MaxMicros)) { why[0] = "More micros than the firm allows (" + s.Rules.MaxMicros + " MNQ + MGC together)."; return null; }
                    if (s.RotTarget <= 0 || s.RotStop <= 0 || s.FundRotTarget <= 0 || s.FundRotStop <= 0) { why[0] = "Targets and stops must be above $0."; return null; }
                    if (s.PauseSeconds < 0) { why[0] = "PAUSE: 0 seconds or more."; return null; }
                }
                if (!IsValidHhmm(s.StartHhmm) || !IsValidHhmm(s.EndHhmm) || KeystoneRotDay.Slot(s.EndHhmm) <= KeystoneRotDay.Slot(s.StartHhmm)) { why[0] = "TRADING HOURS: HHMM (New York), FROM before CLOSE ALL in the day that starts 18:00 (e.g. 930 → 1555, or 1800 → 1555)."; return null; }
                if (s.Rules.Target <= 0 || s.Rules.EvalDrawdown <= 0) { why[0] = "The firm needs a profit target and a drawdown above $0."; return null; }
                return s;
            };
            changed = delegate
            {
                DateTime a = ParseStudioDate(fromBox.Text), b = ParseStudioDate(toBox.Text);
                if (a == DateTime.MinValue || b == DateTime.MinValue || b < a) { rangeInfo.Text = "FROM / TO: yyyy-MM-dd, FROM before TO"; rangeInfo.Foreground = Red; }
                else
                {
                    var days = KeystonePropSim.Weekdays(a, b); var mnq = KeystoneStudioStore.Sessions(StudioFolder(), "MNQ"); var mgc = KeystoneStudioStore.Sessions(StudioFolder(), "MGC");
                    int saved = days.Count(d => { int c1, c2; return mnq.TryGetValue(d, out c1) && c1 >= 600 && mgc.TryGetValue(d, out c2) && c2 >= 600; });
                    if (days.Count == 0) { rangeInfo.Text = a.ToString("dddd yyyy-MM-dd", CultureInfo.InvariantCulture).ToUpperInvariant() + " is a weekend day — pick a weekday"; rangeInfo.Foreground = Red; }
                    else { rangeInfo.Text = (days.Count == 1 ? "ONE DAY • " + days[0].ToString("dddd yyyy-MM-dd", CultureInfo.InvariantCulture).ToUpperInvariant() : days.Count + " weekdays") + " • " + saved + " saved on this PC • the others come from NinjaTrader as the run reaches them (a day with no data is skipped)"; rangeInfo.Foreground = saved == days.Count ? Green : Cyan; }
                }
                var why = new string[1]; var s = read(why);
                if (s == null) { summary.Text = ""; note.Text = why[0]; goWatch.IsEnabled = goFast.IsEnabled = goData.IsEnabled = false; return; }
                note.Text = ""; goWatch.IsEnabled = goFast.IsEnabled = goData.IsEnabled = true;
                summary.Text = s.Describe() + "\n\n" + s.Rules.Describe();
                var flB = KeystoneSimFirm.Parse(s.Firms, s.Rules, s.Accounts); double costAll = flB.Sum(f => f.Count * f.Rules.EvalCost);
                firmTotal.Text = "TOTAL: " + s.Accounts + " evaluations at " + flB.Count + " firm" + (flB.Count == 1 ? "" : "s") + " (" + string.Join(" • ", flB.Select(f => f.Code + " " + f.Count)) + ") = " + Cash(costAll);
                budgetInfo.Text = "BUDGET: " + s.Accounts + " evaluations = " + Cash(costAll) + (s.Allocation == "COPY" ? " — 📋 COPY: they all take the same trades; a blown batch is bought again the next day." : s.BuyRule == "BATCH" ? " — a new batch of " + s.Accounts + " (" + Cash(costAll) + ") the day after every one of them has passed or blown." : s.BuyRule == "BREAKEVEN" ? " — that is all the money: a blown / passed evaluation is replaced only after the payouts have paid it all back." : " — and a new one is bought every time one blows or passes."); budgetInfo.Foreground = Gold;
            };
            Action<bool, bool> go = (fast, dataOnly) =>
            {
                var why = new string[1]; var s = read(why); if (s == null) { note.Text = why[0]; return; } s.DataOnly = dataOnly;
                string warn = s.Auto && s.Strategy != "MANUAL" && !s.Rules.Automation ? "\n\n⚠ " + s.Rules.Name + " does not allow automated trading on real accounts (simulated anyway, to compare)." : "";
                int nDays = KeystonePropSim.Weekdays(s.From, s.To).Count;
                if (!StyledConfirm(owner, "START THE PROP SIMULATION?", s.Describe() + "\n\n" + s.Rules.Describe() + "\n\n" + nDays + " weekdays • " + (dataOnly ? "DATA ONLY: all days at full speed, no charts" : fast ? "ALL DAYS FAST" : "you watch it: ▶ PLAY at any speed, every next day loads by itself") + warn, dataOnly ? "📊 START DATA ONLY" : fast ? "⚡ START FAST" : "▶ START", Green)) return;
                try { Directory.CreateDirectory(PropSimFolder()); File.WriteAllText(Path.Combine(PropSimFolder(), "last_settings.txt"), s.ToText()); } catch { }
                start(s, null, fast);
            };
            goWatch.Click += delegate { go(false, false); };
            goFast.Click += delegate { go(true, false); };
            goData.Click += delegate { go(true, true); };
            paintHow();
        }

        // the PROP POOL: tiles, the money curve, the pools (EVAL / FUNDED / PAYOUTS / BLOWN + RETIRED), days, trades, events
        private void FillPropPool(ScrollViewer host, KeystonePropSim sim, bool running, Action<string> act)
        {
            var root = new StackPanel { Margin = new Thickness(16, 12, 16, 16) }; host.Content = root;
            var top = new DockPanel { Margin = new Thickness(0, 0, 0, 8) }; root.Children.Add(top);
            var btns = new StackPanel { Orientation = Orientation.Horizontal }; DockPanel.SetDock(btns, Dock.Right); top.Children.Add(btns);
            Func<string, Brush, string, Button> tb = (t, br, code) => { var b = Btn(t, br); b.Height = 30; b.Padding = new Thickness(12, 0, 12, 0); b.Click += delegate { act(code); }; btns.Children.Add(b); return b; };
            var runs = PropSimRuns();
            // the run on screen is selected; picking another shows it (the running one comes back live)
            int shown = sim == null ? -1 : runs.FindIndex(r => string.Equals(Path.GetFullPath(r).TrimEnd('\\', '/'), Path.GetFullPath(sim.Folder ?? ".").TrimEnd('\\', '/'), StringComparison.OrdinalIgnoreCase));
            var runPick = Select(new[] { "SAVED RUNS (" + runs.Count + ")" }.Concat(runs.Select(r => (running && r == (shown >= 0 ? runs[shown] : null) ? "● RUNNING • " : "") + Path.GetFileName(r))).ToArray()); runPick.SelectedIndex = shown + 1; runPick.Width = 300; runPick.ToolTip = "Look at a saved run";
            runPick.SelectionChanged += delegate { if (runPick.SelectedIndex > 0 && runPick.SelectedIndex - 1 != shown) act("VIEW|" + runs[runPick.SelectedIndex - 1]); };
            btns.Children.Add(runPick); tb("NEW SIMULATION…", Green, "SETUP");
            if (sim != null && sim.S.Strategy == "ROTATION" && sim.Days.Count > 0) tb("⚖ COMPARE SESSIONS", Cyan, "COMPARE").ToolTip = "What if the same days had been traded in another session? Every session side by side, the winner in green";
            if (sim != null && sim.Days.Count > 0 && !string.IsNullOrEmpty(sim.Folder)) tb("📄 EXPORT HTML", Card, "EXPORT").ToolTip = "One page with everything (saved in the run's folder and opened)";
            if (sim != null && !string.IsNullOrEmpty(sim.Folder)) tb("OPEN FOLDER", Card, "FOLDER");
            top.Children.Add(new TextBlock { Text = "🏦 PROP POOL", Foreground = Gold, FontSize = 22, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center });
            if (sim == null)
            {
                root.Children.Add(new TextBlock { Text = "No simulation yet. Press NEW SIMULATION… (or 🏦 PROP SIM in the studio's top bar): choose the strategy (random BB rotation, manual, or the studio's strategy in AUTO), how many accounts, the date range and the firm's rules — then watch it trade, or run all the days fast. Every day lands here.", Foreground = Muted, FontSize = 13, TextWrapping = TextWrapping.Wrap, MaxWidth = 900 });
                return;
            }
            root.Children.Add(new TextBlock { Text = sim.S.Describe() + " • " + sim.S.Rules.Name, Foreground = Muted, FontSize = 11.5, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 8), ToolTip = sim.S.Rules.Describe() });
            // an account card: balance + today, the bars that matter for its phase, the facts behind them; its edge pulses when it
            // trades (gold), nears its floor (red), or nears its target / a payout (green); click = its trades and events
            string runKey = sim.Folder ?? "";
            Func<KeystoneSimAccount, Border> card = a =>
            {
                bool funded = a.Phase == "FUNDED", dead = !a.Alive, trading = sim.Active == a && sim.DayOpen; var r = sim.S.Rules;
                Brush edge = a.Phase == "BLOWN" ? Red : a.Phase == "RETIRED" ? Gold : funded ? Orchid : Cyan;   // passed (funded) = violet
                bool lockedToday = a.Alive && sim.DayOpen && a.LockedToday; double today = a.Alive && sim.DayOpen ? a.DayPnl : 0;
                double bal = a.Bal + (sim.DayOpen && a.Alive ? a.DayPnl : 0), room = a.Alive ? bal - sim.Floor(a) : 0, dd = Math.Max(1, sim.Drawdown(a));
                double toTarget = Math.Max(0, r.Target - bal), tgtFrac = Math.Max(0, Math.Min(1, bal / Math.Max(1, r.Target)));
                bool danger = a.Alive && room < dd * 0.25, near = a.Alive && (!funded ? tgtFrac >= 0.8 : a.Qualifying >= Math.Max(1, r.PayoutDays) - 1);
                Brush pulse = dead ? null : trading ? Gold : danger ? Red : near ? Green : null;
                // the card's colour says the day: locked = orange • up today = green • down today = red (passed = violet edge, blown = red edge)
                Brush back = lockedToday ? Tint(Orange, 34) : today > 0 ? Tint(Green, 26) : today < 0 ? Tint(Red, 26) : funded ? Tint(Orchid, 30) : Card;
                var b = new Border { Background = back, CornerRadius = new CornerRadius(12), Margin = new Thickness(0, 0, 10, 10), Width = 330, BorderBrush = edge, BorderThickness = new Thickness(1.2), Opacity = dead ? 0.85 : 1, Cursor = System.Windows.Input.Cursors.Hand, ToolTip = "click = this account's trades and events" };
                var layers = new Grid(); b.Child = layers; var col = new StackPanel { Margin = new Thickness(12, 8, 12, 10) }; layers.Children.Add(col);
                if (pulse != null)
                {
                    var glow = new Border { BorderBrush = pulse, BorderThickness = new Thickness(3), CornerRadius = new CornerRadius(12), IsHitTestVisible = false };
                    layers.Children.Add(glow); glow.BeginAnimation(UIElement.OpacityProperty, new DoubleAnimation(1, 0.15, TimeSpan.FromMilliseconds(trading ? 600 : 900)) { AutoReverse = true, RepeatBehavior = RepeatBehavior.Forever });
                }
                var hd = new DockPanel();
                var chip = new Border { CornerRadius = new CornerRadius(8), Padding = new Thickness(8, 1, 8, 2), Background = Tint((SolidColorBrush)edge, 70), Child = new TextBlock { Text = (a.Phase == "BLOWN" ? "💀 " : a.Phase == "RETIRED" ? "★ " : funded ? "✔ " : "") + a.Phase, Foreground = System.Windows.Media.Brushes.White, FontSize = 10.5, FontWeight = FontWeights.Bold } };
                DockPanel.SetDock(chip, Dock.Right); hd.Children.Add(chip);
                if (lockedToday) { var lk = new Border { CornerRadius = new CornerRadius(8), Padding = new Thickness(8, 1, 8, 2), Margin = new Thickness(0, 0, 6, 0), Background = Tint(Orange, 90), Child = new TextBlock { Text = "🔒 LOCKED TODAY", Foreground = System.Windows.Media.Brushes.White, FontSize = 10.5, FontWeight = FontWeights.Bold }, ToolTip = a.DayNote }; DockPanel.SetDock(lk, Dock.Right); hd.Children.Add(lk); }
                hd.Children.Add(new TextBlock { Text = a.Name + (trading ? "  ◀ IN TURN" : ""), Foreground = trading ? Gold : Text, FontSize = 15, FontWeight = FontWeights.Bold });
                if (sim.HasFirms) hd.Children.Add(new TextBlock { Text = "  " + sim.FirmName(a), Foreground = Muted, FontSize = 10.5, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center });
                col.Children.Add(hd);
                var money = new WrapPanel();
                if (funded) col.Children.Add(new TextBlock { Text = "FUNDED BALANCE (since it passed)", Foreground = Orchid, FontSize = 9.5, FontWeight = FontWeights.Bold });
                money.Children.Add(new TextBlock { Text = Signed(bal), Foreground = MoneyBrush(bal), FontSize = 22, FontWeight = FontWeights.Bold, FontFamily = new FontFamily("Consolas"), Margin = new Thickness(0, 0, 10, 0) });
                if (a.Alive && sim.DayOpen && a.TradedToday) money.Children.Add(new TextBlock { Text = "today " + Signed(a.DayPnl) + (lockedToday && a.DayNote != "" ? " • " + a.DayNote : ""), TextWrapping = TextWrapping.Wrap, MaxWidth = 190, Foreground = MoneyBrush(a.DayPnl), FontSize = 13, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Bottom, Margin = new Thickness(0, 0, 0, 3) });
                col.Children.Add(money);
                Action<string, double, Brush> bar = (cap, frac, br) =>
                {
                    col.Children.Add(new TextBlock { Text = cap, Foreground = br, FontSize = 10.5, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 3, 0, 2), TextWrapping = TextWrapping.Wrap });
                    var g = new Grid { Height = 7 }; g.Children.Add(new Border { Background = Panel, CornerRadius = new CornerRadius(3) });
                    g.Children.Add(new Border { Background = br, CornerRadius = new CornerRadius(3), HorizontalAlignment = HorizontalAlignment.Left, Width = 306 * Math.Max(0, Math.Min(1, frac)) }); col.Children.Add(g);
                };
                Action<string, string, Brush> fact = (k, v, br) => { var dp = new DockPanel { Margin = new Thickness(0, 1, 0, 0) }; var vt = new TextBlock { Text = v, Foreground = br, FontSize = 11, FontWeight = FontWeights.Bold, FontFamily = new FontFamily("Consolas") }; DockPanel.SetDock(vt, Dock.Right); dp.Children.Add(vt); dp.Children.Add(new TextBlock { Text = k, Foreground = Muted, FontSize = 11 }); col.Children.Add(dp); };
                if (a.Alive)
                {
                    bar("ROOM TO THE FLOOR " + Cash(room) + " (floor " + Signed(sim.Floor(a)) + ")", room / dd, danger ? Red : room < dd * 0.5 ? Orange : Green);
                    if (!funded)
                    {
                        bar("TARGET +" + Cash(r.Target) + " • " + (100 * tgtFrac).ToString("0") + "% • " + Cash(toTarget) + " to go", tgtFrac, near ? Green : Cyan);
                        double perDay = a.EvalDays > 0 ? a.Bal / a.EvalDays : 0; int need = Math.Max(0, r.EvalMinDays - a.Days);
                        fact("days traded (minimum " + r.EvalMinDays + ")", a.Days + (need > 0 ? " • " + need + " more" : " ✔"), need > 0 ? Orange : Green);
                        fact("days to FUNDED at its pace", toTarget <= 0 ? "at target" : perDay > 0 ? "≈ " + Math.Max(Math.Max(1, need), (int)Math.Ceiling(toTarget / perDay)) : "— (not up yet)", perDay > 0 || toTarget <= 0 ? Green : Muted);
                        if (r.EvalConsistency > 0) { double share = a.Bal > 0 ? 100 * a.BestDay / a.Bal : 0; fact("best day " + Cash(a.BestDay) + " • limit " + r.EvalConsistency.ToString("0") + "%", a.Bal <= 0 ? "—" : share.ToString("0") + "%" + (share <= r.EvalConsistency + 1e-9 ? " ✔" : " ✖"), share <= r.EvalConsistency + 1e-9 ? Green : Red); }
                    }
                    else
                    {
                        double above = a.Bal - r.PayoutBuffer, gross = above > 0 ? Math.Min(r.PayoutCap > 0 ? r.PayoutCap : double.MaxValue, above * r.PayoutPercent / 100.0) : 0;
                        bool qToday = sim.DayOpen && a.TradedToday && (r.QualifyingDay <= 0 || (a.DayPnl > 0 && a.DayPnl >= r.QualifyingDay - 1e-9)); int qNow = a.Qualifying + (qToday ? 1 : 0);
                        col.Children.Add(new TextBlock { Text = "💰 PAYOUT CYCLE " + (a.Payouts + 1) + " • " + qNow + " of " + r.PayoutDays + " qualifying days" + (qToday ? " (incl. today)" : "") + " (≥ " + Cash(r.QualifyingDay) + ")", Foreground = near ? Green : Orchid, FontSize = 10.5, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 3, 0, 3) });
                        var dayBoxes = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 3) };
                        for (int qi = 0; qi < Math.Max(1, r.PayoutDays); qi++) dayBoxes.Children.Add(new Border { Width = 40, Height = 14, CornerRadius = new CornerRadius(4), Margin = new Thickness(0, 0, 5, 0), Background = qi < a.Qualifying ? Green : qi < qNow ? Tint(Green, 150) : Panel, BorderBrush = Orchid, BorderThickness = new Thickness(qi == qNow ? 1.5 : 0) });
                        col.Children.Add(dayBoxes);
                        fact("payout now would be", gross >= Math.Max(1, r.PayoutMin) ? Cash(gross) + " → you " + Cash(gross * r.Split / 100.0) : "— (" + (above > 0 ? "under the minimum" : "under the buffer") + ")", gross > 0 ? Green : Muted);
                        fact("payouts so far", a.Payouts + (r.MaxPayouts > 0 ? " of " + r.MaxPayouts : "") + " • " + Cash(a.Cash), a.Payouts > 0 ? Green : Muted);
                    }
                    if (r.MinHoldSeconds > 0) { double all = a.ProfitHeld + a.ProfitShort, held = all > 0 ? 100 * a.ProfitHeld / all : 100; fact(r.MinHoldSeconds + "-second rule (≥ " + r.MinHoldShare.ToString("0") + "% held)", held.ToString("0") + "%" + (held >= r.MinHoldShare - 1e-9 ? " ✔" : " ✖"), held >= r.MinHoldShare - 1e-9 ? Green : Red); }
                }
                else col.Children.Add(new TextBlock { Text = a.EndReason + (a.Ended != DateTime.MinValue ? " • " + a.Ended.ToString("yyyy-MM-dd") : ""), Foreground = a.Phase == "BLOWN" ? Red : Gold, FontSize = 11.5, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap });
                if (a.PassedOn != DateTime.MinValue)
                {
                    var ft = sim.Trades.Where(t => t.Account == a.Id && t.Phase == "FUNDED").ToList();
                    fact("funded trades • won", ft.Count + " • " + (ft.Count == 0 ? 0 : 100 * ft.Count(t => t.Pnl > 0) / ft.Count) + "%", Text);
                    fact("funded days • passed in", a.FundedDays + " • " + a.EvalDays + " evaluation days", Text);
                }
                else
                {
                    fact("trades • won", a.Trades + " • " + (a.Trades == 0 ? 0 : 100 * a.Wins / a.Trades) + "%", Text);
                    fact("evaluation days", a.EvalDays.ToString(), Text);
                }
                fact("bought " + a.Bought.ToString("yyyy-MM-dd") + (a.PassedOn != DateTime.MinValue ? " • passed " + a.PassedOn.ToString("MM-dd") : ""), "spent " + Cash(a.Spent), Orange);
                fact("received • net", Cash(a.Cash) + " • " + Signed(a.Net), MoneyBrush(a.Net));
                // click: this account's trades and events
                var more = new StackPanel { Margin = new Thickness(0, 6, 0, 0) }; col.Children.Add(more); string key = runKey + "|" + a.Id;
                Action fill = delegate
                {
                    more.Children.Clear(); if (!propPoolOpen.Contains(key)) return;
                    var tr = sim.Trades.Where(t => t.Account == a.Id).Reverse().Take(14).ToList();
                    more.Children.Add(new TextBlock { Text = tr.Count == 0 ? "no trades yet" : "LAST TRADES", Foreground = Muted, FontSize = 10, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 2, 0, 2) });
                    foreach (var t in tr) more.Children.Add(new TextBlock { Text = t.Day.ToString("MM-dd") + " " + t.Entry.ToString("HH:mm") + " " + (t.Legs == "" ? (t.Dir > 0 ? "BUY" : "SELL") : t.Legs) + "  " + Signed(t.Pnl) + "  " + t.Reason, Foreground = t.Pnl >= 0 ? Green : Red, FontSize = 10.5, FontFamily = new FontFamily("Consolas"), TextWrapping = TextWrapping.Wrap });
                    var ev = sim.Events.Where(e => e.Account == a.Id && e.Kind != "LOCKED").Reverse().Take(6).ToList();
