            views.Add(Tuple.Create("WINNERS", "🏆 WINNERS", (Brush)Green, (Func<UIElement>)(() => PropWinnersView(sim, act))));
            // 📊 STRATEGY (every strategy): the run's trades broken down — instrument, side, session, hour, weekday, exit, phase, account
            views.Insert(Math.Min(views.Count, 5), Tuple.Create("STRATEGY", "📊 " + PropStrategyName(sim), (Brush)Cyan, (Func<UIElement>)(() => PropStrategyView(sim))));
            // the tab bar on top (one view at a time) and the view below it
            var strip = new WrapPanel { Margin = new Thickness(0, 2, 0, 10) }; root.Children.Add(strip);
            var bodyHost = new Border(); root.Children.Add(bodyHost);
            var tabBtns = new List<Tuple<string, Button, Brush>>();
            foreach (var vw in views)
            {
                var vv = vw; var b = Btn(vw.Item2, Card); b.Height = 34; b.FontSize = 12; b.Padding = new Thickness(12, 0, 12, 0); b.Margin = new Thickness(0, 0, 6, 6);
                b.Click += delegate { show(vv.Item1); }; strip.Children.Add(b); tabBtns.Add(Tuple.Create(vw.Item1, b, vw.Item3));
            }
            show = key =>
            {
                var vw = views.FirstOrDefault(x => x.Item1 == key) ?? views[0]; propPoolView = vw.Item1;
                foreach (var tbn in tabBtns) PaintBtn(tbn.Item2, tbn.Item1 == vw.Item1 ? tbn.Item3 : Card);
                bodyHost.Child = vw.Item4();
            };
            if (propPoolWant != null) { propPoolView = propPoolWant; propPoolWant = null; }
            show(propPoolView);
        }
