        private static string ResearchFolder() { return Path.Combine(PropSimFolder(), "Research"); }
        private static List<KeystoneDaySession> LoadDaySessions(string file) { var l = new List<KeystoneDaySession>(); try { if (File.Exists(file)) foreach (var x in File.ReadAllLines(file).Skip(1)) { var r = KeystoneDaySession.Parse(x); if (r != null) l.Add(r); } } catch { } return l; }
        private static List<KeystoneDaySession> ResearchPool() { return LoadDaySessions(Path.Combine(ResearchFolder(), "day_sessions.csv")); }
        // a test's rows into the research pool (one row per day × session × set-up; a repeat replaces the old one)
        private static int AddToResearchPool(IEnumerable<KeystoneDaySession> rows)
        {
            try
            {
                Directory.CreateDirectory(ResearchFolder()); var map = ResearchPool().ToDictionary(r => r.Key, r => r); int before = map.Count;
                foreach (var r in rows) map[r.Key] = r;
                File.WriteAllLines(Path.Combine(ResearchFolder(), "day_sessions.csv"), new[] { KeystoneDaySession.Header }.Concat(map.Values.OrderBy(r => r.Day).ThenBy(r => r.Session).Select(r => r.Line())));
                return map.Count - before;
            }
            catch { return 0; }
        }
