        private static void SavePropIndicator(KeystoneEntryIndicator ind) { SavePropIndicator(ind, true); }
        private static string SavePropIndicator(KeystoneEntryIndicator ind, bool choose)
        {
            try
            {
                Directory.CreateDirectory(PropIndicatorPoolFolder()); var t = ind.Formed == DateTime.MinValue ? DateTime.Now : ind.Formed;
                string f = Path.Combine(PropIndicatorPoolFolder(), t.ToString("yyyyMMdd_HHmmss", CultureInfo.InvariantCulture) + "_" + ind.TrainFrom.ToString("yyyyMMdd") + "-" + ind.TrainTo.ToString("yyyyMMdd") + ".txt");
                for (int k = 2; File.Exists(f); k++) f = f.Replace(".txt", "_" + k + ".txt");
                File.WriteAllText(f, ind.ToText());
                if (choose) File.WriteAllText(PropIndicatorFile(), ind.ToText());
                File.AppendAllText(Path.Combine(PropSimFolder(), "IndicatorHistory.txt"), DateTime.Now.ToString("yyyy-MM-dd HH:mm") + " " + ind.Describe() + "\n");
                return f;
            }
            catch { return null; }
        }
        private static List<Tuple<string, KeystoneEntryIndicator>> PropIndicatorPool()
        {
            var list = new List<Tuple<string, KeystoneEntryIndicator>>(); EnsureBuiltinIndicator();
            try { if (Directory.Exists(PropIndicatorPoolFolder())) foreach (var f in Directory.GetFiles(PropIndicatorPoolFolder(), "*.txt")) { var i = KeystoneEntryIndicator.FromText(File.ReadAllText(f)); if (i != null) list.Add(Tuple.Create(f, i)); } } catch { }
            return list.OrderByDescending(x => x.Item2.Formed).ThenByDescending(x => x.Item1).ToList();
        }
