        private static string AiKey() { try { var ev = Environment.GetEnvironmentVariable("ANTHROPIC_API_KEY"); if (!string.IsNullOrWhiteSpace(ev)) return ev.Trim(); var f = Path.Combine(StudioFolder(), "AiCoachKey.txt"); if (File.Exists(f)) return File.ReadAllText(f).Trim(); } catch { } return ""; }
        // one AI question (blocking; call it off the UI thread): MY CLAUDE PLAN = Claude Code on this PC ("claude -p") • else the API key
        private static KeystoneCoachAnswer AiAsk(string system, string prompt, bool viaPlan, string key)
        {
            var pa = new KeystoneCoachAnswer();
            if (viaPlan)
            {
                try
                {
                    var psi = new System.Diagnostics.ProcessStartInfo("cmd.exe", "/c claude -p --max-turns 1 --output-format text") { UseShellExecute = false, RedirectStandardInput = true, RedirectStandardOutput = true, RedirectStandardError = true, CreateNoWindow = true, WorkingDirectory = Path.GetTempPath(), StandardOutputEncoding = Encoding.UTF8 };
                    using (var proc = System.Diagnostics.Process.Start(psi))
                    {
                        proc.StandardInput.Write(system + "\nAnswer in plain text only; do not use any tools, files or commands.\n\n" + prompt); proc.StandardInput.Close();
                        var outTask = proc.StandardOutput.ReadToEndAsync(); var errTask = proc.StandardError.ReadToEndAsync();
                        if (!proc.WaitForExit(180000)) { try { proc.Kill(); } catch { } pa.Error = "Claude Code did not answer within 3 minutes"; return pa; }
                        string outS = (outTask.Result ?? "").Trim(), errS = (errTask.Result ?? "").Trim();
                        if (proc.ExitCode == 0 && outS != "") { pa.Ok = true; pa.Text = outS; }
                        else pa.Error = (errS + " " + outS).Contains("not recognized") ? "Claude Code is not installed on this PC (PowerShell: irm https://claude.ai/install.ps1 | iex, then run claude once and log in)" : (errS != "" ? errS : outS != "" ? outS : "Claude Code returned nothing (log in: open a terminal and run   claude)");
                    }
                }
                catch (Exception ex) { pa.Error = "could not start Claude Code: " + ex.Message; }
                return pa;
            }
            string reply;
            try
            {
                System.Net.ServicePointManager.SecurityProtocol |= (System.Net.SecurityProtocolType)3072;
                using (var wc = new System.Net.WebClient())
                {
                    wc.Encoding = Encoding.UTF8; wc.Headers.Add("x-api-key", key); wc.Headers.Add("anthropic-version", "2023-06-01"); wc.Headers.Add("anthropic-beta", KeystoneAiCoach.Beta); wc.Headers.Add("content-type", "application/json");
                    reply = wc.UploadString(KeystoneAiCoach.Url, "POST", KeystoneAiCoach.RequestFor(system, prompt));
                }
            }
            catch (System.Net.WebException wex)
            {
                reply = null; try { if (wex.Response != null) using (var rd = new StreamReader(wex.Response.GetResponseStream())) reply = rd.ReadToEnd(); } catch { }
                if (string.IsNullOrEmpty(reply)) reply = "{\"type\":\"error\",\"error\":{\"type\":\"connection\",\"message\":" + KeystoneJson.Str(wex.Message) + "}}";
            }
            catch (Exception ex) { reply = "{\"type\":\"error\",\"error\":{\"type\":\"connection\",\"message\":" + KeystoneJson.Str(ex.Message) + "}}"; }
            return KeystoneAiCoach.Answer(reply);
        }
        private string propPoolWant; private string propCompareBusy; private string propCompareKind = "SESSIONS"; private List<KeystoneTradeContext> propWinners; private string propWinnersFolder, propWinnersBusy;   // a pool tab to show next (its header's start) • "k / n" while COMPARE SESSIONS runs

        // 💰 PAYOUT CYCLES (PROP POOL): the firm's payout logic step by step, every funded account's cycles in order
        private UIElement PropPayoutView(KeystonePropSim sim, UIElement payoutTable)
        {
            var r = sim.S.Rules; var root = new StackPanel { Margin = new Thickness(12, 10, 12, 16) };
            // the money in a few numbers
            var paid = sim.Accounts.Where(x => x.Payouts > 0).ToList(); int fp = KeystoneSessionWhatIf.FirstPayout(sim), be = KeystoneSessionWhatIf.Breakeven(sim);
            var tiles = new WrapPanel { Margin = new Thickness(0, 0, 0, 10) }; root.Children.Add(tiles);
            Action<string, string, Brush, string> tile = (cap, val, br, sub) => { var sp0 = new StackPanel(); sp0.Children.Add(new TextBlock { Text = cap, Foreground = Muted, FontSize = 10.5, FontWeight = FontWeights.Bold }); sp0.Children.Add(new TextBlock { Text = val, Foreground = br, FontSize = 22, FontWeight = FontWeights.Bold, FontFamily = new FontFamily("Consolas") }); if (sub != "") sp0.Children.Add(new TextBlock { Text = sub, Foreground = Muted, FontSize = 10.5, TextWrapping = TextWrapping.Wrap, MaxWidth = 180 }); tiles.Children.Add(new Border { Background = Card, CornerRadius = new CornerRadius(10), Padding = new Thickness(14, 8, 16, 10), Margin = new Thickness(0, 0, 10, 8), MinWidth = 140, BorderBrush = br, BorderThickness = new Thickness(0, 0, 0, 3), Child = sp0 }); };
            tile("PAID OUT (GROSS)", Cash(sim.Accounts.Sum(x => x.Gross)), Gold, sim.PayoutCount + " payouts from " + paid.Count + " accounts");
            tile("YOU RECEIVED", Cash(sim.Cash), Green, "after the " + r.Split.ToString("0") + "% split");
            tile("SPENT", Cash(sim.Spent), Orange, sim.Bought + " evaluations" + (r.Activation > 0 ? " + activations" : ""));
            tile("PROFIT SINCE THE FIRST INVESTMENT", Signed(sim.Net), MoneyBrush(sim.Net), "received − spent");
            tile("RETURN (ROI)", (sim.Spent > 0 ? 100.0 * sim.Net / sim.Spent : 0).ToString("0") + "%", MoneyBrush(sim.Net), "");
            tile("AVERAGE PAYOUT", sim.PayoutCount > 0 ? Cash(sim.Cash / sim.PayoutCount) : "—", Green, "to you");
            tile("FIRST PAYOUT", fp > 0 ? "day " + fp : "—", fp > 0 ? Green : Muted, fp > 0 ? sim.Days[fp - 1].Day.ToString("ddd yyyy-MM-dd", CultureInfo.InvariantCulture) : "");
            tile("BREAKEVEN", be > 0 ? "day " + be : "—", be > 0 ? Green : Muted, be > 0 ? sim.Days[be - 1].Day.ToString("ddd yyyy-MM-dd", CultureInfo.InvariantCulture) : sim.Net < 0 ? Cash(-sim.Net) + " still to pay back" : "");
            tile("FUNDED NOW • PAYABLE NOW", sim.Accounts.Count(x => x.Funded) + " • " + Cash(sim.Accounts.Where(x => x.Funded && x.Qualifying >= Math.Max(1, r.PayoutDays)).Sum(x => { double ab = x.Bal - r.PayoutBuffer; return ab > 0 ? Math.Min(r.PayoutCap > 0 ? r.PayoutCap : double.MaxValue, ab * r.PayoutPercent / 100.0) : 0; })), Orchid, "accounts with the qualifying days done");
            // per account
            var ag = new Grid { Margin = new Thickness(0, 0, 0, 12) }; double[] aw = { 60, 80, 80, 80, 70, 100, 100, 80, 100, 110 }; foreach (var c in aw) ag.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(c) });
            int ar = 0; Action<string[], Brush, bool> aline = (cells, br, hdr) => { ag.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); for (int c = 0; c < cells.Length; c++) { var tb0 = new TextBlock { Text = cells[c], Foreground = br, FontSize = hdr ? 10.5 : 12, FontWeight = hdr ? FontWeights.Bold : FontWeights.Normal, FontFamily = hdr ? new FontFamily("Segoe UI") : new FontFamily("Consolas"), Margin = new Thickness(0, 1, 8, 1) }; Grid.SetRow(tb0, ar); Grid.SetColumn(tb0, c); ag.Children.Add(tb0); } ar++; };
            aline(new[] { "ACCOUNT", "NOW", "PASSED", "FUNDED DAYS", "PAYOUTS", "PAID GROSS", "TO YOU", "SPENT", "NET", "BALANCE NOW" }, Muted, true);
            foreach (var x in sim.Accounts.Where(x => x.PassedOn != DateTime.MinValue).OrderByDescending(x => x.Cash).ThenBy(x => x.Id))
                aline(new[] { x.Name, x.Phase, x.PassedOn.ToString("MM-dd"), x.FundedDays.ToString(), x.Payouts.ToString(), Cash(x.Gross), Cash(x.Cash), Cash(x.Spent), Signed(x.Net), x.Alive ? Signed(x.Bal + (sim.DayOpen ? x.DayPnl : 0)) : "—" }, x.Net > 0 ? Green : x.Phase == "BLOWN" ? Red : Text, false);
            root.Children.Add(new TextBlock { Text = "EVERY FUNDED ACCOUNT'S MONEY", Foreground = Gold, FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 4) });
            root.Children.Add(new Border { Background = Panel, CornerRadius = new CornerRadius(10), Padding = new Thickness(12, 8, 12, 8), Child = ag, HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(0, 0, 0, 12) });
            root.Children.Add(new TextBlock { Text = "💰 HOW A PAYOUT HAPPENS (" + r.Name + ")", Foreground = Gold, FontSize = 16, FontWeight = FontWeights.Bold });
            var steps = new[]
            {
                "1  The account passes → FUNDED, its balance starts again at $0 (only what is made from now on counts).",
                "2  Every funded day with ≥ " + Cash(r.QualifyingDay) + " profit is a QUALIFYING day.",
                "3  After " + r.PayoutDays + " qualifying days" + (r.PayoutConsistency > 0 ? " and the best day ≤ " + r.PayoutConsistency.ToString("0") + "% of the profit since the last payout" : "") + ": a payout of " + r.PayoutPercent.ToString("0") + "% of the balance above the " + Cash(r.PayoutBuffer) + " buffer" + (r.PayoutCap > 0 ? ", at most " + Cash(r.PayoutCap) : "") + (r.PayoutMin > 0 ? ", at least " + Cash(r.PayoutMin) : "") + ".",
                "4  You keep " + r.Split.ToString("0") + "%; the payout leaves the account and the rest stays as the CARRY-OVER balance.",
                "5  A new cycle starts at 0 qualifying days" + (r.MaxPayouts > 0 ? "; after " + r.MaxPayouts + " payouts the account is retired" : "") + ". The drawdown floor still applies."
            };
            var sb = new Border { Background = Panel, CornerRadius = new CornerRadius(10), Padding = new Thickness(14, 8, 14, 10), Margin = new Thickness(0, 6, 0, 12) }; var sp = new StackPanel(); sb.Child = sp;
            foreach (var st in steps) sp.Children.Add(new TextBlock { Text = st, Foreground = Text, FontSize = 12.5, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 2) });
            root.Children.Add(sb);
            var funded = sim.Accounts.Where(a => a.PassedOn != DateTime.MinValue).OrderByDescending(a => a.Funded).ThenBy(a => a.Id).ToList();
            if (funded.Count == 0) { root.Children.Add(new TextBlock { Text = "No account has passed yet.", Foreground = Muted, FontSize = 13 }); }
            var wrap = new WrapPanel(); root.Children.Add(wrap);
            foreach (var a in funded)
            {
                var cyc = sim.PayoutCycles(a); var cur = cyc.LastOrDefault(c => c.Open);
                var b = new Border { Width = 440, Margin = new Thickness(0, 0, 10, 10), Padding = new Thickness(12, 8, 12, 10), CornerRadius = new CornerRadius(12), Background = Tint(Orchid, (byte)(a.Funded ? 34 : 16)), BorderBrush = a.Phase == "BLOWN" ? Red : Orchid, BorderThickness = new Thickness(1.5) };
                var col = new StackPanel(); b.Child = col; wrap.Children.Add(b);
                col.Children.Add(new TextBlock { Text = a.Name + " • " + a.Phase + " • passed " + a.PassedOn.ToString("MM-dd") + " • payouts " + a.Payouts + " (" + Cash(a.Cash) + " to you)", Foreground = a.Funded ? Orchid : Muted, FontSize = 14, FontWeight = FontWeights.Bold });
                if (cur != null)
                {
                    double above = a.Bal - r.PayoutBuffer, gross = above > 0 ? Math.Min(r.PayoutCap > 0 ? r.PayoutCap : double.MaxValue, above * r.PayoutPercent / 100.0) : 0;
                    col.Children.Add(new TextBlock { Text = "CYCLE " + cur.No + " NOW • balance " + Signed(a.Bal + (sim.DayOpen ? a.DayPnl : 0)) + " • qualifying " + (a.Qualifying + (sim.DayOpen && a.TradedToday && a.DayPnl > 0 && a.DayPnl >= r.QualifyingDay - 1e-9 ? 1 : 0)) + " / " + r.PayoutDays + " (incl. today) • payable now " + (gross > 0 ? Cash(gross) + " → you " + Cash(gross * r.Split / 100) : "—"), Foreground = Text, FontSize = 12, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 4, 0, 4) });
                }
                foreach (var c in cyc)
                {
                    var row = new WrapPanel { Margin = new Thickness(0, 2, 0, 2) };
                    row.Children.Add(new TextBlock { Text = "#" + c.No + " ", Foreground = c.Open ? Gold : Green, FontSize = 12, FontWeight = FontWeights.Bold, Width = 34 });
                    foreach (var d in c.Days) row.Children.Add(new Border { Width = 22, Height = 16, CornerRadius = new CornerRadius(3), Margin = new Thickness(0, 0, 3, 0), Background = d.Item3 ? Green : d.Item2 < 0 ? Tint(Red, 120) : Panel, ToolTip = d.Item1.ToString("ddd yyyy-MM-dd", CultureInfo.InvariantCulture) + " " + Signed(d.Item2) + (d.Item3 ? " • qualifying" : "") });
                    row.Children.Add(new TextBlock { Text = "  " + c.Days.Count + " days • " + c.Qualifying + " qualifying • " + Signed(c.Profit) + (c.Open ? " • running" : " • PAID " + Cash(c.Gross) + " → you " + Cash(c.Cash) + " • carried " + Signed(c.BalanceAfter)), Foreground = c.Open ? Text : Green, FontSize = 11.5, FontFamily = new FontFamily("Consolas"), VerticalAlignment = VerticalAlignment.Center });
                    col.Children.Add(row);
                }
            }
            root.Children.Add(new TextBlock { Text = "EVERY PAYOUT", Foreground = Gold, FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 10, 0, 4) });
            root.Children.Add(payoutTable);
