        }

        // 🏆 WINNERS (PROP POOL): every trade with what came before it; the conditions the winners shared against all trades
        private UIElement PropWinnersView(KeystonePropSim sim, Action<string> act)
        {
            var root = new StackPanel { Margin = new Thickness(12, 10, 12, 16) };
            root.Children.Add(new TextBlock { Text = "THE WINNERS: WHAT CAME BEFORE THE TRADES THAT REACHED THE TARGET?", Foreground = Green, FontSize = 16, FontWeight = FontWeights.Bold });
            root.Children.Add(new TextBlock { Text = "Every rotation trade of this run with its session, sides and both instruments' last 5 / 15 / 30 minutes before the entry (WITH = the leg went the way the price had moved, AGAINST = the other way). A condition helps only if its win rate is clearly above ALL TRADES — with few trades it is luck. Saved as winners.csv in the run's folder (for an indicator).", Foreground = Muted, FontSize = 12, TextWrapping = TextWrapping.Wrap, MaxWidth = 1000, Margin = new Thickness(0, 2, 0, 10) });
            var cx = propWinners != null && propWinnersFolder == sim.Folder ? propWinners : null;
            var go = Btn(propWinnersBusy != null ? "🏆 " + propWinnersBusy : cx == null ? "🏆 ANALYZE THE WINNERS" : "↻ ANALYZE AGAIN (the trades so far)", Green); go.Height = 36; go.HorizontalAlignment = HorizontalAlignment.Left; go.IsEnabled = propWinnersBusy == null; go.Margin = new Thickness(0, 0, 0, 10); go.Click += delegate { act("WINNERS"); };
            root.Children.Add(go);
            if (cx == null || cx.Count == 0) return root;
            int won = cx.Count(x => x.Won); double basePct = 100.0 * won / cx.Count;
            root.Children.Add(new TextBlock { Text = "ALL TRADES: " + cx.Count + " • reached the target: " + won + " (" + basePct.ToString("0") + "%) • average time to the target " + cx.Where(x => x.Won).Select(x => x.Minutes).DefaultIfEmpty(0).Average().ToString("0") + " min", Foreground = Gold, FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 8) });
            var g = new Grid(); double[] cw = { 220, 220, 80, 90, 90, 110 }; foreach (var c in cw) g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(c) });
