            var aiA = Btn("🤖 FIND PATTERNS • API KEY", Card); aiA.Height = 32; aiA.Margin = new Thickness(0, 0, 8, 6); aiA.IsEnabled = !propDaySessAiBusy && pool.Count > 0; aiA.Click += delegate { act("DAYSESS|AI|API"); }; aiRow.Children.Add(aiA);
            string aiText = propDaySessAi; if (aiText == null) { try { var f = Path.Combine(ResearchFolder(), "ai_patterns.txt"); if (File.Exists(f)) aiText = File.ReadAllText(f); } catch { } }
            if (!string.IsNullOrEmpty(aiText)) root.Children.Add(new Border { Background = HexBrush("#151B33"), BorderBrush = HexBrush("#7C4DFF"), BorderThickness = new Thickness(3, 0, 0, 0), CornerRadius = new CornerRadius(8), Padding = new Thickness(12, 8, 12, 10), MaxWidth = 1050, HorizontalAlignment = HorizontalAlignment.Left, Child = new TextBlock { Text = aiText, Foreground = aiText.StartsWith("⚠") ? Red : Text, FontSize = 13, TextWrapping = TextWrapping.Wrap, LineHeight = 19 } });
            root.Children.Add(new TextBlock { Text = "Saved on this PC: the test's day_sessions.csv, and PropSim\\Research\\day_sessions.csv (the whole pool) + ai_patterns.txt. History, not a promise.", Foreground = Muted, FontSize = 10.5, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 0) });
