        private static Brush Brushes0() { return System.Windows.Media.Brushes.Transparent; }
        // 🏢 FIRMS: every firm's evaluations — passed / blown / running, the pass rate, cost, days to pass, its rules (trailing or not)
        private UIElement PropFirmsView(KeystonePropSim sim)
        {
            var root = new StackPanel { Margin = new Thickness(12, 10, 12, 16) };
            root.Children.Add(new TextBlock { Text = "🏢 PROP FIRMS • HOW MANY PASSED AT EACH", Foreground = Blue, FontSize = 17, FontWeight = FontWeights.Bold });
            root.Children.Add(new TextBlock { Text = "The accounts are numbered by firm (e.g. NW-01) and traded firm by firm. Same strategy everywhere — a difference between firms comes from their rules (drawdown, trailing, target, consistency) or luck.", Foreground = Muted, FontSize = 12, TextWrapping = TextWrapping.Wrap, MaxWidth = 1050, Margin = new Thickness(0, 2, 0, 10) });
            var wrap = new WrapPanel(); root.Children.Add(wrap);
            for (int i = 0; i < sim.FirmList.Count; i++)
            {
                var f = sim.FirmList[i]; var acc = sim.Accounts.Where(a => sim.HasFirms ? a.Firm == i : true).ToList(); var r = f.Rules;
                int passed = acc.Count(a => a.PassedOn != DateTime.MinValue), blown = acc.Count(a => a.WasPhase == "EVAL" && (a.Phase == "BLOWN" || a.Phase == "RETIRED")), running = acc.Count(a => a.Phase == "EVAL"), done = passed + blown;
                double rate = done == 0 ? 0 : 100.0 * passed / done; var passDays = acc.Where(a => a.PassedOn != DateTime.MinValue).Select(a => (double)a.EvalDays).ToList();
                var sp = new StackPanel();
                sp.Children.Add(new TextBlock { Text = (f.Code != "" ? f.Code + " • " : "") + f.Name, Foreground = Text, FontSize = 15, FontWeight = FontWeights.Bold });
                sp.Children.Add(new TextBlock { Text = rate.ToString("0") + "% PASSED", Foreground = passed > 0 ? Green : Muted, FontSize = 24, FontWeight = FontWeights.Bold, FontFamily = new FontFamily("Consolas") });
                sp.Children.Add(new TextBlock { Text = passed + " passed • " + blown + " blown • " + running + " running • " + acc.Count + " bought", Foreground = Text, FontSize = 12 });
                var barG = new Grid { Height = 10, Width = 280, HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(0, 4, 0, 4) }; barG.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(Math.Max(0.001, passed), GridUnitType.Star) }); barG.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(Math.Max(0.001, blown), GridUnitType.Star) }); barG.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(Math.Max(0.001, running), GridUnitType.Star) });
                for (int c = 0; c < 3; c++) { var bb = new Border { Background = c == 0 ? Green : c == 1 ? Red : Cyan, CornerRadius = new CornerRadius(2), Margin = new Thickness(0, 0, 1, 0) }; Grid.SetColumn(bb, c); barG.Children.Add(bb); } sp.Children.Add(barG);
                sp.Children.Add(new TextBlock { Text = "spent " + Cash(acc.Sum(a => a.Spent)) + (passed > 0 ? " • " + Cash(acc.Sum(a => a.Spent) / passed) + " per pass • " + passDays.Average().ToString("0.0") + " days to pass" : ""), Foreground = Muted, FontSize = 11.5 });
                sp.Children.Add(new TextBlock { Text = "target +" + Cash(r.Target) + " • drawdown " + Cash(r.EvalDrawdown) + " " + (r.EvalDdType == "STATIC" ? "fixed" : "TRAILING (" + (r.EvalDdType == "INTRADAY" ? "intraday" : "end of day") + ", stops at " + Signed(r.EvalLockAt) + ")") + " • consistency " + r.EvalConsistency.ToString("0") + "% • min " + r.EvalMinDays + " days • $" + r.EvalCost.ToString("0") + " each", Foreground = Muted, FontSize = 10.5, TextWrapping = TextWrapping.Wrap, MaxWidth = 300 });
                wrap.Children.Add(new Border { Background = Card, BorderBrush = Blue, BorderThickness = new Thickness(0, 0, 0, 3), CornerRadius = new CornerRadius(10), Padding = new Thickness(14, 10, 14, 10), Margin = new Thickness(0, 0, 10, 10), Width = 330, Child = sp });
            }
            return new ScrollViewer { Content = root, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, MaxHeight = 900 };
        }
        private static string PropStrategyName(KeystonePropSim sim)
        {
            var s = sim.S; return s.Strategy == "ROTATION" ? "ROTATION" : s.Strategy == "MANUAL" ? "MY TRADES" : s.Signal > 0 && s.Signal < KeystoneReplaySignals.Names.Length ? KeystoneReplaySignals.Names[s.Signal] : "STRATEGY";
        }
        // 📊 the strategy's own results (any strategy): what worked where — by instrument, side, session, hour, weekday, exit, phase, account
        private UIElement PropStrategyView(KeystonePropSim sim)
        {
            var root = new StackPanel { Margin = new Thickness(12, 10, 12, 16) }; var tr = sim.Trades.ToList();
            root.Children.Add(new TextBlock { Text = "📊 " + PropStrategyName(sim) + " • THE STRATEGY'S RESULTS", Foreground = Cyan, FontSize = 17, FontWeight = FontWeights.Bold });
            root.Children.Add(new TextBlock { Text = sim.S.Describe(), Foreground = Muted, FontSize = 11.5, TextWrapping = TextWrapping.Wrap, MaxWidth = 1050, Margin = new Thickness(0, 2, 0, 10) });
            if (tr.Count == 0) { root.Children.Add(new TextBlock { Text = "No trade yet — the breakdown fills in as the strategy trades.", Foreground = Muted, FontSize = 13 }); return root; }
            Func<KeystoneSimTrade, string> symOf = t => { var w = (t.Legs ?? "").Split(new[] { ' ', '+' }, StringSplitOptions.RemoveEmptyEntries); var syms = w.Where(x => x.Length >= 2 && x.All(char.IsLetter) && x != "BUY" && x != "SELL").Distinct().ToList(); return syms.Count == 0 ? "?" : string.Join(" + ", syms); };
            Func<KeystoneSimTrade, string> sideOf = t => { var l = t.Legs ?? ""; bool b = l.Contains("BUY"), sl = l.Contains("SELL"); return b && sl ? "BUY + SELL" : b ? "BUY" : sl ? "SELL" : t.Dir > 0 ? "BUY" : t.Dir < 0 ? "SELL" : "?"; };
            double wins = tr.Where(t => t.Pnl > 0).Sum(t => t.Pnl), losses = -tr.Where(t => t.Pnl < 0).Sum(t => t.Pnl); int nw = tr.Count(t => t.Pnl > 0), nl = tr.Count(t => t.Pnl < 0);
            Func<string, string, SolidColorBrush, string, UIElement> tile = (k, v, br, sub) =>
            {
                var sp = new StackPanel(); sp.Children.Add(new TextBlock { Text = k, Foreground = Muted, FontSize = 10, FontWeight = FontWeights.Bold }); sp.Children.Add(new TextBlock { Text = v, Foreground = br, FontSize = 18, FontWeight = FontWeights.Bold, FontFamily = new FontFamily("Consolas") });
                if (sub != "") sp.Children.Add(new TextBlock { Text = sub, Foreground = Muted, FontSize = 10.5, TextWrapping = TextWrapping.Wrap, MaxWidth = 220 });
                return new Border { Background = Tint(br, 26), BorderBrush = br, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(10), Padding = new Thickness(12, 7, 12, 8), Margin = new Thickness(0, 0, 8, 8), MinWidth = 150, Child = sp };
            };
            double net = tr.Sum(t => t.Pnl); var tw = new WrapPanel { Margin = new Thickness(0, 0, 0, 8) }; root.Children.Add(tw);
            tw.Children.Add(tile("TRADES", tr.Count.ToString(), Cyan, nw + " won • " + nl + " lost • " + tr.Select(t => t.Day).Distinct().Count() + " days"));
            tw.Children.Add(tile("WIN RATE", (100.0 * nw / tr.Count).ToString("0") + "%", nw * 2 >= tr.Count ? Green : Gold, ""));
            tw.Children.Add(tile("TRADING P/L", Signed(net), net >= 0 ? Green : Red, "after the costs • " + Signed(net / tr.Count) + " a trade"));
            tw.Children.Add(tile("AVERAGE WIN / LOSS", Signed(nw == 0 ? 0 : wins / nw) + " / " + Signed(nl == 0 ? 0 : -losses / nl), Gold, "profit factor " + (losses <= 0 ? "∞" : (wins / losses).ToString("0.00"))));
            tw.Children.Add(tile("BEST / WORST TRADE", Signed(tr.Max(t => t.Pnl)) + " / " + Signed(tr.Min(t => t.Pnl)), Orchid, ""));
            tw.Children.Add(tile("AVERAGE HOLD", (tr.Average(t => (t.Exit - t.Entry).TotalMinutes)).ToString("0.0") + " min", Muted, ""));
            int accts = tr.Select(t => t.Account).Distinct().Count(); tw.Children.Add(tile("ACCOUNTS USED", accts.ToString(), Blue, (tr.Count / (double)Math.Max(1, accts)).ToString("0.0") + " trades each • " + (sim.PerSetup ? "one setup per account" : "shared setups")));
            Action<string, Func<KeystoneSimTrade, string>, Func<IEnumerable<IGrouping<string, KeystoneSimTrade>>, IEnumerable<IGrouping<string, KeystoneSimTrade>>>> group = (title, key, order) =>
            {
                var groups = order(tr.GroupBy(key)).ToList(); if (groups.Count == 0) return;
                root.Children.Add(new TextBlock { Text = title, Foreground = Gold, FontSize = 13.5, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 10, 0, 4) });
                var g = new Grid(); double[] cw = { 230, 70, 70, 80, 110, 100, 180 }; foreach (var c in cw) g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(c) });
                Action<int, int, string, Brush, bool> cell = (r, c, t, br, bold) => { while (g.RowDefinitions.Count <= r) g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); var tb = new TextBlock { Text = t, Foreground = br, FontSize = 12, FontFamily = new FontFamily(c == 0 ? "Segoe UI" : "Consolas"), FontWeight = bold ? FontWeights.Bold : FontWeights.Normal, Margin = new Thickness(0, 2, 0, 2), TextTrimming = TextTrimming.CharacterEllipsis }; Grid.SetRow(tb, r); Grid.SetColumn(tb, c); g.Children.Add(tb); };
                string[] hd = { "", "TRADES", "WON", "WIN %", "P/L", "PER TRADE", "" }; for (int c = 0; c < hd.Length; c++) cell(0, c, hd[c], Muted, true);
                double mx = groups.Max(x => Math.Abs(x.Sum(t => t.Pnl))); int r0 = 1;
                foreach (var x in groups)
                {
                    int n = x.Count(), w = x.Count(t => t.Pnl > 0); double pl = x.Sum(t => t.Pnl); Brush br = MoneyBrush(pl);
                    cell(r0, 0, x.Key, Text, true); cell(r0, 1, n.ToString(), Text, false); cell(r0, 2, w.ToString(), Text, false); cell(r0, 3, (100.0 * w / n).ToString("0") + "%", w * 2 >= n ? Green : Text, false); cell(r0, 4, Signed(pl), br, true); cell(r0, 5, Signed(pl / n), br, false);
                    var barB = new Border { Height = 10, Width = mx <= 0 ? 2 : Math.Max(2, 170 * Math.Abs(pl) / mx), Background = pl >= 0 ? Green : Red, CornerRadius = new CornerRadius(3), HorizontalAlignment = HorizontalAlignment.Left, VerticalAlignment = VerticalAlignment.Center };
                    Grid.SetRow(barB, r0); Grid.SetColumn(barB, 6); g.Children.Add(barB); r0++;
                }
                root.Children.Add(g);
            };
            Func<IEnumerable<IGrouping<string, KeystoneSimTrade>>, IEnumerable<IGrouping<string, KeystoneSimTrade>>> byPl = q => q.OrderByDescending(x => x.Sum(t => t.Pnl)), byKey = q => q.OrderBy(x => x.Key);
            group("BY INSTRUMENT", symOf, byPl);
            group("BY INSTRUMENT + SIDE", t => symOf(t) + " • " + sideOf(t), byPl);
            group("BY SESSION (NY, entry)", t => { int h = t.Entry.Hour * 100 + t.Entry.Minute; int si = KeystoneEntryIndicator.SessionOf(h); return KeystoneEntryIndicator.SessionName(si); }, byPl);
            group("BY HOUR (NY, entry)", t => t.Entry.ToString("HH") + ":00", q => q.OrderBy(x => (int.Parse(x.Key.Substring(0, 2)) + 6) % 24));
            group("BY WEEKDAY", t => t.Day.DayOfWeek.ToString().ToUpperInvariant(), q => q.OrderBy(x => (int)x.First().Day.DayOfWeek));
            group("BY EXIT", t => string.IsNullOrEmpty(t.Reason) ? "?" : t.Reason, byPl);
            group("BY PHASE", t => t.Phase == "" ? "?" : t.Phase, byKey);
            group("THE 10 BEST AND 10 WORST ACCOUNTS (trading P/L)", t => "A" + t.Account.ToString("00"), q => { var l = q.OrderByDescending(x => x.Sum(t => t.Pnl)).ToList(); return l.Count <= 20 ? l : l.Take(10).Concat(l.Skip(l.Count - 10)); });
            return new ScrollViewer { Content = root, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, MaxHeight = 900 };
        }
        // 🛑 LOSERS (PROP POOL): every losing trade's best open profit before it lost, how often losers had been well up, and the
        // breakeven math (every trade replayed with a breakeven step at +$100, +$200 … → losers saved vs winners cut → the best level)
        private UIElement PropLosersView(KeystonePropSim sim, Action<string> act)
        {
            var root = new StackPanel { Margin = new Thickness(12, 10, 12, 16) };
            root.Children.Add(new TextBlock { Text = "🛑 LOSERS • HOW FAR UP WAS EACH LOSER BEFORE IT LOST?", Foreground = Red, FontSize = 17, FontWeight = FontWeights.Bold });
            root.Children.Add(new TextBlock { Text = "Every losing trade with its best open profit (both legs, before the fees) before it turned into a loss. When many losers had been well up, a breakeven step (stop to + the fees once the trade is up +$X) turns them into ≈ $0 — but it also closes some winners that dip back before their target. 🧮 BREAKEVEN MATH replays every trade on its 1-minute bars with each level and counts both.", Foreground = Muted, FontSize = 12, TextWrapping = TextWrapping.Wrap, MaxWidth = 1050, Margin = new Thickness(0, 2, 0, 10) });
            bool mine = propBeFolder == sim.Folder && propLosers != null;
            var ls = mine ? propLosers.Select(l => Tuple.Create(l.Trade, l.Peak, l.Worst)).ToList() : sim.Trades.Where(t => t.Pnl < 0).Select(t => Tuple.Create(t, t.Peak, t.Worst)).ToList();
            var known = ls.Where(x => !double.IsNaN(x.Item2)).ToList(); int nAll = sim.Trades.Count, nLoss = sim.Trades.Count(t => t.Pnl < 0);
            Func<string, string, SolidColorBrush, string, UIElement> tile = (k, v, br, sub) =>
            {
                var sp = new StackPanel(); sp.Children.Add(new TextBlock { Text = k, Foreground = Muted, FontSize = 10, FontWeight = FontWeights.Bold }); sp.Children.Add(new TextBlock { Text = v, Foreground = br, FontSize = 18, FontWeight = FontWeights.Bold, FontFamily = new FontFamily("Consolas") });
                if (sub != "") sp.Children.Add(new TextBlock { Text = sub, Foreground = Muted, FontSize = 10.5, TextWrapping = TextWrapping.Wrap, MaxWidth = 220 });
                return new Border { Background = Tint(br, 26), BorderBrush = br, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(10), Padding = new Thickness(12, 7, 12, 8), Margin = new Thickness(0, 0, 8, 8), MinWidth = 160, Child = sp };
            };
            var tw = new WrapPanel { Margin = new Thickness(0, 0, 0, 6) }; root.Children.Add(tw);
            tw.Children.Add(tile("LOSING TRADES", nLoss.ToString(), Red, nAll == 0 ? "" : (100.0 * nLoss / nAll).ToString("0") + "% of " + nAll + " trades • " + sim.Trades.Count(t => t.Reason == "STOP") + " at the full stop"));
            if (known.Count > 0)
            {
                var pk = known.Select(x => x.Item2).OrderBy(x => x).ToList(); Func<double, int> up = v => known.Count(x => x.Item2 >= v);
                tw.Children.Add(tile("AVERAGE BEST BEFORE THE LOSS", Signed(pk.Average()), Green, "median " + Signed(pk[pk.Count / 2]) + " • best " + Signed(pk[pk.Count - 1])));
                tw.Children.Add(tile("WERE UP ≥ +$250", up(250) + " (" + (100.0 * up(250) / known.Count).ToString("0") + "%)", Gold, "of the losers"));
                tw.Children.Add(tile("WERE UP ≥ +$500", up(500) + " (" + (100.0 * up(500) / known.Count).ToString("0") + "%)", Gold, "of the losers"));
                tw.Children.Add(tile("WERE UP ≥ +$1,000", up(1000) + " (" + (100.0 * up(1000) / known.Count).ToString("0") + "%)", Orange, "of the losers"));
                // the buckets
                root.Children.Add(new TextBlock { Text = "THE LOSERS BY THEIR BEST OPEN PROFIT BEFORE THE LOSS" + (mine ? " (measured on the bars)" : known.Count < ls.Count ? " (" + known.Count + " of " + ls.Count + " recorded • 🧮 measures all)" : ""), Foreground = Gold, FontSize = 13, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 4, 0, 4) });
                double[] edges = { double.NegativeInfinity, 0.01, 100, 250, 500, 750, 1000, 1500, double.PositiveInfinity }; string[] names = { "never green", "+$0 – 100", "+$100 – 250", "+$250 – 500", "+$500 – 750", "+$750 – 1,000", "+$1,000 – 1,500", "+$1,500 and more" };
                var bars = new StackPanel(); int mx = 1; var counts = new int[names.Length];
                for (int i = 0; i < names.Length; i++) { counts[i] = known.Count(x => x.Item2 >= edges[i] && x.Item2 < edges[i + 1]); mx = Math.Max(mx, counts[i]); }
                for (int i = 0; i < names.Length; i++)
                {
                    var row = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 3) };
                    row.Children.Add(new TextBlock { Text = names[i], Width = 150, Foreground = Text, FontSize = 12, FontFamily = new FontFamily("Consolas") });
                    row.Children.Add(new Border { Width = 4 + 420.0 * counts[i] / mx, Height = 14, Background = i == 0 ? Red : i < 3 ? Orange : Green, CornerRadius = new CornerRadius(3), Margin = new Thickness(0, 0, 8, 0) });
                    row.Children.Add(new TextBlock { Text = counts[i] + " (" + (100.0 * counts[i] / known.Count).ToString("0") + "%)", Foreground = Muted, FontSize = 12, FontFamily = new FontFamily("Consolas") });
                    bars.Children.Add(row);
                }
                root.Children.Add(bars);
            }
            // 🧮 the breakeven math
            var go = Btn(propBeBusy != null ? "🧮 " + propBeBusy : "🧮 BREAKEVEN MATH • REPLAY EVERY TRADE WITH A BREAKEVEN AT +$100, +$200 …", Cyan); go.Height = 36; go.HorizontalAlignment = HorizontalAlignment.Left; go.Margin = new Thickness(0, 12, 0, 8); go.IsEnabled = propBeBusy == null && sim.Trades.Count > 0;
            go.Click += delegate { act("LOSERS|STUDY"); };
            if (sim.S.Strategy == "ROTATION") root.Children.Add(go);
            else root.Children.Add(new TextBlock { Text = "🧮 The breakeven replay uses the rotation's $ target / stop; for " + PropStrategyName(sim) + " each trade's best and worst open P/L are recorded as it trades (above) — the share of losers that were well up shows where a breakeven step would help.", Foreground = Muted, FontSize = 11.5, TextWrapping = TextWrapping.Wrap, MaxWidth = 1050, Margin = new Thickness(0, 10, 0, 8) });
            if (propBeFolder == sim.Folder && propBeRows != null && propBeRows.Count > 0)
            {
                var best = KeystoneBreakevenStudy.Best(propBeRows); var none = propBeRows[0];
                var banner = new Border { Background = Tint(best != null ? Green : Gold, 40), BorderBrush = best != null ? Green : Gold, BorderThickness = new Thickness(1.5), CornerRadius = new CornerRadius(10), Padding = new Thickness(12, 7, 12, 8), Margin = new Thickness(0, 0, 0, 8), HorizontalAlignment = HorizontalAlignment.Left };
                banner.Child = new TextBlock { Text = best == null ? "No breakeven level did better than none on these " + none.Trades + " trades (the winners it cut cost more than the losers it saved)." : "★ BEST: BREAKEVEN AT +$" + best.At.ToString("N0", CultureInfo.InvariantCulture) + " • saves " + best.Saved + " losers • cuts " + best.Cut + " winners • " + Signed(best.Change) + " on these " + none.Trades + " trades (" + Signed(none.Net) + " → " + Signed(best.Net) + ")", Foreground = System.Windows.Media.Brushes.White, FontSize = 13.5, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap, MaxWidth = 1000 };
                root.Children.Add(banner);
                if (best != null) { var use = Btn("▶ USE BREAKEVEN AT +$" + best.At.ToString("N0", CultureInfo.InvariantCulture) + " (this run from now on + the next runs)", Green); use.Height = 32; use.HorizontalAlignment = HorizontalAlignment.Left; use.Margin = new Thickness(0, 0, 0, 8); var at0 = best.At; use.Click += delegate { act("LOSERS|USE|" + at0.ToString(CultureInfo.InvariantCulture)); }; root.Children.Add(use); }
                var g = new Grid(); double[] cw = { 150, 80, 90, 120, 120, 120, 120 }; foreach (var c in cw) g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(c) });
                Action<int, int, string, Brush, bool> cell = (r, c, t, br, bold) => { while (g.RowDefinitions.Count <= r) g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); var tb = new TextBlock { Text = t, Foreground = br, FontSize = 12, FontFamily = new FontFamily("Consolas"), FontWeight = bold ? FontWeights.Bold : FontWeights.Normal, Margin = new Thickness(0, 2, 0, 2) }; Grid.SetRow(tb, r); Grid.SetColumn(tb, c); g.Children.Add(tb); };
                string[] hd = { "BREAKEVEN AT", "TRADES", "WON", "LOSERS SAVED", "WINNERS CUT", "NET", "VS NONE" }; for (int c = 0; c < hd.Length; c++) cell(0, c, hd[c], Muted, true);
                int ri = 1;
                foreach (var r in propBeRows)
                {
                    bool isBest = best != null && r == best; Brush br = isBest ? Green : r.At == 0 ? Gold : Text;
                    cell(ri, 0, (isBest ? "★ " : "") + (r.At == 0 ? "NONE (as traded)" : "+$" + r.At.ToString("N0", CultureInfo.InvariantCulture)), br, isBest); cell(ri, 1, r.Trades.ToString(), br, false); cell(ri, 2, (r.Trades == 0 ? 0 : 100.0 * r.Wins / r.Trades).ToString("0") + "%", br, false);
                    cell(ri, 3, r.At == 0 ? "" : r.Saved.ToString(), Green, false); cell(ri, 4, r.At == 0 ? "" : r.Cut.ToString(), Red, false); cell(ri, 5, Signed(r.Net), MoneyBrush(r.Net), isBest); cell(ri, 6, r.At == 0 ? "" : Signed(r.Change), MoneyBrush(r.Change), isBest); ri++;
                }
                root.Children.Add(g);
                root.Children.Add(new TextBlock { Text = "Replayed with this run's +$" + sim.S.RotTarget.ToString("N0", CultureInfo.InvariantCulture) + " / −$" + sim.S.RotStop.ToString("N0", CultureInfo.InvariantCulture) + " (funded +$" + sim.S.FundRotTarget.ToString("N0", CultureInfo.InvariantCulture) + " / −$" + sim.S.FundRotStop.ToString("N0", CultureInfo.InvariantCulture) + "), its contracts, hours and lock tiers • the stop first at the minute's worst • saved as breakeven_math.csv • history, not a promise: check the level again on new days.", Foreground = Muted, FontSize = 10.5, TextWrapping = TextWrapping.Wrap, MaxWidth = 1050, Margin = new Thickness(0, 6, 0, 10) });
            }
            // every loser
            root.Children.Add(new TextBlock { Text = "EVERY LOSER (newest first)", Foreground = Red, FontSize = 13, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 8, 0, 4) });
            var list = new StackPanel();
            foreach (var x in ls.OrderByDescending(x => x.Item1.Entry).Take(300))
            {
                var t = x.Item1; string pkS = double.IsNaN(x.Item2) ? "—" : Signed(x.Item2), wrS = double.IsNaN(x.Item3) ? "—" : Signed(x.Item3);
                list.Children.Add(new TextBlock { Text = t.Entry.ToString("yyyy-MM-dd HH:mm") + "  A" + t.Account.ToString("00") + " " + (t.Phase ?? "").PadRight(6) + " " + (t.Legs ?? "").PadRight(26) + " best " + pkS.PadLeft(8) + "  worst " + wrS.PadLeft(8) + "  net " + Signed(t.Pnl).PadLeft(8) + "  " + t.Reason, Foreground = !double.IsNaN(x.Item2) && x.Item2 >= 500 ? Gold : Text, FontSize = 11.5, FontFamily = new FontFamily("Consolas") });
            }
            if (ls.Count == 0) list.Children.Add(new TextBlock { Text = "No losing trade yet.", Foreground = Muted, FontSize = 12 });
            root.Children.Add(list);
            return new ScrollViewer { Content = root, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, MaxHeight = 900 };
        }
        // 📡 ENTRY INDICATOR (PROP POOL): build it from a training range, its rules, the proof on unseen days, use it, the AI review
        private UIElement PropIndicatorView(KeystonePropSim sim, Action<string> act)
        {
            var root = new StackPanel { Margin = new Thickness(12, 10, 12, 16) }; var ind = LoadPropIndicator();
            root.Children.Add(new TextBlock { Text = "📡 ENTRY INDICATOR • LEARNED FROM THE WINNERS", Foreground = Orchid, FontSize = 17, FontWeight = FontWeights.Bold });
            root.Children.Add(new TextBlock { Text = "A SETUP FORMS the minute MNQ / MGC turn into a new state (up / down over the last 5, 15 or 30 min); the indicator learns from those moments only and enters only the minute one with an edge forms — no pause in between; it rotates the accounts like the rotation (one trade a day per account by default).  1 BUILD: on the training days, at every setup all 4 sides (BUY/SELL MNQ × BUY/SELL MGC) are traded with this run's +target / −stop and contracts on 1-minute bars. For each market state (MNQ and MGC up / down over the last 5, 15 or 30 minutes, and the session when that helps) it keeps the sides that reached the target clearly more often than the coin flip — or WAIT. The window is chosen on the later half of the training days (learned on the earlier half), so even the choice is checked on days it did not learn from.  2 TEST it on this run's days (not the training days) against random sides.  3 USE it: SIDES = 📡 INDICATOR — AUTO, I TRADE and ⚡ FINISH DAY trade whatever it says.  4 ASK THE AI for an honest review.", Foreground = Muted, FontSize = 12, TextWrapping = TextWrapping.Wrap, MaxWidth = 1050, Margin = new Thickness(0, 2, 0, 10) });
            Func<string, string, SolidColorBrush, string, UIElement> tile = (k, v, br, sub) =>
            {
                var sp = new StackPanel(); sp.Children.Add(new TextBlock { Text = k, Foreground = Muted, FontSize = 10, FontWeight = FontWeights.Bold }); sp.Children.Add(new TextBlock { Text = v, Foreground = br, FontSize = 17, FontWeight = FontWeights.Bold, FontFamily = new FontFamily("Consolas") });
                if (sub != "") sp.Children.Add(new TextBlock { Text = sub, Foreground = Muted, FontSize = 10.5, TextWrapping = TextWrapping.Wrap, MaxWidth = 230 });
                return new Border { Background = Tint(br, 26), BorderBrush = br, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(10), Padding = new Thickness(12, 7, 12, 8), Margin = new Thickness(0, 0, 8, 8), MinWidth = 170, Child = sp };
            };
            // 1 BUILD
            DateTime runFrom = sim.Plan.Count > 0 ? sim.Plan[0] : sim.S.From;
            var build = new Border { Background = Card, CornerRadius = new CornerRadius(10), Padding = new Thickness(12, 8, 12, 10), Margin = new Thickness(0, 0, 0, 10) }; var bsp = new StackPanel(); build.Child = bsp;
            bsp.Children.Add(new TextBlock { Text = "1 • BUILD (training days — keep them BEFORE this run's days " + runFrom.ToString("yyyy-MM-dd") + ")", Foreground = Gold, FontSize = 13, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 6) });
            var row = new WrapPanel();
            Func<string, string, double, TextBox> field = (label, val, wdt) => { row.Children.Add(new TextBlock { Text = label, Foreground = Muted, FontSize = 10.5, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 5, 0) }); var tb = Input(val); tb.Width = wdt; tb.Height = 28; tb.Margin = new Thickness(0, 0, 14, 0); row.Children.Add(tb); return tb; };
            var fromB = field("TRAIN FROM", (ind != null ? ind.TrainFrom : runFrom.AddYears(-1)).ToString("yyyy-MM-dd"), 100);
            var toB = field("TO", (ind != null ? ind.TrainTo : runFrom.AddDays(-1)).ToString("yyyy-MM-dd"), 100);
            var stepB = field("CHECK EVERY (MIN)", ind != null ? ind.Step.ToString() : "1", 44); var minB = field("MIN TRADES / STATE", ind != null ? ind.MinTrades.ToString() : "30", 50); var edgeB = field("MIN EDGE (WIN % POINTS)", ind != null ? ind.MinEdge.ToString(CultureInfo.InvariantCulture) : "3", 44);
            bsp.Children.Add(row);
            var go = Btn(propIndicatorBusy != null ? "🎯 BUILDING… " + propIndicatorBusy : "🎯 BUILD THE INDICATOR", Orchid); go.Height = 36; go.MinWidth = 280; go.HorizontalAlignment = HorizontalAlignment.Left; go.Margin = new Thickness(0, 8, 0, 0); go.IsEnabled = propIndicatorBusy == null;
            go.Click += delegate { act("INDICATOR|BUILD|" + fromB.Text.Trim() + "|" + toB.Text.Trim() + "|" + stepB.Text.Trim() + "|" + minB.Text.Trim() + "|" + edgeB.Text.Trim()); };
            bsp.Children.Add(go);
            bsp.Children.Add(new TextBlock { Text = "Uses this run's +$" + sim.S.RotTarget.ToString("N0", CultureInfo.InvariantCulture) + " / −$" + sim.S.RotStop.ToString("N0", CultureInfo.InvariantCulture) + ", " + sim.S.MnqQty + " MNQ + " + sim.S.MgcQty + " MGC and " + KeystoneBracket.Hm(sim.S.StartHhmm) + "–" + KeystoneBracket.Hm(sim.S.EndHhmm) + " • the training days must be saved on this PC (MNQ + MGC minute bars) • saved as PropSim\\Indicator.txt (every build logged in IndicatorHistory.txt)", Foreground = Muted, FontSize = 11, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 6, 0, 0) });
            root.Children.Add(build);
            // the 📡 INDICATOR POOL: every finished test forms one from its days (and every BUILD) — choose which one trades
            var pool = PropIndicatorPool(); string chosenText = ind != null ? ind.ToText() : "";
            var pb = new Border { Background = Card, CornerRadius = new CornerRadius(10), Padding = new Thickness(12, 8, 12, 10), Margin = new Thickness(0, 0, 0, 10) }; var psp = new StackPanel(); pb.Child = psp; root.Children.Add(pb);
            psp.Children.Add(new TextBlock { Text = "📡 INDICATOR POOL • " + pool.Count + " formed (every finished test forms one from its days; the newest is chosen for the next runs)", Foreground = Orchid, FontSize = 13, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 6) });
            if (pool.Count == 0) psp.Children.Add(new TextBlock { Text = "Empty — finish a rotation test (5+ days) or BUILD one above.", Foreground = Muted, FontSize = 12 });
            foreach (var it in pool.Take(30))
            {
                var itx = it; bool chosen = it.Item2.ToText() == chosenText, here = sim.S.Indicator == it.Item2.ToText();
                var rowP = new DockPanel { Margin = new Thickness(0, 0, 0, 4) };
                var bThis = Btn(here ? "✔ THIS RUN" : "▶ USE IN THIS RUN", here ? Green : Card); bThis.Height = 26; bThis.FontSize = 10.5; bThis.Padding = new Thickness(8, 0, 8, 0); bThis.Margin = new Thickness(6, 0, 0, 0); DockPanel.SetDock(bThis, Dock.Right); bThis.Click += delegate { act("INDICATOR|CHOOSE|" + itx.Item1 + "|THIS"); };
                var bNext = Btn(chosen ? "★ NEXT RUNS" : "USE FOR NEXT RUNS", chosen ? Gold : Card); bNext.Height = 26; bNext.FontSize = 10.5; bNext.Padding = new Thickness(8, 0, 8, 0); bNext.Margin = new Thickness(6, 0, 0, 0); DockPanel.SetDock(bNext, Dock.Right); bNext.Click += delegate { act("INDICATOR|CHOOSE|" + itx.Item1); };
                rowP.Children.Add(bThis); rowP.Children.Add(bNext);
                rowP.Children.Add(new TextBlock { Text = PropIndicatorLabel(it.Item2) + " • last " + it.Item2.Window + " min" + (it.Item2.BySession ? " + session" : "") + " • later half " + it.Item2.HoldoutWin.ToString("0") + "% vs " + it.Item2.HoldoutBase.ToString("0") + "%", Foreground = it.Item2.HoldoutEdge ? Green : Muted, FontSize = 12, FontFamily = new FontFamily("Consolas"), VerticalAlignment = VerticalAlignment.Center, TextTrimming = TextTrimming.CharacterEllipsis });
                psp.Children.Add(rowP);
            }
            if (ind == null) { root.Children.Add(new TextBlock { Text = "No indicator yet — build one above.", Foreground = Muted, FontSize = 13 }); return new ScrollViewer { Content = root, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, MaxHeight = 900 }; }
            // the indicator
            bool overlap = sim.Days.Count > 0 && sim.Days.Min(d => d.Day) <= ind.TrainTo && sim.Days.Max(d => d.Day) >= ind.TrainFrom;
            var tw = new WrapPanel { Margin = new Thickness(0, 0, 0, 6) }; root.Children.Add(tw);
            tw.Children.Add(tile("TRAINED ON", ind.TrainFrom.ToString("yyyy-MM-dd") + " → " + ind.TrainTo.ToString("MM-dd"), Cyan, ind.Days + " days • " + ind.Samples + " moments × 4 sides"));
            tw.Children.Add(tile("READS", "last " + ind.Window + " min" + (ind.BySession ? " + session" : ""), Cyan, "MNQ and MGC up / down"));
            tw.Children.Add(tile("RULES", ind.Rules.Count.ToString(), ind.Rules.Count > 0 ? Green : Muted, "states with an edge (others = WAIT)"));
            tw.Children.Add(tile("COIN FLIP", ind.BaseWin.ToString("0.0") + "%", Muted, "all 4 sides' average win rate"));
            tw.Children.Add(tile("LATER-HALF CHECK", ind.HoldoutWin.ToString("0.0") + "%", ind.HoldoutEdge ? Green : Red, (ind.HoldoutEdge ? "EDGE" : "NO EDGE") + " • " + ind.HoldoutTrades + " trades vs " + ind.HoldoutBase.ToString("0.0") + "% coin flip"));
            // the rules
            root.Children.Add(new TextBlock { Text = "THE RULES (state → sides)", Foreground = Gold, FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 6, 0, 4) });
            var rt = new StackPanel();
            foreach (var r in ind.Rules)
            {
                double edge = r.WinPct - ind.BaseWin; var g = new Grid { Margin = new Thickness(0, 0, 0, 3) }; foreach (var c in new[] { 420.0, 260, 90, 90, 100, 110 }) g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(c) });
                var cells = new[] { KeystoneEntryIndicator.StateName(r.Key, ind.Window), KeystoneSimRotation.Arrows(r.DirM, r.DirG) + " " + KeystoneSimRotation.SidesName(r.DirM, r.DirG), r.Trades + " tr", r.WinPct.ToString("0.0") + "%", "+" + edge.ToString("0.0") + " pts", Signed(r.Pnl) };
                for (int c = 0; c < cells.Length; c++) { var tb = new TextBlock { Text = cells[c], Foreground = c == 1 ? Green : c == 4 ? Green : c == 5 ? MoneyBrush(r.Pnl) : Text, FontSize = 12.5, FontFamily = new FontFamily(c == 0 ? "Segoe UI" : "Consolas"), FontWeight = c == 1 ? FontWeights.Bold : FontWeights.Normal }; Grid.SetColumn(tb, c); g.Children.Add(tb); }
                rt.Children.Add(new Border { Background = Tint(Green, (byte)Math.Min(60, 10 + edge * 2)), CornerRadius = new CornerRadius(6), Padding = new Thickness(8, 4, 8, 4), Child = g, HorizontalAlignment = HorizontalAlignment.Left });
            }
            if (ind.Rules.Count == 0) rt.Children.Add(new TextBlock { Text = "No state beat the coin flip by " + ind.MinEdge.ToString("0.#") + " points with " + ind.MinTrades + "+ trades — the indicator would always WAIT. That is an honest answer: these days showed no edge for these sides.", Foreground = Gold, FontSize = 12, TextWrapping = TextWrapping.Wrap, MaxWidth = 1000 });
            root.Children.Add(rt);
            root.Children.Add(new TextBlock { Text = "choices checked on the later half: " + ind.Variants, Foreground = Muted, FontSize = 10.5, TextWrapping = TextWrapping.Wrap, MaxWidth = 1050, Margin = new Thickness(0, 4, 0, 10) });
            // 2 TEST + 3 USE
            var test = KeystoneSessionWhatIf.Load(sim.Folder, "indicator_test.txt"); var me = test.FirstOrDefault(x => x.Mine); var lucky = test.FirstOrDefault(x => x.Name.Contains("LUCKIEST")); var mid = test.FirstOrDefault(x => x.Name.Contains("MIDDLE"));
            var acts = new WrapPanel { Margin = new Thickness(0, 0, 0, 8) }; root.Children.Add(acts);
            var testB = Btn("⚖ 2 • TEST IT ON THIS RUN'S DAYS (vs random)", Cyan); testB.Height = 34; testB.Margin = new Thickness(0, 0, 8, 6); testB.IsEnabled = sim.Days.Count > 0 && propCompareBusy == null; testB.Click += delegate { act("COMPARE|INDICATOR"); }; acts.Children.Add(testB);
