                : kind == "ACCOUNTS" ? "The same " + sim.Days.Count + " days, strategy and rules with 50 / 40 / 30 / 20 / 10 / 5 accounts (budget = accounts × the evaluation price; new evaluations as your NEW EVALUATIONS rule says). ▶ = your count. 1ST PAYOUT / BREAKEVEN = trading days until the first payout / until the payouts have paid back all that was spent."
                : kind == "CHOICES" ? "The same " + sim.Days.Count + " days with your settings, against: funded traded like the evaluations • funded one trade a day • funded only after every evaluation is done (or together) • new evaluations at once (or only after breakeven). ▶ = your settings."
                : "The same " + sim.Days.Count + " days, accounts, contracts, $ target / stop and day plan (" + KeystoneSimSettings.DayPlanName(sim.S.DayPlan) + "), traded only inside each session and closed at its end. ▶ = your hours.";
            root.Children.Add(new TextBlock { Text = q, Foreground = Cyan, FontSize = 16, FontWeight = FontWeights.Bold });
            root.Children.Add(new TextBlock { Text = how + " On 1-minute bars: the stop first with both legs at their worst of the minute, targets at a minute's close, costs in. Click a row for all its numbers.", Foreground = Muted, FontSize = 12, TextWrapping = TextWrapping.Wrap, MaxWidth = 1000, Margin = new Thickness(0, 2, 0, 10) });
            if (rows.Count == 0)
            {
                var go = Btn(busy != null ? "⚖ COMPARING… " + busy : "⚖ RUN THE COMPARISON", Cyan); go.Height = 40; go.Width = 320; go.HorizontalAlignment = HorizontalAlignment.Left; go.IsEnabled = busy == null; go.Click += delegate { act("COMPARE|" + kind); };
                root.Children.Add(go); return root;
            }
            var win = KeystoneRotationLab.Winner(rows);
            var banner = new Border { Background = Tint(Green, 46), BorderBrush = Green, BorderThickness = new Thickness(1.5), CornerRadius = new CornerRadius(10), Padding = new Thickness(14, 8, 14, 9), Margin = new Thickness(0, 0, 0, 12), HorizontalAlignment = HorizontalAlignment.Left };
            banner.Child = new TextBlock { Text = "★ CLEAR WINNER: " + win.Name + "  •  net " + Signed(win.Net) + "  •  passed " + win.Passed + " of " + win.Bought + " (" + win.PassRate.ToString("0") + "%)  •  " + win.AtTarget + " account-days at the day target (" + win.AtTargetPct.ToString("0") + "%)", Foreground = System.Windows.Media.Brushes.White, FontSize = 14, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap, MaxWidth = 1000 };
            banner.BeginAnimation(UIElement.OpacityProperty, new DoubleAnimation(1, 0.6, TimeSpan.FromMilliseconds(800)) { AutoReverse = true, RepeatBehavior = RepeatBehavior.Forever });
            root.Children.Add(banner);
            double[] cw = { 300, 140, 115, 140, 70, 150, 110, 80, 95, 95 }; string[] hd = { kind == "ACCOUNTS" ? "ACCOUNTS" : kind == "CHOICES" ? "CHOICE" : kind == "INDICATOR" ? "SIDES" : "SESSION (NY)", "DAYS AT TARGET", "TRADES • WON", "PASSED", "BLOWN", "PAYOUTS", "NET", "ROI", "1ST PAYOUT", "BREAKEVEN" };
            Func<Grid> rowGrid = () => { var g = new Grid(); foreach (var c in cw) g.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(c) }); return g; };
            Action<Grid, int, string, Brush, double> cell = (g, c, t, br, fs) => { var tb = new TextBlock { Text = t, Foreground = br, FontSize = fs, FontWeight = FontWeights.Bold, FontFamily = c == 0 ? new FontFamily("Segoe UI") : new FontFamily("Consolas"), VerticalAlignment = VerticalAlignment.Center, TextTrimming = TextTrimming.CharacterEllipsis }; Grid.SetColumn(tb, c); g.Children.Add(tb); };
            var head = rowGrid(); head.Margin = new Thickness(10, 0, 10, 4); for (int c = 0; c < hd.Length; c++) cell(head, c, hd[c], Muted, 10.5); root.Children.Add(head);
            double best = rows.Max(r => r.Net);
            foreach (var x in rows)
            {
                var xx = x; bool isWin = x == win;
                var g = rowGrid(); g.Margin = new Thickness(10, 7, 10, 7);
                cell(g, 0, (x.Mine ? "▶ " : "") + x.Name + (isWin ? "  ★" : ""), isWin ? Green : x.Mine ? Gold : Text, 13);
                cell(g, 1, x.AtTarget + " / " + x.AcctDays + " (" + x.AtTargetPct.ToString("0") + "%)", x.AtTarget > 0 ? Green : Muted, 12.5);
                cell(g, 2, x.Trades + " • " + x.WinPct.ToString("0") + "%", Text, 12.5);
                cell(g, 3, x.Passed + " / " + x.Bought + " (" + x.PassRate.ToString("0") + "%)", x.Passed > 0 ? Green : Muted, 12.5);
                cell(g, 4, (x.BlownEval + x.BlownFunded).ToString(), x.BlownEval + x.BlownFunded > 0 ? Red : Muted, 12.5);
                cell(g, 5, x.Payouts + " • " + Cash(x.Cash), x.Payouts > 0 ? Green : Muted, 12.5);
                cell(g, 6, Signed(x.Net), MoneyBrush(x.Net), 13.5);
                cell(g, 7, x.Roi.ToString("0") + "%", MoneyBrush(x.Roi), 12.5);
                cell(g, 8, x.FirstPayoutDay > 0 ? "day " + x.FirstPayoutDay : "none", x.FirstPayoutDay > 0 ? Green : Muted, 12.5);
                cell(g, 9, x.BreakevenDay > 0 ? "day " + x.BreakevenDay : "not yet", x.BreakevenDay > 0 ? Green : Muted, 12.5);
                var layers = new Grid(); layers.Children.Add(g);
                if (isWin) { var glow = new Border { BorderBrush = Green, BorderThickness = new Thickness(2.5), CornerRadius = new CornerRadius(8), IsHitTestVisible = false }; layers.Children.Add(glow); glow.BeginAnimation(UIElement.OpacityProperty, new DoubleAnimation(1, 0.15, TimeSpan.FromMilliseconds(700)) { AutoReverse = true, RepeatBehavior = RepeatBehavior.Forever }); }
                var rowB = new Border { Background = isWin ? Tint(Green, 42) : x.Mine ? Tint(Gold, 22) : Card, CornerRadius = new CornerRadius(8), Margin = new Thickness(0, 0, 0, 4), Cursor = System.Windows.Input.Cursors.Hand, Child = layers, HorizontalAlignment = HorizontalAlignment.Left, ToolTip = "click = every number of this session" };
                var det = new StackPanel { Visibility = Visibility.Collapsed, Margin = new Thickness(14, 2, 14, 12) };
                rowB.MouseLeftButtonUp += delegate
                {
                    if (det.Visibility == Visibility.Visible) { det.Visibility = Visibility.Collapsed; return; }
                    det.Children.Clear(); det.Visibility = Visibility.Visible;
                    var facts = new WrapPanel();
                    Action<string, string, Brush> fact = (k, v, br) => { var sp = new StackPanel(); sp.Children.Add(new TextBlock { Text = k, Foreground = Muted, FontSize = 10, FontWeight = FontWeights.Bold }); sp.Children.Add(new TextBlock { Text = v, Foreground = br, FontSize = 15, FontWeight = FontWeights.Bold, FontFamily = new FontFamily("Consolas") }); facts.Children.Add(new Border { Background = Panel, CornerRadius = new CornerRadius(8), Padding = new Thickness(10, 5, 12, 6), Margin = new Thickness(0, 0, 8, 8), MinWidth = 150, Child = sp }); };
                    fact("HOURS (NY)", KeystoneBracket.Hm(xx.Start) + " – " + KeystoneBracket.Hm(xx.End), Cyan); fact("DAYS", xx.Days.ToString(), Text);
                    fact("ACCOUNT-DAYS TRADED", xx.AcctDays.ToString(), Text); fact("REACHED THE DAY TARGET", xx.AtTarget + " (" + xx.AtTargetPct.ToString("0") + "%)", xx.AtTarget > 0 ? Green : Muted);
                    fact("TRADES • WON", xx.Trades + " • " + xx.Wins + " (" + xx.WinPct.ToString("0") + "%)", Text); fact("TRADING P/L", Signed(xx.Pnl), MoneyBrush(xx.Pnl));
                    fact("BEST DAY", Signed(xx.BestDay), MoneyBrush(xx.BestDay)); fact("WORST DAY", Signed(xx.WorstDay), MoneyBrush(xx.WorstDay));
                    fact("EVALUATIONS BOUGHT", xx.Bought.ToString(), Text); fact("PASSED • RATE", xx.Passed + " • " + xx.PassRate.ToString("0") + "%", xx.Passed > 0 ? Green : Muted);
                    fact("BLOWN EVAL • FUNDED", xx.BlownEval + " • " + xx.BlownFunded, xx.BlownEval + xx.BlownFunded > 0 ? Red : Muted); fact("PAYOUTS • TO YOU", xx.Payouts + " • " + Cash(xx.Cash), xx.Payouts > 0 ? Green : Muted);
                    fact("SPENT", Cash(xx.Spent), Orange); fact("NET", Signed(xx.Net), MoneyBrush(xx.Net)); fact("DEEPEST DROP", Cash(xx.MaxDrop), xx.MaxDrop > 0 ? Red : Muted);
                    fact("AVERAGE DAYS TO PASS", xx.Passed > 0 ? xx.AvgPassDays.ToString("0.0", CultureInfo.InvariantCulture) : "—", Text);
                    fact("RETURN ON WHAT WAS SPENT", xx.Roi.ToString("0") + "%", MoneyBrush(xx.Roi)); fact("FIRST PAYOUT", xx.FirstPayoutDay > 0 ? "trading day " + xx.FirstPayoutDay : "none", xx.FirstPayoutDay > 0 ? Green : Muted); fact("BREAKEVEN (paid back)", xx.BreakevenDay > 0 ? "trading day " + xx.BreakevenDay : "not reached", xx.BreakevenDay > 0 ? Green : Muted);
                    det.Children.Add(facts);
                    if (xx.Curve.Count >= 2)
                    {
                        const double cvW = 760, cvH = 110; var cv = new System.Windows.Controls.Canvas { Width = cvW, Height = cvH, Background = Panel, HorizontalAlignment = HorizontalAlignment.Left, ClipToBounds = true };
                        double lo = Math.Min(0, xx.Curve.Min()), hi = Math.Max(0, xx.Curve.Max()); if (hi - lo < 1) hi = lo + 1; Func<double, double> yy = v => 6 + (hi - v) / (hi - lo) * (cvH - 12);
                        cv.Children.Add(new System.Windows.Shapes.Line { X1 = 0, X2 = cvW, Y1 = yy(0), Y2 = yy(0), Stroke = Muted, StrokeThickness = 1, StrokeDashArray = new DoubleCollection { 3, 3 } });
                        var pl = new System.Windows.Shapes.Polyline { Stroke = xx.Net >= 0 ? Green : Red, StrokeThickness = 2 };
                        for (int i = 0; i < xx.Curve.Count; i++) pl.Points.Add(new System.Windows.Point(4 + (cvW - 8) * i / (xx.Curve.Count - 1), yy(xx.Curve[i])));
                        cv.Children.Add(pl); det.Children.Add(new TextBlock { Text = "NET MONEY DAY BY DAY (payouts − evaluations)", Foreground = Muted, FontSize = 10, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 3) }); det.Children.Add(cv);
                    }
                };
                root.Children.Add(rowB); root.Children.Add(det);
            }
            var again = Btn(busy != null ? "⚖ COMPARING… " + busy : "↻ COMPARE AGAIN", Card); again.Height = 30; again.HorizontalAlignment = HorizontalAlignment.Left; again.Margin = new Thickness(0, 10, 0, 0); again.IsEnabled = busy == null; again.Click += delegate { act("COMPARE|" + kind); };
            root.Children.Add(again);
            root.Children.Add(new TextBlock { Text = "Saved with the run (sessions.txt) • 📄 EXPORT HTML puts this table in the report • a what-if on history, not a promise.", Foreground = Muted, FontSize = 11, Margin = new Thickness(0, 8, 0, 0), TextWrapping = TextWrapping.Wrap });
            return new ScrollViewer { Content = root, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, HorizontalScrollBarVisibility = ScrollBarVisibility.Auto, MaxHeight = 900 };
        }

        // ---- INSTRUMENTS (the + tab): NinjaTrader's instrument list; added instruments kept in Studio\Instruments.txt --------
        private static string InstrumentsFile() { return Path.Combine(StudioFolder(), "Instruments.txt"); }
        private static void LoadStudioInstruments() { try { if (File.Exists(InstrumentsFile())) foreach (var s in KeystoneSymbols.Parse(File.ReadAllText(InstrumentsFile()))) KeystoneSymbols.Register(s); } catch { } }
        private static void SaveStudioInstruments() { try { Directory.CreateDirectory(StudioFolder()); File.WriteAllText(InstrumentsFile(), KeystoneSymbols.Serialize(KeystoneSymbols.All())); } catch { } }
        private static int FullDayOf(string sym) { var sp = KeystoneSymbols.Get(sym); return sp != null ? sp.FullDayMinutes : FullDayMinutes; }
        private static bool IsFuturesSymbol(string sym) { var sp = KeystoneSymbols.Get(sym); return sp == null || sp.Futures; }
        // MNQ / MGC and added futures: the dated contract of the date (as before) • an added forex / stock / CFD symbol: itself
        private Instrument ResolveStudioInstrument(string sym, DateTime date, out string source)
        {
            var sp = KeystoneSymbols.Get(sym);
            if (sp != null && !sp.Futures) { var i = SafeGetInstrument(sym); source = i != null ? "INSTRUMENT • " + i.FullName : "NOT FOUND IN NINJATRADER • " + sym; return i; }
            return ResolveDynamicInstrument(sym, date, out source);
        }
        // every instrument in NinjaTrader's database (Tools → Instruments). Read by reflection: no compile dependency on the list.
        private static List<KeystoneSymbolSpec> NinjaInstrumentCatalog(out string note)
        {
            var list = new List<KeystoneSymbolSpec>(); note = string.Empty; var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            try
            {
                var flags = System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static;
                Func<Type, object> allOf = t => { var p = t.GetProperty("All", flags); if (p != null) return p.GetValue(null, null); var f = t.GetField("All", flags); return f == null ? null : f.GetValue(null); };
                var items = new List<object>();
                foreach (var src in new[] { allOf(typeof(MasterInstrument)), allOf(typeof(Instrument)) })
                {
                    var en = src as IEnumerable; if (en == null) continue;
                    try { lock (en) foreach (object o in en) items.Add(o); } catch { try { foreach (object o in en) items.Add(o); } catch { } }
                }
                foreach (object o in items)
                {
                    object mi = o is MasterInstrument ? o : ReflectionValue(o, "MasterInstrument"); if (mi == null) continue;
                    string name = Convert.ToString(ReflectionValue(mi, "Name")); if (string.IsNullOrWhiteSpace(name) || KeystoneSymbols.Builtin(name) || !seen.Add(name)) continue;
                    double pv = 0, tk = 0; try { pv = Convert.ToDouble(ReflectionValue(mi, "PointValue"), CultureInfo.InvariantCulture); tk = Convert.ToDouble(ReflectionValue(mi, "TickSize"), CultureInfo.InvariantCulture); } catch { }
                    if (pv <= 0 || tk <= 0) continue;
                    string type = KeystoneSymbols.TypeName(Convert.ToString(ReflectionValue(mi, "InstrumentType")));
                    list.Add(new KeystoneSymbolSpec { Symbol = name.Trim().ToUpperInvariant(), Name = Convert.ToString(ReflectionValue(mi, "Description")) ?? string.Empty, Type = type, PointValue = pv, TickSize = tk, Commission = KeystoneSymbols.DefaultCommission(type, pv), FullDayMinutes = KeystoneSymbols.DefaultFullDay(type) });
                }
                if (list.Count == 0) note = "NinjaTrader's instrument list could not be read here — type the symbol below (exactly as NinjaTrader names it, e.g. ES, CL, 6E, EURUSD, AAPL).";
            }
            catch (Exception ex) { note = "Could not read NinjaTrader's instrument list (" + ex.Message + ") — type the symbol below."; }
            return list.OrderBy(x => x.Type == "FUTURE" ? 0 : 1).ThenBy(x => x.Symbol).ToList();
        }
        // one symbol typed by hand: NinjaTrader's master instrument for it (null = unknown)
        private static KeystoneSymbolSpec NinjaInstrumentSpec(string sym)
        {
            sym = (sym ?? string.Empty).Trim().ToUpperInvariant(); if (sym == string.Empty) return null;
            var inst = SafeGetInstrument(sym); object mi = inst == null ? null : ReflectionValue(inst, "MasterInstrument"); if (mi == null) return null;
            double pv = 0, tk = 0; try { pv = Convert.ToDouble(ReflectionValue(mi, "PointValue"), CultureInfo.InvariantCulture); tk = Convert.ToDouble(ReflectionValue(mi, "TickSize"), CultureInfo.InvariantCulture); } catch { }
            if (pv <= 0 || tk <= 0) return null; string type = KeystoneSymbols.TypeName(Convert.ToString(ReflectionValue(mi, "InstrumentType")));
            string root = Convert.ToString(ReflectionValue(mi, "Name")); if (!string.IsNullOrWhiteSpace(root)) sym = root.Trim().ToUpperInvariant();
            return new KeystoneSymbolSpec { Symbol = sym, Name = Convert.ToString(ReflectionValue(mi, "Description")) ?? string.Empty, Type = type, PointValue = pv, TickSize = tk, Commission = KeystoneSymbols.DefaultCommission(type, pv), FullDayMinutes = KeystoneSymbols.DefaultFullDay(type) };
        }
        // loads a symbol's days into the studio store: joins the running download queue, or starts it (newest week first)
        private int QueueStudioDownload(Dispatcher d, string sym, DateTime from, DateTime to)
        {
            int skipped;
            if (!dlBusy) return StartStudioDownload(d, new[] { sym }, new List<Tuple<DateTime, DateTime>> { Tuple.Create(from, to) }, true, out skipped);
            int n = 0; foreach (var wk in KeystoneStudioStore.Weeks(from, to).OrderByDescending(x => x.Item1)) { dlQueue.Add(Tuple.Create(sym, wk.Item1, wk.Item2, 0)); n++; }
            dlTotal += n; DlNotify("ADDED • " + sym + " • " + n + " weeks after the current download", Cyan); return n;
        }

