                    return HelixRow(new[] { t.Session.ToString("yyyy-MM-dd"), t.Symbol, t.Side, t.Qty.ToString(), t.EntryTime.ToString("HH:mm:ss"), t.Entry.ToString("0.##", CultureInfo.InvariantCulture), t.ExitTime.ToString("HH:mm:ss"), t.Exit.ToString("0.##", CultureInfo.InvariantCulture), t.Points.ToString("+0.##;−0.##;0", CultureInfo.InvariantCulture), Signed(t.Net), cut(t.Reason), t.How, cut(t.Strategy) },
                        new Brush[] { Text, Cyan, t.Side == "BUY" ? Green : Red, Text, Muted, Text, Muted, Text, MoneyBrush(t.Points), MoneyBrush(t.Net), Muted, t.How == "I TRADE" ? Orange : Cyan, Muted }, wd, MoneyBrush(t.Net), null);
                }, 60, false));
            };
            Action render = null;
            Action<DateTime> showDay = d =>
            {
                daysP.Children.Clear(); var ts = shown.Where(t => t.Session == d).ToList(); var r = KeystoneManualPool.Sum(d.ToString("yyyy-MM-dd ddd", CultureInfo.InvariantCulture), ts);
                var back = Btn("◀ ALL DAYS", Card); back.Height = 28; back.HorizontalAlignment = HorizontalAlignment.Left; back.Click += delegate { render(); }; daysP.Children.Add(back);
                daysP.Children.Add(new TextBlock { Text = r.Name + " • " + r.Trades + " trades • " + r.Won + " won (" + r.WinPct.ToString("0") + "%) • " + Signed(r.Net), Foreground = MoneyBrush(r.Net), FontSize = 18, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 8, 0, 4) });
                table(daysP, "BY INSTRUMENT", KeystoneManualPool.By(ts, "INSTRUMENT"));
                daysP.Children.Add(new TextBlock { Text = "THE TRADES", Foreground = Gold, FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 12, 0, 4) }); tradeRows(daysP, ts, false);
            };
            render = delegate
            {
                string sm = Convert.ToString(symF.SelectedItem ?? "ALL INSTRUMENTS");
                filling = true; symF.Items.Clear(); symF.Items.Add("ALL INSTRUMENTS"); foreach (var s0 in all.Select(t => t.Symbol).Distinct().OrderBy(x => x)) symF.Items.Add(s0); int si0 = symF.Items.IndexOf(sm); symF.SelectedIndex = si0 < 0 ? 0 : si0; filling = false;
                string md = modeF.SelectedIndex <= 0 ? "ALL" : Convert.ToString(modeF.SelectedItem ?? "ALL"), hw = howF.SelectedIndex <= 0 ? "ALL" : Convert.ToString(howF.SelectedItem ?? "ALL"); sm = symF.SelectedIndex <= 0 ? "ALL" : Convert.ToString(symF.SelectedItem ?? "ALL");
                DateTime fd, td; bool hasF = DateTime.TryParseExact(fromF.Text.Trim(), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out fd), hasT = DateTime.TryParseExact(toF.Text.Trim(), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out td);
                shown = all.Where(t => (md.StartsWith("ALL") || t.Mode == md) && (sm.StartsWith("ALL") || t.Symbol == sm) && (hw.StartsWith("ALL") || t.How == hw) && (!hasF || t.Session >= fd) && (!hasT || t.Session <= td)).ToList();
                foreach (var p in new[] { overview, daysP, tradesP, byP, aiP }) p.Children.Clear();
                var a = KeystoneManualPool.Sum("ALL", shown); var st = KeystoneManualPool.Streaks(shown); var days = KeystoneManualPool.Days(shown);
                if (shown.Count == 0)
                {
                    var none = all.Count == 0 ? "No trades saved yet. Trade a replayed day (✋ I TRADE or ⚡ AUTO) — every closed trade lands here by itself." : "No trades match the filters (" + all.Count + " saved in all).";
                    foreach (var p in new[] { overview, daysP, tradesP, byP }) p.Children.Add(new TextBlock { Text = none, Foreground = Muted, FontSize = 13 });
                }
                else
                {
                    // OVERVIEW
                    var cards = new WrapPanel(); overview.Children.Add(cards);
                    int green = days.Count(d => d.Item2.Net > 0);
                    CycleMetric(cards, "NET", Signed(a.Net), MoneyBrush(a.Net)); CycleMetric(cards, "TRADES", a.Trades + " in " + a.Days + " days", Cyan); CycleMetric(cards, "WON", a.WinPct.ToString("0") + "% (" + a.Won + ")", a.WinPct >= 50 ? Green : Orange);
                    CycleMetric(cards, "GREEN DAYS", green + " of " + days.Count, green * 2 >= days.Count ? Green : Orange); CycleMetric(cards, "AVG WIN / LOSS", Cash(a.AvgWin) + " / " + Cash(-a.AvgLoss), Text); CycleMetric(cards, "PROFIT FACTOR", a.Pf >= 99 ? "∞" : a.Pf.ToString("0.00"), a.Pf >= 1 ? Green : Red);
                    CycleMetric(cards, "MAX DRAWDOWN", Cash(-KeystoneManualPool.MaxDrawdown(shown)), Red); CycleMetric(cards, "RUNS (TRADES)", st[0] + " wins • " + st[1] + " losses", Text); CycleMetric(cards, "RUNS (DAYS)", st[2] + " green • " + st[3] + " red", Text);
                    if (days.Count > 0) { var bd = days.OrderByDescending(d => d.Item2.Net).First(); var wd0 = days.OrderBy(d => d.Item2.Net).First(); CycleMetric(cards, "BEST DAY", bd.Item1.ToString("yyyy-MM-dd") + " " + Signed(bd.Item2.Net), Green); CycleMetric(cards, "WORST DAY", wd0.Item1.ToString("yyyy-MM-dd") + " " + Signed(wd0.Item2.Net), Red); }
                    table(overview, "BY INSTRUMENT", KeystoneManualPool.By(shown, "INSTRUMENT")); table(overview, "✋ I TRADE vs ⚡ AUTO", KeystoneManualPool.By(shown, "HOW")); table(overview, "BY MODE", KeystoneManualPool.By(shown, "MODE"));
                    overview.Children.Add(new TextBlock { Text = "THE LAST 10 DAYS", Foreground = Gold, FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 12, 0, 4) });
                    var wdD = new double[] { 150, 70, 80, 110, 420 };
                    overview.Children.Add(HelixHeader(new[] { "DAY", "TRADES", "WON", "NET", "INSTRUMENTS" }, wdD));
                    foreach (var d in days.Take(10)) { var d0 = d.Item1; var rr = HelixRow(new[] { d.Item2.Name, d.Item2.Trades.ToString(), d.Item2.WinPct.ToString("0") + "%", Signed(d.Item2.Net), d.Item3 }, new Brush[] { Text, Text, Text, MoneyBrush(d.Item2.Net), Muted }, wdD, MoneyBrush(d.Item2.Net), () => { tabs.SelectedIndex = 1; showDay(d0); }); rr.ToolTip = "Click: this day's trades"; overview.Children.Add(rr); }
                    // EVERY DAY
                    daysP.Children.Add(new TextBlock { Text = days.Count + " DAYS • click a day for its trades", Foreground = Gold, FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 4) });
                    var wdA = new double[] { 150, 70, 80, 110, 100, 100, 420 };
                    daysP.Children.Add(HelixPaged(new[] { "DAY", "TRADES", "WON", "NET", "BEST", "WORST", "INSTRUMENTS" }, wdA, days.Count, i =>
                    {
                        var d = days[i]; var d0 = d.Item1;
                        var rr = HelixRow(new[] { d.Item2.Name, d.Item2.Trades.ToString(), d.Item2.WinPct.ToString("0") + "%", Signed(d.Item2.Net), Signed(d.Item2.Best), Signed(d.Item2.Worst), d.Item3 }, new Brush[] { Text, Text, Text, MoneyBrush(d.Item2.Net), Green, Red, Muted }, wdA, MoneyBrush(d.Item2.Net), () => showDay(d0));
                        rr.ToolTip = "Click: this day's trades"; return rr;
                    }, 60, false));
                    // EVERY TRADE (newest first)
                    tradesP.Children.Add(new TextBlock { Text = shown.Count + " TRADES • newest first", Foreground = Gold, FontSize = 14, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 0, 0, 4) }); tradeRows(tradesP, shown, true);
                    // BREAKDOWNS
                    byP.Children.Add(new TextBlock { Text = "What works for me: the same trades cut every way. Green rows make money; under 20 trades a row is a hint, not a finding.", Foreground = Muted, FontSize = 12, TextWrapping = TextWrapping.Wrap });
                    foreach (var v in KeystoneManualPool.Views) table(byP, "BY " + v, KeystoneManualPool.By(shown, v));
                }
                // AI
                aiP.Children.Add(new TextBlock { Text = "🤖 The AI reads these " + shown.Count + " trades (the filters apply) and names my patterns: what wins, what loses, what to stop, one rule to test next.", Foreground = Text, FontSize = 13, TextWrapping = TextWrapping.Wrap });
                var aiRow = new WrapPanel { Margin = new Thickness(0, 8, 0, 8) }; var planBtn = Btn("🤖 FIND MY PATTERNS • MY CLAUDE PLAN", Orchid); var apiBtn = Btn("… WITH MY API KEY", Card); planBtn.Height = apiBtn.Height = 32; aiRow.Children.Add(planBtn); aiRow.Children.Add(apiBtn); aiP.Children.Add(aiRow);
                if (aiBusy) aiP.Children.Add(new TextBlock { Text = "the AI is reading your trades…", Foreground = Cyan, FontSize = 13 });
                else if (aiText != null) aiP.Children.Add(new TextBox { Text = aiText, Foreground = Text, Background = Panel, BorderBrush = Card, FontSize = 13, TextWrapping = TextWrapping.Wrap, IsReadOnly = true, Padding = new Thickness(10) });
                Action<bool> ask = viaPlan =>
                {
                    if (aiBusy) return; if (shown.Count == 0) { aiText = "⚠ no trades to read"; render(); return; }
                    string key = viaPlan ? "" : AiKey(); if (!viaPlan && key == "") { aiText = "⚠ no API key: set ANTHROPIC_API_KEY or save it in the AI COACH — or use MY CLAUDE PLAN"; render(); return; }
                    string prompt = KeystoneManualPool.AiPrompt(shown); aiBusy = true; render(); var disp = w.Dispatcher;
                    System.Threading.ThreadPool.QueueUserWorkItem(delegate
                    {
                        var ans = AiAsk(KeystoneManualPool.AiSystem, prompt, viaPlan, key);
                        string txt = ans.Ok ? DateTime.Now.ToString("yyyy-MM-dd HH:mm") + " • " + shown.Count + " trades\n" + ans.Text : "⚠ " + ans.Error;
                        if (ans.Ok) { try { File.WriteAllText(Path.Combine(StudioFolder(), "ai_my_trades.txt"), txt); } catch { } }
                        Action done = delegate { aiBusy = false; aiText = txt; if (manualPoolWindow != null) render(); };
                        if (disp != null) disp.BeginInvoke(done); else done();
                    });
                };
                planBtn.Click += delegate { ask(true); }; apiBtn.Click += delegate { ask(false); };
            };
            Action reload = delegate { all = KeystoneManualPool.Load(StudioTradesFile(), ReplayJournalFile()); render(); };
            refreshBtn.Click += delegate { reload(); }; folderBtn.Click += delegate { try { Directory.CreateDirectory(StudioFolder()); System.Diagnostics.Process.Start("explorer.exe", StudioFolder()); } catch { } };
            modeF.SelectionChanged += delegate { render(); }; howF.SelectionChanged += delegate { render(); }; symF.SelectionChanged += delegate { if (!filling) render(); };
            fromF.LostFocus += delegate { render(); }; toF.LostFocus += delegate { render(); };
            reload(); w.Show();
        }

        private void OpenReportsWindow()
