            var importBtn = Btn("IMPORT REPORT FILE…", Cyan); importBtn.Height = 32; var folderBtn = Btn("OPEN FOLDER", Card); folderBtn.Height = 28; var refreshBtn = Btn("REFRESH", Card); refreshBtn.Height = 28;
            left.Children.Add(importBtn); var lb2 = new WrapPanel(); lb2.Children.Add(folderBtn); lb2.Children.Add(refreshBtn); left.Children.Add(lb2);
            var list = new ListBox { Background = Panel, Foreground = Text, BorderBrush = Card, Height = 560, Margin = new Thickness(0, 8, 0, 0) };
            left.Children.Add(list);
            var status = new TextBlock { Text = "", Foreground = Muted, FontSize = 11, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 8, 0, 0) }; left.Children.Add(status);
            Grid.SetColumn(left, 0); root.Children.Add(left);
            // right: the report
            var tabs = new TabControl { Background = Panel, BorderBrush = Card };
            var overview = new StackPanel { Margin = new Thickness(14) }; var tables = new StackPanel { Margin = new Thickness(14) };
            var daysGrid = new Grid { Margin = new Thickness(10) };
            tabs.Items.Add(new TabItem { Header = "OVERVIEW", Content = new ScrollViewer { Content = overview, VerticalScrollBarVisibility = ScrollBarVisibility.Auto } });
            tabs.Items.Add(new TabItem { Header = "TABLES", Content = new ScrollViewer { Content = tables, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, HorizontalScrollBarVisibility = ScrollBarVisibility.Auto } });
            tabs.Items.Add(new TabItem { Header = "EVERY DAY (LABELLED)", Content = daysGrid });
            Grid.SetColumn(tabs, 1); root.Children.Add(tabs);
            // days tab: filter + list + detail + open on chart
            daysGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto }); daysGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            daysGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) }); daysGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(420) });
            var filterBar = new WrapPanel { Margin = new Thickness(0, 0, 0, 6) };
            var findBox = Input(""); findBox.Width = 220; findBox.ToolTip = "Filter: any text of the label or note (e.g. BEAR, STRAIGHT UP, REVERSED, 2024-05)";
            var labelBox = Select("ALL DAYS"); labelBox.Width = 300;
            var countText = new TextBlock { Foreground = Muted, FontSize = 11, Margin = new Thickness(8, 6, 0, 0) };
            filterBar.Children.Add(new TextBlock { Text = "FIND", Foreground = Muted, FontSize = 11, Margin = new Thickness(0, 6, 6, 0) }); filterBar.Children.Add(findBox); filterBar.Children.Add(labelBox); filterBar.Children.Add(countText);
            Grid.SetRow(filterBar, 0); Grid.SetColumnSpan(filterBar, 2); daysGrid.Children.Add(filterBar);
            var dayList = new ListBox { Background = Panel, Foreground = Text, BorderBrush = Card }; Grid.SetRow(dayList, 1); daysGrid.Children.Add(dayList);
            var detail = new StackPanel { Margin = new Thickness(10, 0, 0, 0) };
            var detailText = new TextBlock { Foreground = Text, FontSize = 12, TextWrapping = TextWrapping.Wrap };
            var openBtn = Btn("OPEN THIS DAY ON THE CHART", Green); openBtn.Height = 34; openBtn.Margin = new Thickness(0, 10, 0, 0); openBtn.ToolTip = "Opens the BACKTEST STUDIO on this day (start 5 minutes before the first label). Press ▶ PLAY: the report's labels and trades appear as the replay reaches them.";
            detail.Children.Add(detailText); detail.Children.Add(openBtn);
            var detailScroll = new ScrollViewer { Content = detail, VerticalScrollBarVisibility = ScrollBarVisibility.Auto }; Grid.SetRow(detailScroll, 1); Grid.SetColumn(detailScroll, 1); daysGrid.Children.Add(detailScroll);
            w.Content = root; FitToScreen(w);

            KeystoneReport current = null; var shown = new List<KeystoneReport.Day>();
            Func<string, Brush> cellBrush = t => t.StartsWith("+") ? Green : (t.StartsWith("-") || t.StartsWith("−")) ? Red : Text;
            Func<string, Brush> dayBrush = c => c == "green" ? Green : c == "red" ? Red : c == "orange" ? Orange : c == "blue" ? Blue : Muted;
            Action fillDays = delegate
            {
                dayList.Items.Clear(); shown.Clear(); if (current == null) return;
                string f = findBox.Text.Trim(); string lab = Convert.ToString(labelBox.SelectedItem ?? "ALL DAYS");
                foreach (var d in current.Days)
                {
                    string all = d.Date.ToString("yyyy-MM-dd ddd", CultureInfo.InvariantCulture) + " " + d.Label + " " + d.Note;
                    if (f != "" && all.IndexOf(f, StringComparison.OrdinalIgnoreCase) < 0) continue;
                    if (lab != "ALL DAYS" && !d.Label.StartsWith(lab.Split('(')[0].Trim(), StringComparison.Ordinal) && d.Label.IndexOf(lab.Split('(')[0].Trim(), StringComparison.Ordinal) < 0) continue;
                    shown.Add(d);
                    dayList.Items.Add(new TextBlock { Text = d.Date.ToString("yyyy-MM-dd ddd", CultureInfo.InvariantCulture) + "   " + d.Label, Foreground = dayBrush(d.Color), FontSize = 12 });
                }
                countText.Text = shown.Count + " of " + current.Days.Count + " days";
            };
            Action show = delegate
            {
                overview.Children.Clear(); tables.Children.Clear(); labelBox.Items.Clear(); labelBox.Items.Add("ALL DAYS"); labelBox.SelectedIndex = 0; detailText.Text = "";
                if (current == null) { overview.Children.Add(Txt("IMPORT A REPORT (left) OR PICK ONE FROM THE LIST", Muted, 16, FontWeights.Bold)); fillDays(); return; }
                overview.Children.Add(Txt(current.Title, Gold, 26, FontWeights.Bold));
                overview.Children.Add(new TextBlock { Text = current.Subtitle + (current.Generated != "" ? " • made " + current.Generated : ""), Foreground = Muted, FontSize = 12.5, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 12) });
                var cards = new WrapPanel();
                foreach (var sm in current.Summary)
                {
                    var c = new StackPanel(); c.Children.Add(new TextBlock { Text = sm[0].ToUpperInvariant(), Foreground = Muted, FontSize = 10.5, FontWeight = FontWeights.Bold });
                    c.Children.Add(new TextBlock { Text = sm[1], Foreground = Text, FontSize = 19, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap });
                    if (sm[2] != "") c.Children.Add(new TextBlock { Text = sm[2], Foreground = Muted, FontSize = 11, TextWrapping = TextWrapping.Wrap });
                    cards.Children.Add(new Border { Background = Card, CornerRadius = new CornerRadius(6), Padding = new Thickness(12, 8, 12, 8), Margin = new Thickness(0, 0, 10, 10), Width = 300, Child = c });
                }
                overview.Children.Add(cards);
                if (current.Method != "") { overview.Children.Add(Txt("HOW IT WAS MEASURED", Cyan, 12, FontWeights.Bold)); overview.Children.Add(new TextBlock { Text = current.Method, Foreground = Text, FontSize = 12, TextWrapping = TextWrapping.Wrap, MaxWidth = 900, HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(0, 4, 0, 0) }); }
                foreach (var sec in current.Sections)
                {
                    tables.Children.Add(Txt(sec.Title, Gold, 15, FontWeights.Bold));
                    if (sec.Note != "") tables.Children.Add(new TextBlock { Text = sec.Note, Foreground = Muted, FontSize = 11, TextWrapping = TextWrapping.Wrap, MaxWidth = 1000, HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(0, 2, 0, 6) });
                    var g = new Grid { Margin = new Thickness(0, 0, 0, 18), HorizontalAlignment = HorizontalAlignment.Left };
                    for (int ci = 0; ci < sec.Columns.Count; ci++) g.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                    for (int ri = 0; ri <= sec.Rows.Count; ri++) g.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                    for (int ci = 0; ci < sec.Columns.Count; ci++)
                    {
                        var hd = new Border { Background = Card, Padding = new Thickness(8, 4, 8, 4), Child = new TextBlock { Text = sec.Columns[ci].ToUpperInvariant(), Foreground = Muted, FontSize = 10.5, FontWeight = FontWeights.Bold, MaxWidth = ci == 0 ? 420 : 140, TextWrapping = TextWrapping.Wrap } };
                        Grid.SetRow(hd, 0); Grid.SetColumn(hd, ci); g.Children.Add(hd);
                    }
                    for (int ri = 0; ri < sec.Rows.Count; ri++)
                        for (int ci = 0; ci < Math.Min(sec.Columns.Count, sec.Rows[ri].Count); ci++)
                        {
                            string t = sec.Rows[ri][ci];
                            var cell = new Border { Background = ri % 2 == 0 ? Panel : Bg, Padding = new Thickness(8, 3, 8, 3), Child = new TextBlock { Text = t, Foreground = ci == 0 ? Text : cellBrush(t), FontSize = 12, MaxWidth = ci == 0 ? 420 : 140, TextWrapping = TextWrapping.Wrap, HorizontalAlignment = ci == 0 ? HorizontalAlignment.Left : HorizontalAlignment.Right } };
                            Grid.SetRow(cell, ri + 1); Grid.SetColumn(cell, ci); g.Children.Add(cell);
                        }
                    tables.Children.Add(g);
                }
                foreach (var lab in current.Days.Select(d => d.Label.Split(new[] { " • " }, StringSplitOptions.None)[0]).Select(x => x.Contains("→") ? x.Substring(x.IndexOf('→') + 1).Trim() : x).Where(x => x != "").GroupBy(x => x).OrderByDescending(g2 => g2.Count()).Take(30))
                    labelBox.Items.Add(lab.Key + " (" + lab.Count() + ")");
                fillDays();
            };
            Action refresh = delegate
            {
                list.Items.Clear();
                try { Directory.CreateDirectory(ReportsFolder()); foreach (var f in Directory.GetFiles(ReportsFolder(), "*.kreport.json").OrderBy(x => x)) list.Items.Add(Path.GetFileName(f)); } catch (Exception ex) { status.Text = "COULD NOT READ THE FOLDER • " + ex.Message; status.Foreground = Red; }
                if (list.Items.Count == 0) { status.Text = "No reports yet: IMPORT REPORT FILE… (e.g. opening_minute.kreport.json)."; status.Foreground = Muted; }
            };
            Action<string> openFile = path =>
            {
                try { current = KeystoneReport.Load(path); status.Text = "LOADED • " + current.Title + " • " + current.Days.Count + " days • " + current.Sections.Count + " tables"; status.Foreground = Green; }
                catch (Exception ex) { current = null; status.Text = "NOT A KEYSTONE REPORT • " + ex.Message; status.Foreground = Red; }
                show();
            };
            list.SelectionChanged += delegate { if (list.SelectedItem != null) openFile(Path.Combine(ReportsFolder(), Convert.ToString(list.SelectedItem))); };
            importBtn.Click += delegate
            {
                var dlg = new Microsoft.Win32.OpenFileDialog { Filter = "Keystone report (*.kreport.json)|*.kreport.json|JSON (*.json)|*.json", Title = "Import a Keystone report" };
                if (dlg.ShowDialog() != true || string.IsNullOrEmpty(dlg.FileName)) return;
                try
                {
                    KeystoneReport.Load(dlg.FileName);   // must parse before it is kept
                    string name = Path.GetFileName(dlg.FileName); if (!name.EndsWith(".kreport.json", StringComparison.OrdinalIgnoreCase)) name = Path.GetFileNameWithoutExtension(name) + ".kreport.json";
                    Directory.CreateDirectory(ReportsFolder()); string to = Path.Combine(ReportsFolder(), name); File.Copy(dlg.FileName, to, true);
                    refresh(); list.SelectedItem = name; if (list.SelectedItem == null) openFile(to);
                }
                catch (Exception ex) { status.Text = "NOT IMPORTED • " + ex.Message; status.Foreground = Red; }
            };
            folderBtn.Click += delegate { try { Directory.CreateDirectory(ReportsFolder()); System.Diagnostics.Process.Start(ReportsFolder()); } catch { } };
            refreshBtn.Click += delegate { refresh(); };
            findBox.TextChanged += delegate { fillDays(); }; labelBox.SelectionChanged += delegate { fillDays(); };
            dayList.SelectionChanged += delegate
            {
                int k = dayList.SelectedIndex; if (current == null || k < 0 || k >= shown.Count) { detailText.Text = ""; return; }
                var d = shown[k];
