        private static Dictionary<string, LiveProfile> LoadLiveDesk(List<string> groups)
        {
            var profiles = new Dictionary<string, LiveProfile>(StringComparer.OrdinalIgnoreCase); Func<string, double> num = x => { double v; return double.TryParse(x, NumberStyles.Any, CultureInfo.InvariantCulture, out v) ? v : 0; };
            try
            {
                if (!File.Exists(LiveDeskFile())) return profiles;
                foreach (var l in File.ReadAllLines(LiveDeskFile()))
                {
                    var a = l.Split('|');
                    if (a[0] == "GROUP" && a.Length > 1 && a[1].Trim() != "" && !groups.Contains(a[1])) groups.Add(a[1]);
                    else if (a[0] == "ACCOUNT" && a.Length >= 12) profiles[a[1]] = new LiveProfile { Name = a[1], Nick = a[2], Firm = a[3], Group = a[4], Status = a[5], Size = num(a[6]), Dd = num(a[7]), Target = num(a[8]), Peak = num(a[9]), Hidden = a[10] == "1", StopsAtStart = a[11] != "0", Plan = a.Length > 12 ? a[12] : "" };
                }
            }
            catch { }
            return profiles;
        }
        private static void SaveLiveDesk(List<string> groups, Dictionary<string, LiveProfile> profiles)
        {
            try
            {
                Func<string, string> c = x => (x ?? string.Empty).Replace("|", "/").Replace("\n", " ");
                Func<double, string> n = x => x.ToString("0.##", CultureInfo.InvariantCulture);
                var lines = groups.Select(g => "GROUP|" + c(g)).Concat(profiles.Values.Select(p => string.Join("|", "ACCOUNT", c(p.Name), c(p.Nick), c(p.Firm), c(p.Group), c(p.Status), n(p.Size), n(p.Dd), n(p.Target), n(p.Peak), p.Hidden ? "1" : "0", p.StopsAtStart ? "1" : "0", c(p.Plan))));
                Directory.CreateDirectory(DataStoreDirectory()); File.WriteAllLines(LiveDeskFile(), lines.ToArray());
            }
            catch { }
        }

        // NinjaTrader's accounts (prop accounts appear here once their connection is set up in NinjaTrader).
        // ⛔ CLOSE ALL POSITIONS: every connected NinjaTrader account (not Backtest / Playback) with an open position or a working order —
        // closeNow = false only lists them ("TAKEPROFIT250 • MGC LONG 3"); true flattens each one (NinjaTrader closes its positions at market
        // and cancels its orders on those instruments). Asked by the user: works even when nothing is armed, after a confirmation.
        private static List<Tuple<string, string>> FlattenEveryAccount(bool closeNow)
        {
            var res = new List<Tuple<string, string>>(); Account[] all;
            try { lock (Account.All) all = Account.All.ToArray(); } catch { return res; }
            var working = new[] { OrderState.Working, OrderState.Accepted, OrderState.TriggerPending, OrderState.Submitted, OrderState.ChangePending, OrderState.ChangeSubmitted, OrderState.PartFilled, OrderState.Initialized };
            foreach (var a in all)
            {
                if (a == null || (a.Name ?? "").StartsWith("Backtest", StringComparison.OrdinalIgnoreCase) || (a.Name ?? "").StartsWith("Playback", StringComparison.OrdinalIgnoreCase)) continue;
                var inst = new List<Instrument>(); var what = new List<string>(); int nOrd = 0;
                try { lock (a.Positions) foreach (Position p in a.Positions) if (p != null && p.MarketPosition != MarketPosition.Flat && p.Instrument != null) { if (!inst.Contains(p.Instrument)) inst.Add(p.Instrument); what.Add((p.Instrument.MasterInstrument != null ? p.Instrument.MasterInstrument.Name : p.Instrument.FullName) + " " + (p.MarketPosition == MarketPosition.Long ? "LONG " : "SHORT ") + p.Quantity); } } catch { }
                try { lock (a.Orders) foreach (Order o in a.Orders) if (o != null && o.Instrument != null && working.Contains(o.OrderState)) { nOrd++; if (!inst.Contains(o.Instrument)) inst.Add(o.Instrument); } } catch { }
                if (inst.Count == 0) continue;
                if (nOrd > 0) what.Add(nOrd + " order" + (nOrd == 1 ? "" : "s"));
                if (closeNow) { try { a.Flatten(inst); } catch { what.Add("FLATTEN FAILED"); } }
                res.Add(Tuple.Create(a.Name, string.Join(", ", what)));
            }
            return res;
        }
        private static List<LiveSnap> ReadNinjaAccounts()
        {
            var list = new List<LiveSnap>();
            try
            {
                Account[] all; lock (Account.All) all = Account.All.ToArray();
                foreach (var a in all)
                {
                    if (a == null) continue; var s = new LiveSnap { Name = a.Name ?? string.Empty };
                    double netLiq = 0, cash = 0, realized = 0, unrealized = 0;
                    try { netLiq = a.Get(AccountItem.NetLiquidation, Currency.UsDollar); } catch { }
                    try { cash = a.Get(AccountItem.CashValue, Currency.UsDollar); } catch { }
                    try { realized = a.Get(AccountItem.RealizedProfitLoss, Currency.UsDollar); } catch { }
                    try { unrealized = a.Get(AccountItem.UnrealizedProfitLoss, Currency.UsDollar); } catch { }
                    try { s.Gross = a.Get(AccountItem.GrossRealizedProfitLoss, Currency.UsDollar); } catch { s.Gross = realized; }
                    try
                    {
                        // today's fills (from 18:00 New York) → trades ≈ fills / 2
                        var ex = ReflectionValue(a, "Executions") as System.Collections.IEnumerable; int nEx = 0; DateTime nyL = DateTime.Now; try { nyL = TimeZoneInfo.ConvertTimeBySystemTimeZoneId(DateTime.UtcNow, "Eastern Standard Time"); } catch { }
                        DateTime nyStart = nyL.Hour >= 18 ? nyL.Date.AddHours(18) : nyL.Date.AddDays(-1).AddHours(18), from = DateTime.Now - (nyL - nyStart);   // the session start (18:00 New York) on this PC's clock
                        if (ex != null) foreach (var e in ex) { var tt = ReflectionValue(e, "Time"); if (!(tt is DateTime)) continue; if ((DateTime)tt >= from) nEx++; var tNy = (DateTime)tt + (nyL - DateTime.Now); if (tNy > s.LastExecNy) s.LastExecNy = tNy; }   // the last fill, New York time
                        s.Trades = (nEx + 1) / 2;
                    }
                    catch { }
                    s.Balance = netLiq != 0 ? netLiq : cash + unrealized; if (s.Balance > 0) lock (KeystoneFirmRules.Balances) KeystoneFirmRules.Balances[s.Name] = s.Balance; s.Today = realized + unrealized; s.Open = unrealized; s.Closed = realized;
                    object conn = ReflectionValue(a, "Connection"); object opts = ReflectionValue(conn, "Options");
                    s.Connection = Convert.ToString(ReflectionValue(opts, "Name") ?? string.Empty); object st = ReflectionValue(conn, "Status");
                    s.AccStatus = Convert.ToString(ReflectionValue(a, "AccountStatus") ?? string.Empty);   /* the firm's status when NinjaTrader exposes it (Disabled / Liquidate …) — the labs' ● LIVE hides those */
                    s.Connected = conn != null && (st == null || Convert.ToString(st).IndexOf("Connected", StringComparison.OrdinalIgnoreCase) >= 0 && Convert.ToString(st).IndexOf("Dis", StringComparison.OrdinalIgnoreCase) < 0);
                    var parts = new List<string>();
                    try
                    {
                        foreach (Position p in a.Positions)
                            if (p != null && p.MarketPosition != MarketPosition.Flat)
                            {
                                parts.Add((p.MarketPosition == MarketPosition.Long ? "LONG " : "SHORT ") + p.Quantity + " " + (p.Instrument == null ? "" : p.Instrument.FullName) + " @ " + p.AveragePrice.ToString("0.00", CultureInfo.InvariantCulture));
                                s.Contracts += p.Quantity; s.OpenCost += p.Quantity * KeystoneMoveStudy.Cost(p.Instrument != null && p.Instrument.MasterInstrument != null ? p.Instrument.MasterInstrument.Name : "MNQ");
                                string mi = p.Instrument != null && p.Instrument.MasterInstrument != null ? p.Instrument.MasterInstrument.Name : ""; int sq; s.Qty.TryGetValue(mi, out sq); s.Qty[mi] = sq + (p.MarketPosition == MarketPosition.Long ? p.Quantity : -p.Quantity);
                            }
                    }
                    catch { }
                    s.Positions = string.Join(" • ", parts); list.Add(s);
                }
            }
            catch { }
            return list;
        }

