            for (int i = 0; i < 4; i++) root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            var head = new StackPanel(); head.Children.Add(Txt("DATA LIBRARY", Blue, 22, FontWeights.Bold));
            head.Children.Add(new TextBlock { Text = "The Backtest Studio's own 1-minute bars, from NinjaTrader, saved in " + StudioFolder() + "\\MNQ (and MGC)" + " — a DATA folder apart from the reports (" + DataDirectory() + "), so deleting reports never deletes data. Download once; the studio opens with them every time. A day is replaced only by a fuller copy of the same day, so contracts are never mixed inside a day.", Foreground = Muted, FontSize = 11, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 8) });
            Grid.SetRow(head, 0); root.Children.Add(head);
            var coverage = new StackPanel { Margin = new Thickness(0, 0, 0, 10) }; Grid.SetRow(coverage, 1); root.Children.Add(coverage);
            w.Height = 960; w.Width = 1180; FitToScreen(w);
            Action<string, UIElement, System.Windows.Controls.Panel> add = (l, e, p) => { var sp = new StackPanel { Margin = new Thickness(2, 0, 8, 0) }; sp.Children.Add(new TextBlock { Text = l, Foreground = Muted, FontSize = 9, FontWeight = FontWeights.Bold }); sp.Children.Add(e); p.Children.Add(sp); };
            var form = new WrapPanel { Margin = new Thickness(0, 0, 0, 6) };
            var symBox = Select("MNQ + MGC", "MNQ", "MGC"); symBox.SelectedIndex = 0; symBox.Width = 120;
            var today = DateTime.Today; var fromBox = Input(today.AddYears(-1).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)); fromBox.Width = 100; var toBox = Input(today.AddDays(-1).ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)); toBox.Width = 100;
            var missingOnly = new CheckBox { Content = "ONLY WEEKS NOT SAVED YET", IsChecked = true, Foreground = Text, Margin = new Thickness(4, 16, 8, 0) };
            var go = Btn("DOWNLOAD", Green); go.Height = 30; go.Margin = new Thickness(4, 12, 4, 0); go.Padding = new Thickness(16, 0, 16, 0);
            var stop = Btn("STOP", Red); stop.Height = 30; stop.Margin = new Thickness(4, 12, 4, 0); stop.IsEnabled = false;
            var importBtn = Btn("COPY FROM THE LAB", Card); importBtn.Height = 30; importBtn.Margin = new Thickness(4, 12, 4, 0); importBtn.ToolTip = "Copies the lab's loaded 1-minute bars and every 1-minute file it saved before.";
            var folderBtn = Btn("OPEN FOLDER", Card); folderBtn.Height = 30; folderBtn.Margin = new Thickness(4, 12, 4, 0);
            // 1) pick months on the tiles (or a quick choice)  2) DOWNLOAD SELECTED — saved months are skipped by themselves
            var selectedMonths = new HashSet<DateTime>(); Action refreshTiles = null; Func<IEnumerable<DateTime>> gapMonths = null;
            var goSel = Btn("DOWNLOAD SELECTED", Green); goSel.Height = 36; goSel.FontSize = 14; goSel.Margin = new Thickness(0, 0, 8, 0); goSel.Padding = new Thickness(18, 0, 18, 0);
            var clearSel = Btn("CLEAR SELECTION", Card); clearSel.Height = 30; clearSel.Margin = new Thickness(0, 3, 12, 0);
            var quick = new WrapPanel { Margin = new Thickness(0, 6, 0, 0) };
            quick.Children.Add(new TextBlock { Text = "QUICK:", Foreground = Muted, FontSize = 11, FontWeight = FontWeights.Bold, Margin = new Thickness(0, 5, 6, 0) });
            Func<DateTime, DateTime> monthOf = d => new DateTime(d.Year, d.Month, 1);
            foreach (var q in new[] { Tuple.Create("THIS MONTH", 0), Tuple.Create("LAST 3 MONTHS", 2), Tuple.Create("LAST 12 MONTHS", 11), Tuple.Create("LAST 3 YEARS", 35), Tuple.Create("LAST 6 YEARS", 71), Tuple.Create("EVERY GAP", -1) })
            {
                var qq = q; var b = Btn(q.Item1, Card); b.Height = 26; b.FontSize = 11; b.Margin = new Thickness(0, 0, 4, 0); b.Padding = new Thickness(10, 0, 10, 0);
                b.Click += delegate
                {
                    selectedMonths.Clear();
                    if (qq.Item2 >= 0) for (int k = 0; k <= qq.Item2; k++) selectedMonths.Add(monthOf(today).AddMonths(-k));
                    else foreach (var t in gapMonths()) selectedMonths.Add(t);
                    refreshTiles();
                };
                quick.Children.Add(b);
            }
            var allBtn = Btn("LOAD ALL 6 YEARS (MNQ + MGC)", Green); allBtn.Height = 36; allBtn.FontSize = 14; allBtn.Margin = new Thickness(0, 0, 8, 0); allBtn.Padding = new Thickness(18, 0, 18, 0); allBtn.ToolTip = "Everything from " + SixYearsBack().ToString("yyyy-MM-dd") + " to today, newest first, in the background. Saved weeks are skipped; stop and resume any time.";
            var repairBtn = Btn("REPAIR THIN DAYS", Orange); repairBtn.Height = 36; repairBtn.Margin = new Thickness(0, 0, 8, 0); repairBtn.Padding = new Thickness(14, 0, 14, 0); repairBtn.ToolTip = "Days with under 800 minutes (a contract that had already rolled) are asked again on the next contracts; each day keeps its fullest copy.";
            var sendBtn = Btn("SEND DATA TO CLAUDE", Orchid); sendBtn.Height = 36; sendBtn.Margin = new Thickness(0, 0, 8, 0); sendBtn.Padding = new Thickness(14, 0, 14, 0); sendBtn.ToolTip = "Puts the 6 years of bars + your logs into three upload folders and opens GitHub's upload page on the research branch.";
            var row1 = new WrapPanel(); row1.Children.Add(allBtn); row1.Children.Add(repairBtn); row1.Children.Add(sendBtn); row1.Children.Add(goSel); goSel.Background = Card; row1.Children.Add(clearSel); add("INSTRUMENT", symBox, row1); row1.Children.Add(stop); row1.Children.Add(importBtn); row1.Children.Add(folderBtn);
            add("OR FROM", fromBox, form); add("TO", toBox, form); form.Children.Add(missingOnly); form.Children.Add(go);
            go.Content = "DOWNLOAD THESE DATES"; go.Background = Card;
            var formStack = new StackPanel(); formStack.Children.Add(row1); formStack.Children.Add(quick); formStack.Children.Add(form);
            Grid.SetRow(formStack, 2); root.Children.Add(formStack);
            var progress = new TextBlock { Text = "LOAD ALL 6 YEARS once (it runs in the background) — or click months on the tiles → DOWNLOAD SELECTED. Saved weeks are skipped. NinjaTrader must be connected (the same feed the lab loads from).", Foreground = Cyan, FontSize = 12, FontWeight = FontWeights.Bold, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 8, 0, 4) };
            Grid.SetRow(progress, 3); root.Children.Add(progress);
            var log = new StackPanel(); var logScroll = new ScrollViewer { Content = log, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Background = Panel, Height = 220 };
            Grid.SetRow(logScroll, 4); root.Children.Add(logScroll);
            w.Content = new ScrollViewer { Content = root, VerticalScrollBarVisibility = ScrollBarVisibility.Auto };
            Action<string, Brush> addLog = (t, b) => { log.Children.Insert(0, new TextBlock { Text = DateTime.Now.ToString("HH:mm:ss") + "  " + t, Foreground = b, FontFamily = new FontFamily("Consolas"), FontSize = 11, Margin = new Thickness(6, 1, 6, 1), TextWrapping = TextWrapping.Wrap }); while (log.Children.Count > 400) log.Children.RemoveAt(log.Children.Count - 1); };

            Func<DateTime, int> weekdaysIn = m => { int n = 0; for (var d = m; d.Month == m.Month && d < today; d = d.AddDays(1)) if (d.DayOfWeek != DayOfWeek.Saturday && d.DayOfWeek != DayOfWeek.Sunday) n++; return n; };
            Func<string, DateTime, SortedDictionary<DateTime, int>, int> savedIn = (sym, m, sessions) => sessions.Count(kv => kv.Key.Year == m.Year && kv.Key.Month == m.Month && kv.Value >= 60);
            SortedDictionary<DateTime, int> mnqHave = new SortedDictionary<DateTime, int>(), mgcHave = new SortedDictionary<DateTime, int>();
            gapMonths = () =>
            {
                var all = mnqHave.Keys.Concat(mgcHave.Keys).ToList(); if (all.Count == 0) return new DateTime[0];
                var res = new List<DateTime>(); for (var m = monthOf(all.Min()); m <= monthOf(today); m = m.AddMonths(1)) { int wd = weekdaysIn(m); if (wd > 0 && (savedIn("MNQ", m, mnqHave) < wd * 0.9 || savedIn("MGC", m, mgcHave) < wd * 0.9)) res.Add(m); }
                return res;
            };
            var tiles = new StackPanel { Margin = new Thickness(0, 6, 0, 0) };
            refreshTiles = delegate
            {
                tiles.Children.Clear(); mnqHave = KeystoneStudioStore.Sessions(StudioFolder(), "MNQ"); mgcHave = KeystoneStudioStore.Sessions(StudioFolder(), "MGC");
                string[] names = { "JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC" };
                for (int y = today.Year; y >= 2019; y--)
                {
                    int yy = y; var row = new WrapPanel { Margin = new Thickness(0, 0, 0, 4) };
                    var yb = Btn(y.ToString(CultureInfo.InvariantCulture), Card); yb.Width = 64; yb.Height = 52; yb.FontSize = 14; yb.Margin = new Thickness(0, 0, 6, 0); yb.ToolTip = "Select / unselect the whole year";
                    yb.Click += delegate { var ms = Enumerable.Range(1, 12).Select(k => new DateTime(yy, k, 1)).Where(m => m <= today).ToList(); bool all = ms.All(selectedMonths.Contains); foreach (var m in ms) { if (all) selectedMonths.Remove(m); else selectedMonths.Add(m); } refreshTiles(); };
                    row.Children.Add(yb);
                    for (int mo = 1; mo <= 12; mo++)
                    {
                        var m = new DateTime(y, mo, 1); int wd = weekdaysIn(m); bool future = m > today;
                        int a = savedIn("MNQ", m, mnqHave), g = savedIn("MGC", m, mgcHave); double f = wd == 0 ? 0 : Math.Min(a, g) / (double)wd, fmax = wd == 0 ? 0 : Math.Max(a, g) / (double)wd;
                        Brush col = future ? Panel : f >= 0.9 ? Green : fmax >= 0.5 ? Gold : fmax > 0 ? Orange : Card;
                        var tx = new TextBlock { Text = names[mo - 1] + (future ? "" : "\nMNQ " + a + "/" + wd + "\nMGC " + g + "/" + wd), Foreground = future ? Muted : f >= 0.9 || fmax >= 0.5 ? Bg : Text, FontSize = 10.5, FontWeight = FontWeights.Bold, TextAlignment = TextAlignment.Center };
                        bool sel = selectedMonths.Contains(m);
                        var tile = new Border { Width = 74, Height = 52, Margin = new Thickness(0, 0, 4, 0), CornerRadius = new CornerRadius(5), Background = col, BorderBrush = sel ? Cyan : Panel, BorderThickness = new Thickness(sel ? 3 : 1), Child = tx, Cursor = future ? null : System.Windows.Input.Cursors.Hand, ToolTip = future ? null : names[mo - 1] + " " + y + " • MNQ " + a + " of " + wd + " weekdays saved • MGC " + g + " of " + wd + " • click to select" };
                        if (!future) { var mm = m; tile.MouseLeftButtonUp += delegate { if (!selectedMonths.Remove(mm)) selectedMonths.Add(mm); refreshTiles(); }; }
                        row.Children.Add(tile);
                    }
                    tiles.Children.Add(row);
                }
                goSel.Content = selectedMonths.Count == 0 ? "DOWNLOAD SELECTED" : "DOWNLOAD " + selectedMonths.Count + " MONTH" + (selectedMonths.Count == 1 ? "" : "S");
            };
            clearSel.Click += delegate { selectedMonths.Clear(); refreshTiles(); };
            Action refresh = delegate
            {
                coverage.Children.Clear();
                coverage.Children.Add(new TextBlock { Text = "GREEN = saved • GOLD = partly • ORANGE = a few days • DARK = nothing yet • a cyan border = selected", Foreground = Muted, FontSize = 10.5 });
                coverage.Children.Add(tiles); refreshTiles();
                foreach (var sym in new[] { "MNQ", "MGC" })
                {
                    var sessions = KeystoneStudioStore.Sessions(StudioFolder(), sym); var full = sessions.Where(kv => kv.Value >= 60).Select(kv => kv.Key).ToList();
                    var line = new StackPanel { Margin = new Thickness(0, 0, 0, 6) };
                    if (full.Count == 0) { line.Children.Add(new TextBlock { Text = sym + " • nothing saved yet", Foreground = Gold, FontSize = 12.5, FontWeight = FontWeights.Bold }); coverage.Children.Add(line); continue; }
                    DateTime first = full.First(), last = full.Last(); var missing = KeystoneStudioStore.Missing(sessions, first, last, 60);
                    line.Children.Add(new TextBlock { Text = sym + " • " + full.Count + " days saved • " + first.ToString("yyyy-MM-dd") + " → " + last.ToString("yyyy-MM-dd") + " • " + (KeystoneStudioStore.SizeBytes(StudioFolder(), sym) / 1048576.0).ToString("0.0", CultureInfo.InvariantCulture) + " MB" + " • " + missing.Count + " weekdays missing inside (holidays count too)", Foreground = Green, FontSize = 12.5, FontWeight = FontWeights.Bold });
                    coverage.Children.Add(line);
                }
            };
            // news
            var newsLine = new TextBlock { Foreground = Text, FontSize = 12, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 4, 0, 0) };
            Action refreshNews = delegate
            {
                var all = LoadStudioNews(); int high = all.Count(e => e.Impact == "HIGH");
                var nextNews = all.FirstOrDefault(e => e.Time >= DateTime.Now && e.Impact == "HIGH");
                newsLine.Text = "NEWS • " + high + " high-impact USD events known (FOMC 2019–2026 + payrolls built in, the rest from the ForexFactory week feed and your News.csv)" + (nextNews != null ? " • next: " + nextNews.Time.ToString("ddd MM-dd HH:mm") + " " + nextNews.Title : "") + ". CPI / PPI / retail sales etc. of past years: add lines to News.csv (date,time,USD,HIGH,title).";
            };
            var newsUpdate = Btn("UPDATE NEWS NOW", Card); newsUpdate.Height = 26; newsUpdate.Margin = new Thickness(0, 4, 6, 0);
            var newsOpen = Btn("OPEN NEWS FILE", Card); newsOpen.Height = 26; newsOpen.Margin = new Thickness(0, 4, 6, 0);
            newsUpdate.Click += delegate
            {
                var disp = w.Dispatcher; newsLine.Text = "GETTING THIS + NEXT WEEK FROM FOREXFACTORY…";
                System.Threading.ThreadPool.QueueUserWorkItem(delegate { int n = 0; string err = null; try { n = FetchForexFactoryNews(true); } catch (Exception ex) { err = ex.Message; } if (disp != null) disp.BeginInvoke(new Action(delegate { refreshNews(); addLog(err != null ? "NEWS UPDATE FAILED • " + err : "NEWS • " + n + " new lines in News.csv", err != null ? Red : Green); })); });
            };
            newsOpen.Click += delegate { try { if (!File.Exists(NewsFile())) { Directory.CreateDirectory(DataStoreDirectory()); File.WriteAllText(NewsFile(), "# date,time (New York),currency,impact (HIGH / MEDIUM),title — e.g. 2026-10-14,08:30,USD,HIGH,CPI\r\n"); } System.Diagnostics.Process.Start(NewsFile()); } catch (Exception ex) { addLog("COULD NOT OPEN News.csv • " + ex.Message, Red); } };
            var newsRow = new WrapPanel(); newsRow.Children.Add(newsUpdate); newsRow.Children.Add(newsOpen);
            var newsStack = new StackPanel(); newsStack.Children.Add(newsLine); newsStack.Children.Add(newsRow);
            head.Children.Add(newsStack); refreshNews();
            dataLibraryRefresh = refresh; refresh();

            // downloads run in the background service; this window only shows them
            Action showDl = delegate { string t = StudioDownloadStatus(); if (t != "") { progress.Text = t; progress.Foreground = dlBusy ? Cyan : (dlStop ? Gold : Green); } go.IsEnabled = !dlBusy; goSel.IsEnabled = !dlBusy; allBtn.IsEnabled = !dlBusy; stop.IsEnabled = dlBusy; };
            Action<string, Brush> dlLine = (t, b) => addLog(t, b);
            dlChanged += showDl; dlLog += dlLine; showDl();
            Action<string, List<Tuple<DateTime, DateTime>>, bool> downloadRanges = (symChoice, ranges, onlyMissing) =>
            {
                var syms = symChoice == "MNQ" ? new[] { "MNQ" } : symChoice == "MGC" ? new[] { "MGC" } : new[] { "MNQ", "MGC" }; int skipped;
                int n = StartStudioDownload(w.Dispatcher, syms, ranges, onlyMissing, out skipped);
                if (n < 0) { progress.Text = "ALREADY LOADING • it goes on in the background (STOP first to change it)"; progress.Foreground = Gold; }
                else if (n == 0) { progress.Text = "NOTHING TO DOWNLOAD • every week is saved already (" + skipped + " weeks)." + (onlyMissing ? " Untick ONLY WEEKS NOT SAVED YET to download again." : ""); progress.Foreground = Green; }
            };
            dataLibraryDownload = (symChoice, from, to, onlyMissing) => downloadRanges(symChoice, new List<Tuple<DateTime, DateTime>> { Tuple.Create(from, to) }, onlyMissing);
            allBtn.Click += delegate { progress.Text = StartSixYears(w.Dispatcher); progress.Foreground = Cyan; };
            sendBtn.Click += delegate
            {
                try
                {
                    string msg = PrepareDataForClaude();
                    progress.Text = msg; progress.Foreground = Green;
                    try { System.Diagnostics.Process.Start(Path.Combine(DataStoreDirectory(), "ForClaude")); System.Diagnostics.Process.Start(ClaudeUploadUrl); } catch { }
                    KBox(msg + "\n\nGitHub's upload page and the ForClaude folder just opened.\n\nFor PART 01, then PART 02, and so on: open the PART folder, drag its folder \"data\" onto the GitHub page, wait until every file shows, press COMMIT CHANGES (directly to the claude/... branch), then reload the upload page for the next part.\n\nThen tell Claude it is uploaded.", "SEND DATA TO CLAUDE", MessageBoxButton.OK, MessageBoxImage.Information);
                }
                catch (Exception ex) { progress.Text = "COULD NOT PREPARE THE DATA • " + ex.Message; progress.Foreground = Red; }
            };
            repairBtn.Click += delegate { progress.Text = StartRepairThin(w.Dispatcher); progress.Foreground = Cyan; };
            go.Click += delegate
            {
                DateTime from = ParseStudioDate(fromBox.Text), to = ParseStudioDate(toBox.Text);
                if (from == DateTime.MinValue || to == DateTime.MinValue || to < from) { progress.Text = "DATES: type yyyy-MM-dd, FROM before TO"; progress.Foreground = Red; return; }
                if (to > DateTime.Today) to = DateTime.Today;
                dataLibraryDownload(Convert.ToString(symBox.Items[Math.Max(0, symBox.SelectedIndex)]).Replace("MNQ + MGC", "BOTH"), from, to, missingOnly.IsChecked == true);
            };
            goSel.Click += delegate
            {
                if (selectedMonths.Count == 0) { progress.Text = "CLICK SOME MONTHS FIRST (or a QUICK choice)"; progress.Foreground = Gold; return; }
                var ranges = selectedMonths.OrderBy(m => m).Select(m => Tuple.Create(m, m.AddMonths(1).AddDays(-1) > today ? today : m.AddMonths(1).AddDays(-1))).ToList();
                downloadRanges(Convert.ToString(symBox.Items[Math.Max(0, symBox.SelectedIndex)]).Replace("MNQ + MGC", "BOTH"), ranges, true);
            };
            stop.Click += delegate { StopStudioDownload(); };
            importBtn.Click += delegate
            {
                string lab = ImportLabBarsIntoStudio(); progress.Text = "COPYING the lab's saved 1-minute files…"; progress.Foreground = Cyan;
                var disp = w.Dispatcher;
                System.Threading.ThreadPool.QueueUserWorkItem(delegate
                {
                    int n = 0; string err = null; try { n = ImportLabCacheIntoStudio(); } catch (Exception ex) { err = ex.Message; }
                    disp.BeginInvoke(new Action(delegate { progress.Text = err != null ? "COPY FAILED • " + err : "COPIED • " + (lab != "" ? lab + " • " : "") + n + " days from the lab's saved files"; progress.Foreground = err != null ? Red : Green; refresh(); if (studioDataChanged != null) studioDataChanged(); }));
                });
            };
            folderBtn.Click += delegate { try { Directory.CreateDirectory(StudioFolder()); System.Diagnostics.Process.Start(StudioFolder()); } catch (Exception ex) { progress.Text = "COULD NOT OPEN THE FOLDER • " + ex.Message; progress.Foreground = Red; } };
            w.Closing += (sender, args) =>
            {
                if (toolWindowsClosingWithLab) return;
                string text = dlBusy ? "Close the DATA LIBRARY? The download goes on in the background (the studio shows its progress)." : "Close the DATA LIBRARY? Everything downloaded is saved.";
                if (KBox(text, "Close DATA LIBRARY", MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes) { args.Cancel = true; return; }
            };
            w.Closed += delegate { dlChanged -= showDl; dlLog -= dlLine; dataLibraryWindow = null; dataLibraryRefresh = null; dataLibraryDownload = null; };
            w.Show();
        }

