        static List<KeystoneFlip.Unit> AsianUnits(KeystoneAsianLabRow r) { return r.Nights.OrderBy(n => n.Date).Select(n => new KeystoneFlip.Unit { Time = n.Date, Net = n.Net, Worst = Math.Min(n.Worst, n.Net) }).ToList(); }

        // FLIP for Asian: each row exactly as tested (its starting micros ARE the size; more micros = a tighter stop, not just bigger numbers).
        private UIElement AsianLabFlipView(KeystoneAsianLabRow r)
        {
            var root = new StackPanel { Margin = new Thickness(4) };
            root.Children.Add(HelixTitle("FLIP A LIVE ACCOUNT • " + r.Label, Gold));
            root.Children.Add(HelixNote("Your own account: START, every night of this row in order; at GOAL withdraw the profit and restart at START; below BUST (the night's worst open loss counts) deposit START again. The row's STARTING MICROS is the size — compare sizes with the rows below or add sizes to STARTING MICROS and RUN."));
            Action<string, UIElement> add; var inputs = LabInputs(out add);
            var sB = Input(flipStart); sB.Width = 80; var gB = Input(flipGoal); gB.Width = 80; var bB = Input(flipBust); bB.Width = 70; var go = Btn("RECALCULATE", Gold);
            add("START $", sB); add("GOAL $", gB); add("BUST BELOW $", bB); add(" ", go); root.Children.Add(inputs);
            var outPanel = new StackPanel(); root.Children.Add(outPanel);
            Action calc = delegate
            {
                flipStart = sB.Text; flipGoal = gB.Text; flipBust = bB.Text; double start = Number(sB, 500), goal = Number(gB, 1500), bust = NumberAllowZero(bB, 100);
                outPanel.Children.Clear();
                if (goal <= start || bust >= start) { outPanel.Children.Add(Txt("GOAL must be above START, BUST below START.", Red, 12, FontWeights.Bold)); return; }
                double[] w = { 420, 70, 70, 120, 120, 120, 100, 90, 90 };
                outPanel.Children.Add(HelixHeader(new[] { "ROW", "FLIPS", "BUSTS", "WITHDRAWN", "DEPOSITED", "NET CASH", "DAYS / FLIP", "REACH %", "BUST %" }, w));
                Action<KeystoneAsianLabRow, bool> line = delegate(KeystoneAsianLabRow x, bool mine)
                {
                    var f = KeystoneFlip.Run(AsianUnits(x), start, goal, bust, 0, 1);
                    var row = HelixRow(new[] { (mine ? "► " : "") + x.Label, f.Flips.ToString(), f.Busts.ToString(), Cash(f.Withdrawn), Cash(f.Deposited), Signed(f.Net), f.Flips == 0 ? "–" : f.MedianDaysPerFlip.ToString("0"), f.ReachPct.ToString("0") + "%", f.BustPct.ToString("0") + "%" },
                        new[] { mine ? Gold : Text, Green, Red, Green, Red, MoneyBrush(f.Net), Cyan, Green, Red }, w, mine ? Gold : MoneyBrush(f.Net), null);
                    var xx = x; row.Cursor = System.Windows.Input.Cursors.Hand; row.MouseLeftButtonUp += delegate { ShowAsianLabSelected(xx, false); if (asianLabTabs != null) asianLabTabs.SelectedIndex = asianLabTabs.Items.Count - 1; };
                    outPanel.Children.Add(row);
                };
                line(r, true);
                outPanel.Children.Add(HelixTitle("BEST ROWS FOR FLIPPING (top 40 plain-profitable rows)", Gold));
                foreach (var x in asianLabResult.Rows.Where(x => x.P.Net > 0 && x != r).OrderByDescending(x => x.P.Net).Take(40).OrderByDescending(x => KeystoneFlip.Run(AsianUnits(x), start, goal, bust, 0, 1).Net).Take(15)) line(x, false);
            };
            go.Click += delegate { calc(); }; calc();
            return HelixScroll(root);
        }

