                    var line = new WrapPanel(); line.Children.Add(new Border { Width = 110, Padding = new Thickness(6), Child = Txt(rv + " rev (" + (rv + 1) + " legs)", Gold, 11, FontWeights.Bold) });
                    foreach (double t in tps)
