                        st.Children.Add(Txt(KeystoneAsianLab.Blowups(b) + " lost • " + (b.P.Stats.HasPayout ? "1st pay " + b.P.Stats.CalendarDaysToFirstPayout + " d" : "never paid"), Text, 10, FontWeights.Normal));
