        // A separate window: firm rules + your day plan → pass rate, what a funded account pays, the value of one
        // evaluation, separate vs copy vs rotation, history by year (real days) and the SWEET SPOT ranking.
        private Window propPlannerWindow;
        private KeystonePropPlanResult propLastResult; private List<KeystonePropProgram> propLastPrograms = new List<KeystonePropProgram>();
        private List<KeystonePropYear> propLastYears = new List<KeystonePropYear>(); private List<KeystonePropPlanResult> propLastSweet = new List<KeystonePropPlanResult>(); private string propLastSource = string.Empty;
        private string propLastSweetRange = string.Empty, propLastProofRange = string.Empty; private List<Tuple<KeystoneBracket.SavedRule, KeystonePropPlanResult>> propLastProof = new List<Tuple<KeystoneBracket.SavedRule, KeystonePropPlanResult>>();
        private static string PropSavedRulesFile() { return Path.Combine(DataDirectory(), "PropPlanner_SavedRules.txt"); }
        private static List<KeystoneBracket.SavedRule> LoadSavedRules()
        {
            var list = new List<KeystoneBracket.SavedRule>();
            try { if (File.Exists(PropSavedRulesFile())) foreach (var line in File.ReadAllLines(PropSavedRulesFile())) { if (line.StartsWith("#")) continue; var r = KeystoneBracket.SavedRule.FromLine(line); if (r != null) list.Add(r); } } catch { }
            return list;
        }
        // Keep the newest sweet spot's best rules per instrument (other instruments' rules stay).
        private static void StoreSavedRules(string symbol, List<KeystoneBracket.SavedRule> rules)
        {
            try
            {
                var keep = LoadSavedRules().Where(r => r.Symbol != symbol).ToList(); keep.AddRange(rules);
                Directory.CreateDirectory(DataDirectory());
                File.WriteAllLines(PropSavedRulesFile(), new[] { "# Keystone PROP PLANNER saved rules • symbol;entry;close;direction;evalC;evalT$;evalS$;fundC;fundT$;fundS$;foundValue;everyYear;foundRange;foundYears;rank" }.Concat(keep.Select(r => r.ToLine())).ToArray());
            }
            catch { }
        }

        private static double PropNum(TextBox box, double fallback)
        {
            double v; return box != null && double.TryParse((box.Text ?? string.Empty).Replace("$", "").Replace(",", "").Replace("%", "").Trim(), NumberStyles.Any, CultureInfo.InvariantCulture, out v) && v >= 0 ? v : fallback;
        }

        // Keep a window inside the screen's work area (taskbar excluded) so its title bar and maximize button stay reachable
        // on laptops and scaled displays.
        // open maximized; the restore size (▢) = 90 % of the work area, centred
        private static void MaximizeWithRestore(Window w)
        {
            try
            {
                var wa = SystemParameters.WorkArea;
                if (wa.Width >= 400 && wa.Height >= 300) { w.WindowStartupLocation = WindowStartupLocation.Manual; w.Width = Math.Max(Math.Min(w.MinWidth, wa.Width), wa.Width * 0.9); w.Height = Math.Max(Math.Min(w.MinHeight, wa.Height), wa.Height * 0.9); w.Left = wa.X + (wa.Width - w.Width) / 2; w.Top = wa.Y + (wa.Height - w.Height) / 2; }
                w.WindowState = WindowState.Maximized;
            }
            catch { }
        }
        private static void FitWindowToScreen(Window w)
        {
            var wa = SystemParameters.WorkArea;
            if (wa.Width < 400 || wa.Height < 300) return;
            w.Width = Math.Min(w.Width, wa.Width - 16); w.Height = Math.Min(w.Height, wa.Height - 16);
            w.MinWidth = Math.Min(w.MinWidth, w.Width); w.MinHeight = Math.Min(w.MinHeight, w.Height);
            w.WindowStartupLocation = WindowStartupLocation.Manual;
            w.Left = wa.X + (wa.Width - w.Width) / 2; w.Top = wa.Y + Math.Max(0, (wa.Height - w.Height) / 2);
        }


        // ---- MOVE STUDY window: ONE way to test every strategy -------------------------------------------
        // Takes the entries of the last run (GOLDEN: every entry set; any other strategy: its entries), follows each one
        // to the close on the 1-minute bars, compares with buying blindly at the start, and derives target / stop from the moves.
        // Tool windows ask before the X closes them (their results live only in memory); the lab closing them skips the question.
        private bool toolWindowsClosingWithLab;
        private void CloseToolQuietly(Window w) { bool was = toolWindowsClosingWithLab; toolWindowsClosingWithLab = true; try { w.Close(); } finally { toolWindowsClosingWithLab = was; } }
        // Every window asks before the X closes it. message() can explain what is (or is not) saved.
        // a window never larger than the screen's work area, so its title bar (minimise / maximise / close) is always reachable
        private static void FitToScreen(Window w)
        {
            try
            {
                var wa = SystemParameters.WorkArea; if (wa.Width < 200 || wa.Height < 200) return;
                if (w.Width > wa.Width - 20) w.Width = wa.Width - 20; if (w.Height > wa.Height - 20) w.Height = wa.Height - 20;
                if (w.MinWidth > w.Width) w.MinWidth = w.Width; if (w.MinHeight > w.Height) w.MinHeight = w.Height;
                w.ResizeMode = ResizeMode.CanResize;
            }
            catch { }
        }
        private void AskBeforeClosing(Window w, string name, Func<string> message)
        {
            FitToScreen(w);
            w.Closing += delegate(object sender, CancelEventArgs args)
            {
                if (toolWindowsClosingWithLab) return;
                string text = message == null ? "Close " + name + "?" : message();
                if (KBox(text, "Close " + name, MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes) args.Cancel = true;
            };
        }
        private void ConfirmToolClose(Window w, string name)
        {
            FitToScreen(w);
            w.Closing += delegate(object sender, CancelEventArgs args)
            {
                if (toolWindowsClosingWithLab) return;
                if (KBox("Close " + name + "? Its results are not saved unless you exported them.", "Close " + name, MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes) args.Cancel = true;
            };
        }
