        // the sides of the two entries the 30-eval study found best (docs/progress/eval-30-plan-study.txt): ORB30 = MNQ's 9:30–10:00 range,
        // the first 1-minute close beyond it (10:00–11:30) gives the side of both • LONDON = MNQ's move 03:00 → 09:30, traded from 09:30
        // the drawdown room as the user reads it: "room $2,000 (full)" after a +day, "room $500" after −1,500 (never a bare negative floor)
        private static string RoomText(double room, double dd) { room = Math.Max(0, room); return "room " + Cash(room) + (dd > 0 && room >= dd - 0.5 ? " (full)" : ""); }
        private static Func<KeystoneRotDay, int, Tuple<int, int>> RotStudioSides(string code)
        {
            if (code == "ST15")   /* 📈 the short-term trend: the side of MNQ's last 15 minutes (both instruments) */
                return (d, k) => { if (k < 16) return Tuple.Create(0, 0); double a = d.CloseM(k - 1), b = d.CloseM(k - 16); if (double.IsNaN(a) || double.IsNaN(b) || a == b) return Tuple.Create(0, 0); int sd = a > b ? 1 : -1; return Tuple.Create(sd, sd); };
            if (code != "ORB30" && code != "LONDON") return null;
            var cache = new Dictionary<DateTime, int[]>(); var none = Tuple.Create(0, 0);
            return (d, k) =>
            {
                int[] c;
                if (!cache.TryGetValue(d.Day, out c))
                {
                    c = new[] { 0, int.MaxValue, 0 };
                    int r0 = KeystoneRotDay.Slot(930), r1 = KeystoneRotDay.Slot(959), b0 = KeystoneRotDay.Slot(1000), b1 = KeystoneRotDay.Slot(1129); double hi = double.MinValue, lo = double.MaxValue;
                    for (int i = r0; i <= r1; i++) if (d.HasM(i)) { hi = Math.Max(hi, d.MH[i]); lo = Math.Min(lo, d.ML[i]); }
                    if (hi > lo) for (int i = b0; i <= b1; i++) if (d.HasM(i)) { if (d.MC[i] > hi) { c[0] = 1; c[1] = i; break; } if (d.MC[i] < lo) { c[0] = -1; c[1] = i; break; } }
                    double o = d.OpenM(KeystoneRotDay.Slot(300)), x = d.CloseM(KeystoneRotDay.Slot(929)); if (!double.IsNaN(o) && !double.IsNaN(x) && x != o) c[2] = x > o ? 1 : -1;
                    cache[d.Day] = c;
                }
                if (code == "ORB30") return c[0] != 0 && k > c[1] && k <= KeystoneRotDay.Slot(1130) ? Tuple.Create(c[0], c[0]) : none;
                return c[2] != 0 && k >= KeystoneRotDay.Slot(930) ? Tuple.Create(c[2], c[2]) : none;
            };
        }
