        // small coloured chips: the stage, the % (hit the target before the stop on the saved days), the ▲ / ▼ side suggestion; the details in the tooltip
        private FrameworkElement StageStrip(List<KeystonePayout.Chip> chips)
        {
            var wp = new WrapPanel { Margin = new Thickness(0, 4, 0, 8) };
            wp.Children.Add(new TextBlock { Text = "🚦 STAGE INDICATORS", Foreground = Muted, FontSize = 11, FontWeight = FontWeights.Bold, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 10, 0) });
            foreach (var c in chips ?? new List<KeystonePayout.Chip>())
            {
                bool pay = c.Stage == "PAYOUT"; double p = c.Pct; SolidColorBrush col = pay ? Gold : double.IsNaN(p) ? Muted : c.Stage == "PUSH" ? (p >= 25 ? Green : p >= 15 ? Gold : Red) : (p >= 55 ? Green : p >= 48 ? Gold : Red);
                string side = c.Side > 0 ? " ▲ BUY" : c.Side < 0 ? " ▼ SELL" : "";
                var tb = new TextBlock { Text = c.Label + (pay ? "" : " • " + (double.IsNaN(p) ? "—" : p.ToString("0.0", CultureInfo.InvariantCulture) + "%")) + side + (c.Research ? " (research)" : ""), Foreground = col, FontSize = 11.5, FontWeight = FontWeights.Bold };
                var bd = new Border { Background = Tint(col, 40), BorderBrush = Tint(col, 150), BorderThickness = new Thickness(1.2), CornerRadius = new CornerRadius(10), Padding = new Thickness(9, 3, 9, 3), Margin = new Thickness(0, 0, 6, 4), Child = tb, ToolTip = c.Detail };
                wp.Children.Add(bd);
            }
            return wp;
        }
        // the chips from the last ~4 months of saved minutes (in the background; the research values when none are saved)
        private void StageChipsInto(Window w, System.Windows.Controls.Panel host, Func<DateTime, DateTime, List<KeystoneRotDay>> load, DateTime last, Func<KeystonePayoutAccount> acct, Func<KeystonePayoutRules> rules)
        {
            if (host == null) return; host.Children.Clear(); host.Children.Add(Txt("🚦 stage indicators: reading the saved days …", Muted, 11, FontWeights.SemiBold));
            var a0 = acct != null ? acct() : null; var r0 = rules != null ? rules() : null;
            System.Threading.ThreadPool.QueueUserWorkItem(delegate
            {
                List<KeystonePayout.Chip> chips; try { var days = load(last.AddMonths(-4), last) ?? new List<KeystoneRotDay>(); chips = KeystonePayout.StageChips(days, a0, r0); } catch { chips = KeystonePayout.StageChips(null, a0, r0); }
                Action done = delegate { labChipsLast = chips; host.Children.Clear(); host.Children.Add(StageStrip(chips)); };
                if (w == null || w.Dispatcher == null || w.Dispatcher.CheckAccess()) done(); else w.Dispatcher.BeginInvoke(done);
            });
        }
