        private FrameworkElement LabWizardView(KeystoneLabWizard wz, string title, string intro, string[] titles, string[] expl, FrameworkElement[] bodies, Func<string>[] complete, Action advanced, TextBlock msg, out Action repaint)
        {
            var root = new StackPanel { Margin = new Thickness(22, 16, 22, 16), MaxWidth = 1100, HorizontalAlignment = HorizontalAlignment.Left };
            var head = new DockPanel(); root.Children.Add(head);
            var adv = Btn("⚙ advanced • every screen", Card); adv.Height = 32; adv.FontSize = 12.5; adv.Padding = new Thickness(12, 0, 12, 0); adv.ToolTip = "the full lab: pools, plans, every setting, calculate, pipeline, stats, data"; adv.Click += delegate { if (advanced != null) advanced(); };
            DockPanel.SetDock(adv, Dock.Right); head.Children.Add(adv); head.Children.Add(Txt(title, Gold, 24, FontWeights.Bold));
            var it = Txt(intro, Muted, 13, FontWeights.SemiBold); it.TextWrapping = TextWrapping.Wrap; it.Margin = new Thickness(0, 2, 0, 12); root.Children.Add(it);
            if (msg != null) { msg.TextWrapping = TextWrapping.Wrap; msg.Margin = new Thickness(0, 0, 0, 10); root.Children.Add(msg); }
            var cards = new StackPanel(); root.Children.Add(cards);
            string[] num = { "①", "②", "③", "④", "⑤" }; Action paint = null;
            paint = delegate
            {
                cards.Children.Clear();
                for (int i0 = 0; i0 < titles.Length; i0++)
                {
                    int i = i0; bool open = wz.Step == i && wz.CanOpen(i), done = wz.Done[i], locked = !wz.CanOpen(i);
                    var sp = new StackPanel(); var bd = new Border { Background = Panel, BorderBrush = open ? Gold : done ? Green : Card, BorderThickness = new Thickness(open ? 2 : 1.2), CornerRadius = new CornerRadius(10), Padding = new Thickness(16, 10, 16, 12), Margin = new Thickness(0, 0, 0, 10), Child = sp, Opacity = locked ? 0.5 : 1 };
                    var hd = new DockPanel(); sp.Children.Add(hd);
                    hd.Children.Add(Txt(num[i] + " STEP " + (i + 1) + " • " + titles[i] + (done && !open ? "   ✓" : ""), open ? Gold : done ? Green : Muted, 16, FontWeights.Bold));
                    if (done && !open) { var ch = Btn("✎ CHANGE", Card); ch.Height = 28; ch.FontSize = 12; ch.Padding = new Thickness(10, 0, 10, 0); ch.ToolTip = "re-open step " + (i + 1); ch.Click += delegate { wz.Open(i); paint(); }; DockPanel.SetDock(ch, Dock.Right); hd.Children.Insert(0, ch); var sm = Txt("✓ " + wz.Summary[i], Text, 13, FontWeights.SemiBold); sm.TextWrapping = TextWrapping.Wrap; sm.Margin = new Thickness(0, 4, 0, 0); sp.Children.Add(sm); }
                    else if (locked) { var lk = Txt("🔒 finish step " + (Enumerable.Range(0, i).First(j => !wz.Done[j]) + 1) + " first", Muted, 12.5, FontWeights.SemiBold); sp.Children.Add(lk); }
                    if (open)
                    {
                        var ex = Txt(expl[i], Muted, 12.5, FontWeights.Normal); ex.TextWrapping = TextWrapping.Wrap; ex.Margin = new Thickness(0, 4, 0, 8); sp.Children.Add(ex);
                        var pb = bodies[i]; var par = pb.Parent as System.Windows.Controls.Panel; if (par != null) par.Children.Remove(pb); sp.Children.Add(pb);
                        var row = new WrapPanel { Margin = new Thickness(0, 10, 0, 0) }; sp.Children.Add(row);
                        if (i > 0) { var bk = Btn("← BACK", Card); bk.Height = 38; bk.FontSize = 13.5; bk.Padding = new Thickness(14, 0, 14, 0); bk.Margin = new Thickness(0, 0, 8, 0); bk.ToolTip = "back to step " + i; bk.Click += delegate { wz.Back(); paint(); }; row.Children.Add(bk); }
                        var nx = Btn(i == titles.Length - 1 ? "▶ START" : "✓ NEXT", i == titles.Length - 1 ? Green : Tint(Gold, 80)); nx.Height = 38; nx.FontSize = 14; nx.Padding = new Thickness(18, 0, 18, 0); nx.Foreground = i == titles.Length - 1 ? Bg : Gold;
                        nx.ToolTip = i == titles.Length - 1 ? "starts it with the choices above" : "saves this step and opens step " + (i + 2);
                        nx.Click += delegate { string r = null; try { r = complete[i](); } catch (Exception ex2) { if (msg != null) { msg.Text = "⚠ " + ex2.Message; msg.Foreground = Red; } } if (r == null) return; wz.Complete(i, r); if (msg != null && i < titles.Length - 1) { msg.Text = "✓ step " + (i + 1) + " done • step " + (i + 2) + ": " + titles[i + 1]; msg.Foreground = Green; } paint(); };
                        row.Children.Add(nx);
                    }
                    cards.Children.Add(bd);
                }
            };
            paint(); repaint = paint; return new ScrollViewer { VerticalScrollBarVisibility = ScrollBarVisibility.Auto, HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled, Content = root };
        }
        private FrameworkElement LabModeBar(string lab, TextBlock status)
        {
