                b.ToolTip = KeystonePayoutPlan.SprintName(v) + (v == 0 ? " (the default — the realistic lab: SPRINT lost money)" : ""); b.Click += delegate { set(v); paint(); }; btns.Add(b); row.Children.Add(b);
            }
