            var clrT = Btn("✕ CLEAR THE TICKS", Card); clrT.Height = 32; var tr = new WrapPanel { Margin = new Thickness(0, 2, 0, 4) }; tr.Children.Add(useT); tr.Children.Add(clrT); root.Children.Add(tr); root.Children.Add(tickSum);
