                        File.AppendAllText(resFile, string.Join(",", t.Account, t.Kind, t.Symbol, t.Qty, t.Open.ToString("yyyy-MM-dd HH:mm:ss"), t.Close.ToString("yyyy-MM-dd HH:mm:ss"), ((int)(t.Close - t.Open).TotalSeconds).ToString(), t.Entry.ToString("0.00"), t.Exit.ToString("0.00"), t.Pnl.ToString("0.00"), t.BestOpen.ToString("0.00"), t.WorstOpen.ToString("0.00"), t.PeakEquity.ToString("0.00"), t.MaxDdFromPeak.ToString("0.00"), (t.MinBuffer == double.MaxValue ? 0 : t.MinBuffer).ToString("0.00"), t.FloorAtClose.ToString("0.00"), (t.Why ?? "").Replace(",", " ")) + "\n"); } catch { }
                }
            };
            fillResults = () =>
            {
                resList.Children.Clear(); resInfo.Text = saved.Count + " finished trades this session • saved to " + resFile;
                var hdr = new StackPanel { Orientation = Orientation.Horizontal }; foreach (var h in new[] { "ACCOUNT|120", "INSTR.|60", "SIDE|70", "OPEN → CLOSE|170", "⏱ IN TRADE|90", "ENTRY → EXIT|150", "RESULT|90", "BEST|80", "WORST|80", "PEAK EQUITY|100", "DEEPEST DD|90", "LOWEST BUFFER|110", "HOW|160" }) { var x = h.Split('|'); var tb = Txt(x[0], Muted, 10.5, FontWeights.Bold); tb.Width = double.Parse(x[1]); hdr.Children.Add(tb); }
                resList.Children.Add(new Border { Child = hdr, Padding = new Thickness(10, 4, 10, 4) });
                foreach (var t in saved.AsEnumerable().Reverse())
                {
                    var r = new StackPanel { Orientation = Orientation.Horizontal }; var col = t.Pnl >= 0 ? Green : Red; var kb = t.Kind == "TRAILING" ? Orchid : Cyan; var secs = (t.Close - t.Open).TotalSeconds;
                    Action<string, double, Brush> cell = (txt, wd, br) => { var tb = Txt(txt, br, 12, FontWeights.SemiBold); tb.Width = wd; r.Children.Add(tb); };
                    cell(t.Account, 120, kb); cell(t.Symbol, 60, Text); cell((t.Qty > 0 ? "LONG " : "SHORT ") + Math.Abs(t.Qty), 70, t.Qty > 0 ? Green : Red); cell(t.Open.ToString("MM-dd HH:mm:ss") + " → " + t.Close.ToString("HH:mm:ss"), 170, Text);
                    cell(secs >= 3600 ? ((int)(secs / 3600)) + "h " + ((int)(secs % 3600 / 60)) + "m" : ((int)(secs / 60)) + "m " + ((int)(secs % 60)) + "s", 90, Orchid); cell(t.Entry.ToString("0.00") + " → " + t.Exit.ToString("0.00"), 150, Text);
                    cell(Signed(t.Pnl), 90, col); cell(Signed(t.BestOpen), 80, Green); cell(Signed(t.WorstOpen), 80, Red); cell(Cash(t.PeakEquity), 100, Text); cell("−" + Cash(t.MaxDdFromPeak), 90, Red); cell(Cash(t.MinBuffer == double.MaxValue ? 0 : t.MinBuffer), 110, Gold); cell(t.Why, 160, col);
                    resList.Children.Add(new Border { Child = r, Background = Card, BorderBrush = col, BorderThickness = new Thickness(4, 0, 0, 0), CornerRadius = new CornerRadius(6), Padding = new Thickness(10, 5, 10, 5), Margin = new Thickness(0, 2, 0, 2) });
                }
