            };
            // the prices: LIVE = NinjaTrader's 1-minute bars as they update; REPLAY = the saved 1-minute history from the chosen day and New York time
            Action startSource = () =>
            {
                foreach (var f in feeds.Values) f.Stop(); feeds.Clear(); px.Clear(); candles.Clear(); times = null; rIdx = 0;
                if (srcBox.SelectedIndex == 0)
                {
