                    if (w.Dispatcher == null) { status.Text = "LIVE: no window dispatcher"; return; }
                    foreach (var s in new[] { "MGC", "MNQ" }) { var sym = s; feeds[sym] = StartLiveFeed(sym, w.Dispatcher, f => { if (f.Problem != "") { status.Text = sym + ": " + f.Problem; status.Foreground = Red; } else if (f.Initial != null && f.Initial.Count > 0) { foreach (var b in f.Initial.Skip(Math.Max(0, f.Initial.Count - 300))) putBar(sym, b.Time, b.Open, b.High, b.Low, b.Close); px[sym] = f.Initial[f.Initial.Count - 1].Close; } }); }
                    status.Text = "LIVE: NinjaTrader's MGC / MNQ • ① APPLY → ② ▶ START ALL"; status.Foreground = Gold;
                }
                else
                {
                    playBtn.Visibility = Visibility.Visible; rbars = new Dictionary<string, Dictionary<DateTime, KeystoneArcBar>>(StringComparer.OrdinalIgnoreCase); var all = new SortedSet<DateTime>();
                    DateTime want; bool hasDay = DateTime.TryParseExact((dayBox.Text ?? "").Trim(), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out want);
                    int hhmm = (int)PropNum(fromBox, 930); var fromT = TimeSpan.FromMinutes(hhmm / 100 * 60 + hhmm % 100);
                    foreach (var s in new[] { "MGC", "MNQ" })
                    {
                        var b = SavedOneMinuteBars(s); if (b == null || b.Count == 0) continue; var days = b.Select(x => x.Time.Date).Distinct().OrderBy(x => x).ToList(); var day = hasDay ? want : days[days.Count - 1];
                        if (!hasDay) dayBox.Text = day.ToString("yyyy-MM-dd");
                        var d = new Dictionary<DateTime, KeystoneArcBar>(); foreach (var x in b) if (x.Time.Date >= day.AddDays(-1) && x.Time <= day.AddDays(3)) { d[x.Time] = x; if (x.Time >= day + fromT) all.Add(x.Time); else putBar(s, x.Time, x.Open, x.High, x.Low, x.Close); }
                        rbars[s] = d; var before = d.Values.Where(x => x.Time < day + fromT).OrderBy(x => x.Time).LastOrDefault(); if (before != null) px[s] = before.Close;
                    }
