                }
            };
            srcBox.SelectionChanged += delegate { startSource(); };
            dayBox.LostFocus += delegate { if (srcBox.SelectedIndex == 1) startSource(); }; fromBox.LostFocus += delegate { if (srcBox.SelectedIndex == 1) startSource(); };
            Action<DateTime> dayRoll = ny => { if (prevNyHour >= 0 && prevNyHour < 17 && ny.Hour >= 17) foreach (var c in cards) c.A.EndOfDay(ny, P(c.A.Symbol)); prevNyHour = ny.Hour; };
            var timer = new DispatcherTimer(DispatcherPriority.Background, w.Dispatcher) { Interval = TimeSpan.FromMilliseconds(250) };
            int tick = 0;
            timer.Tick += delegate
            {
                try
                {
                    tick++;
                    if (srcBox.SelectedIndex == 0)
                    {
                        foreach (var kv in feeds) { var f = kv.Value; lock (f.Gate) { while (f.Updates.Count > 0) { var b = f.Updates.Dequeue(); px[kv.Key] = b.Close; putBar(kv.Key, b.Time, b.Open, b.High, b.Low, b.Close); } } }
                        clock = NewYorkTime(DateTimeOffset.Now); foreach (var c in cards) { double p = P(c.A.Symbol); if (!double.IsNaN(p)) c.A.Mark(clock, p); } dayRoll(clock);
                    }
                    else if (times != null && times.Count > 0 && !paused)
                    {
                        int per = speedBox.SelectedIndex == 0 ? 1 : speedBox.SelectedIndex == 1 ? 4 : speedBox.SelectedIndex == 2 ? 15 : 60; int every = per >= 4 ? 1 : 4;
                        if (tick % every == 0)
                            for (int k = 0; k < (per >= 4 ? per / 4 : 1) && rIdx < times.Count; k++, rIdx++)
                            {
                                var t = times[rIdx]; dayRoll(t);
                                foreach (var s in rbars.Keys) { KeystoneArcBar b; if (!rbars[s].TryGetValue(t, out b)) continue; bool up = b.Close >= b.Open; double h = b.Open, l = b.Open;
                                    foreach (var p in new[] { b.Open, up ? b.Low : b.High, up ? b.High : b.Low, b.Close }) { px[s] = p; clock = t; h = Math.Max(h, p); l = Math.Min(l, p); putBar(s, t, b.Open, h, l, p); foreach (var c in cards) if (string.Equals(c.A.Symbol, s, StringComparison.OrdinalIgnoreCase)) c.A.Mark(t, p); } }
                            }
                        if (rIdx >= times.Count) status.Text = "REPLAY: the end of the saved data • ↺ RESET or another day";
                    }
                    collect();
                    foreach (var c in cards)
                    {
                        var a = c.A; double p = P(a.Symbol), buf = a.Buffer(p), ratio = Math.Max(0, Math.Min(1.5, buf / a.MaxDd)), prof = a.Profit(p), eqN = a.Equity(p);
                        c.Eq.Text = Cash(eqN); c.Open.Text = Signed(a.Open(p)); c.Open.Foreground = MoneyBrush(a.Open(p)); c.Real.Text = Signed(a.Realized); c.Real.Foreground = MoneyBrush(a.Realized);
                        double peakEq = a.Trailing ? a.Peak : Math.Max(a.Peak, eqN); c.Peak.Text = Cash(peakEq); c.Floor.Text = Cash(a.Floor); c.Buf.Text = Cash(buf); c.Buf.Foreground = ratio > 0.6 ? Green : ratio > 0.3 ? Gold : Red;
                        double half = Math.Max(40, (c.Card.ActualWidth > 100 ? c.Card.ActualWidth : 600) / 2 - 18), full = half * 2;
                        double f = prof >= 0 ? Math.Min(1, a.Target > 0 ? prof / a.Target : 0) : Math.Min(1, -prof / a.MaxDd); c.TgtPos.Width = prof >= 0 ? f * half : 0; c.TgtNeg.Width = prof < 0 ? f * half : 0; c.TgtPos.Background = a.Passed ? Gold : Green;
                        c.TgtText.Text = "🎯 " + (prof >= 0 ? Signed(prof) + " of the " + Cash(a.Target) + " target (" + (a.Target > 0 ? (100 * prof / a.Target).ToString("0") : "0") + "%)" : Signed(prof) + " — losing"); c.TgtText.Foreground = prof >= 0 ? Green : Red;
                        double lossB = Math.Max(0, a.Start - eqN), used = Math.Max(0, a.MaxDd - buf), notTaken = Math.Max(0, used - lossB), left = Math.Max(0, Math.Min(a.MaxDd, buf)), sc = (full - 4) / Math.Max(1, a.MaxDd);
                        c.SegLeft.Width = left * sc; c.SegPeak.Width = Math.Min(full, notTaken * sc); c.SegLoss.Width = Math.Min(full, lossB * sc);
                        bool fresh = (clock - a.RaisedAt).TotalSeconds < (srcBox.SelectedIndex == 0 ? 4 : 240) && a.RaisedAt > DateTime.MinValue; c.SegPeak.Opacity = fresh && tick % 2 == 0 ? 0.4 : 1; c.SegLoss.Opacity = ratio < 0.25 && tick % 4 < 2 ? 0.5 : 1;
                        c.Why.Text = a.Trailing
                            ? "📈 highest " + Cash(peakEq) + (peakEq > eqN + 0.5 ? " (" + Signed(peakEq - a.Start) + " NOT taken)" : " (you are at it)") + " → now " + Cash(eqN) + " → used " + Cash(used) + " = " + Cash(notTaken) + " given back + " + Cash(lossB) + " loss → " + Cash(Math.Max(0, buf)) + " LEFT"
                            : "🌙 floor " + Cash(a.Floor) + " until 17:00 NY → now " + Cash(eqN) + " → used " + Cash(used) + " (" + Cash(lossB) + " loss) → " + Cash(Math.Max(0, buf)) + " LEFT";
                        c.Why.Foreground = buf < a.MaxDd * 0.3 ? Red : notTaken > 0.5 ? Orchid : Text;
                        c.Badge.Text = (a.Trailing ? "TRAILING" : "END OF DAY") + " • " + a.Symbol + " " + (a.Pos > 0 ? "LONG " + a.Pos : a.Pos < 0 ? "SHORT " + (-a.Pos) : "FLAT");
                        if (a.Blown) { c.Flash.Text = "💀 BLOWN — the equity touched the floor"; c.Flash.Foreground = Red; c.Card.BorderBrush = tick % 4 < 2 ? Red : Card; }
                        else if (a.Passed) { c.Flash.Text = "🏆 TARGET REACHED — ✖ CLOSE to bank it"; c.Flash.Foreground = Green; }
                        else if (fresh) { c.Flash.Text = (a.Trailing ? "▲ the floor followed the peak +" : "🌙 end of day: the floor rose +") + Cash(a.LastRaise); c.Flash.Foreground = tick % 2 == 0 ? Gold : Orchid; }
                        else { c.Flash.Text = a.Pos != 0 ? "" : "flat — ② START ALL or ▶ ENTER"; c.Flash.Foreground = Muted; }
                    }
                    // the candles: the last ~90 one-minute candles of the chosen instrument + each open account's entry / target / blow-up price
                    pc.Children.Clear(); var csym = Convert.ToString(chartSym.SelectedItem) ?? "MGC"; double cw = pc.ActualWidth > 50 ? pc.ActualWidth : 900, ch = pc.ActualHeight > 50 ? pc.ActualHeight : 300;
                    SortedList<DateTime, double[]> cl;
                    if (candles.TryGetValue(csym, out cl) && cl.Count > 0)
                    {
                        int nShow = Math.Max(20, Math.Min(cl.Count, (int)((cw - 90) / 8))); var seg = cl.Values.Skip(Math.Max(0, cl.Count - nShow)).ToList(); var lv = new List<Tuple<double, Brush, string, bool>>();
                        foreach (var c in cards.Where(x => x.A.Symbol == csym && x.A.Pos != 0 && !x.A.Blown))
                        {
                            var a = c.A; double perPt = a.Pos * a.PointValue; var kb = a.Trailing ? (Brush)Orchid : Cyan;
                            lv.Add(Tuple.Create(a.Avg, (Brush)Text, a.Name + " entry " + a.Avg.ToString("0.00"), true));
                            double blow = a.Avg + (a.Floor - a.Start - a.Realized) / perPt; lv.Add(Tuple.Create(blow, kb, a.Name + " BLOWS AT " + blow.ToString("0.00"), false));
                            if (a.Target > 0) { double tg = a.Avg + (a.Target - a.Realized) / perPt; lv.Add(Tuple.Create(tg, (Brush)Green, a.Name + " TARGET " + tg.ToString("0.00"), true)); }
                        }
