                            var wick = new System.Windows.Shapes.Line { X1 = x, X2 = x, Y1 = py(b[1]), Y2 = py(b[2]), Stroke = col, StrokeThickness = 1 }; pc.Children.Add(wick);
                            var body = new System.Windows.Shapes.Rectangle { Width = Math.Max(1, bw * 0.7), Height = Math.Max(1, Math.Abs(py(b[0]) - py(b[3]))), Fill = col }; Canvas.SetLeft(body, x - bw * 0.35); Canvas.SetTop(body, Math.Min(py(b[0]), py(b[3]))); pc.Children.Add(body);
                        }
