                        double last = seg[seg.Count - 1][3]; var tagB = new Border { Background = Gold, CornerRadius = new CornerRadius(3), Padding = new Thickness(4, 1, 4, 1), Child = Txt(last.ToString("0.00"), Bg, 11, FontWeights.Bold), Opacity = tick % 2 == 0 ? 1 : 0.75 }; Canvas.SetLeft(tagB, cw - 84); Canvas.SetTop(tagB, py(last) - 9); pc.Children.Add(tagB);
                        chartInfo.Text = csym + " 1-minute • " + clock.ToString("ddd dd MMM HH:mm") + " NY";
                    }
                    else chartInfo.Text = "waiting for " + csym + " candles…";
                    var cmp = new List<string>();
                    foreach (var s in cards.Select(x => x.A.Symbol).Distinct())
                    {
                        var tr = cards.Where(x => x.A.Symbol == s && x.A.Trailing).ToList(); var eo = cards.Where(x => x.A.Symbol == s && !x.A.Trailing).ToList(); double p = P(s);
                        if (tr.Count == 0 || eo.Count == 0 || double.IsNaN(p)) continue; double bt = tr.Average(x => x.A.Buffer(p)), be = eo.Average(x => x.A.Buffer(p));
                        cmp.Add(s + " " + p.ToString("0.00") + " • TRAILING buffer " + Cash(bt) + " vs END OF DAY " + Cash(be) + (be - bt > 1 ? " → the trailing rule took " + Cash(be - bt) + " of room" : bt - be > 1 ? " → EOD has " + Cash(bt - be) + " less room" : " → the same so far"));
                    }
