            };
            stop = () => { timer.Stop(); foreach (var f in feeds.Values) f.Stop(); feeds.Clear(); };
            build(); startSource(); timer.Start(); return root;
        }

        // ---- ROTATION TESTER window -------------------------------------------------------------------------
        private Window rotationWindow; private KeystoneRotationResult rotationLast; private List<KeystoneRotationResult> rotationOpt = new List<KeystoneRotationResult>();
        private TextBlock rotationStatus; private Action rotationRun, rotationOptimize;

        private void OpenRotationTester()
        {
            if (rotationWindow != null) { rotationWindow.Activate(); return; }
            var w = new KeystoneWindow { Title = "SPASIX FUTURE • ROTATION TESTER", Width = 1500, Height = 900, MinWidth = 900, MinHeight = 560, Background = Bg, Foreground = Text, ResizeMode = ResizeMode.CanResize, WindowStartupLocation = WindowStartupLocation.CenterScreen, ShowInTaskbar = true };
