                PayoutPercent = Math.Min(100, PropNum(payPctBox, 50)), PayoutCap = PropNum(capBox, 2000), Split = Math.Min(100, PropNum(splitBox, 90)), MaxPayouts = (int)PropNum(maxPayBox, 0)
            };
            Func<KeystonePropRules> readRules = () =>
