                cards.Children.Add(HelixCard("VALUE OF ONE EVALUATION", Signed(x.ValuePerEval), "after its " + Cash(x.Rules.EvalCost) + " cost • the number that decides it", MoneyBrush(x.ValuePerEval), 230));
