                cards.Children.Add(HelixCard("FAILS IN A ROW (WORST 1 IN 20)", x.LongestFailStreak95.ToString(), "= " + Cash(x.LongestFailStreak95 * x.Rules.EvalCost) + " in evaluations before a pass", Red, 230));
