            Action<List<KeystonePropPlanResult>> renderSweet = list =>
            {
                var p = new StackPanel();
                if (list == null || list.Count == 0) { p.Children.Add(HelixNote("Press FIND SWEET SPOT.")); setTab(3, p); return; }
                bool br = list[0].Plan != null && list[0].Plan.Source == "BRACKET";
                p.Children.Add(HelixNote("Every plan below was simulated with the same firm rules and ranked by VALUE / EVAL (what one evaluation is worth after its cost). Click a row to load that plan into the settings and run it." + (br ? " BY YEAR = the same rule on each year's days alone (top 25): ✓ positive in every year = a real candidate • ✗ = it needed one lucky year. Prefer the best ✓ over a higher ✗." : "")));
                if (br) { var bestEvery = list.FirstOrDefault(s => s.EveryYear); p.Children.Add(Txt(bestEvery == null ? "NO RULE WAS POSITIVE IN EVERY YEAR — the ranking is luck; do not trade it." : "BEST RULE THAT WORKED IN EVERY YEAR: #" + (list.IndexOf(bestEvery) + 1) + " • " + bestEvery.Label + " • " + Signed(bestEvery.ValuePerEval) + " per evaluation • " + bestEvery.YearText, bestEvery == null ? Red : Green, 12.5, FontWeights.Bold)); }
                double[] w5 = br ? new double[] { 40, 640, 60, 56, 100, 100, 90, 70, 330 } : new double[] { 40, 420, 70, 64, 110, 110, 100, 90, 10 };
                p.Children.Add(HelixPaged(new[] { "#", "PLAN", "PASS", "DAYS", "FUNDED PAYS", "VALUE / EVAL", "LOSING EVALS", "FAILS IN A ROW", br ? "BY YEAR" : "" }, w5, list.Count, i =>
                {
                    var s = list[i];
                    string yr = s.YearText.Length == 0 ? (br ? "—" : "") : (s.EveryYear ? "✓ " : "✗ ") + s.YearText;
                    return HelixRow(new[] { (i + 1).ToString(), s.Label, s.PassRate.ToString("0") + "%", s.AvgDaysToPass.ToString("0.0"), Cash(s.FundedValue), Signed(s.ValuePerEval), s.LosingShare.ToString("0") + "%", s.LongestFailStreak95.ToString(), yr },
                        new[] { Gold, Text, Text, Text, Text, MoneyBrush(s.ValuePerEval), Text, Text, s.YearText.Length == 0 ? Muted : (s.EveryYear ? Green : Red) }, w5, i == 0 ? Gold : MoneyBrush(s.ValuePerEval), delegate { if (applyPlanAndRun != null) applyPlanAndRun(s.Plan); });
                }, 40, false));
                setTab(3, p);
            };

            Action run = delegate
            {
                if (busy) return;
                var rules = readRules(); var plan = readPlan(); var days = readDays();
                if (plan.Source == "REAL" && (days == null || days.Count(d => d.Traded) == 0)) { status.Text = "NO RECOIL DAYS • run RECOIL in the lab first (or choose COIN FLIP)."; status.Foreground = Red; return; }
                string bSym = kind().StartsWith("BRACKET") ? kind().Substring(8) : null; int bEntry = (int)PropNum(entryBox, 935), bClose = (int)PropNum(closeBox, 1555); string bDir = readDir();
                if (bSym != null && (!IsValidHhmm(bEntry) || !IsValidHhmm(bClose) || bClose <= bEntry)) { status.Text = "BRACKET TIME ERROR • entry and close are HHMM New York time, close after entry (e.g. 935 and 1555)."; status.Foreground = Red; return; }
                int n = Math.Max(500, Math.Min(50000, (int)PropNum(simsBox, 4000))), slots = Math.Max(1, Math.Min(100, (int)PropNum(slotsBox, 5))), months = Math.Max(1, Math.Min(60, (int)PropNum(monthsBox, 12)));
                string source = sources[Math.Max(0, Math.Min(sources.Count - 1, sourceBox.SelectedIndex))];
                busy = true; runBtn.IsEnabled = sweetBtn.IsEnabled = false; status.Text = "RUNNING • " + n.ToString("N0") + " evaluations + " + slots + " accounts × 3 ways × " + months + " months…"; status.Foreground = Gold;
                System.Threading.ThreadPool.QueueUserWorkItem(delegate
                {
                    KeystonePropPlanResult x = null, luck = null; var programs = new List<KeystonePropProgram>(); var years = new List<KeystonePropYear>(); string failure = null;
                    try
                    {
                        if (bSym != null)
                        {
                            plan.Bracket = KeystoneBracket.Build(daysFor(bSym), bSym, bEntry, bClose, bDir);
                            if (plan.Bracket.Traded == 0) throw new Exception("no trades • the entry time " + KeystoneBracket.Hm(bEntry) + " is outside the loaded hours (" + dataText(bSym) + ")");
                        }
                        x = KeystonePropPlanner.Evaluate(rules, plan, days, n, 17);
                        int runs = Math.Max(200, Math.Min(2000, 400000 / Math.Max(1, slots * months)));
                        foreach (var mode in new[] { "SEPARATE", "COPY", "ROTATION" }) programs.Add(KeystonePropPlanner.Program(rules, plan, days, mode, slots, months * 21, runs, 23));
                        if (plan.Source == "REAL" || plan.Source == "BRACKET") { years = KeystonePropPlanner.History(rules, plan, days); var coin = plan.Copy(); coin.Source = "COIN"; coin.DayCost = plan.Source == "BRACKET" ? plan.Bracket.CostPerContract * plan.EvalContracts : plan.DayCost; luck = KeystonePropPlanner.Evaluate(rules, coin, null, n, 17); }
                    }
                    catch (Exception ex) { failure = ex.Message; }
                    Action done = delegate
                    {
                        busy = false; runBtn.IsEnabled = sweetBtn.IsEnabled = true;
                        if (failure != null || x == null) { status.Text = "PLANNER ERROR • " + failure; status.Foreground = Red; return; }
                        renderPlan(x, programs, years, luck, source);
                        propLastPrograms = programs; propLastYears = years; propLastSource = source; propLastResult = x;
                        status.Text = "DONE • one evaluation is worth " + Signed(x.ValuePerEval) + " • pass " + x.PassRate.ToString("0.0") + "% • " + slots + " separate accounts for " + months + " months: typical " + Signed(programs[0].P50) + ", money needed " + Cash(programs[0].MoneyNeeded95);
                        status.Foreground = x.ValuePerEval > 0 ? Green : Red;
                        tabs.SelectedIndex = 0;
                    };
                    if (w.Dispatcher == null || w.Dispatcher.CheckAccess()) done(); else w.Dispatcher.BeginInvoke(done);
                });
            };

            Action<KeystonePropPlan> applyPlan = p =>
            {
                eTBox.Text = p.EvalTarget.ToString("0", CultureInfo.InvariantCulture); eSBox.Text = p.EvalStop.ToString("0", CultureInfo.InvariantCulture); fTBox.Text = p.FundTarget.ToString("0", CultureInfo.InvariantCulture); fSBox.Text = p.FundStop.ToString("0", CultureInfo.InvariantCulture);
                eKBox.Text = p.EvalSize.ToString("0.##", CultureInfo.InvariantCulture); eStopBox.Text = p.EvalDayStop.ToString("0", CultureInfo.InvariantCulture); fKBox.Text = p.FundSize.ToString("0.##", CultureInfo.InvariantCulture); fStopBox.Text = p.FundDayStop.ToString("0", CultureInfo.InvariantCulture);
                eCBox.Text = p.EvalContracts.ToString(CultureInfo.InvariantCulture); fCBox.Text = p.FundContracts.ToString(CultureInfo.InvariantCulture);
                if (p.Bracket != null) { entryBox.Text = p.Bracket.EntryHhmm.ToString(CultureInfo.InvariantCulture); closeBox.Text = p.Bracket.CloseHhmm.ToString(CultureInfo.InvariantCulture); dirBox.SelectedIndex = Math.Max(0, Array.IndexOf(KeystoneBracket.Directions, p.Bracket.Direction)); }
            };
            applyPlanAndRun = p => { applyPlan(p); run(); };

            Action sweet = delegate
            {
                if (busy) return;
                var rules = readRules(); var plan = readPlan(); var days = readDays();
                if (plan.Source == "REAL" && (days == null || days.Count(d => d.Traded) == 0)) { status.Text = "NO RECOIL DAYS • run RECOIL in the lab first (or choose COIN FLIP)."; status.Foreground = Red; return; }
                int n = Math.Max(300, Math.Min(5000, (int)PropNum(simsBox, 4000) / 2));
                string bSym = kind().StartsWith("BRACKET") ? kind().Substring(8) : null; int bClose = (int)PropNum(closeBox, 1555);
                busy = true; runBtn.IsEnabled = sweetBtn.IsEnabled = false; status.Text = bSym != null ? "SEARCHING THE SWEET SPOT ON REAL " + bSym + " PRICES • every entry time × direction, then every size, then each year (uses all CPU cores, about a minute)…" : "SEARCHING THE SWEET SPOT • every plan × " + n.ToString("N0") + " evaluations…"; status.Foreground = Gold;
                Action<string> progress = msg => { Action u = delegate { if (busy) status.Text = "SEARCHING THE SWEET SPOT ON REAL " + bSym + " PRICES • " + msg + "…"; }; if (w.Dispatcher == null || w.Dispatcher.CheckAccess()) u(); else w.Dispatcher.BeginInvoke(u); };
                System.Threading.ThreadPool.QueueUserWorkItem(delegate
                {
                    List<KeystonePropPlanResult> list = null; string failure = null;
                    try
                    {
                        if (bSym != null) { list = KeystoneBracket.SweetSpot(daysFor(bSym), bSym, IsValidHhmm(bClose) ? bClose : 1555, rules, plan, n, 31, progress); if (list.Count == 0) throw new Exception("fewer than 10 trading days for every entry time • load more dates (" + dataText(bSym) + ")"); }
                        else list = KeystonePropPlanner.SweetSpot(rules, plan, days, n, 31);
                    }
                    catch (Exception ex) { failure = ex.Message; }
                    Action done = delegate
                    {
                        busy = false; runBtn.IsEnabled = sweetBtn.IsEnabled = true;
                        if (failure != null || list == null) { status.Text = "SWEET SPOT ERROR • " + failure; status.Foreground = Red; return; }
                        renderSweet(list);
                        useBtn.IsEnabled = list.Count > 0; propLastSweet = list;
                        propLastSweetRange = bSym != null ? bSym + " " + KeystoneBracket.RangeText(daysFor(bSym)) : "COIN";
                        if (bSym != null) StoreSavedRules(bSym, list.Take(25).Select((x, i) => KeystoneBracket.SavedRule.From(x, KeystoneBracket.RangeText(daysFor(bSym)), i + 1)).ToList());
                        var b = list[0]; var every = list.FirstOrDefault(s => s.EveryYear);
                        int tradedDays = b.Plan != null && b.Plan.Bracket != null ? b.Plan.Bracket.Traded : 0;
                        if (bSym != null && every != null) b = every;
                        status.Text = (bSym != null ? (every != null ? "SWEET SPOT • BEST RULE THAT WORKED EVERY YEAR: " : "SWEET SPOT • NO RULE WORKED IN EVERY YEAR • #1 ") : "SWEET SPOT • #1 ") + b.Label + " • one evaluation worth " + Signed(b.ValuePerEval) + " • pass " + b.PassRate.ToString("0") + "% • press USE BEST PLAN or click any row";
                        status.Foreground = b.ValuePerEval > 0 ? Green : Red;
                        if (bSym != null && tradedDays < 120) { status.Text = "WARNING: ONLY " + tradedDays + " TRADING DAYS LOADED — far too few to trust; load 2 years in Step 1. " + status.Text; status.Foreground = Gold; }
                        tabs.SelectedIndex = 3;
                    };
                    if (w.Dispatcher == null || w.Dispatcher.CheckAccess()) done(); else w.Dispatcher.BeginInvoke(done);
                });
            };
            Action<List<Tuple<KeystoneBracket.SavedRule, KeystonePropPlanResult>>, string> renderProof = (proof, range) =>
            {
                var p = new StackPanel();
                if (proof == null || proof.Count == 0) { p.Children.Add(HelixNote("PROOF TEST re-runs the best rules saved by your last FIND SWEET SPOT on the data loaded now. 1) Run FIND SWEET SPOT on one period (e.g. 2025–2026). 2) In the lab load dates the rules never saw (e.g. 2023-01-01 → 2024-12-31) with PROP BRACKET. 3) Press PROOF TEST.")); setTab(4, p); return; }
                int held = proof.Count(t => t.Item2.ValuePerEval > 0), every = proof.Count(t => t.Item2.EveryYear);
                bool overlap = KeystoneBracket.Overlaps(proof[0].Item1.FoundRange, range);
                p.Children.Add(Txt(overlap ? "WARNING: the rules were found on " + proof[0].Item1.FoundRange + " and the data now is " + range + " — they overlap, so this is NOT a proof. Load dates the rules never saw." : held + " OF " + proof.Count + " SAVED RULES STAYED PROFITABLE ON NEW DATA (" + range + ") • " + every + " positive in every year. Found on " + proof[0].Item1.FoundRange + ".", overlap ? Red : (held * 2 >= proof.Count ? Green : Red), 14, FontWeights.Bold));
                var best = proof.Where(t => t.Item2.EveryYear).OrderByDescending(t => t.Item2.ValuePerEval).FirstOrDefault();
                p.Children.Add(Txt(best == null ? "No saved rule was positive in every year of the new data — none of them is proven." : "STRONGEST ON NEW DATA: " + best.Item2.Label + " • " + Signed(best.Item2.ValuePerEval) + " per evaluation (found: " + Signed(best.Item1.FoundValue) + ") • " + best.Item2.YearText, best == null ? Red : Green, 12.5, FontWeights.Bold));
                p.Children.Add(HelixNote("FOUND = what the sweet spot measured on its own dates • NOW = the same rule on the data loaded now. A real edge keeps most of its value on new data; a lucky fit falls to zero or below. Click a row to load the rule and run it."));
                double[] wp = { 36, 600, 210, 60, 100, 110, 280, 70 };
                p.Children.Add(HelixHeader(new[] { "#", "RULE", "FOUND: VALUE / EVAL", "PASS", "FUNDED PAYS", "NOW: VALUE", "NOW: BY YEAR", "HOLDS?" }, wp));
                foreach (var t in proof)
                {
                    var tt = t; bool ok = tt.Item2.ValuePerEval > 0;
                    p.Children.Add(HelixRow(new[] { tt.Item1.Rank.ToString(), tt.Item2.Label, Signed(tt.Item1.FoundValue) + (tt.Item1.FoundEveryYear ? " ✓" : ""), tt.Item2.PassRate.ToString("0") + "%", Cash(tt.Item2.FundedValue), Signed(tt.Item2.ValuePerEval), (tt.Item2.EveryYear ? "✓ " : "✗ ") + tt.Item2.YearText, ok ? (tt.Item2.EveryYear ? "YES" : "PARTLY") : "NO" },
                        new[] { Gold, Text, Muted, Text, Text, MoneyBrush(tt.Item2.ValuePerEval), tt.Item2.EveryYear ? Green : Red, ok ? (tt.Item2.EveryYear ? Green : Gold) : Red }, wp, ok ? (tt.Item2.EveryYear ? Green : Gold) : Red, delegate { if (applyPlanAndRun != null) applyPlanAndRun(tt.Item2.Plan); }));
                }
                setTab(4, p);
            };
            Action proofRun = delegate
            {
                if (busy) return;
                string kd = kind();
                if (!kd.StartsWith("BRACKET")) { status.Text = "PROOF TEST needs REAL BRACKET days: load dates in the lab with PROP BRACKET, choose REAL BRACKET in DAYS COME FROM."; status.Foreground = Red; return; }
                string sym = kd.Substring(8);
                var saved = LoadSavedRules().Where(r => r.Symbol == sym).OrderBy(r => r.Rank).ToList();
                if (saved.Count == 0) { status.Text = "NO SAVED " + sym + " RULES • run FIND SWEET SPOT on another period first (e.g. 2025–2026); its best 25 rules are saved for the proof."; status.Foreground = Red; return; }
                var rules = readRules(); var plan = readPlan(); int n = Math.Max(500, Math.Min(4000, (int)PropNum(simsBox, 4000) / 2));
                busy = true; runBtn.IsEnabled = sweetBtn.IsEnabled = proofBtn.IsEnabled = false; status.Text = "PROOF TEST • " + saved.Count + " saved " + sym + " rules (found on " + saved[0].FoundRange + ") on the data loaded now…"; status.Foreground = Gold;
                System.Threading.ThreadPool.QueueUserWorkItem(delegate
                {
                    List<Tuple<KeystoneBracket.SavedRule, KeystonePropPlanResult>> proof = null; string failure = null, range = string.Empty;
                    try { var md = daysFor(sym); range = KeystoneBracket.RangeText(md); proof = KeystoneBracket.ProofTest(md, saved, rules, plan, n, 41); } catch (Exception ex) { failure = ex.Message; }
                    Action done = delegate
                    {
                        busy = false; runBtn.IsEnabled = sweetBtn.IsEnabled = proofBtn.IsEnabled = true;
                        if (failure != null || proof == null) { status.Text = "PROOF TEST ERROR • " + failure; status.Foreground = Red; return; }
                        renderProof(proof, range); propLastProof = proof; propLastProofRange = range;
                        int held = proof.Count(t => t.Item2.ValuePerEval > 0);
                        status.Text = "PROOF TEST • " + held + " of " + proof.Count + " rules stayed profitable on " + range + (KeystoneBracket.Overlaps(saved[0].FoundRange, range) ? " (WARNING: overlaps the dates they were found on)" : " (new data)") + " • see the PROOF TEST tab";
                        status.Foreground = held * 2 >= proof.Count ? Green : Red; tabs.SelectedIndex = 4;
                    };
                    if (w.Dispatcher == null || w.Dispatcher.CheckAccess()) done(); else w.Dispatcher.BeginInvoke(done);
                });
            };
            proofBtn.Click += delegate { proofRun(); };
            sweetBtn.Click += delegate { sweet(); };
            runBtn.Click += delegate { run(); };
            useBtn.Click += delegate { if (propLastSweet.Count > 0) applyPlanAndRun((propLastSweet.FirstOrDefault(s => s.EveryYear) ?? propLastSweet[0]).Plan); };
            exportBtn.Click += delegate
            {
                if (propLastResult == null) { status.Text = "RUN THIS PLAN FIRST"; status.Foreground = Gold; return; }
                try
                {
                    string dir = DataDirectory(); Directory.CreateDirectory(dir);
                    string html = Path.Combine(dir, "KeystoneArc_PropPlanner_" + DateTime.Now.ToString("yyyyMMdd_HHmmss") + ".html");
                    File.WriteAllText(html, KeystonePropPlanner.Html(propLastResult, propLastPrograms, propLastYears, propLastSweet, propLastSource, propLastProof, propLastProofRange, propLastSweetRange), Encoding.UTF8);
                    string csv = null;
                    if (propLastResult.Plan != null && propLastResult.Plan.Bracket != null) { csv = Path.ChangeExtension(html, null) + "_days.csv"; File.WriteAllText(csv, KeystoneBracket.DayCsv(propLastResult.Plan), Encoding.UTF8); }
                    status.Text = "EXPORTED • " + html + (csv != null ? " + every day: " + Path.GetFileName(csv) : "") + " • attach these files to Claude"; status.Foreground = Green;
                }
                catch (Exception ex) { status.Text = "EXPORT ERROR • " + ex.Message; status.Foreground = Red; }
            };
            // The sweet spot list belongs to the data it was searched on: hide it when other data is loaded now.
            if (propLastSweetRange != "COIN" && propLastSweet.Count > 0)
            {
                bool same = false; foreach (var sym in labBars.Keys) if (propLastSweetRange == sym + " " + KeystoneBracket.RangeText(daysFor(sym))) same = true;
                if (!same) { propLastSweet = new List<KeystonePropPlanResult>(); propLastSweetRange = string.Empty; }
            }
            renderSweet(propLastSweet); useBtn.IsEnabled = propLastSweet.Count > 0;
            renderProof(null, string.Empty); propLastProof = new List<Tuple<KeystoneBracket.SavedRule, KeystonePropPlanResult>>(); propLastProofRange = string.Empty;
            // Keep the last rule and firm rules you ran (a new data load must not reset them).
            if (propLastResult != null) { showRules(propLastResult.Rules); applyPlan(propLastResult.Plan); refreshPoints(); }

            ConfirmToolClose(w, "PROP PLANNER");
            w.Content = root; propPlannerWindow = w;
            w.Closed += delegate { propPlannerWindow = null; applyPlanAndRun = null; propPlannerRun = null; propPlannerSweet = null; propPlannerProof = null; };
            w.Show();
            propPlannerRun = run; propPlannerSweet = sweet; propPlannerTabs = tabs; propPlannerStatus = status; propPlannerProof = proofRun;
        }
        private Action<KeystonePropPlan> applyPlanAndRun;
        private TabControl propPlannerTabs; private TextBlock propPlannerStatus;
        private Action propPlannerRun, propPlannerSweet, propPlannerProof;   // the open planner's RUN / FIND SWEET SPOT (used by the smoke test)

        // ---- chart -------------------------------------------------------------------------------
        private void RecoilFillDetail(KeystoneArcEvent e)
        {
            KeystoneRecoilCycle c;
            if (e == null || !recoilCycleById.TryGetValue(e.SessionOrder, out c)) return;
            recoilSelectedId = c.Id;
            Brush accent = c.Win ? WinPurple : (c.Reason == "SESSION END" ? ExitIce : LossAmber);
            if (evidenceDetailText != null) { evidenceDetailText.Text = RecoilCycleText(c); evidenceDetailText.Foreground = accent; }
            if (evidenceDetailBorder != null) { evidenceDetailBorder.BorderBrush = accent; evidenceDetailBorder.Visibility = Visibility.Visible; }
            if (evidencePnlText != null) { evidencePnlText.Foreground = accent; evidencePnlText.Text = (c.Win ? "WIN" : c.Reason) + " • " + Signed(c.Net) + "\n" + c.Side + " " + c.Entries + " entries • " + c.MaxQty + " contracts • avg " + c.AvgAtExit.ToString(c.Symbol == "MGC" ? "0.0" : "0.00"); }
            if (evidencePnlBorder != null) { evidencePnlBorder.BorderBrush = accent; evidencePnlBorder.Visibility = Visibility.Visible; }
        }

        // Each ladder: start price → trigger, every fill with its size, the average (steps at each add), the target
        // and blowup lines (they move with each add), the exit. In replay everything appears when it happened.
        private void DrawRecoilLadders(List<KeystoneArcEvent> marks, List<KeystoneArcBar> bars, double left, double candleWidth, Func<double, double> y, double plotTop, double plotBottom, bool replaying)
        {
            if (evidenceCanvas == null || bars == null || bars.Count == 0 || marks == null) return;
            DateTime cutoff = replaying ? evidenceBarCursor : DateTime.MaxValue, firstBar = bars[0].Time, lastBar = bars[bars.Count - 1].Time;
            Func<DateTime, double> xAt = t => { int i = bars.FindIndex(b => b.Time >= t); if (i < 0) i = t > lastBar ? bars.Count : 0; return left + i * candleWidth + candleWidth / 2.0; };
            Action<double, double, double, double, Brush, double, bool> line = (x1, y1, x2, y2, brush, th, dash) =>
            {
                var l = new System.Windows.Shapes.Line { X1 = x1, Y1 = y1, X2 = x2, Y2 = y2, Stroke = brush, StrokeThickness = th, Opacity = 0.9, IsHitTestVisible = false };
                if (dash) l.StrokeDashArray = new DoubleCollection { 5, 3 };
                evidenceCanvas.Children.Add(l);
            };
            Action<string, double, double, Brush> tag = (text, x, yy, brush) =>
            {
                var b = new Border { Background = Card, BorderBrush = brush, BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(3), Padding = new Thickness(3, 0, 3, 0), IsHitTestVisible = false, Child = new TextBlock { Text = text, Foreground = brush, FontSize = 10, FontWeight = FontWeights.Bold } };
                Canvas.SetLeft(b, x); Canvas.SetTop(b, Math.Max(plotTop, Math.Min(plotBottom - 16, yy))); evidenceCanvas.Children.Add(b);
            };
            foreach (var id in marks.Select(e => e.SessionOrder).Distinct())
            {
                KeystoneRecoilCycle c; if (!recoilCycleById.TryGetValue(id, out c) || c.Fills.Count == 0) continue;
                if (c.Fills[0].Time > cutoff || c.ExitTime < firstBar || c.AnchorTime > lastBar) continue;
                string f = c.Symbol == "MGC" ? "0.0" : "0.00";
                bool selected = c.Id == recoilSelectedId;
                bool closed = c.ExitTime <= cutoff;
                DateTime end = closed ? c.ExitTime : cutoff;
                // start price and the trigger move
                double ax = xAt(c.AnchorTime.AddMinutes(1)) - candleWidth / 2.0, tx = xAt(c.Fills[0].Time);
                line(ax, y(c.AnchorPrice), tx, y(c.AnchorPrice), Muted, 1, true);
                line(ax, y(c.TriggerLevel), tx, y(c.TriggerLevel), Gold, 1, true);
                tag("START " + c.AnchorPrice.ToString(f) + " • " + (c.Dir > 0 ? "−" : "+") + Math.Abs(c.TriggerLevel - c.AnchorPrice).ToString("0.##") + " → " + c.Side, ax + 2, y(c.AnchorPrice) - (c.Dir > 0 ? 18 : -4), Gold);
                var fills = c.Fills.Where(z => z.Time <= cutoff).ToList();
                for (int k = 0; k < fills.Count; k++)
                {
                    var z = fills[k];
                    DateTime segEnd = k + 1 < fills.Count ? fills[k + 1].Time : end;
                    double x0 = xAt(z.Time), x1 = Math.Max(x0 + candleWidth, xAt(segEnd));
                    line(x0, y(z.Avg), x1, y(z.Avg), Cyan, selected ? 2 : 1.5, false);
                    line(x0, y(z.TargetPrice), x1, y(z.TargetPrice), Green, 1.2, true);
                    if (!double.IsNaN(z.StopPrice)) line(x0, y(z.StopPrice), x1, y(z.StopPrice), Red, 1.2, true);
                    int zd = z.Dir == 0 ? c.Dir : z.Dir;
                    var dot = new System.Windows.Shapes.Ellipse { Width = 9, Height = 9, Fill = zd > 0 ? Green : Red, Stroke = Text, StrokeThickness = 1, IsHitTestVisible = false };
                    Canvas.SetLeft(dot, x0 - 4.5); Canvas.SetTop(dot, y(z.Price) - 4.5); evidenceCanvas.Children.Add(dot);
                    string lbl = c.Mode == "REVERSE" ? (k == 0 ? "" : "REVERSE → ") + (zd > 0 ? "BUY " : "SELL ") + z.Qty + " @ " + z.Price.ToString(f) : (k == 0 ? c.Side + " " : "+") + z.Qty + " @ " + z.Price.ToString(f) + " → " + z.TotalQty + " • avg " + z.Avg.ToString(f);
                    tag(lbl, x0 + 6, y(z.Price) + (zd > 0 ? 4 : -18), zd > 0 ? Green : Red);
                }
                if (fills.Count > 0)
                {
                    var lastF = fills[fills.Count - 1]; double xr = Math.Max(xAt(lastF.Time) + candleWidth, xAt(end));
                    tag("TP " + lastF.TargetPrice.ToString(f), xr + 3, y(lastF.TargetPrice) - 8, Green);
                    tag(double.IsNaN(lastF.StopPrice) ? "BLOWUP = SHARED −" + Cash((recoilConfig ?? recoilResult.Config).MaxDrawdown) : (c.Mode == "REVERSE" ? (n0(c, lastF) ? "LAST STOP " : "STOP → REVERSE ") : "BLOWUP ") + lastF.StopPrice.ToString(f), xr + 3, double.IsNaN(lastF.StopPrice) ? y(lastF.Avg) + 4 : y(lastF.StopPrice) - 8, Red);
                    // next add level while the ladder is open
                    int n = c.Fills.IndexOf(lastF) + 1;
                    if (!closed && c.Mode != "REVERSE" && n < (recoilConfig ?? recoilResult.Config).MaxEntries) { double nl = c.Fills[0].Price - c.Dir * n * c.Step; line(xAt(lastF.Time), y(nl), xr, y(nl), Muted, 1, true); tag("NEXT ADD " + nl.ToString(f), xr + 3, y(nl) - 8, Muted); }
                }
                if (closed)
                {
                    Brush res = c.Win ? WinPurple : (c.Reason == "SESSION END" ? ExitIce : LossAmber);
                    double ex = xAt(c.ExitTime);
                    var sq = new System.Windows.Shapes.Rectangle { Width = 10, Height = 10, Fill = res, Stroke = Text, StrokeThickness = 1, IsHitTestVisible = false };
                    Canvas.SetLeft(sq, ex - 5); Canvas.SetTop(sq, y(c.ExitPrice) - 5); evidenceCanvas.Children.Add(sq);
                    tag((c.Win ? "TARGET " : c.Reason + " ") + Signed(c.Net) + " • " + c.MaxQty + " contracts • " + Hm(c.ExitTime), ex + 7, y(c.ExitPrice) + (c.Win ? -18 : 4), res);
                }
            }
        }

        private bool n0(KeystoneRecoilCycle c, KeystoneRecoilFill f) { return c.Fills.IndexOf(f) + 1 >= (recoilConfig ?? recoilResult.Config).MaxEntries; }

        // Live replay box: every open ladder (contracts, average, open P/L, distance to the target and to the blowup) and the day's log.
        private void UpdateRecoilLivePanel()
        {
            DateTime day; if (!EvidenceReplayDay(out day) || recoilResult == null) return;
            DateTime cur = evidenceBarCursor;
            var cfg = recoilConfig ?? recoilResult.Config;
            var today = recoilResult.Cycles.Where(x => x.Day == day && x.Fills.Count > 0).OrderBy(x => x.EntryTime).ToList();
            var open = today.Where(x => x.EntryTime <= cur && x.ExitTime > cur).ToList();
            var done = today.Where(x => x.ExitTime <= cur).ToList();
            evidenceLiveBorder.Visibility = Visibility.Visible;
            evidenceLiveClock.Text = cur.ToString("ddd yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture) + " ET";
            var sb = new StringBuilder();
            double openSum = 0, targetSum = 0, minStopRoom = double.MaxValue;
            foreach (var c in open)
            {
                var fills = c.Fills.Where(z => z.Time <= cur).ToList(); if (fills.Count == 0) continue;
                double px = LabCloseAt(c.Symbol, cur) ?? fills[fills.Count - 1].Price;
                double v = KeystoneRecoil.Value(c, px, cur);
                var lf = fills[fills.Count - 1]; string f = c.Symbol == "MGC" ? "0.0" : "0.00";
                openSum += v; targetSum += cfg.TargetMode == "POINTS" ? Math.Abs(lf.TargetPrice - lf.Avg) * lf.TotalQty * c.PointValue : cfg.TargetDollars;
                double room = double.IsNaN(lf.StopPrice) ? cfg.MaxDrawdown + v : Math.Abs(px - lf.StopPrice) * lf.TotalQty * c.PointValue;
                minStopRoom = Math.Min(minStopRoom, room);
                sb.AppendLine(c.Symbol + " " + (c.Mode == "REVERSE" ? "STEP " + fills.Count + " " + (lf.Dir > 0 ? "BUY" : "SELL") : c.Side) + " " + lf.TotalQty + " contracts • " + (c.Mode == "REVERSE" ? "entry " : "avg ") + lf.Avg.ToString(f) + " • now " + px.ToString(f) + " → cycle " + Signed(v));
                sb.AppendLine("   target " + lf.TargetPrice.ToString(f) + " (" + Math.Abs(lf.TargetPrice - px).ToString("0.##") + " pts away) • " + (double.IsNaN(lf.StopPrice) ? "shared blowup at −" + Cash(cfg.MaxDrawdown) : (c.Mode == "REVERSE" ? (fills.Count >= cfg.MaxEntries ? "last stop " : "stop → reverse ") : "blowup ") + lf.StopPrice.ToString(f) + " (" + Math.Abs(px - lf.StopPrice).ToString("0.##") + " pts away)"));
                int n = fills.Count; if (c.Mode != "REVERSE" && n < cfg.MaxEntries) sb.AppendLine("   next add " + (c.Fills[0].Price - c.Dir * n * c.Step).ToString(f) + " (+" + KeystoneRecoil.AddQty(cfg, n) + ")");
            }
            if (open.Count > 0)
            {
                evidenceLiveCaption.Text = "LADDERS OPEN • " + string.Join(" + ", open.Select(x => x.Symbol + " " + x.Fills.Count(z => z.Time <= cur) + "/" + cfg.MaxEntries));
                evidenceLiveCombined.Text = Signed(openSum); evidenceLiveCombined.Foreground = openSum > 0 ? Green : (openSum < 0 ? Red : Text);
                evidenceLiveTargetText.Text = "TARGET +" + Cash(targetSum) + " • " + Math.Max(0, 100.0 * openSum / Math.Max(1, targetSum)).ToString("0") + "% of the way";
                evidenceLiveTargetFill.Width = 330 * Math.Max(0, Math.Min(1, openSum / Math.Max(1, targetSum)));
                double ddUsed = cfg.MaxDrawdown <= 0 ? 0 : -openSum / cfg.MaxDrawdown;
                evidenceLiveLossText.Text = "MAX DRAWDOWN −" + Cash(cfg.MaxDrawdown) + " • " + Math.Max(0, 100.0 * ddUsed).ToString("0") + "% used";
                evidenceLiveLossFill.Width = 330 * Math.Max(0, Math.Min(1, ddUsed));
                sb.AppendLine();
            }
            else
            {
                var next = today.FirstOrDefault(x => x.EntryTime > cur);
                evidenceLiveCaption.Text = "NO LADDER OPEN";
                evidenceLiveCombined.Text = "FLAT"; evidenceLiveCombined.Foreground = Muted;
                evidenceLiveTargetText.Text = next == null ? "waiting for the trigger move (or no more ladders today)" : "NEXT • " + next.Symbol + " " + next.Side + " at " + Hm(next.EntryTime);
                evidenceLiveLossText.Text = string.Empty; evidenceLiveTargetFill.Width = 0; evidenceLiveLossFill.Width = 0;
            }
            sb.AppendLine("TODAY SO FAR • " + done.Count(x => x.Win) + " won / " + done.Count(x => x.Blown) + " blown • " + Signed(done.Sum(x => x.Net)));
            foreach (var x in today.Where(z => z.EntryTime <= cur))
            {
                string f = x.Symbol == "MGC" ? "0.0" : "0.00";
                foreach (var z in x.Fills.Where(q => q.Time <= cur)) sb.AppendLine(x.Mode == "REVERSE" ? Hm(z.Time) + " " + x.Symbol + " " + (z == x.Fills[0] ? "" : "REVERSE → ") + (z.Dir > 0 ? "BUY " : "SELL ") + z.Qty + " @ " + z.Price.ToString(f) : Hm(z.Time) + " " + x.Symbol + " " + (z == x.Fills[0] ? x.Side : "ADD") + " " + z.Qty + " @ " + z.Price.ToString(f) + " → " + z.TotalQty + " (avg " + z.Avg.ToString(f) + ")");
                if (x.ExitTime <= cur) sb.AppendLine(Hm(x.ExitTime) + " " + x.Symbol + " " + (x.Win ? "TARGET" : x.Reason) + " @ " + x.ExitPrice.ToString(f) + " → " + Signed(x.Net));
            }
            evidenceLiveLines.Text = sb.ToString().TrimEnd();
            bool closedNow = done.Any(x => x.ExitTime == cur); var last = done.LastOrDefault();
            evidenceLiveBorder.BorderBrush = closedNow && last != null ? (last.Win ? Green : Red) : Gold;
            evidenceLiveBorder.BorderThickness = new Thickness(closedNow ? 3 : 1.5);
        }

        // =================================================================================
        // GOLDEN SETUP • Step 1 settings (same row style as the other strategies)
        // =================================================================================
        private readonly List<UIElement> goldenStrategyControls = new List<UIElement>();
        private bool goldenDefaultsApplied;
        private TextBox goldenMnqStartBox, goldenMgcStartBox, goldenLastEntryBox, goldenCloseBox, goldenMnqDropBox, goldenMgcDropBox, goldenMnqTargetBox, goldenMgcTargetBox, goldenMnqStopBox, goldenMgcStopBox, goldenMnqBufferBox, goldenMgcBufferBox, goldenMnqMaxStopBox, goldenMgcMaxStopBox, goldenMnqQtyBox, goldenMgcQtyBox, goldenTriesBox;
        private ComboBox goldenSideBox, fvgSideBox, tradeSideBox;
        private ComboBox goldenFvgBox, goldenAggressionBox, goldenStopBox, goldenHoldBox, goldenFirstBox, goldenOpenGapBox;
        private CheckBox goldenBhBox, goldenSkipBigStopBox;
        private TextBox goldenMnqGapBox, goldenMgcGapBox;
        private TextBlock goldenPreviewText;

        private bool IsGoldenSelected() { return strategyBox != null && Convert.ToString(strategyBox.SelectedItem ?? string.Empty).StartsWith("GOLDEN SETUP", StringComparison.OrdinalIgnoreCase); }

        private UIElement BuildGoldenPanel()
        {
            var panel = Stack(); panel.Margin = new Thickness(0, 4, 0, 2);
            panel.Children.Add(Txt("GOLDEN SETUP • FIRST BH / FVG AFTER THE OPEN", Gold, 11, FontWeights.Bold));
            panel.Children.Add(Txt("The first bullish setup after the start time is the one trade of the day for that instrument: BH or a bullish FVG, whichever forms first. The push down before it is measured on every setup so the results show whether aggression really makes the difference.", Muted, 10, FontWeights.Normal));
            goldenMnqStartBox = Input("930"); goldenMgcStartBox = Input("800"); goldenLastEntryBox = Input("1555"); goldenCloseBox = Input("1555");
            goldenBhBox = new CheckBox { Content = "BH SETUPS", IsChecked = true, Foreground = Text, Margin = new Thickness(6) };
            goldenFvgBox = Select("RETEST + BREAK • price comes back into the gap, a green candle closes, the next candle breaks its high", "CANDLE 3 CLOSE • enter the moment the gap forms (no retest)", "50% TAP • a limit at the middle of the gap fills when price taps it • stop below candle 1's low", "OFF • BH only"); goldenFvgBox.SelectedIndex = 0;
            goldenSideBox = Select("BUY • bullish FVG / BH, break of a high (the original)", "SELL • bearish FVG / BH, break of a low (the same rules mirrored)", "BUY + SELL • both"); goldenSideBox.SelectedIndex = 0; goldenSideBox.SelectionChanged += delegate { InvalidateConfigurationApproval(); };
            goldenAggressionBox = Select("MEASURE + COMPARE (take every setup)", "REQUIRED • only after a push down", "OFF"); goldenAggressionBox.SelectedIndex = 0;
            goldenMnqDropBox = Input("30"); goldenMgcDropBox = Input("3");
            goldenMnqTargetBox = Input("100"); goldenMgcTargetBox = Input("10");
            goldenStopBox = Select("BELOW THE PATTERN'S LOW", "FIXED POINTS"); goldenStopBox.SelectedIndex = 0;
            goldenMnqStopBox = Input("50"); goldenMgcStopBox = Input("5"); goldenMnqBufferBox = Input("0"); goldenMgcBufferBox = Input("0"); goldenMnqMaxStopBox = Input("0"); goldenMgcMaxStopBox = Input("0");
            goldenMnqQtyBox = Input("5"); goldenMgcQtyBox = Input("10"); goldenTriesBox = Input("1");
            goldenMnqGapBox = Input("5"); goldenMgcGapBox = Input("1");
            goldenSkipBigStopBox = new CheckBox { Content = "SKIP A SETUP WHOSE STOP IS BIGGER THAN ITS TARGET", IsChecked = true, Foreground = Text, Margin = new Thickness(6) };
            goldenHoldBox = Select("HOLD UNTIL THE TARGET OR THE STOP (overnight, next days) • loads the full session", "CLOSE AT THE TIME BELOW (same day)"); goldenHoldBox.SelectedIndex = 1;   // same-day by default: prop accounts must be flat at the close
            goldenFirstBox = Select("STRICTLY THE FIRST SETUP • if a filter skips it, no trade that day", "TAKE THE NEXT SETUP when the first one is skipped"); goldenFirstBox.SelectedIndex = 0;
            goldenOpenGapBox = Select("YES • the gap may start with the last candle before the start (the opening candle makes the gap)", "NO • all three candles after the start"); goldenOpenGapBox.SelectedIndex = 0; goldenOpenGapBox.SelectionChanged += delegate { InvalidateConfigurationApproval(); };
            foreach (ComboBox box in new[] { goldenHoldBox, goldenFirstBox }) box.SelectionChanged += delegate { InvalidateConfigurationApproval(); };
            WatchConfigurationInput(goldenMnqGapBox); WatchConfigurationInput(goldenMgcGapBox);
            goldenSkipBigStopBox.Checked += delegate { InvalidateConfigurationApproval(); }; goldenSkipBigStopBox.Unchecked += delegate { InvalidateConfigurationApproval(); };
            foreach (TextBox box in new[] { goldenMnqStartBox, goldenMgcStartBox, goldenLastEntryBox, goldenCloseBox, goldenMnqDropBox, goldenMgcDropBox, goldenMnqTargetBox, goldenMgcTargetBox, goldenMnqStopBox, goldenMgcStopBox, goldenMnqBufferBox, goldenMgcBufferBox, goldenMnqMaxStopBox, goldenMgcMaxStopBox, goldenMnqQtyBox, goldenMgcQtyBox, goldenTriesBox }) { WatchConfigurationInput(box); box.TextChanged += delegate { UpdateGoldenPreview(); }; }
            foreach (ComboBox box in new[] { goldenFvgBox, goldenAggressionBox, goldenStopBox }) box.SelectionChanged += delegate { InvalidateConfigurationApproval(); UpdateGoldenPreview(); };
            goldenBhBox.Checked += delegate { InvalidateConfigurationApproval(); }; goldenBhBox.Unchecked += delegate { InvalidateConfigurationApproval(); };
            panel.Children.Add(Txt("WHEN", Cyan, 10, FontWeights.Bold));
            panel.Children.Add(Row("MNQ STARTS AT (HHMM ET)", goldenMnqStartBox)); panel.Children.Add(Row("MGC STARTS AT (HHMM ET)", goldenMgcStartBox));
            panel.Children.Add(Txt("Start 1800 or later = the evening open (it belongs to the next trading day, 18:00 → 17:00).", Muted, 9.5, FontWeights.Normal));
            panel.Children.Add(Row("NO NEW TRADE AFTER", goldenLastEntryBox));
            panel.Children.Add(Row("OPENING CANDLE GAP (FVG)", goldenOpenGapBox));
            panel.Children.Add(Row("AN OPEN TRADE", goldenHoldBox)); panel.Children.Add(Row("CLOSE AN OPEN TRADE AT", goldenCloseBox));
            panel.Children.Add(Row("WHICH SETUP OF THE DAY", goldenFirstBox));
            panel.Children.Add(Row("TRADES A DAY PER INSTRUMENT (1 = first setup only)", goldenTriesBox));
            panel.Children.Add(Txt("WHICH SETUPS", Cyan, 10, FontWeights.Bold));
            panel.Children.Add(Row("BH", goldenBhBox)); panel.Children.Add(Row("FVG (sells: the mirror)", goldenFvgBox));
            panel.Children.Add(Row("MNQ FVG GAP AT LEAST (POINTS)", goldenMnqGapBox)); panel.Children.Add(Row("MGC FVG GAP AT LEAST (POINTS)", goldenMgcGapBox));
            panel.Children.Add(Row("PUSH DOWN BEFORE THE SETUP", goldenAggressionBox));
            panel.Children.Add(Row("MNQ PUSH DOWN = AT LEAST (POINTS)", goldenMnqDropBox)); panel.Children.Add(Row("MGC PUSH DOWN = AT LEAST (POINTS)", goldenMgcDropBox));
            panel.Children.Add(Txt("TARGET, STOP, SIZE", Cyan, 10, FontWeights.Bold));
            panel.Children.Add(Row("MNQ TARGET (POINTS)", goldenMnqTargetBox)); panel.Children.Add(Row("MGC TARGET (POINTS)", goldenMgcTargetBox));
            panel.Children.Add(Row("STOP", goldenStopBox));
            panel.Children.Add(Row("MNQ FIXED STOP (POINTS)", goldenMnqStopBox)); panel.Children.Add(Row("MGC FIXED STOP (POINTS)", goldenMgcStopBox));
            panel.Children.Add(Row("MNQ EXTRA POINTS BELOW THE PATTERN", goldenMnqBufferBox)); panel.Children.Add(Row("MGC EXTRA POINTS BELOW THE PATTERN", goldenMgcBufferBox));
            panel.Children.Add(Row("MNQ SKIP IF THE STOP IS BIGGER THAN (0 = ANY)", goldenMnqMaxStopBox)); panel.Children.Add(Row("MGC SKIP IF THE STOP IS BIGGER THAN (0 = ANY)", goldenMgcMaxStopBox));
            panel.Children.Add(Row("RISK FILTER", goldenSkipBigStopBox));
            panel.Children.Add(Row("MNQ CONTRACTS", goldenMnqQtyBox)); panel.Children.Add(Row("MGC CONTRACTS", goldenMgcQtyBox));
            goldenPreviewText = Txt(string.Empty, Green, 10, FontWeights.Bold); panel.Children.Add(goldenPreviewText);
            UpdateGoldenPreview();
            goldenStrategyControls.Clear(); goldenStrategyControls.Add(panel);
            panel.Visibility = Visibility.Collapsed;
            return panel;
        }

        private void UpdateGoldenPreview()
        {
            if (goldenPreviewText == null) return;
            double mt = Number(goldenMnqTargetBox, 100), gt = Number(goldenMgcTargetBox, 10); int mq = Math.Max(1, Integer(goldenMnqQtyBox, 5)), gq = Math.Max(1, Integer(goldenMgcQtyBox, 10));
            goldenPreviewText.Text = "A WIN = MNQ " + N0(mt) + " pts × $2 × " + mq + " = " + Cash(mt * 2 * mq) + "  •  MGC " + N0(gt) + " pts × $10 × " + gq + " = " + Cash(gt * 10 * gq) + ((goldenStopBox != null && goldenStopBox.SelectedIndex == 1) ? "  •  A LOSS = MNQ " + Cash(-Number(goldenMnqStopBox, 50) * 2 * mq) + " / MGC " + Cash(-Number(goldenMgcStopBox, 5) * 10 * gq) : "  •  a loss depends on the pattern's low (shown on every trade)");
        }

        private bool ReadGoldenConfig()
        {
            int ms = Integer(goldenMnqStartBox, 930), gs = Integer(goldenMgcStartBox, 800), le = Integer(goldenLastEntryBox, 1555), cl = Integer(goldenCloseBox, 1555);
            if (!IsValidHhmm(ms) || !IsValidHhmm(gs) || !IsValidHhmm(le) || !IsValidHhmm(cl)) { UpdateUi("GOLDEN TIME ERROR • USE HHMM FROM 0000 TO 2359", Red); return false; }
            config.GoldenMnqStart = ms; config.GoldenMgcStart = gs; config.GoldenLastEntry = le; config.GoldenClose = cl;
            config.GoldenUseBh = goldenBhBox == null || goldenBhBox.IsChecked != false ? 1 : 0;
            config.GoldenFvgMode = goldenFvgBox == null ? "BREAK" : new[] { "BREAK", "CLOSE", "DIP50", "OFF" }[Math.Max(0, Math.Min(3, goldenFvgBox.SelectedIndex))];
            if (config.GoldenUseBh == 0 && config.GoldenFvgMode == "OFF") { UpdateUi("GOLDEN • choose BH, FVG or both", Red); return false; }
            config.GoldenAggression = goldenAggressionBox == null ? "TAG" : new[] { "TAG", "REQUIRED", "OFF" }[Math.Max(0, Math.Min(2, goldenAggressionBox.SelectedIndex))];
            config.GoldenMnqDropPoints = NumberAllowZero(goldenMnqDropBox, 30); config.GoldenMgcDropPoints = NumberAllowZero(goldenMgcDropBox, 3);
            config.GoldenMnqTargetPoints = Number(goldenMnqTargetBox, 100); config.GoldenMgcTargetPoints = Number(goldenMgcTargetBox, 10);
            config.GoldenStopMode = goldenStopBox != null && goldenStopBox.SelectedIndex == 1 ? "FIXED" : "PATTERN";
            config.GoldenMnqStopPoints = Number(goldenMnqStopBox, 50); config.GoldenMgcStopPoints = Number(goldenMgcStopBox, 5);
            config.GoldenMnqStopBuffer = NumberAllowZero(goldenMnqBufferBox, 0); config.GoldenMgcStopBuffer = NumberAllowZero(goldenMgcBufferBox, 0);
            config.GoldenMnqMaxStop = NumberAllowZero(goldenMnqMaxStopBox, 0); config.GoldenMgcMaxStop = NumberAllowZero(goldenMgcMaxStopBox, 0);
            config.GoldenMnqQuantity = Math.Max(1, Integer(goldenMnqQtyBox, 5)); config.GoldenMgcQuantity = Math.Max(1, Integer(goldenMgcQtyBox, 10));
            config.GoldenMaxTradesPerDay = Math.Max(1, Math.Min(5, Integer(goldenTriesBox, 1)));
            config.GoldenMnqMinGap = NumberAllowZero(goldenMnqGapBox, 5); config.GoldenMgcMinGap = NumberAllowZero(goldenMgcGapBox, 1);
            config.GoldenSkipStopOverTarget = goldenSkipBigStopBox == null || goldenSkipBigStopBox.IsChecked != false ? 1 : 0;
            config.GoldenHold = goldenHoldBox == null || goldenHoldBox.SelectedIndex != 1 ? 1 : 0;
            config.GoldenStrictFirst = goldenFirstBox == null || goldenFirstBox.SelectedIndex != 1 ? 1 : 0;
            config.GoldenFvgOpenCandle = goldenOpenGapBox != null && goldenOpenGapBox.SelectedIndex == 0 ? 1 : 0;
            // Load from the earliest start to 16:55 (or later close) — the same window as the FVG
            // default, so bars already saved by an FVG / BH test are reused without a new read.
            int first = Math.Min(config.Scope == "MGC" ? gs : ms, config.Scope == "MNQ" ? ms : gs);
            bool evening = (config.Scope != "MGC" && ms >= 1800) || (config.Scope != "MNQ" && gs >= 1800);
            // HOLD (trades carry overnight) or an evening start needs the whole trading day: 18:00 → 17:00.
            if (config.GoldenHold == 1 || evening) { config.SessionMode = "FULL_GLOBEX"; config.CustomStart = 1800; config.EndTime = 1655; }
            else { config.SessionMode = "CUSTOM"; config.CustomStart = Math.Min(800, first); config.EndTime = Math.Max(1655, cl); }
            return true;
        }
    }
}
